        NEW.invoice_id,
        v_user_key,
        NEW.organization_id,
        NEW.amount,
        NEW.payment_method,
        NEW.status
    )
    ON CONFLICT (source_payment_id) DO UPDATE SET
        payment_date_key = EXCLUDED.payment_date_key,
        due_date_key     = EXCLUDED.due_date_key,
        vendor_key       = EXCLUDED.vendor_key,
        amount           = EXCLUDED.amount,
