-- 011_fix_onboarding_rls.sql
-- This migration adds necessary INSERT policies for the onboarding process.
-- When a new user completes onboarding, they need to create an organization, 
-- a brand, and a location before their JWT metadata is updated.

-- 1. Allow authenticated users to create their own organization
DROP POLICY IF EXISTS "Users can create their own organization" ON public.organizations;
CREATE POLICY "Users can create their own organization"
ON public.organizations
FOR INSERT
TO authenticated
WITH CHECK (auth.uid() = owner_id);

-- 2. Allow organization owners to create brands (even if organization_id is not in their JWT yet)
DROP POLICY IF EXISTS "Owners can create brands for their organizations" ON public.brands;
CREATE POLICY "Owners can create brands for their organizations"
ON public.brands
FOR INSERT
TO authenticated
WITH CHECK (
    EXISTS (
        SELECT 1 FROM public.organizations
        WHERE organizations.id = organization_id
        AND organizations.owner_id = auth.uid()
    )
);

-- 3. Allow organization owners to create locations (even if organization_id is not in their JWT yet)
DROP POLICY IF EXISTS "Owners can create locations for their organizations" ON public.locations;
CREATE POLICY "Owners can create locations for their organizations"
ON public.locations
FOR INSERT
TO authenticated
WITH CHECK (
    EXISTS (
        SELECT 1 FROM public.organizations
        WHERE organizations.id = organization_id
        AND organizations.owner_id = auth.uid()
    )
);

-- 4. Ensure organization owners can see their own organizations (even if organization_id is not in their JWT yet)
-- This supplements the existing JWT-based SELECT policies.
DROP POLICY IF EXISTS "Owners can view their own organizations" ON public.organizations;
CREATE POLICY "Owners can view their own organizations"
ON public.organizations
FOR SELECT
TO authenticated
USING (auth.uid() = owner_id);

-- ==========================================================================
-- Source: 012_fix_role_constraint_and_utility_functions.sql
-- ==========================================================================

-- ============================================================
-- 012: Fix Role Constraint + Create Missing Utility Functions
-- ============================================================
-- Fixes:
--   [SYNC REPORT #1] Role constraint uses old names (manager/owner/admin)
--   [SYNC REPORT #2] Missing get_my_accessible_brand_ids(), get_my_accessible_location_ids(), can_invite_role()
-- ============================================================

BEGIN;

-- Bootstrap auth helpers before this migration creates functions that depend on
-- them. Later migrations harden and recreate these definitions.
CREATE OR REPLACE FUNCTION public.get_auth_role()
RETURNS TEXT AS $$
  SELECT COALESCE(auth.jwt() -> 'user_metadata' ->> 'role', 'ground_staff');
$$ LANGUAGE sql SECURITY DEFINER STABLE SET search_path = '';

CREATE OR REPLACE FUNCTION public.get_auth_org()
RETURNS UUID AS $$
  SELECT NULLIF(auth.jwt() -> 'user_metadata' ->> 'organization_id', '')::uuid;
$$ LANGUAGE sql SECURITY DEFINER STABLE SET search_path = '';

GRANT EXECUTE ON FUNCTION public.get_auth_role() TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_auth_org() TO anon, authenticated, service_role;

-- ────────────────────────────────────────────────────────────
-- STEP 1: Fix the profiles role constraint
-- The old constraint allowed: ground_staff, manager, owner, admin, platform_admin
-- The frontend now uses: ground_staff, location_manager, branch_manager, org_owner, platform_admin
-- ────────────────────────────────────────────────────────────

ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_role_check;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_role_check
  CHECK (role IN (
    'ground_staff',
    'location_manager',
    'branch_manager',
    'org_owner',
    'platform_admin'
  ));

-- Also ensure all necessary profile columns exist for the RPC functions
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS full_name TEXT;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS status TEXT DEFAULT 'active';
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS department TEXT;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS permissions JSONB DEFAULT '{}'::jsonb;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS signing_privileges JSONB DEFAULT '{}'::jsonb;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS access_level TEXT DEFAULT 'location'
  CHECK (access_level IN ('platform', 'organization', 'brand', 'location'));
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS payment_verified BOOLEAN DEFAULT false;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT now();
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;


-- ────────────────────────────────────────────────────────────
-- STEP 2: Create can_invite_role(target_role TEXT)
-- Returns TRUE if the caller's role is strictly above the target role.
-- Used in the invitations INSERT policy to prevent privilege escalation.
-- ────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.can_invite_role(target_role TEXT)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  caller_level INT;
  target_level INT;
BEGIN
  caller_level := CASE public.get_auth_role()
    WHEN 'platform_admin'    THEN 4
    WHEN 'org_owner'         THEN 3
    WHEN 'branch_manager'    THEN 2
    WHEN 'location_manager'  THEN 1
    WHEN 'ground_staff'      THEN 0
    ELSE 0
  END;

  target_level := CASE target_role
    WHEN 'platform_admin'    THEN 4
    WHEN 'org_owner'         THEN 3
    WHEN 'branch_manager'    THEN 2
    WHEN 'location_manager'  THEN 1
    WHEN 'ground_staff'      THEN 0
    ELSE 0
  END;

  -- Can only invite roles STRICTLY below your own level
  RETURN caller_level > target_level;
END;
$$;

COMMENT ON FUNCTION public.can_invite_role(TEXT) IS
  'Returns TRUE if the authenticated user''s role is above the given target_role. Used in RLS policies to prevent privilege escalation on invitations.';


-- ────────────────────────────────────────────────────────────
-- STEP 3: Create get_my_accessible_brand_ids()
-- Returns the set of brand UUIDs the caller is allowed to see.
--   platform_admin / org_owner → all brands in their org
--   branch_manager             → only their assigned brand
--   everyone else              → empty set
-- ────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.get_my_accessible_brand_ids()
RETURNS SETOF UUID
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
  SELECT b.id
  FROM public.brands b
  WHERE b.organization_id = public.get_auth_org()
    AND (
      -- org_owner and platform_admin see all brands in the org
      public.get_auth_role() IN ('platform_admin', 'org_owner')
      OR (
        -- branch_manager sees only their assigned brand
        public.get_auth_role() = 'branch_manager'
        AND b.id = (SELECT p.brand_id FROM public.profiles p WHERE p.id = auth.uid())
      )
    );
$$;

COMMENT ON FUNCTION public.get_my_accessible_brand_ids() IS
  'Returns brand IDs the caller can access. org_owner/platform_admin get all org brands; branch_manager gets their assigned brand.';


-- ────────────────────────────────────────────────────────────
-- STEP 4: Create get_my_accessible_location_ids()
-- Returns the set of location UUIDs the caller is allowed to see.
--   platform_admin / org_owner → all locations in their org
--   branch_manager             → all locations under their brand(s)
--   location_manager           → only their assigned location
--   everyone else              → empty set
-- ────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.get_my_accessible_location_ids()
RETURNS SETOF UUID
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
  SELECT l.id
  FROM public.locations l
  WHERE l.organization_id = public.get_auth_org()
    AND (
      -- org_owner and platform_admin see all locations in the org
      public.get_auth_role() IN ('platform_admin', 'org_owner')
      OR (
        -- branch_manager sees locations under their accessible brands
        public.get_auth_role() = 'branch_manager'
        AND l.brand_id IN (SELECT public.get_my_accessible_brand_ids())
      )
      OR (
        -- location_manager sees only their assigned location
        public.get_auth_role() = 'location_manager'
        AND l.id = (SELECT p.location_id FROM public.profiles p WHERE p.id = auth.uid())
      )
    );
$$;

COMMENT ON FUNCTION public.get_my_accessible_location_ids() IS
  'Returns location IDs the caller can access. Cascades from org → brand → location based on role.';


COMMIT;

-- ==========================================================================
-- Source: 013_version_control_rpc_functions.sql
-- ==========================================================================

-- ============================================================
-- 013: Version-Control Critical RPC Functions
-- ============================================================
-- Fixes:
--   [SYNC REPORT #4] setup_organization_full, accept_invitation,
--   admin_update_user_role are called by the frontend but have
--   NO SQL definition tracked in the repository.
--
-- NOTE: We must DROP existing functions first because old versions
--       may have different signatures (e.g. TEXT vs UUID), and
--       CREATE OR REPLACE cannot change parameter types.
-- ============================================================

BEGIN;

-- ────────────────────────────────────────────────────────────
-- STEP 0: Drop ALL existing overloads of these functions
--
-- CASCADE ensures dependent objects (triggers, policies) that
-- reference these are also dropped. We recreate them below.
-- ────────────────────────────────────────────────────────────

DROP FUNCTION IF EXISTS public.setup_organization_full(UUID, TEXT, TEXT, TEXT, TEXT, TEXT) CASCADE;
DROP FUNCTION IF EXISTS public.setup_organization_full(UUID, TEXT, TEXT, TEXT, TEXT) CASCADE;
-- Catch any other signatures
DO $$ BEGIN
  EXECUTE (
    SELECT string_agg(
      format('DROP FUNCTION IF EXISTS %s CASCADE;', oid::regprocedure),
      E'\n'
    )
    FROM pg_proc
    WHERE proname = 'setup_organization_full'
      AND pronamespace = 'public'::regnamespace
  );
EXCEPTION WHEN OTHERS THEN NULL;
END $$;

DROP FUNCTION IF EXISTS public.accept_invitation(UUID) CASCADE;
DROP FUNCTION IF EXISTS public.accept_invitation(TEXT) CASCADE;
-- Catch any other signatures
DO $$ BEGIN
  EXECUTE (
    SELECT string_agg(
      format('DROP FUNCTION IF EXISTS %s CASCADE;', oid::regprocedure),
      E'\n'
    )
    FROM pg_proc
    WHERE proname = 'accept_invitation'
      AND pronamespace = 'public'::regnamespace
  );
EXCEPTION WHEN OTHERS THEN NULL;
END $$;

DROP FUNCTION IF EXISTS public.admin_update_user_role(UUID, TEXT, TEXT, TEXT, TEXT, JSONB, UUID, UUID, TEXT) CASCADE;
DROP FUNCTION IF EXISTS public.admin_update_user_role(UUID, TEXT) CASCADE;
-- Catch any other signatures
DO $$ BEGIN
  EXECUTE (
    SELECT string_agg(
      format('DROP FUNCTION IF EXISTS %s CASCADE;', oid::regprocedure),
      E'\n'
    )
    FROM pg_proc
    WHERE proname = 'admin_update_user_role'
      AND pronamespace = 'public'::regnamespace
  );
EXCEPTION WHEN OTHERS THEN NULL;
END $$;

-- Also drop complete_onboarding if it exists (legacy name)
DROP FUNCTION IF EXISTS public.complete_onboarding() CASCADE;
DROP FUNCTION IF EXISTS public.complete_onboarding(UUID) CASCADE;
DROP FUNCTION IF EXISTS public.complete_onboarding(UUID, TEXT) CASCADE;


-- ────────────────────────────────────────────────────────────
-- RPC 1: setup_organization_full
--
-- Called by: apiClient.js → api.onboarding.setupOrgAndFirstLocation()
-- Purpose:  Atomic onboarding — creates org, brand, location, and
--           assigns the user as org_owner in a single transaction.
-- ────────────────────────────────────────────────────────────

CREATE FUNCTION public.setup_organization_full(
  p_user_id UUID,
  p_org_name TEXT,
  p_org_slug TEXT,
  p_brand_name TEXT,
  p_location_name TEXT,
  p_location_address TEXT DEFAULT ''
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
BEGIN
  -- Verify the caller IS the user being onboarded (or a platform admin)
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  -- 1. Create the organization
  INSERT INTO public.organizations (name, slug, owner_id)
  VALUES (p_org_name, p_org_slug, p_user_id)
  RETURNING id INTO v_org_id;

  -- 2. Create the first brand
  INSERT INTO public.brands (organization_id, name)
  VALUES (v_org_id, p_brand_name)
  RETURNING id INTO v_brand_id;

  -- 3. Create the first location
  INSERT INTO public.locations (organization_id, brand_id, name, address)
  VALUES (v_org_id, v_brand_id, p_location_name, p_location_address)
  RETURNING id INTO v_location_id;

  -- 4. Assign user as org_owner with full hierarchy
  UPDATE public.profiles
  SET organization_id = v_org_id,
      brand_id        = v_brand_id,
      location_id     = v_location_id,
      role            = 'org_owner',
      access_level    = 'organization',
      updated_at      = now()
  WHERE id = p_user_id;

  -- 5. Sync auth JWT metadata so RLS policies work immediately
  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'org_owner',
    'organization_id', v_org_id::text
  )
  WHERE id = p_user_id;

  RETURN jsonb_build_object(
    'org_id',      v_org_id,
    'brand_id',    v_brand_id,
    'location_id', v_location_id
  );
END;
$$;

COMMENT ON FUNCTION public.setup_organization_full IS
  'Atomic onboarding: creates org → brand → location → assigns user as org_owner. Called from OnboardingPage.';


-- ────────────────────────────────────────────────────────────
-- RPC 2: accept_invitation
--
-- Called by: apiClient.js → api.onboarding.acceptInvitation()
-- Purpose:  Accepts a pending invitation, assigns the user their
--           invited role/org/brand/location, and syncs JWT metadata.
--
-- NOTE: Uses TEXT for p_token because the invitation token may be
--       stored as TEXT or UUID in the DB, and the frontend passes
--       it as a string from URL params.
-- ────────────────────────────────────────────────────────────

CREATE FUNCTION public.accept_invitation(p_token TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invite RECORD;
  v_user_id UUID;
  v_user_email TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Get the caller's email
  SELECT email INTO v_user_email
  FROM auth.users WHERE id = v_user_id;

  -- Find the matching pending invitation
  -- Cast p_token to match the column type (works for both TEXT and UUID columns)
  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND LOWER(email) = LOWER(v_user_email);

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  -- Update user's profile with the invitation assignment
  UPDATE public.profiles
  SET role            = v_invite.role,
      organization_id = v_invite.organization_id,
      brand_id        = COALESCE(v_invite.brand_id, brand_id),
      location_id     = COALESCE(v_invite.location_id, location_id),
      updated_at      = now()
  WHERE id = v_user_id;

  -- Mark invitation as accepted
  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id
  WHERE id = v_invite.id;

  -- Sync auth JWT metadata
  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', v_invite.role,
    'organization_id', v_invite.organization_id::text
  )
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success',         true,
    'role',            v_invite.role,
    'organization_id', v_invite.organization_id
  );
END;
$$;

COMMENT ON FUNCTION public.accept_invitation IS
  'Accepts a pending invitation by token. Assigns the user their invited role/org/brand/location and syncs JWT metadata.';


-- ────────────────────────────────────────────────────────────
-- RPC 3: admin_update_user_role
--
-- Called by: apiClient.js → api.admin.updateUserRole()
-- Purpose:  Securely update a user's role and assignment fields.
--           Enforces hierarchy: callers can only assign roles below
--           their own level (preventing privilege escalation).
-- ────────────────────────────────────────────────────────────

CREATE FUNCTION public.admin_update_user_role(
  target_user_id    UUID,
  new_role          TEXT,
  new_status        TEXT         DEFAULT NULL,
  new_department    TEXT         DEFAULT NULL,
  new_location      TEXT         DEFAULT NULL,
  new_permissions   JSONB        DEFAULT NULL,
  new_brand_id      UUID         DEFAULT NULL,
  new_location_id   UUID         DEFAULT NULL,
  new_access_level  TEXT         DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  caller_role TEXT;
  caller_org  UUID;
  target_org  UUID;
BEGIN
  caller_role := public.get_auth_role();
  caller_org  := public.get_auth_org();

  -- Permission gate: only org_owner+ can modify user roles
  IF caller_role NOT IN ('org_owner', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: only org_owner or platform_admin can update user roles';
  END IF;

  -- Get the target user's organization
  SELECT organization_id INTO target_org
  FROM public.profiles
  WHERE id = target_user_id;

  -- Org owners can only manage users within their own organization
  IF caller_role = 'org_owner' AND target_org IS DISTINCT FROM caller_org THEN
    RAISE EXCEPTION 'Cannot modify users outside your organization';
  END IF;

  -- Prevent privilege escalation (platform_admin is exempt)
  IF caller_role != 'platform_admin' AND new_role IS NOT NULL THEN
    IF NOT public.can_invite_role(new_role) THEN
      RAISE EXCEPTION 'Cannot assign a role equal to or above your own';
    END IF;
  END IF;

  -- Prevent self-demotion for org_owners
  IF target_user_id = auth.uid() AND caller_role = 'org_owner' AND new_role != 'org_owner' THEN
    RAISE EXCEPTION 'Cannot change your own role. Transfer ownership first.';
  END IF;

  -- Apply updates (COALESCE preserves existing values when NULL is passed)
  UPDATE public.profiles
  SET role         = COALESCE(new_role, role),
      status       = COALESCE(new_status, status),
      department   = COALESCE(new_department, department),
      permissions  = COALESCE(new_permissions, permissions),
      brand_id     = COALESCE(new_brand_id, brand_id),
      location_id  = COALESCE(new_location_id, location_id),
      access_level = COALESCE(new_access_level, access_level),
      updated_at   = now()
  WHERE id = target_user_id;

  -- Sync auth JWT metadata with the new role
  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', COALESCE(new_role, (SELECT role FROM public.profiles WHERE id = target_user_id))
  )
  WHERE id = target_user_id;

  RETURN jsonb_build_object('success', true);
END;
$$;

COMMENT ON FUNCTION public.admin_update_user_role IS
  'Securely updates a user''s role and assignment. Enforces org-scoping and prevents privilege escalation.';


COMMIT;

-- ==========================================================================
-- Source: 014_security_hardening_and_rls_optimization.sql
-- ==========================================================================

-- ============================================================
-- 014: Security Hardening & RLS Optimization
-- ============================================================
-- Implementation Plan Phase 1: Secure SECURITY DEFINER functions
-- Implementation Plan Phase 2: Optimize RLS InitPlans
-- ============================================================

BEGIN;

-- ╔══════════════════════════════════════════════════════════╗
-- ║  PHASE 1: Securing SECURITY DEFINER Functions           ║
-- ╚══════════════════════════════════════════════════════════╝

-- ────────────────────────────────────────────────────────────
-- 1A: Revoke public execution rights from sensitive functions
--
-- By default, Postgres grants EXECUTE to PUBLIC on new functions.
-- These SECURITY DEFINER functions run with the OWNER's elevated
-- privileges, so they must NOT be callable by anon or public.
-- ────────────────────────────────────────────────────────────

-- Core JWT helpers (used by RLS policies — must stay callable by authenticated)
REVOKE EXECUTE ON FUNCTION public.get_auth_role()              FROM public, anon;
GRANT  EXECUTE ON FUNCTION public.get_auth_role()              TO authenticated, service_role;

REVOKE EXECUTE ON FUNCTION public.get_auth_org()               FROM public, anon;
GRANT  EXECUTE ON FUNCTION public.get_auth_org()               TO authenticated, service_role;

-- Invitation hierarchy check
REVOKE EXECUTE ON FUNCTION public.can_invite_role(TEXT)         FROM public, anon;
GRANT  EXECUTE ON FUNCTION public.can_invite_role(TEXT)         TO authenticated, service_role;

-- Accessor functions (used in RLS policies)
REVOKE EXECUTE ON FUNCTION public.get_my_accessible_brand_ids()    FROM public, anon;
GRANT  EXECUTE ON FUNCTION public.get_my_accessible_brand_ids()    TO authenticated, service_role;

REVOKE EXECUTE ON FUNCTION public.get_my_accessible_location_ids() FROM public, anon;
GRANT  EXECUTE ON FUNCTION public.get_my_accessible_location_ids() TO authenticated, service_role;

-- Onboarding RPC (only authenticated users should call this)
REVOKE EXECUTE ON FUNCTION public.setup_organization_full(UUID, TEXT, TEXT, TEXT, TEXT, TEXT) FROM public, anon;
GRANT  EXECUTE ON FUNCTION public.setup_organization_full(UUID, TEXT, TEXT, TEXT, TEXT, TEXT) TO authenticated, service_role;

-- Invitation acceptance (only authenticated users)
REVOKE EXECUTE ON FUNCTION public.accept_invitation(TEXT)      FROM public, anon;
GRANT  EXECUTE ON FUNCTION public.accept_invitation(TEXT)      TO authenticated, service_role;

-- Admin role update (only authenticated users — function internally enforces org_owner+)
REVOKE EXECUTE ON FUNCTION public.admin_update_user_role(UUID, TEXT, TEXT, TEXT, TEXT, JSONB, UUID, UUID, TEXT) FROM public, anon;
GRANT  EXECUTE ON FUNCTION public.admin_update_user_role(UUID, TEXT, TEXT, TEXT, TEXT, JSONB, UUID, UUID, TEXT) TO authenticated, service_role;


-- ────────────────────────────────────────────────────────────
-- 1B: Secure function search paths
--
-- Functions without SET search_path are vulnerable to search_path
-- injection. Adding SET search_path = '' forces fully-qualified
-- table references and prevents object hijacking.
-- ────────────────────────────────────────────────────────────

-- Recreate get_auth_role with secure search_path
CREATE OR REPLACE FUNCTION public.get_auth_role()
RETURNS TEXT AS $$
  SELECT COALESCE(auth.jwt() -> 'user_metadata' ->> 'role', 'ground_staff');
$$ LANGUAGE sql SECURITY DEFINER STABLE SET search_path = '';

-- Recreate get_auth_org with secure search_path
CREATE OR REPLACE FUNCTION public.get_auth_org()
RETURNS UUID AS $$
  SELECT (auth.jwt() -> 'user_metadata' ->> 'organization_id')::uuid;
$$ LANGUAGE sql SECURITY DEFINER STABLE SET search_path = '';

-- Fix set_updated_at trigger function (if it exists)
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'set_updated_at') THEN
    EXECUTE $fn$
      CREATE OR REPLACE FUNCTION public.set_updated_at()
      RETURNS TRIGGER AS $t$
      BEGIN
        NEW.updated_at = now();
        RETURN NEW;
      END;
      $t$ LANGUAGE plpgsql SECURITY INVOKER SET search_path = '';
    $fn$;
  END IF;
END $$;

-- Fix set_updated_at_metadata trigger function (if it exists)
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'set_updated_at_metadata') THEN
    EXECUTE $fn$
      CREATE OR REPLACE FUNCTION public.set_updated_at_metadata()
      RETURNS TRIGGER AS $t$
      BEGIN
        NEW.updated_at = now();
        RETURN NEW;
      END;
      $t$ LANGUAGE plpgsql SECURITY INVOKER SET search_path = '';
    $fn$;
  END IF;
END $$;


-- ────────────────────────────────────────────────────────────
-- 1C: Secure the health_monitor view
--
-- The current view uses SECURITY DEFINER semantics and exposes
-- aggregate counts to any authenticated user. Replace with
-- SECURITY INVOKER so it respects the caller's RLS context.
-- ────────────────────────────────────────────────────────────

DROP VIEW IF EXISTS public.health_monitor;
CREATE VIEW public.health_monitor
WITH (security_invoker = true) AS
SELECT
  (SELECT count(*) FROM public.organizations)  AS total_orgs,
  (SELECT count(*) FROM public.profiles)       AS total_users,
  (SELECT count(*) FROM public.invoices)       AS total_invoices,
  public.get_auth_role()                       AS active_role,
  public.get_auth_org()                        AS active_org_id;

-- Only platform admins and authenticated users should see this
GRANT SELECT ON public.health_monitor TO authenticated;
REVOKE SELECT ON public.health_monitor FROM anon;

-- Also secure the system_health_check view if it exists
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_views WHERE viewname = 'system_health_check' AND schemaname = 'public') THEN
    REVOKE SELECT ON public.system_health_check FROM anon;
  END IF;
END $$;


-- ╔══════════════════════════════════════════════════════════╗
-- ║  PHASE 2: Optimize RLS Policies (InitPlan Warnings)     ║
-- ╚══════════════════════════════════════════════════════════╝
--
-- Problem: Policies using auth.uid() directly force Postgres to
--          evaluate the function for EVERY ROW (InitPlan warning).
-- Fix:     Wrap in (SELECT auth.uid()) to cache the value once
--          per query execution.
-- ────────────────────────────────────────────────────────────

-- 2A: profiles_self_select — auth.uid() → (select auth.uid())
DROP POLICY IF EXISTS "profiles_self_select" ON public.profiles;
CREATE POLICY "profiles_self_select"
  ON public.profiles FOR SELECT
  USING (id = (SELECT auth.uid()));

-- 2B: profiles_self_update — auth.uid() → (select auth.uid())
DROP POLICY IF EXISTS "profiles_self_update" ON public.profiles;
CREATE POLICY "profiles_self_update"
  ON public.profiles FOR UPDATE
  USING (id = (SELECT auth.uid()))
  WITH CHECK (id = (SELECT auth.uid()));

-- 2C: profiles_org_owner_delete — auth.uid() → (select auth.uid())
DROP POLICY IF EXISTS "profiles_org_owner_delete" ON public.profiles;
CREATE POLICY "profiles_org_owner_delete"
  ON public.profiles FOR DELETE
  USING (
    (SELECT public.get_auth_role()) = 'org_owner'
    AND organization_id = (SELECT public.get_auth_org())
    AND id != (SELECT auth.uid())  -- cannot delete self
  );

-- 2D: invitations_cancel_own — auth.uid() → (select auth.uid())
DROP POLICY IF EXISTS "invitations_cancel_own" ON public.invitations;
CREATE POLICY "invitations_cancel_own"
  ON public.invitations FOR DELETE
  USING (
    organization_id = (SELECT public.get_auth_org())
    AND (
      invited_by = (SELECT auth.uid())
      OR (SELECT public.get_auth_role()) = 'org_owner'
    )
  );

-- 2E: Also fix the legacy Profile_Self_Access if it still exists
DROP POLICY IF EXISTS "Profile_Self_Access" ON public.profiles;
DROP POLICY IF EXISTS "Profile_Org_Visibility" ON public.profiles;


COMMIT;

-- ==========================================================================
-- Source: 015_create_error_logs_and_audit_hardening.sql
-- ==========================================================================

-- ============================================================
-- 015: Create error_logs Table & Misc Hardening
-- ============================================================
-- Fixes:
--   [SYNC REPORT #3] errorMonitor.js writes to error_logs but
--                     no migration creates the table.
--   [AUDIT]           Adds RLS to error_logs and audit_log INSERT policy.
-- ============================================================

BEGIN;

-- ────────────────────────────────────────────────────────────
-- STEP 1: Create the error_logs table
-- ────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.error_logs (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  message         TEXT NOT NULL,
  stack           TEXT,
  component_stack TEXT,
  route           TEXT,
  user_id         UUID REFERENCES auth.users(id),
  severity        TEXT DEFAULT 'error'
                    CHECK (severity IN ('info', 'warning', 'error', 'fatal')),
  metadata        JSONB,
  created_at      TIMESTAMPTZ DEFAULT now()
);

-- Enable RLS
ALTER TABLE public.error_logs ENABLE ROW LEVEL SECURITY;

-- Authenticated users can INSERT error logs (the frontend logger)
CREATE POLICY "error_logs_authenticated_insert"
  ON public.error_logs FOR INSERT
  TO authenticated
  WITH CHECK (true);

-- Only platform admins can READ error logs
CREATE POLICY "error_logs_platform_admin_select"
  ON public.error_logs FOR SELECT
  USING ((SELECT public.get_auth_role()) = 'platform_admin');

-- Platform admins can manage (delete old logs, etc.)
CREATE POLICY "error_logs_platform_admin_manage"
  ON public.error_logs FOR DELETE
  USING ((SELECT public.get_auth_role()) = 'platform_admin');

-- Create index for efficient querying
CREATE INDEX IF NOT EXISTS idx_error_logs_created_at
  ON public.error_logs (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_error_logs_severity
  ON public.error_logs (severity);


-- ────────────────────────────────────────────────────────────
-- STEP 2: Ensure audit_logs has an INSERT policy
--
-- The existing audit_logs table only has a SELECT policy.
-- The frontend audit.js needs to INSERT rows.
-- ────────────────────────────────────────────────────────────

-- Allow authenticated users to INSERT audit entries
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'audit_logs'
      AND policyname = 'audit_logs_authenticated_insert'
  ) THEN
    CREATE POLICY "audit_logs_authenticated_insert"
      ON public.audit_logs FOR INSERT
      TO authenticated
      WITH CHECK (true);
  END IF;
END $$;

-- Platform admin full access to audit logs
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'audit_logs'
      AND policyname = 'audit_logs_platform_admin_full'
  ) THEN
    CREATE POLICY "audit_logs_platform_admin_full"
      ON public.audit_logs FOR ALL
      USING ((SELECT public.get_auth_role()) = 'platform_admin');
  END IF;
END $$;

-- Add missing columns to audit_logs that audit.js expects
ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS entity_type TEXT;
ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS entity_id TEXT;
ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS module TEXT;
ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS org_id UUID;
ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS field_changed TEXT;
ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS old_value TEXT;
ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS new_value TEXT;
ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS user_email TEXT;
ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS details TEXT;

-- Index for org-scoped queries
CREATE INDEX IF NOT EXISTS idx_audit_logs_org_id
  ON public.audit_logs (org_id);

CREATE INDEX IF NOT EXISTS idx_audit_logs_module
  ON public.audit_logs (module);


COMMIT;

