-- ==========================================================================
-- Source: 017_policy_consolidation_and_public_forms.sql
-- ==========================================================================

-- ============================================================
-- 017: Policy Consolidation & Form Hardening
-- ============================================================
-- Fixes:
--   [SECURITY] Multiple permissive policies from the initial schema
--   were overlapping with the strict Tenant_Isolation policies, 
--   effectively bypassing row-level security.
--   [SECURITY] Public insert policies on business tables are removed.
-- ============================================================

BEGIN;

-- ────────────────────────────────────────────────────────────
-- 1: Drop Overlapping Permissive Policies
-- ────────────────────────────────────────────────────────────
-- These policies used `USING (true)` or `WITH CHECK (true)` and
-- broke the multi-tenant isolation model.

-- Profiles
DROP POLICY IF EXISTS "Users can view all profiles" ON public.profiles;
DROP POLICY IF EXISTS "Users can update own profile" ON public.profiles;
DROP POLICY IF EXISTS "Owner/Admin can update any profile" ON public.profiles;
DROP POLICY IF EXISTS "Owner/Admin can manage profiles" ON public.profiles;

-- Vendors
DROP POLICY IF EXISTS "All users can view vendors" ON public.vendors;
DROP POLICY IF EXISTS "Manager+ can manage vendors" ON public.vendors;
DROP POLICY IF EXISTS "Manager+ can update vendors" ON public.vendors;
DROP POLICY IF EXISTS "Admin can delete vendors" ON public.vendors;

-- Products
DROP POLICY IF EXISTS "All users can view products" ON public.products;
DROP POLICY IF EXISTS "All users can create products" ON public.products;
DROP POLICY IF EXISTS "Manager+ can update products" ON public.products;
DROP POLICY IF EXISTS "Admin can delete products" ON public.products;

-- Invoices
DROP POLICY IF EXISTS "All users can view invoices" ON public.invoices;
DROP POLICY IF EXISTS "All users can upload invoices" ON public.invoices;
DROP POLICY IF EXISTS "Manager+ can update invoices" ON public.invoices;
DROP POLICY IF EXISTS "Admin can delete invoices" ON public.invoices;

-- Payments
DROP POLICY IF EXISTS "All users can view payments" ON public.payments;
DROP POLICY IF EXISTS "Manager+ can manage payments" ON public.payments;
DROP POLICY IF EXISTS "Manager+ can update payments" ON public.payments;
DROP POLICY IF EXISTS "Admin can delete payments" ON public.payments;

-- Inventory
DROP POLICY IF EXISTS "All users can view inventory" ON public.inventory;
DROP POLICY IF EXISTS "All users can create inventory" ON public.inventory;
DROP POLICY IF EXISTS "Manager+ can update inventory" ON public.inventory;
DROP POLICY IF EXISTS "Admin can delete inventory" ON public.inventory;

-- Wastage Logs
DROP POLICY IF EXISTS "All users can view wastage logs" ON public.wastage_logs;
DROP POLICY IF EXISTS "All users can log waste" ON public.wastage_logs;
DROP POLICY IF EXISTS "Admin can delete wastage logs" ON public.wastage_logs;

-- Recipes
DROP POLICY IF EXISTS "All users can view recipes" ON public.recipes;
DROP POLICY IF EXISTS "Manager+ can manage recipes" ON public.recipes;
DROP POLICY IF EXISTS "Manager+ can update recipes" ON public.recipes;
DROP POLICY IF EXISTS "Admin can delete recipes" ON public.recipes;

-- Auto Orders
DROP POLICY IF EXISTS "All users can view auto orders" ON public.auto_orders;
DROP POLICY IF EXISTS "Manager+ can manage auto orders" ON public.auto_orders;
DROP POLICY IF EXISTS "Manager+ can update auto orders" ON public.auto_orders;
DROP POLICY IF EXISTS "Admin can delete auto orders" ON public.auto_orders;


-- ────────────────────────────────────────────────────────────
-- 2: Hardening the Access/Demo/Contact Requests
-- ────────────────────────────────────────────────────────────
-- If these tables exist in the marketing site schemas, we drop the
-- Anon_Insert policies to force the use of Edge Functions with
-- rate-limiting and CAPTCHA validation.
DO $$
BEGIN
    IF EXISTS (SELECT FROM pg_tables WHERE schemaname = 'public' AND tablename = 'access_requests') THEN
        EXECUTE 'DROP POLICY IF EXISTS "Anon_Insert_Access_Requests" ON public.access_requests';
    END IF;
    IF EXISTS (SELECT FROM pg_tables WHERE schemaname = 'public' AND tablename = 'contact_requests') THEN
        EXECUTE 'DROP POLICY IF EXISTS "Anon_Insert_Contact_Requests" ON public.contact_requests';
    END IF;
    IF EXISTS (SELECT FROM pg_tables WHERE schemaname = 'public' AND tablename = 'demo_requests') THEN
        EXECUTE 'DROP POLICY IF EXISTS "Anon_Insert_Demo_Requests" ON public.demo_requests';
    END IF;
END $$;

COMMIT;

-- ==========================================================================
-- Source: 018_fix_anon_invitation_read.sql
-- ==========================================================================

-- ============================================================
-- 018: Fix Anonymous Invitation Read
-- ============================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.get_invite_details(invite_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = ''
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', id,
    'email', email,
    'role', role,
    'organization_id', organization_id,
    'brand_id', brand_id,
    'location_id', location_id,
    'token', token
  ) INTO v_result
  FROM public.invitations
  WHERE token = invite_token AND accepted_at IS NULL;
  
  RETURN v_result;
END;
$function$;

GRANT EXECUTE ON FUNCTION public.get_invite_details(text) TO anon, authenticated;

COMMIT;

-- ==========================================================================
-- Source: 019_fix_accept_invitation_role_mapping.sql
-- ==========================================================================

-- ============================================================
-- 019: Fix accept_invitation Role Mapping and Profile Constraints
-- ============================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.accept_invitation(p_token TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invite RECORD;
  v_user_id UUID;
  v_user_email TEXT;
  v_mapped_role TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Get the caller's email
  SELECT email INTO v_user_email
  FROM auth.users WHERE id = v_user_id;

  -- Find the matching pending invitation
  -- Cast p_token to match the column type (works for both TEXT and UUID columns)
  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND LOWER(email) = LOWER(v_user_email);

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  -- Map old role names to the new role names to respect profiles_role_check constraints
  v_mapped_role := CASE v_invite.role
    WHEN 'owner'   THEN 'org_owner'
    WHEN 'admin'   THEN 'platform_admin'
    WHEN 'manager' THEN 'branch_manager'
    ELSE v_invite.role
  END;

  -- Update user's profile with the invitation assignment
  UPDATE public.profiles
  SET role            = v_mapped_role,
      organization_id = v_invite.organization_id,
      brand_id        = COALESCE(v_invite.brand_id, brand_id),
      location_id     = COALESCE(v_invite.location_id, location_id),
      updated_at      = now()
  WHERE id = v_user_id;

  -- Mark invitation as accepted
  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id
  WHERE id = v_invite.id;

  -- Sync auth JWT metadata
  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', v_mapped_role,
    'organization_id', v_invite.organization_id::text
  )
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success',         true,
    'role',            v_mapped_role,
    'organization_id', v_invite.organization_id
  );
END;
$$;

COMMENT ON FUNCTION public.accept_invitation IS
  'Accepts a pending invitation by token. Safely maps old role names to new role names, assigns the user their invited role/org/brand/location, and syncs JWT metadata.';

COMMIT;

-- ==========================================================================
-- Source: 020_restore_public_insert_policies.sql
-- ==========================================================================

-- ============================================================
-- 020: Restore Public INSERT Policies for Marketing Forms
-- ============================================================
-- Fixes:
--   [SECURITY/UX] RLS insertion violations when submitting 
--   "Request Demo", "Request Access", or "Contact Us" forms
--   from the public marketing landing page.
-- ============================================================

BEGIN;

DO $guard$
BEGIN
    -- Drop/create only when optional public form tables exist.
    IF to_regclass('public.demo_requests') IS NOT NULL THEN
        DROP POLICY IF EXISTS "Anon_Insert_Demo_Requests" ON public.demo_requests;
        CREATE POLICY "Anon_Insert_Demo_Requests" ON public.demo_requests
        FOR INSERT WITH CHECK (true);
    END IF;

    IF to_regclass('public.access_requests') IS NOT NULL THEN
        DROP POLICY IF EXISTS "Anon_Insert_Access_Requests" ON public.access_requests;
        CREATE POLICY "Anon_Insert_Access_Requests" ON public.access_requests
        FOR INSERT WITH CHECK (true);
    END IF;

    IF to_regclass('public.contact_requests') IS NOT NULL THEN
        DROP POLICY IF EXISTS "Anon_Insert_Contact_Requests" ON public.contact_requests;
        CREATE POLICY "Anon_Insert_Contact_Requests" ON public.contact_requests
        FOR INSERT WITH CHECK (true);
    END IF;
END $guard$;

COMMIT;

-- ==========================================================================
-- Source: 021_add_phone_and_check_email_exists.sql
-- ==========================================================================

-- ============================================================
-- 021: Add Phone to Profiles & Create Check Email RPC
-- ============================================================
-- Adds support for users editing their phone number on Profile
-- and enables check_email_exists function for Forgot Password.
-- ============================================================

BEGIN;

-- Add phone column if not exists
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS phone TEXT;

-- Create secure email check RPC for unauthenticated check
CREATE OR REPLACE FUNCTION public.check_email_exists(email_to_check text)
RETURNS boolean AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.profiles WHERE email = email_to_check
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = '';

-- Revoke public execution to ensure explicit grants
REVOKE EXECUTE ON FUNCTION public.check_email_exists(text) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.check_email_exists(text) TO anon, authenticated, service_role;

COMMIT;

-- ==========================================================================
-- Source: 022_allow_auto_pay_status.sql
-- ==========================================================================

-- ============================================================
-- 022: ALLOW AUTO-PAY STATUS
-- Drop the default payment_status check constraint and add a new
-- constraint that permits 'auto_pay' value.
-- ============================================================

-- Drop the old constraint
ALTER TABLE public.invoices DROP CONSTRAINT IF EXISTS invoices_payment_status_check;

-- Create the new constraint permitting 'unpaid', 'partial', 'paid', and 'auto_pay'
ALTER TABLE public.invoices ADD CONSTRAINT invoices_payment_status_check 
  CHECK (payment_status = ANY (ARRAY['unpaid'::text, 'partial'::text, 'paid'::text, 'auto_pay'::text]));

-- Ensure the default value is 'unpaid'
ALTER TABLE public.invoices ALTER COLUMN payment_status SET DEFAULT 'unpaid';

-- ==========================================================================
-- Source: 026_normalize_invoice_line_items.sql
-- ==========================================================================

-- Migration 026: Normalize Invoice Line Items
-- This migration removes existing invoice data and creates a normalized invoice_line_items table.

-- 1. Remove existing invoice data (and cascading dependencies like payments) to start fresh.
-- Guard the destructive reset path so migration replay cannot wipe a populated database.
DO $$
BEGIN
  IF (SELECT count(*) FROM public.invoices) = 0 THEN
    TRUNCATE TABLE public.invoices CASCADE;
  ELSE
    RAISE NOTICE '026: invoices table not empty (% rows); skipping TRUNCATE to protect data',
      (SELECT count(*) FROM public.invoices);
  END IF;
END $$;
-- 2. Create the invoice_line_items table
CREATE TABLE IF NOT EXISTS public.invoice_line_items (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    invoice_id UUID REFERENCES public.invoices(id) ON DELETE CASCADE,
    organization_id UUID REFERENCES public.organizations(id),
    inventory_item_id TEXT, -- References product_id
    item_name TEXT NOT NULL,
    quantity NUMERIC(10,2) NOT NULL DEFAULT 1,
    unit_price NUMERIC(12,2) NOT NULL DEFAULT 0,
    total_price NUMERIC(12,2) NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- 3. Add trigger for updated_at
DROP TRIGGER IF EXISTS set_updated_at ON public.invoice_line_items;
CREATE TRIGGER set_updated_at 
    BEFORE UPDATE ON public.invoice_line_items 
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- 4. Enable RLS
ALTER TABLE public.invoice_line_items ENABLE ROW LEVEL SECURITY;

-- Compatibility helpers for fresh migration replay after 002 drops the initial helpers.
CREATE OR REPLACE FUNCTION public.is_manager_or_above()
RETURNS BOOLEAN AS $func$
  SELECT public.get_auth_role() IN ('manager', 'owner', 'admin', 'platform_admin');
$func$ LANGUAGE sql SECURITY DEFINER STABLE;

CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN AS $func$
  SELECT public.get_auth_role() IN ('admin', 'platform_admin');
$func$ LANGUAGE sql SECURITY DEFINER STABLE;

CREATE OR REPLACE FUNCTION public.is_owner_or_admin()
RETURNS BOOLEAN AS $func$
  SELECT public.get_auth_role() IN ('owner', 'admin', 'platform_admin');
$func$ LANGUAGE sql SECURITY DEFINER STABLE;
-- 5. RLS Policies
DROP POLICY IF EXISTS "All users can view invoice line items" ON public.invoice_line_items;
CREATE POLICY "All users can view invoice line items" ON public.invoice_line_items 
    FOR SELECT USING (organization_id = public.get_auth_org());

DROP POLICY IF EXISTS "Manager+ can manage invoice line items" ON public.invoice_line_items;
CREATE POLICY "Manager+ can manage invoice line items" ON public.invoice_line_items 
    FOR INSERT WITH CHECK (public.is_manager_or_above() AND organization_id = public.get_auth_org());

DROP POLICY IF EXISTS "Manager+ can update invoice line items" ON public.invoice_line_items;
CREATE POLICY "Manager+ can update invoice line items" ON public.invoice_line_items 
    FOR UPDATE USING (public.is_manager_or_above() AND organization_id = public.get_auth_org());

DROP POLICY IF EXISTS "Admin can delete invoice line items" ON public.invoice_line_items;
CREATE POLICY "Admin can delete invoice line items" ON public.invoice_line_items 
    FOR DELETE USING (public.is_admin() AND organization_id = public.get_auth_org());

-- 6. Indexes
CREATE INDEX IF NOT EXISTS idx_invoice_line_items_invoice_id ON public.invoice_line_items(invoice_id);
CREATE INDEX IF NOT EXISTS idx_invoice_line_items_org_id ON public.invoice_line_items(organization_id);

