-- ==========================================================================
-- Source: 053_fix_auth_user_fk_constraints.sql
-- ==========================================================================

-- ============================================================
-- Migration 053: Fix auth.users foreign key constraints
-- 
-- Fixes "Database error deleting user" by updating all tables 
-- that reference auth.users to use ON DELETE SET NULL.
-- ============================================================

BEGIN;

DO $$ 
DECLARE
    rec record;
BEGIN
    -- Loop through all foreign keys that reference auth.users(id)
    FOR rec IN 
        SELECT 
            tc.table_schema, 
            tc.table_name, 
            kcu.column_name, 
            tc.constraint_name
        FROM 
            information_schema.table_constraints AS tc 
            JOIN information_schema.key_column_usage AS kcu
              ON tc.constraint_name = kcu.constraint_name
              AND tc.table_schema = kcu.table_schema
            JOIN information_schema.constraint_column_usage AS ccu
              ON ccu.constraint_name = tc.constraint_name
              AND ccu.table_schema = tc.table_schema
        WHERE tc.constraint_type = 'FOREIGN KEY' 
          AND ccu.table_schema = 'auth'
          AND ccu.table_name = 'users'
          AND ccu.column_name = 'id'
          -- Exclude tables that already use CASCADE correctly
          AND tc.table_name NOT IN ('profiles', 'organization_members', 'brand_members', 'location_members', 'notifications', 'role_permissions', 'user_organizations')
    LOOP
        -- Drop the existing strict constraint
        EXECUTE format('ALTER TABLE %I.%I DROP CONSTRAINT IF EXISTS %I;', rec.table_schema, rec.table_name, rec.constraint_name);
        
        -- Add the relaxed constraint with ON DELETE SET NULL
        EXECUTE format('ALTER TABLE %I.%I ADD CONSTRAINT %I FOREIGN KEY (%I) REFERENCES auth.users(id) ON DELETE SET NULL;', 
            rec.table_schema, rec.table_name, rec.constraint_name, rec.column_name);
            
        RAISE NOTICE 'Updated constraint % on table %', rec.constraint_name, rec.table_name;
    END LOOP;
END $$;

COMMIT;

-- ==========================================================================
-- Source: 054_custom_rbac_roles.sql
-- ==========================================================================

-- Migration 054: Custom RBAC Roles per Organization
-- Extends the global roles system to allow organizations to build custom granular roles

BEGIN;

-- 1. Add organization_id and customization fields to roles table
ALTER TABLE public.roles 
ADD COLUMN IF NOT EXISTS organization_id UUID REFERENCES public.organizations(id) ON DELETE CASCADE,
ADD COLUMN IF NOT EXISTS description TEXT,
ADD COLUMN IF NOT EXISTS color TEXT DEFAULT 'slate',
ADD COLUMN IF NOT EXISTS default_page_permissions JSONB DEFAULT '{}'::jsonb,
ADD COLUMN IF NOT EXISTS default_signing_privileges JSONB DEFAULT '{}'::jsonb,
ADD COLUMN IF NOT EXISTS is_system BOOLEAN DEFAULT false;

-- Mark existing hardcoded roles as system roles
UPDATE public.roles SET is_system = true WHERE name IN ('platform_admin', 'org_owner', 'branch_manager', 'location_manager', 'ground_staff');

-- 2. Modify the unique constraint
-- We need to drop the existing global UNIQUE on `name`
ALTER TABLE public.roles DROP CONSTRAINT IF EXISTS roles_name_key;

-- System roles must be globally unique. Custom roles must be unique within an org.
CREATE UNIQUE INDEX IF NOT EXISTS idx_roles_system_name ON public.roles (name) WHERE is_system = true;
CREATE UNIQUE INDEX IF NOT EXISTS idx_roles_org_name ON public.roles (organization_id, name) WHERE is_system = false;

-- 3. Update RLS policies for roles table
DROP POLICY IF EXISTS "Users can view roles" ON public.roles;

-- Anyone can read system roles, and users can read their own org's custom roles
CREATE POLICY "Users can view roles" ON public.roles 
FOR SELECT USING (
    is_system = true 
    OR organization_id = public.get_auth_org() 
    OR public.get_auth_role() = 'platform_admin'
);

-- Only org owners (or platform admins) can insert/update custom roles
CREATE POLICY "Org owners can manage custom roles" ON public.roles 
FOR ALL USING (
    is_system = false 
    AND (
        (public.get_auth_role() = 'org_owner' AND organization_id = public.get_auth_org())
        OR public.get_auth_role() = 'platform_admin'
    )
);

COMMIT;

-- ==========================================================================
-- Source: 055_dynamic_recipe_costing.sql
-- ==========================================================================

-- Migration 055: Dynamic Recipe Costing & Margin Alerts
-- Automatically cascades pricing updates from Vendor Invoices to Products and Inventory

BEGIN;

-- Create trigger function that updates product and inventory pricing when an invoice is validated
CREATE OR REPLACE FUNCTION public.cascade_invoice_prices()
RETURNS TRIGGER AS $$
DECLARE
    r RECORD;
BEGIN
    -- Only run when status changes to 'validated' or 'approved'
    IF NEW.status IN ('validated', 'approved') AND OLD.status NOT IN ('validated', 'approved') THEN
        -- Loop through all line items for this invoice
        FOR r IN 
            SELECT inventory_item_id, unit_price 
            FROM public.invoice_line_items 
            WHERE invoice_id = NEW.id AND inventory_item_id IS NOT NULL
        LOOP
            -- 1. Update products table
            -- This will automatically trigger `recalculate_recipe_costs_on_price_change` (Migration 044)
            UPDATE public.products
            SET 
                latest_price = r.unit_price,
                updated_at = now()
            WHERE product_id = r.inventory_item_id 
              AND organization_id = NEW.organization_id;

            -- 2. Update inventory table
            UPDATE public.inventory
            SET 
                unit_cost = r.unit_price,
                current_value = current_quantity * r.unit_price,
                updated_at = now()
            WHERE product_id = r.inventory_item_id
              AND organization_id = NEW.organization_id;
        END LOOP;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Attach trigger to invoices
DROP TRIGGER IF EXISTS trigger_cascade_invoice_prices ON public.invoices;
CREATE TRIGGER trigger_cascade_invoice_prices
    AFTER UPDATE OF status ON public.invoices
    FOR EACH ROW
    EXECUTE FUNCTION public.cascade_invoice_prices();

COMMIT;

-- ==========================================================================
-- Source: 056_sub_recipes.sql
-- ==========================================================================

-- Migration 056: Sub-recipes and JSONB Sync
-- Allows nested recipes and automatically synchronizes the frontend's JSONB array to the relational table

BEGIN;

-- 1. Add sub_recipe_id to recipe_ingredients
ALTER TABLE public.recipe_ingredients
ADD COLUMN IF NOT EXISTS sub_recipe_id UUID REFERENCES public.recipes(id) ON DELETE CASCADE;

-- 2. Modify constraint (product_id or sub_recipe_id must be provided, but not both)
-- Actually, we'll just allow it without strict constraints for flexibility.

-- 3. Create a trigger to automatically sync the JSONB `ingredients` column on recipes 
-- to the `recipe_ingredients` table.
CREATE OR REPLACE FUNCTION public.sync_recipe_ingredients_from_jsonb()
RETURNS TRIGGER AS $$
DECLARE
    ing RECORD;
    v_product_id UUID;
    v_sub_recipe_id UUID;
BEGIN
    -- Delete existing ingredients for this recipe to replace them
    DELETE FROM public.recipe_ingredients WHERE recipe_id = NEW.id;

    -- Iterate over the JSONB array and insert into recipe_ingredients
    -- We assume the JSON structure has `product_id`, `sub_recipe_id`, `quantity`, `unit`
    IF NEW.ingredients IS NOT NULL AND jsonb_typeof(NEW.ingredients) = 'array' THEN
        FOR ing IN SELECT * FROM jsonb_array_elements(NEW.ingredients)
        LOOP
            v_product_id := NULL;
            v_sub_recipe_id := NULL;

            IF (ing.value->>'product_id') IS NOT NULL AND (ing.value->>'product_id') != '' THEN
                v_product_id := (ing.value->>'product_id')::UUID;
            END IF;

            IF (ing.value->>'sub_recipe_id') IS NOT NULL AND (ing.value->>'sub_recipe_id') != '' THEN
                v_sub_recipe_id := (ing.value->>'sub_recipe_id')::UUID;
            END IF;

            IF v_product_id IS NOT NULL OR v_sub_recipe_id IS NOT NULL THEN
                INSERT INTO public.recipe_ingredients (
                    organization_id,
                    recipe_id,
                    product_id,
                    sub_recipe_id,
                    quantity,
                    unit
                ) VALUES (
                    NEW.organization_id,
                    NEW.id,
                    v_product_id,
                    v_sub_recipe_id,
                    COALESCE((ing.value->>'quantity')::NUMERIC, 0),
                    ing.value->>'unit'
                );
            END IF;
        END LOOP;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Attach the sync trigger to the recipes table
DROP TRIGGER IF EXISTS trigger_sync_recipe_ingredients ON public.recipes;
CREATE TRIGGER trigger_sync_recipe_ingredients
    AFTER INSERT OR UPDATE OF ingredients ON public.recipes
    FOR EACH ROW
    EXECUTE FUNCTION public.sync_recipe_ingredients_from_jsonb();

-- 4. Create an initial sync for existing recipes
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT id, organization_id, ingredients FROM public.recipes WHERE ingredients IS NOT NULL AND jsonb_typeof(ingredients) = 'array'
    LOOP
        -- This forces the trigger to run by doing a dummy update
        UPDATE public.recipes SET updated_at = now() WHERE id = r.id;
    END LOOP;
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 057_avt_variance_rpc.sql
-- ==========================================================================

-- Migration 057: AvT Variance RPC
-- Creates a function to aggregate inventory movements into an Actual vs Theoretical variance report

BEGIN;

CREATE OR REPLACE FUNCTION public.get_avt_variance_report(p_start_date DATE, p_end_date DATE)
RETURNS TABLE (
    id UUID,
    ingredient TEXT,
    theoretical NUMERIC,
    actual NUMERIC,
    unit TEXT,
    "costPerUnit" NUMERIC,
    status TEXT
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        i.id,
        i.product_name AS ingredient,
        COALESCE(SUM(CASE WHEN im.movement_type = 'recipe_consumption' THEN ABS(im.quantity) ELSE 0 END), 0) AS theoretical,
        COALESCE(SUM(CASE WHEN im.movement_type IN ('recipe_consumption', 'wastage', 'spoilage', 'stock_count') AND im.quantity < 0 THEN ABS(im.quantity) WHEN im.movement_type = 'manual_adjustment' AND im.quantity < 0 THEN ABS(im.quantity) ELSE 0 END), 0) AS actual,
        i.current_unit AS unit,
        COALESCE(i.unit_cost, 0) AS "costPerUnit",
        CASE 
            WHEN COALESCE(SUM(CASE WHEN im.movement_type IN ('recipe_consumption', 'wastage', 'spoilage', 'stock_count') AND im.quantity < 0 THEN ABS(im.quantity) WHEN im.movement_type = 'manual_adjustment' AND im.quantity < 0 THEN ABS(im.quantity) ELSE 0 END), 0) > 
                 COALESCE(SUM(CASE WHEN im.movement_type = 'recipe_consumption' THEN ABS(im.quantity) ELSE 0 END), 0) * 1.10 THEN 'critical'
            WHEN COALESCE(SUM(CASE WHEN im.movement_type IN ('recipe_consumption', 'wastage', 'spoilage', 'stock_count') AND im.quantity < 0 THEN ABS(im.quantity) WHEN im.movement_type = 'manual_adjustment' AND im.quantity < 0 THEN ABS(im.quantity) ELSE 0 END), 0) > 
                 COALESCE(SUM(CASE WHEN im.movement_type = 'recipe_consumption' THEN ABS(im.quantity) ELSE 0 END), 0) * 1.05 THEN 'warning'
            ELSE 'good'
        END AS status
    FROM public.inventory i
    JOIN public.inventory_movements im 
        ON im.inventory_id = i.id 
        AND im.organization_id = i.organization_id
        AND DATE(im.created_at) >= p_start_date 
        AND DATE(im.created_at) <= p_end_date
    WHERE i.organization_id = public.get_auth_org()
    GROUP BY i.id, i.product_name, i.current_unit, i.unit_cost
    HAVING COALESCE(SUM(CASE WHEN im.movement_type = 'recipe_consumption' THEN ABS(im.quantity) ELSE 0 END), 0) > 0;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMIT;

