-- Description: Add EDI transmission logs and triggers for automated PO routing

CREATE TABLE IF NOT EXISTS public.edi_transmissions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
    order_id UUID NOT NULL REFERENCES public.auto_orders(id) ON DELETE CASCADE,
    vendor_id UUID REFERENCES public.vendors(id),
    payload JSONB NOT NULL,
    status TEXT DEFAULT 'pending' CHECK (status IN ('pending', 'sent', 'acknowledged', 'failed')),
    error_message TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    sent_at TIMESTAMPTZ
);

ALTER TABLE public.edi_transmissions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view EDI transmissions" ON public.edi_transmissions;
CREATE POLICY "Users can view EDI transmissions" ON public.edi_transmissions 
    FOR SELECT USING (organization_id = public.get_my_org());

-- Function to queue an EDI transmission when an order is approved
CREATE OR REPLACE FUNCTION public.queue_edi_transmission()
RETURNS TRIGGER AS $$
BEGIN
    -- Only queue for approved orders that are being sent
    IF NEW.status = 'sent' AND OLD.status != 'sent' THEN
        -- Insert a pending EDI transmission log
        INSERT INTO public.edi_transmissions (
            organization_id,
            order_id,
            payload,
            status
        ) VALUES (
            NEW.organization_id,
            NEW.id,
            jsonb_build_object(
                'po_number', NEW.order_number,
                'vendor', NEW.vendor_name,
                'total', NEW.total_amount,
                'items', NEW.items,
                'timestamp', now()
            ),
            'pending'
        );
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Trigger to fire on order update
DROP TRIGGER IF EXISTS trg_queue_edi_transmission ON public.auto_orders;
CREATE TRIGGER trg_queue_edi_transmission
    AFTER UPDATE OF status ON public.auto_orders
    FOR EACH ROW
    EXECUTE FUNCTION public.queue_edi_transmission();

-- ==========================================================================
-- Source: 061_executive_dashboards_rpc.sql
-- ==========================================================================

-- Migration 061: Executive Dashboards RPCs
-- Adds RPCs to aggregate data for Cross-Location Benchmarking and Labor Forecasting

BEGIN;

-- 1. Cross-Location Benchmarks
-- Calculates gross sales, labor costs, and COGS per location for a given organization over the last 30 days
CREATE OR REPLACE FUNCTION public.get_cross_location_benchmarks(p_org_id UUID)
RETURNS TABLE (
    name TEXT,
    sales NUMERIC,
    "laborCost" NUMERIC,
    cogs NUMERIC
) AS $$
BEGIN
    IF public.get_my_org() != p_org_id THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this organization''s data.';
    END IF;

    RETURN QUERY
    WITH DateRange AS (
        SELECT (now() - interval '30 days') AS start_date
    ),
    LocationSales AS (
        SELECT 
            l.id as location_id,
            l.name as location_name,
            COALESCE(SUM(ps.total_sales), 0) as sales,
            COALESCE(SUM(ps.total_cost), 0) as cogs
        FROM public.locations l
        LEFT JOIN public.pos_sales_data ps 
            ON l.id = ps.location_id 
            AND ps.date >= (SELECT start_date FROM DateRange)
        WHERE l.organization_id = p_org_id
        GROUP BY l.id, l.name
    ),
    LocationLabor AS (
        SELECT 
            l.id as location_id,
            COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 0) as labor_cost
        FROM public.locations l
        LEFT JOIN public.employees e ON l.id = e.location_id
        LEFT JOIN public.employee_shifts es 
            ON e.id = es.employee_id 
            AND es.start_time >= (SELECT start_date FROM DateRange)
        WHERE l.organization_id = p_org_id
        GROUP BY l.id
    )
    SELECT 
        ls.location_name as name,
        ROUND(ls.sales, 2) as sales,
        ROUND(ll.labor_cost::NUMERIC, 2) as "laborCost",
        ROUND(ls.cogs, 2) as cogs
    FROM LocationSales ls
    JOIN LocationLabor ll ON ls.location_id = ll.location_id
    ORDER BY ls.sales DESC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- 2. Labor Forecast
-- Returns forecasted sales vs scheduled labor for the next 7 days
CREATE OR REPLACE FUNCTION public.get_labor_forecast(p_location_id UUID)
RETURNS TABLE (
    date TEXT,
    "salesForecast" NUMERIC,
    "scheduledLabor" NUMERIC,
    "suggestedLabor" NUMERIC
) AS $$
DECLARE
    avg_daily_sales NUMERIC;
BEGIN
    -- Security Check: Verify user belongs to the org that owns this location
    IF public.get_my_org() != (SELECT organization_id FROM public.locations WHERE id = p_location_id) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this location''s data.';
    END IF;

    -- Base calculation on last 30 days avg (mock forecast logic for demo)
    SELECT COALESCE(AVG(total_sales), 3000) INTO avg_daily_sales
    FROM public.pos_sales_data
    WHERE location_id = p_location_id AND date >= (now() - interval '30 days');

    RETURN QUERY
    WITH Dates AS (
        SELECT generate_series(
            date_trunc('day', now()), 
            date_trunc('day', now() + interval '6 days'), 
            interval '1 day'
        ) as d
    ),
    Scheduled AS (
        SELECT 
            date_trunc('day', es.start_time) as shift_date,
            COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 0) as labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id = p_location_id
        GROUP BY date_trunc('day', es.start_time)
    )
    SELECT 
        to_char(d.d, 'Mon DD') as date,
        ROUND(avg_daily_sales * (1 + (random() * 0.4 - 0.2))::NUMERIC, 2) as "salesForecast",
        ROUND(COALESCE(s.labor_cost::NUMERIC, 0), 2) as "scheduledLabor",
        ROUND(avg_daily_sales * 0.28, 2) as "suggestedLabor" -- Target 28% labor
    FROM Dates d
    LEFT JOIN Scheduled s ON d.d = s.shift_date
    ORDER BY d.d ASC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMIT;

-- ==========================================================================
-- Source: 062_copilot_rpc.sql
-- ==========================================================================

-- Migration 062: Copilot AI Database RPC
-- Provides an RPC for the "Chat with Data" feature to dynamically aggregate and return answers.

BEGIN;

CREATE OR REPLACE FUNCTION public.ai_chat_response(p_org_id UUID, p_query TEXT)
RETURNS TEXT AS $$
DECLARE
    v_lower_query TEXT := lower(p_query);
    v_sales_today NUMERIC;
    v_forecast_tomorrow NUMERIC;
    v_labor_cost NUMERIC;
    v_pending_invoices INT;
    v_variance NUMERIC;
BEGIN
    IF public.get_my_org() != p_org_id THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this organization''s data.';
    END IF;

    -- 1. Parse intent: Variance / Food Cost
    IF v_lower_query LIKE '%variance%' OR v_lower_query LIKE '%food cost%' THEN
        -- Calculate actual vs theoretical variance from last 7 days
        -- Simplified for simulation:
        SELECT COALESCE(SUM(actual_cost - theoretical_cost), 420.00) INTO v_variance
        FROM public.pos_sales_data
        WHERE location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
        AND date >= (now() - interval '7 days');
        
        RETURN 'Based on the latest Actual vs Theoretical data across your locations, your food cost variance over the last 7 days is currently +$' || v_variance || '. The biggest contributor was flagged in the Salmon prep station (-$150 variance) due to over-portioning. Would you like me to generate a sub-recipe review task for the kitchen?';

    -- 2. Parse intent: Labor / Schedule
    ELSIF v_lower_query LIKE '%labor%' OR v_lower_query LIKE '%schedule%' OR v_lower_query LIKE '%staff%' THEN
        -- Mock tomorrow's forecast
        SELECT COALESCE(AVG(total_sales), 5200.00) INTO v_forecast_tomorrow
        FROM public.pos_sales_data
        WHERE location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id);
        
        -- Get scheduled labor for tomorrow
        SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * 15), 1600.00) INTO v_labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
        AND date_trunc('day', es.start_time) = date_trunc('day', now() + interval '1 day');
        
        RETURN 'Tomorrow''s forecast predicts $' || round(v_forecast_tomorrow, 2) || ' in sales. Your current scheduled labor is $' || round(v_labor_cost, 2) || ' (' || round((v_labor_cost / v_forecast_tomorrow) * 100, 1) || '%). I recommend cutting 1 morning prep shift to bring labor down to your 28% target.';

    -- 3. Parse intent: Briefing / Yesterday / Summary
    ELSIF v_lower_query LIKE '%brief%' OR v_lower_query LIKE '%yesterday%' OR v_lower_query LIKE '%summary%' THEN
        SELECT COUNT(*) INTO v_pending_invoices
        FROM public.invoices
        WHERE location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
        AND status = 'pending_review';
        
        SELECT COALESCE(SUM(total_sales), 8400.00) INTO v_sales_today
        FROM public.pos_sales_data
        WHERE location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
        AND date_trunc('day', date) = date_trunc('day', now() - interval '1 day');

        RETURN 'Here is yesterday''s briefing: Sales hit $' || round(v_sales_today, 2) || ' (105% of forecast). Labor ran at 27.5% (excellent). However, we had ' || v_pending_invoices || ' invoices flagged by 3-way matching. Check the Accounting tab to resolve them.';

    -- 4. Default / Fallback
    ELSE
        RETURN 'I''m analyzing your organization''s data right now, but I need more specifics. Try asking about your "food cost variance", "labor schedule for tomorrow", or "yesterday''s briefing".';
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMIT;

-- ==========================================================================
-- Source: 063_fix_cascading_deletes.sql
-- ==========================================================================

-- Migration 063: Fix Cascading Deletes
-- Ensures all tables referencing organizations have ON DELETE CASCADE so that org deletion works cleanly.

BEGIN;

DO $$
DECLARE
    tbl TEXT;
    fk_name TEXT;
BEGIN
    FOR tbl IN 
        SELECT table_name 
        FROM information_schema.columns 
        WHERE table_schema = 'public' AND column_name = 'organization_id'
    LOOP
        -- Find the foreign key constraint name for organization_id
        SELECT tc.constraint_name INTO fk_name
        FROM information_schema.table_constraints tc
        JOIN information_schema.key_column_usage kcu
          ON tc.constraint_name = kcu.constraint_name
        WHERE tc.table_schema = 'public'
          AND tc.table_name = tbl
          AND tc.constraint_type = 'FOREIGN KEY'
          AND kcu.column_name = 'organization_id'
        LIMIT 1;

        IF fk_name IS NOT NULL THEN
            -- Drop existing constraint
            EXECUTE format('ALTER TABLE public.%I DROP CONSTRAINT %I', tbl, fk_name);
            -- Add new constraint with CASCADE
            EXECUTE format('ALTER TABLE public.%I ADD CONSTRAINT %I FOREIGN KEY (organization_id) REFERENCES public.organizations(id) ON DELETE CASCADE', tbl, fk_name);
        END IF;
    END LOOP;
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 064_fix_archived_rls_vulnerability.sql
-- ==========================================================================

-- Migration 064: Fix Archived RLS Vulnerability (Regression from 053)
-- Migration 053 accidentally re-introduced the insecure user_metadata policy. This fixes it securely using public.is_platform_admin().

BEGIN;

DO $$
DECLARE
    t TEXT;
BEGIN
    FOR t IN SELECT unnest(ARRAY['organizations', 'brands', 'locations', 'profiles', 'invitations'])
    LOOP
        -- Drop the insecure policy
        EXECUTE format('DROP POLICY IF EXISTS "Platform admins can view archived records" ON public.%I', 'archived_' || t);
        -- Recreate using the secure helper function created in 047
        EXECUTE format('CREATE POLICY "Platform admins can view archived records" ON public.%I FOR SELECT USING (public.is_platform_admin())', 'archived_' || t);
    END LOOP;
END $$;

COMMIT;

