ALTER TABLE public.auto_orders
  DROP CONSTRAINT IF EXISTS auto_orders_status_check;

ALTER TABLE public.auto_orders
  ADD CONSTRAINT auto_orders_status_check CHECK (
    status IS NULL OR status IN (
      'pending',
      'pending_approval',
      'approved',
      'sent',
      'partially_received',
      'received',
      'ordered',
      'cancelled'
    )
