ALTER TABLE public.auto_orders
  ADD COLUMN IF NOT EXISTS sent_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS sent_via TEXT,
  ADD COLUMN IF NOT EXISTS delivery_status TEXT DEFAULT 'not_sent',
