CREATE OR REPLACE FUNCTION public.touch_invoice_ingestion_jobs_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_invoice_ingestion_jobs_updated_at ON public.invoice_ingestion_jobs;
