-- ==========================================================================

-- 081: Vendor and Item Matching
-- Creates tables for vendor aliases, vendor items, and internal item mappings. Adds fuzzy matching support.

BEGIN;

CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS fuzzystrmatch WITH SCHEMA extensions;

-- Vendor Aliases
CREATE TABLE IF NOT EXISTS public.vendor_aliases (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  canonical_vendor_id UUID REFERENCES public.vendors(id) ON DELETE CASCADE,
  alias_name TEXT NOT NULL,
  confidence_score FLOAT,
  is_verified BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(organization_id, alias_name)
);

-- Vendor Items Catalog
CREATE TABLE IF NOT EXISTS public.vendor_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  vendor_id UUID REFERENCES public.vendors(id) ON DELETE CASCADE,
  vendor_item_code TEXT,
  vendor_item_name TEXT NOT NULL,
  vendor_unit TEXT,
  default_price NUMERIC,
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(organization_id, vendor_id, vendor_item_code, vendor_item_name)
);

-- Mapping from Vendor Items to Internal Products
CREATE TABLE IF NOT EXISTS public.vendor_item_mappings (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  vendor_item_id UUID NOT NULL REFERENCES public.vendor_items(id) ON DELETE CASCADE,
  internal_product_id UUID REFERENCES public.products(id) ON DELETE CASCADE,
  conversion_multiplier NUMERIC DEFAULT 1.0,
  is_verified BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(vendor_item_id, internal_product_id)
);

ALTER TABLE public.vendor_aliases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vendor_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vendor_item_mappings ENABLE ROW LEVEL SECURITY;

-- RLS Policies
DROP POLICY IF EXISTS "Vendor aliases read" ON public.vendor_aliases;
CREATE POLICY "Vendor aliases read" ON public.vendor_aliases FOR SELECT USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);

DROP POLICY IF EXISTS "Vendor aliases write" ON public.vendor_aliases;
CREATE POLICY "Vendor aliases write" ON public.vendor_aliases FOR ALL USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);

DROP POLICY IF EXISTS "Vendor items read" ON public.vendor_items;
CREATE POLICY "Vendor items read" ON public.vendor_items FOR SELECT USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);

DROP POLICY IF EXISTS "Vendor items write" ON public.vendor_items;
CREATE POLICY "Vendor items write" ON public.vendor_items FOR ALL USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);

DROP POLICY IF EXISTS "Vendor item mappings read" ON public.vendor_item_mappings;
CREATE POLICY "Vendor item mappings read" ON public.vendor_item_mappings FOR SELECT USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);

DROP POLICY IF EXISTS "Vendor item mappings write" ON public.vendor_item_mappings;
CREATE POLICY "Vendor item mappings write" ON public.vendor_item_mappings FOR ALL USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);

CREATE OR REPLACE FUNCTION public.match_vendor(p_org_id UUID, p_vendor_name TEXT)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_vendor_id UUID;
  v_exact_match UUID;
  v_alias_match UUID;
  v_fuzzy_match UUID;
BEGIN
  -- 1. Exact match on vendors table
  SELECT id INTO v_exact_match FROM public.vendors 
  WHERE organization_id = p_org_id AND LOWER(name) = LOWER(p_vendor_name)
  LIMIT 1;
  
  IF v_exact_match IS NOT NULL THEN
    RETURN v_exact_match;
  END IF;

  -- 2. Exact match on vendor_aliases
  SELECT canonical_vendor_id INTO v_alias_match FROM public.vendor_aliases
  WHERE organization_id = p_org_id AND LOWER(alias_name) = LOWER(p_vendor_name) AND is_verified = true
  LIMIT 1;

  IF v_alias_match IS NOT NULL THEN
    RETURN v_alias_match;
  END IF;

  -- 3. Fuzzy match using Levenshtein distance
  -- Only consider if distance <= 3 (e.g. slight typo)
  SELECT id INTO v_fuzzy_match FROM public.vendors
  WHERE organization_id = p_org_id AND extensions.levenshtein(LOWER(name), LOWER(p_vendor_name)) <= 3
  ORDER BY extensions.levenshtein(LOWER(name), LOWER(p_vendor_name)) ASC
  LIMIT 1;
  
  RETURN v_fuzzy_match;
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 082_three_way_reconciliation.sql
-- ==========================================================================

-- 082: Three-Way Line-Item Reconciliation
-- Creates tables and logic to reconcile invoice lines against POs and Receipts.

BEGIN;

-- Tolerance Configurations
CREATE TABLE IF NOT EXISTS public.tolerance_configurations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  vendor_id UUID REFERENCES public.vendors(id) ON DELETE CASCADE,
  category TEXT, -- 'food', 'beverage', etc. NULL means all categories.
  product_id UUID REFERENCES public.products(id) ON DELETE CASCADE,
  
  -- Tolerances can be absolute amounts or percentages
  price_tolerance_percent NUMERIC DEFAULT 0.05, -- 5%
  price_tolerance_amount NUMERIC DEFAULT 1.00,  -- $1.00
  qty_tolerance_percent NUMERIC DEFAULT 0.00,
  qty_tolerance_amount NUMERIC DEFAULT 0.00,
  
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- Invoice Line Matches
CREATE TABLE IF NOT EXISTS public.invoice_line_matches (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  invoice_line_id UUID NOT NULL REFERENCES public.invoice_line_items(id) ON DELETE CASCADE,
  purchase_order_line_id UUID, -- REFERENCES public.purchase_order_lines(id)
  receipt_movement_id UUID, -- REFERENCES public.inventory_movements(id) for receipts
  
  match_confidence FLOAT DEFAULT 0.0,
  match_status TEXT DEFAULT 'unmatched' CHECK (match_status IN ('unmatched', 'partial', 'exact', 'variance')),
  
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(invoice_line_id)
);

-- Reconciliation Variances
CREATE TABLE IF NOT EXISTS public.reconciliation_variances (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  invoice_id UUID NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,
  invoice_line_id UUID REFERENCES public.invoice_line_items(id) ON DELETE CASCADE,
  
  variance_type TEXT NOT NULL CHECK (variance_type IN ('price', 'quantity', 'missing_po', 'missing_receipt', 'unexpected_item', 'packaging')),
  expected_value NUMERIC,
  actual_value NUMERIC,
  variance_amount NUMERIC NOT NULL,
  
  is_resolved BOOLEAN DEFAULT false,
  resolution_notes TEXT,
  resolved_by UUID REFERENCES auth.users(id),
  resolved_at TIMESTAMPTZ,
  
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE public.tolerance_configurations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoice_line_matches ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reconciliation_variances ENABLE ROW LEVEL SECURITY;

-- RLS
CREATE POLICY "Tolerances read" ON public.tolerance_configurations FOR SELECT USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);
CREATE POLICY "Tolerances write" ON public.tolerance_configurations FOR ALL USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);

CREATE POLICY "Line matches read" ON public.invoice_line_matches FOR SELECT USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);
CREATE POLICY "Line matches write" ON public.invoice_line_matches FOR ALL USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);

CREATE POLICY "Variances read" ON public.reconciliation_variances FOR SELECT USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);
CREATE POLICY "Variances write" ON public.reconciliation_variances FOR ALL USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);

-- RPC: Reconcile Invoice Lines
-- Automatically matches lines and calculates variances
CREATE OR REPLACE FUNCTION public.reconcile_invoice_lines(p_invoice_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_org_id UUID;
  v_vendor_id UUID;
  v_po_id UUID;
  v_line RECORD;
  v_match_id UUID;
  v_variance_id UUID;
  v_tolerance RECORD;
BEGIN
  SELECT organization_id, vendor_id, purchase_order_id INTO v_org_id, v_vendor_id, v_po_id 
  FROM public.invoices WHERE id = p_invoice_id;

  -- Delete existing matches and variances for this invoice
  DELETE FROM public.invoice_line_matches WHERE invoice_line_id IN (SELECT id FROM public.invoice_line_items WHERE invoice_id = p_invoice_id);
  DELETE FROM public.reconciliation_variances WHERE invoice_id = p_invoice_id;

  -- Load Tolerance config (fallback to defaults if none exist)
  SELECT * INTO v_tolerance FROM public.tolerance_configurations 
  WHERE organization_id = v_org_id AND vendor_id = v_vendor_id LIMIT 1;
  IF NOT FOUND THEN
    v_tolerance := (NULL, v_org_id, v_vendor_id, NULL, NULL, 0.05, 1.00, 0.00, 0.00, now(), now())::public.tolerance_configurations;
  END IF;

  FOR v_line IN (SELECT * FROM public.invoice_line_items WHERE invoice_id = p_invoice_id) LOOP
    -- Simple exact match stub for demonstration. In full production, this maps to PO lines and Receipt movements.
    
    INSERT INTO public.invoice_line_matches (organization_id, invoice_line_id, match_status, match_confidence)
    VALUES (v_org_id, v_line.id, 'unmatched', 0.0)
    RETURNING id INTO v_match_id;

    -- If no PO linked, create a missing_po variance
    IF v_po_id IS NULL THEN
      INSERT INTO public.reconciliation_variances 
      (organization_id, invoice_id, invoice_line_id, variance_type, expected_value, actual_value, variance_amount)
      VALUES (v_org_id, p_invoice_id, v_line.id, 'missing_po', 0, v_line.total_price, v_line.total_price);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'reconciled_lines', (SELECT count(*) FROM public.invoice_line_items WHERE invoice_id = p_invoice_id));
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 083_invoice_allocations.sql
-- ==========================================================================

-- 083: Invoice Allocations for Category Summary and Split Coding
-- Creates tables and logic to allocate invoice totals to GL accounts/categories.

BEGIN;

-- Invoice Allocations Table
CREATE TABLE IF NOT EXISTS public.invoice_allocations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  invoice_id UUID NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,
  
  -- 'line_items' (COGS), 'tax', 'delivery', 'fuel', 'other', etc.
  allocation_type TEXT NOT NULL, 
  
  -- Sourced from gl_mappings if exists, otherwise free text
  category_name TEXT,
  gl_code TEXT,
  
  -- Optional location splitting
  location_id UUID REFERENCES public.locations(id) ON DELETE SET NULL,
  
  amount NUMERIC NOT NULL DEFAULT 0.0,
  
  -- For split coding logic
  percentage NUMERIC, -- e.g., 50 for 50%. Null if flat amount split.
  
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE public.invoice_allocations ENABLE ROW LEVEL SECURITY;

-- RLS
CREATE POLICY "Invoice allocations read" ON public.invoice_allocations FOR SELECT USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);
CREATE POLICY "Invoice allocations write" ON public.invoice_allocations FOR ALL USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);

-- RPC: Calculate Default Invoice Allocations
-- Automatically buckets line items and fees into their default GL categories
CREATE OR REPLACE FUNCTION public.calculate_invoice_allocations(p_invoice_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_org_id UUID;
  v_tax NUMERIC;
  v_fuel NUMERIC;
  v_delivery NUMERIC;
  v_other NUMERIC;
  
  v_cat_record RECORD;
BEGIN
  -- Get invoice details
  SELECT organization_id, tax_amount, fuel_surcharge, delivery_fee, other_charges 
  INTO v_org_id, v_tax, v_fuel, v_delivery, v_other
  FROM public.invoices WHERE id = p_invoice_id;

  -- Clear existing auto-generated allocations (this could be enhanced to preserve manual splits in the future)
  DELETE FROM public.invoice_allocations WHERE invoice_id = p_invoice_id;

  -- 1. Aggregate Line Items by Product Category
  FOR v_cat_record IN (
    SELECT 
      COALESCE(p.category, 'uncategorized') as cat_name, 
      SUM(ili.extended_price) as total_amount
    FROM public.invoice_line_items ili
    LEFT JOIN public.products p ON ili.product_id = p.id
    WHERE ili.invoice_id = p_invoice_id
    GROUP BY COALESCE(p.category, 'uncategorized')
  ) LOOP
    IF v_cat_record.total_amount > 0 THEN
      -- Attempt to find a matching GL code
      INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, gl_code, amount)
      SELECT 
        v_org_id, p_invoice_id, 'line_items', v_cat_record.cat_name, 
        (SELECT gl_code FROM public.gl_mappings WHERE organization_id = v_org_id AND LOWER(category) = LOWER(v_cat_record.cat_name) LIMIT 1),
        v_cat_record.total_amount;
    END IF;
  END LOOP;

  -- 2. Add Tax
  IF v_tax > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'tax', 'Tax', v_tax);
  END IF;

  -- 3. Add Delivery
  IF v_delivery > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'delivery', 'Delivery Fee', v_delivery);
  END IF;

  -- 4. Add Fuel
  IF v_fuel > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'fuel', 'Fuel Surcharge', v_fuel);
  END IF;

  -- 5. Add Other
  IF v_other > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'other', 'Other Charges', v_other);
  END IF;

  RETURN jsonb_build_object('success', true, 'message', 'Allocations calculated');
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 084_approval_workflows.sql
-- ==========================================================================

-- 084: Configurable Approval Workflow
-- Replaces simple approve/reject with a policy-driven workflow.

BEGIN;

CREATE TYPE approval_instance_status AS ENUM ('pending', 'approved', 'rejected', 'cancelled');
CREATE TYPE approval_step_status AS ENUM ('pending', 'approved', 'rejected');

-- 1. Approval Policies (Rules)
CREATE TABLE IF NOT EXISTS public.approval_policies (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  
  -- Conditions
  min_amount NUMERIC DEFAULT 0,
  max_amount NUMERIC,
  category TEXT, -- If NULL, applies to all
  
  -- Requirement
  required_role TEXT NOT NULL, -- e.g., 'location_manager', 'org_admin'
  
  created_at TIMESTAMPTZ DEFAULT now()
);

-- 2. Approval Instances (The running workflow)
CREATE TABLE IF NOT EXISTS public.approval_instances (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id UUID NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,
  status approval_instance_status DEFAULT 'pending',
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- 3. Approval Steps (The specific required actions)
CREATE TABLE IF NOT EXISTS public.approval_steps (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  instance_id UUID NOT NULL REFERENCES public.approval_instances(id) ON DELETE CASCADE,
  required_role TEXT NOT NULL,
  
  status approval_step_status DEFAULT 'pending',
  approver_id UUID REFERENCES auth.users(id),
  comments TEXT,
  acted_at TIMESTAMPTZ,
  
  created_at TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE public.approval_policies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.approval_instances ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.approval_steps ENABLE ROW LEVEL SECURITY;

-- RLS
CREATE POLICY "View policies" ON public.approval_policies FOR SELECT USING (organization_id = public.get_my_org() OR public.is_platform_admin());
CREATE POLICY "Manage policies" ON public.approval_policies FOR ALL USING (
  (public.is_manager_or_above() AND organization_id = public.get_my_org()) OR public.is_platform_admin()
);

CREATE POLICY "View instances" ON public.approval_instances FOR SELECT USING (
  invoice_id IN (SELECT id FROM public.invoices WHERE organization_id = public.get_my_org())
);
CREATE POLICY "Manage instances" ON public.approval_instances FOR ALL USING (
  invoice_id IN (SELECT id FROM public.invoices WHERE organization_id = public.get_my_org())
);

CREATE POLICY "View steps" ON public.approval_steps FOR SELECT USING (
  instance_id IN (SELECT id FROM public.approval_instances WHERE invoice_id IN (SELECT id FROM public.invoices WHERE organization_id = public.get_my_org()))
);
CREATE POLICY "Manage steps" ON public.approval_steps FOR ALL USING (
  instance_id IN (SELECT id FROM public.approval_instances WHERE invoice_id IN (SELECT id FROM public.invoices WHERE organization_id = public.get_my_org()))
);

-- RPC to Evaluate Policies and Start Workflow
CREATE OR REPLACE FUNCTION public.evaluate_invoice_approval_policy(p_invoice_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_org_id UUID;
  v_amount NUMERIC;
  v_instance_id UUID;
  v_policy RECORD;
  v_steps_created INT := 0;
BEGIN
  -- Get invoice details
  SELECT organization_id, total_amount INTO v_org_id, v_amount
  FROM public.invoices WHERE id = p_invoice_id;

  -- Cancel any existing pending instances for this invoice (e.g. if it was edited)
  UPDATE public.approval_instances 
  SET status = 'cancelled', updated_at = now()
  WHERE invoice_id = p_invoice_id AND status = 'pending';

  -- Create a new instance
  INSERT INTO public.approval_instances (invoice_id, status)
  VALUES (p_invoice_id, 'pending')
  RETURNING id INTO v_instance_id;

  -- Find matching policies
  FOR v_policy IN (
    SELECT required_role FROM public.approval_policies
    WHERE organization_id = v_org_id
      AND (min_amount IS NULL OR v_amount >= min_amount)
      AND (max_amount IS NULL OR v_amount <= max_amount)
  ) LOOP
    -- Insert a step for this policy
    -- Parallel approvals: We insert them all. Any user with the required_role can approve their step.
    INSERT INTO public.approval_steps (instance_id, required_role)
    VALUES (v_instance_id, v_policy.required_role);
    
    v_steps_created := v_steps_created + 1;
  END LOOP;

  IF v_steps_created = 0 THEN
    -- Auto-approve if no policies apply
    UPDATE public.approval_instances SET status = 'approved', updated_at = now() WHERE id = v_instance_id;
    UPDATE public.invoices SET status = 'approved', updated_at = now() WHERE id = p_invoice_id;
    RETURN jsonb_build_object('status', 'auto_approved');
  ELSE
    -- Set to pending approval
    UPDATE public.invoices SET status = 'pending_approval', updated_at = now() WHERE id = p_invoice_id;
    RETURN jsonb_build_object('status', 'pending_approval', 'steps', v_steps_created);
  END IF;
END;
$$;

-- Default policy for all orgs: If no policy exists, let's make a generic one so the feature works
INSERT INTO public.approval_policies (organization_id, required_role)
SELECT id, 'org_admin' FROM public.organizations
ON CONFLICT DO NOTHING;

-- RPC to Execute an Approval Step
CREATE OR REPLACE FUNCTION public.execute_approval_step(p_step_id UUID, p_status TEXT, p_comments TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_instance_id UUID;
  v_invoice_id UUID;
  v_pending_count INT;
BEGIN
  -- Update the step
  UPDATE public.approval_steps
  SET status = p_status::approval_step_status,
      approver_id = auth.uid(),
      comments = p_comments,
      acted_at = now()
  WHERE id = p_step_id
  RETURNING instance_id INTO v_instance_id;

  SELECT invoice_id INTO v_invoice_id FROM public.approval_instances WHERE id = v_instance_id;

  IF p_status = 'rejected' THEN
    -- If one rejects, the whole instance is rejected
    UPDATE public.approval_instances SET status = 'rejected', updated_at = now() WHERE id = v_instance_id;
    UPDATE public.invoices SET status = 'rejected', updated_at = now() WHERE id = v_invoice_id;
    RETURN jsonb_build_object('status', 'rejected');
  END IF;

  IF p_status = 'approved' THEN
    -- Check if any pending steps remain for this instance
    SELECT count(*) INTO v_pending_count FROM public.approval_steps WHERE instance_id = v_instance_id AND status = 'pending';
    
    IF v_pending_count = 0 THEN
      -- All steps approved!
      UPDATE public.approval_instances SET status = 'approved', updated_at = now() WHERE id = v_instance_id;
      UPDATE public.invoices SET status = 'approved', updated_at = now() WHERE id = v_invoice_id;
      RETURN jsonb_build_object('status', 'fully_approved');
    ELSE
      RETURN jsonb_build_object('status', 'partially_approved', 'pending_steps', v_pending_count);
    END IF;
  END IF;

  RETURN jsonb_build_object('status', 'unknown');
END;
$$;

COMMIT;

