  ON public.payments
  FOR INSERT
  WITH CHECK (
    EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (
          p.role = 'platform_admin'
          OR (
            p.organization_id = public.payments.organization_id
            AND p.role IN ('location_manager', 'manager', 'branch_manager', 'org_owner', 'owner', 'admin')
          )
        )
    )
  );

CREATE POLICY "Payments role-scoped update"
  ON public.payments
  FOR UPDATE
  USING (
    EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (
          p.role = 'platform_admin'
          OR (
            p.organization_id = public.payments.organization_id
            AND p.role IN ('location_manager', 'manager', 'branch_manager', 'org_owner', 'owner', 'admin')
          )
        )
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (
          p.role = 'platform_admin'
          OR (
            p.organization_id = public.payments.organization_id
            AND p.role IN ('location_manager', 'manager', 'branch_manager', 'org_owner', 'owner', 'admin')
          )
        )
    )
  );

CREATE POLICY "Payments owner delete"
  ON public.payments
  FOR DELETE
  USING (
    EXISTS (
      SELECT 1
