COMMIT;

-- ==========================================================================
-- Source: 096_fix_labor_forecast_revenue_column.sql
-- ==========================================================================

-- 096: Fix labor forecast RPC against current POS sales schema
-- pos_sales_data stores sales in revenue, not total_sales.

BEGIN;

CREATE OR REPLACE FUNCTION public.get_labor_forecast(p_location_id UUID)
RETURNS TABLE (
    date TEXT,
    "salesForecast" NUMERIC,
    "scheduledLabor" NUMERIC,
    "suggestedLabor" NUMERIC
) AS $$
DECLARE
    avg_daily_sales NUMERIC;
BEGIN
    IF public.get_my_org() != (SELECT organization_id FROM public.locations WHERE id = p_location_id) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this location''s data.';
    END IF;

    SELECT COALESCE(AVG(revenue), 3000) INTO avg_daily_sales
    FROM public.pos_sales_data
    WHERE location_id = p_location_id
      AND date >= (now() - interval '30 days')::date;

    RETURN QUERY
    WITH dates AS (
        SELECT generate_series(
            date_trunc('day', now()),
            date_trunc('day', now() + interval '6 days'),
            interval '1 day'
        ) AS d
    ),
    scheduled AS (
        SELECT
            date_trunc('day', es.start_time) AS shift_date,
            COALESCE(SUM(EXTRACT(EPOCH FROM (COALESCE(es.end_time, es.start_time) - es.start_time)) / 3600 * COALESCE(e.hourly_rate, 15)), 0) AS labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id = p_location_id
        GROUP BY date_trunc('day', es.start_time)
    )
    SELECT
        to_char(d.d, 'Mon DD') AS date,
        ROUND(avg_daily_sales * (1 + (random() * 0.4 - 0.2))::NUMERIC, 2) AS "salesForecast",
        ROUND(COALESCE(s.labor_cost::NUMERIC, 0), 2) AS "scheduledLabor",
        ROUND(avg_daily_sales * 0.28, 2) AS "suggestedLabor"
    FROM dates d
    LEFT JOIN scheduled s ON d.d = s.shift_date
    ORDER BY d.d ASC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMIT;

-- ==========================================================================
-- Source: 097_finalize_payment_rbac_and_labor_forecast.sql
-- ==========================================================================

-- 097: Finalize payment RBAC and labor forecast RPC
-- Safely replaces any remaining permissive payment policies and fixes
-- get_labor_forecast column ambiguity after the revenue-column update.

BEGIN;

ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE
  policy_record RECORD;
BEGIN
  FOR policy_record IN
    SELECT policyname
    FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'payments'
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.payments', policy_record.policyname);
  END LOOP;
END $$;

CREATE POLICY "Payments role-scoped select"
  ON public.payments
  FOR SELECT
  USING (
    EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (
          p.role = 'platform_admin'
          OR (
            p.organization_id = public.payments.organization_id
            AND p.role IN ('location_manager', 'manager', 'branch_manager', 'org_owner', 'owner', 'admin')
          )
        )
    )
  );

CREATE POLICY "Payments role-scoped insert"
  ON public.payments
  FOR INSERT
  WITH CHECK (
    EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (
          p.role = 'platform_admin'
          OR (
            p.organization_id = public.payments.organization_id
            AND p.role IN ('location_manager', 'manager', 'branch_manager', 'org_owner', 'owner', 'admin')
          )
        )
    )
  );

CREATE POLICY "Payments role-scoped update"
  ON public.payments
  FOR UPDATE
  USING (
    EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (
          p.role = 'platform_admin'
          OR (
            p.organization_id = public.payments.organization_id
            AND p.role IN ('location_manager', 'manager', 'branch_manager', 'org_owner', 'owner', 'admin')
          )
        )
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (
          p.role = 'platform_admin'
          OR (
            p.organization_id = public.payments.organization_id
            AND p.role IN ('location_manager', 'manager', 'branch_manager', 'org_owner', 'owner', 'admin')
          )
        )
    )
  );

CREATE POLICY "Payments owner delete"
  ON public.payments
  FOR DELETE
  USING (
    EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (
          p.role = 'platform_admin'
          OR (
            p.organization_id = public.payments.organization_id
            AND p.role IN ('org_owner', 'owner', 'admin')
          )
        )
    )
  );

CREATE OR REPLACE FUNCTION public.get_labor_forecast(p_location_id UUID)
RETURNS TABLE (
    date TEXT,
    "salesForecast" NUMERIC,
    "scheduledLabor" NUMERIC,
    "suggestedLabor" NUMERIC
) AS $$
DECLARE
    avg_daily_sales NUMERIC;
BEGIN
    IF public.get_my_org() != (SELECT l.organization_id FROM public.locations l WHERE l.id = p_location_id) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this location''s data.';
    END IF;

    SELECT COALESCE(AVG(ps.revenue), 3000) INTO avg_daily_sales
    FROM public.pos_sales_data ps
    WHERE ps.location_id = p_location_id
      AND ps.date >= (now() - interval '30 days')::date;

    RETURN QUERY
    WITH forecast_dates AS (
        SELECT generate_series(
            date_trunc('day', now()),
            date_trunc('day', now() + interval '6 days'),
            interval '1 day'
        ) AS forecast_day
    ),
    scheduled AS (
        SELECT
            date_trunc('day', es.start_time) AS shift_date,
            COALESCE(SUM(EXTRACT(EPOCH FROM (COALESCE(es.end_time, es.start_time) - es.start_time)) / 3600 * COALESCE(e.hourly_rate, 15)), 0) AS labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id = p_location_id
        GROUP BY date_trunc('day', es.start_time)
    )
    SELECT
        to_char(fd.forecast_day, 'Mon DD') AS date,
        ROUND(avg_daily_sales * (1 + (random() * 0.4 - 0.2))::NUMERIC, 2) AS "salesForecast",
        ROUND(COALESCE(s.labor_cost::NUMERIC, 0), 2) AS "scheduledLabor",
        ROUND(avg_daily_sales * 0.28, 2) AS "suggestedLabor"
    FROM forecast_dates fd
    LEFT JOIN scheduled s ON fd.forecast_day = s.shift_date
    ORDER BY fd.forecast_day ASC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMIT;

-- ==========================================================================
-- Source: 098_vendor_item_price_intelligence.sql
-- ==========================================================================

-- 098: Vendor item price intelligence and invoice line mapping
-- Adds the fields needed to turn invoice lines into reusable vendor catalog data.

BEGIN;

ALTER TABLE public.vendor_items
  ADD COLUMN IF NOT EXISTS previous_price NUMERIC(12,2),
  ADD COLUMN IF NOT EXISTS last_invoice_id UUID REFERENCES public.invoices(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS last_invoice_line_id UUID REFERENCES public.invoice_line_items(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS last_purchased_at DATE,
  ADD COLUMN IF NOT EXISTS last_price_change_percent NUMERIC(8,2),
  ADD COLUMN IF NOT EXISTS price_variance_threshold_percent NUMERIC(8,2) DEFAULT 10,
  ADD COLUMN IF NOT EXISTS mapping_status TEXT DEFAULT 'unmapped'
    CHECK (mapping_status IN ('unmapped', 'suggested', 'verified')),
  ADD COLUMN IF NOT EXISTS match_confidence NUMERIC(5,2) DEFAULT 0,
  ADD COLUMN IF NOT EXISTS price_variance_flag BOOLEAN DEFAULT false;

ALTER TABLE public.invoice_line_items
  ADD COLUMN IF NOT EXISTS vendor_id UUID REFERENCES public.vendors(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS vendor_item_id UUID REFERENCES public.vendor_items(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS vendor_item_code TEXT,
  ADD COLUMN IF NOT EXISTS vendor_unit TEXT,
  ADD COLUMN IF NOT EXISTS price_variance_percent NUMERIC(8,2),
  ADD COLUMN IF NOT EXISTS price_variance_flag BOOLEAN DEFAULT false;

CREATE INDEX IF NOT EXISTS idx_vendor_items_price_variance
  ON public.vendor_items(organization_id, vendor_id, price_variance_flag);

CREATE INDEX IF NOT EXISTS idx_vendor_items_mapping_status
  ON public.vendor_items(organization_id, mapping_status);

CREATE INDEX IF NOT EXISTS idx_invoice_line_items_vendor_item
  ON public.invoice_line_items(vendor_item_id);

CREATE OR REPLACE FUNCTION public.refresh_vendor_item_mapping_status(p_vendor_item_id UUID)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_verified_count INTEGER;
  v_suggested_count INTEGER;
BEGIN
  SELECT
    COUNT(*) FILTER (WHERE is_verified = true),
    COUNT(*)
  INTO v_verified_count, v_suggested_count
  FROM public.vendor_item_mappings
  WHERE vendor_item_id = p_vendor_item_id;

  UPDATE public.vendor_items
  SET mapping_status = CASE
      WHEN v_verified_count > 0 THEN 'verified'
      WHEN v_suggested_count > 0 THEN 'suggested'
      ELSE 'unmapped'
    END,
    updated_at = now()
  WHERE id = p_vendor_item_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.touch_vendor_item_mapping_status()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vendor_item_id UUID;
BEGIN
  v_vendor_item_id := COALESCE(NEW.vendor_item_id, OLD.vendor_item_id);
  PERFORM public.refresh_vendor_item_mapping_status(v_vendor_item_id);
  RETURN COALESCE(NEW, OLD);
END;
$$;

DROP TRIGGER IF EXISTS trg_vendor_item_mapping_status_insert ON public.vendor_item_mappings;
CREATE TRIGGER trg_vendor_item_mapping_status_insert
  AFTER INSERT OR UPDATE ON public.vendor_item_mappings
  FOR EACH ROW EXECUTE FUNCTION public.touch_vendor_item_mapping_status();

DROP TRIGGER IF EXISTS trg_vendor_item_mapping_status_delete ON public.vendor_item_mappings;
CREATE TRIGGER trg_vendor_item_mapping_status_delete
  AFTER DELETE ON public.vendor_item_mappings
  FOR EACH ROW EXECUTE FUNCTION public.touch_vendor_item_mapping_status();

COMMIT;

-- ==========================================================================
-- Source: 099_bill_pay_status_hardening.sql
-- ==========================================================================

-- 099: Bill Pay status hardening
-- Makes scheduled and partial payment states first-class so AP workflows do not fail on constraints.

BEGIN;

-- Clean up any invalid statuses before applying the constraint
UPDATE public.invoices 
SET status = 'pending_review' 
WHERE status IS NOT NULL AND status NOT IN (
  'pending_review',
  'validated',
  'pending_approval',
  'approved',
  'scheduled',
  'partially_paid',
  'paid',
  'rejected',
  'duplicate',
  'flagged'
);

ALTER TABLE public.invoices DROP CONSTRAINT IF EXISTS invoices_status_check;
ALTER TABLE public.invoices
  ADD CONSTRAINT invoices_status_check CHECK (
    status IS NULL OR status IN (
      'pending_review',
      'validated',
      'pending_approval',
      'approved',
      'scheduled',
      'partially_paid',
      'paid',
      'rejected',
      'duplicate',
      'flagged'
    )
  );

-- Clean up any invalid payment statuses before applying the constraint
UPDATE public.invoices 
SET payment_status = 'unpaid' 
WHERE payment_status IS NOT NULL AND payment_status NOT IN (
  'unpaid',
  'partial',
  'pending',
  'paid',
  'auto_pay'
);

ALTER TABLE public.invoices DROP CONSTRAINT IF EXISTS invoices_payment_status_check;
ALTER TABLE public.invoices
  ADD CONSTRAINT invoices_payment_status_check CHECK (
    payment_status IS NULL OR payment_status IN (
      'unpaid',
      'partial',
      'pending',
      'paid',
      'auto_pay'
    )
  );

ALTER TABLE public.payments DROP CONSTRAINT IF EXISTS payments_status_check;
ALTER TABLE public.payments
  ADD CONSTRAINT payments_status_check CHECK (
    status IS NULL OR status IN (
      'pending',
      'processing',
      'completed',
      'failed',
      'cancelled',
      'refunded'
    )
  );

CREATE INDEX IF NOT EXISTS idx_invoices_bill_pay_queue
  ON public.invoices(organization_id, status, payment_status, due_date);

CREATE INDEX IF NOT EXISTS idx_invoices_scheduled_payment
  ON public.invoices(organization_id, scheduled_payment_date)
  WHERE scheduled_payment_date IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_payments_payment_account
  ON public.payments(organization_id, payment_account_id, payment_date);

COMMIT;

-- ==========================================================================
-- Source: 100_scheduled_payments.sql
-- ==========================================================================

-- 100: Scheduled Payments
-- Supports the AP Bill Pay workflow by grouping invoices into batches.

BEGIN;

CREATE TABLE IF NOT EXISTS public.scheduled_payments (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
    vendor_id UUID NOT NULL REFERENCES public.vendors(id),
    payment_account_id UUID REFERENCES public.payment_accounts(id),
    total_amount NUMERIC(12,2) NOT NULL DEFAULT 0,
    scheduled_date DATE NOT NULL,
    status TEXT NOT NULL DEFAULT 'scheduled' CHECK (status IN ('draft', 'scheduled', 'processing', 'paid', 'failed', 'canceled')),
    payment_method TEXT DEFAULT 'ach', -- 'ach', 'check', 'virtual_card', 'manual'
    external_transfer_id TEXT, -- For Stripe Treasury/Modern Treasury mapping
    created_by UUID REFERENCES auth.users(id),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- RLS
ALTER TABLE public.scheduled_payments ENABLE ROW LEVEL SECURITY;

CREATE POLICY "View scheduled payments"
    ON public.scheduled_payments FOR SELECT
    USING (organization_id = public.get_my_org() OR public.is_platform_admin());

CREATE POLICY "Manage scheduled payments"
    ON public.scheduled_payments FOR ALL
    USING (organization_id = public.get_my_org() OR public.is_platform_admin());

-- Link invoices to a scheduled payment via an intersection table (so one payment can cover multiple invoices, or partial)
CREATE TABLE IF NOT EXISTS public.scheduled_payment_invoices (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    scheduled_payment_id UUID NOT NULL REFERENCES public.scheduled_payments(id) ON DELETE CASCADE,
    invoice_id UUID NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,
    amount_applied NUMERIC(12,2) NOT NULL, -- allows partial payments
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    UNIQUE(scheduled_payment_id, invoice_id)
);

-- RLS for intersection
ALTER TABLE public.scheduled_payment_invoices ENABLE ROW LEVEL SECURITY;

CREATE POLICY "View scheduled payment invoices"
    ON public.scheduled_payment_invoices FOR SELECT
    USING (
        EXISTS (
            SELECT 1 FROM public.scheduled_payments sp
            WHERE sp.id = scheduled_payment_id
            AND (sp.organization_id = public.get_my_org() OR public.is_platform_admin())
        )
    );

CREATE POLICY "Manage scheduled payment invoices"
    ON public.scheduled_payment_invoices FOR ALL
    USING (
        EXISTS (
            SELECT 1 FROM public.scheduled_payments sp
            WHERE sp.id = scheduled_payment_id
            AND (sp.organization_id = public.get_my_org() OR public.is_platform_admin())
        )
    );

-- Trigger to update updated_at
CREATE TRIGGER update_scheduled_payments_modtime
    BEFORE UPDATE ON public.scheduled_payments
    FOR EACH ROW EXECUTE FUNCTION public.update_modified_column();

-- RPC for bulk scheduling
CREATE OR REPLACE FUNCTION public.schedule_payment_batch(
    p_vendor_id UUID,
    p_payment_account_id UUID,
    p_scheduled_date DATE,
    p_invoice_ids UUID[],
    p_amounts NUMERIC[]
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_scheduled_payment_id UUID;
    v_total NUMERIC := 0;
    i INT;
BEGIN
    -- Calculate total
    FOR i IN 1 .. array_length(p_amounts, 1) LOOP
        v_total := v_total + p_amounts[i];
    END LOOP;

    -- Create scheduled payment record
    INSERT INTO public.scheduled_payments (
        organization_id,
        vendor_id,
        payment_account_id,
        total_amount,
        scheduled_date,
        status,
        created_by
    ) VALUES (
        public.get_my_org(),
        p_vendor_id,
        p_payment_account_id,
        v_total,
        p_scheduled_date,
        'scheduled',
        auth.uid()
    ) RETURNING id INTO v_scheduled_payment_id;

    -- Insert intersection records
    FOR i IN 1 .. array_length(p_invoice_ids, 1) LOOP
        INSERT INTO public.scheduled_payment_invoices (
            scheduled_payment_id,
            invoice_id,
            amount_applied
        ) VALUES (
            v_scheduled_payment_id,
            p_invoice_ids[i],
            p_amounts[i]
        );
        
        -- Update invoice status
        UPDATE public.invoices 
        SET scheduled_payment_date = p_scheduled_date,
            status = 'scheduled'
        WHERE id = p_invoice_ids[i];
    END LOOP;

    RETURN v_scheduled_payment_id;
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 101_vendor_statements.sql
-- ==========================================================================

-- 101: Vendor Statements Reconciliation
-- Supports uploading vendor statements and auto-matching them to invoices.

BEGIN;

CREATE TABLE IF NOT EXISTS public.vendor_statements (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
    vendor_id UUID NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
    statement_date DATE NOT NULL,
    total_amount NUMERIC(12,2) NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'needs_review' CHECK (status IN ('matched', 'needs_review', 'disputed')),
    file_url TEXT,
    created_by UUID REFERENCES auth.users(id),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- RLS
ALTER TABLE public.vendor_statements ENABLE ROW LEVEL SECURITY;

CREATE POLICY "View vendor statements"
    ON public.vendor_statements FOR SELECT
    USING (organization_id = public.get_my_org() OR public.is_platform_admin());

CREATE POLICY "Manage vendor statements"
    ON public.vendor_statements FOR ALL
    USING (organization_id = public.get_my_org() OR public.is_platform_admin());

-- Statement Lines Table (links statement line to an internal invoice)
CREATE TABLE IF NOT EXISTS public.vendor_statement_lines (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    statement_id UUID NOT NULL REFERENCES public.vendor_statements(id) ON DELETE CASCADE,
    invoice_number TEXT NOT NULL,
    invoice_date DATE,
    amount NUMERIC(12,2) NOT NULL,
    status TEXT NOT NULL DEFAULT 'unmatched' CHECK (status IN ('matched', 'unmatched', 'disputed', 'missing_credit')),
    matched_invoice_id UUID REFERENCES public.invoices(id) ON DELETE SET NULL,
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- RLS
ALTER TABLE public.vendor_statement_lines ENABLE ROW LEVEL SECURITY;

CREATE POLICY "View vendor statement lines"
    ON public.vendor_statement_lines FOR SELECT
    USING (
        EXISTS (
            SELECT 1 FROM public.vendor_statements vs
            WHERE vs.id = statement_id
            AND (vs.organization_id = public.get_my_org() OR public.is_platform_admin())
        )
    );

CREATE POLICY "Manage vendor statement lines"
    ON public.vendor_statement_lines FOR ALL
    USING (
        EXISTS (
            SELECT 1 FROM public.vendor_statements vs
            WHERE vs.id = statement_id
            AND (vs.organization_id = public.get_my_org() OR public.is_platform_admin())
        )
    );

-- Trigger to update updated_at
CREATE TRIGGER update_vendor_statements_modtime
    BEFORE UPDATE ON public.vendor_statements
    FOR EACH ROW EXECUTE FUNCTION public.update_modified_column();

-- RPC for auto-matching statement lines to invoices
CREATE OR REPLACE FUNCTION public.auto_match_statement_lines(p_statement_id UUID)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_vendor_id UUID;
    v_org_id UUID;
    v_matched_count INTEGER := 0;
    v_line RECORD;
    v_invoice_id UUID;
BEGIN
    SELECT vendor_id, organization_id INTO v_vendor_id, v_org_id 
    FROM public.vendor_statements WHERE id = p_statement_id;

    FOR v_line IN SELECT * FROM public.vendor_statement_lines WHERE statement_id = p_statement_id AND status = 'unmatched' LOOP
        -- Try to find an exact match on invoice_number and amount and vendor
        SELECT id INTO v_invoice_id
        FROM public.invoices
        WHERE organization_id = v_org_id 
          AND vendor_id = v_vendor_id
          AND invoice_number = v_line.invoice_number
          AND total_amount = v_line.amount
        LIMIT 1;

        IF v_invoice_id IS NOT NULL THEN
            UPDATE public.vendor_statement_lines
            SET status = 'matched', matched_invoice_id = v_invoice_id
            WHERE id = v_line.id;
            
            v_matched_count := v_matched_count + 1;
        END IF;
    END LOOP;

    -- Update parent statement status if all lines are matched
    IF NOT EXISTS (SELECT 1 FROM public.vendor_statement_lines WHERE statement_id = p_statement_id AND status != 'matched') THEN
        UPDATE public.vendor_statements SET status = 'matched' WHERE id = p_statement_id;
    ELSE
        UPDATE public.vendor_statements SET status = 'needs_review' WHERE id = p_statement_id;
    END IF;

    RETURN v_matched_count;
END;
$$;

COMMIT;

