-- Rename id column in brands table to brand_id
ALTER TABLE public.brands RENAME COLUMN id TO brand_id;

-- ==========================================================================
-- Source: 115_resolve_advisor_lints.sql
-- ==========================================================================

-- Phase 4 Migration: Resolve remaining Advisor lints

-- 1. Security: Move fuzzystrmatch to extensions schema
CREATE SCHEMA IF NOT EXISTS extensions;
ALTER EXTENSION fuzzystrmatch SET SCHEMA extensions;

-- 2. Security: Revoke API access to mv_daily_sales_summary
REVOKE ALL ON public.mv_daily_sales_summary FROM anon, authenticated;

-- 3. Security: Fix permissive RLS policies on audit_logs and error_logs
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'audit_logs' AND policyname = 'System can insert audit logs') THEN
        ALTER POLICY "System can insert audit logs" ON public.audit_logs WITH CHECK (auth.uid() IS NOT NULL);
    END IF;
    
    IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'audit_logs' AND policyname = 'audit_logs_authenticated_insert') THEN
        ALTER POLICY "audit_logs_authenticated_insert" ON public.audit_logs WITH CHECK (auth.uid() IS NOT NULL);
    END IF;

    IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'error_logs' AND policyname = 'error_logs_authenticated_insert') THEN
        ALTER POLICY "error_logs_authenticated_insert" ON public.error_logs WITH CHECK (auth.uid() IS NOT NULL);
    END IF;
END
$$;

-- 4. Performance: Fix auth_rls_initplan by wrapping auth.uid() and auth.role() in (select ...)
DO $$
DECLARE
    pol RECORD;
    new_qual text;
    new_with_check text;
    v_cmd text;
BEGIN
    FOR pol IN (
        SELECT policyname, tablename, roles, pg_policies.cmd as pcmd, qual, with_check 
        FROM pg_policies 
        WHERE schemaname = 'public' 
          AND (qual ILIKE '%auth.uid()%' OR qual ILIKE '%auth.role()%' OR with_check ILIKE '%auth.uid()%' OR with_check ILIKE '%auth.role()%')
    ) LOOP
        new_qual := pol.qual;
        IF new_qual IS NOT NULL THEN
            -- unwrap first to prevent double-wrapping
            new_qual := regexp_replace(new_qual, '\(\s*select\s+auth\.uid\(\)\s*(?:as\s+\w+)?\s*\)', 'auth.uid()', 'ig');
            new_qual := regexp_replace(new_qual, '\(\s*select\s+auth\.role\(\)\s*(?:as\s+\w+)?\s*\)', 'auth.role()', 'ig');
            
            -- wrap
            new_qual := regexp_replace(new_qual, 'auth\.uid\(\)', '(select auth.uid())', 'ig');
            new_qual := regexp_replace(new_qual, 'auth\.role\(\)', '(select auth.role())', 'ig');
        END IF;

        new_with_check := pol.with_check;
        IF new_with_check IS NOT NULL THEN
            new_with_check := regexp_replace(new_with_check, '\(\s*select\s+auth\.uid\(\)\s*(?:as\s+\w+)?\s*\)', 'auth.uid()', 'ig');
            new_with_check := regexp_replace(new_with_check, '\(\s*select\s+auth\.role\(\)\s*(?:as\s+\w+)?\s*\)', 'auth.role()', 'ig');
            
            new_with_check := regexp_replace(new_with_check, 'auth\.uid\(\)', '(select auth.uid())', 'ig');
            new_with_check := regexp_replace(new_with_check, 'auth\.role\(\)', '(select auth.role())', 'ig');
        END IF;
        
        v_cmd := format('ALTER POLICY %I ON public.%I ', pol.policyname, pol.tablename);
        
        IF new_qual IS NOT NULL THEN
            v_cmd := v_cmd || format(' USING (%s) ', new_qual);
        END IF;
        
        IF new_with_check IS NOT NULL THEN
            v_cmd := v_cmd || format(' WITH CHECK (%s) ', new_with_check);
        END IF;

        -- only execute if changes were made to avoid unnecessary updates
        IF (new_qual IS DISTINCT FROM pol.qual) OR (new_with_check IS DISTINCT FROM pol.with_check) THEN
            EXECUTE v_cmd;
        END IF;
    END LOOP;
END
$$;

-- ==========================================================================
-- Source: 116_table_partitioning.sql
-- ==========================================================================

-- Phase 5 Track A: High-Volume Data Partitioning

-- 1. Rename existing tables to safely archive them and free up the names
ALTER TABLE public.audit_logs RENAME TO audit_logs_old;
ALTER TABLE public.error_logs RENAME TO error_logs_old;

-- Rename indexes so we can reuse the names for the new partitioned tables
ALTER INDEX IF EXISTS idx_audit_logs_module RENAME TO idx_audit_logs_module_old;
ALTER INDEX IF EXISTS idx_audit_logs_user_id RENAME TO idx_audit_logs_user_id_old;
ALTER INDEX IF EXISTS idx_audit_logs_organization_id RENAME TO idx_audit_logs_organization_id_old;

ALTER INDEX IF EXISTS idx_error_logs_created_at RENAME TO idx_error_logs_created_at_old;
ALTER INDEX IF EXISTS idx_error_logs_severity RENAME TO idx_error_logs_severity_old;
ALTER INDEX IF EXISTS idx_error_logs_user_id RENAME TO idx_error_logs_user_id_old;

-- 2. Create the partitioned `audit_logs` table
CREATE TABLE public.audit_logs (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    organization_id uuid,
    user_id uuid,
    action text NOT NULL,
    table_name text NOT NULL,
    record_id uuid,
    old_data jsonb,
    new_data jsonb,
    ip_address text,
    user_agent text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    entity_type text,
    entity_id text,
    module text,
    field_changed text,
    old_value text,
    new_value text,
    user_email text,
    details text,
    org_id uuid,
    PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);

-- Create partitions for audit_logs
CREATE TABLE public.audit_logs_y2025 PARTITION OF public.audit_logs
    FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');

CREATE TABLE public.audit_logs_y2026 PARTITION OF public.audit_logs
    FOR VALUES FROM ('2026-01-01') TO ('2027-01-01');

CREATE TABLE public.audit_logs_default PARTITION OF public.audit_logs DEFAULT;

-- Recreate indexes on audit_logs (PostgreSQL 11+ automatically cascades these to partitions)
CREATE INDEX idx_audit_logs_module ON public.audit_logs USING btree (module);
CREATE INDEX idx_audit_logs_user_id ON public.audit_logs USING btree (user_id);
CREATE INDEX idx_audit_logs_organization_id ON public.audit_logs USING btree (organization_id);

-- Enable RLS and recreate policies for audit_logs
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;

CREATE POLICY "System can insert audit logs" ON public.audit_logs
    FOR INSERT TO public WITH CHECK (auth.uid() IS NOT NULL);

CREATE POLICY "audit_logs_authenticated_insert" ON public.audit_logs
    FOR INSERT TO authenticated WITH CHECK (auth.uid() IS NOT NULL);

CREATE POLICY "Platform admins can view all audit logs" ON public.audit_logs
    FOR SELECT USING (
        EXISTS ( SELECT 1 FROM profiles WHERE profiles.id = (select auth.uid()) AND profiles.role = 'platform_admin'::text )
    );

-- 3. Create the partitioned `error_logs` table
CREATE TABLE public.error_logs (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    message text NOT NULL,
    stack text,
    component_stack text,
    route text,
    user_id uuid,
    severity text DEFAULT 'error',
    metadata jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);

-- Create partitions for error_logs
CREATE TABLE public.error_logs_y2025 PARTITION OF public.error_logs
    FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');

CREATE TABLE public.error_logs_y2026 PARTITION OF public.error_logs
    FOR VALUES FROM ('2026-01-01') TO ('2027-01-01');

CREATE TABLE public.error_logs_default PARTITION OF public.error_logs DEFAULT;

-- Recreate indexes on error_logs
CREATE INDEX idx_error_logs_created_at ON public.error_logs USING btree (created_at DESC);
CREATE INDEX idx_error_logs_severity ON public.error_logs USING btree (severity);
CREATE INDEX idx_error_logs_user_id ON public.error_logs USING btree (user_id);

-- Enable RLS and recreate policies for error_logs
ALTER TABLE public.error_logs ENABLE ROW LEVEL SECURITY;

CREATE POLICY "error_logs_authenticated_insert" ON public.error_logs
    FOR INSERT TO authenticated WITH CHECK (auth.uid() IS NOT NULL);

-- 4. Migrate existing data seamlessly into the new partitioned structures
-- Setting created_at to now() if it's null to satisfy NOT NULL constraints.
INSERT INTO public.audit_logs 
SELECT 
    id, organization_id, user_id, action, table_name, record_id, 
    old_data, new_data, ip_address, user_agent, COALESCE(created_at, now()), 
    entity_type, entity_id, module, field_changed, old_value, new_value, 
    user_email, details, organization_id 
FROM public.audit_logs_old;

INSERT INTO public.error_logs 
SELECT 
    id, message, stack, component_stack, route, user_id, 
    severity, metadata, COALESCE(created_at, now())
FROM public.error_logs_old;

-- 5. Drop the old unpartitioned tables
DROP TABLE public.audit_logs_old;
DROP TABLE public.error_logs_old;

-- ==========================================================================
-- Source: 117_fix_fetch_user_access_tree.sql
-- ==========================================================================

-- Migration 117: Fix fetch_user_access_tree RPC
-- Fixes an undefined column error (42703) after brands.id was renamed to brands.brand_id in migration 114.

BEGIN;

CREATE OR REPLACE FUNCTION public.fetch_user_access_tree()
RETURNS JSONB
LANGUAGE sql
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT jsonb_agg(
    jsonb_build_object(
      'organization', row_to_json(o.*),
      'role', om.role,
      'brands', (
        SELECT jsonb_agg(
          jsonb_build_object(
            'brand', row_to_json(b.*),
            'role', bm.role,
            'locations', (
              SELECT jsonb_agg(
                jsonb_build_object(
                  'location', row_to_json(l.*),
                  'role', lm.role
                )
              )
              FROM public.location_members lm
              JOIN public.locations l ON l.id = lm.location_id
              WHERE lm.user_id = auth.uid() AND l.brand_id = b.brand_id
            )
          )
        )
        FROM public.brand_members bm
        JOIN public.brands b ON b.brand_id = bm.brand_id
        WHERE bm.user_id = auth.uid() AND b.organization_id = o.id
      )
    )
  )
  FROM public.organization_members om
  JOIN public.organizations o ON o.id = om.organization_id
  WHERE om.user_id = auth.uid();
$$;

-- Force PostgREST to reload the schema cache so the frontend can immediately use the updated RPC
NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 118_live_schema_repair_and_security.sql
-- ==========================================================================

-- Migration 118: Live schema repair and security hardening
-- Repairs functions that drifted from the live schema and removes unsafe auth fallbacks.

BEGIN;

-- Keep useful audit attribution columns rather than silently dropping values in RPCs.
ALTER TABLE public.invitations
  ADD COLUMN IF NOT EXISTS accepted_by UUID REFERENCES auth.users(id) ON DELETE SET NULL;

ALTER TABLE public.payments
  ADD COLUMN IF NOT EXISTS created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_invitations_accepted_by ON public.invitations(accepted_by);
CREATE INDEX IF NOT EXISTS idx_payments_created_by ON public.payments(created_by);

-- Auth helpers must not trust user_metadata. app_metadata is server-controlled.
CREATE OR REPLACE FUNCTION public.get_auth_org()
RETURNS UUID
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT NULLIF(auth.jwt() -> 'app_metadata' ->> 'organization_id', '')::uuid;
$$;

CREATE OR REPLACE FUNCTION public.get_auth_role()
RETURNS TEXT
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT COALESCE(NULLIF(auth.jwt() -> 'app_metadata' ->> 'role', ''), 'ground_staff');
$$;

-- Revoke direct access to query text/statistics from normal authenticated users.
REVOKE ALL ON public.vw_slow_queries FROM anon, authenticated, public;

-- brands uses brand_id in the live schema.
CREATE OR REPLACE FUNCTION public.setup_organization_full(
  p_user_id UUID,
  p_org_name TEXT,
  p_org_slug TEXT,
  p_brand_name TEXT,
  p_location_name TEXT,
  p_location_address TEXT DEFAULT ''
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  INSERT INTO public.organizations (name, slug, owner_id)
  VALUES (p_org_name, p_org_slug, p_user_id)
  RETURNING id INTO v_org_id;

  INSERT INTO public.brands (organization_id, name)
  VALUES (v_org_id, p_brand_name)
  RETURNING brand_id INTO v_brand_id;

  INSERT INTO public.locations (organization_id, brand_id, name, address)
  VALUES (v_org_id, v_brand_id, p_location_name, p_location_address)
  RETURNING id INTO v_location_id;

  INSERT INTO public.organization_members (organization_id, user_id, role)
  VALUES (v_org_id, p_user_id, 'org_owner')
  ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  INSERT INTO public.brand_members (brand_id, user_id, role)
  VALUES (v_brand_id, p_user_id, 'org_owner')
  ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  INSERT INTO public.location_members (location_id, user_id, role)
  VALUES (v_location_id, p_user_id, 'org_owner')
  ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.profiles
  SET organization_id = v_org_id,
      brand_id        = v_brand_id,
      location_id     = v_location_id,
      role            = 'org_owner',
      access_level    = 'organization',
      updated_at      = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'org_owner',
    'organization_id', v_org_id::text,
    'brand_id', v_brand_id::text,
    'location_id', v_location_id::text
  )
  WHERE id = p_user_id;

  RETURN jsonb_build_object(
    'org_id',      v_org_id,
    'brand_id',    v_brand_id,
    'location_id', v_location_id
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.accept_invitation(p_token TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invite RECORD;
  v_user_id UUID;
  v_user_email TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND LOWER(email) = LOWER(v_user_email);

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  INSERT INTO public.organization_members (organization_id, user_id, role)
  VALUES (v_invite.organization_id, v_user_id, v_invite.role)
  ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  IF v_invite.brand_id IS NOT NULL THEN
    INSERT INTO public.brand_members (brand_id, user_id, role)
    VALUES (v_invite.brand_id, v_user_id, v_invite.role)
    ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.location_id IS NOT NULL THEN
    INSERT INTO public.location_members (location_id, user_id, role)
    VALUES (v_invite.location_id, v_user_id, v_invite.role)
    ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  UPDATE public.profiles
  SET role            = v_invite.role,
      organization_id = v_invite.organization_id,
      brand_id        = COALESCE(v_invite.brand_id, brand_id),
      location_id     = COALESCE(v_invite.location_id, location_id),
      access_level    = COALESCE(v_invite.access_level, access_level),
      updated_at      = now()
  WHERE id = v_user_id;

  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id
  WHERE id = v_invite.id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', v_invite.role,
    'organization_id', v_invite.organization_id::text,
    'brand_id', COALESCE(v_invite.brand_id::text, ''),
    'location_id', COALESCE(v_invite.location_id::text, '')
  )
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success',         true,
    'role',            v_invite.role,
    'organization_id', v_invite.organization_id,
    'brand_id',        v_invite.brand_id,
    'location_id',     v_invite.location_id
  );
END;
$$;

-- invoice_line_items uses internal_product_id and total_price in the live schema.
CREATE OR REPLACE FUNCTION public.calculate_invoice_allocations(p_invoice_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
  v_tax NUMERIC;
  v_fuel NUMERIC;
  v_delivery NUMERIC;
  v_other NUMERIC;
  v_cat_record RECORD;
BEGIN
  SELECT organization_id,
         COALESCE(tax_amount, 0),
         COALESCE(fuel_surcharge, 0),
         COALESCE(delivery_fee, 0),
         COALESCE(other_charges, 0)
  INTO v_org_id, v_tax, v_fuel, v_delivery, v_other
  FROM public.invoices
  WHERE id = p_invoice_id;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  DELETE FROM public.invoice_allocations WHERE invoice_id = p_invoice_id;

  FOR v_cat_record IN (
    SELECT
      COALESCE(p.category, 'uncategorized') AS cat_name,
      SUM(COALESCE(ili.total_price, ili.quantity * ili.unit_price, 0)) AS total_amount
    FROM public.invoice_line_items ili
    LEFT JOIN public.products p ON ili.internal_product_id = p.id
    WHERE ili.invoice_id = p_invoice_id
    GROUP BY COALESCE(p.category, 'uncategorized')
  ) LOOP
    IF COALESCE(v_cat_record.total_amount, 0) > 0 THEN
      INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, gl_code, amount)
      SELECT
        v_org_id,
        p_invoice_id,
        'line_items',
        v_cat_record.cat_name,
        (SELECT gl_code FROM public.gl_mappings WHERE organization_id = v_org_id AND LOWER(category) = LOWER(v_cat_record.cat_name) LIMIT 1),
        v_cat_record.total_amount;
    END IF;
  END LOOP;

  IF v_tax > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'tax', 'Tax', v_tax);
  END IF;

  IF v_delivery > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'delivery', 'Delivery Fee', v_delivery);
  END IF;

  IF v_fuel > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'fuel', 'Fuel Surcharge', v_fuel);
  END IF;

  IF v_other > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'other', 'Other Charges', v_other);
  END IF;

  RETURN jsonb_build_object('success', true, 'message', 'Allocations calculated');
END;
$$;

CREATE OR REPLACE FUNCTION public.record_invoice_payment(
  p_invoice_id UUID,
  p_amount NUMERIC,
  p_reference TEXT,
  p_payment_method TEXT DEFAULT 'manual'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_new_paid_amount NUMERIC;
  v_new_status TEXT;
  v_payment_id UUID;
BEGIN
  SELECT * INTO v_invoice FROM public.invoices WHERE id = p_invoice_id FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  v_new_paid_amount := COALESCE(v_invoice.paid_amount, 0) + COALESCE(p_amount, 0);
  v_new_status := CASE WHEN v_new_paid_amount >= COALESCE(v_invoice.total_amount, 0) THEN 'paid' ELSE 'partially_paid' END;

  UPDATE public.invoices
  SET paid_amount = v_new_paid_amount,
      payment_status = CASE WHEN v_new_status = 'paid' THEN 'paid' ELSE 'partial' END,
      status = v_new_status,
      ap_status = CASE WHEN v_new_status = 'paid' THEN 'paid' ELSE ap_status END,
      payment_reference = p_reference,
      updated_at = now()
  WHERE id = p_invoice_id;

  INSERT INTO public.payments (
    invoice_id, vendor_id, vendor_name, invoice_number,
    amount, payment_method, status, transaction_id, payment_date,
    payment_account_id, organization_id, brand_id, location_id, created_by
  )
  VALUES (
    v_invoice.id, v_invoice.vendor_id, v_invoice.vendor_name, v_invoice.invoice_number,
    p_amount, p_payment_method, 'completed', p_reference, CURRENT_DATE,
    v_invoice.payment_account_id, v_invoice.organization_id, v_invoice.brand_id, v_invoice.location_id, auth.uid()
  )
  RETURNING id INTO v_payment_id;

  RETURN jsonb_build_object(
    'status', v_new_status,
    'paid_amount', v_new_paid_amount,
    'payment_id', v_payment_id
  );
END;
$$;

-- recipe_ingredients does not store name; join products for display names.
CREATE OR REPLACE FUNCTION public.calculate_theoretical_depletion(
  p_org_id UUID,
  p_sales_json JSONB
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_result JSONB;
BEGIN
  IF NOT public.is_platform_admin() AND p_org_id != public.get_auth_org() THEN
    RAISE EXCEPTION 'Access Denied: Tenant context violation.';
  END IF;

  WITH sales AS (
    SELECT
      (elem->>'name')::TEXT AS sale_name,
      COALESCE((elem->>'qty')::NUMERIC, 0) AS sale_qty
    FROM jsonb_array_elements(p_sales_json) elem
  ),
  matched_recipes AS (
    SELECT
      s.sale_qty,
      r.id AS recipe_id
    FROM sales s
    JOIN public.recipes r ON lower(trim(r.name)) = lower(trim(s.sale_name))
    WHERE r.organization_id = p_org_id
  ),
  depletions AS (
    SELECT
      ri.product_id,
      COALESCE(p.name, ri.product_id::text) AS product_name,
      SUM(ri.quantity * mr.sale_qty) AS total_used,
      MAX(ri.unit) AS unit
    FROM matched_recipes mr
    JOIN public.recipe_ingredients ri ON ri.recipe_id = mr.recipe_id
    LEFT JOIN public.products p ON p.id = ri.product_id
    WHERE ri.organization_id = p_org_id
    GROUP BY ri.product_id, COALESCE(p.name, ri.product_id::text)
  )
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'product_id', d.product_id,
      'product_name', d.product_name,
      'total_used', d.total_used,
      'unit', d.unit
    ) ORDER BY d.total_used DESC
  ), '[]'::jsonb)
  INTO v_result
  FROM depletions d;

  RETURN v_result;
END;
$$;

-- POS data exposes revenue and quantity_sold, not total_sales/actual_cost.
CREATE OR REPLACE FUNCTION public.get_cross_location_benchmarks(p_org_id UUID)
RETURNS TABLE (
    name TEXT,
    sales NUMERIC,
    "laborCost" NUMERIC,
    cogs NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
    IF NOT public.is_platform_admin() AND public.get_my_org() != p_org_id THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this organization data.';
    END IF;

    RETURN QUERY
    WITH date_range AS (
        SELECT (now() - interval '30 days') AS start_date
    ),
    sales_by_location AS (
        SELECT ps.location_id, COALESCE(SUM(ps.revenue), 0) AS sales
        FROM public.pos_sales_data ps
        WHERE ps.date >= (SELECT start_date FROM date_range)
        GROUP BY ps.location_id
    ),
    cogs_by_location AS (
        SELECT i.location_id, COALESCE(SUM(i.total_amount), 0) AS cogs
        FROM public.invoices i
        WHERE COALESCE(i.invoice_date, i.created_at::date) >= (SELECT start_date::date FROM date_range)
        GROUP BY i.location_id
    ),
    location_sales AS (
        SELECT
            l.id AS location_id,
            l.name AS location_name,
            COALESCE(s.sales, 0) AS sales,
            COALESCE(c.cogs, 0) AS cogs
        FROM public.locations l
        LEFT JOIN sales_by_location s ON l.id = s.location_id
        LEFT JOIN cogs_by_location c ON l.id = c.location_id
        WHERE l.organization_id = p_org_id
        GROUP BY l.id, l.name, s.sales, c.cogs
    ),
    location_labor AS (
        SELECT
            l.id AS location_id,
            COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 0) AS labor_cost
        FROM public.locations l
        LEFT JOIN public.employees e ON l.id = e.location_id
        LEFT JOIN public.employee_shifts es
            ON e.id = es.employee_id
            AND es.start_time >= (SELECT start_date FROM date_range)
        WHERE l.organization_id = p_org_id
        GROUP BY l.id
    )
    SELECT
        ls.location_name AS name,
        ROUND(ls.sales, 2) AS sales,
        ROUND(ll.labor_cost::NUMERIC, 2) AS "laborCost",
        ROUND(ls.cogs, 2) AS cogs
    FROM location_sales ls
    JOIN location_labor ll ON ls.location_id = ll.location_id
    ORDER BY ls.sales DESC;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_labor_forecast(p_location_id UUID)
RETURNS TABLE (
    date TEXT,
    "salesForecast" NUMERIC,
    "scheduledLabor" NUMERIC,
    "suggestedLabor" NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    avg_daily_sales NUMERIC;
BEGIN
    IF NOT public.is_platform_admin()
       AND public.get_my_org() != (SELECT organization_id FROM public.locations WHERE id = p_location_id) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this location data.';
    END IF;

    SELECT COALESCE(AVG(revenue), 3000) INTO avg_daily_sales
    FROM public.pos_sales_data
    WHERE location_id = p_location_id AND date >= (now() - interval '30 days');

    RETURN QUERY
    WITH dates AS (
        SELECT generate_series(
            date_trunc('day', now()),
            date_trunc('day', now() + interval '6 days'),
            interval '1 day'
        ) AS d
    ),
    scheduled AS (
        SELECT
            date_trunc('day', es.start_time) AS shift_date,
            COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 0) AS labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id = p_location_id
        GROUP BY date_trunc('day', es.start_time)
    )
    SELECT
        to_char(d.d, 'Mon DD') AS date,
        ROUND(avg_daily_sales * (1 + (random() * 0.4 - 0.2))::NUMERIC, 2) AS "salesForecast",
        ROUND(COALESCE(s.labor_cost::NUMERIC, 0), 2) AS "scheduledLabor",
        ROUND(avg_daily_sales * 0.28, 2) AS "suggestedLabor"
    FROM dates d
    LEFT JOIN scheduled s ON d.d = s.shift_date
    ORDER BY d.d ASC;
END;
$$;

CREATE OR REPLACE FUNCTION public.ai_chat_response(p_org_id UUID, p_query TEXT)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_lower_query TEXT := lower(p_query);
    v_sales_yesterday NUMERIC;
    v_forecast_tomorrow NUMERIC;
    v_labor_cost NUMERIC;
    v_pending_invoices INT;
    v_variance NUMERIC;
BEGIN
    IF NOT public.is_platform_admin() AND public.get_my_org() != p_org_id THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this organization data.';
    END IF;

    IF v_lower_query LIKE '%variance%' OR v_lower_query LIKE '%food cost%' THEN
        WITH invoice_spend AS (
            SELECT COALESCE(SUM(i.total_amount), 0) AS amount
            FROM public.invoices i
            WHERE i.location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
              AND COALESCE(i.invoice_date, i.created_at::date) >= (now() - interval '7 days')::date
        ),
        sales AS (
            SELECT COALESCE(SUM(ps.revenue), 0) AS amount
            FROM public.pos_sales_data ps
            WHERE ps.location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
              AND ps.date >= (now() - interval '7 days')::date
        )
        SELECT invoice_spend.amount - (sales.amount * 0.30)
        INTO v_variance
        FROM invoice_spend, sales;

        RETURN 'Based on available invoice and POS data, estimated food cost variance over the last 7 days is $' || round(v_variance, 2) || '.';

    ELSIF v_lower_query LIKE '%labor%' OR v_lower_query LIKE '%schedule%' OR v_lower_query LIKE '%staff%' THEN
        SELECT COALESCE(AVG(revenue), 5200.00) INTO v_forecast_tomorrow
        FROM public.pos_sales_data
        WHERE location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id);

        SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 1600.00)
        INTO v_labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
          AND date_trunc('day', es.start_time) = date_trunc('day', now() + interval '1 day');

        RETURN 'Tomorrow forecast predicts $' || round(v_forecast_tomorrow, 2) || ' in sales. Current scheduled labor is $' || round(v_labor_cost, 2) || ' (' || round((v_labor_cost / NULLIF(v_forecast_tomorrow, 0)) * 100, 1) || '%).';

    ELSIF v_lower_query LIKE '%brief%' OR v_lower_query LIKE '%yesterday%' OR v_lower_query LIKE '%summary%' THEN
        SELECT COUNT(*) INTO v_pending_invoices
        FROM public.invoices
        WHERE location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
          AND status = 'pending_review';

        SELECT COALESCE(SUM(revenue), 0) INTO v_sales_yesterday
        FROM public.pos_sales_data
        WHERE location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
          AND date_trunc('day', date) = date_trunc('day', now() - interval '1 day');

        RETURN 'Yesterday briefing: sales were $' || round(v_sales_yesterday, 2) || '. There are ' || v_pending_invoices || ' invoices pending review.';

    ELSE
        RETURN 'I am analyzing your organization data. Try asking about food cost variance, labor schedule, or yesterday briefing.';
    END IF;
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 119_fix_labor_forecast_date_ambiguity.sql
-- ==========================================================================

-- Migration 119: Fix get_labor_forecast date ambiguity

CREATE OR REPLACE FUNCTION public.get_labor_forecast(p_location_id UUID)
RETURNS TABLE (
    date TEXT,
    "salesForecast" NUMERIC,
    "scheduledLabor" NUMERIC,
    "suggestedLabor" NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    avg_daily_sales NUMERIC;
BEGIN
    IF NOT public.is_platform_admin()
       AND public.get_my_org() != (SELECT l.organization_id FROM public.locations l WHERE l.id = p_location_id) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this location data.';
    END IF;

    SELECT COALESCE(AVG(ps.revenue), 3000)
    INTO avg_daily_sales
    FROM public.pos_sales_data ps
    WHERE ps.location_id = p_location_id
      AND ps.date >= (now() - interval '30 days');

    RETURN QUERY
    WITH forecast_dates AS (
        SELECT generate_series(
            date_trunc('day', now()),
            date_trunc('day', now() + interval '6 days'),
            interval '1 day'
        ) AS forecast_day
    ),
    scheduled AS (
        SELECT
            date_trunc('day', es.start_time) AS shift_date,
            COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 0) AS labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id = p_location_id
        GROUP BY date_trunc('day', es.start_time)
    )
    SELECT
        to_char(fd.forecast_day, 'Mon DD') AS date,
        ROUND(avg_daily_sales * (1 + (random() * 0.4 - 0.2))::NUMERIC, 2) AS "salesForecast",
        ROUND(COALESCE(s.labor_cost::NUMERIC, 0), 2) AS "scheduledLabor",
        ROUND(avg_daily_sales * 0.28, 2) AS "suggestedLabor"
    FROM forecast_dates fd
    LEFT JOIN scheduled s ON fd.forecast_day = s.shift_date
    ORDER BY fd.forecast_day ASC;
END;
$$;

-- ==========================================================================
-- Source: 120_native_workflow_triggers.sql
-- ==========================================================================

-- Migration 120: Native Workflow Triggers via pg_net
-- Replaces Inngest by wiring database events directly to Supabase Edge Functions.

BEGIN;

CREATE EXTENSION IF NOT EXISTS pg_net;

-- 1. Create a generic trigger function that dispatches events to Edge Functions
CREATE OR REPLACE FUNCTION public.invoke_edge_function()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  function_name TEXT := TG_ARGV[0];
  v_url TEXT;
  v_service_role_key TEXT;
  v_headers JSONB;
  v_payload JSONB;
BEGIN
  -- Construct the Edge Function URL. 
  -- We default to the known production URL, but allow overrides via custom settings if needed.
  v_url := COALESCE(current_setting('app.settings.functions_url', true), 'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1') || '/' || function_name;
  v_service_role_key := current_setting('app.settings.service_role_key', true);

  IF v_service_role_key IS NULL OR length(trim(v_service_role_key)) = 0 THEN
    RAISE EXCEPTION 'app.settings.service_role_key is required for invoke_edge_function';
  END IF;
  
  v_headers := jsonb_build_object(
    'Content-Type', 'application/json',
    'Authorization', 'Bearer ' || v_service_role_key
  );

  v_payload := jsonb_build_object(
    'type', TG_OP,
    'table', TG_TABLE_NAME,
    'schema', TG_TABLE_SCHEMA,
    'record', CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN row_to_json(NEW) ELSE null END,
    'old_record', CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN row_to_json(OLD) ELSE null END
  );

  PERFORM net.http_post(
      url := v_url,
      body := v_payload,
      headers := v_headers
  );
  
  RETURN NULL; -- AFTER trigger
END;
$$;

-- 2. process-onboarding Triggers
DO $guard$
BEGIN
  IF to_regclass('public.demo_requests') IS NOT NULL THEN
    DROP TRIGGER IF EXISTS trg_demo_requests_webhook ON public.demo_requests;
    CREATE TRIGGER trg_demo_requests_webhook
      AFTER INSERT OR UPDATE ON public.demo_requests
      FOR EACH ROW EXECUTE FUNCTION public.invoke_edge_function('process-onboarding');
  END IF;
END $guard$;

DROP TRIGGER IF EXISTS trg_org_deleted_webhook ON public.organizations;
CREATE TRIGGER trg_org_deleted_webhook
  AFTER DELETE ON public.organizations
  FOR EACH ROW EXECUTE FUNCTION public.invoke_edge_function('process-onboarding');

-- 3. invoice-processing Triggers
DROP TRIGGER IF EXISTS trg_invoices_webhook ON public.invoices;
CREATE TRIGGER trg_invoices_webhook
  AFTER INSERT OR UPDATE ON public.invoices
  FOR EACH ROW EXECUTE FUNCTION public.invoke_edge_function('invoice-processing');

-- 4. billing-worker Triggers
-- Note: Requires `subscriptions` table. If it's missing, this trigger will just wait to be attached.
DO $$ 
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'subscriptions') THEN
    DROP TRIGGER IF EXISTS trg_subscriptions_webhook ON public.subscriptions;
    EXECUTE 'CREATE TRIGGER trg_subscriptions_webhook
      AFTER INSERT OR UPDATE ON public.subscriptions
      FOR EACH ROW EXECUTE FUNCTION public.invoke_edge_function(''billing-worker'')';
  END IF;
END $$;

DROP TRIGGER IF EXISTS trg_payments_webhook ON public.payments;
CREATE TRIGGER trg_payments_webhook
  AFTER UPDATE ON public.payments
  FOR EACH ROW 
  WHEN (NEW.status = 'failed' AND OLD.status IS DISTINCT FROM 'failed')
  EXECUTE FUNCTION public.invoke_edge_function('billing-worker');

-- 5. team-worker Triggers
DROP TRIGGER IF EXISTS trg_invitations_webhook ON public.invitations;
CREATE TRIGGER trg_invitations_webhook
  AFTER INSERT ON public.invitations
  FOR EACH ROW EXECUTE FUNCTION public.invoke_edge_function('team-worker');

DROP TRIGGER IF EXISTS trg_integrations_webhook ON public.integrations;
CREATE TRIGGER trg_integrations_webhook
  AFTER INSERT ON public.integrations
  FOR EACH ROW EXECUTE FUNCTION public.invoke_edge_function('team-worker');

-- 6. Setup pg_cron for Webhook Dispatcher
-- We set up a cron job to call the webhook-dispatcher every minute to process retries/queue.
CREATE EXTENSION IF NOT EXISTS pg_cron;

DO $$
DECLARE
  v_url TEXT;
  v_service_role_key TEXT;
  v_job_id INT;
BEGIN
  v_url := COALESCE(current_setting('app.settings.functions_url', true), 'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1') || '/webhook-dispatcher';
  v_service_role_key := current_setting('app.settings.service_role_key', true);

  IF v_service_role_key IS NULL OR length(trim(v_service_role_key)) = 0 THEN
    RAISE NOTICE 'Skipping process-webhook-queue cron schedule: app.settings.service_role_key is not configured';
    RETURN;
  END IF;
  
  -- Create the cron job if it doesn't exist
  SELECT jobid INTO v_job_id FROM cron.job WHERE jobname = 'process-webhook-queue';
  
  IF v_job_id IS NULL THEN
    PERFORM cron.schedule(
      'process-webhook-queue',
      '* * * * *', -- Every minute
      format(
        'SELECT net.http_post(''%s'', ''{}''::jsonb, ''{"Content-Type": "application/json", "Authorization": "Bearer %s"}''::jsonb);',
        v_url,
        replace(v_service_role_key, '''', '''''')
      )
    );
  END IF;
END $$;

COMMIT;

-- ==========================================================================
-- Source: 121_safe_updated_at_trigger.sql
-- ==========================================================================

-- Migration 121: Make shared updated_at trigger safe on mixed schemas
--
-- Some live workflow inserts fail with:
--   record "new" has no field "updated_at"
-- That happens when the generic updated_at trigger function is attached to an
-- object that does not expose an updated_at column. Keep the trigger behavior
-- for normal tables, but no-op safely for tables without that column.

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF to_jsonb(NEW) ? 'updated_at' THEN
    NEW := jsonb_populate_record(NEW, jsonb_build_object('updated_at', now()));
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF to_jsonb(NEW) ? 'updated_at' THEN
    NEW := jsonb_populate_record(NEW, jsonb_build_object('updated_at', now()));
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.set_updated_at_metadata()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF to_jsonb(NEW) ? 'updated_at' THEN
    NEW := jsonb_populate_record(NEW, jsonb_build_object('updated_at', now()));
  END IF;

  RETURN NEW;
END;
$$;

-- ==========================================================================
-- Source: 122_harden_native_workflow_triggers.sql
-- ==========================================================================

-- Migration 122: Harden native workflow trigger authentication
--
-- Removes hardcoded service-role fallback behavior from DB-to-Edge-Function
-- dispatch. Runtime secrets are read from private.workflow_runtime_settings,
-- which is not granted to anon/authenticated client roles.

BEGIN;

CREATE EXTENSION IF NOT EXISTS pg_net;
CREATE EXTENSION IF NOT EXISTS pg_cron;

CREATE SCHEMA IF NOT EXISTS private;

CREATE TABLE IF NOT EXISTS private.workflow_runtime_settings (
  setting_name text PRIMARY KEY,
  setting_value text NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE private.workflow_runtime_settings ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON SCHEMA private FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL TABLES IN SCHEMA private FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.invoke_edge_function()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  function_name text := TG_ARGV[0];
  v_url text;
  v_functions_url text;
  v_service_role_key text;
  v_headers jsonb;
  v_payload jsonb;
BEGIN
  SELECT setting_value
    INTO v_functions_url
    FROM private.workflow_runtime_settings
   WHERE setting_name = 'functions_url';

  SELECT setting_value
    INTO v_service_role_key
    FROM private.workflow_runtime_settings
   WHERE setting_name = 'service_role_key';

  v_url := COALESCE(
    NULLIF(trim(v_functions_url), ''),
    'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1'
  ) || '/' || function_name;

  IF v_service_role_key IS NULL OR length(trim(v_service_role_key)) = 0 THEN
    RAISE EXCEPTION 'private.workflow_runtime_settings.service_role_key is required for invoke_edge_function';
  END IF;

  v_headers := jsonb_build_object(
    'Content-Type', 'application/json',
    'Authorization', 'Bearer ' || v_service_role_key
  );

  v_payload := jsonb_build_object(
    'type', TG_OP,
    'table', TG_TABLE_NAME,
    'schema', TG_TABLE_SCHEMA,
    'record', CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN row_to_json(NEW) ELSE NULL END,
    'old_record', CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN row_to_json(OLD) ELSE NULL END
  );

  PERFORM net.http_post(
    url := v_url,
    body := v_payload,
    headers := v_headers
  );

  RETURN NULL;
END;
$$;

DO $$
DECLARE
  v_url text;
  v_functions_url text;
  v_service_role_key text;
  v_job_id int;
BEGIN
  SELECT jobid
    INTO v_job_id
    FROM cron.job
   WHERE jobname = 'process-webhook-queue';

  IF v_job_id IS NOT NULL THEN
    PERFORM cron.unschedule(v_job_id);
  END IF;

  SELECT setting_value
    INTO v_functions_url
    FROM private.workflow_runtime_settings
   WHERE setting_name = 'functions_url';

  SELECT setting_value
    INTO v_service_role_key
    FROM private.workflow_runtime_settings
   WHERE setting_name = 'service_role_key';

  IF v_service_role_key IS NULL OR length(trim(v_service_role_key)) = 0 THEN
    RAISE NOTICE 'Skipping process-webhook-queue cron schedule: private.workflow_runtime_settings.service_role_key is not configured';
    RETURN;
  END IF;

  v_url := COALESCE(
    NULLIF(trim(v_functions_url), ''),
    'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1'
  ) || '/webhook-dispatcher';

  PERFORM cron.schedule(
    'process-webhook-queue',
    '* * * * *',
    format(
      'SELECT net.http_post(%L, %L::jsonb, jsonb_build_object(%L, %L, %L, %L));',
      v_url,
      '{}',
      'Content-Type',
      'application/json',
      'Authorization',
      'Bearer ' || v_service_role_key
    )
  );
END $$;

COMMIT;

-- ==========================================================================
-- Source: 123_security_hardening_app_metadata.sql
-- ==========================================================================

-- ============================================================
-- 020: Security Hardening - Migrate to app_metadata
-- ============================================================
-- Fixes critical vulnerability where frontend clients could
-- self-escalate privileges by editing their user_metadata.
-- We move all sensitive RLS claims to app_metadata.
-- ============================================================

BEGIN;

-- 1. DATA MIGRATION: Copy existing claims from user_metadata to app_metadata
-- This ensures no existing users are locked out.
UPDATE auth.users
SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || 
    jsonb_build_object(
        'role', raw_user_meta_data->>'role',
        'organization_id', raw_user_meta_data->>'organization_id'
    )
WHERE raw_user_meta_data ? 'role' OR raw_user_meta_data ? 'organization_id';

-- 2. UPDATE JWT HELPERS TO READ FROM app_metadata
CREATE OR REPLACE FUNCTION public.get_auth_role() RETURNS TEXT AS $$
  SELECT COALESCE(auth.jwt() -> 'app_metadata' ->> 'role', 'ground_staff');
$$ LANGUAGE sql SECURITY DEFINER STABLE;

CREATE OR REPLACE FUNCTION public.get_auth_org() RETURNS UUID AS $$
  SELECT (auth.jwt() -> 'app_metadata' ->> 'organization_id')::uuid;
$$ LANGUAGE sql SECURITY DEFINER STABLE;

-- 3. UPDATE setup_organization_full RPC to write to app_metadata
CREATE OR REPLACE FUNCTION public.setup_organization_full(
  p_user_id UUID,
  p_org_name TEXT,
  p_org_slug TEXT,
  p_brand_name TEXT,
  p_location_name TEXT,
  p_location_address TEXT DEFAULT ''
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  INSERT INTO public.organizations (name, slug, owner_id)
  VALUES (p_org_name, p_org_slug, p_user_id)
  RETURNING id INTO v_org_id;

  INSERT INTO public.brands (organization_id, name)
  VALUES (v_org_id, p_brand_name)
  RETURNING id INTO v_brand_id;

  INSERT INTO public.locations (organization_id, brand_id, name, address)
  VALUES (v_org_id, v_brand_id, p_location_name, p_location_address)
  RETURNING id INTO v_location_id;

  UPDATE public.profiles
  SET organization_id = v_org_id,
      brand_id        = v_brand_id,
      location_id     = v_location_id,
      role            = 'org_owner',
      access_level    = 'organization',
      updated_at      = now()
  WHERE id = p_user_id;

  -- Use raw_app_meta_data
  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'org_owner',
    'organization_id', v_org_id::text
  )
  WHERE id = p_user_id;

  RETURN jsonb_build_object(
    'org_id',      v_org_id,
    'brand_id',    v_brand_id,
    'location_id', v_location_id
  );
END;
$$;

-- 4. UPDATE accept_invitation RPC to write to app_metadata
CREATE OR REPLACE FUNCTION public.accept_invitation(p_token TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invite RECORD;
  v_user_id UUID;
  v_user_email TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND LOWER(email) = LOWER(v_user_email);

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  UPDATE public.profiles
  SET role            = v_invite.role,
      organization_id = v_invite.organization_id,
      brand_id        = COALESCE(v_invite.brand_id, brand_id),
      location_id     = COALESCE(v_invite.location_id, location_id),
      updated_at      = now()
  WHERE id = v_user_id;

  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id
  WHERE id = v_invite.id;

  -- Use raw_app_meta_data
  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', v_invite.role,
    'organization_id', v_invite.organization_id::text
  )
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success',         true,
    'role',            v_invite.role,
    'organization_id', v_invite.organization_id
  );
END;
$$;

-- 5. UPDATE admin_update_user_role RPC to write to app_metadata
CREATE OR REPLACE FUNCTION public.admin_update_user_role(
  target_user_id    UUID,
  new_role          TEXT,
  new_status        TEXT         DEFAULT NULL,
  new_department    TEXT         DEFAULT NULL,
  new_location      TEXT         DEFAULT NULL,
  new_permissions   JSONB        DEFAULT NULL,
  new_brand_id      UUID         DEFAULT NULL,
  new_location_id   UUID         DEFAULT NULL,
  new_access_level  TEXT         DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  caller_role TEXT;
  caller_org  UUID;
  target_org  UUID;
BEGIN
  caller_role := public.get_auth_role();
  caller_org  := public.get_auth_org();

  IF caller_role NOT IN ('org_owner', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: only org_owner or platform_admin can update user roles';
  END IF;

  SELECT organization_id INTO target_org
  FROM public.profiles
  WHERE id = target_user_id;

  IF caller_role = 'org_owner' AND target_org IS DISTINCT FROM caller_org THEN
    RAISE EXCEPTION 'Cannot modify users outside your organization';
  END IF;

  IF caller_role != 'platform_admin' AND new_role IS NOT NULL THEN
    IF NOT public.can_invite_role(new_role) THEN
      RAISE EXCEPTION 'Cannot assign a role equal to or above your own';
    END IF;
  END IF;

  IF target_user_id = auth.uid() AND caller_role = 'org_owner' AND new_role != 'org_owner' THEN
    RAISE EXCEPTION 'Cannot change your own role. Transfer ownership first.';
  END IF;

  UPDATE public.profiles
  SET role         = COALESCE(new_role, role),
      status       = COALESCE(new_status, status),
      department   = COALESCE(new_department, department),
      permissions  = COALESCE(new_permissions, permissions),
      brand_id     = COALESCE(new_brand_id, brand_id),
      location_id  = COALESCE(new_location_id, location_id),
      access_level = COALESCE(new_access_level, access_level),
      updated_at   = now()
  WHERE id = target_user_id;

  -- Use raw_app_meta_data
  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', COALESCE(new_role, (SELECT role FROM public.profiles WHERE id = target_user_id))
  )
  WHERE id = target_user_id;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- 6. Re-promote admin account (ensuring it works with app_metadata)
DO $$
DECLARE
    target_uid UUID;
BEGIN
    SELECT id INTO target_uid FROM auth.users WHERE email = 'uppalapatisivasaipavankarthik@gmail.com' LIMIT 1;
    
    IF target_uid IS NOT NULL THEN
        -- Sync Profile
        INSERT INTO public.profiles (id, email, role)
        VALUES (target_uid, 'uppalapatisivasaipavankarthik@gmail.com', 'platform_admin')
        ON CONFLICT (id) DO UPDATE SET role = 'platform_admin';
        
        -- Sync JWT App Metadata
        UPDATE auth.users 
        SET raw_app_meta_data = 
            COALESCE(raw_app_meta_data, '{}'::jsonb) || 
            jsonb_build_object('role', 'platform_admin')
        WHERE id = target_uid;
    END IF;
END $$;

COMMIT;

-- ==========================================================================
-- Source: 124_sync_archived_tables.sql
-- ==========================================================================

-- Migration 053: Sync Archived Tables Schema
-- Fix schema mismatch between main tables and archived tables after new columns were added.
-- The archive_record_on_delete trigger relies on exact column ordering.

DO $$
DECLARE
    t TEXT;
BEGIN
    FOR t IN SELECT unnest(ARRAY['organizations', 'brands', 'locations', 'profiles', 'invitations'])
    LOOP
        EXECUTE format('DROP TABLE IF EXISTS public.%I CASCADE', 'archived_' || t);
        EXECUTE format('CREATE TABLE public.%I AS SELECT * FROM public.%I WHERE false', 'archived_' || t, t);
        EXECUTE format('ALTER TABLE public.%I ADD COLUMN archived_at TIMESTAMPTZ DEFAULT now()', 'archived_' || t);
        EXECUTE format('ALTER TABLE public.%I ADD COLUMN archived_by UUID', 'archived_' || t);
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', 'archived_' || t);
        EXECUTE format('CREATE POLICY "Platform admins can view archived records" ON public.%I FOR SELECT USING (auth.jwt() -> ''user_metadata'' ->> ''role'' = ''platform_admin'')', 'archived_' || t);
    END LOOP;
END $$;

-- ==========================================================================
-- Source: 125_fix_storage_fk.sql
-- ==========================================================================

-- ============================================================
-- Fix Supabase Storage constraints blocking user deletion
-- ============================================================

BEGIN;

-- 1. Fix storage.objects owner when the migration role owns the managed storage table.
DO $guard$
BEGIN
  ALTER TABLE storage.objects DROP CONSTRAINT IF EXISTS objects_owner_fkey;
  ALTER TABLE storage.objects ADD CONSTRAINT objects_owner_fkey
      FOREIGN KEY (owner) REFERENCES auth.users(id) ON DELETE SET NULL;
EXCEPTION
  WHEN insufficient_privilege THEN
    RAISE NOTICE 'Skipping storage.objects owner FK repair: migration role does not own storage.objects';
END $guard$;

-- 2. Fix storage.buckets owner when the migration role owns the managed storage table.
DO $guard$
BEGIN
  ALTER TABLE storage.buckets DROP CONSTRAINT IF EXISTS buckets_owner_fkey;
  ALTER TABLE storage.buckets ADD CONSTRAINT buckets_owner_fkey
      FOREIGN KEY (owner) REFERENCES auth.users(id) ON DELETE SET NULL;
EXCEPTION
  WHEN insufficient_privilege THEN
    RAISE NOTICE 'Skipping storage.buckets owner FK repair: migration role does not own storage.buckets';
END $guard$;

-- 3. Explicitly fix the archived_users constraint just in case it was missed
ALTER TABLE public.archived_users DROP CONSTRAINT IF EXISTS archived_users_deleted_by_fkey;
ALTER TABLE public.archived_users ADD CONSTRAINT archived_users_deleted_by_fkey 
    FOREIGN KEY (deleted_by) REFERENCES auth.users(id) ON DELETE SET NULL;

COMMIT;

-- ==========================================================================
-- Source: 126_fix_admin_delete_rpc.sql
-- ==========================================================================

-- ============================================================
-- Migration 055: Fix admin_delete_user RPC Storage Constraint
-- ============================================================

CREATE OR REPLACE FUNCTION public.admin_delete_user(target_user_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    caller_role TEXT;
    v_email TEXT;
    v_full_name TEXT;
    v_role TEXT;
BEGIN
    -- 1. Check if caller is authenticated
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- 2. Verify the caller is a platform_admin
    caller_role := COALESCE(auth.jwt() -> 'app_metadata' ->> 'role', '');
    
    IF caller_role != 'platform_admin' THEN
        RAISE EXCEPTION 'Insufficient permissions: only platform_admin can delete users permanently';
    END IF;

    -- 3. Prevent self-deletion via this route
    IF target_user_id = auth.uid() THEN
        RAISE EXCEPTION 'You cannot delete your own account.';
    END IF;

    -- 4. Gather user details before deletion for the archive
    SELECT email, full_name, role INTO v_email, v_full_name, v_role
    FROM public.profiles
    WHERE id = target_user_id;

    -- If profile was missing, fallback to auth.users for email
    IF v_email IS NULL THEN
        SELECT email INTO v_email FROM auth.users WHERE id = target_user_id;
    END IF;

    -- 5. Archive the user
    INSERT INTO public.archived_users (original_user_id, email, full_name, role, deleted_by)
    VALUES (target_user_id, v_email, v_full_name, v_role, auth.uid());

    -- 6. Detach any files the user uploaded to prevent Foreign Key constraints from blocking deletion
    UPDATE storage.objects SET owner = NULL WHERE owner = target_user_id;

    -- 7. Delete the user from auth.users
    -- Because this function is SECURITY DEFINER, it runs with the privileges 
    -- of the user who created it (postgres superuser during migrations),
    -- allowing it to safely bypass the auth schema restrictions.
    DELETE FROM auth.users WHERE id = target_user_id;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- ==========================================================================
-- Source: 127_vendor_command_center.sql
-- ==========================================================================

-- 087: Vendor Command Center & Health Scores
-- Adds fields to support Phase 2 & 3 of Vendor Command Center

BEGIN;

-- 1. Add fields to vendors table for Accounting Controls and Health Scores
ALTER TABLE public.vendors ADD COLUMN IF NOT EXISTS health_score NUMERIC(5,2) DEFAULT 100.00;
ALTER TABLE public.vendors ADD COLUMN IF NOT EXISTS default_expense_category TEXT;
ALTER TABLE public.vendors ADD COLUMN IF NOT EXISTS default_payment_account_id UUID REFERENCES public.payment_accounts(id) ON DELETE SET NULL;
ALTER TABLE public.vendors ADD COLUMN IF NOT EXISTS file_routing_preference TEXT DEFAULT 'storage' CHECK (file_routing_preference IN ('storage', 'payments', 'accounting'));
ALTER TABLE public.vendors ADD COLUMN IF NOT EXISTS unpaid_ap NUMERIC(12,2) DEFAULT 0;

-- 2. Add Order Guide fields to vendor_items
ALTER TABLE public.vendor_items ADD COLUMN IF NOT EXISTS on_order_guide BOOLEAN DEFAULT false;
ALTER TABLE public.vendor_items ADD COLUMN IF NOT EXISTS preferred_quantity NUMERIC(10,2) DEFAULT 1;
ALTER TABLE public.vendor_items ADD COLUMN IF NOT EXISTS pack_size TEXT;
ALTER TABLE public.vendor_items ADD COLUMN IF NOT EXISTS last_price NUMERIC(10,2);
ALTER TABLE public.vendor_items ADD COLUMN IF NOT EXISTS price_variance_flag BOOLEAN DEFAULT false;

-- 3. Create a Vendor Issues log for the Communication Hub
CREATE TABLE IF NOT EXISTS public.vendor_issues (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  vendor_id UUID NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
  issue_type TEXT NOT NULL CHECK (issue_type IN ('late_delivery', 'missing_item', 'price_mismatch', 'invoice_dispute', 'other')),
  description TEXT NOT NULL,
  status TEXT DEFAULT 'open' CHECK (status IN ('open', 'resolved', 'ignored')),
  reported_by UUID REFERENCES auth.users(id),
  resolved_by UUID REFERENCES auth.users(id),
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE public.vendor_issues ENABLE ROW LEVEL SECURITY;

-- 4. RLS for vendor_issues
DROP POLICY IF EXISTS "Vendor issues read" ON public.vendor_issues;
CREATE POLICY "Vendor issues read" ON public.vendor_issues FOR SELECT USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);

DROP POLICY IF EXISTS "Vendor issues write" ON public.vendor_issues;
CREATE POLICY "Vendor issues write" ON public.vendor_issues FOR ALL USING (
  public.is_platform_admin() OR organization_id = public.get_my_org() OR organization_id IN (SELECT organization_id FROM public.organization_members WHERE user_id = auth.uid())
);

-- 5. Trigger to auto-update vendor total spent when an invoice is paid or approved
CREATE OR REPLACE FUNCTION public.update_vendor_metrics_on_invoice()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status != 'approved') THEN
    UPDATE public.vendors 
    SET total_spent = total_spent + NEW.total_amount,
        unpaid_ap = unpaid_ap + NEW.total_amount
    WHERE id = NEW.vendor_id;
  END IF;

  IF NEW.payment_status = 'paid' AND (OLD.payment_status IS NULL OR OLD.payment_status != 'paid') THEN
    UPDATE public.vendors 
    SET unpaid_ap = GREATEST(unpaid_ap - NEW.total_amount, 0)
    WHERE id = NEW.vendor_id;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS trg_update_vendor_metrics ON public.invoices;
CREATE TRIGGER trg_update_vendor_metrics
AFTER INSERT OR UPDATE ON public.invoices
FOR EACH ROW
EXECUTE FUNCTION public.update_vendor_metrics_on_invoice();

COMMIT;

-- ==========================================================================
-- Source: 128_fix_lint_errors.sql
-- ==========================================================================

-- Migration 119: Fix PL/pgSQL Linter Errors
BEGIN;

-- 1. Fix get_labor_forecast "date" ambiguous reference
CREATE OR REPLACE FUNCTION public.get_labor_forecast(p_location_id UUID)
RETURNS TABLE (
    date TEXT,
    "salesForecast" NUMERIC,
    "scheduledLabor" NUMERIC,
    "suggestedLabor" NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    avg_daily_sales NUMERIC;
BEGIN
    IF NOT public.is_platform_admin()
       AND public.get_my_org() != (SELECT organization_id FROM public.locations WHERE id = p_location_id) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this location data.';
    END IF;

    SELECT COALESCE(AVG(ps.revenue), 3000) INTO avg_daily_sales
    FROM public.pos_sales_data ps
    WHERE ps.location_id = p_location_id AND ps.date >= (now() - interval '30 days');

    RETURN QUERY
    WITH dates AS (
        SELECT generate_series(
            date_trunc('day', now()),
            date_trunc('day', now() + interval '6 days'),
            interval '1 day'
        ) AS d
    ),
    scheduled AS (
        SELECT
            date_trunc('day', es.start_time) AS shift_date,
            COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 0) AS labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id = p_location_id
        GROUP BY date_trunc('day', es.start_time)
    )
    SELECT
        to_char(d.d, 'Mon DD') AS date,
        ROUND(avg_daily_sales * (1 + (random() * 0.4 - 0.2))::NUMERIC, 2) AS "salesForecast",
        ROUND(COALESCE(s.labor_cost::NUMERIC, 0), 2) AS "scheduledLabor",
        ROUND(avg_daily_sales * 0.28, 2) AS "suggestedLabor"
    FROM dates d
    LEFT JOIN scheduled s ON d.d = s.shift_date
    ORDER BY d.d ASC;
END;
$$;

-- 2. Fix schedule_invoice_payment: never read variable "v_org_id"
CREATE OR REPLACE FUNCTION public.schedule_invoice_payment(
  p_invoice_id UUID, 
  p_payment_account_id UUID, 
  p_date DATE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice_status TEXT;
BEGIN
  -- Verify the invoice exists and get its status
  SELECT status INTO v_invoice_status
  FROM public.invoices WHERE id = p_invoice_id;

  IF v_invoice_status NOT IN ('approved', 'scheduled') THEN
    RAISE EXCEPTION 'Invoice must be approved to schedule payment';
  END IF;

  -- Update the invoice
  UPDATE public.invoices
  SET payment_account_id = p_payment_account_id,
      scheduled_payment_date = p_date,
      status = CASE WHEN status = 'approved' THEN 'scheduled' ELSE status END,
      ap_status = CASE WHEN ap_status = 'approved' THEN 'scheduled' ELSE ap_status END,
      updated_at = now()
  WHERE id = p_invoice_id;

  RETURN jsonb_build_object('status', 'scheduled', 'scheduled_payment_date', p_date);
END;
$$;

-- 3. Fix reconcile_invoice_lines: unused variable "v_variance_id", "v_match_id", "v_tolerance"
CREATE OR REPLACE FUNCTION public.reconcile_invoice_lines(p_invoice_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
  v_po_id UUID;
  v_line RECORD;
BEGIN
  SELECT organization_id, purchase_order_id INTO v_org_id, v_po_id 
  FROM public.invoices WHERE id = p_invoice_id;

  -- Delete existing matches and variances for this invoice
  DELETE FROM public.invoice_line_matches WHERE invoice_line_id IN (SELECT id FROM public.invoice_line_items WHERE invoice_id = p_invoice_id);
  DELETE FROM public.reconciliation_variances WHERE invoice_id = p_invoice_id;

  FOR v_line IN (SELECT * FROM public.invoice_line_items WHERE invoice_id = p_invoice_id) LOOP
    INSERT INTO public.invoice_line_matches (organization_id, invoice_line_id, match_status, match_confidence)
    VALUES (v_org_id, v_line.id, 'unmatched', 0.0);

    -- If no PO linked, create a missing_po variance
    IF v_po_id IS NULL THEN
      INSERT INTO public.reconciliation_variances 
      (organization_id, invoice_id, invoice_line_id, variance_type, expected_value, actual_value, variance_amount)
      VALUES (v_org_id, p_invoice_id, v_line.id, 'missing_po', 0, v_line.total_price, v_line.total_price);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'reconciled_lines', (SELECT count(*) FROM public.invoice_line_items WHERE invoice_id = p_invoice_id));
END;
$$;

-- 4. Fix schedule_payment_batch: auto variable "i" shadows a previously defined variable, unused variable "i".
CREATE OR REPLACE FUNCTION public.schedule_payment_batch(
    p_vendor_id UUID,
    p_payment_account_id UUID,
    p_scheduled_date DATE,
    p_invoice_ids UUID[],
    p_amounts NUMERIC[]
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_scheduled_payment_id UUID;
    v_total NUMERIC := 0;
BEGIN
    -- Calculate total
    FOR i IN 1 .. array_length(p_amounts, 1) LOOP
        v_total := v_total + p_amounts[i];
    END LOOP;

    -- Create scheduled payment record
    INSERT INTO public.scheduled_payments (
        organization_id,
        vendor_id,
        payment_account_id,
        total_amount,
        scheduled_date,
        status,
        created_by
    ) VALUES (
        public.get_my_org(),
        p_vendor_id,
        p_payment_account_id,
        v_total,
        p_scheduled_date,
        'scheduled',
        auth.uid()
    ) RETURNING id INTO v_scheduled_payment_id;

    -- Insert intersection records
    FOR i IN 1 .. array_length(p_invoice_ids, 1) LOOP
        INSERT INTO public.scheduled_payment_invoices (
            scheduled_payment_id,
            invoice_id,
            amount_applied
        ) VALUES (
            v_scheduled_payment_id,
            p_invoice_ids[i],
            p_amounts[i]
        );
        
        -- Update invoice status
        UPDATE public.invoices 
        SET scheduled_payment_date = p_scheduled_date,
            status = 'scheduled'
        WHERE id = p_invoice_ids[i];
    END LOOP;

    RETURN v_scheduled_payment_id;
END;
$$;

-- 5. Fix match_vendor: unused variable "v_vendor_id".
CREATE OR REPLACE FUNCTION public.match_vendor(p_org_id UUID, p_vendor_name TEXT)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_exact_match UUID;
  v_alias_match UUID;
  v_fuzzy_match UUID;
BEGIN
  -- 1. Exact match on vendors table
  SELECT id INTO v_exact_match FROM public.vendors 
  WHERE organization_id = p_org_id AND LOWER(name) = LOWER(p_vendor_name)
  LIMIT 1;
  
  IF v_exact_match IS NOT NULL THEN
    RETURN v_exact_match;
  END IF;

  -- 2. Exact match on vendor_aliases
  SELECT canonical_vendor_id INTO v_alias_match FROM public.vendor_aliases
  WHERE organization_id = p_org_id AND LOWER(alias_name) = LOWER(p_vendor_name) AND is_verified = true
  LIMIT 1;

  IF v_alias_match IS NOT NULL THEN
    RETURN v_alias_match;
  END IF;

  -- 3. Fuzzy match using Levenshtein distance
  -- Only consider if distance <= 3 (e.g. slight typo)
  SELECT id INTO v_fuzzy_match FROM public.vendors
  WHERE organization_id = p_org_id AND extensions.levenshtein(LOWER(name), LOWER(p_vendor_name)) <= 3
  ORDER BY extensions.levenshtein(LOWER(name), LOWER(p_vendor_name)) ASC
  LIMIT 1;
  
  RETURN v_fuzzy_match;
END;
$$;

-- 6. Fix admin_update_user_role: unused parameter "new_location".
-- NOTE: Dropping the old signature to prevent duplicated signatures.
DROP FUNCTION IF EXISTS public.admin_update_user_role(UUID, TEXT, TEXT, TEXT, TEXT, JSONB, UUID, UUID, TEXT, JSONB);
DROP FUNCTION IF EXISTS public.admin_update_user_role(UUID, TEXT, TEXT, TEXT, TEXT, JSONB, UUID, UUID, TEXT);

CREATE OR REPLACE FUNCTION public.admin_update_user_role(
  target_user_id    UUID,
  new_role          TEXT         DEFAULT NULL,
  new_status        TEXT         DEFAULT NULL,
  new_department    TEXT         DEFAULT NULL,
  new_location      TEXT         DEFAULT NULL,
  new_permissions   JSONB        DEFAULT NULL,
  new_brand_id      UUID         DEFAULT NULL,
  new_location_id   UUID         DEFAULT NULL,
  new_access_level  TEXT         DEFAULT NULL,
  new_signing_privileges JSONB   DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  caller_role TEXT;
  caller_org  UUID;
  target_org  UUID;
BEGIN
  -- Suppress unused parameter warning
  IF new_location IS NOT NULL THEN
    -- location string is currently not used but passed by API
  END IF;

  caller_role := public.get_auth_role();
  caller_org  := public.get_auth_org();

  IF caller_role NOT IN ('org_owner', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: only org_owner or platform_admin can update user roles';
  END IF;

  SELECT organization_id INTO target_org
  FROM public.profiles
  WHERE id = target_user_id;

  IF caller_role = 'org_owner' AND target_org IS DISTINCT FROM caller_org THEN
    RAISE EXCEPTION 'Cannot modify users outside your organization';
  END IF;

  IF caller_role != 'platform_admin' AND new_role IS NOT NULL THEN
    IF NOT public.can_invite_role(new_role) THEN
      RAISE EXCEPTION 'Cannot assign a role equal to or above your own';
    END IF;
  END IF;

  IF target_user_id = auth.uid() AND caller_role = 'org_owner' AND new_role != 'org_owner' THEN
    RAISE EXCEPTION 'Cannot change your own role. Transfer ownership first.';
  END IF;
  
  -- Update membership tables
  IF new_role IS NOT NULL AND target_org IS NOT NULL THEN
      INSERT INTO public.organization_members (organization_id, user_id, role)
      VALUES (target_org, target_user_id, new_role)
      ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  UPDATE public.profiles
  SET role               = COALESCE(new_role, role),
      status             = COALESCE(new_status, status),
      department         = COALESCE(new_department, department),
      permissions        = COALESCE(new_permissions, permissions),
      signing_privileges = COALESCE(new_signing_privileges, signing_privileges),
      brand_id           = COALESCE(new_brand_id, brand_id),
      location_id        = COALESCE(new_location_id, location_id),
      access_level       = COALESCE(new_access_level, access_level),
      updated_at         = now()
  WHERE id = target_user_id;

  -- Only update app_metadata if this is their ACTIVE org
  IF (SELECT raw_app_meta_data->>'organization_id' FROM auth.users WHERE id = target_user_id) = target_org::text THEN
      UPDATE auth.users
      SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
        'role', COALESCE(new_role, (SELECT role FROM public.profiles WHERE id = target_user_id))
      )
      WHERE id = target_user_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- 7. Fix org_remove_member: unused variable "active_org".
CREATE OR REPLACE FUNCTION public.org_remove_member(
    target_user_id UUID,
    target_org_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  caller_role TEXT;
  caller_org  UUID;
BEGIN
  caller_role := public.get_auth_role();
  caller_org  := COALESCE(target_org_id, public.get_auth_org());

  IF caller_role != 'org_owner' AND caller_role != 'platform_admin' THEN
    RAISE EXCEPTION 'Insufficient permissions: only org_owner or platform_admin can remove users';
  END IF;

  IF target_user_id = auth.uid() THEN
    RAISE EXCEPTION 'You cannot remove yourself. Transfer ownership first.';
  END IF;

  -- Remove from organization_members
  DELETE FROM public.organization_members 
  WHERE user_id = target_user_id AND organization_id = caller_org;
  
  -- Remove from brand_members for this org
  DELETE FROM public.brand_members 
  WHERE user_id = target_user_id 
    AND brand_id IN (SELECT id FROM public.brands WHERE organization_id = caller_org);
    
  -- Remove from location_members for this org
  DELETE FROM public.location_members 
  WHERE user_id = target_user_id 
    AND location_id IN (SELECT id FROM public.locations WHERE organization_id = caller_org);

  -- Update profiles if this was their active org
  UPDATE public.profiles 
  SET organization_id = NULL, brand_id = NULL, location_id = NULL, role = 'ground_staff'
  WHERE id = target_user_id AND organization_id = caller_org;

  -- Update app_metadata if this is their active context
  IF (SELECT raw_app_meta_data->>'organization_id' FROM auth.users WHERE id = target_user_id) = caller_org::text THEN
      UPDATE auth.users
      SET raw_app_meta_data = raw_app_meta_data - 'organization_id' - 'role' - 'brand_id' - 'location_id'
      WHERE id = target_user_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 129_server_side_pnl.sql
-- ==========================================================================

-- Migration 124: Server-Side PnL Aggregation RPC

-- Create or Replace the RPC for PnL Summary
CREATE OR REPLACE FUNCTION public.get_pnl_summary(
  p_org_id UUID,
  p_start_date DATE,
  p_end_date DATE,
  p_brand_id UUID DEFAULT NULL,
  p_location_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_total_revenue NUMERIC(15,2) := 0;
  v_total_labor NUMERIC(15,2) := 0;
  v_total_cogs_allocated NUMERIC(15,2) := 0;
  v_total_invoices_raw NUMERIC(15,2) := 0;
  v_total_cogs NUMERIC(15,2) := 0;
BEGIN
  -- 1. Calculate Total Revenue from mv_daily_sales_summary
  SELECT COALESCE(SUM(total_revenue), 0) INTO v_total_revenue
  FROM public.mv_daily_sales_summary
  WHERE organization_id = p_org_id
    AND date >= p_start_date 
    AND date <= p_end_date
    AND (p_brand_id IS NULL OR brand_id = p_brand_id)
    AND (p_location_id IS NULL OR location_id = p_location_id);

  -- 2. Calculate Total Labor from employee_shifts
  SELECT COALESCE(SUM(labor_cost), 0) INTO v_total_labor
  FROM public.employee_shifts
  WHERE organization_id = p_org_id
    AND shift_start >= p_start_date 
    AND shift_start <= p_end_date
    AND (p_location_id IS NULL OR location_id = p_location_id);

  -- 3. Calculate Total COGS 
  -- We first check invoice_allocations specifically for 'line_items' within the period.
  -- Because invoice_allocations lacks a date field natively (unless joined to invoices),
  -- we join it to invoices here to apply the date filter.
  SELECT COALESCE(SUM(a.amount), 0) INTO v_total_cogs_allocated
  FROM public.invoice_allocations a
  JOIN public.invoices i ON i.id = a.invoice_id
  WHERE a.organization_id = p_org_id
    AND a.allocation_type = 'line_items'
    AND i.invoice_date >= p_start_date
    AND i.invoice_date <= p_end_date
    AND (p_brand_id IS NULL OR i.brand_id = p_brand_id)
    AND (p_location_id IS NULL OR i.location_id = p_location_id);

  -- If allocated COGS is zero, we fallback to raw total_amount of invoices
  IF v_total_cogs_allocated > 0 THEN
    v_total_cogs := v_total_cogs_allocated;
  ELSE
    SELECT COALESCE(SUM(total_amount), 0) INTO v_total_invoices_raw
    FROM public.invoices
    WHERE organization_id = p_org_id
      AND invoice_date >= p_start_date
      AND invoice_date <= p_end_date
      AND status != 'void'
      AND (p_brand_id IS NULL OR brand_id = p_brand_id)
      AND (p_location_id IS NULL OR location_id = p_location_id);
      
    v_total_cogs := v_total_invoices_raw;
  END IF;

  RETURN jsonb_build_object(
    'total_revenue', v_total_revenue,
    'total_labor_cost', v_total_labor,
    'total_cogs', v_total_cogs,
    'prime_cost', (v_total_cogs + v_total_labor)
  );
END;
$$;

-- ==========================================================================
-- Source: 130_labor_schedule_variance.sql
-- ==========================================================================

-- Migration 130: Labor Schedule Variance

-- Drop if exists to avoid return type mismatch errors on replace
DROP FUNCTION IF EXISTS public.get_labor_schedule_variance(DATE, DATE, UUID);

CREATE OR REPLACE FUNCTION public.get_labor_schedule_variance(
  p_start_date DATE,
  p_end_date DATE,
  p_location_id UUID
)
RETURNS TABLE (
  date DATE,
  projected_sales NUMERIC(15,2),
  scheduled_labor NUMERIC(15,2),
  suggested_labor NUMERIC(15,2),
  variance_amount NUMERIC(15,2)
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  RETURN QUERY
  WITH date_series AS (
    SELECT generate_series(p_start_date, p_end_date, '1 day'::interval)::date AS d
  ),
  daily_sales AS (
    SELECT 
      m.date,
      SUM(m.total_revenue) as projected_sales
    FROM public.mv_daily_sales_summary m
    WHERE m.date >= p_start_date AND m.date <= p_end_date
      AND (p_location_id IS NULL OR m.location_id = p_location_id)
    GROUP BY m.date
  ),
  daily_labor AS (
    SELECT 
      s.shift_start::date AS date,
      SUM(s.labor_cost) as scheduled_labor
    FROM public.employee_shifts s
    WHERE s.shift_start >= p_start_date AND s.shift_start <= p_end_date
      AND (p_location_id IS NULL OR s.location_id = p_location_id)
    GROUP BY s.shift_start::date
  )
  SELECT 
    ds.d AS date,
    COALESCE(s.projected_sales, 0) AS projected_sales,
    COALESCE(l.scheduled_labor, 0) AS scheduled_labor,
    -- Suggested labor is typically ~25% of sales
    (COALESCE(s.projected_sales, 0) * 0.25)::numeric(15,2) AS suggested_labor,
    -- Variance is scheduled minus suggested (positive = overstaffed, negative = understaffed)
    (COALESCE(l.scheduled_labor, 0) - (COALESCE(s.projected_sales, 0) * 0.25))::numeric(15,2) AS variance_amount
  FROM date_series ds
  LEFT JOIN daily_sales s ON ds.d = s.date
  LEFT JOIN daily_labor l ON ds.d = l.date
  ORDER BY ds.d;
END;
$$;

