-- Migration 131: Procurement Receivings

-- 1. Create receivings table
CREATE TABLE IF NOT EXISTS public.receivings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
    location_id UUID REFERENCES public.locations(id) ON DELETE SET NULL,
    purchase_order_id UUID REFERENCES public.purchase_orders(id) ON DELETE CASCADE,
    vendor_id UUID REFERENCES public.vendors(id) ON DELETE SET NULL,
    received_date DATE NOT NULL DEFAULT CURRENT_DATE,
    received_by UUID REFERENCES auth.users(id),
    status TEXT DEFAULT 'completed' CHECK (status IN ('draft', 'completed', 'disputed')),
    notes TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- Fix if table already existed without columns
ALTER TABLE public.receivings ADD COLUMN IF NOT EXISTS purchase_order_id UUID REFERENCES public.purchase_orders(id) ON DELETE CASCADE;
ALTER TABLE public.receivings ADD COLUMN IF NOT EXISTS vendor_id UUID REFERENCES public.vendors(id) ON DELETE SET NULL;
ALTER TABLE public.receivings ADD COLUMN IF NOT EXISTS received_date DATE NOT NULL DEFAULT CURRENT_DATE;
ALTER TABLE public.receivings ADD COLUMN IF NOT EXISTS received_by UUID REFERENCES auth.users(id);

-- 2. Create receiving_items table
CREATE TABLE IF NOT EXISTS public.receiving_items (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    receiving_id UUID NOT NULL REFERENCES public.receivings(id) ON DELETE CASCADE,
    purchase_order_item_id UUID REFERENCES public.purchase_order_items(id) ON DELETE SET NULL,
    product_id UUID REFERENCES public.products(id) ON DELETE SET NULL,
    quantity_received NUMERIC(10,2) NOT NULL DEFAULT 0,
    condition TEXT DEFAULT 'good' CHECK (condition IN ('good', 'damaged', 'spoiled', 'missing')),
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- Fix if items table already existed
ALTER TABLE public.receiving_items ADD COLUMN IF NOT EXISTS purchase_order_item_id UUID REFERENCES public.purchase_order_items(id) ON DELETE SET NULL;
ALTER TABLE public.receiving_items ADD COLUMN IF NOT EXISTS product_id UUID REFERENCES public.products(id) ON DELETE SET NULL;
ALTER TABLE public.receiving_items ADD COLUMN IF NOT EXISTS quantity_received NUMERIC(10,2) NOT NULL DEFAULT 0;

-- 3. Link Invoices to Purchase Orders
ALTER TABLE public.invoices ADD COLUMN IF NOT EXISTS purchase_order_id UUID REFERENCES public.purchase_orders(id) ON DELETE SET NULL;

-- 4. Triggers
DROP TRIGGER IF EXISTS set_updated_at ON public.receivings;
CREATE TRIGGER set_updated_at 
    BEFORE UPDATE ON public.receivings 
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

DROP TRIGGER IF EXISTS set_updated_at ON public.receiving_items;
CREATE TRIGGER set_updated_at 
    BEFORE UPDATE ON public.receiving_items 
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- 5. RLS
ALTER TABLE public.receivings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.receiving_items ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view receivings" ON public.receivings;
CREATE POLICY "Users can view receivings" ON public.receivings 
    FOR SELECT USING (organization_id = public.get_my_org());

DROP POLICY IF EXISTS "Manager+ can manage receivings" ON public.receivings;
CREATE POLICY "Manager+ can manage receivings" ON public.receivings 
    FOR ALL USING (is_manager_or_above() AND organization_id = public.get_my_org());

DROP POLICY IF EXISTS "Users can view receiving items" ON public.receiving_items;
CREATE POLICY "Users can view receiving items" ON public.receiving_items 
    FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.receivings r
            WHERE r.id = receiving_items.receiving_id 
            AND r.organization_id = public.get_my_org()
        )
    );

DROP POLICY IF EXISTS "Manager+ can manage receiving items" ON public.receiving_items;
CREATE POLICY "Manager+ can manage receiving items" ON public.receiving_items 
    FOR ALL USING (
        EXISTS (
            SELECT 1 FROM public.receivings r 
            WHERE r.id = receiving_items.receiving_id 
            AND r.organization_id = public.get_my_org()
            AND is_manager_or_above()
        )
    );

-- 6. Indexes
CREATE INDEX IF NOT EXISTS idx_receivings_org_id ON public.receivings(organization_id);
CREATE INDEX IF NOT EXISTS idx_receivings_po_id ON public.receivings(purchase_order_id);
CREATE INDEX IF NOT EXISTS idx_receiving_items_rec_id ON public.receiving_items(receiving_id);
CREATE INDEX IF NOT EXISTS idx_invoices_po_id ON public.invoices(purchase_order_id);

-- ==========================================================================
-- Source: 132_three_way_match_rpc.sql
-- ==========================================================================

-- Migration 132: Three-Way Match RPC and Trigger

-- 1. Create the RPC to return match status
CREATE OR REPLACE FUNCTION public.get_three_way_match_status(p_purchase_order_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_po RECORD;
  v_invoice RECORD;
  v_receiving RECORD;
  v_po_total NUMERIC := 0;
  v_inv_total NUMERIC := 0;
  v_rec_qty NUMERIC := 0;
  v_po_qty NUMERIC := 0;
  v_variance_amount NUMERIC := 0;
  v_variance_percent NUMERIC := 0;
  v_status TEXT := 'matched';
BEGIN
  -- Get PO details
  SELECT * INTO v_po FROM public.purchase_orders WHERE id = p_purchase_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'PO not found'); END IF;

  v_po_total := v_po.total_amount;

  -- Get Invoice details (assume 1 invoice per PO for simplicity)
  SELECT * INTO v_invoice FROM public.invoices WHERE purchase_order_id = p_purchase_order_id ORDER BY created_at DESC LIMIT 1;
  IF FOUND THEN
    v_inv_total := v_invoice.total_amount;
  END IF;

  -- Get total PO quantity
  SELECT COALESCE(SUM(quantity), 0) INTO v_po_qty FROM public.purchase_order_items WHERE purchase_order_id = p_purchase_order_id;

  -- Get total Received quantity
  SELECT COALESCE(SUM(ri.quantity_received), 0) INTO v_rec_qty 
  FROM public.receivings r
  JOIN public.receiving_items ri ON ri.receiving_id = r.id
  WHERE r.purchase_order_id = p_purchase_order_id;

  -- Calculate variance based on invoice vs PO cost
  IF v_inv_total > 0 AND v_po_total > 0 THEN
    v_variance_amount := ABS(v_inv_total - v_po_total);
    v_variance_percent := (v_variance_amount / v_po_total) * 100;
  END IF;

  -- Determine status
  IF v_rec_qty < v_po_qty THEN
    v_status := 'quantity_variance';
  END IF;

  IF v_variance_percent > 5 OR v_variance_amount > 50 THEN
    v_status := 'price_variance';
  END IF;

  -- If both, just say critical_variance
  IF v_rec_qty < v_po_qty AND (v_variance_percent > 5 OR v_variance_amount > 50) THEN
    v_status := 'critical_variance';
  END IF;

  RETURN jsonb_build_object(
    'po_total', v_po_total,
    'invoice_total', v_inv_total,
    'po_quantity', v_po_qty,
    'received_quantity', v_rec_qty,
    'variance_amount', v_variance_amount,
    'variance_percent', v_variance_percent,
    'match_status', v_status
  );
END;
$$;

-- 2. Create Trigger Function to block invoice
CREATE OR REPLACE FUNCTION public.check_three_way_match_before_invoice_approval()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_match_data JSONB;
BEGIN
  -- Only run if there's a PO attached and it's trying to move to approved or pending_payment
  IF NEW.purchase_order_id IS NOT NULL AND NEW.status IN ('approved', 'pending_payment') THEN
    
    -- If it's already pending_match_approval, we don't loop
    IF OLD.status = 'pending_match_approval' AND NEW.status != 'pending_match_approval' THEN
      -- A manager is forcing the approval. Let it pass.
      RETURN NEW;
    END IF;

    v_match_data := public.get_three_way_match_status(NEW.purchase_order_id);
    
    IF v_match_data->>'match_status' IN ('price_variance', 'critical_variance') THEN
      NEW.status := 'pending_match_approval';
      NEW.validation_notes := 'Blocked by Three-Way Match: Variance > 5% or > $50. Requires manager override.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trigger_three_way_match_invoice ON public.invoices;
CREATE TRIGGER trigger_three_way_match_invoice
  BEFORE INSERT OR UPDATE OF status, total_amount ON public.invoices
  FOR EACH ROW
  EXECUTE FUNCTION public.check_three_way_match_before_invoice_approval();

-- ==========================================================================
-- Source: 133_harden_rls_location_access.sql
-- ==========================================================================

-- Migration 133: Harden RLS Location Access
-- Extends the get_my_accessible_location_ids and get_my_accessible_brand_ids 
-- to explicitly read from the user_roles table, securing data visibility for custom roles.

BEGIN;

CREATE OR REPLACE FUNCTION public.get_my_accessible_brand_ids()
RETURNS SETOF UUID
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
  -- 1. Base access from legacy profiles.role
  SELECT b.brand_id
  FROM public.brands b
  WHERE b.organization_id = public.get_auth_org()
    AND (
      public.get_auth_role() IN ('platform_admin', 'org_owner')
      OR (
        public.get_auth_role() = 'branch_manager'
        AND b.brand_id = (SELECT p.brand_id FROM public.profiles p WHERE p.id = auth.uid())
      )
    )
  UNION
  -- 2. Location-based brand access from user_roles
  SELECT l.brand_id
  FROM public.locations l
  INNER JOIN public.user_roles ur ON ur.location_id = l.id
  WHERE ur.user_id = auth.uid() AND ur.organization_id = public.get_auth_org()
  UNION
  -- 3. Org-wide access from user_roles (when location_id IS NULL)
  SELECT b.brand_id
  FROM public.brands b
  INNER JOIN public.user_roles ur ON ur.organization_id = b.organization_id
  WHERE ur.user_id = auth.uid() 
    AND ur.organization_id = public.get_auth_org() 
    AND ur.location_id IS NULL;
$$;

COMMENT ON FUNCTION public.get_my_accessible_brand_ids() IS
  'Returns brand IDs the caller can access via profiles or user_roles assignments.';


CREATE OR REPLACE FUNCTION public.get_my_accessible_location_ids()
RETURNS SETOF UUID
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
  -- 1. Base access from legacy profiles.role
  SELECT l.id
  FROM public.locations l
  WHERE l.organization_id = public.get_auth_org()
    AND (
      public.get_auth_role() IN ('platform_admin', 'org_owner')
      OR (
        public.get_auth_role() = 'branch_manager'
        AND l.brand_id IN (
          SELECT b.brand_id FROM public.brands b WHERE b.brand_id = (SELECT p.brand_id FROM public.profiles p WHERE p.id = auth.uid())
        )
      )
      OR (
        public.get_auth_role() = 'location_manager'
        AND l.id = (SELECT p.location_id FROM public.profiles p WHERE p.id = auth.uid())
      )
    )
  UNION
  -- 2. Explicit location access from user_roles
  SELECT ur.location_id
  FROM public.user_roles ur
  WHERE ur.user_id = auth.uid() 
    AND ur.organization_id = public.get_auth_org() 
    AND ur.location_id IS NOT NULL
  UNION
  -- 3. Org-wide access from user_roles (when location_id IS NULL)
  SELECT l.id
  FROM public.locations l
  INNER JOIN public.user_roles ur ON ur.organization_id = l.organization_id
  WHERE ur.user_id = auth.uid() 
    AND ur.organization_id = public.get_auth_org() 
    AND ur.location_id IS NULL;
$$;

COMMENT ON FUNCTION public.get_my_accessible_location_ids() IS
  'Returns location IDs the caller can access via profiles or user_roles assignments.';

COMMIT;

-- ==========================================================================
-- Source: 134_cross_location_benchmarks.sql
-- ==========================================================================

-- supabase/migrations/134_cross_location_benchmarks.sql

CREATE OR REPLACE FUNCTION get_location_benchmarks(
  p_organization_id UUID,
  p_start_date DATE,
  p_end_date DATE
)
RETURNS TABLE (
  location_id UUID,
  location_name TEXT,
  total_revenue NUMERIC,
  total_cogs NUMERIC,
  total_labor NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  -- Verify the user has access to this organization
  IF NOT EXISTS (
    SELECT 1 FROM user_profiles
    WHERE id = auth.uid()
    AND organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  WITH Sales AS (
    SELECT 
      m.location_id,
      SUM(m.total_revenue) as rev
    FROM mv_daily_sales_summary m
    WHERE m.organization_id = p_organization_id
      AND m.date >= p_start_date
      AND m.date <= p_end_date
    GROUP BY m.location_id
  ),
  COGS AS (
    SELECT
      i.location_id,
      SUM(i.total_amount) as cogs
    FROM invoices i
    WHERE i.organization_id = p_organization_id
      AND i.invoice_date >= p_start_date
      AND i.invoice_date <= p_end_date
    GROUP BY i.location_id
  ),
  Labor AS (
    SELECT
      s.location_id,
      SUM(s.labor_cost) as labor
    FROM employee_shifts s
    WHERE s.organization_id = p_organization_id
      AND DATE(s.shift_start) >= p_start_date
      AND DATE(s.shift_start) <= p_end_date
    GROUP BY s.location_id
  )
  SELECT 
    l.id as location_id,
    l.name as location_name,
    COALESCE(s.rev, 0)::NUMERIC as total_revenue,
    COALESCE(c.cogs, 0)::NUMERIC as total_cogs,
    COALESCE(lab.labor, 0)::NUMERIC as total_labor
  FROM locations l
  LEFT JOIN Sales s ON l.id = s.location_id
  LEFT JOIN COGS c ON l.id = c.location_id
  LEFT JOIN Labor lab ON l.id = lab.location_id
  WHERE l.organization_id = p_organization_id
  ORDER BY COALESCE(s.rev, 0) DESC;
END;
$$;

-- ==========================================================================
-- Source: 135_prevent_privilege_escalation.sql
-- ==========================================================================

-- ============================================================
-- 129: Prevent Mass Assignment / Privilege Escalation
-- ============================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.protect_profile_security_columns()
RETURNS TRIGGER AS $$
BEGIN
  -- Check if restricted security columns are being modified
  IF NEW.role IS DISTINCT FROM OLD.role OR
     NEW.organization_id IS DISTINCT FROM OLD.organization_id OR
     NEW.brand_id IS DISTINCT FROM OLD.brand_id OR
     NEW.location_id IS DISTINCT FROM OLD.location_id THEN
     
     -- Only allow modifications if the current database user is NOT authenticated/anon
     -- Typically, standard API requests execute as 'authenticated'. 
     -- System backend actions run as 'postgres' or 'service_role' or 'supabase_admin'.
     IF current_setting('role') IN ('authenticated', 'anon') THEN
        RAISE EXCEPTION '42501: Privilege escalation attempt detected. You cannot modify your own role or organization bindings.';
     END IF;
  END IF;
  
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY INVOKER SET search_path = '';

-- Apply the trigger to the profiles table
DROP TRIGGER IF EXISTS trg_protect_profile_security_columns ON public.profiles;
CREATE TRIGGER trg_protect_profile_security_columns
  BEFORE UPDATE ON public.profiles
  FOR EACH ROW
  EXECUTE FUNCTION public.protect_profile_security_columns();

COMMIT;

-- ==========================================================================
-- Source: 136_fix_invoice_status_constraint.sql
-- ==========================================================================

-- Fix invoices_status_check constraint to allow extracting and extract_failed
BEGIN;

ALTER TABLE public.invoices DROP CONSTRAINT IF EXISTS invoices_status_check;
ALTER TABLE public.invoices ADD CONSTRAINT invoices_status_check CHECK (status IN ('extracting', 'extract_failed', 'pending_review', 'validated', 'pending_approval', 'approved', 'scheduled', 'partially_paid', 'paid', 'rejected', 'duplicate', 'flagged'));

DO $$
DECLARE
  schema_record RECORD;
BEGIN
  IF to_regclass('public.tenant_registry') IS NULL THEN
    RAISE NOTICE 'Skipping tenant schema invoice status constraint update: public.tenant_registry does not exist';
    RETURN;
  END IF;

  FOR schema_record IN SELECT schema_name FROM public.tenant_registry LOOP
    EXECUTE format('ALTER TABLE %I.invoices DROP CONSTRAINT IF EXISTS invoices_status_check;', schema_record.schema_name);
    EXECUTE format('ALTER TABLE %I.invoices ADD CONSTRAINT invoices_status_check CHECK (status IN (''extracting'', ''extract_failed'', ''pending_review'', ''validated'', ''pending_approval'', ''approved'', ''scheduled'', ''partially_paid'', ''paid'', ''rejected'', ''duplicate'', ''flagged''));', schema_record.schema_name);
  END LOOP;
END $$;

COMMIT;

