-- ==========================================================================
-- Source: 20260618051000_resolve_remote_lint_errors.sql
-- ==========================================================================

-- Resolve remote lint errors after API-role grant mitigations.
--
-- Fixes get_location_benchmarks referencing a non-existent user_profiles table
-- and removes an unused variable from get_three_way_match_status.

BEGIN;

CREATE OR REPLACE FUNCTION public.get_location_benchmarks(
  p_organization_id uuid,
  p_start_date date,
  p_end_date date
)
RETURNS TABLE (
  location_id uuid,
  location_name text,
  total_revenue numeric,
  total_cogs numeric,
  total_labor numeric
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
      FROM public.profiles p
     WHERE p.id = auth.uid()
       AND p.organization_id = p_organization_id
       AND p.status = 'active'
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  WITH sales AS (
    SELECT
      m.location_id,
      SUM(m.total_revenue) AS rev
    FROM public.mv_daily_sales_summary m
    WHERE m.organization_id = p_organization_id
      AND m.date >= p_start_date
      AND m.date <= p_end_date
    GROUP BY m.location_id
  ),
  cogs AS (
    SELECT
      i.location_id,
      SUM(i.total_amount) AS cogs
    FROM public.invoices i
    WHERE i.organization_id = p_organization_id
      AND i.invoice_date >= p_start_date
      AND i.invoice_date <= p_end_date
    GROUP BY i.location_id
  ),
  labor AS (
    SELECT
      s.location_id,
      SUM(s.labor_cost) AS labor
    FROM public.employee_shifts s
    WHERE s.organization_id = p_organization_id
      AND DATE(s.shift_start) >= p_start_date
      AND DATE(s.shift_start) <= p_end_date
    GROUP BY s.location_id
  )
  SELECT
    l.id AS location_id,
    l.name AS location_name,
    COALESCE(s.rev, 0)::numeric AS total_revenue,
    COALESCE(c.cogs, 0)::numeric AS total_cogs,
    COALESCE(lab.labor, 0)::numeric AS total_labor
  FROM public.locations l
  LEFT JOIN sales s ON l.id = s.location_id
  LEFT JOIN cogs c ON l.id = c.location_id
  LEFT JOIN labor lab ON l.id = lab.location_id
  WHERE l.organization_id = p_organization_id
  ORDER BY COALESCE(s.rev, 0) DESC;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_three_way_match_status(p_purchase_order_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_po record;
  v_invoice record;
  v_po_total numeric := 0;
  v_inv_total numeric := 0;
  v_rec_qty numeric := 0;
  v_po_qty numeric := 0;
  v_variance_amount numeric := 0;
  v_variance_percent numeric := 0;
  v_status text := 'matched';
BEGIN
  SELECT * INTO v_po FROM public.purchase_orders WHERE id = p_purchase_order_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'PO not found');
  END IF;

  v_po_total := v_po.total_amount;

  SELECT * INTO v_invoice
    FROM public.invoices
   WHERE purchase_order_id = p_purchase_order_id
   ORDER BY created_at DESC
   LIMIT 1;

  IF FOUND THEN
    v_inv_total := v_invoice.total_amount;
  END IF;

  SELECT COALESCE(SUM(quantity), 0)
    INTO v_po_qty
    FROM public.purchase_order_items
   WHERE purchase_order_id = p_purchase_order_id;

  SELECT COALESCE(SUM(ri.quantity_received), 0)
    INTO v_rec_qty
    FROM public.receivings r
    JOIN public.receiving_items ri ON ri.receiving_id = r.id
   WHERE r.purchase_order_id = p_purchase_order_id;

  IF v_inv_total > 0 AND v_po_total > 0 THEN
    v_variance_amount := ABS(v_inv_total - v_po_total);
    v_variance_percent := (v_variance_amount / v_po_total) * 100;
  END IF;

  IF v_rec_qty < v_po_qty THEN
    v_status := 'quantity_variance';
  END IF;

  IF v_variance_percent > 5 OR v_variance_amount > 50 THEN
    v_status := 'price_variance';
  END IF;

  IF v_rec_qty < v_po_qty AND (v_variance_percent > 5 OR v_variance_amount > 50) THEN
    v_status := 'critical_variance';
  END IF;

  RETURN jsonb_build_object(
    'po_total', v_po_total,
    'invoice_total', v_inv_total,
    'po_quantity', v_po_qty,
    'received_quantity', v_rec_qty,
    'variance_amount', v_variance_amount,
    'variance_percent', v_variance_percent,
    'match_status', v_status
  );
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260618120000_remove_ask_tom.sql
-- ==========================================================================

-- Remove the deprecated Ask Tom chat workflow.
-- AI Insights remains the restaurant-specific AI surface.

BEGIN;

UPDATE public.plans
SET features = (
  SELECT COALESCE(jsonb_agg(DISTINCT feature), '[]'::jsonb)
  FROM (
    SELECT feature
    FROM jsonb_array_elements_text(features) AS feature
    WHERE feature <> 'ask_tom'
    UNION ALL
    SELECT 'ai_insights'
  ) plan_features
)
WHERE jsonb_typeof(features) = 'array'
  AND features ? 'ask_tom';

UPDATE public.organizations
SET enabled_modules = (
  SELECT COALESCE(jsonb_agg(DISTINCT module_key), '[]'::jsonb)
  FROM (
    SELECT module_key
    FROM jsonb_array_elements_text(enabled_modules) AS module_key
    WHERE module_key <> 'ask_tom'
    UNION ALL
    SELECT 'ai_insights'
  ) org_modules
)
WHERE jsonb_typeof(enabled_modules) = 'array'
  AND enabled_modules ? 'ask_tom';

DROP TABLE IF EXISTS public.ask_tom_messages;
DROP TABLE IF EXISTS public.ask_tom_threads;
DROP FUNCTION IF EXISTS public.ai_chat_response(UUID, TEXT);

COMMIT;

-- ==========================================================================
-- Source: 20260618143000_remove_legacy_access_levels.sql
-- ==========================================================================

-- Remove the legacy JSON page-access/signing-authority layer.
-- RBAC remains handled through roles, permissions, role_permissions, org membership,
-- and module enablement.

DROP FUNCTION IF EXISTS public.admin_update_user_role(UUID, TEXT, TEXT, TEXT, TEXT, JSONB, UUID, UUID, TEXT, JSONB);
DROP FUNCTION IF EXISTS public.admin_update_user_role(UUID, TEXT, TEXT, TEXT, TEXT, JSONB, UUID, UUID, TEXT);

CREATE OR REPLACE FUNCTION public.admin_update_user_role(
  target_user_id    UUID,
  new_role          TEXT         DEFAULT NULL,
  new_status        TEXT         DEFAULT NULL,
  new_department    TEXT         DEFAULT NULL,
  new_location      TEXT         DEFAULT NULL,
  new_brand_id      UUID         DEFAULT NULL,
  new_location_id   UUID         DEFAULT NULL,
  new_access_level  TEXT         DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  caller_role TEXT;
  caller_org  UUID;
  target_org  UUID;
BEGIN
  IF new_location IS NOT NULL THEN
    -- Location display text is accepted for backward-compatible callers but not stored.
  END IF;

  caller_role := public.get_auth_role();
  caller_org  := public.get_auth_org();

  IF caller_role NOT IN ('org_owner', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: only org_owner or platform_admin can update user roles';
  END IF;

  SELECT organization_id INTO target_org
  FROM public.profiles
  WHERE id = target_user_id;

  IF caller_role = 'org_owner' AND target_org IS DISTINCT FROM caller_org THEN
    RAISE EXCEPTION 'Cannot modify users outside your organization';
  END IF;

  IF caller_role != 'platform_admin' AND new_role IS NOT NULL THEN
    IF NOT public.can_invite_role(new_role) THEN
      RAISE EXCEPTION 'Cannot assign a role equal to or above your own';
    END IF;
  END IF;

  IF target_user_id = auth.uid() AND caller_role = 'org_owner' AND new_role != 'org_owner' THEN
    RAISE EXCEPTION 'Cannot change your own role. Transfer ownership first.';
  END IF;

  IF new_role IS NOT NULL AND target_org IS NOT NULL THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (target_org, target_user_id, new_role)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  UPDATE public.profiles
  SET role             = COALESCE(new_role, role),
      status           = COALESCE(new_status, status),
      department       = COALESCE(new_department, department),
      brand_id         = COALESCE(new_brand_id, brand_id),
      location_id      = COALESCE(new_location_id, location_id),
      access_level     = COALESCE(new_access_level, access_level),
      updated_at       = now()
  WHERE id = target_user_id;

  IF (SELECT raw_app_meta_data->>'organization_id' FROM auth.users WHERE id = target_user_id) = target_org::text THEN
    UPDATE auth.users
    SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
      'role', COALESCE(new_role, (SELECT role FROM public.profiles WHERE id = target_user_id))
    )
    WHERE id = target_user_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_update_user_role(UUID, TEXT, TEXT, TEXT, TEXT, UUID, UUID, TEXT) TO authenticated, service_role;

ALTER TABLE public.profiles
  DROP COLUMN IF EXISTS permissions,
  DROP COLUMN IF EXISTS signing_privileges;

ALTER TABLE public.roles
  DROP COLUMN IF EXISTS default_page_permissions,
  DROP COLUMN IF EXISTS default_signing_privileges;

ALTER TABLE public.invitations
  DROP COLUMN IF EXISTS permissions,
  DROP COLUMN IF EXISTS page_permissions,
  DROP COLUMN IF EXISTS signing_privileges;

-- ==========================================================================
-- Source: 20260618153000_create_tenant_registry.sql
-- ==========================================================================

-- Phase 1: Tenant registry for future schema-per-tenant migration.
-- This does not move operational data yet. It records the authoritative mapping
-- from public.organizations to the future tenant schema name and rollout modes.

BEGIN;

CREATE TABLE IF NOT EXISTS public.tenant_registry (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  schema_name TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'planned',
  read_mode TEXT NOT NULL DEFAULT 'public',
  write_mode TEXT NOT NULL DEFAULT 'public',
  provisioned_at TIMESTAMPTZ,
  migrated_at TIMESTAMPTZ,
  last_validated_at TIMESTAMPTZ,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT tenant_registry_organization_unique UNIQUE (organization_id),
  CONSTRAINT tenant_registry_schema_unique UNIQUE (schema_name),
  CONSTRAINT tenant_registry_schema_name_safe CHECK (
    schema_name ~ '^tenant_[a-z0-9_]+$'
    AND length(schema_name) <= 63
  ),
  CONSTRAINT tenant_registry_status_check CHECK (
    status IN ('planned', 'provisioning', 'active', 'migrating', 'failed', 'archived')
  ),
  CONSTRAINT tenant_registry_read_mode_check CHECK (
    read_mode IN ('public', 'dual', 'tenant_schema')
  ),
  CONSTRAINT tenant_registry_write_mode_check CHECK (
    write_mode IN ('public', 'dual', 'tenant_schema')
  )
);

CREATE INDEX IF NOT EXISTS idx_tenant_registry_status ON public.tenant_registry(status);
CREATE INDEX IF NOT EXISTS idx_tenant_registry_read_write_mode ON public.tenant_registry(read_mode, write_mode);

CREATE OR REPLACE FUNCTION public.set_tenant_registry_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS set_tenant_registry_updated_at ON public.tenant_registry;
CREATE TRIGGER set_tenant_registry_updated_at
BEFORE UPDATE ON public.tenant_registry
FOR EACH ROW
EXECUTE FUNCTION public.set_tenant_registry_updated_at();

ALTER TABLE public.tenant_registry ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "tenant_registry_platform_admin_all" ON public.tenant_registry;
CREATE POLICY "tenant_registry_platform_admin_all"
ON public.tenant_registry
FOR ALL
USING (public.is_platform_admin())
WITH CHECK (public.is_platform_admin());

DROP POLICY IF EXISTS "tenant_registry_org_read" ON public.tenant_registry;
CREATE POLICY "tenant_registry_org_read"
ON public.tenant_registry
FOR SELECT
USING (organization_id = public.get_my_org());

-- Backfill existing organizations into the registry in public-table mode.
-- The suffix keeps names unique even when two org slugs sanitize to the same value.
INSERT INTO public.tenant_registry (organization_id, schema_name, status, read_mode, write_mode)
SELECT
  o.id,
  left(
    'tenant_' ||
    regexp_replace(lower(coalesce(nullif(o.slug, ''), o.name, o.id::text)), '[^a-z0-9]+', '_', 'g') ||
    '_' || replace(left(o.id::text, 8), '-', ''),
    63
  ) AS schema_name,
  'planned',
  'public',
  'public'
FROM public.organizations o
WHERE NOT EXISTS (
  SELECT 1 FROM public.tenant_registry tr WHERE tr.organization_id = o.id
);

COMMENT ON TABLE public.tenant_registry IS
  'Authoritative organization-to-tenant-schema mapping for the phased schema-per-tenant migration.';
COMMENT ON COLUMN public.tenant_registry.status IS
  'Provisioning lifecycle: planned, provisioning, active, migrating, failed, archived.';
COMMENT ON COLUMN public.tenant_registry.read_mode IS
  'Current read source for tenant data: public, dual, or tenant_schema.';
COMMENT ON COLUMN public.tenant_registry.write_mode IS
  'Current write target for tenant data: public, dual, or tenant_schema.';

COMMIT;

