-- ==========================================================================
-- Source: 20260618160000_provision_tenant_schema.sql
-- ==========================================================================

-- Phase 3: Secure tenant schema provisioning.
-- Creates per-tenant schemas from tenant_template without switching app reads/writes yet.

BEGIN;

CREATE OR REPLACE FUNCTION public.generate_tenant_schema_name(
  p_organization_id UUID,
  p_org_slug TEXT DEFAULT NULL,
  p_org_name TEXT DEFAULT NULL
)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  base_name TEXT;
  suffix TEXT;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  base_name := lower(coalesce(nullif(p_org_slug, ''), nullif(p_org_name, ''), p_organization_id::text));
  base_name := regexp_replace(base_name, '[^a-z0-9]+', '_', 'g');
  base_name := regexp_replace(base_name, '^_+|_+$', '', 'g');

  IF base_name = '' THEN
    base_name := replace(p_organization_id::text, '-', '_');
  END IF;

  suffix := replace(left(p_organization_id::text, 8), '-', '');
  RETURN left('tenant_' || base_name || '_' || suffix, 63);
END;
$$;

CREATE OR REPLACE FUNCTION public.provision_tenant_schema(p_organization_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  org_record RECORD;
  registry_record RECORD;
  schema_name TEXT;
  table_record RECORD;
  created_tables TEXT[] := ARRAY[]::TEXT[];
  skipped_tables TEXT[] := ARRAY[]::TEXT[];
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can provision tenant schemas';
  END IF;

  SELECT id, name, slug
  INTO org_record
  FROM public.organizations
  WHERE id = p_organization_id;

  IF org_record.id IS NULL THEN
    RAISE EXCEPTION 'Organization % does not exist', p_organization_id;
  END IF;

  SELECT *
  INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id
  FOR UPDATE;

  IF registry_record.organization_id IS NULL THEN
    schema_name := public.generate_tenant_schema_name(org_record.id, org_record.slug, org_record.name);

    INSERT INTO public.tenant_registry (
      organization_id,
      schema_name,
      status,
      read_mode,
      write_mode,
      metadata
    )
    VALUES (
      org_record.id,
      schema_name,
      'provisioning',
      'public',
      'public',
      jsonb_build_object('provisioned_by', 'provision_tenant_schema')
    )
    RETURNING * INTO registry_record;
  ELSE
    schema_name := registry_record.schema_name;

    IF registry_record.status = 'archived' THEN
      RAISE EXCEPTION 'Cannot provision archived tenant registry for organization %', p_organization_id;
    END IF;

    UPDATE public.tenant_registry
    SET status = 'provisioning',
        metadata = metadata || jsonb_build_object('last_provision_attempt_at', now())
    WHERE organization_id = p_organization_id
    RETURNING * INTO registry_record;
  END IF;

  IF schema_name !~ '^tenant_[a-z0-9_]+$' OR length(schema_name) > 63 THEN
    RAISE EXCEPTION 'Unsafe tenant schema name: %', schema_name;
  END IF;

  EXECUTE format('CREATE SCHEMA IF NOT EXISTS %I', schema_name);
  EXECUTE format('COMMENT ON SCHEMA %I IS %L', schema_name, 'Per-tenant operational schema for organization ' || p_organization_id::text);
  EXECUTE format('REVOKE ALL ON SCHEMA %I FROM PUBLIC', schema_name);
  EXECUTE format('REVOKE ALL ON SCHEMA %I FROM anon', schema_name);
  EXECUTE format('REVOKE ALL ON SCHEMA %I FROM authenticated', schema_name);
  EXECUTE format('GRANT USAGE ON SCHEMA %I TO service_role', schema_name);

  FOR table_record IN
    SELECT table_name, is_required
    FROM public.tenant_template_tables
    ORDER BY copy_order, table_name
  LOOP
    IF to_regclass(format('tenant_template.%I', table_record.table_name)) IS NULL THEN
      IF table_record.is_required THEN
        RAISE EXCEPTION 'Required template table tenant_template.% is missing', table_record.table_name;
      END IF;
      skipped_tables := array_append(skipped_tables, table_record.table_name);
      CONTINUE;
    END IF;

    EXECUTE format(
      'CREATE TABLE IF NOT EXISTS %I.%I (LIKE tenant_template.%I INCLUDING ALL)',
      schema_name,
      table_record.table_name,
      table_record.table_name
    );

    EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', schema_name, table_record.table_name);
    EXECUTE format('REVOKE ALL ON TABLE %I.%I FROM PUBLIC', schema_name, table_record.table_name);
    EXECUTE format('REVOKE ALL ON TABLE %I.%I FROM anon', schema_name, table_record.table_name);
    EXECUTE format('REVOKE ALL ON TABLE %I.%I FROM authenticated', schema_name, table_record.table_name);
    EXECUTE format('GRANT ALL ON TABLE %I.%I TO service_role', schema_name, table_record.table_name);
    EXECUTE format('COMMENT ON TABLE %I.%I IS %L', schema_name, table_record.table_name, 'Provisioned tenant table for organization ' || p_organization_id::text);

    created_tables := array_append(created_tables, table_record.table_name);
  END LOOP;

  UPDATE public.tenant_registry
  SET status = 'active',
      provisioned_at = COALESCE(provisioned_at, now()),
      metadata = metadata || jsonb_build_object(
        'last_provisioned_at', now(),
        'created_table_count', coalesce(array_length(created_tables, 1), 0),
        'skipped_tables', skipped_tables
      )
  WHERE organization_id = p_organization_id
  RETURNING * INTO registry_record;

  RETURN jsonb_build_object(
    'success', true,
    'organization_id', p_organization_id,
    'schema_name', schema_name,
    'status', registry_record.status,
    'read_mode', registry_record.read_mode,
    'write_mode', registry_record.write_mode,
    'created_tables', created_tables,
    'skipped_tables', skipped_tables
  );
EXCEPTION
  WHEN OTHERS THEN
    IF p_organization_id IS NOT NULL THEN
      UPDATE public.tenant_registry
      SET status = 'failed',
          metadata = metadata || jsonb_build_object(
            'last_error', SQLERRM,
            'last_failed_at', now()
          )
      WHERE organization_id = p_organization_id;
    END IF;
    RAISE;
END;
$$;

CREATE OR REPLACE FUNCTION public.provision_planned_tenant_schemas(p_limit INTEGER DEFAULT 10)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  org_record RECORD;
  results JSONB := '[]'::jsonb;
  provision_result JSONB;
  max_count INTEGER;
BEGIN
  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can provision tenant schemas';
  END IF;

  max_count := greatest(1, least(coalesce(p_limit, 10), 100));

  FOR org_record IN
    SELECT organization_id
    FROM public.tenant_registry
    WHERE status IN ('planned', 'failed')
    ORDER BY created_at
    LIMIT max_count
  LOOP
    provision_result := public.provision_tenant_schema(org_record.organization_id);
    results := results || jsonb_build_array(provision_result);
  END LOOP;

  RETURN jsonb_build_object('success', true, 'results', results);
END;
$$;

REVOKE ALL ON FUNCTION public.generate_tenant_schema_name(UUID, TEXT, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.generate_tenant_schema_name(UUID, TEXT, TEXT) TO service_role;

REVOKE ALL ON FUNCTION public.provision_tenant_schema(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.provision_tenant_schema(UUID) TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.provision_planned_tenant_schemas(INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.provision_planned_tenant_schemas(INTEGER) TO authenticated, service_role;

COMMENT ON FUNCTION public.provision_tenant_schema(UUID) IS
  'Creates a tenant schema from tenant_template for one organization. Does not switch read/write modes.';
COMMENT ON FUNCTION public.provision_planned_tenant_schemas(INTEGER) IS
  'Batch helper to provision planned/failed tenant_registry entries. Use cautiously from platform admin or service role contexts.';

COMMIT;

-- ==========================================================================
-- Source: 20260618161500_tenant_access_routing.sql
-- ==========================================================================

-- Phase 4: Tenant access/routing foundation.
-- Adds secure resolver functions for future backend/Edge data access. These functions
-- do not switch application reads/writes and do not expose generic schema querying.

BEGIN;

CREATE OR REPLACE FUNCTION public.get_tenant_runtime(p_organization_id UUID DEFAULT NULL)
RETURNS TABLE (
  organization_id UUID,
  schema_name TEXT,
  status TEXT,
  read_mode TEXT,
  write_mode TEXT,
  provisioned_at TIMESTAMPTZ,
  migrated_at TIMESTAMPTZ,
  last_validated_at TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  caller_org UUID;
  target_org UUID;
BEGIN
  caller_org := public.get_my_org();
  target_org := COALESCE(p_organization_id, caller_org);

  IF target_org IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role' OR target_org = caller_org) THEN
    RAISE EXCEPTION 'Cannot resolve tenant runtime outside caller organization';
  END IF;

  RETURN QUERY
  SELECT
    tr.organization_id,
    tr.schema_name,
    tr.status,
    tr.read_mode,
    tr.write_mode,
    tr.provisioned_at,
    tr.migrated_at,
    tr.last_validated_at
  FROM public.tenant_registry tr
  WHERE tr.organization_id = target_org;
END;
$$;

CREATE OR REPLACE FUNCTION public.resolve_tenant_schema(p_organization_id UUID DEFAULT NULL)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  runtime_record RECORD;
BEGIN
  SELECT * INTO runtime_record
  FROM public.get_tenant_runtime(p_organization_id)
  LIMIT 1;

  IF runtime_record.organization_id IS NULL THEN
    RAISE EXCEPTION 'Tenant registry entry not found';
  END IF;

  IF runtime_record.status NOT IN ('active', 'migrating') THEN
    RAISE EXCEPTION 'Tenant schema is not ready. Current status: %', runtime_record.status;
  END IF;

  IF runtime_record.schema_name !~ '^tenant_[a-z0-9_]+$' OR length(runtime_record.schema_name) > 63 THEN
    RAISE EXCEPTION 'Unsafe tenant schema name: %', runtime_record.schema_name;
  END IF;

  RETURN runtime_record.schema_name;
END;
$$;

CREATE OR REPLACE FUNCTION public.assert_tenant_scope(
  p_organization_id UUID,
  p_brand_id UUID DEFAULT NULL,
  p_location_id UUID DEFAULT NULL
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  caller_org UUID;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  caller_org := public.get_my_org();

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role' OR p_organization_id = caller_org) THEN
    RAISE EXCEPTION 'Organization is outside caller tenant';
  END IF;

  IF p_brand_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.brands b
      WHERE b.brand_id = p_brand_id
        AND b.organization_id = p_organization_id
        AND (
          public.is_platform_admin()
          OR (SELECT auth.role()) = 'service_role'
          OR p_brand_id IN (SELECT public.get_my_accessible_brand_ids())
        )
    ) THEN
      RAISE EXCEPTION 'Brand is outside caller tenant scope';
    END IF;
  END IF;

  IF p_location_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.locations l
      WHERE l.id = p_location_id
        AND l.organization_id = p_organization_id
        AND (p_brand_id IS NULL OR l.brand_id = p_brand_id)
        AND (
          public.is_platform_admin()
          OR (SELECT auth.role()) = 'service_role'
          OR p_location_id IN (SELECT public.get_my_accessible_location_ids())
        )
    ) THEN
      RAISE EXCEPTION 'Location is outside caller tenant scope';
    END IF;
  END IF;

  RETURN TRUE;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_tenant_data_route(
  p_organization_id UUID DEFAULT NULL,
  p_brand_id UUID DEFAULT NULL,
  p_location_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  runtime_record RECORD;
  target_org UUID;
BEGIN
  target_org := COALESCE(p_organization_id, public.get_my_org());

  PERFORM public.assert_tenant_scope(target_org, p_brand_id, p_location_id);

  SELECT * INTO runtime_record
  FROM public.get_tenant_runtime(target_org)
  LIMIT 1;

  IF runtime_record.organization_id IS NULL THEN
    RETURN jsonb_build_object(
      'organization_id', target_org,
      'schema_name', NULL,
      'status', 'unregistered',
      'read_mode', 'public',
      'write_mode', 'public',
      'read_source', 'public',
      'write_target', 'public'
    );
  END IF;

  RETURN jsonb_build_object(
    'organization_id', runtime_record.organization_id,
    'schema_name', runtime_record.schema_name,
    'status', runtime_record.status,
    'read_mode', runtime_record.read_mode,
    'write_mode', runtime_record.write_mode,
    'read_source', CASE WHEN runtime_record.read_mode = 'tenant_schema' THEN runtime_record.schema_name ELSE 'public' END,
    'write_target', CASE WHEN runtime_record.write_mode = 'tenant_schema' THEN runtime_record.schema_name ELSE 'public' END,
    'brand_id', p_brand_id,
    'location_id', p_location_id
  );
END;
$$;

REVOKE ALL ON FUNCTION public.get_tenant_runtime(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_tenant_runtime(UUID) TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.resolve_tenant_schema(UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_tenant_schema(UUID) TO service_role;

REVOKE ALL ON FUNCTION public.assert_tenant_scope(UUID, UUID, UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.assert_tenant_scope(UUID, UUID, UUID) TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.get_tenant_data_route(UUID, UUID, UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_tenant_data_route(UUID, UUID, UUID) TO authenticated, service_role;

COMMENT ON FUNCTION public.get_tenant_runtime(UUID) IS
  'Returns tenant registry runtime state for caller org, platform admins, or service role.';
COMMENT ON FUNCTION public.resolve_tenant_schema(UUID) IS
  'Service-role resolver for the provisioned tenant schema name. Not granted to browser clients.';
COMMENT ON FUNCTION public.assert_tenant_scope(UUID, UUID, UUID) IS
  'Validates organization/brand/location scope before backend code routes tenant data access.';
COMMENT ON FUNCTION public.get_tenant_data_route(UUID, UUID, UUID) IS
  'Returns current public-vs-tenant routing mode after validating caller scope. Does not perform generic data access.';

COMMIT;

-- ==========================================================================
-- Source: 20260618163000_dual_write_mirror_infrastructure.sql
-- ==========================================================================

-- Phase 5: Dual-write mirror infrastructure.
-- Adds opt-in public -> tenant schema write mirroring for provisioned tenants.
-- Existing tenants remain unchanged because tenant_registry.write_mode is still 'public'.

BEGIN;

CREATE TABLE IF NOT EXISTS public.tenant_mirror_tables (
  table_name TEXT PRIMARY KEY,
  enabled BOOLEAN NOT NULL DEFAULT true,
  has_trigger BOOLEAN NOT NULL DEFAULT false,
  last_checked_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.tenant_mirror_tables ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "tenant_mirror_tables_platform_admin_all" ON public.tenant_mirror_tables;
CREATE POLICY "tenant_mirror_tables_platform_admin_all"
ON public.tenant_mirror_tables
FOR ALL
USING (public.is_platform_admin())
WITH CHECK (public.is_platform_admin());

DROP POLICY IF EXISTS "tenant_mirror_tables_authenticated_read" ON public.tenant_mirror_tables;
CREATE POLICY "tenant_mirror_tables_authenticated_read"
ON public.tenant_mirror_tables
FOR SELECT
USING (auth.uid() IS NOT NULL);

CREATE OR REPLACE FUNCTION public.set_tenant_mirror_tables_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS set_tenant_mirror_tables_updated_at ON public.tenant_mirror_tables;
CREATE TRIGGER set_tenant_mirror_tables_updated_at
BEFORE UPDATE ON public.tenant_mirror_tables
FOR EACH ROW
EXECUTE FUNCTION public.set_tenant_mirror_tables_updated_at();

INSERT INTO public.tenant_mirror_tables (table_name, enabled, notes)
SELECT table_name, true, 'Mirrored from public writes when tenant write_mode is dual or tenant_schema.'
FROM public.tenant_template_tables
ON CONFLICT (table_name) DO UPDATE SET
  enabled = EXCLUDED.enabled,
  notes = EXCLUDED.notes,
  last_checked_at = now();

CREATE OR REPLACE FUNCTION public.mirror_public_row_to_tenant_schema()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  row_payload JSONB;
  org_id UUID;
  target_schema TEXT;
  target_status TEXT;
  target_write_mode TEXT;
  target_table REGCLASS;
  id_text TEXT;
  column_list TEXT;
  update_list TEXT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    row_payload := to_jsonb(OLD);
  ELSE
    row_payload := to_jsonb(NEW);
  END IF;

  org_id := NULLIF(row_payload->>'organization_id', '')::UUID;

  IF org_id IS NULL THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  SELECT tr.schema_name, tr.status, tr.write_mode
  INTO target_schema, target_status, target_write_mode
  FROM public.tenant_registry tr
  WHERE tr.organization_id = org_id;

  IF target_schema IS NULL OR target_status NOT IN ('active', 'migrating') OR target_write_mode NOT IN ('dual', 'tenant_schema') THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF target_schema !~ '^tenant_[a-z0-9_]+$' OR length(target_schema) > 63 THEN
    RAISE EXCEPTION 'Unsafe tenant schema name: %', target_schema;
  END IF;

  target_table := to_regclass(format('%I.%I', target_schema, TG_TABLE_NAME));
  IF target_table IS NULL THEN
    RAISE EXCEPTION 'Tenant mirror table %.% does not exist', target_schema, TG_TABLE_NAME;
  END IF;

  id_text := row_payload->>'id';
  IF id_text IS NULL THEN
    RAISE EXCEPTION 'Cannot mirror %.% without id column', target_schema, TG_TABLE_NAME;
  END IF;

  IF TG_OP = 'DELETE' THEN
    EXECUTE format('DELETE FROM %I.%I WHERE id::text = $1', target_schema, TG_TABLE_NAME)
    USING id_text;
    RETURN OLD;
  END IF;

  SELECT
    string_agg(format('%I', a.attname), ', ' ORDER BY a.attnum),
    string_agg(format('%I = EXCLUDED.%I', a.attname, a.attname), ', ' ORDER BY a.attnum)
  INTO column_list, update_list
  FROM pg_catalog.pg_attribute a
  WHERE a.attrelid = target_table
    AND a.attnum > 0
    AND NOT a.attisdropped
    AND a.attgenerated = ''
    AND a.attname <> 'id';

  IF column_list IS NULL THEN
    EXECUTE format(
      'INSERT INTO %I.%I (id) SELECT id FROM jsonb_populate_record(NULL::%I.%I, $1) ON CONFLICT (id) DO NOTHING',
      target_schema,
      TG_TABLE_NAME,
      target_schema,
      TG_TABLE_NAME
    )
    USING row_payload;
  ELSE
    EXECUTE format(
      'INSERT INTO %I.%I (id, %s) SELECT id, %s FROM jsonb_populate_record(NULL::%I.%I, $1) ON CONFLICT (id) DO UPDATE SET %s',
      target_schema,
      TG_TABLE_NAME,
      column_list,
      column_list,
      target_schema,
      TG_TABLE_NAME,
      update_list
    )
    USING row_payload;
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.install_tenant_mirror_triggers()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  table_record RECORD;
  installed TEXT[] := ARRAY[]::TEXT[];
  skipped JSONB := '[]'::jsonb;
  table_reg REGCLASS;
  has_org_id BOOLEAN;
  has_id BOOLEAN;
BEGIN
  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can install tenant mirror triggers';
  END IF;

  FOR table_record IN
    SELECT tmt.table_name
    FROM public.tenant_mirror_tables tmt
    WHERE tmt.enabled = true
    ORDER BY tmt.table_name
  LOOP
    table_reg := to_regclass(format('public.%I', table_record.table_name));

    IF table_reg IS NULL THEN
      skipped := skipped || jsonb_build_array(jsonb_build_object('table', table_record.table_name, 'reason', 'missing public table'));
      UPDATE public.tenant_mirror_tables SET has_trigger = false, last_checked_at = now(), notes = 'Skipped: missing public table' WHERE table_name = table_record.table_name;
      CONTINUE;
    END IF;

    SELECT EXISTS (
      SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid = table_reg AND attname = 'organization_id' AND attnum > 0 AND NOT attisdropped
    ) INTO has_org_id;

    SELECT EXISTS (
      SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid = table_reg AND attname = 'id' AND attnum > 0 AND NOT attisdropped
    ) INTO has_id;

    IF NOT has_org_id OR NOT has_id THEN
      skipped := skipped || jsonb_build_array(jsonb_build_object('table', table_record.table_name, 'reason', 'requires id and organization_id columns'));
      UPDATE public.tenant_mirror_tables SET has_trigger = false, last_checked_at = now(), notes = 'Skipped: requires id and organization_id columns' WHERE table_name = table_record.table_name;
      CONTINUE;
    END IF;

    EXECUTE format('DROP TRIGGER IF EXISTS tenant_mirror_dual_write ON public.%I', table_record.table_name);
    EXECUTE format(
      'CREATE TRIGGER tenant_mirror_dual_write AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.mirror_public_row_to_tenant_schema()',
      table_record.table_name
    );

    installed := array_append(installed, table_record.table_name);
    UPDATE public.tenant_mirror_tables SET has_trigger = true, last_checked_at = now(), notes = 'Trigger installed' WHERE table_name = table_record.table_name;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'installed', installed, 'skipped', skipped);
END;
$$;

CREATE OR REPLACE FUNCTION public.set_tenant_write_mode(
  p_organization_id UUID,
  p_write_mode TEXT,
  p_read_mode TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
BEGIN
  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can set tenant modes';
  END IF;

  IF p_write_mode NOT IN ('public', 'dual', 'tenant_schema') THEN
    RAISE EXCEPTION 'Invalid write mode: %', p_write_mode;
  END IF;

  IF p_read_mode IS NOT NULL AND p_read_mode NOT IN ('public', 'dual', 'tenant_schema') THEN
    RAISE EXCEPTION 'Invalid read mode: %', p_read_mode;
  END IF;

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id
  FOR UPDATE;

  IF registry_record.organization_id IS NULL THEN
    RAISE EXCEPTION 'Tenant registry entry not found for organization %', p_organization_id;
  END IF;

  IF p_write_mode IN ('dual', 'tenant_schema') AND registry_record.status NOT IN ('active', 'migrating') THEN
    RAISE EXCEPTION 'Tenant schema must be active before enabling % write mode. Current status: %', p_write_mode, registry_record.status;
  END IF;

  UPDATE public.tenant_registry
  SET write_mode = p_write_mode,
      read_mode = COALESCE(p_read_mode, read_mode),
      metadata = metadata || jsonb_build_object('last_mode_change_at', now())
  WHERE organization_id = p_organization_id
  RETURNING * INTO registry_record;

  RETURN jsonb_build_object(
    'success', true,
    'organization_id', registry_record.organization_id,
    'schema_name', registry_record.schema_name,
    'status', registry_record.status,
    'read_mode', registry_record.read_mode,
    'write_mode', registry_record.write_mode
  );
END;
$$;

-- Install triggers now through migration context. They are inert for all tenants
-- whose write_mode remains 'public'. Runtime reinstall still goes through the
-- permission-checked public.install_tenant_mirror_triggers() function above.
DO $$
DECLARE
  table_record RECORD;
  table_reg REGCLASS;
  has_org_id BOOLEAN;
  has_id BOOLEAN;
BEGIN
  FOR table_record IN
    SELECT tmt.table_name
    FROM public.tenant_mirror_tables tmt
    WHERE tmt.enabled = true
    ORDER BY tmt.table_name
  LOOP
    table_reg := to_regclass(format('public.%I', table_record.table_name));

    IF table_reg IS NULL THEN
      UPDATE public.tenant_mirror_tables SET has_trigger = false, last_checked_at = now(), notes = 'Skipped: missing public table' WHERE table_name = table_record.table_name;
      CONTINUE;
    END IF;

    SELECT EXISTS (
      SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid = table_reg AND attname = 'organization_id' AND attnum > 0 AND NOT attisdropped
    ) INTO has_org_id;

    SELECT EXISTS (
      SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid = table_reg AND attname = 'id' AND attnum > 0 AND NOT attisdropped
    ) INTO has_id;

    IF NOT has_org_id OR NOT has_id THEN
      UPDATE public.tenant_mirror_tables SET has_trigger = false, last_checked_at = now(), notes = 'Skipped: requires id and organization_id columns' WHERE table_name = table_record.table_name;
      CONTINUE;
    END IF;

    EXECUTE format('DROP TRIGGER IF EXISTS tenant_mirror_dual_write ON public.%I', table_record.table_name);
    EXECUTE format(
      'CREATE TRIGGER tenant_mirror_dual_write AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.mirror_public_row_to_tenant_schema()',
      table_record.table_name
    );

    UPDATE public.tenant_mirror_tables SET has_trigger = true, last_checked_at = now(), notes = 'Trigger installed' WHERE table_name = table_record.table_name;
  END LOOP;
END;
$$;

REVOKE ALL ON FUNCTION public.mirror_public_row_to_tenant_schema() FROM PUBLIC, anon, authenticated;

REVOKE ALL ON FUNCTION public.install_tenant_mirror_triggers() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.install_tenant_mirror_triggers() TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.set_tenant_write_mode(UUID, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_tenant_write_mode(UUID, TEXT, TEXT) TO authenticated, service_role;

COMMENT ON FUNCTION public.mirror_public_row_to_tenant_schema() IS
  'Generic trigger function that mirrors public table writes into the provisioned tenant schema only when write_mode is dual or tenant_schema.';
COMMENT ON FUNCTION public.install_tenant_mirror_triggers() IS
  'Installs opt-in dual-write triggers on eligible public operational tables.';
COMMENT ON FUNCTION public.set_tenant_write_mode(UUID, TEXT, TEXT) IS
  'Platform/service helper to set tenant read/write modes after provisioning and validation.';
COMMENT ON TABLE public.tenant_mirror_tables IS
  'Operational tables eligible for public-to-tenant-schema dual-write mirroring.';

COMMIT;

-- ==========================================================================
-- Source: 20260618164500_tenant_backfill_validation.sql
-- ==========================================================================

-- Phase 6: Tenant schema backfill and validation.
-- Adds guarded RPCs to copy existing public tenant rows into provisioned tenant schemas
-- and validate counts. Does not switch read/write modes.

BEGIN;

CREATE TABLE IF NOT EXISTS public.tenant_backfill_runs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  schema_name TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'running',
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  completed_at TIMESTAMPTZ,
  requested_by UUID DEFAULT auth.uid(),
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  CONSTRAINT tenant_backfill_runs_status_check CHECK (status IN ('running', 'completed', 'failed'))
);

CREATE TABLE IF NOT EXISTS public.tenant_backfill_table_results (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  run_id UUID NOT NULL REFERENCES public.tenant_backfill_runs(id) ON DELETE CASCADE,
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  schema_name TEXT NOT NULL,
  table_name TEXT NOT NULL,
  public_count BIGINT NOT NULL DEFAULT 0,
  tenant_count BIGINT NOT NULL DEFAULT 0,
  affected_rows BIGINT NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'pending',
  error_message TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT tenant_backfill_table_results_status_check CHECK (status IN ('copied', 'validated', 'skipped', 'failed'))
);

CREATE INDEX IF NOT EXISTS idx_tenant_backfill_runs_org ON public.tenant_backfill_runs(organization_id, started_at DESC);
CREATE INDEX IF NOT EXISTS idx_tenant_backfill_table_results_run ON public.tenant_backfill_table_results(run_id);
CREATE INDEX IF NOT EXISTS idx_tenant_backfill_table_results_org_table ON public.tenant_backfill_table_results(organization_id, table_name);

ALTER TABLE public.tenant_backfill_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tenant_backfill_table_results ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "tenant_backfill_runs_platform_admin_all" ON public.tenant_backfill_runs;
CREATE POLICY "tenant_backfill_runs_platform_admin_all"
ON public.tenant_backfill_runs
FOR ALL
USING (public.is_platform_admin())
WITH CHECK (public.is_platform_admin());

DROP POLICY IF EXISTS "tenant_backfill_runs_org_read" ON public.tenant_backfill_runs;
CREATE POLICY "tenant_backfill_runs_org_read"
ON public.tenant_backfill_runs
FOR SELECT
USING (organization_id = public.get_my_org());

DROP POLICY IF EXISTS "tenant_backfill_results_platform_admin_all" ON public.tenant_backfill_table_results;
CREATE POLICY "tenant_backfill_results_platform_admin_all"
ON public.tenant_backfill_table_results
FOR ALL
USING (public.is_platform_admin())
WITH CHECK (public.is_platform_admin());

DROP POLICY IF EXISTS "tenant_backfill_results_org_read" ON public.tenant_backfill_table_results;
CREATE POLICY "tenant_backfill_results_org_read"
ON public.tenant_backfill_table_results
FOR SELECT
USING (organization_id = public.get_my_org());

CREATE OR REPLACE FUNCTION public.backfill_tenant_schema(
  p_organization_id UUID,
  p_table_name TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  run_id UUID;
  table_record RECORD;
  table_reg REGCLASS;
  target_reg REGCLASS;
  has_org_id BOOLEAN;
  has_id BOOLEAN;
  column_list TEXT;
  update_list TEXT;
  public_count BIGINT;
  tenant_count BIGINT;
  affected_rows BIGINT;
  copied_tables TEXT[] := ARRAY[]::TEXT[];
  skipped_tables JSONB := '[]'::jsonb;
  failed_tables JSONB := '[]'::jsonb;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can backfill tenant schemas';
  END IF;

  IF p_table_name IS NOT NULL AND p_table_name !~ '^[a-z0-9_]+$' THEN
    RAISE EXCEPTION 'Unsafe table name: %', p_table_name;
  END IF;

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id
  FOR UPDATE;

  IF registry_record.organization_id IS NULL OR registry_record.status IN ('planned', 'failed') THEN
    PERFORM public.provision_tenant_schema(p_organization_id);
    SELECT * INTO registry_record
    FROM public.tenant_registry
    WHERE organization_id = p_organization_id
    FOR UPDATE;
  END IF;

  IF registry_record.status NOT IN ('active', 'migrating') THEN
    RAISE EXCEPTION 'Tenant schema must be active before backfill. Current status: %', registry_record.status;
  END IF;

  IF registry_record.schema_name !~ '^tenant_[a-z0-9_]+$' OR length(registry_record.schema_name) > 63 THEN
    RAISE EXCEPTION 'Unsafe tenant schema name: %', registry_record.schema_name;
  END IF;

  INSERT INTO public.tenant_backfill_runs (organization_id, schema_name, status, metadata)
  VALUES (
    p_organization_id,
    registry_record.schema_name,
    'running',
    jsonb_build_object('table_name', p_table_name, 'started_from', 'backfill_tenant_schema')
  )
  RETURNING id INTO run_id;

  UPDATE public.tenant_registry
  SET status = 'migrating',
      metadata = metadata || jsonb_build_object('last_backfill_started_at', now(), 'last_backfill_run_id', run_id)
  WHERE organization_id = p_organization_id;

  FOR table_record IN
    SELECT tmt.table_name
    FROM public.tenant_mirror_tables tmt
    WHERE tmt.enabled = true
      AND (p_table_name IS NULL OR tmt.table_name = p_table_name)
    ORDER BY tmt.table_name
  LOOP
    BEGIN
      table_reg := to_regclass(format('public.%I', table_record.table_name));
      target_reg := to_regclass(format('%I.%I', registry_record.schema_name, table_record.table_name));

      IF table_reg IS NULL OR target_reg IS NULL THEN
        skipped_tables := skipped_tables || jsonb_build_array(jsonb_build_object('table', table_record.table_name, 'reason', 'missing source or target table'));
        INSERT INTO public.tenant_backfill_table_results (run_id, organization_id, schema_name, table_name, status, error_message)
        VALUES (run_id, p_organization_id, registry_record.schema_name, table_record.table_name, 'skipped', 'missing source or target table');
        CONTINUE;
      END IF;

      SELECT EXISTS (
        SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid = table_reg AND attname = 'organization_id' AND attnum > 0 AND NOT attisdropped
      ) INTO has_org_id;

      SELECT EXISTS (
        SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid = table_reg AND attname = 'id' AND attnum > 0 AND NOT attisdropped
      ) INTO has_id;

      IF NOT has_org_id OR NOT has_id THEN
        skipped_tables := skipped_tables || jsonb_build_array(jsonb_build_object('table', table_record.table_name, 'reason', 'requires id and organization_id columns'));
        INSERT INTO public.tenant_backfill_table_results (run_id, organization_id, schema_name, table_name, status, error_message)
        VALUES (run_id, p_organization_id, registry_record.schema_name, table_record.table_name, 'skipped', 'requires id and organization_id columns');
        CONTINUE;
      END IF;

      SELECT
        string_agg(format('%I', source_columns.column_name), ', ' ORDER BY source_columns.ordinal_position),
        string_agg(format('%I = EXCLUDED.%I', source_columns.column_name, source_columns.column_name), ', ' ORDER BY source_columns.ordinal_position)
      INTO column_list, update_list
      FROM information_schema.columns source_columns
      INNER JOIN information_schema.columns target_columns
        ON target_columns.table_schema = registry_record.schema_name
       AND target_columns.table_name = table_record.table_name
       AND target_columns.column_name = source_columns.column_name
      WHERE source_columns.table_schema = 'public'
        AND source_columns.table_name = table_record.table_name
        AND source_columns.is_generated = 'NEVER'
        AND source_columns.is_identity = 'NO';

      IF column_list IS NULL THEN
        skipped_tables := skipped_tables || jsonb_build_array(jsonb_build_object('table', table_record.table_name, 'reason', 'no copyable columns'));
        INSERT INTO public.tenant_backfill_table_results (run_id, organization_id, schema_name, table_name, status, error_message)
        VALUES (run_id, p_organization_id, registry_record.schema_name, table_record.table_name, 'skipped', 'no copyable columns');
        CONTINUE;
      END IF;

      SELECT
        string_agg(format('%I = EXCLUDED.%I', source_columns.column_name, source_columns.column_name), ', ' ORDER BY source_columns.ordinal_position)
      INTO update_list
      FROM information_schema.columns source_columns
      INNER JOIN information_schema.columns target_columns
        ON target_columns.table_schema = registry_record.schema_name
       AND target_columns.table_name = table_record.table_name
       AND target_columns.column_name = source_columns.column_name
      WHERE source_columns.table_schema = 'public'
        AND source_columns.table_name = table_record.table_name
        AND source_columns.column_name <> 'id'
        AND source_columns.is_generated = 'NEVER'
        AND source_columns.is_identity = 'NO';

      EXECUTE format('SELECT count(*) FROM public.%I WHERE organization_id = $1', table_record.table_name)
      INTO public_count
      USING p_organization_id;

      IF update_list IS NULL THEN
        EXECUTE format(
          'INSERT INTO %I.%I (%s) SELECT %s FROM public.%I WHERE organization_id = $1 ON CONFLICT (id) DO NOTHING',
          registry_record.schema_name,
          table_record.table_name,
          column_list,
          column_list,
          table_record.table_name
        )
        USING p_organization_id;
      ELSE
        EXECUTE format(
          'INSERT INTO %I.%I (%s) SELECT %s FROM public.%I WHERE organization_id = $1 ON CONFLICT (id) DO UPDATE SET %s',
          registry_record.schema_name,
          table_record.table_name,
          column_list,
          column_list,
          table_record.table_name,
          update_list
        )
        USING p_organization_id;
      END IF;

      GET DIAGNOSTICS affected_rows = ROW_COUNT;

      EXECUTE format('SELECT count(*) FROM %I.%I WHERE organization_id = $1', registry_record.schema_name, table_record.table_name)
      INTO tenant_count
      USING p_organization_id;

      INSERT INTO public.tenant_backfill_table_results (
        run_id,
        organization_id,
        schema_name,
        table_name,
        public_count,
        tenant_count,
        affected_rows,
        status
      ) VALUES (
        run_id,
        p_organization_id,
        registry_record.schema_name,
        table_record.table_name,
        public_count,
        tenant_count,
        affected_rows,
        CASE WHEN tenant_count >= public_count THEN 'validated' ELSE 'failed' END
      );

      IF tenant_count >= public_count THEN
        copied_tables := array_append(copied_tables, table_record.table_name);
      ELSE
        failed_tables := failed_tables || jsonb_build_array(jsonb_build_object('table', table_record.table_name, 'public_count', public_count, 'tenant_count', tenant_count));
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        failed_tables := failed_tables || jsonb_build_array(jsonb_build_object('table', table_record.table_name, 'error', SQLERRM));
        INSERT INTO public.tenant_backfill_table_results (run_id, organization_id, schema_name, table_name, status, error_message)
        VALUES (run_id, p_organization_id, registry_record.schema_name, table_record.table_name, 'failed', SQLERRM);
    END;
  END LOOP;

  IF jsonb_array_length(failed_tables) > 0 THEN
    UPDATE public.tenant_backfill_runs
    SET status = 'failed', completed_at = now(), metadata = metadata || jsonb_build_object('failed_tables', failed_tables, 'skipped_tables', skipped_tables)
    WHERE id = run_id;

    UPDATE public.tenant_registry
    SET status = 'failed',
        metadata = metadata || jsonb_build_object('last_backfill_failed_at', now(), 'last_backfill_run_id', run_id, 'failed_tables', failed_tables)
    WHERE organization_id = p_organization_id;
  ELSE
    UPDATE public.tenant_backfill_runs
    SET status = 'completed', completed_at = now(), metadata = metadata || jsonb_build_object('copied_tables', copied_tables, 'skipped_tables', skipped_tables)
    WHERE id = run_id;

    UPDATE public.tenant_registry
    SET status = 'active',
        migrated_at = COALESCE(migrated_at, now()),
        last_validated_at = now(),
        metadata = metadata || jsonb_build_object('last_backfill_completed_at', now(), 'last_backfill_run_id', run_id)
    WHERE organization_id = p_organization_id;
  END IF;

  RETURN jsonb_build_object(
    'success', jsonb_array_length(failed_tables) = 0,
    'run_id', run_id,
    'organization_id', p_organization_id,
    'schema_name', registry_record.schema_name,
    'copied_tables', copied_tables,
    'skipped_tables', skipped_tables,
    'failed_tables', failed_tables
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.validate_tenant_backfill_counts(p_organization_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  table_record RECORD;
  table_reg REGCLASS;
  target_reg REGCLASS;
  public_count BIGINT;
  tenant_count BIGINT;
  mismatches JSONB := '[]'::jsonb;
  checked_tables TEXT[] := ARRAY[]::TEXT[];
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role' OR p_organization_id = public.get_my_org()) THEN
    RAISE EXCEPTION 'Insufficient permissions to validate tenant schema';
  END IF;

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id;

  IF registry_record.organization_id IS NULL THEN
    RAISE EXCEPTION 'Tenant registry entry not found for organization %', p_organization_id;
  END IF;

  FOR table_record IN
    SELECT table_name
    FROM public.tenant_mirror_tables
    WHERE enabled = true
    ORDER BY table_name
  LOOP
    table_reg := to_regclass(format('public.%I', table_record.table_name));
    target_reg := to_regclass(format('%I.%I', registry_record.schema_name, table_record.table_name));

    IF table_reg IS NULL OR target_reg IS NULL THEN
      CONTINUE;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid = table_reg AND attname = 'organization_id' AND attnum > 0 AND NOT attisdropped
    ) THEN
      CONTINUE;
    END IF;

    EXECUTE format('SELECT count(*) FROM public.%I WHERE organization_id = $1', table_record.table_name)
    INTO public_count
    USING p_organization_id;

    EXECUTE format('SELECT count(*) FROM %I.%I WHERE organization_id = $1', registry_record.schema_name, table_record.table_name)
    INTO tenant_count
    USING p_organization_id;

    checked_tables := array_append(checked_tables, table_record.table_name);

    IF tenant_count < public_count THEN
      mismatches := mismatches || jsonb_build_array(jsonb_build_object('table', table_record.table_name, 'public_count', public_count, 'tenant_count', tenant_count));
    END IF;
  END LOOP;

  IF jsonb_array_length(mismatches) = 0 THEN
    UPDATE public.tenant_registry
    SET last_validated_at = now(),
        metadata = metadata || jsonb_build_object('last_count_validation_at', now())
    WHERE organization_id = p_organization_id;
  END IF;

  RETURN jsonb_build_object(
    'success', jsonb_array_length(mismatches) = 0,
    'organization_id', p_organization_id,
    'schema_name', registry_record.schema_name,
    'checked_tables', checked_tables,
    'mismatches', mismatches
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.backfill_planned_tenant_schemas(p_limit INTEGER DEFAULT 5)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  results JSONB := '[]'::jsonb;
  backfill_result JSONB;
  max_count INTEGER;
BEGIN
  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can backfill tenant schemas';
  END IF;

  max_count := greatest(1, least(coalesce(p_limit, 5), 50));

  FOR registry_record IN
    SELECT organization_id
    FROM public.tenant_registry
    WHERE read_mode = 'public'
      AND write_mode = 'public'
      AND status IN ('planned', 'active', 'failed')
    ORDER BY created_at
    LIMIT max_count
  LOOP
    backfill_result := public.backfill_tenant_schema(registry_record.organization_id);
    results := results || jsonb_build_array(backfill_result);
  END LOOP;

  RETURN jsonb_build_object('success', true, 'results', results);
END;
$$;

REVOKE ALL ON FUNCTION public.backfill_tenant_schema(UUID, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.backfill_tenant_schema(UUID, TEXT) TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.validate_tenant_backfill_counts(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.validate_tenant_backfill_counts(UUID) TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.backfill_planned_tenant_schemas(INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.backfill_planned_tenant_schemas(INTEGER) TO authenticated, service_role;

COMMENT ON TABLE public.tenant_backfill_runs IS
  'Audit records for tenant schema backfill runs from public shared tables.';
COMMENT ON TABLE public.tenant_backfill_table_results IS
  'Per-table results and count validation from tenant schema backfill runs.';
COMMENT ON FUNCTION public.backfill_tenant_schema(UUID, TEXT) IS
  'Copies one organization from public operational tables into its provisioned tenant schema. Does not change read/write modes.';
COMMENT ON FUNCTION public.validate_tenant_backfill_counts(UUID) IS
  'Compares public and tenant schema row counts for one organization.';
COMMENT ON FUNCTION public.backfill_planned_tenant_schemas(INTEGER) IS
  'Batch helper for backfilling planned/active/failed tenant registry entries that still read/write public tables.';

COMMIT;

-- ==========================================================================
-- Source: 20260618170000_tenant_read_cutover_controls.sql
-- ==========================================================================

-- Phase 7: Tenant read-switch controls.
-- Adds guarded cutover helpers for moving one tenant at a time from public reads
-- to tenant schema reads after backfill validation. Does not switch any tenant.

BEGIN;

CREATE TABLE IF NOT EXISTS public.tenant_cutover_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  schema_name TEXT,
  previous_read_mode TEXT,
  new_read_mode TEXT NOT NULL,
  previous_write_mode TEXT,
  new_write_mode TEXT,
  status TEXT NOT NULL DEFAULT 'requested',
  validation JSONB NOT NULL DEFAULT '{}'::jsonb,
  requested_by UUID DEFAULT auth.uid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT tenant_cutover_events_status_check CHECK (status IN ('requested', 'applied', 'blocked', 'rolled_back')),
  CONSTRAINT tenant_cutover_events_read_mode_check CHECK (new_read_mode IN ('public', 'dual', 'tenant_schema')),
  CONSTRAINT tenant_cutover_events_write_mode_check CHECK (new_write_mode IS NULL OR new_write_mode IN ('public', 'dual', 'tenant_schema'))
);

CREATE INDEX IF NOT EXISTS idx_tenant_cutover_events_org_created ON public.tenant_cutover_events(organization_id, created_at DESC);

ALTER TABLE public.tenant_cutover_events ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "tenant_cutover_events_platform_admin_all" ON public.tenant_cutover_events;
CREATE POLICY "tenant_cutover_events_platform_admin_all"
ON public.tenant_cutover_events
FOR ALL
USING (public.is_platform_admin())
WITH CHECK (public.is_platform_admin());

DROP POLICY IF EXISTS "tenant_cutover_events_org_read" ON public.tenant_cutover_events;
CREATE POLICY "tenant_cutover_events_org_read"
ON public.tenant_cutover_events
FOR SELECT
USING (organization_id = public.get_my_org());

CREATE OR REPLACE FUNCTION public.get_tenant_cutover_status(p_organization_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  validation_result JSONB;
  latest_run RECORD;
  blockers JSONB := '[]'::jsonb;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role' OR p_organization_id = public.get_my_org()) THEN
    RAISE EXCEPTION 'Insufficient permissions to inspect tenant cutover status';
  END IF;

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id;

  IF registry_record.organization_id IS NULL THEN
    RAISE EXCEPTION 'Tenant registry entry not found for organization %', p_organization_id;
  END IF;

  IF registry_record.status NOT IN ('active', 'migrating') THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'tenant registry is not active', 'status', registry_record.status));
  END IF;

  IF registry_record.schema_name IS NULL OR registry_record.schema_name !~ '^tenant_[a-z0-9_]+$' THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'missing or unsafe tenant schema name'));
  ELSIF to_regnamespace(registry_record.schema_name) IS NULL THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'tenant schema does not exist', 'schema_name', registry_record.schema_name));
  END IF;

  SELECT * INTO latest_run
  FROM public.tenant_backfill_runs
  WHERE organization_id = p_organization_id
    AND schema_name = registry_record.schema_name
  ORDER BY started_at DESC
  LIMIT 1;

  IF latest_run.id IS NULL THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'no backfill run found'));
  ELSIF latest_run.status <> 'completed' THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'latest backfill run is not completed', 'run_id', latest_run.id, 'status', latest_run.status));
  END IF;

  validation_result := public.validate_tenant_backfill_counts(p_organization_id);

  IF COALESCE((validation_result->>'success')::BOOLEAN, false) IS NOT TRUE THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'count validation failed', 'validation', validation_result));
  END IF;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'schema_name', registry_record.schema_name,
    'status', registry_record.status,
    'read_mode', registry_record.read_mode,
    'write_mode', registry_record.write_mode,
    'latest_backfill_run_id', latest_run.id,
    'latest_backfill_status', latest_run.status,
    'validation', validation_result,
    'ready_for_tenant_schema_reads', jsonb_array_length(blockers) = 0,
    'blockers', blockers
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.set_tenant_read_mode(
  p_organization_id UUID,
  p_read_mode TEXT,
  p_force BOOLEAN DEFAULT false
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  cutover_status JSONB;
  ready BOOLEAN;
  event_status TEXT;
  event_id UUID;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF p_read_mode NOT IN ('public', 'dual', 'tenant_schema') THEN
    RAISE EXCEPTION 'Invalid read mode: %', p_read_mode;
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can set tenant read mode';
  END IF;

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id
  FOR UPDATE;

  IF registry_record.organization_id IS NULL THEN
    RAISE EXCEPTION 'Tenant registry entry not found for organization %', p_organization_id;
  END IF;

  cutover_status := public.get_tenant_cutover_status(p_organization_id);
  ready := COALESCE((cutover_status->>'ready_for_tenant_schema_reads')::BOOLEAN, false);

  IF p_read_mode = 'tenant_schema' AND NOT ready AND NOT p_force THEN
    INSERT INTO public.tenant_cutover_events (
      organization_id,
      schema_name,
      previous_read_mode,
      new_read_mode,
      previous_write_mode,
      new_write_mode,
      status,
      validation
    ) VALUES (
      p_organization_id,
      registry_record.schema_name,
      registry_record.read_mode,
      p_read_mode,
      registry_record.write_mode,
      registry_record.write_mode,
      'blocked',
      cutover_status
    ) RETURNING id INTO event_id;

    RETURN jsonb_build_object(
      'success', false,
      'event_id', event_id,
      'organization_id', p_organization_id,
      'requested_read_mode', p_read_mode,
      'current_read_mode', registry_record.read_mode,
      'blocked', true,
      'cutover_status', cutover_status
    );
  END IF;

  UPDATE public.tenant_registry
  SET read_mode = p_read_mode,
      metadata = metadata || jsonb_build_object('last_read_mode_change_at', now(), 'last_read_mode', p_read_mode)
  WHERE organization_id = p_organization_id
  RETURNING * INTO registry_record;

  event_status := CASE
    WHEN p_read_mode = 'public' THEN 'rolled_back'
    ELSE 'applied'
  END;

  INSERT INTO public.tenant_cutover_events (
    organization_id,
    schema_name,
    previous_read_mode,
    new_read_mode,
    previous_write_mode,
    new_write_mode,
    status,
    validation
  ) VALUES (
    p_organization_id,
    registry_record.schema_name,
    cutover_status->>'read_mode',
    p_read_mode,
    registry_record.write_mode,
    registry_record.write_mode,
    event_status,
    cutover_status
  ) RETURNING id INTO event_id;

  RETURN jsonb_build_object(
    'success', true,
    'event_id', event_id,
    'organization_id', registry_record.organization_id,
    'schema_name', registry_record.schema_name,
    'status', registry_record.status,
    'read_mode', registry_record.read_mode,
    'write_mode', registry_record.write_mode,
    'forced', p_force,
    'cutover_status', cutover_status
  );
END;
$$;

REVOKE ALL ON FUNCTION public.get_tenant_cutover_status(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_tenant_cutover_status(UUID) TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.set_tenant_read_mode(UUID, TEXT, BOOLEAN) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_tenant_read_mode(UUID, TEXT, BOOLEAN) TO authenticated, service_role;

COMMENT ON TABLE public.tenant_cutover_events IS
  'Audit trail for tenant read-mode cutover attempts and rollbacks.';
COMMENT ON FUNCTION public.get_tenant_cutover_status(UUID) IS
  'Returns whether a tenant is ready for tenant_schema reads based on provisioning and backfill validation.';
COMMENT ON FUNCTION public.set_tenant_read_mode(UUID, TEXT, BOOLEAN) IS
  'Safely changes tenant read mode. tenant_schema mode is blocked unless validation passes, unless force is true.';

COMMIT;

-- ==========================================================================
-- Source: 20260619101500_tenant_write_cutover_controls.sql
-- ==========================================================================

-- Phase 8: Tenant write-switch controls.
-- Hardens write-mode cutover so tenant_schema writes are blocked until read cutover
-- and validation are ready. Does not switch any tenant.

BEGIN;

ALTER TABLE public.tenant_cutover_events
  ADD COLUMN IF NOT EXISTS cutover_type TEXT NOT NULL DEFAULT 'read';

ALTER TABLE public.tenant_cutover_events
  DROP CONSTRAINT IF EXISTS tenant_cutover_events_cutover_type_check;

ALTER TABLE public.tenant_cutover_events
  ADD CONSTRAINT tenant_cutover_events_cutover_type_check
  CHECK (cutover_type IN ('read', 'write'));

CREATE INDEX IF NOT EXISTS idx_tenant_cutover_events_type_org_created
  ON public.tenant_cutover_events(cutover_type, organization_id, created_at DESC);

CREATE OR REPLACE FUNCTION public.get_tenant_write_cutover_status(p_organization_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  read_status JSONB;
  blockers JSONB := '[]'::jsonb;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role' OR p_organization_id = public.get_my_org()) THEN
    RAISE EXCEPTION 'Insufficient permissions to inspect tenant write cutover status';
  END IF;

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id;

  IF registry_record.organization_id IS NULL THEN
    RAISE EXCEPTION 'Tenant registry entry not found for organization %', p_organization_id;
  END IF;

  read_status := public.get_tenant_cutover_status(p_organization_id);

  IF COALESCE((read_status->>'ready_for_tenant_schema_reads')::BOOLEAN, false) IS NOT TRUE THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'tenant is not ready for tenant schema reads', 'read_status', read_status));
  END IF;

  IF registry_record.read_mode <> 'tenant_schema' THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'read_mode must be tenant_schema before tenant_schema writes', 'read_mode', registry_record.read_mode));
  END IF;

  IF registry_record.status NOT IN ('active', 'migrating') THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'tenant registry is not active', 'status', registry_record.status));
  END IF;

  IF registry_record.schema_name IS NULL OR registry_record.schema_name !~ '^tenant_[a-z0-9_]+$' THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'missing or unsafe tenant schema name'));
  ELSIF to_regnamespace(registry_record.schema_name) IS NULL THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'tenant schema does not exist', 'schema_name', registry_record.schema_name));
  END IF;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'schema_name', registry_record.schema_name,
    'status', registry_record.status,
    'read_mode', registry_record.read_mode,
    'write_mode', registry_record.write_mode,
    'read_status', read_status,
    'ready_for_tenant_schema_writes', jsonb_array_length(blockers) = 0,
    'blockers', blockers
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.set_tenant_write_mode(
  p_organization_id UUID,
  p_write_mode TEXT,
  p_read_mode TEXT DEFAULT NULL,
  p_force BOOLEAN DEFAULT false
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  previous_read_mode TEXT;
  previous_write_mode TEXT;
  write_status JSONB;
  ready BOOLEAN;
  event_status TEXT;
  event_id UUID;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can set tenant write mode';
  END IF;

  IF p_write_mode NOT IN ('public', 'dual', 'tenant_schema') THEN
    RAISE EXCEPTION 'Invalid write mode: %', p_write_mode;
  END IF;

  IF p_read_mode IS NOT NULL AND p_read_mode NOT IN ('public', 'dual', 'tenant_schema') THEN
    RAISE EXCEPTION 'Invalid read mode: %', p_read_mode;
  END IF;

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id
  FOR UPDATE;

  IF registry_record.organization_id IS NULL THEN
    RAISE EXCEPTION 'Tenant registry entry not found for organization %', p_organization_id;
  END IF;

  previous_read_mode := registry_record.read_mode;
  previous_write_mode := registry_record.write_mode;
  write_status := public.get_tenant_write_cutover_status(p_organization_id);
  ready := COALESCE((write_status->>'ready_for_tenant_schema_writes')::BOOLEAN, false);

  IF p_write_mode = 'tenant_schema' AND NOT ready AND NOT p_force THEN
    INSERT INTO public.tenant_cutover_events (
      cutover_type,
      organization_id,
      schema_name,
      previous_read_mode,
      new_read_mode,
      previous_write_mode,
      new_write_mode,
      status,
      validation
    ) VALUES (
      'write',
      p_organization_id,
      registry_record.schema_name,
      previous_read_mode,
      COALESCE(p_read_mode, previous_read_mode),
      previous_write_mode,
      p_write_mode,
      'blocked',
      write_status
    ) RETURNING id INTO event_id;

    RETURN jsonb_build_object(
      'success', false,
      'event_id', event_id,
      'organization_id', p_organization_id,
      'requested_write_mode', p_write_mode,
      'current_write_mode', previous_write_mode,
      'blocked', true,
      'write_cutover_status', write_status
    );
  END IF;

  IF p_write_mode IN ('dual', 'tenant_schema') AND registry_record.status NOT IN ('active', 'migrating') THEN
    RAISE EXCEPTION 'Tenant schema must be active before enabling % write mode. Current status: %', p_write_mode, registry_record.status;
  END IF;

  UPDATE public.tenant_registry
  SET write_mode = p_write_mode,
      read_mode = COALESCE(p_read_mode, read_mode),
      metadata = metadata || jsonb_build_object(
        'last_write_mode_change_at', now(),
        'last_write_mode', p_write_mode,
        'last_mode_change_at', now()
      )
  WHERE organization_id = p_organization_id
  RETURNING * INTO registry_record;

  event_status := CASE
    WHEN p_write_mode = 'public' THEN 'rolled_back'
    ELSE 'applied'
  END;

  INSERT INTO public.tenant_cutover_events (
    cutover_type,
    organization_id,
    schema_name,
    previous_read_mode,
    new_read_mode,
    previous_write_mode,
    new_write_mode,
    status,
    validation
  ) VALUES (
    'write',
    p_organization_id,
    registry_record.schema_name,
    previous_read_mode,
    registry_record.read_mode,
    previous_write_mode,
    p_write_mode,
    event_status,
    write_status
  ) RETURNING id INTO event_id;

  RETURN jsonb_build_object(
    'success', true,
    'event_id', event_id,
    'organization_id', registry_record.organization_id,
    'schema_name', registry_record.schema_name,
    'status', registry_record.status,
    'read_mode', registry_record.read_mode,
    'write_mode', registry_record.write_mode,
    'forced', p_force,
    'write_cutover_status', write_status
  );
END;
$$;

REVOKE ALL ON FUNCTION public.get_tenant_write_cutover_status(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_tenant_write_cutover_status(UUID) TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.set_tenant_write_mode(UUID, TEXT, TEXT, BOOLEAN) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_tenant_write_mode(UUID, TEXT, TEXT, BOOLEAN) TO authenticated, service_role;

COMMENT ON FUNCTION public.get_tenant_write_cutover_status(UUID) IS
  'Returns whether a tenant is ready for tenant_schema writes. Requires tenant_schema reads and validation readiness.';
COMMENT ON FUNCTION public.set_tenant_write_mode(UUID, TEXT, TEXT, BOOLEAN) IS
  'Safely changes tenant write mode. tenant_schema mode is blocked unless read cutover and validation pass, unless force is true.';

COMMIT;

