    FROM public.invoice_line_items ili
    WHERE ili.id = p_invoice_line_id
      AND public.invoice_writable(ili.invoice_id, false)
  );
$$;

CREATE OR REPLACE FUNCTION public.ledger_payment_visible(
  p_organization_id uuid,
  p_bill_id uuid
)
RETURNS boolean
LANGUAGE sql
