DO $$
DECLARE
  v_table text;
  v_policy text;
BEGIN
  FOREACH v_table IN ARRAY ARRAY[
    'invoices',
    'payments',
    'invoice_allocations',
    'credit_requests',
    'invoice_line_items',
    'invoice_documents',
    'reconciliation_variances',
    'invoice_audit_events',
    'ledger_bills',
    'invoice_line_matches',
    'ledger_payments',
    'ledger_entries'
  ]
  LOOP
    FOR v_policy IN
      SELECT policyname
      FROM pg_policies
      WHERE schemaname = 'public'
        AND tablename = v_table
    LOOP
      EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', v_policy, v_table);
    END LOOP;
  END LOOP;
END $$;

REVOKE TRUNCATE, REFERENCES, TRIGGER ON
  public.invoices,
  public.payments,
  public.invoice_allocations,
  public.credit_requests,
  public.invoice_line_items,
  public.invoice_documents,
  public.reconciliation_variances,
  public.invoice_audit_events,
  public.ledger_bills,
  public.invoice_line_matches,
  public.ledger_payments,
  public.ledger_entries
FROM anon, authenticated;

GRANT SELECT, INSERT, UPDATE ON
  public.invoices,
  public.payments,
  public.invoice_allocations,
  public.credit_requests,
  public.invoice_line_items,
  public.invoice_documents,
  public.reconciliation_variances,
  public.ledger_bills,
  public.invoice_line_matches,
  public.ledger_payments
TO authenticated;

GRANT SELECT, INSERT ON
  public.invoice_audit_events,
  public.ledger_entries
TO authenticated;

