-- ==========================================================================
-- Source: 20260628000016_transfer_endpoint_rls.sql
-- ==========================================================================

BEGIN;

-- Transfer-rule step: two-endpoint RLS for transfer-style operational tables.
-- commissary_routes is a route header/config-operational record: origin_location_id plus destination stops in commissary_route_stops.
-- No target table has deleted_at in the live schema, so soft-delete predicates are not applicable here.

CREATE OR REPLACE FUNCTION public.transfer_scope_visible(
  p_organization_id uuid,
  p_from_location_id uuid,
  p_to_location_id uuid,
  p_deleted_at timestamptz DEFAULT NULL
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT
    p_deleted_at IS NULL
    AND (
      public.is_platform_admin()
      OR (
        p_organization_id = public.get_auth_org()
        AND (
          public.get_auth_role() = 'org_owner'
          OR p_from_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
          OR p_to_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
        )
      )
    );
$$;

CREATE OR REPLACE FUNCTION public.transfer_from_scope_writable(
  p_organization_id uuid,
  p_from_location_id uuid,
  p_deleted_at timestamptz DEFAULT NULL
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT
    p_deleted_at IS NULL
    AND public.is_manager_or_above()
    AND (
      public.is_platform_admin()
      OR (
        p_organization_id = public.get_auth_org()
        AND (
          public.get_auth_role() = 'org_owner'
          OR p_from_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
        )
      )
    );
$$;

CREATE OR REPLACE FUNCTION public.intercompany_from_scope_writable(
  p_organization_id uuid,
  p_from_location_id uuid,
  p_deleted_at timestamptz DEFAULT NULL
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT
    p_deleted_at IS NULL
    AND public.get_auth_role() IN ('branch_manager', 'org_owner', 'platform_admin')
    AND (
      public.is_platform_admin()
      OR (
        p_organization_id = public.get_auth_org()
        AND (
          public.get_auth_role() = 'org_owner'
          OR p_from_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
        )
      )
    );
$$;

CREATE OR REPLACE FUNCTION public.commissary_route_scope_visible(
  p_organization_id uuid,
  p_route_id uuid,
  p_origin_location_id uuid,
  p_deleted_at timestamptz DEFAULT NULL
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT
    p_deleted_at IS NULL
    AND (
      public.is_platform_admin()
      OR (
        p_organization_id = public.get_auth_org()
        AND (
          public.get_auth_role() = 'org_owner'
          OR p_origin_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
          OR EXISTS (
            SELECT 1
            FROM public.commissary_route_stops crs
            WHERE crs.route_id = p_route_id
              AND crs.destination_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
          )
        )
      )
    );
$$;

CREATE OR REPLACE FUNCTION public.commissary_route_scope_writable(
  p_organization_id uuid,
  p_origin_location_id uuid,
  p_deleted_at timestamptz DEFAULT NULL
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT
    p_deleted_at IS NULL
    AND public.is_manager_or_above()
    AND (
      public.is_platform_admin()
      OR (
        p_organization_id = public.get_auth_org()
        AND (
          public.get_auth_role() = 'org_owner'
          OR p_origin_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
        )
      )
    );
$$;

DO $$
DECLARE
  v_policy record;
BEGIN
  FOR v_policy IN
    SELECT tablename, policyname
    FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename IN ('transfers', 'intercompany_transfers', 'commissary_routes')
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', v_policy.policyname, v_policy.tablename);
  END LOOP;
END $$;

REVOKE ALL PRIVILEGES ON public.transfers, public.intercompany_transfers, public.commissary_routes FROM anon, authenticated;
REVOKE TRUNCATE, REFERENCES, TRIGGER ON public.transfers, public.intercompany_transfers, public.commissary_routes FROM anon, authenticated;

GRANT SELECT, INSERT, UPDATE ON public.transfers, public.intercompany_transfers, public.commissary_routes TO authenticated;
GRANT ALL PRIVILEGES ON public.transfers, public.intercompany_transfers, public.commissary_routes TO service_role;

GRANT EXECUTE ON FUNCTION public.transfer_scope_visible(uuid, uuid, uuid, timestamptz) TO authenticated;
GRANT EXECUTE ON FUNCTION public.transfer_from_scope_writable(uuid, uuid, timestamptz) TO authenticated;
GRANT EXECUTE ON FUNCTION public.intercompany_from_scope_writable(uuid, uuid, timestamptz) TO authenticated;
GRANT EXECUTE ON FUNCTION public.commissary_route_scope_visible(uuid, uuid, uuid, timestamptz) TO authenticated;
GRANT EXECUTE ON FUNCTION public.commissary_route_scope_writable(uuid, uuid, timestamptz) TO authenticated;

CREATE POLICY transfers_endpoint_select
  ON public.transfers
  FOR SELECT
  USING (public.transfer_scope_visible(organization_id, from_location_id, to_location_id, NULL));

CREATE POLICY transfers_from_scope_insert
  ON public.transfers
  FOR INSERT
  WITH CHECK (public.transfer_from_scope_writable(organization_id, from_location_id, NULL));

CREATE POLICY transfers_from_scope_update
  ON public.transfers
  FOR UPDATE
  USING (public.transfer_from_scope_writable(organization_id, from_location_id, NULL))
  WITH CHECK (public.transfer_from_scope_writable(organization_id, from_location_id, NULL));

CREATE POLICY intercompany_transfers_endpoint_select
  ON public.intercompany_transfers
  FOR SELECT
  USING (public.transfer_scope_visible(organization_id, from_location_id, to_location_id, NULL));

CREATE POLICY intercompany_transfers_branch_from_scope_insert
  ON public.intercompany_transfers
  FOR INSERT
  WITH CHECK (public.intercompany_from_scope_writable(organization_id, from_location_id, NULL));

CREATE POLICY intercompany_transfers_branch_from_scope_update
  ON public.intercompany_transfers
  FOR UPDATE
  USING (public.intercompany_from_scope_writable(organization_id, from_location_id, NULL))
  WITH CHECK (public.intercompany_from_scope_writable(organization_id, from_location_id, NULL));

CREATE POLICY commissary_routes_endpoint_select
  ON public.commissary_routes
  FOR SELECT
  USING (public.commissary_route_scope_visible(organization_id, id, origin_location_id, NULL));

CREATE POLICY commissary_routes_origin_scope_insert
  ON public.commissary_routes
  FOR INSERT
  WITH CHECK (public.commissary_route_scope_writable(organization_id, origin_location_id, NULL));

CREATE POLICY commissary_routes_origin_scope_update
  ON public.commissary_routes
  FOR UPDATE
  USING (public.commissary_route_scope_writable(organization_id, origin_location_id, NULL))
  WITH CHECK (public.commissary_route_scope_writable(organization_id, origin_location_id, NULL));

COMMIT;

-- ==========================================================================
-- Source: 20260628000017_location_email_addresses.sql
-- ==========================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS public.location_email_addresses (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email text NOT NULL,
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  brand_id uuid REFERENCES public.brands(brand_id) ON DELETE SET NULL,
  location_id uuid NOT NULL REFERENCES public.locations(id) ON DELETE CASCADE,
  label text,
  is_active boolean NOT NULL DEFAULT true,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  deleted_at timestamptz
);

CREATE UNIQUE INDEX IF NOT EXISTS location_email_addresses_email_active_idx
  ON public.location_email_addresses (lower(email))
  WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS location_email_addresses_location_id_idx
  ON public.location_email_addresses (location_id);

CREATE INDEX IF NOT EXISTS location_email_addresses_lower_email_idx
  ON public.location_email_addresses (lower(email));

CREATE OR REPLACE FUNCTION public.set_location_email_scope()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_organization_id uuid;
  v_brand_id uuid;
BEGIN
  NEW.email := lower(btrim(NEW.email));

  IF NEW.email IS NULL OR NEW.email = '' THEN
    RAISE EXCEPTION 'location_email_addresses.email is required';
  END IF;

  SELECT l.organization_id, l.brand_id
    INTO v_organization_id, v_brand_id
  FROM public.locations l
  WHERE l.id = NEW.location_id;

  IF v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Location % does not exist', NEW.location_id;
  END IF;

  NEW.organization_id := v_organization_id;
  NEW.brand_id := v_brand_id;
  NEW.updated_at := now();

  IF TG_OP = 'INSERT' THEN
    NEW.created_at := COALESCE(NEW.created_at, now());
    NEW.created_by := COALESCE(NEW.created_by, auth.uid());
  END IF;

  NEW.updated_by := COALESCE(auth.uid(), NEW.updated_by);

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS set_location_email_scope ON public.location_email_addresses;
CREATE TRIGGER set_location_email_scope
BEFORE INSERT OR UPDATE ON public.location_email_addresses
FOR EACH ROW
EXECUTE FUNCTION public.set_location_email_scope();

ALTER TABLE public.location_email_addresses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.location_email_addresses FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
  policy_record record;
BEGIN
  FOR policy_record IN
    SELECT policyname
    FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'location_email_addresses'
  LOOP
    EXECUTE format(
      'DROP POLICY IF EXISTS %I ON public.location_email_addresses',
      policy_record.policyname
    );
  END LOOP;
END $$;

CREATE POLICY location_email_addresses_select
  ON public.location_email_addresses
  FOR SELECT
  USING (
    public.tenant_scope_visible(organization_id, brand_id, location_id, deleted_at)
  );

CREATE POLICY location_email_addresses_insert
  ON public.location_email_addresses
  FOR INSERT
  WITH CHECK (
    deleted_at IS NULL
    AND public.tenant_scope_writable(organization_id, brand_id, location_id, NULL, false)
  );

CREATE POLICY location_email_addresses_update
  ON public.location_email_addresses
  FOR UPDATE
  USING (
    public.tenant_scope_writable(organization_id, brand_id, location_id, deleted_at, false)
  )
  WITH CHECK (
    public.tenant_scope_writable(organization_id, brand_id, location_id, NULL, false)
  );

REVOKE TRUNCATE, REFERENCES, TRIGGER ON public.location_email_addresses FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON public.location_email_addresses TO authenticated;
GRANT ALL ON public.location_email_addresses TO service_role;
GRANT EXECUTE ON FUNCTION public.tenant_scope_visible(uuid, uuid, uuid, timestamptz) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.tenant_scope_writable(uuid, uuid, uuid, timestamptz, boolean) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_manager_or_above() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_platform_admin() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_my_accessible_location_ids() TO authenticated, service_role;

COMMIT;

-- ==========================================================================
-- Source: 20260628000018_ingest_email_invoice_rpc.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.ingest_email_invoice(
  p_recipient_email text,
  p_fallback_organization_id uuid DEFAULT NULL,
  p_invoice jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_recipient_email text;
  v_location_email public.location_email_addresses%ROWTYPE;
  v_vendor_name text;
  v_invoice_number text;
  v_total_amount numeric := 0;
  v_invoice_id uuid;
  v_system_user_id uuid := '99999999-9999-9999-9999-999999999999';
  v_metadata jsonb;
BEGIN
  v_recipient_email := lower(btrim(COALESCE(p_recipient_email, '')));

  IF v_recipient_email = '' THEN
    v_recipient_email := NULL;
  END IF;

  v_vendor_name := COALESCE(NULLIF(btrim(p_invoice->>'vendor_name'), ''), 'Unknown Vendor (Auto-Ingested)');
  v_invoice_number := COALESCE(
    NULLIF(btrim(p_invoice->>'invoice_number'), ''),
    'EMAIL-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS') || '-' || substr(gen_random_uuid()::text, 1, 8)
  );

  BEGIN
    v_total_amount := COALESCE(NULLIF(btrim(p_invoice->>'total_amount'), '')::numeric, 0);
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    v_total_amount := 0;
  END;

  SELECT lea.*
    INTO v_location_email
  FROM public.location_email_addresses lea
  WHERE lower(lea.email) = v_recipient_email
    AND lea.is_active = true
    AND lea.deleted_at IS NULL
  LIMIT 1;

  IF FOUND THEN
    v_metadata := COALESCE(p_invoice->'ap_metadata', '{}'::jsonb)
      || jsonb_build_object(
        'ingest_recipient', v_recipient_email,
        'received_at', now(),
        'matched_location_email_id', v_location_email.id,
        'source', 'email_import'
      );

    INSERT INTO public.invoices (
      vendor_name,
      invoice_number,
      total_amount,
      status,
      ap_status,
      source,
      file_url,
      organization_id,
      brand_id,
      location_id,
      created_by,
      ap_metadata
    ) VALUES (
      v_vendor_name,
      v_invoice_number,
      v_total_amount,
      'extracting',
      'processing',
      'email_import',
      NULLIF(p_invoice->>'file_url', ''),
      v_location_email.organization_id,
      v_location_email.brand_id,
      v_location_email.location_id,
      v_system_user_id,
      v_metadata
    )
    RETURNING id INTO v_invoice_id;

    RETURN jsonb_build_object(
      'invoice_id', v_invoice_id,
      'matched', true,
      'organization_id', v_location_email.organization_id,
      'brand_id', v_location_email.brand_id,
      'location_id', v_location_email.location_id,
      'recipient_email', v_recipient_email
    );
  END IF;

  v_metadata := COALESCE(p_invoice->'ap_metadata', '{}'::jsonb)
    || jsonb_build_object(
      'ingest_recipient', v_recipient_email,
      'received_at', now(),
      'reason', 'no_location_email_match',
      'source', 'email_import'
    );

  INSERT INTO public.invoices (
    vendor_name,
    invoice_number,
    total_amount,
    status,
    ap_status,
    action_required_reason,
    action_required_details,
    source,
    file_url,
    organization_id,
    brand_id,
    location_id,
    created_by,
    ap_metadata
  ) VALUES (
    v_vendor_name,
    v_invoice_number,
    v_total_amount,
    'pending_review',
    'action_required',
    'needs_scope_assignment',
    'No active location email address matched the ingest recipient.',
    'email_import',
    NULLIF(p_invoice->>'file_url', ''),
    p_fallback_organization_id,
    NULL,
    NULL,
    v_system_user_id,
    v_metadata
  )
  RETURNING id INTO v_invoice_id;

  RETURN jsonb_build_object(
    'invoice_id', v_invoice_id,
    'matched', false,
    'organization_id', p_fallback_organization_id,
    'brand_id', NULL,
    'location_id', NULL,
    'recipient_email', v_recipient_email,
    'warning', CASE WHEN p_fallback_organization_id IS NULL THEN 'fallback_organization_id_missing' ELSE NULL END
  );
END;
$$;

REVOKE ALL ON FUNCTION public.ingest_email_invoice(text, uuid, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.ingest_email_invoice(text, uuid, jsonb) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.ingest_email_invoice(text, uuid, jsonb) TO service_role;

COMMIT;

-- ==========================================================================
-- Source: 20260628000019_fix_invoice_column_drift.sql
-- ==========================================================================

BEGIN;

ALTER TABLE public.invoices
  ADD COLUMN IF NOT EXISTS raw_text text,
  ADD COLUMN IF NOT EXISTS extraction_method text,
  ADD COLUMN IF NOT EXISTS purchase_order_number text;

CREATE OR REPLACE FUNCTION public.save_invoice_workflow(
  p_invoice_id UUID DEFAULT NULL,
  p_invoice JSONB DEFAULT '{}'::jsonb,
  p_line_items JSONB DEFAULT '[]'::jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_existing public.invoices%ROWTYPE;
  v_invoice public.invoices%ROWTYPE;
  v_payload JSONB;
  v_org_id UUID;
BEGIN
  v_payload := COALESCE(p_invoice, '{}'::jsonb)
    - 'id'
    - 'created_at'
    - 'updated_at'
    - 'deleted_at'
    - 'deleted_by'
    - 'vendor_address';

  IF p_invoice_id IS NULL THEN
    v_org_id := NULLIF(v_payload->>'organization_id', '')::UUID;

    IF v_org_id IS NULL THEN
      v_org_id := public.get_my_org();
      v_payload := jsonb_set(v_payload, '{organization_id}', to_jsonb(v_org_id), true);
    END IF;

    PERFORM public.assert_org_actor(v_org_id);

    v_invoice := jsonb_populate_record(NULL::public.invoices, v_payload);

    INSERT INTO public.invoices (
      vendor_name,
      invoice_number,
      total_amount,
      status,
      account_number,
      subtotal,
      organization_id,
      location_id,
      payment_status,
      vendor_id,
      due_date,
      delivery_fee,
      fuel_surcharge,
      other_charges,
      tax_amount,
      currency,
      source,
      file_url,
      line_items,
      validation_results,
      validation_notes,
      approved_by,
      approved_date,
      location,
      created_by,
      extraction_method,
      raw_text,
      purchase_order_number,
      invoice_date,
      payment_terms,
      file_destination,
      purchase_order_id,
      matched_order_id,
      match_status,
      brand_id,
      ap_status,
      action_required_reason,
      action_required_details,
      assigned_reviewer_id,
      payment_account_id,
      scheduled_payment_date,
      closed_at,
      closed_by,
      ap_metadata,
      paid_amount,
      payment_reference,
      credit_applied,
      credit_reason,
      version_number,
      ap_routing_destination,
      ap_routing_resolved_at
    ) VALUES (
      v_invoice.vendor_name,
      v_invoice.invoice_number,
      v_invoice.total_amount,
      COALESCE(v_invoice.status, 'pending_review'),
      v_invoice.account_number,
      v_invoice.subtotal,
      v_org_id,
      v_invoice.location_id,
      COALESCE(v_invoice.payment_status, 'unpaid'),
      v_invoice.vendor_id,
      v_invoice.due_date,
      v_invoice.delivery_fee,
      v_invoice.fuel_surcharge,
      v_invoice.other_charges,
      v_invoice.tax_amount,
      COALESCE(v_invoice.currency, 'USD'),
      v_invoice.source,
      v_invoice.file_url,
      COALESCE(v_invoice.line_items, '[]'::jsonb),
      COALESCE(v_invoice.validation_results, '{}'::jsonb),
      v_invoice.validation_notes,
      v_invoice.approved_by,
      v_invoice.approved_date,
      v_invoice.location,
      COALESCE(v_invoice.created_by, auth.uid()),
      v_invoice.extraction_method,
      v_invoice.raw_text,
      v_invoice.purchase_order_number,
      v_invoice.invoice_date,
      v_invoice.payment_terms,
      v_invoice.file_destination,
      v_invoice.purchase_order_id,
      v_invoice.matched_order_id,
      v_invoice.match_status,
      v_invoice.brand_id,
      v_invoice.ap_status,
      v_invoice.action_required_reason,
      v_invoice.action_required_details,
      v_invoice.assigned_reviewer_id,
      v_invoice.payment_account_id,
      v_invoice.scheduled_payment_date,
      v_invoice.closed_at,
      v_invoice.closed_by,
      COALESCE(v_invoice.ap_metadata, '{}'::jsonb),
      COALESCE(v_invoice.paid_amount, 0),
      v_invoice.payment_reference,
      COALESCE(v_invoice.credit_applied, 0),
      v_invoice.credit_reason,
      COALESCE(v_invoice.version_number, 1),
      v_invoice.ap_routing_destination,
      v_invoice.ap_routing_resolved_at
    )
    RETURNING * INTO v_invoice;
  ELSE
    SELECT *
      INTO v_existing
    FROM public.invoices
    WHERE id = p_invoice_id
      AND deleted_at IS NULL
    FOR UPDATE;

    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION 'Invoice not found';
    END IF;

    PERFORM public.assert_org_actor(v_existing.organization_id);

    IF v_payload ? 'organization_id'
      AND NULLIF(v_payload->>'organization_id', '')::UUID IS DISTINCT FROM v_existing.organization_id THEN
      RAISE EXCEPTION 'Invoice organization cannot be changed';
    END IF;

    v_invoice := jsonb_populate_record(v_existing, v_payload);

    UPDATE public.invoices
       SET vendor_name = v_invoice.vendor_name,
           invoice_number = v_invoice.invoice_number,
           total_amount = v_invoice.total_amount,
           status = v_invoice.status,
           account_number = v_invoice.account_number,
           subtotal = v_invoice.subtotal,
           location_id = v_invoice.location_id,
           payment_status = v_invoice.payment_status,
           vendor_id = v_invoice.vendor_id,
           due_date = v_invoice.due_date,
           delivery_fee = v_invoice.delivery_fee,
           fuel_surcharge = v_invoice.fuel_surcharge,
           other_charges = v_invoice.other_charges,
           tax_amount = v_invoice.tax_amount,
           currency = v_invoice.currency,
           source = v_invoice.source,
           file_url = v_invoice.file_url,
           line_items = v_invoice.line_items,
           validation_results = v_invoice.validation_results,
           validation_notes = v_invoice.validation_notes,
           approved_by = v_invoice.approved_by,
           approved_date = v_invoice.approved_date,
           location = v_invoice.location,
           extraction_method = v_invoice.extraction_method,
           raw_text = v_invoice.raw_text,
           purchase_order_number = v_invoice.purchase_order_number,
           invoice_date = v_invoice.invoice_date,
           payment_terms = v_invoice.payment_terms,
           file_destination = v_invoice.file_destination,
           purchase_order_id = v_invoice.purchase_order_id,
           matched_order_id = v_invoice.matched_order_id,
           match_status = v_invoice.match_status,
           brand_id = v_invoice.brand_id,
           ap_status = v_invoice.ap_status,
           action_required_reason = v_invoice.action_required_reason,
           action_required_details = v_invoice.action_required_details,
           assigned_reviewer_id = v_invoice.assigned_reviewer_id,
           payment_account_id = v_invoice.payment_account_id,
           scheduled_payment_date = v_invoice.scheduled_payment_date,
           closed_at = v_invoice.closed_at,
           closed_by = v_invoice.closed_by,
           ap_metadata = v_invoice.ap_metadata,
           paid_amount = v_invoice.paid_amount,
           payment_reference = v_invoice.payment_reference,
           credit_applied = v_invoice.credit_applied,
           credit_reason = v_invoice.credit_reason,
           version_number = COALESCE(v_existing.version_number, 1) + 1,
           ap_routing_destination = v_invoice.ap_routing_destination,
           ap_routing_resolved_at = v_invoice.ap_routing_resolved_at,
           updated_at = now()
     WHERE id = p_invoice_id
     RETURNING * INTO v_invoice;
  END IF;

  IF jsonb_typeof(COALESCE(p_line_items, '[]'::jsonb)) = 'array' AND jsonb_array_length(COALESCE(p_line_items, '[]'::jsonb)) > 0 THEN
    PERFORM public.upsert_invoice_line_items(v_invoice.id, p_line_items);
  END IF;

  RETURN to_jsonb(v_invoice);
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260628000020_vendor_data_model_v1a.sql
-- ==========================================================================

BEGIN;

-- V1a keeps the existing operational vendors.status axis intact and adds a
-- separate approval lifecycle used by validation/payment workflows.
ALTER TABLE public.vendors
  ADD COLUMN IF NOT EXISTS approval_status text NOT NULL DEFAULT 'draft',
  ADD COLUMN IF NOT EXISTS dba_name text,
  ADD COLUMN IF NOT EXISTS vendor_type text,
  ADD COLUMN IF NOT EXISTS internal_vendor_id text,
  ADD COLUMN IF NOT EXISTS remittance_address_line1 text,
  ADD COLUMN IF NOT EXISTS remittance_address_line2 text,
  ADD COLUMN IF NOT EXISTS remittance_city text,
  ADD COLUMN IF NOT EXISTS remittance_state text,
  ADD COLUMN IF NOT EXISTS remittance_zip_code text,
  ADD COLUMN IF NOT EXISTS remittance_country text,
  ADD COLUMN IF NOT EXISTS mailing_address_line1 text,
  ADD COLUMN IF NOT EXISTS mailing_address_line2 text,
  ADD COLUMN IF NOT EXISTS mailing_city text,
  ADD COLUMN IF NOT EXISTS mailing_state text,
  ADD COLUMN IF NOT EXISTS mailing_zip_code text,
  ADD COLUMN IF NOT EXISTS mailing_country text,
  ADD COLUMN IF NOT EXISTS payment_recipient_name text,
  ADD COLUMN IF NOT EXISTS accepts_check boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS accepts_ach boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS accepts_electronic boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS accepts_autopay boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS payment_confirmation_email_enabled boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS payment_terms text,
  ADD COLUMN IF NOT EXISTS custom_payment_terms_days integer,
  ADD COLUMN IF NOT EXISTS invoice_start_date date,
  ADD COLUMN IF NOT EXISTS due_date_calculation_method text,
  ADD COLUMN IF NOT EXISTS auto_schedule_payments boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS default_gl_code text;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'vendors_approval_status_check'
      AND conrelid = 'public.vendors'::regclass
  ) THEN
    ALTER TABLE public.vendors
      ADD CONSTRAINT vendors_approval_status_check
      CHECK (approval_status IN ('draft', 'pending_approval', 'approved', 'suspended', 'rejected'));
  END IF;
END $$;

-- Extend payment terms without removing existing values used by the app.
ALTER TABLE public.vendors
  DROP CONSTRAINT IF EXISTS vendors_payment_terms_check;

ALTER TABLE public.vendors
  ADD CONSTRAINT vendors_payment_terms_check
  CHECK (
    payment_terms IS NULL
    OR payment_terms IN (
      'net_7',
      'net_15',
      'net_30',
      'net_45',
      'net_60',
      'due_on_receipt',
      'custom'
    )
  );

CREATE TABLE IF NOT EXISTS public.vendor_tax_information (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id uuid NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  brand_id uuid REFERENCES public.brands(brand_id) ON DELETE SET NULL,
  location_id uuid REFERENCES public.locations(id) ON DELETE SET NULL,
  w9_status text NOT NULL DEFAULT 'not_collected'
    CHECK (w9_status IN ('not_collected', 'requested', 'received', 'verified', 'rejected')),
  tax_classification text,
  legal_name text,
  tax_id_last4 text,
  tax_id_full text,
  is_1099 boolean NOT NULL DEFAULT false,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);

CREATE TABLE IF NOT EXISTS public.vendor_banking_details (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id uuid NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  brand_id uuid REFERENCES public.brands(brand_id) ON DELETE SET NULL,
  location_id uuid REFERENCES public.locations(id) ON DELETE SET NULL,
  account_number text,
  routing_number text,
  account_last4 text,
  verification_state text NOT NULL DEFAULT 'unverified'
    CHECK (verification_state IN ('unverified', 'pending', 'verified')),
  verified_at timestamptz,
  is_active boolean NOT NULL DEFAULT true,
  version integer NOT NULL DEFAULT 1 CHECK (version > 0),
  effective_from timestamptz NOT NULL DEFAULT now(),
  effective_to timestamptz,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);

CREATE TABLE IF NOT EXISTS public.vendor_payment_provider_links (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id uuid NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  brand_id uuid REFERENCES public.brands(brand_id) ON DELETE SET NULL,
  location_id uuid REFERENCES public.locations(id) ON DELETE SET NULL,
  provider text NOT NULL CHECK (provider IN ('dwolla', 'stripe', 'plaid')),
  provider_customer_ref text,
  provider_funding_ref text,
  provider_status text,
  is_active boolean NOT NULL DEFAULT true,
