-- ==========================================================================
-- Source: 20260628000028_vendor_approval_containment.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.assert_can_approve_vendor_scope(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role text;
  v_auth_org uuid;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_role := public.get_auth_role();
  v_auth_org := public.get_auth_org();

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;

  IF p_organization_id IS NULL OR v_auth_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization vendor approval denied';
  END IF;

  IF v_role = 'org_owner' THEN
    RETURN;
  END IF;

  IF v_role = 'branch_manager'
     AND p_brand_id IS NOT NULL
     AND public.reference_scope_writable(
       p_organization_id,
       p_brand_id,
       NULL,
       NULL,
       'branch_manager'
     ) THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'Vendor approval denied for role % outside accessible brand scope', v_role;
END;
$$;

CREATE OR REPLACE FUNCTION public.enforce_vendor_approval_authorization()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN
    PERFORM public.assert_can_approve_vendor_scope(
      NEW.organization_id,
      NEW.brand_id,
      NEW.location_id
    );
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS enforce_vendor_approval_authorization ON public.vendors;
CREATE TRIGGER enforce_vendor_approval_authorization
BEFORE UPDATE OF approval_status ON public.vendors
FOR EACH ROW
EXECUTE FUNCTION public.enforce_vendor_approval_authorization();

REVOKE EXECUTE ON FUNCTION public.assert_can_approve_vendor_scope(uuid, uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.assert_can_approve_vendor_scope(uuid, uuid, uuid) TO authenticated, service_role;

COMMIT;

-- ==========================================================================
-- Source: 20260628000029_vendor_approval_insert_containment.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.assert_can_approve_vendor_scope(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role text;
  v_auth_org uuid;
BEGIN
  -- ponytail: service_role bypass is safe here because auth.role() comes from the
  -- verified database request context, not user-supplied JWT metadata; authenticated
  -- callers cannot forge service_role without the service-role key.
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_role := public.get_auth_role();
  v_auth_org := public.get_auth_org();

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;

  IF p_organization_id IS NULL OR v_auth_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization vendor approval denied';
  END IF;

  IF v_role = 'org_owner' THEN
    RETURN;
  END IF;

  IF v_role = 'branch_manager'
     AND p_brand_id IS NOT NULL
     AND public.reference_scope_writable(
       p_organization_id,
       p_brand_id,
       NULL,
       NULL,
       'branch_manager'
     ) THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'Vendor approval denied for role % outside accessible brand scope', v_role;
END;
$$;

CREATE OR REPLACE FUNCTION public.enforce_vendor_approval_authorization()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.approval_status IN ('pending_approval', 'approved', 'suspended', 'rejected') THEN
      PERFORM public.assert_can_approve_vendor_scope(
        NEW.organization_id,
        NEW.brand_id,
        NEW.location_id
      );
    END IF;

    RETURN NEW;
  END IF;

  IF NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN
    PERFORM public.assert_can_approve_vendor_scope(
      NEW.organization_id,
      NEW.brand_id,
      NEW.location_id
    );
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS enforce_vendor_approval_authorization ON public.vendors;
CREATE TRIGGER enforce_vendor_approval_authorization
BEFORE INSERT OR UPDATE OF approval_status ON public.vendors
FOR EACH ROW
EXECUTE FUNCTION public.enforce_vendor_approval_authorization();

COMMIT;

-- ==========================================================================
-- Source: 20260628000030_vendor_approval_transition_rpc.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.transition_vendor_approval(
  p_vendor_id uuid,
  p_new_status text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vendor public.vendors%ROWTYPE;
  v_new_status text;
BEGIN

  v_new_status := lower(btrim(COALESCE(p_new_status, '')));

  SELECT *
    INTO v_vendor
  FROM public.vendors
  WHERE id = p_vendor_id
  FOR UPDATE;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  PERFORM public.assert_can_approve_vendor_scope(
    v_vendor.organization_id,
    v_vendor.brand_id,
    v_vendor.location_id
  );

  IF v_new_status = v_vendor.approval_status THEN
    RAISE EXCEPTION 'Vendor approval_status is already %', v_new_status;
  END IF;

  -- ponytail: transition edges are intentionally hard-coded for V2's tiny
  -- lifecycle. Ceiling: edges live in function code; upgrade path is a
  -- transition table if the lifecycle grows or becomes tenant-configurable.
  IF NOT (
    (v_vendor.approval_status = 'draft' AND v_new_status IN ('pending_approval', 'approved'))
    OR (v_vendor.approval_status = 'pending_approval' AND v_new_status IN ('approved', 'rejected'))
    OR (v_vendor.approval_status = 'approved' AND v_new_status = 'suspended')
    OR (v_vendor.approval_status = 'suspended' AND v_new_status IN ('approved', 'rejected'))
  ) THEN
    RAISE EXCEPTION 'Invalid vendor approval transition from % to %',
      v_vendor.approval_status,
      COALESCE(NULLIF(v_new_status, ''), '<empty>');
  END IF;

  UPDATE public.vendors
     SET approval_status = v_new_status,
         updated_at = now()
   WHERE id = p_vendor_id
   RETURNING * INTO v_vendor;

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_vendor.id,
    'approval_status', v_vendor.approval_status
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.transition_vendor_approval(uuid, text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.transition_vendor_approval(uuid, text) FROM anon;
