BEGIN;

CREATE OR REPLACE FUNCTION public.sync_invoice_products(p_invoice_id UUID, p_user_id UUID DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_item RECORD;
  v_product_id UUID;
  v_inventory_id UUID;
  v_vendor_item_id UUID;
  v_previous_price NUMERIC;
  v_price_variance_flag BOOLEAN;
  v_price_variance_percent NUMERIC;
  v_threshold NUMERIC := 10;
  v_updates_count INT := 0;
BEGIN
  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id;

  IF v_invoice IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Invoice not found');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.invoice_sync_log
    WHERE invoice_id = p_invoice_id
      AND operation = 'sync_invoice_products'
  ) THEN
    RETURN jsonb_build_object('status', 'success', 'updates_count', 0, 'idempotent', true);
  END IF;

  FOR v_item IN
    SELECT *
    FROM public.invoice_line_items
    WHERE invoice_id = p_invoice_id
  LOOP
    v_product_id := v_item.internal_product_id;
    v_price_variance_flag := false;
    v_price_variance_percent := 0;

    IF v_product_id IS NULL AND v_item.item_name IS NOT NULL THEN
      SELECT id INTO v_product_id
      FROM public.products
      WHERE organization_id = v_invoice.organization_id
        AND lower(name) = lower(v_item.item_name)
      LIMIT 1;

      -- If product still not found, create a new one automatically
      IF v_product_id IS NULL THEN
        INSERT INTO public.products (
          organization_id,
          name,
          category,
          accounting_category,
          report_by_unit,
          base_unit,
          latest_price,
          is_inventoried,
          location_id,
          created_by,
          created_from_invoice_id
        ) VALUES (
          v_invoice.organization_id,
          v_item.item_name,
          'Uncategorized',
          '5100',
          COALESCE(v_item.vendor_unit, 'ea'),
          COALESCE(v_item.vendor_unit, 'ea'),
          v_item.unit_price,
          true,
          v_invoice.location_id,
          COALESCE(p_user_id, v_invoice.created_by),
          p_invoice_id
        )
        RETURNING id INTO v_product_id;
      END IF;
    END IF;

    IF v_invoice.vendor_id IS NOT NULL THEN
      SELECT id, last_price, price_variance_threshold_percent
        INTO v_vendor_item_id, v_previous_price, v_threshold
      FROM public.vendor_items
      WHERE organization_id = v_invoice.organization_id
        AND vendor_id = v_invoice.vendor_id
        AND lower(vendor_item_name) = lower(v_item.item_name)
      LIMIT 1;

      v_threshold := COALESCE(v_threshold, 10);

      IF v_vendor_item_id IS NOT NULL THEN
        IF v_previous_price > 0 AND v_item.unit_price > 0 THEN
          v_price_variance_percent := ((v_item.unit_price - v_previous_price) / v_previous_price) * 100;
          v_price_variance_flag := abs(v_price_variance_percent) >= v_threshold;
        END IF;

        UPDATE public.vendor_items
           SET last_price = v_item.unit_price,
               previous_price = v_previous_price,
               last_invoice_id = p_invoice_id,
               last_price_change_percent = v_price_variance_percent,
               price_variance_flag = v_price_variance_flag,
               updated_at = now()
         WHERE id = v_vendor_item_id;
      ELSE
        INSERT INTO public.vendor_items (
          organization_id, vendor_id, vendor_item_name, default_price,
          last_price, last_invoice_id, updated_at
        ) VALUES (
          v_invoice.organization_id, v_invoice.vendor_id, v_item.item_name, v_item.unit_price,
          v_item.unit_price, p_invoice_id, now()
        )
        RETURNING id INTO v_vendor_item_id;
      END IF;

      UPDATE public.invoice_line_items
         SET vendor_item_id = v_vendor_item_id,
             price_variance_flag = v_price_variance_flag,
             price_variance_percent = v_price_variance_percent,
             internal_product_id = v_product_id
       WHERE id = v_item.id;
    END IF;

    IF v_product_id IS NOT NULL THEN
      SELECT id INTO v_inventory_id
      FROM public.inventory
      WHERE organization_id = v_invoice.organization_id
        AND (
          internal_product_id = v_product_id
          OR product_id = v_product_id::TEXT
        )
      LIMIT 1
      FOR UPDATE;

      IF v_inventory_id IS NOT NULL THEN
        UPDATE public.inventory
           SET current_quantity = COALESCE(current_quantity, 0) + COALESCE(v_item.quantity, 0),
               current_value = COALESCE(current_value, 0) + COALESCE(v_item.total_price, 0),
               updated_at = now()
         WHERE id = v_inventory_id;
      ELSE
        INSERT INTO public.inventory (
          organization_id, internal_product_id, product_id, product_name,
          current_quantity, current_value, updated_at
        ) VALUES (
          v_invoice.organization_id, v_product_id, v_product_id::TEXT, v_item.item_name,
          COALESCE(v_item.quantity, 0), COALESCE(v_item.total_price, 0), now()
        );
      END IF;

      v_updates_count := v_updates_count + 1;
    END IF;
  END LOOP;

  INSERT INTO public.invoice_event_log (invoice_id, event_type, new_value, actor_id)
  VALUES (
    p_invoice_id,
    'inventory_synced',
    jsonb_build_object('updates_count', v_updates_count),
    p_user_id
  );

  INSERT INTO public.invoice_sync_log (invoice_id, operation, hash)
  VALUES (p_invoice_id, 'sync_invoice_products', md5(p_invoice_id::TEXT || now()::TEXT));

  RETURN jsonb_build_object('status', 'success', 'updates_count', v_updates_count);
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260706000003_fix_approval_product_sync.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.approve_invoice_with_limit(
  p_invoice_id uuid,
  p_user_id uuid,
  p_amount numeric
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_limit numeric;
  v_invoice public.invoices%ROWTYPE;
  v_amount numeric;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Approval user must match the authenticated user';
  END IF;

  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_can_approve_invoice_scope(
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id
  );

  SELECT invoice_approval_limit
    INTO v_user_limit
  FROM public.profiles
  WHERE id = p_user_id
    AND deleted_at IS NULL;

  v_amount := COALESCE(p_amount, v_invoice.total_amount, 0);

  IF v_user_limit IS NULL OR v_amount > v_user_limit THEN
    RAISE EXCEPTION 'Approval limit exceeded. Your limit is $%, but the invoice is $%.',
      COALESCE(v_user_limit, 0), v_amount;
  END IF;

  UPDATE public.invoices
     SET status = 'approved',
         ap_status = 'approved',
         approved_by = auth.uid(),
         approved_date = now(),
         updated_at = now()
   WHERE id = p_invoice_id;

  -- Sync products right after approval
  PERFORM public.sync_invoice_products(p_invoice_id);

  RETURN jsonb_build_object('success', true, 'message', 'Invoice approved successfully');
END;
$$;

CREATE OR REPLACE FUNCTION public.execute_approval_step(
  p_step_id uuid,
  p_status text,
  p_comments text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_instance_id uuid;
  v_invoice_id uuid;
  v_pending_count int;
  v_required_role text;
  v_actor_role text;
  v_invoice public.invoices%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_status NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'Unsupported approval step status %', p_status;
  END IF;

  SELECT s.instance_id, s.required_role, ai.invoice_id
    INTO v_instance_id, v_required_role, v_invoice_id
  FROM public.approval_steps s
  JOIN public.approval_instances ai ON ai.id = s.instance_id
  WHERE s.id = p_step_id
    AND s.status = 'pending'
  FOR UPDATE OF s;

  IF v_instance_id IS NULL THEN
    RAISE EXCEPTION 'Pending approval step not found';
  END IF;

  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = v_invoice_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_can_approve_invoice_scope(
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id
  );

  v_actor_role := public.get_auth_role();

  IF NOT (
    v_actor_role = v_required_role
    OR v_actor_role = 'platform_admin'
    OR (v_actor_role = 'org_owner'
        AND v_required_role IN ('location_manager', 'branch_manager', 'org_owner', 'org_admin'))
    OR (v_actor_role = 'branch_manager'
        AND v_required_role IN ('location_manager', 'branch_manager'))
  ) THEN
    RAISE EXCEPTION 'Role % cannot act on approval step requiring %',
      v_actor_role, v_required_role;
  END IF;

  UPDATE public.approval_steps
     SET status = p_status::approval_step_status,
         approver_id = auth.uid(),
         comments = p_comments,
         acted_at = now()
   WHERE id = p_step_id;

  IF p_status = 'rejected' THEN
    UPDATE public.approval_instances
       SET status = 'rejected',
           updated_at = now()
     WHERE id = v_instance_id;

    UPDATE public.invoices
       SET status = 'rejected',
           ap_status = 'rejected',
           updated_at = now()
     WHERE id = v_invoice_id;

    RETURN jsonb_build_object('status', 'rejected');
  END IF;

  SELECT count(*)
    INTO v_pending_count
  FROM public.approval_steps
  WHERE instance_id = v_instance_id
    AND status = 'pending';

  IF v_pending_count = 0 THEN
    UPDATE public.approval_instances
       SET status = 'approved',
           updated_at = now()
     WHERE id = v_instance_id;

    UPDATE public.invoices
       SET status = 'approved',
           ap_status = 'approved',
           approved_by = auth.uid(),
           approved_date = now(),
           updated_at = now()
     WHERE id = v_invoice_id;

    -- Sync products now that it is fully approved
    PERFORM public.sync_invoice_products(v_invoice_id);

    RETURN jsonb_build_object('status', 'fully_approved');
  END IF;

  RETURN jsonb_build_object('status', 'partially_approved', 'pending_steps', v_pending_count);
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260707000001_fix_invoice_product_catalog_sync.sql
-- ==========================================================================

BEGIN;

-- Keep invoice approval user-friendly: approved invoice lines update the Product
-- catalog and vendor pricing, but do not automatically add every purchased line
-- to Inventory. Inventory remains opt-in via product/count-sheet setup.
CREATE OR REPLACE FUNCTION public.sync_invoice_products(p_invoice_id UUID, p_user_id UUID DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_item RECORD;
  v_product_id UUID;
  v_vendor_item_id UUID;
  v_mapping_id UUID;
  v_previous_price NUMERIC;
  v_threshold NUMERIC := 10;
  v_price_variance_flag BOOLEAN;
  v_price_variance_percent NUMERIC;
  v_line_hash TEXT;
  v_existing_hash TEXT;
  v_updates_count INT := 0;
BEGIN
  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id;

  IF v_invoice IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Invoice not found');
  END IF;

  SELECT md5(COALESCE(jsonb_agg(jsonb_build_object(
      'id', ili.id,
      'item_name', ili.item_name,
      'quantity', ili.quantity,
      'unit_price', ili.unit_price,
      'total_price', ili.total_price,
      'vendor_item_code', ili.vendor_item_code,
      'vendor_unit', ili.vendor_unit
    ) ORDER BY ili.id)::TEXT, '[]'))
    INTO v_line_hash
  FROM public.invoice_line_items ili
  WHERE ili.invoice_id = p_invoice_id;

  SELECT hash INTO v_existing_hash
  FROM public.invoice_sync_log
  WHERE invoice_id = p_invoice_id
    AND operation = 'sync_invoice_products'
  ORDER BY processed_at DESC
  LIMIT 1;

  IF v_existing_hash IS NOT NULL AND v_existing_hash = v_line_hash THEN
    RETURN jsonb_build_object('status', 'success', 'updates_count', 0, 'idempotent', true);
  END IF;

  FOR v_item IN
    SELECT *
    FROM public.invoice_line_items
    WHERE invoice_id = p_invoice_id
      AND NULLIF(trim(COALESCE(item_name, '')), '') IS NOT NULL
  LOOP
    v_product_id := v_item.internal_product_id;
    v_vendor_item_id := NULL;
    v_mapping_id := NULL;
    v_price_variance_flag := false;
    v_price_variance_percent := 0;

    IF v_product_id IS NULL THEN
      SELECT id INTO v_product_id
      FROM public.products
      WHERE organization_id = v_invoice.organization_id
        AND lower(name) = lower(v_item.item_name)
        AND deleted_at IS NULL
        AND (
          brand_id IS NOT DISTINCT FROM v_invoice.brand_id
          OR brand_id IS NULL
        )
      ORDER BY CASE WHEN brand_id IS NOT DISTINCT FROM v_invoice.brand_id THEN 0 ELSE 1 END
      LIMIT 1;

      IF v_product_id IS NULL THEN
        INSERT INTO public.products (
          organization_id,
          brand_id,
          location_id,
          name,
          category,
          accounting_category,
          report_by_unit,
          base_unit,
          latest_price,
          is_inventoried,
          created_by,
          created_from_invoice_id
        ) VALUES (
          v_invoice.organization_id,
          v_invoice.brand_id,
          v_invoice.location_id,
          v_item.item_name,
          'Uncategorized',
          '5100',
          COALESCE(NULLIF(v_item.vendor_unit, ''), 'ea'),
          COALESCE(NULLIF(v_item.vendor_unit, ''), 'ea'),
          COALESCE(v_item.unit_price, 0),
          false,
          COALESCE(p_user_id, v_invoice.created_by),
          p_invoice_id
        )
        RETURNING id INTO v_product_id;
      ELSE
        UPDATE public.products
           SET latest_price = CASE
                 WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price
                 ELSE latest_price
               END,
               brand_id = COALESCE(brand_id, v_invoice.brand_id),
               location_id = COALESCE(location_id, v_invoice.location_id),
               updated_at = now()
         WHERE id = v_product_id;
      END IF;
    END IF;

    IF v_invoice.vendor_id IS NOT NULL THEN
      SELECT id, last_price, price_variance_threshold_percent
        INTO v_vendor_item_id, v_previous_price, v_threshold
      FROM public.vendor_items
      WHERE organization_id = v_invoice.organization_id
        AND vendor_id = v_invoice.vendor_id
        AND lower(vendor_item_name) = lower(v_item.item_name)
        AND COALESCE(vendor_item_code, '') = COALESCE(v_item.vendor_item_code, '')
      LIMIT 1;

      v_threshold := COALESCE(v_threshold, 10);

      IF v_vendor_item_id IS NOT NULL THEN
        IF COALESCE(v_previous_price, 0) > 0 AND COALESCE(v_item.unit_price, 0) > 0 THEN
          v_price_variance_percent := ((v_item.unit_price - v_previous_price) / v_previous_price) * 100;
          v_price_variance_flag := abs(v_price_variance_percent) >= v_threshold;
        END IF;

        UPDATE public.vendor_items
           SET vendor_unit = COALESCE(NULLIF(v_item.vendor_unit, ''), vendor_unit),
               previous_price = last_price,
               last_price = COALESCE(v_item.unit_price, last_price),
               last_invoice_id = p_invoice_id,
               last_invoice_line_id = v_item.id,
               last_purchased_at = COALESCE(v_invoice.invoice_date, CURRENT_DATE),
               last_price_change_percent = v_price_variance_percent,
               price_variance_flag = v_price_variance_flag,
               updated_at = now()
         WHERE id = v_vendor_item_id;
      ELSE
        INSERT INTO public.vendor_items (
          organization_id,
          vendor_id,
          vendor_item_code,
          vendor_item_name,
          vendor_unit,
          default_price,
          last_price,
          last_invoice_id,
          last_invoice_line_id,
          last_purchased_at,
          updated_at
        ) VALUES (
          v_invoice.organization_id,
          v_invoice.vendor_id,
          NULLIF(v_item.vendor_item_code, ''),
          v_item.item_name,
          NULLIF(v_item.vendor_unit, ''),
          v_item.unit_price,
          v_item.unit_price,
          p_invoice_id,
          v_item.id,
          COALESCE(v_invoice.invoice_date, CURRENT_DATE),
          now()
        )
        RETURNING id INTO v_vendor_item_id;
      END IF;

      IF v_product_id IS NOT NULL AND v_vendor_item_id IS NOT NULL THEN
        INSERT INTO public.vendor_item_mappings (
          organization_id,
          vendor_item_id,
          internal_product_id,
          conversion_multiplier,
          is_verified,
          updated_at
        ) VALUES (
          v_invoice.organization_id,
          v_vendor_item_id,
          v_product_id,
          1,
          false,
          now()
        )
        ON CONFLICT (vendor_item_id, internal_product_id)
        DO UPDATE SET updated_at = now()
        RETURNING id INTO v_mapping_id;
      END IF;
    END IF;

    UPDATE public.invoice_line_items
       SET vendor_id = v_invoice.vendor_id,
           vendor_item_id = v_vendor_item_id,
           internal_product_id = v_product_id,
           price_variance_flag = v_price_variance_flag,
           price_variance_percent = v_price_variance_percent
     WHERE id = v_item.id;

    v_updates_count := v_updates_count + 1;
  END LOOP;

  INSERT INTO public.invoice_event_log (invoice_id, event_type, new_value, actor_id)
  VALUES (
    p_invoice_id,
    'product_catalog_synced',
    jsonb_build_object('updates_count', v_updates_count),
    COALESCE(p_user_id, auth.uid())
  );

  INSERT INTO public.invoice_sync_log (invoice_id, operation, hash)
  VALUES (p_invoice_id, 'sync_invoice_products', v_line_hash);

  RETURN jsonb_build_object('status', 'success', 'updates_count', v_updates_count);
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260707000002_onboarding_draft_and_verification_settings.sql
-- ==========================================================================

BEGIN;

ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS onboarding_draft JSONB NOT NULL DEFAULT '{}'::jsonb;

CREATE TABLE IF NOT EXISTS public.platform_onboarding_settings (
  id BOOLEAN PRIMARY KEY DEFAULT true,
  ein_verification_enabled BOOLEAN NOT NULL DEFAULT true,
  ssn_verification_enabled BOOLEAN NOT NULL DEFAULT true,
  updated_by UUID REFERENCES auth.users(id),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT platform_onboarding_settings_singleton CHECK (id = true)
);

INSERT INTO public.platform_onboarding_settings (id, ein_verification_enabled, ssn_verification_enabled)
VALUES (true, true, true)
ON CONFLICT (id) DO NOTHING;

ALTER TABLE public.platform_onboarding_settings ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS platform_onboarding_settings_read ON public.platform_onboarding_settings;
CREATE POLICY platform_onboarding_settings_read
  ON public.platform_onboarding_settings FOR SELECT
  USING (auth.role() = 'authenticated');

DROP POLICY IF EXISTS platform_onboarding_settings_admin_update ON public.platform_onboarding_settings;
CREATE POLICY platform_onboarding_settings_admin_update
  ON public.platform_onboarding_settings FOR UPDATE
  USING (public.get_auth_role() = 'platform_admin')
  WITH CHECK (public.get_auth_role() = 'platform_admin');

CREATE OR REPLACE FUNCTION public.touch_platform_onboarding_settings_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_touch_platform_onboarding_settings ON public.platform_onboarding_settings;
CREATE TRIGGER trg_touch_platform_onboarding_settings
  BEFORE UPDATE ON public.platform_onboarding_settings
  FOR EACH ROW EXECUTE FUNCTION public.touch_platform_onboarding_settings_updated_at();

CREATE OR REPLACE FUNCTION public.get_onboarding_verification_settings()
RETURNS JSONB
LANGUAGE sql
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT jsonb_build_object(
    'ein_verification_enabled', ein_verification_enabled,
    'ssn_verification_enabled', ssn_verification_enabled,
    'updated_at', updated_at
  )
  FROM public.platform_onboarding_settings
  WHERE id = true;
$$;

CREATE OR REPLACE FUNCTION public.update_onboarding_verification_settings(
  p_ein_enabled BOOLEAN,
  p_ssn_enabled BOOLEAN
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_settings public.platform_onboarding_settings%ROWTYPE;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  UPDATE public.platform_onboarding_settings
  SET ein_verification_enabled = COALESCE(p_ein_enabled, ein_verification_enabled),
      ssn_verification_enabled = COALESCE(p_ssn_enabled, ssn_verification_enabled)
  WHERE id = true
  RETURNING * INTO v_settings;

  RETURN jsonb_build_object(
    'success', true,
    'ein_verification_enabled', v_settings.ein_verification_enabled,
    'ssn_verification_enabled', v_settings.ssn_verification_enabled,
    'updated_at', v_settings.updated_at
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.get_my_business_verification_draft()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_profile RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT onboarding_draft, onboarding_current_step, onboarding_status
  INTO v_profile
  FROM public.profiles
  WHERE id = auth.uid();

  RETURN jsonb_build_object(
    'draft', COALESCE(v_profile.onboarding_draft, '{}'::jsonb),
    'current_step', v_profile.onboarding_current_step,
    'status', v_profile.onboarding_status
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.save_business_verification_draft(
  p_payload JSONB,
  p_step TEXT DEFAULT 'business_information'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_run_id UUID;
  v_step TEXT := COALESCE(NULLIF(btrim(p_step), ''), 'business_information');
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  UPDATE public.profiles
  SET onboarding_draft = COALESCE(p_payload, '{}'::jsonb),
      onboarding_status = CASE WHEN onboarding_status = 'completed' THEN onboarding_status ELSE 'in_progress' END,
      onboarding_current_step = v_step,
      updated_at = now()
  WHERE id = v_user_id;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(v_run_id, v_user_id, v_step, 'draft_saved', 'in_progress', jsonb_build_object('source', 'business_verification'));

  RETURN jsonb_build_object('success', true, 'current_step', v_step);
END;
$$;

CREATE OR REPLACE FUNCTION public.submit_business_verification(p_payload JSONB)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_run_id UUID;
  v_legal_name TEXT;
  v_business_type TEXT;
  v_identifier_type TEXT;
  v_identifier_required BOOLEAN;
  v_identifier_last4 TEXT;
  v_email TEXT;
  v_phone TEXT;
  v_website TEXT;
  v_provider TEXT;
  v_score INTEGER := 0;
  v_status TEXT;
  v_business_address JSONB;
  v_mailing_address JSONB;
  v_service_address JSONB;
  v_same_mailing BOOLEAN;
  v_verification_id UUID;
  v_settings RECORD;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT ein_verification_enabled, ssn_verification_enabled
  INTO v_settings
  FROM public.platform_onboarding_settings
  WHERE id = true;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  v_legal_name := NULLIF(btrim(p_payload->>'legalName'), '');
  v_business_type := COALESCE(NULLIF(btrim(p_payload->>'businessType'), ''), 'llc');
  v_identifier_type := COALESCE(NULLIF(btrim(p_payload->>'identifierType'), ''), public.required_tax_identifier_type_for_business_type(v_business_type));
  v_identifier_required := CASE
    WHEN v_identifier_type = 'ein' THEN COALESCE(v_settings.ein_verification_enabled, true)
    WHEN v_identifier_type = 'ssn' THEN COALESCE(v_settings.ssn_verification_enabled, true)
    ELSE true
  END;
  v_identifier_last4 := CASE WHEN v_identifier_required THEN public.mask_tax_identifier(p_payload->>'taxIdentifier') ELSE NULL END;
  v_email := NULLIF(btrim(p_payload->>'email'), '');
  v_phone := NULLIF(btrim(p_payload->>'phone'), '');
  v_website := NULLIF(btrim(p_payload->>'website'), '');
  v_business_address := COALESCE(p_payload->'businessAddress', '{}'::jsonb);
  v_same_mailing := COALESCE((p_payload->>'sameMailing')::boolean, true);
  v_mailing_address := CASE
    WHEN v_same_mailing THEN v_business_address
    ELSE COALESCE(p_payload->'mailingAddress', '{}'::jsonb)
  END;
  v_service_address := COALESCE(p_payload->'serviceAddress', '{}'::jsonb);

  IF v_legal_name IS NULL THEN
    RAISE EXCEPTION 'Legal business name is required';
  END IF;

  IF v_identifier_type NOT IN ('ein', 'ssn') THEN
    RAISE EXCEPTION 'Tax identifier type must be ein or ssn';
  END IF;

  IF v_identifier_type IS DISTINCT FROM public.required_tax_identifier_type_for_business_type(v_business_type) THEN
    RAISE EXCEPTION 'Tax identifier type % is not allowed for business type %', v_identifier_type, v_business_type;
  END IF;

  IF v_identifier_required AND length(COALESCE(v_identifier_last4, '')) <> 4 THEN
    RAISE EXCEPTION 'Valid tax identifier is required';
  END IF;

  IF v_email IS NULL OR position('@' in v_email) = 0 THEN
    RAISE EXCEPTION 'A valid business email is required';
  END IF;

  IF length(regexp_replace(COALESCE(v_phone, ''), '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid business phone number is required';
  END IF;

  IF NULLIF(btrim(v_business_address->>'line1'), '') IS NULL
     OR NULLIF(btrim(v_business_address->>'city'), '') IS NULL
     OR NULLIF(btrim(v_business_address->>'state'), '') IS NULL
     OR length(regexp_replace(COALESCE(v_business_address->>'zip', ''), '\D', '', 'g')) < 5 THEN
    RAISE EXCEPTION 'Business address must include street, city, state, and ZIP';
  END IF;

  IF NULLIF(btrim(v_service_address->>'line1'), '') IS NULL
     OR NULLIF(btrim(v_service_address->>'city'), '') IS NULL
     OR NULLIF(btrim(v_service_address->>'state'), '') IS NULL
     OR length(regexp_replace(COALESCE(v_service_address->>'zip', ''), '\D', '', 'g')) < 5 THEN
    RAISE EXCEPTION 'Service address must include street, city, state, and ZIP';
  END IF;

  v_score := CASE
    WHEN NOT v_identifier_required THEN 60
    WHEN v_identifier_type = 'ein' THEN 50
    ELSE 45
  END;
  IF v_email LIKE '%@%' THEN v_score := v_score + 10; END IF;
  IF length(regexp_replace(v_phone, '\D', '', 'g')) >= 10 THEN v_score := v_score + 10; END IF;
  IF v_website IS NOT NULL THEN v_score := v_score + 10; END IF;
  IF length(regexp_replace(COALESCE(v_business_address->>'zip', ''), '\D', '', 'g')) >= 5 THEN v_score := v_score + 10; END IF;
  IF length(regexp_replace(COALESCE(v_service_address->>'zip', ''), '\D', '', 'g')) >= 5 THEN v_score := v_score + 10; END IF;
  v_score := LEAST(v_score, 100);
  v_status := CASE WHEN v_score >= 80 THEN 'verified' WHEN v_score >= 50 THEN 'pending_review' ELSE 'failed' END;
  v_provider := CASE
    WHEN NOT v_identifier_required THEN v_identifier_type || '_verification_disabled_by_platform'
    WHEN v_identifier_type = 'ein' THEN 'global_database_kyb'
    ELSE 'searchbug_ssn'
  END;

  INSERT INTO public.business_verifications (
    user_id,
    legal_business_name,
    business_type,
    identifier_type,
    identifier_last4,
    provider_name,
    provider_reference_id,
    verification_status,
    trust_score,
    metadata
  )
  VALUES (
    v_user_id,
    v_legal_name,
    v_business_type,
    v_identifier_type,
    v_identifier_last4,
    v_provider,
    CASE WHEN v_identifier_required THEN 'provider-ready-' || replace(gen_random_uuid()::text, '-', '') ELSE 'verification-disabled' END,
    v_status,
    v_score,
    jsonb_build_object(
      'email', v_email,
      'phone', v_phone,
      'website', v_website,
      'tax_identifier_required', v_identifier_required,
      'ein_verification_enabled', COALESCE(v_settings.ein_verification_enabled, true),
      'ssn_verification_enabled', COALESCE(v_settings.ssn_verification_enabled, true),
      'provider_mode', CASE WHEN v_identifier_required THEN 'simulation_until_provider_keys_configured' ELSE 'disabled_by_platform_admin' END
    )
  )
  RETURNING id INTO v_verification_id;

  DELETE FROM public.organization_addresses
  WHERE user_id = v_user_id
    AND organization_id IS NULL;

  INSERT INTO public.organization_addresses (
    user_id,
    address_type,
    location_name,
    address_line_1,
    address_line_2,
    city,
    state,
    zip_code,
    country,
    usps_verified,
    usps_standardized,
    usps_validation_code
  )
  VALUES
    (v_user_id, 'business', NULL, btrim(v_business_address->>'line1'), NULLIF(btrim(v_business_address->>'line2'), ''), btrim(v_business_address->>'city'), btrim(v_business_address->>'state'), btrim(v_business_address->>'zip'), 'US', true, true, 'PROVIDER_READY_USPS'),
    (v_user_id, 'mailing', NULL, btrim(v_mailing_address->>'line1'), NULLIF(btrim(v_mailing_address->>'line2'), ''), btrim(v_mailing_address->>'city'), btrim(v_mailing_address->>'state'), btrim(v_mailing_address->>'zip'), 'US', true, true, CASE WHEN v_same_mailing THEN 'SAME_AS_BUSINESS' ELSE 'PROVIDER_READY_USPS' END),
    (v_user_id, 'service', NULLIF(btrim(p_payload->>'serviceLocationName'), ''), btrim(v_service_address->>'line1'), NULLIF(btrim(v_service_address->>'line2'), ''), btrim(v_service_address->>'city'), btrim(v_service_address->>'state'), btrim(v_service_address->>'zip'), 'US', true, true, 'PROVIDER_READY_USPS');

  UPDATE public.profiles
  SET business_verification_status = v_status,
      business_verification_score = v_score,
      business_verification_provider = v_provider,
      business_verified_at = CASE WHEN v_status = 'verified' THEN now() ELSE NULL END,
      business_type = v_business_type,
      tax_identifier_type = v_identifier_type,
      tax_identifier_last4 = v_identifier_last4,
      onboarding_draft = '{}'::jsonb,
      onboarding_status = CASE WHEN v_status = 'pending_review' THEN 'pending_review' ELSE 'in_progress' END,
      onboarding_current_step = CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'business_verification' END,
      updated_at = now()
  WHERE id = v_user_id;

  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'business_verification',
    CASE WHEN v_status = 'verified' THEN 'verified' WHEN v_status = 'failed' THEN 'failed' ELSE 'submitted' END,
    v_status,
    jsonb_build_object('verification_id', v_verification_id, 'trust_score', v_score, 'tax_identifier_required', v_identifier_required)
  );

  RETURN jsonb_build_object(
    'success', true,
    'verification_id', v_verification_id,
    'status', v_status,
    'trust_score', v_score,
    'tax_identifier_required', v_identifier_required,
    'next_step', CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'manual_review' END
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_onboarding_verification_settings() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.update_onboarding_verification_settings(BOOLEAN, BOOLEAN) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_my_business_verification_draft() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.save_business_verification_draft(JSONB, TEXT) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.submit_business_verification(JSONB) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260707000003_onboarding_audit_log_coverage.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.redact_onboarding_audit_payload(
  p_table_name TEXT,
  p_payload JSONB
)
RETURNS JSONB
LANGUAGE plpgsql
IMMUTABLE
SET search_path = ''
AS $$
DECLARE
  v_payload JSONB := COALESCE(p_payload, '{}'::jsonb);
BEGIN
  IF p_payload IS NULL THEN
    RETURN NULL;
  END IF;

  IF p_table_name = 'profiles' THEN
    v_payload := v_payload - 'onboarding_draft';
    IF p_payload ? 'onboarding_draft' THEN
      v_payload := v_payload || jsonb_build_object('onboarding_draft_redacted', true);
    END IF;
  END IF;

  IF p_table_name = 'onboarding_contact_otps' THEN
    v_payload := v_payload - 'code_hash' - 'provider_reference_id';
  END IF;

  IF p_table_name = 'tenant_payment_authorizations' THEN
    v_payload := v_payload - 'signature_payload' - 'signature_storage_path' - 'consent_text';
  END IF;

  IF p_table_name = 'onboarding_bank_accounts' THEN
    v_payload := v_payload - 'banking_secret_id';
  END IF;

  IF p_table_name = 'invitations' THEN
    v_payload := v_payload - 'token' - 'invite_token' - 'invitation_token' - 'raw_token';
  END IF;

  RETURN v_payload;
END;
$$;

CREATE OR REPLACE FUNCTION public.resolve_onboarding_audit_org_id(p_row JSONB)
RETURNS UUID
LANGUAGE plpgsql
STABLE
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
  v_user_id UUID;
BEGIN
  IF p_row ? 'organization_id'
     AND COALESCE(p_row->>'organization_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN (p_row->>'organization_id')::UUID;
  END IF;

  IF p_row ? 'user_id'
     AND COALESCE(p_row->>'user_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_user_id := (p_row->>'user_id')::UUID;
  ELSIF p_row ? 'id'
     AND COALESCE(p_row->>'id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_user_id := (p_row->>'id')::UUID;
  END IF;

  IF v_user_id IS NOT NULL THEN
    SELECT organization_id INTO v_org_id
    FROM public.profiles
    WHERE id = v_user_id;
  END IF;

  RETURN v_org_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.process_onboarding_audit_log()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_old JSONB;
  v_new JSONB;
  v_row JSONB;
  v_org_id UUID;
  v_record_id UUID;
  v_target_user_id UUID;
  v_entity_id TEXT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_old := public.redact_onboarding_audit_payload(TG_TABLE_NAME, to_jsonb(OLD));
    v_row := COALESCE(to_jsonb(OLD), '{}'::jsonb);
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := public.redact_onboarding_audit_payload(TG_TABLE_NAME, to_jsonb(OLD));
    v_new := public.redact_onboarding_audit_payload(TG_TABLE_NAME, to_jsonb(NEW));
    v_row := COALESCE(to_jsonb(NEW), '{}'::jsonb);
  ELSE
    v_new := public.redact_onboarding_audit_payload(TG_TABLE_NAME, to_jsonb(NEW));
    v_row := COALESCE(to_jsonb(NEW), '{}'::jsonb);
  END IF;

  IF v_row ? 'id'
     AND COALESCE(v_row->>'id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_record_id := (v_row->>'id')::UUID;
    v_entity_id := v_row->>'id';
  ELSE
    v_entity_id := COALESCE(v_row->>'id', TG_TABLE_NAME);
  END IF;

  IF v_row ? 'user_id'
     AND COALESCE(v_row->>'user_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_target_user_id := (v_row->>'user_id')::UUID;
  ELSIF TG_TABLE_NAME = 'profiles'
     AND v_row ? 'id'
     AND COALESCE(v_row->>'id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_target_user_id := (v_row->>'id')::UUID;
  ELSIF v_row ? 'target_user_id'
     AND COALESCE(v_row->>'target_user_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_target_user_id := (v_row->>'target_user_id')::UUID;
  END IF;

  v_org_id := public.resolve_onboarding_audit_org_id(v_row);

  INSERT INTO public.audit_logs (
    organization_id,
    user_id,
    action,
    table_name,
    record_id,
    old_data,
    new_data,
    entity_type,
    entity_id,
    module,
    details
  ) VALUES (
    v_org_id,
    COALESCE(v_actor, v_target_user_id),
    TG_OP,
    TG_TABLE_NAME,
    v_record_id,
    v_old,
    v_new,
    TG_TABLE_NAME,
    v_entity_id,
    'onboarding',
    jsonb_build_object(
      'source', 'onboarding_audit_trigger',
      'target_user_id', v_target_user_id,
      'actor_user_id', v_actor,
      'redacted_fields', CASE
        WHEN TG_TABLE_NAME = 'profiles' THEN jsonb_build_array('onboarding_draft')
        WHEN TG_TABLE_NAME = 'onboarding_contact_otps' THEN jsonb_build_array('code_hash', 'provider_reference_id')
        WHEN TG_TABLE_NAME = 'tenant_payment_authorizations' THEN jsonb_build_array('signature_payload', 'signature_storage_path', 'consent_text')
        WHEN TG_TABLE_NAME = 'onboarding_bank_accounts' THEN jsonb_build_array('banking_secret_id')
        WHEN TG_TABLE_NAME = 'invitations' THEN jsonb_build_array('token', 'invite_token', 'invitation_token', 'raw_token')
        ELSE '[]'::jsonb
      END
    )::TEXT
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

DO $$
DECLARE
  v_table TEXT;
BEGIN
  FOREACH v_table IN ARRAY ARRAY[
    'business_verifications',
    'organization_addresses',
    'onboarding_workflow_runs',
    'onboarding_step_events',
    'onboarding_payment_methods',
    'onboarding_contact_otps',
    'onboarding_bank_accounts',
    'tenant_payment_authorizations',
    'onboarding_admin_actions',
    'platform_onboarding_settings',
    'invitations'
  ] LOOP
    IF to_regclass('public.' || v_table) IS NOT NULL THEN
      EXECUTE format('DROP TRIGGER IF EXISTS audit_onboarding_%I ON public.%I', v_table, v_table);
      EXECUTE format('CREATE TRIGGER audit_onboarding_%I AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.process_onboarding_audit_log()', v_table, v_table);
    END IF;
  END LOOP;
END $$;

DROP TRIGGER IF EXISTS audit_onboarding_profiles ON public.profiles;
CREATE TRIGGER audit_onboarding_profiles
AFTER UPDATE OF
  onboarding_status,
  onboarding_current_step,
  onboarding_completed_at,
  onboarding_draft,
  business_email,
  business_email_verified_at,
  business_phone,
  business_phone_verified_at,
  business_verification_status,
  business_verification_score,
  business_verification_provider,
  business_verified_at,
  business_type,
  tax_identifier_type,
  tax_identifier_last4,
  payment_method_type,
  payment_method_verified_at
ON public.profiles
FOR EACH ROW EXECUTE FUNCTION public.process_onboarding_audit_log();

DO $$
DECLARE
  v_table TEXT;
  v_record RECORD;
  v_record_id UUID;
  v_target_user_id UUID;
  v_org_id UUID;
  v_entity_id TEXT;
  v_row JSONB;
BEGIN
  FOREACH v_table IN ARRAY ARRAY[
    'business_verifications',
    'organization_addresses',
    'onboarding_workflow_runs',
    'onboarding_step_events',
    'onboarding_payment_methods',
    'onboarding_contact_otps',
    'onboarding_bank_accounts',
    'tenant_payment_authorizations',
    'onboarding_admin_actions',
    'platform_onboarding_settings',
    'invitations'
  ] LOOP
    IF to_regclass('public.' || v_table) IS NULL THEN
      CONTINUE;
    END IF;

    FOR v_record IN EXECUTE format('SELECT to_jsonb(t) AS row_data FROM public.%I t', v_table) LOOP
      v_row := v_record.row_data;
      v_record_id := NULL;
      v_target_user_id := NULL;
      v_entity_id := COALESCE(v_row->>'id', v_table);

      IF COALESCE(v_row->>'id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_record_id := (v_row->>'id')::UUID;
      END IF;

      IF COALESCE(v_row->>'user_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_target_user_id := (v_row->>'user_id')::UUID;
      ELSIF COALESCE(v_row->>'target_user_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_target_user_id := (v_row->>'target_user_id')::UUID;
      END IF;

      v_org_id := public.resolve_onboarding_audit_org_id(v_row);

      IF NOT EXISTS (
        SELECT 1 FROM public.audit_logs
        WHERE table_name = v_table
          AND action = 'BACKFILL'
          AND COALESCE(entity_id, '') = COALESCE(v_entity_id, '')
      ) THEN
        INSERT INTO public.audit_logs (
          organization_id,
          user_id,
          action,
          table_name,
          record_id,
          new_data,
          entity_type,
          entity_id,
          module,
          details
        ) VALUES (
          v_org_id,
          v_target_user_id,
          'BACKFILL',
          v_table,
          v_record_id,
          public.redact_onboarding_audit_payload(v_table, v_row),
          v_table,
          v_entity_id,
          'onboarding',
          jsonb_build_object('source', 'onboarding_audit_backfill')::TEXT
        );
      END IF;
    END LOOP;
  END LOOP;
END $$;

INSERT INTO public.audit_logs (
  organization_id,
  user_id,
  action,
  table_name,
  record_id,
  new_data,
  entity_type,
  entity_id,
  module,
  details
)
SELECT
  public.resolve_onboarding_audit_org_id(to_jsonb(p)),
  p.id,
  'BACKFILL',
  'profiles',
  p.id,
  public.redact_onboarding_audit_payload('profiles', to_jsonb(p)),
  'profiles',
  p.id::TEXT,
  'onboarding',
  jsonb_build_object('source', 'onboarding_profile_audit_backfill')::TEXT
FROM public.profiles p
WHERE (
    COALESCE(p.onboarding_status, 'not_started') <> 'not_started'
    OR COALESCE(p.business_verification_status, 'not_started') <> 'not_started'
    OR p.business_email_verified_at IS NOT NULL
    OR p.business_phone_verified_at IS NOT NULL
    OR p.payment_method_verified_at IS NOT NULL
  )
  AND NOT EXISTS (
    SELECT 1 FROM public.audit_logs a
    WHERE a.table_name = 'profiles'
      AND a.action = 'BACKFILL'
      AND a.entity_id = p.id::TEXT
  );
REVOKE ALL ON FUNCTION public.redact_onboarding_audit_payload(TEXT, JSONB) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.resolve_onboarding_audit_org_id(JSONB) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.process_onboarding_audit_log() FROM PUBLIC, anon;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260708000001_invitation_signup_validation_status.sql
-- ==========================================================================

ALTER TABLE public.invitations
  ADD COLUMN IF NOT EXISTS closed_at timestamptz;

DROP FUNCTION IF EXISTS public.get_invite_details(text);

CREATE OR REPLACE FUNCTION public.get_invite_details(invite_token text)
RETURNS TABLE (
  id uuid,
  email text,
  role text,
  organization_id uuid,
  organization_name text,
  invited_by uuid,
  expires_at timestamptz,
  metadata jsonb,
  status text,
  status_message text
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT
    i.id,
    i.email,
    i.role,
    i.organization_id,
    o.name AS organization_name,
    i.invited_by,
    i.expires_at,
    i.metadata,
    CASE
      WHEN i.accepted_at IS NOT NULL THEN 'accepted'
      WHEN i.closed_at IS NOT NULL THEN 'closed'
      WHEN i.expires_at IS NOT NULL AND i.expires_at <= now() THEN 'expired'
      ELSE 'active'
    END AS status,
    CASE
      WHEN i.accepted_at IS NOT NULL THEN 'This invitation was already accepted. Please sign in instead.'
      WHEN i.closed_at IS NOT NULL THEN 'This invitation was closed by the Platform Admin. Please ask for a new invite.'
      WHEN i.expires_at IS NOT NULL AND i.expires_at <= now() THEN 'This invitation link has expired. Please ask the Platform Admin to reissue the invite.'
      ELSE 'Invitation is active.'
    END AS status_message
  FROM public.invitations i
  LEFT JOIN public.organizations o ON o.id = i.organization_id
  WHERE btrim(i.token) = btrim(invite_token)
  LIMIT 1;
$$;

GRANT EXECUTE ON FUNCTION public.get_invite_details(text) TO anon, authenticated;

NOTIFY pgrst, 'reload schema';

-- ==========================================================================
-- Source: 20260708000002_tenant_super_admin_org_manager_role_model.sql
-- ==========================================================================

-- Tenant Super Admin + Org Manager role model.
-- Adds a business tenant layer above organizations and migrates the
-- legacy customer-facing owner role to org_manager.

BEGIN;

ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS tenant_id uuid;
ALTER TABLE public.invitations ADD COLUMN IF NOT EXISTS tenant_id uuid;
ALTER TABLE public.organizations ADD COLUMN IF NOT EXISTS tenant_id uuid;

CREATE TABLE IF NOT EXISTS public.tenants (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  slug text UNIQUE,
  owner_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  status text NOT NULL DEFAULT 'active',
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT tenants_status_check CHECK (status IN ('active', 'suspended', 'archived'))
);

ALTER TABLE public.organizations
  DROP CONSTRAINT IF EXISTS organizations_tenant_id_fkey;
ALTER TABLE public.organizations
  ADD CONSTRAINT organizations_tenant_id_fkey
  FOREIGN KEY (tenant_id) REFERENCES public.tenants(id) ON DELETE SET NULL;

ALTER TABLE public.profiles
  DROP CONSTRAINT IF EXISTS profiles_tenant_id_fkey;
ALTER TABLE public.profiles
  ADD CONSTRAINT profiles_tenant_id_fkey
  FOREIGN KEY (tenant_id) REFERENCES public.tenants(id) ON DELETE SET NULL;

ALTER TABLE public.invitations
  DROP CONSTRAINT IF EXISTS invitations_tenant_id_fkey;
ALTER TABLE public.invitations
  ADD CONSTRAINT invitations_tenant_id_fkey
  FOREIGN KEY (tenant_id) REFERENCES public.tenants(id) ON DELETE SET NULL;

CREATE TABLE IF NOT EXISTS public.tenant_members (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  role text NOT NULL DEFAULT 'org_manager',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_organizations_tenant_id ON public.organizations(tenant_id);
CREATE INDEX IF NOT EXISTS idx_profiles_tenant_id ON public.profiles(tenant_id);
CREATE INDEX IF NOT EXISTS idx_invitations_tenant_id ON public.invitations(tenant_id);
CREATE INDEX IF NOT EXISTS idx_tenant_members_user_id ON public.tenant_members(user_id);

CREATE OR REPLACE FUNCTION public.normalize_app_role(p_role text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE COALESCE(NULLIF(p_role, ''), 'ground_staff')
    WHEN 'owner' THEN 'org_manager'
    WHEN 'org_owner' THEN 'org_manager'
    WHEN 'manager' THEN 'branch_manager'
    WHEN 'admin' THEN 'platform_admin'
    ELSE p_role
  END;
$$;

CREATE OR REPLACE FUNCTION public.touch_tenant_updated_at()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_touch_tenants_updated_at ON public.tenants;
CREATE TRIGGER trg_touch_tenants_updated_at
BEFORE UPDATE ON public.tenants
FOR EACH ROW EXECUTE FUNCTION public.touch_tenant_updated_at();

DROP TRIGGER IF EXISTS trg_touch_tenant_members_updated_at ON public.tenant_members;
CREATE TRIGGER trg_touch_tenant_members_updated_at
BEFORE UPDATE ON public.tenant_members
FOR EACH ROW EXECUTE FUNCTION public.touch_tenant_updated_at();

-- Backfill one business tenant per current organization owner where possible.
INSERT INTO public.tenants (name, slug, owner_id, metadata)
SELECT
  COALESCE(max(o.name) FILTER (WHERE o.owner_id IS NOT NULL), max(o.name), 'Tenant') AS name,
  left(
    'tenant_' ||
    regexp_replace(lower(COALESCE(max(o.slug), max(o.name), min(o.id::text))), '[^a-z0-9]+', '_', 'g') ||
    '_' || replace(left(min(o.id::text), 8), '-', ''),
    63
  ) AS slug,
  o.owner_id,
  jsonb_build_object('source', 'tenant_super_admin_org_manager_backfill')
FROM public.organizations o
WHERE o.tenant_id IS NULL
GROUP BY COALESCE(o.owner_id, o.id), o.owner_id
ON CONFLICT (slug) DO NOTHING;

UPDATE public.organizations o
SET tenant_id = t.id
FROM public.tenants t
WHERE o.tenant_id IS NULL
  AND (
    (o.owner_id IS NOT NULL AND t.owner_id = o.owner_id)
    OR t.slug = left(
      'tenant_' ||
      regexp_replace(lower(COALESCE(o.slug, o.name, o.id::text)), '[^a-z0-9]+', '_', 'g') ||
      '_' || replace(left(o.id::text, 8), '-', ''),
      63
    )
  );

INSERT INTO public.tenants (name, slug, owner_id, metadata)
SELECT
  COALESCE(o.name, 'Tenant'),
  left(
    'tenant_' ||
    regexp_replace(lower(COALESCE(o.slug, o.name, o.id::text)), '[^a-z0-9]+', '_', 'g') ||
    '_' || replace(left(o.id::text, 8), '-', ''),
    63
  ),
  o.owner_id,
  jsonb_build_object('source', 'tenant_super_admin_org_manager_backfill_fallback')
FROM public.organizations o
WHERE o.tenant_id IS NULL
ON CONFLICT (slug) DO NOTHING;

UPDATE public.organizations o
SET tenant_id = t.id
FROM public.tenants t
WHERE o.tenant_id IS NULL
  AND t.slug = left(
    'tenant_' ||
    regexp_replace(lower(COALESCE(o.slug, o.name, o.id::text)), '[^a-z0-9]+', '_', 'g') ||
    '_' || replace(left(o.id::text, 8), '-', ''),
    63
  );

UPDATE public.profiles p
SET tenant_id = o.tenant_id
FROM public.organizations o
WHERE p.organization_id = o.id
  AND p.tenant_id IS NULL;

UPDATE public.invitations i
SET tenant_id = o.tenant_id
FROM public.organizations o
WHERE i.organization_id = o.id
  AND i.tenant_id IS NULL;

ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_role_check;
ALTER TABLE public.invitations DROP CONSTRAINT IF EXISTS invitations_role_check;
ALTER TABLE public.tenant_members DROP CONSTRAINT IF EXISTS tenant_members_role_check;

-- Normalize stored role values.
UPDATE public.profiles SET role = public.normalize_app_role(role) WHERE role IN ('owner', 'org_owner', 'manager', 'admin');
UPDATE public.invitations SET role = public.normalize_app_role(role) WHERE role IN ('owner', 'org_owner', 'manager', 'admin');
UPDATE public.organization_members SET role = public.normalize_app_role(role) WHERE role IN ('owner', 'org_owner', 'manager', 'admin');
UPDATE public.brand_members SET role = public.normalize_app_role(role) WHERE role IN ('owner', 'org_owner', 'manager', 'admin');
UPDATE public.location_members SET role = public.normalize_app_role(role) WHERE role IN ('owner', 'org_owner', 'manager', 'admin');

UPDATE auth.users
SET raw_app_meta_data = jsonb_set(COALESCE(raw_app_meta_data, '{}'::jsonb), '{role}', '"org_manager"'::jsonb, true)
WHERE raw_app_meta_data ->> 'role' = 'org_owner';

UPDATE auth.users
SET raw_user_meta_data = jsonb_set(COALESCE(raw_user_meta_data, '{}'::jsonb), '{role}', '"org_manager"'::jsonb, true)
WHERE raw_user_meta_data ->> 'role' = 'org_owner';

INSERT INTO public.tenant_members (tenant_id, user_id, role)
SELECT DISTINCT o.tenant_id, o.owner_id, 'tenant_super_admin'
FROM public.organizations o
WHERE o.tenant_id IS NOT NULL
  AND o.owner_id IS NOT NULL
ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

INSERT INTO public.tenant_members (tenant_id, user_id, role)
SELECT DISTINCT p.tenant_id, p.id, p.role
FROM public.profiles p
WHERE p.tenant_id IS NOT NULL
  AND p.role IN ('tenant_super_admin', 'org_manager')
ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

UPDATE public.profiles p
SET role = 'tenant_super_admin'
FROM public.tenant_members tm
WHERE tm.user_id = p.id
  AND tm.role = 'tenant_super_admin'
  AND p.id IN (SELECT owner_id FROM public.organizations WHERE owner_id IS NOT NULL);



ALTER TABLE public.profiles ADD CONSTRAINT profiles_role_check CHECK (
  role IN ('ground_staff', 'location_manager', 'brand_manager', 'branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin')
);

ALTER TABLE public.invitations ADD CONSTRAINT invitations_role_check CHECK (
  role IN ('ground_staff', 'location_manager', 'brand_manager', 'branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin')
);

ALTER TABLE public.tenant_members ADD CONSTRAINT tenant_members_role_check CHECK (
  role IN ('org_manager', 'tenant_super_admin')
);

-- Soft role checks for membership tables. Existing custom roles remain possible
-- through public.roles/user_roles, so these are not constrained here.

INSERT INTO public.roles (name, is_system)
VALUES
  ('ground_staff', true),
  ('location_manager', true),
  ('branch_manager', true),
  ('brand_manager', true),
  ('org_manager', true),
  ('tenant_super_admin', true),
  ('platform_admin', true)
ON CONFLICT (name) WHERE is_system = true DO UPDATE SET is_system = true;

DO $$
DECLARE
  v_legacy_owner_role_id uuid;
  v_org_manager_role_id uuid;
BEGIN
  SELECT id INTO v_legacy_owner_role_id FROM public.roles WHERE name = 'org_owner' LIMIT 1;
  SELECT id INTO v_org_manager_role_id FROM public.roles WHERE name = 'org_manager' LIMIT 1;

  IF v_legacy_owner_role_id IS NOT NULL AND v_org_manager_role_id IS NOT NULL THEN
    DELETE FROM public.user_roles legacy_ur
    WHERE legacy_ur.role_id = v_legacy_owner_role_id
      AND EXISTS (
        SELECT 1
        FROM public.user_roles manager_ur
        WHERE manager_ur.user_id = legacy_ur.user_id
          AND manager_ur.role_id = v_org_manager_role_id
      );

    UPDATE public.user_roles
    SET role_id = v_org_manager_role_id
    WHERE role_id = v_legacy_owner_role_id;

    DELETE FROM public.role_permissions
    WHERE role_id = v_legacy_owner_role_id;

    DELETE FROM public.roles
    WHERE id = v_legacy_owner_role_id;
  END IF;
END $$;
CREATE OR REPLACE FUNCTION public.normalize_app_role(p_role text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE lower(NULLIF(trim(p_role), ''))
    WHEN 'owner' THEN 'org_manager'
    WHEN 'manager' THEN 'branch_manager'
    WHEN 'admin' THEN 'platform_admin'
    ELSE lower(NULLIF(trim(p_role), ''))
  END;
$$;

CREATE OR REPLACE FUNCTION public.get_auth_role()
RETURNS text
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT public.normalize_app_role(COALESCE((SELECT role FROM public.profiles WHERE id = auth.uid()), 'ground_staff'));
$$;

CREATE OR REPLACE FUNCTION public.get_auth_tenant()
RETURNS uuid
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE(
    (SELECT p.tenant_id FROM public.profiles p WHERE p.id = auth.uid()),
    (SELECT o.tenant_id FROM public.profiles p JOIN public.organizations o ON o.id = p.organization_id WHERE p.id = auth.uid()),
    (SELECT tm.tenant_id FROM public.tenant_members tm WHERE tm.user_id = auth.uid() ORDER BY tm.created_at LIMIT 1)
  );
$$;

CREATE OR REPLACE FUNCTION public.is_tenant_super_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT public.get_auth_role() = 'tenant_super_admin';
$$;

CREATE OR REPLACE FUNCTION public.is_platform_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT public.get_auth_role() = 'platform_admin';
$$;

CREATE OR REPLACE FUNCTION public.is_manager_or_above()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT public.get_auth_role() IN (
    'location_manager',
    'branch_manager',
    'brand_manager',
    'org_manager',
    'tenant_super_admin',
    'platform_admin'
  );
$$;

CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT public.get_auth_role() IN ('org_manager', 'tenant_super_admin', 'platform_admin');
$$;

CREATE OR REPLACE FUNCTION public.is_owner_or_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT public.get_auth_role() IN ('org_manager', 'tenant_super_admin', 'platform_admin');
$$;

CREATE OR REPLACE FUNCTION public.access_role_rank(p_role text)
RETURNS integer
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE public.normalize_app_role(p_role)
    WHEN 'ground_staff' THEN 10
    WHEN 'location_manager' THEN 20
    WHEN 'branch_manager' THEN 30
    WHEN 'brand_manager' THEN 30
    WHEN 'org_manager' THEN 40
    WHEN 'tenant_super_admin' THEN 50
    WHEN 'platform_admin' THEN 60
    ELSE 0
  END;
$$;

CREATE OR REPLACE FUNCTION public.can_invite_role(target_role text)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  caller_role text := public.get_auth_role();
  normalized_target text := public.normalize_app_role(target_role);
BEGIN
  IF caller_role = 'platform_admin' THEN
    RETURN normalized_target IN ('ground_staff', 'location_manager', 'brand_manager', 'branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin');
  END IF;

  IF caller_role = 'tenant_super_admin' THEN
    RETURN normalized_target IN ('ground_staff', 'location_manager', 'brand_manager', 'branch_manager', 'org_manager', 'tenant_super_admin');
  END IF;

  IF caller_role = 'org_manager' THEN
    RETURN normalized_target IN ('ground_staff', 'location_manager', 'brand_manager', 'branch_manager');
  END IF;

  IF caller_role IN ('brand_manager', 'branch_manager') THEN
    RETURN normalized_target IN ('ground_staff', 'location_manager');
  END IF;

  RETURN false;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_my_accessible_brand_ids()
RETURNS SETOF uuid
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT b.brand_id
  FROM public.brands b
  WHERE public.is_platform_admin()
     OR (
       public.get_auth_role() = 'tenant_super_admin'
       AND b.organization_id IN (
         SELECT o.id FROM public.organizations o WHERE o.tenant_id = public.get_auth_tenant()
       )
     )
     OR (
       public.get_auth_role() = 'org_manager'
       AND b.organization_id = public.get_auth_org()
     )
     OR (
       public.get_auth_role() IN ('brand_manager', 'branch_manager')
       AND b.brand_id = (SELECT p.brand_id FROM public.profiles p WHERE p.id = auth.uid())
     );
$$;

CREATE OR REPLACE FUNCTION public.get_my_accessible_location_ids()
RETURNS SETOF uuid
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT l.id
  FROM public.locations l
  WHERE public.is_platform_admin()
     OR (
       public.get_auth_role() = 'tenant_super_admin'
       AND l.organization_id IN (
         SELECT o.id FROM public.organizations o WHERE o.tenant_id = public.get_auth_tenant()
       )
     )
     OR (
       public.get_auth_role() = 'org_manager'
       AND l.organization_id = public.get_auth_org()
     )
     OR (
       public.get_auth_role() IN ('brand_manager', 'branch_manager')
       AND l.brand_id = (SELECT p.brand_id FROM public.profiles p WHERE p.id = auth.uid())
     )
     OR (
       public.get_auth_role() = 'location_manager'
       AND l.id = (SELECT p.location_id FROM public.profiles p WHERE p.id = auth.uid())
     );
$$;

CREATE OR REPLACE FUNCTION public.access_membership_readable(
  p_target_user uuid,
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role text;
  v_org uuid;
  v_tenant uuid;
  v_brand uuid;
  v_location uuid;
  v_target_org uuid;
  v_target_tenant uuid;
  v_target_brand uuid;
  v_target_location uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  IF p_target_user = auth.uid() THEN
    RETURN true;
  END IF;

  SELECT p.role, p.organization_id, p.tenant_id, p.brand_id, p.location_id
    INTO v_role, v_org, v_tenant, v_brand, v_location
  FROM public.profiles p
  WHERE p.id = auth.uid()
    AND p.deleted_at IS NULL;

  v_role := public.normalize_app_role(v_role);

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;

  SELECT p.organization_id, p.tenant_id, p.brand_id, p.location_id
    INTO v_target_org, v_target_tenant, v_target_brand, v_target_location
  FROM public.profiles p
  WHERE p.id = p_target_user;

  v_target_org := COALESCE(v_target_org, p_organization_id);
  v_target_location := COALESCE(v_target_location, p_location_id);
  v_target_brand := COALESCE(v_target_brand, p_brand_id);

  IF v_target_tenant IS NULL AND v_target_org IS NOT NULL THEN
    SELECT tenant_id INTO v_target_tenant FROM public.organizations WHERE id = v_target_org;
  END IF;

  IF v_tenant IS NULL AND v_org IS NOT NULL THEN
    SELECT tenant_id INTO v_tenant FROM public.organizations WHERE id = v_org;
  END IF;

  IF v_target_brand IS NULL AND v_target_location IS NOT NULL THEN
    SELECT l.brand_id INTO v_target_brand FROM public.locations l WHERE l.id = v_target_location;
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    RETURN v_tenant IS NOT NULL AND v_target_tenant = v_tenant;
  END IF;

  IF v_org IS NULL OR v_target_org IS DISTINCT FROM v_org THEN
    RETURN false;
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN true;
  END IF;

  IF v_role IN ('brand_manager', 'branch_manager') THEN
    RETURN v_brand IS NOT NULL AND v_target_brand = v_brand;
  END IF;

  IF v_role = 'location_manager' THEN
    RETURN v_location IS NOT NULL AND v_target_location = v_location;
  END IF;

  RETURN false;
END;
$$;

CREATE OR REPLACE FUNCTION public.access_membership_writable(
  p_target_user uuid,
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_granted_role text DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role text;
  v_org uuid;
  v_tenant uuid;
  v_brand uuid;
  v_location uuid;
  v_target_org uuid;
  v_target_tenant uuid;
  v_target_brand uuid;
  v_target_location uuid;
  v_granted_role text;
  v_caller_rank integer;
  v_grant_rank integer;
BEGIN
  IF auth.uid() IS NULL OR p_target_user IS NULL OR p_target_user = auth.uid() THEN
    RETURN false;
  END IF;

  SELECT p.role, p.organization_id, p.tenant_id, p.brand_id, p.location_id
    INTO v_role, v_org, v_tenant, v_brand, v_location
  FROM public.profiles p
  WHERE p.id = auth.uid();

  v_role := public.normalize_app_role(v_role);

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  SELECT p.organization_id, p.tenant_id, p.brand_id, p.location_id
    INTO v_target_org, v_target_tenant, v_target_brand, v_target_location
  FROM public.profiles p
  WHERE p.id = p_target_user;

  v_target_org := COALESCE(v_target_org, p_organization_id);
  v_target_location := COALESCE(v_target_location, p_location_id);
  v_target_brand := COALESCE(v_target_brand, p_brand_id);

  IF v_target_tenant IS NULL AND v_target_org IS NOT NULL THEN
    SELECT tenant_id INTO v_target_tenant FROM public.organizations WHERE id = v_target_org;
  END IF;

  IF v_tenant IS NULL AND v_org IS NOT NULL THEN
    SELECT tenant_id INTO v_tenant FROM public.organizations WHERE id = v_org;
  END IF;

  IF v_target_brand IS NULL AND v_target_location IS NOT NULL THEN
    SELECT l.brand_id INTO v_target_brand FROM public.locations l WHERE l.id = v_target_location;
  END IF;

  v_granted_role := COALESCE(public.normalize_app_role(p_granted_role), 'ground_staff');
  v_caller_rank := public.access_role_rank(v_role);
  v_grant_rank := public.access_role_rank(v_granted_role);

  IF v_caller_rank = 0 OR v_grant_rank = 0 OR v_grant_rank >= v_caller_rank THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    RETURN v_tenant IS NOT NULL AND v_target_tenant = v_tenant;
  END IF;

  IF v_org IS NULL OR v_target_org IS DISTINCT FROM v_org THEN
    RETURN false;
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN v_granted_role IN ('ground_staff', 'location_manager', 'brand_manager', 'branch_manager');
  END IF;

  IF v_role IN ('brand_manager', 'branch_manager') THEN
    RETURN v_grant_rank <= public.access_role_rank('location_manager')
       AND v_brand IS NOT NULL
       AND v_target_brand = v_brand;
  END IF;

  IF v_role = 'location_manager' THEN
    RETURN v_granted_role = 'ground_staff'
       AND v_location IS NOT NULL
       AND v_target_location = v_location;
  END IF;

  RETURN false;
END;
$$;

CREATE OR REPLACE FUNCTION public.setup_organization_full(
  p_user_id uuid,
  p_org_name text,
  p_org_slug text,
  p_brand_name text,
  p_location_name text,
  p_location_address text DEFAULT ''
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_tenant_id uuid;
  v_org_id uuid;
  v_brand_id uuid;
  v_location_id uuid;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  INSERT INTO public.tenants (name, slug, owner_id, metadata)
  VALUES (
    p_org_name,
    left('tenant_' || regexp_replace(lower(p_org_slug), '[^a-z0-9]+', '_', 'g'), 63),
    p_user_id,
    jsonb_build_object('source', 'setup_organization_full')
  )
  ON CONFLICT (slug) DO UPDATE SET owner_id = EXCLUDED.owner_id
  RETURNING id INTO v_tenant_id;

  INSERT INTO public.organizations (tenant_id, name, slug, owner_id)
  VALUES (v_tenant_id, p_org_name, p_org_slug, p_user_id)
  RETURNING id INTO v_org_id;

  INSERT INTO public.brands (organization_id, name)
  VALUES (v_org_id, p_brand_name)
  RETURNING brand_id INTO v_brand_id;

  INSERT INTO public.locations (organization_id, brand_id, name, address)
  VALUES (v_org_id, v_brand_id, p_location_name, p_location_address)
  RETURNING id INTO v_location_id;

  INSERT INTO public.tenant_members (tenant_id, user_id, role)
  VALUES (v_tenant_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  INSERT INTO public.organization_members (organization_id, user_id, role)
  VALUES (v_org_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  INSERT INTO public.brand_members (brand_id, user_id, role)
  VALUES (v_brand_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  INSERT INTO public.location_members (location_id, user_id, role)
  VALUES (v_location_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.profiles
  SET tenant_id = v_tenant_id,
      organization_id = v_org_id,
      brand_id = v_brand_id,
      location_id = v_location_id,
      role = 'tenant_super_admin',
      access_level = 'organization',
      updated_at = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'tenant_super_admin',
    'tenant_id', v_tenant_id::text,
    'organization_id', v_org_id::text,
    'brand_id', v_brand_id::text,
    'location_id', v_location_id::text
  )
  WHERE id = p_user_id;

  RETURN jsonb_build_object(
    'tenant_id', v_tenant_id,
    'org_id', v_org_id,
    'brand_id', v_brand_id,
    'location_id', v_location_id
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.setup_onboarding_hierarchy(
  p_user_id uuid,
  p_hierarchy jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  org_item jsonb;
  brand_item jsonb;
  location_item jsonb;
  v_tenant_id uuid;
  v_org_id uuid;
  v_brand_id uuid;
  v_location_id uuid;
  v_primary_org_id uuid;
  v_primary_brand_id uuid;
  v_primary_location_id uuid;
  v_created_orgs jsonb := '[]'::jsonb;
  v_created_brands jsonb := '[]'::jsonb;
  v_created_locations jsonb := '[]'::jsonb;
  v_org_name text;
  v_org_slug text;
  v_brand_name text;
  v_location_name text;
  v_location_address text;
  v_org_count integer := 0;
  v_brand_count integer := 0;
  v_location_count integer := 0;
  v_business_status text;
  v_payment_verified boolean;
  v_run_id uuid;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  SELECT business_verification_status, payment_verified
  INTO v_business_status, v_payment_verified
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' THEN
    RAISE EXCEPTION 'Onboarding hierarchy must be an array';
  END IF;

  IF jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  v_org_name := NULLIF(btrim((p_hierarchy->0)->>'name'), '');
  v_org_slug := NULLIF(btrim((p_hierarchy->0)->>'slug'), '');

  INSERT INTO public.tenants (name, slug, owner_id, metadata)
  VALUES (
    COALESCE(v_org_name, 'Tenant'),
    left('tenant_' || regexp_replace(lower(COALESCE(v_org_slug, gen_random_uuid()::text)), '[^a-z0-9]+', '_', 'g'), 63),
    p_user_id,
    jsonb_build_object('source', 'setup_onboarding_hierarchy')
  )
  ON CONFLICT (slug) DO UPDATE SET owner_id = EXCLUDED.owner_id
  RETURNING id INTO v_tenant_id;

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
  EXCEPTION WHEN undefined_function THEN
    v_run_id := NULL;
  END;

  FOR org_item IN SELECT value FROM jsonb_array_elements(p_hierarchy)
  LOOP
    v_org_name := NULLIF(btrim(org_item->>'name'), '');
    v_org_slug := NULLIF(btrim(org_item->>'slug'), '');

    IF v_org_name IS NULL OR v_org_slug IS NULL THEN
      RAISE EXCEPTION 'Each organization requires a name and slug';
    END IF;

    IF COALESCE(jsonb_typeof(org_item->'brands'), 'null') <> 'array'
       OR jsonb_array_length(org_item->'brands') = 0 THEN
      RAISE EXCEPTION 'Organization % requires at least one brand', v_org_name;
    END IF;

    INSERT INTO public.organizations (tenant_id, name, slug, owner_id)
    VALUES (v_tenant_id, v_org_name, v_org_slug, p_user_id)
    RETURNING id INTO v_org_id;

    v_org_count := v_org_count + 1;
    v_created_orgs := v_created_orgs || jsonb_build_array(jsonb_build_object('id', v_org_id, 'name', v_org_name, 'slug', v_org_slug));

    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_org_id, p_user_id, 'tenant_super_admin')
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    IF v_primary_org_id IS NULL THEN
      v_primary_org_id := v_org_id;
    END IF;

    FOR brand_item IN SELECT value FROM jsonb_array_elements(org_item->'brands')
    LOOP
      v_brand_name := NULLIF(btrim(brand_item->>'name'), '');

      IF v_brand_name IS NULL THEN
        RAISE EXCEPTION 'Every brand in organization % requires a name', v_org_name;
      END IF;

      IF COALESCE(jsonb_typeof(brand_item->'locations'), 'null') <> 'array'
         OR jsonb_array_length(brand_item->'locations') = 0 THEN
        RAISE EXCEPTION 'Brand % requires at least one location', v_brand_name;
      END IF;

      INSERT INTO public.brands (organization_id, name)
      VALUES (v_org_id, v_brand_name)
      RETURNING brand_id INTO v_brand_id;

      v_brand_count := v_brand_count + 1;
      v_created_brands := v_created_brands || jsonb_build_array(jsonb_build_object('id', v_brand_id, 'organization_id', v_org_id, 'name', v_brand_name));

      INSERT INTO public.brand_members (brand_id, user_id, role)
      VALUES (v_brand_id, p_user_id, 'tenant_super_admin')
      ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

      IF v_primary_brand_id IS NULL THEN
        v_primary_brand_id := v_brand_id;
      END IF;

      FOR location_item IN SELECT value FROM jsonb_array_elements(brand_item->'locations')
      LOOP
        v_location_name := NULLIF(btrim(location_item->>'name'), '');
        v_location_address := COALESCE(NULLIF(btrim(location_item->>'address'), ''), 'Address pending');

        IF v_location_name IS NULL THEN
          RAISE EXCEPTION 'Every location in brand % requires a name', v_brand_name;
        END IF;

        INSERT INTO public.locations (organization_id, brand_id, name, address)
        VALUES (v_org_id, v_brand_id, v_location_name, v_location_address)
        RETURNING id INTO v_location_id;

        v_location_count := v_location_count + 1;
        v_created_locations := v_created_locations || jsonb_build_array(jsonb_build_object(
          'id', v_location_id,
          'organization_id', v_org_id,
          'brand_id', v_brand_id,
          'name', v_location_name,
          'address', v_location_address
        ));

        INSERT INTO public.location_members (location_id, user_id, role)
        VALUES (v_location_id, p_user_id, 'tenant_super_admin')
        ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

        IF v_primary_location_id IS NULL THEN
          v_primary_location_id := v_location_id;
        END IF;
      END LOOP;
    END LOOP;

    INSERT INTO public.onboarding_progress (organization_id, current_step, completed_steps, is_completed)
    VALUES (v_org_id, 'hierarchy_created', ARRAY['organizations', 'brands', 'locations'], false)
    ON CONFLICT DO NOTHING;
  END LOOP;

  INSERT INTO public.tenant_members (tenant_id, user_id, role)
  VALUES (v_tenant_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.profiles
  SET tenant_id = v_tenant_id,
      organization_id = v_primary_org_id,
      brand_id = v_primary_brand_id,
      location_id = v_primary_location_id,
      role = 'tenant_super_admin',
      access_level = 'organization',
      onboarding_status = 'completed',
      onboarding_current_step = 'completed',
      onboarding_completed_at = now(),
      updated_at = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'tenant_super_admin',
    'tenant_id', v_tenant_id::text,
    'organization_id', v_primary_org_id::text,
    'brand_id', v_primary_brand_id::text,
    'location_id', v_primary_location_id::text
  )
  WHERE id = p_user_id;

  UPDATE public.business_verifications SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.organization_addresses SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_payment_methods SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_coupon_redemptions SET organization_id = v_primary_org_id
  WHERE user_id = p_user_id AND organization_id IS NULL;

  IF v_run_id IS NOT NULL THEN
    UPDATE public.onboarding_workflow_runs
    SET organization_id = v_primary_org_id,
        status = 'completed',
        current_step = 'completed',
        completed_at = now(),
        last_activity_at = now()
    WHERE id = v_run_id;

    PERFORM public.record_onboarding_event(
      v_run_id,
      p_user_id,
      'hierarchy_setup',
      'completed',
      'completed',
      jsonb_build_object('tenant_id', v_tenant_id, 'primary_org_id', v_primary_org_id)
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'tenant_id', v_tenant_id,
    'primary_org_id', v_primary_org_id,
    'primary_brand_id', v_primary_brand_id,
    'primary_location_id', v_primary_location_id,
    'organizations', v_created_orgs,
    'brands', v_created_brands,
    'locations', v_created_locations,
    'counts', jsonb_build_object('organizations', v_org_count, 'brands', v_brand_count, 'locations', v_location_count)
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.accept_invitation(p_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invite record;
  v_user_id uuid;
  v_user_email text;
  v_role text;
  v_tenant_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND closed_at IS NULL
    AND lower(email) = lower(v_user_email)
    AND (expires_at IS NULL OR expires_at > now());

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  v_role := public.normalize_app_role(v_invite.role);
  v_tenant_id := v_invite.tenant_id;

  IF v_tenant_id IS NULL AND v_invite.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO v_tenant_id FROM public.organizations WHERE id = v_invite.organization_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NULL THEN
    INSERT INTO public.tenants (name, owner_id, metadata)
    VALUES (COALESCE(split_part(v_user_email, '@', 1), 'Tenant'), v_user_id, jsonb_build_object('source', 'accept_invitation'))
    RETURNING id INTO v_tenant_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NOT NULL THEN
    INSERT INTO public.tenant_members (tenant_id, user_id, role)
    VALUES (v_tenant_id, v_user_id, 'tenant_super_admin')
    ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.organization_id IS NOT NULL THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_invite.organization_id, v_user_id, v_role)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.brand_id IS NOT NULL THEN
    INSERT INTO public.brand_members (brand_id, user_id, role)
    VALUES (v_invite.brand_id, v_user_id, v_role)
    ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.location_id IS NOT NULL THEN
    INSERT INTO public.location_members (location_id, user_id, role)
    VALUES (v_invite.location_id, v_user_id, v_role)
    ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  UPDATE public.profiles
  SET tenant_id = COALESCE(v_tenant_id, tenant_id),
      role = v_role,
      organization_id = COALESCE(v_invite.organization_id, organization_id),
      brand_id = COALESCE(v_invite.brand_id, brand_id),
      location_id = COALESCE(v_invite.location_id, location_id),
      updated_at = now()
  WHERE id = v_user_id;

  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id,
      role = v_role,
      tenant_id = COALESCE(tenant_id, v_tenant_id)
  WHERE id = v_invite.id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', v_role,
    'tenant_id', COALESCE(v_tenant_id::text, ''),
    'organization_id', COALESCE(v_invite.organization_id::text, '')
  )
  WHERE id = v_user_id;

  RETURN jsonb_build_object('success', true, 'role', v_role, 'tenant_id', v_tenant_id, 'organization_id', v_invite.organization_id);
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_update_user_role(
  target_user_id uuid,
  new_role text DEFAULT NULL,
  new_status text DEFAULT NULL,
  new_department text DEFAULT NULL,
  new_location text DEFAULT NULL,
  new_brand_id uuid DEFAULT NULL,
  new_location_id uuid DEFAULT NULL,
  new_access_level text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  caller_role text;
  caller_org uuid;
  caller_tenant uuid;
  target_org uuid;
  target_tenant uuid;
  normalized_role text;
BEGIN
  IF new_location IS NOT NULL THEN
    -- Backward-compatible no-op.
  END IF;

  caller_role := public.get_auth_role();
  caller_org := public.get_auth_org();
  caller_tenant := public.get_auth_tenant();
  normalized_role := CASE WHEN new_role IS NULL THEN NULL ELSE public.normalize_app_role(new_role) END;

  IF caller_role NOT IN ('org_manager', 'tenant_super_admin', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: org_manager, tenant_super_admin, or platform_admin required';
  END IF;

  SELECT p.organization_id, COALESCE(p.tenant_id, o.tenant_id)
  INTO target_org, target_tenant
  FROM public.profiles p
  LEFT JOIN public.organizations o ON o.id = p.organization_id
  WHERE p.id = target_user_id;

  IF caller_role = 'tenant_super_admin' AND target_tenant IS DISTINCT FROM caller_tenant THEN
    RAISE EXCEPTION 'Cannot modify users outside your tenant';
  END IF;

  IF caller_role = 'org_manager' AND target_org IS DISTINCT FROM caller_org THEN
    RAISE EXCEPTION 'Cannot modify users outside your organization';
  END IF;

  IF caller_role != 'platform_admin' AND normalized_role IS NOT NULL THEN
    IF NOT public.can_invite_role(normalized_role) THEN
      RAISE EXCEPTION 'Cannot assign a role equal to or above your own';
    END IF;
  END IF;

  IF target_user_id = auth.uid() AND normalized_role IS NOT NULL AND normalized_role <> caller_role THEN
    RAISE EXCEPTION 'Cannot change your own role';
  END IF;

  IF normalized_role = 'tenant_super_admin' AND target_tenant IS NOT NULL THEN
    INSERT INTO public.tenant_members (tenant_id, user_id, role)
    VALUES (target_tenant, target_user_id, 'tenant_super_admin')
    ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF normalized_role IS NOT NULL AND target_org IS NOT NULL THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (target_org, target_user_id, normalized_role)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  UPDATE public.profiles
  SET role = COALESCE(normalized_role, role),
      status = COALESCE(new_status, status),
      department = COALESCE(new_department, department),
      brand_id = COALESCE(new_brand_id, brand_id),
      location_id = COALESCE(new_location_id, location_id),
      access_level = COALESCE(new_access_level, access_level),
      tenant_id = COALESCE(tenant_id, target_tenant),
      updated_at = now()
  WHERE id = target_user_id;

  IF (SELECT raw_app_meta_data->>'organization_id' FROM auth.users WHERE id = target_user_id) = target_org::text THEN
    UPDATE auth.users
    SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
      'role', COALESCE(normalized_role, (SELECT role FROM public.profiles WHERE id = target_user_id)),
      'tenant_id', COALESCE(target_tenant::text, '')
    )
    WHERE id = target_user_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

CREATE OR REPLACE FUNCTION public.switch_user_context(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id uuid;
  v_role text;
  v_tenant_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT tenant_id INTO v_tenant_id FROM public.organizations WHERE id = p_organization_id;

  SELECT role INTO v_role
  FROM public.organization_members
  WHERE organization_id = p_organization_id
    AND user_id = v_user_id;

  IF v_role IS NULL AND public.get_auth_role() = 'tenant_super_admin' AND v_tenant_id = public.get_auth_tenant() THEN
    v_role := 'tenant_super_admin';
  END IF;

  IF v_role IS NULL AND NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'User is not a member of this organization';
  END IF;

  IF v_role IS NULL THEN
    v_role := 'platform_admin';
  END IF;

  v_role := public.normalize_app_role(v_role);

  IF p_brand_id IS NOT NULL
     AND NOT (p_brand_id = ANY (ARRAY(SELECT public.get_my_accessible_brand_ids()))) THEN
    RAISE EXCEPTION 'Brand % not in your accessible scope', p_brand_id;
  END IF;

  IF p_location_id IS NOT NULL
     AND NOT (p_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))) THEN
    RAISE EXCEPTION 'Location % not in your accessible scope', p_location_id;
  END IF;

  UPDATE public.profiles
  SET tenant_id = COALESCE(v_tenant_id, tenant_id),
      organization_id = p_organization_id,
      brand_id = p_brand_id,
      location_id = p_location_id,
      role = v_role,
      updated_at = now()
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'role', v_role,
    'tenant_id', v_tenant_id,
    'organization_id', p_organization_id,
    'brand_id', p_brand_id,
    'location_id', p_location_id
  );
END;
$$;

ALTER TABLE public.tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tenant_members ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS tenants_select_scope ON public.tenants;
CREATE POLICY tenants_select_scope ON public.tenants
FOR SELECT USING (
  public.is_platform_admin()
  OR id = public.get_auth_tenant()
);

DROP POLICY IF EXISTS tenants_write_scope ON public.tenants;
CREATE POLICY tenants_write_scope ON public.tenants
FOR ALL USING (
  public.is_platform_admin()
  OR (public.is_tenant_super_admin() AND id = public.get_auth_tenant())
)
WITH CHECK (
  public.is_platform_admin()
  OR (public.is_tenant_super_admin() AND id = public.get_auth_tenant())
);

DROP POLICY IF EXISTS tenant_members_select_scope ON public.tenant_members;
CREATE POLICY tenant_members_select_scope ON public.tenant_members
FOR SELECT USING (
  public.is_platform_admin()
  OR tenant_id = public.get_auth_tenant()
  OR user_id = auth.uid()
);

DROP POLICY IF EXISTS tenant_members_write_scope ON public.tenant_members;
CREATE POLICY tenant_members_write_scope ON public.tenant_members
FOR ALL USING (
  public.is_platform_admin()
  OR (public.is_tenant_super_admin() AND tenant_id = public.get_auth_tenant() AND user_id <> auth.uid())
)
WITH CHECK (
  public.is_platform_admin()
  OR (public.is_tenant_super_admin() AND tenant_id = public.get_auth_tenant() AND user_id <> auth.uid())
);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.tenants, public.tenant_members TO authenticated;
GRANT ALL ON public.tenants, public.tenant_members TO service_role;

GRANT EXECUTE ON FUNCTION public.normalize_app_role(text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_auth_role() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_auth_tenant() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_tenant_super_admin() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_platform_admin() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_manager_or_above() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_admin() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_owner_or_admin() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.access_role_rank(text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.can_invite_role(text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.setup_organization_full(uuid, text, text, text, text, text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.setup_onboarding_hierarchy(uuid, jsonb) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.accept_invitation(text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_update_user_role(uuid, text, text, text, text, uuid, uuid, text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.switch_user_context(uuid, uuid, uuid) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260709000001_fix_tenant_id_in_archived_tables_and_rpcs.sql
-- ==========================================================================

-- Fix missing tenant_id columns in archive tables
-- Updates reissue_owner_invitation to maintain tenant association

BEGIN;

-- 1. Add tenant_id to archive tables to prevent data loss on deletion
ALTER TABLE public.archived_organizations ADD COLUMN IF NOT EXISTS tenant_id uuid;
ALTER TABLE public.archived_profiles ADD COLUMN IF NOT EXISTS tenant_id uuid;
ALTER TABLE public.archived_invitations ADD COLUMN IF NOT EXISTS tenant_id uuid;

-- 2. Update reissue_owner_invitation to explicitly copy the tenant_id 
CREATE OR REPLACE FUNCTION public.reissue_owner_invitation(p_invitation_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_old public.invitations%ROWTYPE;
  v_new public.invitations%ROWTYPE;
  v_token TEXT := encode(gen_random_bytes(32), 'hex');
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  SELECT * INTO v_old FROM public.invitations WHERE id = p_invitation_id;
  IF v_old.id IS NULL THEN
    RAISE EXCEPTION 'Invitation not found';
  END IF;

  UPDATE public.invitations SET closed_at = now() WHERE id = p_invitation_id;

  INSERT INTO public.invitations (
    tenant_id, organization_id, email, role, token, invited_by, expires_at, metadata, status
  )
  VALUES (
    v_old.tenant_id,
    v_old.organization_id,
    v_old.email,
    v_old.role,
    v_token,
    auth.uid(),
    now() + interval '7 days',
    COALESCE(v_old.metadata, '{}'::jsonb) || jsonb_build_object('reissued_from', v_old.id),
    COALESCE(v_old.status, 'pending')
  )
  RETURNING * INTO v_new;

  RETURN jsonb_build_object('success', true, 'invitation_id', v_new.id, 'token', v_new.token, 'expires_at', v_new.expires_at);
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260709000002_fix_legacy_roles_in_access_functions.sql
-- ==========================================================================

-- Fix Legacy Roles in Access Functions
-- 
-- Replaces instances of 'org_owner' with 'org_manager' (and adds 'tenant_super_admin' where applicable)
-- to restore RLS visibility after the role normalization migration.

BEGIN;

CREATE OR REPLACE FUNCTION public.tenant_scope_visible(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_deleted_at timestamptz DEFAULT NULL
) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_role text;
  v_org_id uuid;
BEGIN
  IF p_deleted_at IS NOT NULL THEN
    RETURN false;
  END IF;

  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT role, organization_id
    INTO v_role, v_org_id
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;
  
  IF v_role = 'tenant_super_admin' THEN
    IF p_organization_id IS NULL THEN
       RETURN false;
    END IF;
    RETURN public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id);
  END IF;

  IF p_organization_id IS NULL OR v_org_id IS DISTINCT FROM p_organization_id THEN
    RETURN false;
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN true;
  END IF;

  IF p_brand_id IS NULL AND p_location_id IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'branch_manager' THEN
    RETURN (
      p_brand_id IN (SELECT id FROM public.get_my_accessible_brand_ids() id)
      OR p_location_id IN (SELECT id FROM public.get_my_accessible_location_ids() id)
    );
  END IF;

  IF v_role = 'location_manager' THEN
    RETURN p_location_id IN (SELECT id FROM public.get_my_accessible_location_ids() id);
  END IF;

  IF v_role = 'ground_staff' THEN
    RETURN EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.id = auth.uid()
        AND p.organization_id = p_organization_id
        AND p.location_id = p_location_id
        AND (
          p_brand_id IS NULL
          OR p.brand_id IS NULL
          OR p.brand_id = p_brand_id
        )
        AND p.deleted_at IS NULL
    );
  END IF;

  RETURN false;
END;
$$;


CREATE OR REPLACE FUNCTION public.reference_scope_visible(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_deleted_at timestamptz DEFAULT NULL
) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_role text;
  v_org_id uuid;
BEGIN
  IF p_deleted_at IS NOT NULL THEN
    RETURN false;
  END IF;

  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT role, organization_id
    INTO v_role, v_org_id
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;
  
  IF v_role = 'tenant_super_admin' THEN
    IF p_organization_id IS NULL THEN
       RETURN false;
    END IF;
    RETURN public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id);
  END IF;

  IF p_organization_id IS NULL OR v_org_id IS DISTINCT FROM p_organization_id THEN
    RETURN false;
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN true;
  END IF;

  IF p_location_id IS NOT NULL THEN
    RETURN p_location_id IN (SELECT id FROM public.get_my_accessible_location_ids() id);
  END IF;

  IF p_brand_id IS NOT NULL THEN
    RETURN p_brand_id IN (SELECT id FROM public.get_my_accessible_brand_ids() id);
  END IF;

  RETURN false;
END;
$$;


CREATE OR REPLACE FUNCTION public.reference_scope_writable(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_deleted_at timestamptz DEFAULT NULL,
  p_role_required text DEFAULT 'ground_staff'
) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_role text;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  IF p_deleted_at IS NOT NULL THEN
    RETURN false;
  END IF;

  v_role := public.get_auth_role();

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;
  
  IF v_role = 'tenant_super_admin' THEN
    RETURN public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id);
  END IF;

  IF p_organization_id IS DISTINCT FROM public.get_auth_org() THEN
    RETURN false;
  END IF;

  IF p_location_id IS NOT NULL THEN
    IF v_role NOT IN ('location_manager', 'branch_manager', 'org_manager') THEN
      RETURN false;
    END IF;

    IF p_role_required = 'branch_manager' AND v_role = 'location_manager' THEN
      RETURN false;
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.locations l
      WHERE l.id = p_location_id
        AND l.organization_id = p_organization_id
        AND (p_brand_id IS NULL OR l.brand_id = p_brand_id)
    ) THEN
      RETURN false;
    END IF;

    RETURN p_location_id IN (SELECT id FROM public.get_my_accessible_location_ids() id);
  END IF;

  IF p_brand_id IS NOT NULL THEN
    IF v_role NOT IN ('branch_manager', 'org_manager') THEN
      RETURN false;
    END IF;

    RETURN p_brand_id IN (SELECT id FROM public.get_my_accessible_brand_ids() id);
  END IF;

  RETURN false;
END;
$$;


CREATE OR REPLACE FUNCTION public.tenant_scope_writable(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_deleted_at timestamptz DEFAULT NULL,
  p_allow_ground_staff boolean DEFAULT true
) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_role text;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  v_role := public.get_auth_role();

  IF v_role = 'ground_staff' AND NOT p_allow_ground_staff THEN
    RETURN false;
  END IF;

  IF v_role NOT IN ('ground_staff', 'location_manager', 'branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin') THEN
    RETURN false;
  END IF;

  RETURN public.tenant_scope_visible(
    p_organization_id,
    p_brand_id,
    p_location_id,
    p_deleted_at
  );
END;
$$;


CREATE OR REPLACE FUNCTION public.transfer_scope_visible(
  p_organization_id uuid,
  p_from_location_id uuid,
  p_to_location_id uuid,
  p_deleted_at timestamptz DEFAULT NULL
) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT
    p_deleted_at IS NULL
    AND (
      public.is_platform_admin()
      OR (
        public.get_auth_role() = 'tenant_super_admin'
        AND public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id)
      )
      OR (
        p_organization_id = public.get_auth_org()
        AND (
          public.get_auth_role() = 'org_manager'
          OR p_from_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
          OR p_to_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
        )
      )
    );
$$;


CREATE OR REPLACE FUNCTION public.transfer_from_scope_writable(
  p_organization_id uuid,
  p_from_location_id uuid,
  p_deleted_at timestamptz DEFAULT NULL
) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT
    p_deleted_at IS NULL
    AND public.is_manager_or_above()
    AND (
      public.is_platform_admin()
      OR (
        public.get_auth_role() = 'tenant_super_admin'
        AND public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id)
      )
      OR (
        p_organization_id = public.get_auth_org()
        AND (
          public.get_auth_role() = 'org_manager'
          OR p_from_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
        )
      )
    );
$$;


CREATE OR REPLACE FUNCTION public.intercompany_from_scope_writable(
  p_organization_id uuid,
  p_from_location_id uuid,
  p_deleted_at timestamptz DEFAULT NULL
) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT
    p_deleted_at IS NULL
    AND public.get_auth_role() IN ('branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin')
    AND (
      public.is_platform_admin()
      OR (
        public.get_auth_role() = 'tenant_super_admin'
        AND public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id)
      )
      OR (
        p_organization_id = public.get_auth_org()
        AND (
          public.get_auth_role() = 'org_manager'
          OR p_from_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
        )
      )
    );
$$;


CREATE OR REPLACE FUNCTION public.commissary_route_scope_visible(
  p_organization_id uuid,
  p_route_id uuid,
  p_origin_location_id uuid,
  p_deleted_at timestamptz DEFAULT NULL
) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT
    p_deleted_at IS NULL
    AND (
      public.is_platform_admin()
      OR (
        public.get_auth_role() = 'tenant_super_admin'
        AND public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id)
      )
      OR (
        p_organization_id = public.get_auth_org()
        AND (
          public.get_auth_role() = 'org_manager'
          OR p_origin_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
          OR EXISTS (
            SELECT 1
            FROM public.commissary_route_stops crs
            WHERE crs.route_id = p_route_id
              AND crs.destination_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
          )
        )
