-- Create the vendor tax details table for encrypted/secure storage
CREATE TABLE IF NOT EXISTS public.vendor_tax_details (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    vendor_id UUID NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
    encrypted_tax_id TEXT,
    w9_document_path TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- Add onboarding-specific columns to vendors
ALTER TABLE public.vendors 
  ADD COLUMN IF NOT EXISTS onboarding_status TEXT DEFAULT 'completed',
  ADD COLUMN IF NOT EXISTS otp_hash TEXT,
  ADD COLUMN IF NOT EXISTS otp_expires_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS tax_magic_link_token TEXT,
  ADD COLUMN IF NOT EXISTS tax_magic_link_expires_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS bank_magic_link_token TEXT,
  ADD COLUMN IF NOT EXISTS bank_magic_link_expires_at TIMESTAMPTZ;

-- Ensure RLS is enabled for the new table
ALTER TABLE public.vendor_tax_details ENABLE ROW LEVEL SECURITY;

-- Tenant isolation policy for vendor_tax_details
CREATE POLICY "Tenant isolation for vendor_tax_details"
    ON public.vendor_tax_details
    FOR ALL
    USING (
        vendor_id IN (
            SELECT id FROM public.vendors 
            WHERE organization_id = (current_setting('app.current_tenant_id', true))::uuid
        )
    );

-- Also allow service role full access
CREATE POLICY "Service role full access for vendor_tax_details"
    ON public.vendor_tax_details
    FOR ALL
    USING (auth.jwt()->>'role' = 'service_role');

-- ==========================================================================
-- Source: 20260710000018_optional_org_address_required_location_address.sql
-- ==========================================================================

-- Align hierarchy onboarding with organization/location address capture.
-- Business identity remains identity-only; addresses are captured with the hierarchy.

CREATE OR REPLACE FUNCTION public.setup_onboarding_hierarchy(
  p_user_id uuid,
  p_hierarchy jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  org_item jsonb;
  brand_item jsonb;
  location_item jsonb;
  v_tenant_id uuid;
  v_org_id uuid;
  v_brand_id uuid;
  v_location_id uuid;
  v_primary_org_id uuid;
  v_primary_brand_id uuid;
  v_primary_location_id uuid;
  v_created_orgs jsonb := '[]'::jsonb;
  v_created_brands jsonb := '[]'::jsonb;
  v_created_locations jsonb := '[]'::jsonb;
  v_org_name text;
  v_org_slug text;
  v_brand_name text;
  v_location_name text;
  v_location_address text;
  v_org_count integer := 0;
  v_brand_count integer := 0;
  v_location_count integer := 0;
  v_business_status text;
  v_payment_verified boolean;
  v_pending_plan_id text;
  v_pending_stripe_customer_id text;
  v_pending_stripe_subscription_id text;
  v_pending_checkout_session_id text;
  v_pending_payment_metadata jsonb;
  v_run_id uuid;
  v_org_address jsonb;
  v_brand_address jsonb;
  v_business_address jsonb;
  v_mailing_address jsonb;
  v_tenant_identity jsonb;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  SELECT business_verification_status, payment_verified, pending_onboarding_plan_id, pending_stripe_customer_id, pending_stripe_subscription_id, pending_checkout_session_id, pending_payment_metadata
  INTO v_business_status, v_payment_verified, v_pending_plan_id, v_pending_stripe_customer_id, v_pending_stripe_subscription_id, v_pending_checkout_session_id, v_pending_payment_metadata
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' THEN
    RAISE EXCEPTION 'Onboarding hierarchy must be an array';
  END IF;

  IF jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  v_org_name := NULLIF(btrim((p_hierarchy->0)->>'name'), '');
  v_org_slug := NULLIF(btrim((p_hierarchy->0)->>'slug'), '');

  INSERT INTO public.tenants (name, slug, owner_id, metadata)
  VALUES (
    COALESCE(v_org_name, 'Tenant'),
    left('tenant_' || regexp_replace(lower(COALESCE(v_org_slug, gen_random_uuid()::text)), '[^a-z0-9]+', '_', 'g'), 63),
    p_user_id,
    jsonb_build_object(
      'source', 'setup_onboarding_hierarchy',
      'business_identity', (p_hierarchy->0)#>'{metadata,tenant_business_identity}'
    )
  )
  ON CONFLICT (slug) DO UPDATE
    SET owner_id = EXCLUDED.owner_id,
        metadata = COALESCE(public.tenants.metadata, '{}'::jsonb) || EXCLUDED.metadata
  RETURNING id INTO v_tenant_id;

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
  EXCEPTION WHEN undefined_function THEN
    v_run_id := NULL;
  END;

  FOR org_item IN SELECT value FROM jsonb_array_elements(p_hierarchy)
  LOOP
    v_org_name := NULLIF(btrim(org_item->>'name'), '');
    v_org_slug := NULLIF(btrim(org_item->>'slug'), '');
    v_org_address := COALESCE(org_item#>'{metadata,organization_business_address}', org_item#>'{metadata,organization_address}');
    v_mailing_address := CASE
      WHEN COALESCE((org_item#>>'{metadata,organization_mailing_same_as_business}')::boolean, true) THEN v_org_address
      ELSE org_item#>'{metadata,organization_mailing_address}'
    END;

    IF v_org_name IS NULL OR v_org_slug IS NULL THEN
      RAISE EXCEPTION 'Each organization requires a name and slug';
    END IF;

    IF COALESCE(jsonb_typeof(org_item->'brands'), 'null') <> 'array'
       OR jsonb_array_length(org_item->'brands') = 0 THEN
      RAISE EXCEPTION 'Organization % requires at least one brand', v_org_name;
    END IF;

    INSERT INTO public.organizations (tenant_id, name, slug, owner_id)
    VALUES (v_tenant_id, v_org_name, v_org_slug, p_user_id)
    RETURNING id INTO v_org_id;

    IF v_org_address IS NOT NULL AND COALESCE(jsonb_typeof(v_org_address), 'null') <> 'object' THEN
      RAISE EXCEPTION 'Organization % business/service address must be an object when provided', v_org_name;
    END IF;

    IF v_org_address IS NOT NULL THEN
      IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
        RAISE EXCEPTION 'Organization % mailing address must be an object when organization address is provided', v_org_name;
      END IF;

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'service', v_org_name, v_org_address
      );

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'mailing', v_org_name, v_mailing_address
      );
    END IF;

    v_org_count := v_org_count + 1;
    v_created_orgs := v_created_orgs || jsonb_build_array(jsonb_build_object('id', v_org_id, 'name', v_org_name, 'slug', v_org_slug));

    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_org_id, p_user_id, 'tenant_super_admin')
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    IF v_primary_org_id IS NULL THEN
      v_primary_org_id := v_org_id;
    END IF;

    FOR brand_item IN SELECT value FROM jsonb_array_elements(org_item->'brands')
    LOOP
      v_brand_name := NULLIF(btrim(brand_item->>'name'), '');
      v_brand_address := brand_item#>'{metadata,brand_address}';

      IF v_brand_name IS NULL THEN
        RAISE EXCEPTION 'Every brand in organization % requires a name', v_org_name;
      END IF;

      IF COALESCE(jsonb_typeof(brand_item->'locations'), 'null') <> 'array'
         OR jsonb_array_length(brand_item->'locations') = 0 THEN
        RAISE EXCEPTION 'Brand % requires at least one location', v_brand_name;
      END IF;

      INSERT INTO public.brands (organization_id, name)
      VALUES (v_org_id, v_brand_name)
      RETURNING brand_id INTO v_brand_id;

      IF v_brand_address IS NOT NULL AND COALESCE(jsonb_typeof(v_brand_address), 'null') = 'object' THEN
        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, NULL, 'service', v_brand_name, v_brand_address
        );
      END IF;

      v_brand_count := v_brand_count + 1;
      v_created_brands := v_created_brands || jsonb_build_array(jsonb_build_object('id', v_brand_id, 'organization_id', v_org_id, 'name', v_brand_name));

      INSERT INTO public.brand_members (brand_id, user_id, role)
      VALUES (v_brand_id, p_user_id, 'tenant_super_admin')
      ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

      IF v_primary_brand_id IS NULL THEN
        v_primary_brand_id := v_brand_id;
      END IF;

      FOR location_item IN SELECT value FROM jsonb_array_elements(brand_item->'locations')
      LOOP
        v_location_name := NULLIF(btrim(location_item->>'name'), '');
        v_location_address := COALESCE(NULLIF(btrim(location_item->>'address'), ''), 'Address pending');
        v_business_address := location_item->'business_address';
        v_mailing_address := location_item->'mailing_address';

        IF v_location_name IS NULL THEN
          RAISE EXCEPTION 'Every location in brand % requires a name', v_brand_name;
        END IF;

        IF v_business_address IS NULL OR COALESCE(jsonb_typeof(v_business_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a business/service address', v_brand_name;
        END IF;

        INSERT INTO public.locations (organization_id, brand_id, name, address)
        VALUES (v_org_id, v_brand_id, v_location_name, v_location_address)
        RETURNING id INTO v_location_id;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'service', v_location_name, v_business_address
        );

        IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a mailing address', v_brand_name;
        END IF;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'mailing', v_location_name, v_mailing_address
        );

        v_location_count := v_location_count + 1;
        v_created_locations := v_created_locations || jsonb_build_array(jsonb_build_object(
          'id', v_location_id,
          'organization_id', v_org_id,
          'brand_id', v_brand_id,
          'name', v_location_name,
          'address', v_location_address
        ));

        INSERT INTO public.location_members (location_id, user_id, role)
        VALUES (v_location_id, p_user_id, 'tenant_super_admin')
        ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

        IF v_primary_location_id IS NULL THEN
          v_primary_location_id := v_location_id;
        END IF;
      END LOOP;
    END LOOP;

    INSERT INTO public.onboarding_progress (organization_id, current_step, completed_steps, is_completed)
    VALUES (v_org_id, 'hierarchy_created', ARRAY['organizations', 'brands', 'locations'], false)
    ON CONFLICT DO NOTHING;
  END LOOP;

  INSERT INTO public.tenant_members (tenant_id, user_id, role)
  VALUES (v_tenant_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.profiles
  SET tenant_id = v_tenant_id,
      organization_id = v_primary_org_id,
      brand_id = v_primary_brand_id,
      location_id = v_primary_location_id,
      role = 'tenant_super_admin',
      access_level = 'organization',
      onboarding_status = 'completed',
      onboarding_current_step = 'completed',
      onboarding_completed_at = now(),
      updated_at = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'tenant_super_admin',
    'tenant_id', v_tenant_id::text,
    'organization_id', v_primary_org_id::text,
    'brand_id', v_primary_brand_id::text,
    'location_id', v_primary_location_id::text
  )
  WHERE id = p_user_id;

  IF v_primary_org_id IS NOT NULL THEN
    UPDATE public.organizations
    SET plan_id = COALESCE(v_pending_plan_id, plan_id),
        stripe_customer_id = COALESCE(v_pending_stripe_customer_id, stripe_customer_id),
        stripe_subscription_id = COALESCE(v_pending_stripe_subscription_id, stripe_subscription_id)
    WHERE id = v_primary_org_id;
  END IF;

  UPDATE public.business_verifications SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.organization_addresses SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_payment_methods SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_coupon_redemptions SET organization_id = v_primary_org_id
  WHERE user_id = p_user_id AND organization_id IS NULL;

  v_tenant_identity := (p_hierarchy->0)#>'{metadata,tenant_business_identity}';
  IF v_tenant_identity IS NOT NULL AND COALESCE(jsonb_typeof(v_tenant_identity), 'null') = 'object' THEN
    v_business_address := v_tenant_identity->'businessAddress';
    v_mailing_address := CASE
      WHEN COALESCE((v_tenant_identity->>'mailingSameAsBusiness')::boolean, true) THEN v_business_address
      ELSE v_tenant_identity->'mailingAddress'
    END;

    IF v_business_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'business'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'business', 'Tenant business identity', v_business_address
      );
    END IF;

    IF v_mailing_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'mailing'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'mailing', 'Tenant business identity', v_mailing_address
      );
    END IF;
  END IF;

  IF v_run_id IS NOT NULL THEN
    UPDATE public.onboarding_workflow_runs
    SET organization_id = v_primary_org_id,
        status = 'completed',
        current_step = 'completed',
        completed_at = now(),
        last_activity_at = now()
    WHERE id = v_run_id;

    PERFORM public.record_onboarding_event(
      v_run_id,
      p_user_id,
      'hierarchy_setup',
      'completed',
      'completed',
      jsonb_build_object('tenant_id', v_tenant_id, 'primary_org_id', v_primary_org_id, 'plan_id', v_pending_plan_id, 'checkout_session_id', v_pending_checkout_session_id)
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'tenant_id', v_tenant_id,
    'primary_org_id', v_primary_org_id,
    'primary_brand_id', v_primary_brand_id,
    'primary_location_id', v_primary_location_id,
    'organizations', v_created_orgs,
    'brands', v_created_brands,
    'locations', v_created_locations,
    'counts', jsonb_build_object('organizations', v_org_count, 'brands', v_brand_count, 'locations', v_location_count),
    'plan_id', v_pending_plan_id,
    'stripe_customer_id', v_pending_stripe_customer_id,
    'stripe_subscription_id', v_pending_stripe_subscription_id
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.setup_onboarding_hierarchy(uuid, jsonb) TO authenticated;

NOTIFY pgrst, 'reload schema';

-- ==========================================================================
-- Source: 20260710000019_ensure_legacy_vendor_columns.sql
-- ==========================================================================

-- Ensure legacy columns exist so that triggers and legacy queries do not fail
-- The trigger neutralize_vendor_bank_details requires bank_details to exist on the NEW record.
ALTER TABLE public.vendors 
  ADD COLUMN IF NOT EXISTS contact_name TEXT,
  ADD COLUMN IF NOT EXISTS bank_details JSONB DEFAULT '{}'::jsonb;

-- ==========================================================================
-- Source: 20260711000001_allow_trial_coupon_before_hierarchy_creation.sql
-- ==========================================================================

-- Allow invite trial coupons to satisfy payment setup before hierarchy creation.
-- The tenant enters hierarchy first, then completes plan/payment or trial coupon, then hierarchy is created.

ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_payment_method_type_check;
ALTER TABLE public.profiles
  ADD CONSTRAINT profiles_payment_method_type_check
  CHECK (
    payment_method_type IS NULL
    OR payment_method_type IN ('card', 'ach', 'free_plan', 'mock_subscription', 'stripe_subscription', 'trial_coupon')
  );

UPDATE public.profiles p
SET payment_verified = true,
    payment_method_type = COALESCE(NULLIF(p.payment_method_type, ''), 'trial_coupon'),
    pending_payment_metadata = COALESCE(p.pending_payment_metadata, '{}'::jsonb)
      || jsonb_build_object(
        'provider', 'trial_coupon',
        'coupon_code', c.code,
        'trial_days', c.trial_days,
        'backfilled_at', now()
      ),
    updated_at = now()
FROM public.onboarding_coupon_redemptions r
JOIN public.onboarding_coupons c ON c.id = r.coupon_id
WHERE p.id = r.user_id
  AND COALESCE(p.payment_verified, false) IS NOT TRUE
  AND r.status IN ('applied', 'consumed')
  AND COALESCE(c.trial_days, 0) > 0;


CREATE OR REPLACE FUNCTION public.setup_onboarding_hierarchy(
  p_user_id uuid,
  p_hierarchy jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  org_item jsonb;
  brand_item jsonb;
  location_item jsonb;
  v_tenant_id uuid;
  v_org_id uuid;
  v_brand_id uuid;
  v_location_id uuid;
  v_primary_org_id uuid;
  v_primary_brand_id uuid;
  v_primary_location_id uuid;
  v_created_orgs jsonb := '[]'::jsonb;
  v_created_brands jsonb := '[]'::jsonb;
  v_created_locations jsonb := '[]'::jsonb;
  v_org_name text;
  v_org_slug text;
  v_brand_name text;
  v_location_name text;
  v_location_address text;
  v_org_count integer := 0;
  v_brand_count integer := 0;
  v_location_count integer := 0;
  v_business_status text;
  v_payment_verified boolean;
  v_pending_plan_id text;
  v_pending_stripe_customer_id text;
  v_pending_stripe_subscription_id text;
  v_pending_checkout_session_id text;
  v_pending_payment_metadata jsonb;
  v_run_id uuid;
  v_org_address jsonb;
  v_brand_address jsonb;
  v_business_address jsonb;
  v_mailing_address jsonb;
  v_tenant_identity jsonb;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  SELECT business_verification_status, payment_verified, pending_onboarding_plan_id, pending_stripe_customer_id, pending_stripe_subscription_id, pending_checkout_session_id, pending_payment_metadata
  INTO v_business_status, v_payment_verified, v_pending_plan_id, v_pending_stripe_customer_id, v_pending_stripe_subscription_id, v_pending_checkout_session_id, v_pending_payment_metadata
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE
     AND COALESCE(v_pending_payment_metadata->>'provider', '') NOT IN ('trial_coupon', 'free_plan', 'mock_subscription', 'stripe')
     AND NOT EXISTS (
       SELECT 1
       FROM public.onboarding_coupon_redemptions r
       JOIN public.onboarding_coupons c ON c.id = r.coupon_id
       WHERE r.user_id = p_user_id
         AND r.status IN ('applied', 'consumed')
         AND COALESCE(c.trial_days, 0) > 0
     ) THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' THEN
    RAISE EXCEPTION 'Onboarding hierarchy must be an array';
  END IF;

  IF jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  v_org_name := NULLIF(btrim((p_hierarchy->0)->>'name'), '');
  v_org_slug := NULLIF(btrim((p_hierarchy->0)->>'slug'), '');

  INSERT INTO public.tenants (name, slug, owner_id, metadata)
  VALUES (
    COALESCE(v_org_name, 'Tenant'),
    left('tenant_' || regexp_replace(lower(COALESCE(v_org_slug, gen_random_uuid()::text)), '[^a-z0-9]+', '_', 'g'), 63),
    p_user_id,
    jsonb_build_object(
      'source', 'setup_onboarding_hierarchy',
      'business_identity', (p_hierarchy->0)#>'{metadata,tenant_business_identity}'
    )
  )
  ON CONFLICT (slug) DO UPDATE
    SET owner_id = EXCLUDED.owner_id,
        metadata = COALESCE(public.tenants.metadata, '{}'::jsonb) || EXCLUDED.metadata
  RETURNING id INTO v_tenant_id;

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
  EXCEPTION WHEN undefined_function THEN
    v_run_id := NULL;
  END;

  FOR org_item IN SELECT value FROM jsonb_array_elements(p_hierarchy)
  LOOP
    v_org_name := NULLIF(btrim(org_item->>'name'), '');
    v_org_slug := NULLIF(btrim(org_item->>'slug'), '');
    v_org_address := COALESCE(org_item#>'{metadata,organization_business_address}', org_item#>'{metadata,organization_address}');
    v_mailing_address := CASE
      WHEN COALESCE((org_item#>>'{metadata,organization_mailing_same_as_business}')::boolean, true) THEN v_org_address
      ELSE org_item#>'{metadata,organization_mailing_address}'
    END;

    IF v_org_name IS NULL OR v_org_slug IS NULL THEN
      RAISE EXCEPTION 'Each organization requires a name and slug';
    END IF;

    IF COALESCE(jsonb_typeof(org_item->'brands'), 'null') <> 'array'
       OR jsonb_array_length(org_item->'brands') = 0 THEN
      RAISE EXCEPTION 'Organization % requires at least one brand', v_org_name;
    END IF;

    INSERT INTO public.organizations (tenant_id, name, slug, owner_id)
    VALUES (v_tenant_id, v_org_name, v_org_slug, p_user_id)
    RETURNING id INTO v_org_id;

    IF v_org_address IS NOT NULL AND COALESCE(jsonb_typeof(v_org_address), 'null') <> 'object' THEN
      RAISE EXCEPTION 'Organization % business/service address must be an object when provided', v_org_name;
    END IF;

    IF v_org_address IS NOT NULL THEN
      IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
        RAISE EXCEPTION 'Organization % mailing address must be an object when organization address is provided', v_org_name;
      END IF;

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'service', v_org_name, v_org_address
      );

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'mailing', v_org_name, v_mailing_address
      );
    END IF;

    v_org_count := v_org_count + 1;
    v_created_orgs := v_created_orgs || jsonb_build_array(jsonb_build_object('id', v_org_id, 'name', v_org_name, 'slug', v_org_slug));

    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_org_id, p_user_id, 'tenant_super_admin')
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    IF v_primary_org_id IS NULL THEN
      v_primary_org_id := v_org_id;
    END IF;

    FOR brand_item IN SELECT value FROM jsonb_array_elements(org_item->'brands')
    LOOP
      v_brand_name := NULLIF(btrim(brand_item->>'name'), '');
      v_brand_address := brand_item#>'{metadata,brand_address}';

      IF v_brand_name IS NULL THEN
        RAISE EXCEPTION 'Every brand in organization % requires a name', v_org_name;
      END IF;

      IF COALESCE(jsonb_typeof(brand_item->'locations'), 'null') <> 'array'
         OR jsonb_array_length(brand_item->'locations') = 0 THEN
        RAISE EXCEPTION 'Brand % requires at least one location', v_brand_name;
      END IF;

      INSERT INTO public.brands (organization_id, name)
      VALUES (v_org_id, v_brand_name)
      RETURNING brand_id INTO v_brand_id;

      IF v_brand_address IS NOT NULL AND COALESCE(jsonb_typeof(v_brand_address), 'null') = 'object' THEN
        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, NULL, 'service', v_brand_name, v_brand_address
        );
      END IF;

      v_brand_count := v_brand_count + 1;
      v_created_brands := v_created_brands || jsonb_build_array(jsonb_build_object('id', v_brand_id, 'organization_id', v_org_id, 'name', v_brand_name));

      INSERT INTO public.brand_members (brand_id, user_id, role)
      VALUES (v_brand_id, p_user_id, 'tenant_super_admin')
      ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

      IF v_primary_brand_id IS NULL THEN
        v_primary_brand_id := v_brand_id;
      END IF;

      FOR location_item IN SELECT value FROM jsonb_array_elements(brand_item->'locations')
      LOOP
        v_location_name := NULLIF(btrim(location_item->>'name'), '');
        v_location_address := COALESCE(NULLIF(btrim(location_item->>'address'), ''), 'Address pending');
        v_business_address := location_item->'business_address';
        v_mailing_address := location_item->'mailing_address';

        IF v_location_name IS NULL THEN
          RAISE EXCEPTION 'Every location in brand % requires a name', v_brand_name;
        END IF;

        IF v_business_address IS NULL OR COALESCE(jsonb_typeof(v_business_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a business/service address', v_brand_name;
        END IF;

        INSERT INTO public.locations (organization_id, brand_id, name, address)
        VALUES (v_org_id, v_brand_id, v_location_name, v_location_address)
        RETURNING id INTO v_location_id;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'service', v_location_name, v_business_address
        );

        IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a mailing address', v_brand_name;
        END IF;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'mailing', v_location_name, v_mailing_address
        );

        v_location_count := v_location_count + 1;
        v_created_locations := v_created_locations || jsonb_build_array(jsonb_build_object(
          'id', v_location_id,
          'organization_id', v_org_id,
          'brand_id', v_brand_id,
          'name', v_location_name,
          'address', v_location_address
        ));

        INSERT INTO public.location_members (location_id, user_id, role)
        VALUES (v_location_id, p_user_id, 'tenant_super_admin')
        ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

        IF v_primary_location_id IS NULL THEN
          v_primary_location_id := v_location_id;
        END IF;
      END LOOP;
    END LOOP;

    INSERT INTO public.onboarding_progress (organization_id, current_step, completed_steps, is_completed)
    VALUES (v_org_id, 'hierarchy_created', ARRAY['organizations', 'brands', 'locations'], false)
    ON CONFLICT DO NOTHING;
  END LOOP;

  INSERT INTO public.tenant_members (tenant_id, user_id, role)
  VALUES (v_tenant_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.profiles
  SET tenant_id = v_tenant_id,
      organization_id = v_primary_org_id,
      brand_id = v_primary_brand_id,
      location_id = v_primary_location_id,
      role = 'tenant_super_admin',
      access_level = 'organization',
      onboarding_status = 'completed',
      onboarding_current_step = 'completed',
      onboarding_completed_at = now(),
      updated_at = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'tenant_super_admin',
    'tenant_id', v_tenant_id::text,
    'organization_id', v_primary_org_id::text,
    'brand_id', v_primary_brand_id::text,
    'location_id', v_primary_location_id::text
  )
  WHERE id = p_user_id;

  IF v_primary_org_id IS NOT NULL THEN
    UPDATE public.organizations
    SET plan_id = COALESCE(v_pending_plan_id, plan_id),
        stripe_customer_id = COALESCE(v_pending_stripe_customer_id, stripe_customer_id),
        stripe_subscription_id = COALESCE(v_pending_stripe_subscription_id, stripe_subscription_id)
    WHERE id = v_primary_org_id;
  END IF;

  UPDATE public.business_verifications SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.organization_addresses SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_payment_methods SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_coupon_redemptions SET organization_id = v_primary_org_id
  WHERE user_id = p_user_id AND organization_id IS NULL;

  v_tenant_identity := (p_hierarchy->0)#>'{metadata,tenant_business_identity}';
  IF v_tenant_identity IS NOT NULL AND COALESCE(jsonb_typeof(v_tenant_identity), 'null') = 'object' THEN
    v_business_address := v_tenant_identity->'businessAddress';
    v_mailing_address := CASE
      WHEN COALESCE((v_tenant_identity->>'mailingSameAsBusiness')::boolean, true) THEN v_business_address
      ELSE v_tenant_identity->'mailingAddress'
    END;

    IF v_business_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'business'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'business', 'Tenant business identity', v_business_address
      );
    END IF;

    IF v_mailing_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'mailing'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'mailing', 'Tenant business identity', v_mailing_address
      );
    END IF;
  END IF;

  IF v_run_id IS NOT NULL THEN
    UPDATE public.onboarding_workflow_runs
    SET organization_id = v_primary_org_id,
        status = 'completed',
        current_step = 'completed',
        completed_at = now(),
        last_activity_at = now()
    WHERE id = v_run_id;

    PERFORM public.record_onboarding_event(
      v_run_id,
      p_user_id,
      'hierarchy_setup',
      'completed',
      'completed',
      jsonb_build_object('tenant_id', v_tenant_id, 'primary_org_id', v_primary_org_id, 'plan_id', v_pending_plan_id, 'checkout_session_id', v_pending_checkout_session_id)
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'tenant_id', v_tenant_id,
    'primary_org_id', v_primary_org_id,
    'primary_brand_id', v_primary_brand_id,
    'primary_location_id', v_primary_location_id,
    'organizations', v_created_orgs,
    'brands', v_created_brands,
    'locations', v_created_locations,
    'counts', jsonb_build_object('organizations', v_org_count, 'brands', v_brand_count, 'locations', v_location_count),
    'plan_id', v_pending_plan_id,
    'stripe_customer_id', v_pending_stripe_customer_id,
    'stripe_subscription_id', v_pending_stripe_subscription_id
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.setup_onboarding_hierarchy(uuid, jsonb) TO authenticated;

NOTIFY pgrst, 'reload schema';

-- ==========================================================================
-- Source: 20260711000002_treat_optional_hierarchy_address_json_null_as_absent.sql
-- ==========================================================================

-- Treat optional hierarchy address JSON null values as absent.

CREATE OR REPLACE FUNCTION public.setup_onboarding_hierarchy(
  p_user_id uuid,
  p_hierarchy jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  org_item jsonb;
  brand_item jsonb;
  location_item jsonb;
  v_tenant_id uuid;
  v_org_id uuid;
  v_brand_id uuid;
  v_location_id uuid;
  v_primary_org_id uuid;
  v_primary_brand_id uuid;
  v_primary_location_id uuid;
  v_created_orgs jsonb := '[]'::jsonb;
  v_created_brands jsonb := '[]'::jsonb;
  v_created_locations jsonb := '[]'::jsonb;
  v_org_name text;
  v_org_slug text;
  v_brand_name text;
  v_location_name text;
  v_location_address text;
  v_org_count integer := 0;
  v_brand_count integer := 0;
  v_location_count integer := 0;
  v_business_status text;
  v_payment_verified boolean;
  v_pending_plan_id text;
  v_pending_stripe_customer_id text;
  v_pending_stripe_subscription_id text;
  v_pending_checkout_session_id text;
  v_pending_payment_metadata jsonb;
  v_run_id uuid;
  v_org_address jsonb;
  v_brand_address jsonb;
  v_business_address jsonb;
  v_mailing_address jsonb;
  v_tenant_identity jsonb;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  SELECT business_verification_status, payment_verified, pending_onboarding_plan_id, pending_stripe_customer_id, pending_stripe_subscription_id, pending_checkout_session_id, pending_payment_metadata
  INTO v_business_status, v_payment_verified, v_pending_plan_id, v_pending_stripe_customer_id, v_pending_stripe_subscription_id, v_pending_checkout_session_id, v_pending_payment_metadata
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE
     AND COALESCE(v_pending_payment_metadata->>'provider', '') NOT IN ('trial_coupon', 'free_plan', 'mock_subscription', 'stripe')
     AND NOT EXISTS (
       SELECT 1
       FROM public.onboarding_coupon_redemptions r
       JOIN public.onboarding_coupons c ON c.id = r.coupon_id
       WHERE r.user_id = p_user_id
         AND r.status IN ('applied', 'consumed')
         AND COALESCE(c.trial_days, 0) > 0
     ) THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' THEN
    RAISE EXCEPTION 'Onboarding hierarchy must be an array';
  END IF;

  IF jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  v_org_name := NULLIF(btrim((p_hierarchy->0)->>'name'), '');
  v_org_slug := NULLIF(btrim((p_hierarchy->0)->>'slug'), '');

  INSERT INTO public.tenants (name, slug, owner_id, metadata)
  VALUES (
    COALESCE(v_org_name, 'Tenant'),
    left('tenant_' || regexp_replace(lower(COALESCE(v_org_slug, gen_random_uuid()::text)), '[^a-z0-9]+', '_', 'g'), 63),
    p_user_id,
    jsonb_build_object(
      'source', 'setup_onboarding_hierarchy',
      'business_identity', (p_hierarchy->0)#>'{metadata,tenant_business_identity}'
    )
  )
  ON CONFLICT (slug) DO UPDATE
    SET owner_id = EXCLUDED.owner_id,
        metadata = COALESCE(public.tenants.metadata, '{}'::jsonb) || EXCLUDED.metadata
  RETURNING id INTO v_tenant_id;

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
  EXCEPTION WHEN undefined_function THEN
    v_run_id := NULL;
  END;

  FOR org_item IN SELECT value FROM jsonb_array_elements(p_hierarchy)
  LOOP
    v_org_name := NULLIF(btrim(org_item->>'name'), '');
    v_org_slug := NULLIF(btrim(org_item->>'slug'), '');
    v_org_address := NULLIF(COALESCE(org_item#>'{metadata,organization_business_address}', org_item#>'{metadata,organization_address}'), 'null'::jsonb);
    v_mailing_address := CASE
      WHEN COALESCE((org_item#>>'{metadata,organization_mailing_same_as_business}')::boolean, true) THEN v_org_address
      ELSE NULLIF(org_item#>'{metadata,organization_mailing_address}', 'null'::jsonb)
    END;

    IF v_org_name IS NULL OR v_org_slug IS NULL THEN
      RAISE EXCEPTION 'Each organization requires a name and slug';
    END IF;

    IF COALESCE(jsonb_typeof(org_item->'brands'), 'null') <> 'array'
       OR jsonb_array_length(org_item->'brands') = 0 THEN
      RAISE EXCEPTION 'Organization % requires at least one brand', v_org_name;
    END IF;

    INSERT INTO public.organizations (tenant_id, name, slug, owner_id)
    VALUES (v_tenant_id, v_org_name, v_org_slug, p_user_id)
    RETURNING id INTO v_org_id;

    IF v_org_address IS NOT NULL AND COALESCE(jsonb_typeof(v_org_address), 'null') <> 'object' THEN
      RAISE EXCEPTION 'Organization % business/service address must be an object when provided', v_org_name;
    END IF;

    IF v_org_address IS NOT NULL THEN
      IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
        RAISE EXCEPTION 'Organization % mailing address must be an object when organization address is provided', v_org_name;
      END IF;

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'service', v_org_name, v_org_address
      );

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'mailing', v_org_name, v_mailing_address
      );
    END IF;

    v_org_count := v_org_count + 1;
    v_created_orgs := v_created_orgs || jsonb_build_array(jsonb_build_object('id', v_org_id, 'name', v_org_name, 'slug', v_org_slug));

    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_org_id, p_user_id, 'tenant_super_admin')
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    IF v_primary_org_id IS NULL THEN
      v_primary_org_id := v_org_id;
    END IF;

    FOR brand_item IN SELECT value FROM jsonb_array_elements(org_item->'brands')
    LOOP
      v_brand_name := NULLIF(btrim(brand_item->>'name'), '');
      v_brand_address := NULLIF(brand_item#>'{metadata,brand_address}', 'null'::jsonb);

      IF v_brand_name IS NULL THEN
        RAISE EXCEPTION 'Every brand in organization % requires a name', v_org_name;
      END IF;

      IF COALESCE(jsonb_typeof(brand_item->'locations'), 'null') <> 'array'
         OR jsonb_array_length(brand_item->'locations') = 0 THEN
        RAISE EXCEPTION 'Brand % requires at least one location', v_brand_name;
      END IF;

      INSERT INTO public.brands (organization_id, name)
      VALUES (v_org_id, v_brand_name)
      RETURNING brand_id INTO v_brand_id;

      IF v_brand_address IS NOT NULL AND COALESCE(jsonb_typeof(v_brand_address), 'null') = 'object' THEN
        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, NULL, 'service', v_brand_name, v_brand_address
        );
      END IF;

      v_brand_count := v_brand_count + 1;
      v_created_brands := v_created_brands || jsonb_build_array(jsonb_build_object('id', v_brand_id, 'organization_id', v_org_id, 'name', v_brand_name));

      INSERT INTO public.brand_members (brand_id, user_id, role)
      VALUES (v_brand_id, p_user_id, 'tenant_super_admin')
      ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

      IF v_primary_brand_id IS NULL THEN
        v_primary_brand_id := v_brand_id;
      END IF;

      FOR location_item IN SELECT value FROM jsonb_array_elements(brand_item->'locations')
      LOOP
        v_location_name := NULLIF(btrim(location_item->>'name'), '');
        v_location_address := COALESCE(NULLIF(btrim(location_item->>'address'), ''), 'Address pending');
        v_business_address := location_item->'business_address';
        v_mailing_address := location_item->'mailing_address';

        IF v_location_name IS NULL THEN
          RAISE EXCEPTION 'Every location in brand % requires a name', v_brand_name;
        END IF;

        IF v_business_address IS NULL OR COALESCE(jsonb_typeof(v_business_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a business/service address', v_brand_name;
        END IF;

        INSERT INTO public.locations (organization_id, brand_id, name, address)
        VALUES (v_org_id, v_brand_id, v_location_name, v_location_address)
        RETURNING id INTO v_location_id;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'service', v_location_name, v_business_address
        );

        IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a mailing address', v_brand_name;
        END IF;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'mailing', v_location_name, v_mailing_address
        );

        v_location_count := v_location_count + 1;
        v_created_locations := v_created_locations || jsonb_build_array(jsonb_build_object(
          'id', v_location_id,
          'organization_id', v_org_id,
          'brand_id', v_brand_id,
          'name', v_location_name,
          'address', v_location_address
        ));

        INSERT INTO public.location_members (location_id, user_id, role)
        VALUES (v_location_id, p_user_id, 'tenant_super_admin')
        ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

        IF v_primary_location_id IS NULL THEN
          v_primary_location_id := v_location_id;
        END IF;
      END LOOP;
    END LOOP;

    INSERT INTO public.onboarding_progress (organization_id, current_step, completed_steps, is_completed)
    VALUES (v_org_id, 'hierarchy_created', ARRAY['organizations', 'brands', 'locations'], false)
    ON CONFLICT DO NOTHING;
  END LOOP;

  INSERT INTO public.tenant_members (tenant_id, user_id, role)
  VALUES (v_tenant_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.profiles
  SET tenant_id = v_tenant_id,
      organization_id = v_primary_org_id,
      brand_id = v_primary_brand_id,
      location_id = v_primary_location_id,
      role = 'tenant_super_admin',
      access_level = 'organization',
      onboarding_status = 'completed',
      onboarding_current_step = 'completed',
      onboarding_completed_at = now(),
      updated_at = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'tenant_super_admin',
    'tenant_id', v_tenant_id::text,
    'organization_id', v_primary_org_id::text,
    'brand_id', v_primary_brand_id::text,
    'location_id', v_primary_location_id::text
  )
  WHERE id = p_user_id;

  IF v_primary_org_id IS NOT NULL THEN
    UPDATE public.organizations
    SET plan_id = COALESCE(v_pending_plan_id, plan_id),
        stripe_customer_id = COALESCE(v_pending_stripe_customer_id, stripe_customer_id),
        stripe_subscription_id = COALESCE(v_pending_stripe_subscription_id, stripe_subscription_id)
    WHERE id = v_primary_org_id;
  END IF;

  UPDATE public.business_verifications SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.organization_addresses SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_payment_methods SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_coupon_redemptions SET organization_id = v_primary_org_id
  WHERE user_id = p_user_id AND organization_id IS NULL;

  v_tenant_identity := (p_hierarchy->0)#>'{metadata,tenant_business_identity}';
  IF v_tenant_identity IS NOT NULL AND COALESCE(jsonb_typeof(v_tenant_identity), 'null') = 'object' THEN
    v_business_address := v_tenant_identity->'businessAddress';
    v_mailing_address := CASE
      WHEN COALESCE((v_tenant_identity->>'mailingSameAsBusiness')::boolean, true) THEN v_business_address
      ELSE v_tenant_identity->'mailingAddress'
    END;

    IF v_business_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'business'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'business', 'Tenant business identity', v_business_address
      );
    END IF;

    IF v_mailing_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'mailing'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'mailing', 'Tenant business identity', v_mailing_address
      );
    END IF;
  END IF;

  IF v_run_id IS NOT NULL THEN
    UPDATE public.onboarding_workflow_runs
    SET organization_id = v_primary_org_id,
        status = 'completed',
        current_step = 'completed',
        completed_at = now(),
        last_activity_at = now()
    WHERE id = v_run_id;

    PERFORM public.record_onboarding_event(
      v_run_id,
      p_user_id,
      'hierarchy_setup',
      'completed',
      'completed',
      jsonb_build_object('tenant_id', v_tenant_id, 'primary_org_id', v_primary_org_id, 'plan_id', v_pending_plan_id, 'checkout_session_id', v_pending_checkout_session_id)
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'tenant_id', v_tenant_id,
    'primary_org_id', v_primary_org_id,
    'primary_brand_id', v_primary_brand_id,
    'primary_location_id', v_primary_location_id,
    'organizations', v_created_orgs,
    'brands', v_created_brands,
    'locations', v_created_locations,
    'counts', jsonb_build_object('organizations', v_org_count, 'brands', v_brand_count, 'locations', v_location_count),
    'plan_id', v_pending_plan_id,
    'stripe_customer_id', v_pending_stripe_customer_id,
    'stripe_subscription_id', v_pending_stripe_subscription_id
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.setup_onboarding_hierarchy(uuid, jsonb) TO authenticated;

NOTIFY pgrst, 'reload schema';

-- ==========================================================================
-- Source: 20260711000003_backfill_no_business_verification_invites.sql
-- ==========================================================================

-- Backfill accepted tenant super admin invites where platform admin disabled business verification.
-- New accepts already do this in accept_invitation; this fixes older/stuck test users.

UPDATE public.profiles p
SET business_verification_status = 'verified',
    onboarding_current_step = CASE
      WHEN p.organization_id IS NULL THEN 'hierarchy_setup'
      ELSE p.onboarding_current_step
    END,
    updated_at = now()
FROM public.invitations i
WHERE i.accepted_by = p.id
  AND public.normalize_app_role(i.role) = 'tenant_super_admin'
  AND COALESCE((i.metadata->>'business_verification_required')::boolean, true) IS FALSE
  AND COALESCE(p.business_verification_status, 'not_started') <> 'verified';

NOTIFY pgrst, 'reload schema';

-- ==========================================================================
-- Source: 20260711000004_vendor_onboarding_flow.sql
-- ==========================================================================

BEGIN;

ALTER TABLE public.vendors
  ADD COLUMN IF NOT EXISTS business_verified_at timestamptz;

ALTER TABLE public.vendors
  DROP CONSTRAINT IF EXISTS vendors_onboarding_status_check;

ALTER TABLE public.vendors
  ADD CONSTRAINT vendors_onboarding_status_check
  CHECK (
    onboarding_status IS NULL
    OR onboarding_status IN (
      'invited',
      'pending_otp',
      'otp_verified',
      'pending_tax',
      'tax_submitted',
      'business_verified',
      'verification_failed',
      'documents_on_file',
      'pending_bank',
      'banking_submitted',
      'banking_verified',
      'method_selected',
      'pending_approval',
      'active',
      'completed',
      'rejected'
    )
  );

CREATE TABLE IF NOT EXISTS public.vendor_otp_challenges (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id uuid NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  brand_id uuid REFERENCES public.brands(brand_id) ON DELETE SET NULL,
  location_id uuid REFERENCES public.locations(id) ON DELETE SET NULL,
  channel text NOT NULL DEFAULT 'email' CHECK (channel IN ('email', 'sms')),
  otp_hash text NOT NULL,
  expires_at timestamptz NOT NULL DEFAULT now() + interval '10 minutes',
  attempt_count integer NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  max_attempts integer NOT NULL DEFAULT 5 CHECK (max_attempts > 0),
  status text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'verified', 'expired', 'failed_max_attempts')),
  verified_at timestamptz,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.vendor_link_tokens (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id uuid NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  brand_id uuid REFERENCES public.brands(brand_id) ON DELETE SET NULL,
  location_id uuid REFERENCES public.locations(id) ON DELETE SET NULL,
  link_type text NOT NULL CHECK (link_type IN ('tax', 'documents')),
  token text NOT NULL DEFAULT encode(gen_random_bytes(32), 'hex'),
  status text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'submitted', 'expired', 'cancelled')),
  expires_at timestamptz NOT NULL DEFAULT now() + interval '24 hours',
  submitted_at timestamptz,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);

CREATE TABLE IF NOT EXISTS public.vendor_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id uuid NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  brand_id uuid REFERENCES public.brands(brand_id) ON DELETE SET NULL,
  location_id uuid REFERENCES public.locations(id) ON DELETE SET NULL,
  document_type text NOT NULL
    CHECK (document_type IN ('w9', 'certificate_of_insurance', 'business_license', 'vendor_agreement', 'other')),
  file_name text,
  storage_path text NOT NULL,
  mime_type text,
  file_size_bytes bigint CHECK (file_size_bytes IS NULL OR file_size_bytes >= 0),
  status text NOT NULL DEFAULT 'pending_review'
    CHECK (status IN ('pending_review', 'on_file', 'expired', 'rejected')),
  issued_date date,
  expires_at date,
  uploaded_via text NOT NULL DEFAULT 'admin_upload'
    CHECK (uploaded_via IN ('admin_upload', 'vendor_magic_link')),
  uploaded_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  reviewed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  reviewed_at timestamptz,
  review_notes text,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);

ALTER TABLE public.vendor_tax_information
  ADD COLUMN IF NOT EXISTS tax_id_type text,
  ADD COLUMN IF NOT EXISTS verification_status text NOT NULL DEFAULT 'not_started',
  ADD COLUMN IF NOT EXISTS verification_method text,
  ADD COLUMN IF NOT EXISTS verification_reference text,
  ADD COLUMN IF NOT EXISTS verification_checked_at timestamptz,
  ADD COLUMN IF NOT EXISTS verification_failure_reason text,
  ADD COLUMN IF NOT EXISTS w9_document_id uuid REFERENCES public.vendor_documents(id) ON DELETE SET NULL;

ALTER TABLE public.vendor_tax_information
  DROP CONSTRAINT IF EXISTS vendor_tax_information_tax_id_type_check,
  DROP CONSTRAINT IF EXISTS vendor_tax_information_verification_status_check,
  DROP CONSTRAINT IF EXISTS vendor_tax_information_verification_method_check;

ALTER TABLE public.vendor_tax_information
  ADD CONSTRAINT vendor_tax_information_tax_id_type_check
    CHECK (tax_id_type IS NULL OR tax_id_type IN ('ein', 'ssn')),
  ADD CONSTRAINT vendor_tax_information_verification_status_check
    CHECK (verification_status IN ('not_started', 'pending', 'verified', 'failed', 'mismatch')),
  ADD CONSTRAINT vendor_tax_information_verification_method_check
    CHECK (verification_method IS NULL OR verification_method IN ('irs_tin_match', 'business_registry_lookup', 'manual_review'));

ALTER TABLE public.vendor_banking_details
  ADD COLUMN IF NOT EXISTS callback_status text NOT NULL DEFAULT 'pending';

ALTER TABLE public.vendor_banking_details
  DROP CONSTRAINT IF EXISTS vendor_banking_details_callback_status_check;

ALTER TABLE public.vendor_banking_details
  ADD CONSTRAINT vendor_banking_details_callback_status_check
    CHECK (callback_status IN ('not_required', 'pending', 'confirmed', 'failed'));

UPDATE public.vendor_banking_details
   SET callback_status = 'confirmed'
 WHERE verification_state = 'verified'
   AND callback_status = 'pending'
   AND deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS public.vendor_banking_change_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id uuid NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  brand_id uuid REFERENCES public.brands(brand_id) ON DELETE SET NULL,
  location_id uuid REFERENCES public.locations(id) ON DELETE SET NULL,
  banking_detail_id uuid NOT NULL REFERENCES public.vendor_banking_details(id) ON DELETE CASCADE,
  request_reason text NOT NULL
    CHECK (request_reason IN ('onboarding', 'vendor_requested_update', 'admin_correction')),
  requested_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  requested_at timestamptz NOT NULL DEFAULT now(),
  callback_phone_source text NOT NULL DEFAULT 'on_file_contact'
    CHECK (callback_phone_source IN ('on_file_contact', 'w9_registered_number')),
  callback_status text NOT NULL DEFAULT 'not_started'
    CHECK (callback_status IN ('not_started', 'call_scheduled', 'left_message', 'confirmed', 'failed', 'skipped_override')),
  confirmed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  confirmed_at timestamptz,
  override_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  override_reason text,
  override_at timestamptz,
  notes text,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.vendor_onboarding_preferences (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id uuid NOT NULL UNIQUE REFERENCES public.vendors(id) ON DELETE CASCADE,
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  brand_id uuid REFERENCES public.brands(brand_id) ON DELETE SET NULL,
  location_id uuid REFERENCES public.locations(id) ON DELETE SET NULL,
  invoice_intake_method text NOT NULL CHECK (invoice_intake_method IN ('photo', 'email', 'portal', 'edi')),
  edi_status text NOT NULL DEFAULT 'not_applicable'
    CHECK (edi_status IN ('not_applicable', 'requested', 'in_progress', 'connected', 'failed')),
  price_alert_threshold_percent numeric(5,2),
  order_cadence text,
  set_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  set_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.vendor_onboarding_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id uuid NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  brand_id uuid REFERENCES public.brands(brand_id) ON DELETE SET NULL,
  location_id uuid REFERENCES public.locations(id) ON DELETE SET NULL,
  event_type text NOT NULL,
  from_status text,
  to_status text,
  actor_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  actor_type text NOT NULL DEFAULT 'system' CHECK (actor_type IN ('admin', 'vendor', 'system')),
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);

