-- ==========================================================================
-- Source: 20260717000003_payment_reminders_and_failure_notify.sql
-- ==========================================================================

BEGIN;

-- Per-user due-date reminder settings. Deliberately per-user, not org-wide (each person picks
-- their own reminder cadence for invoices they can already see).
CREATE TABLE IF NOT EXISTS public.invoice_reminder_settings (
  user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  reminder_days int[] NOT NULL DEFAULT '{7,3,1}',
  enabled boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.invoice_reminder_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoice_reminder_settings FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "invoice_reminder_settings_self" ON public.invoice_reminder_settings;
CREATE POLICY "invoice_reminder_settings_self"
  ON public.invoice_reminder_settings
  FOR ALL
  USING (user_id = auth.uid() OR auth.role() = 'service_role')
  WITH CHECK (user_id = auth.uid() OR auth.role() = 'service_role');

GRANT SELECT, INSERT, UPDATE, DELETE ON public.invoice_reminder_settings TO authenticated;
GRANT ALL ON public.invoice_reminder_settings TO service_role;

-- Idempotency log: one row per (invoice, user, reminder_day) that's ever fired, so the daily
-- job can never re-notify for the same threshold crossing.
CREATE TABLE IF NOT EXISTS public.invoice_reminder_log (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id uuid NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  reminder_day int NOT NULL,
  sent_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (invoice_id, user_id, reminder_day)
);

ALTER TABLE public.invoice_reminder_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoice_reminder_log FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "invoice_reminder_log_self_read" ON public.invoice_reminder_log;
CREATE POLICY "invoice_reminder_log_self_read"
  ON public.invoice_reminder_log
  FOR SELECT
  USING (user_id = auth.uid() OR auth.role() = 'service_role');

REVOKE ALL ON public.invoice_reminder_log FROM authenticated, anon;
GRANT SELECT ON public.invoice_reminder_log TO authenticated;
GRANT ALL ON public.invoice_reminder_log TO service_role;

-- Payments needs a failure_reason so the UI can show WHY a payout failed (not just that it
-- did). Nothing set payments.status='failed' synchronously before the payment-workflow-
-- hardening pass above; this column already exists if that migration ran first, IF NOT EXISTS
-- keeps this migration standalone-safe either way.
ALTER TABLE public.payments ADD COLUMN IF NOT EXISTS failure_reason text;

-- Reimplements the org_owner/branch_manager/location_manager/ground_staff visibility rule
-- from financial_scope_visible(), but against an EXPLICIT target user's profile instead of
-- auth.uid() -- financial_scope_visible only ever checks the calling session's own access,
-- which is meaningless inside a cron job that has to evaluate many different users' access.
CREATE OR REPLACE FUNCTION public.send_due_date_reminders()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_setting RECORD;
  v_profile RECORD;
  v_invoice RECORD;
BEGIN
  FOR v_setting IN
    SELECT user_id, organization_id, reminder_days
    FROM public.invoice_reminder_settings
    WHERE enabled = true
  LOOP
    SELECT role, organization_id, brand_id, location_id
      INTO v_profile
    FROM public.profiles
    WHERE id = v_setting.user_id
      AND deleted_at IS NULL;

    IF v_profile.role IS NULL THEN
      CONTINUE;
    END IF;

    FOR v_invoice IN
      SELECT i.id, i.due_date, (i.due_date - CURRENT_DATE) AS days_out
      FROM public.invoices i
      WHERE i.deleted_at IS NULL
        AND i.organization_id = v_setting.organization_id
        AND COALESCE(i.payment_status, 'unpaid') NOT IN ('paid', 'auto_pay')
        AND i.due_date IS NOT NULL
        AND (i.due_date - CURRENT_DATE) = ANY(v_setting.reminder_days)
        AND (
          v_profile.role IN ('org_owner', 'platform_admin')
          OR (
            v_profile.role = 'branch_manager'
            AND (
              i.brand_id = v_profile.brand_id
              OR i.location_id IN (SELECT l.id FROM public.locations l WHERE l.brand_id = v_profile.brand_id)
            )
          )
          OR (
            v_profile.role IN ('location_manager', 'ground_staff')
            AND i.location_id = v_profile.location_id
          )
        )
    LOOP
      INSERT INTO public.invoice_reminder_log (invoice_id, user_id, reminder_day)
      VALUES (v_invoice.id, v_setting.user_id, v_invoice.days_out)
      ON CONFLICT (invoice_id, user_id, reminder_day) DO NOTHING;

      IF FOUND THEN
        INSERT INTO public.notifications (user_id, organization_id, type, title, message, is_read, metadata)
        VALUES (
          v_setting.user_id,
          v_setting.organization_id,
          'invoice',
          CASE WHEN v_invoice.days_out <= 0 THEN 'Invoice overdue' ELSE 'Invoice due soon' END,
          CASE WHEN v_invoice.days_out <= 0
            THEN format('An invoice was due on %s and is still unpaid.', to_char(v_invoice.due_date, 'Mon DD, YYYY'))
            ELSE format('An invoice is due in %s day%s (%s).', v_invoice.days_out, CASE WHEN v_invoice.days_out = 1 THEN '' ELSE 's' END, to_char(v_invoice.due_date, 'Mon DD, YYYY'))
          END,
          false,
          jsonb_build_object('invoice_id', v_invoice.id, 'due_in_days', v_invoice.days_out)
        );
      END IF;
    END LOOP;
  END LOOP;

  -- Trigger the email side (plain SQL can't call Resend). Same secure-dispatch pattern as
  -- dispatch_webhook_queue(): read the functions URL/service key from
  -- private.workflow_runtime_settings rather than hardcoding credentials in this function.
  DECLARE
    v_functions_url text;
    v_service_role_key text;
    v_url text;
  BEGIN
    SELECT setting_value INTO v_functions_url FROM private.workflow_runtime_settings WHERE setting_name = 'functions_url';
    SELECT setting_value INTO v_service_role_key FROM private.workflow_runtime_settings WHERE setting_name = 'service_role_key';

    IF v_service_role_key IS NOT NULL AND length(trim(v_service_role_key)) > 0 THEN
      v_url := COALESCE(NULLIF(trim(v_functions_url), ''), 'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1') || '/send-due-date-reminder-emails';

      PERFORM net.http_post(
        url := v_url,
        body := '{}'::jsonb,
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || v_service_role_key
        )
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Notifications already landed above; a failure to trigger the email side is non-fatal.
    NULL;
  END;
END;
$$;

REVOKE ALL ON FUNCTION public.send_due_date_reminders() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.send_due_date_reminders() TO service_role;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    BEGIN
      PERFORM cron.unschedule('send_due_date_reminders')
      WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'send_due_date_reminders');

      PERFORM cron.schedule(
        'send_due_date_reminders',
        '0 8 * * *',
        'SELECT public.send_due_date_reminders();'
      );
    EXCEPTION WHEN OTHERS THEN
      -- local/CI without cron privileges: skip, not fatal
      NULL;
    END;
  END IF;
END $$;

COMMIT;

-- ==========================================================================
-- Source: 20260718000001_profiles_rls_tenant_super_admin_fix.sql
-- ==========================================================================

-- Fix profiles RLS: org_owner -> org_manager rename (20260708000002) never propagated here.
-- profiles_nonrecursive_select / profiles_owner_delete_nonrecursive still gate on the dead
-- 'org_owner' string, so org_manager and tenant_super_admin cannot see or remove other users'
-- profiles in their own org. Closes CLAUDE.md's open Phase 2c item.
--
-- Fix: route through the already-correct access_membership_readable/writable() functions
-- (20260708000002...sql:458/:550), the same primitives organization_members/brand_members/
-- location_members already use. No new role logic — just reuse what's already correct.

BEGIN;

DROP POLICY IF EXISTS profiles_nonrecursive_select ON public.profiles;
DROP POLICY IF EXISTS profiles_owner_delete_nonrecursive ON public.profiles;

CREATE POLICY profiles_nonrecursive_select ON public.profiles
  FOR SELECT
  USING (
    id = auth.uid()
    OR public.access_membership_readable(id, organization_id, brand_id, location_id)
  );

CREATE POLICY profiles_owner_delete_nonrecursive ON public.profiles
  FOR DELETE
  USING (
    id <> auth.uid()
    AND public.access_membership_writable(id, organization_id, brand_id, location_id)
  );

COMMIT;

-- ==========================================================================
-- Source: 20260718000002_organizations_rls_hierarchy_rebuild.sql
-- ==========================================================================

-- Rebuild organizations RLS: the current policy set is fossils from three eras (002/004/005
-- JWT-user_metadata-based, 011 owner_id-based) never revisited when tenant_super_admin/
-- org_manager were introduced (20260708000002). No policy grants tenant-wide visibility to
-- tenant_super_admin, which is why ContextSwitcher.jsx's "tenant org dropdown" query returns
-- nothing useful for that role today. Drop everything, rebuild on get_auth_role()/
-- get_auth_tenant() (profiles-based, not JWT), per CLAUDE.md's "drop stale, don't add beside".
--
-- No INSERT policy is added: both onboarding paths (setup_organization_full,
-- setup_onboarding_hierarchy, both in 20260708000002...sql) are SECURITY DEFINER and insert
-- organizations rows themselves, bypassing RLS -- confirmed no other code path needs a
-- direct-client INSERT policy on this table.

BEGIN;

DROP POLICY IF EXISTS "RLS_SaaS_Isolation_organizations" ON public.organizations;
DROP POLICY IF EXISTS "Platform Admins see all Orgs" ON public.organizations;
DROP POLICY IF EXISTS "Users see their own Org" ON public.organizations;
DROP POLICY IF EXISTS "Users can create their own organization" ON public.organizations;
DROP POLICY IF EXISTS "Owners can view their own organizations" ON public.organizations;

CREATE POLICY organizations_select_scope ON public.organizations
  FOR SELECT
  USING (
    public.is_platform_admin()
    OR id = public.get_auth_org()
    OR (public.get_auth_role() = 'tenant_super_admin' AND tenant_id = public.get_auth_tenant())
  );

CREATE POLICY organizations_write_scope ON public.organizations
  FOR UPDATE
  USING (
    public.is_platform_admin()
    OR (public.get_auth_role() = 'org_manager' AND id = public.get_auth_org())
    OR (public.get_auth_role() = 'tenant_super_admin' AND tenant_id = public.get_auth_tenant())
  )
  WITH CHECK (
    public.is_platform_admin()
    OR (public.get_auth_role() = 'org_manager' AND id = public.get_auth_org())
    OR (public.get_auth_role() = 'tenant_super_admin' AND tenant_id = public.get_auth_tenant())
  );

COMMIT;

-- ==========================================================================
-- Source: 20260718000003_brands_locations_rls_tenant_super_admin_fix.sql
-- ==========================================================================

-- Fix brands/locations RLS: 20260628000003_harden_context_plumbing.sql predates the
-- tenant_super_admin/org_manager role model (20260708000002) and was never revisited.
--   - SELECT: get_auth_role() = 'org_owner' (dead string) OR'd with an outer
--     organization_id = get_auth_org() AND that silently collapses tenant_super_admin's
--     cross-org visibility down to one org.
--   - INSERT/UPDATE/DELETE: get_auth_role() IN ('branch_manager', 'org_owner') -- neither
--     org_manager nor tenant_super_admin can create/edit/delete a brand or location at all.
--
-- Depends on 20260718000002 (organizations RLS) being applied first: the INSERT/UPDATE
-- WITH CHECK clauses below run an inline subquery against public.organizations, which is
-- itself subject to organizations' RLS (not a SECURITY DEFINER call) -- see the plan's
-- Ordering note.
--
-- Rebuilt on the already-correct get_my_accessible_brand_ids()/get_my_accessible_location_ids()
-- (20260708000002...sql:402/:428), which already do full per-role scoping including
-- tenant-wide for tenant_super_admin. brand_id is brands' PK (renamed from id in
-- 114_rename_brands_id.sql); locations keeps id as PK with locations.brand_id as the FK.
--
-- Product decision: branch_manager manages brands/locations already assigned to them but does
-- NOT get brand-creation rights -- only org_manager and above can INSERT a brand. A
-- branch_manager CAN insert a new location under a brand they already manage.

BEGIN;

DROP POLICY IF EXISTS "brands_hierarchical_select" ON public.brands;
DROP POLICY IF EXISTS "brands_hierarchical_insert" ON public.brands;
DROP POLICY IF EXISTS "brands_hierarchical_update" ON public.brands;
DROP POLICY IF EXISTS "brands_hierarchical_delete" ON public.brands;

DROP POLICY IF EXISTS "locations_hierarchical_select" ON public.locations;
DROP POLICY IF EXISTS "locations_hierarchical_insert" ON public.locations;
DROP POLICY IF EXISTS "locations_hierarchical_update" ON public.locations;
DROP POLICY IF EXISTS "locations_hierarchical_delete" ON public.locations;

-- ===== brands =====

CREATE POLICY "brands_hierarchical_select"
ON public.brands
FOR SELECT
USING (
  public.is_platform_admin()
  OR brand_id = ANY (ARRAY(SELECT public.get_my_accessible_brand_ids()))
);

CREATE POLICY "brands_hierarchical_insert"
ON public.brands
FOR INSERT
WITH CHECK (
  public.access_role_rank(public.get_auth_role()) >= public.access_role_rank('org_manager')
  AND (
    public.is_platform_admin()
    OR (
      public.get_auth_role() = 'tenant_super_admin'
      AND organization_id IN (
        SELECT id FROM public.organizations WHERE tenant_id = public.get_auth_tenant()
      )
    )
    OR (
      public.get_auth_role() = 'org_manager'
      AND organization_id = public.get_auth_org()
    )
  )
);

CREATE POLICY "brands_hierarchical_update"
ON public.brands
FOR UPDATE
USING (
  public.is_platform_admin()
  OR (
    public.access_role_rank(public.get_auth_role()) >= public.access_role_rank('branch_manager')
    AND brand_id = ANY (ARRAY(SELECT public.get_my_accessible_brand_ids()))
  )
)
WITH CHECK (
  public.is_platform_admin()
  OR (
    public.access_role_rank(public.get_auth_role()) >= public.access_role_rank('branch_manager')
    AND brand_id = ANY (ARRAY(SELECT public.get_my_accessible_brand_ids()))
    AND (
      (public.get_auth_role() = 'tenant_super_admin'
        AND organization_id IN (SELECT id FROM public.organizations WHERE tenant_id = public.get_auth_tenant()))
      OR (public.get_auth_role() IN ('org_manager', 'branch_manager')
        AND organization_id = public.get_auth_org())
    )
  )
);

CREATE POLICY "brands_hierarchical_delete"
ON public.brands
FOR DELETE
USING (
  public.is_platform_admin()
  OR (
    public.access_role_rank(public.get_auth_role()) >= public.access_role_rank('branch_manager')
    AND brand_id = ANY (ARRAY(SELECT public.get_my_accessible_brand_ids()))
  )
);

-- ===== locations =====

CREATE POLICY "locations_hierarchical_select"
ON public.locations
FOR SELECT
USING (
  public.is_platform_admin()
  OR id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
);

CREATE POLICY "locations_hierarchical_insert"
ON public.locations
FOR INSERT
WITH CHECK (
  public.access_role_rank(public.get_auth_role()) >= public.access_role_rank('branch_manager')
  AND brand_id = ANY (ARRAY(SELECT public.get_my_accessible_brand_ids()))
  AND organization_id IN (
    SELECT b.organization_id FROM public.brands b WHERE b.brand_id = locations.brand_id
  )
);

CREATE POLICY "locations_hierarchical_update"
ON public.locations
FOR UPDATE
USING (
  public.is_platform_admin()
  OR (
    public.access_role_rank(public.get_auth_role()) >= public.access_role_rank('branch_manager')
    AND id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
  )
)
WITH CHECK (
  public.is_platform_admin()
  OR (
    public.access_role_rank(public.get_auth_role()) >= public.access_role_rank('branch_manager')
    AND brand_id = ANY (ARRAY(SELECT public.get_my_accessible_brand_ids()))
    AND organization_id IN (
      SELECT b.organization_id FROM public.brands b WHERE b.brand_id = locations.brand_id
    )
  )
);

CREATE POLICY "locations_hierarchical_delete"
ON public.locations
FOR DELETE
USING (
  public.is_platform_admin()
  OR (
    public.access_role_rank(public.get_auth_role()) >= public.access_role_rank('branch_manager')
    AND id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))
  )
);

COMMIT;

-- ==========================================================================
-- Source: 20260718000004_fix_reminders_role_list.sql
-- ==========================================================================

-- send_due_date_reminders (20260717000001_payment_reminders_and_failure_notify.sql) shipped
-- 9 days after tenant_super_admin/org_manager existed and still used the dead 'org_owner'
-- string with no tenant_super_admin branch -- no org_manager/tenant_super_admin ever received
-- an invoice due-date reminder. CREATE OR REPLACE with the only line changed (the role check);
-- rest of the function body is unchanged from 20260717000001...sql:60-159.

BEGIN;

CREATE OR REPLACE FUNCTION public.send_due_date_reminders()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_setting RECORD;
  v_profile RECORD;
  v_invoice RECORD;
BEGIN
  FOR v_setting IN
    SELECT user_id, organization_id, reminder_days
    FROM public.invoice_reminder_settings
    WHERE enabled = true
  LOOP
    SELECT role, organization_id, brand_id, location_id
      INTO v_profile
    FROM public.profiles
    WHERE id = v_setting.user_id
      AND deleted_at IS NULL;

    IF v_profile.role IS NULL THEN
      CONTINUE;
    END IF;

    FOR v_invoice IN
      SELECT i.id, i.due_date, (i.due_date - CURRENT_DATE) AS days_out
      FROM public.invoices i
      WHERE i.deleted_at IS NULL
        AND i.organization_id = v_setting.organization_id
        AND COALESCE(i.payment_status, 'unpaid') NOT IN ('paid', 'auto_pay')
        AND i.due_date IS NOT NULL
        AND (i.due_date - CURRENT_DATE) = ANY(v_setting.reminder_days)
        AND (
          v_profile.role IN ('org_manager', 'tenant_super_admin', 'platform_admin')
          OR (
            v_profile.role = 'branch_manager'
            AND (
              i.brand_id = v_profile.brand_id
              OR i.location_id IN (SELECT l.id FROM public.locations l WHERE l.brand_id = v_profile.brand_id)
            )
          )
          OR (
            v_profile.role IN ('location_manager', 'ground_staff')
            AND i.location_id = v_profile.location_id
          )
        )
    LOOP
      INSERT INTO public.invoice_reminder_log (invoice_id, user_id, reminder_day)
      VALUES (v_invoice.id, v_setting.user_id, v_invoice.days_out)
      ON CONFLICT (invoice_id, user_id, reminder_day) DO NOTHING;

      IF FOUND THEN
        INSERT INTO public.notifications (user_id, organization_id, type, title, message, is_read, metadata)
        VALUES (
          v_setting.user_id,
          v_setting.organization_id,
          'invoice',
          CASE WHEN v_invoice.days_out <= 0 THEN 'Invoice overdue' ELSE 'Invoice due soon' END,
          CASE WHEN v_invoice.days_out <= 0
            THEN format('An invoice was due on %s and is still unpaid.', to_char(v_invoice.due_date, 'Mon DD, YYYY'))
            ELSE format('An invoice is due in %s day%s (%s).', v_invoice.days_out, CASE WHEN v_invoice.days_out = 1 THEN '' ELSE 's' END, to_char(v_invoice.due_date, 'Mon DD, YYYY'))
          END,
          false,
          jsonb_build_object('invoice_id', v_invoice.id, 'due_in_days', v_invoice.days_out)
        );
      END IF;
    END LOOP;
  END LOOP;

  -- Trigger the email side (plain SQL can't call Resend). Same secure-dispatch pattern as
  -- dispatch_webhook_queue(): read the functions URL/service key from
  -- private.workflow_runtime_settings rather than hardcoding credentials in this function.
  DECLARE
    v_functions_url text;
    v_service_role_key text;
    v_url text;
  BEGIN
    SELECT setting_value INTO v_functions_url FROM private.workflow_runtime_settings WHERE setting_name = 'functions_url';
    SELECT setting_value INTO v_service_role_key FROM private.workflow_runtime_settings WHERE setting_name = 'service_role_key';

    IF v_service_role_key IS NOT NULL AND length(trim(v_service_role_key)) > 0 THEN
      v_url := COALESCE(NULLIF(trim(v_functions_url), ''), 'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1') || '/send-due-date-reminder-emails';

      PERFORM net.http_post(
        url := v_url,
        body := '{}'::jsonb,
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || v_service_role_key
        )
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Notifications already landed above; a failure to trigger the email side is non-fatal.
    NULL;
  END;
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260719000001_fix_business_verification_review_actions.sql
-- ==========================================================================

-- Fixes two onboarding review bugs found in an end-to-end trace of the tenant onboarding flow:
--
-- 1. request_onboarding_more_info() set business_verifications.verification_status and
--    profiles.business_verification_status to 'pending_review' -- the exact value
--    BusinessVerification.jsx treats as a dead-end "wait for admin, you're logged out" screen
--    (see App.jsx needsBusinessVerification / BusinessVerification.jsx status handling). A
--    tenant asked for more info could never see an editable form again. Fix: reuse the
--    existing 'failed' status (same value reject_business_verification already uses) so the
--    tenant lands back on an editable, resubmittable business-verification form. Only
--    approve_business_verification (unchanged) can ever set 'verified' and unlock hierarchy
--    setup. Reject and Request Info remain distinct admin-facing actions/audit entries
--    (onboarding_admin_actions.action, business_verifications.metadata reason key) but now
--    share the same tenant-facing effect.
--
-- 2. Both reject_business_verification() and request_onboarding_more_info() each insert their
--    own row into public.notifications *and* the business_verifications status UPDATE fires
--    trigger notify_business_verification_review_state() (which inserts its own notification
--    for the tenant, plus one per platform_admin) whenever the new status is 'pending_review'
--    or 'failed'. That produced two near-identical in-app notifications per action. Fix: drop
--    the direct notifications insert from both RPCs and rely solely on the trigger (single
--    writer for tenant-facing status-change notifications). approve_business_verification's
--    own insert is untouched -- the trigger explicitly skips 'verified'.
--
-- Also extends get_my_business_verification_draft() to return the latest rejection reason so
-- BusinessVerification.jsx can show the tenant what to fix (previously it only returned the
-- draft form payload, current step, and onboarding_status -- nothing about *why* they were
-- sent back).

BEGIN;

CREATE OR REPLACE FUNCTION public.reject_business_verification(p_user_id uuid, p_reason text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_actor UUID := auth.uid();
  v_run_id UUID;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A rejection reason is required';
  END IF;

  UPDATE public.business_verifications
  SET verification_status = 'failed',
      rejection_reason = p_reason,
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('admin_reason', p_reason),
      updated_at = now()
  WHERE id = (
    SELECT id FROM public.business_verifications
    WHERE user_id = p_user_id
    ORDER BY created_at DESC
    LIMIT 1
  );

  UPDATE public.profiles
  SET business_verification_status = 'failed',
      onboarding_status = 'blocked',
      onboarding_current_step = 'business_verification',
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.onboarding_admin_actions(actor_user_id, target_user_id, action, reason)
  VALUES (v_actor, p_user_id, 'reject_business_verification', p_reason);

  -- Notification is handled by trg_notify_business_verification_review_state (fires on the
  -- verification_status UPDATE above) -- do not insert one here too, or the tenant gets two.

  v_run_id := public.get_or_create_onboarding_run(p_user_id);
  PERFORM public.record_onboarding_event(v_run_id, p_user_id, 'business_verification', 'admin_rejected', 'failed', jsonb_build_object('actor_user_id', v_actor, 'reason', p_reason));

  RETURN jsonb_build_object('success', true, 'status', 'failed');
END;
$function$;

CREATE OR REPLACE FUNCTION public.request_onboarding_more_info(p_user_id uuid, p_reason text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_actor UUID := auth.uid();
  v_run_id UUID;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  UPDATE public.business_verifications
  SET verification_status = 'failed',
      rejection_reason = p_reason,
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('more_info_reason', p_reason),
      updated_at = now()
  WHERE id = (
    SELECT id FROM public.business_verifications
    WHERE user_id = p_user_id
    ORDER BY created_at DESC
    LIMIT 1
  );

  UPDATE public.profiles
  SET business_verification_status = 'failed',
      onboarding_status = 'blocked',
      onboarding_current_step = 'business_verification',
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.onboarding_admin_actions(actor_user_id, target_user_id, action, reason)
  VALUES (v_actor, p_user_id, 'request_more_info', p_reason);

  -- Notification is handled by trg_notify_business_verification_review_state (fires on the
  -- verification_status UPDATE above) -- do not insert one here too, or the tenant gets two.

  v_run_id := public.get_or_create_onboarding_run(p_user_id);
  PERFORM public.record_onboarding_event(v_run_id, p_user_id, 'business_verification', 'more_info_requested', 'failed', jsonb_build_object('actor_user_id', v_actor, 'reason', p_reason));

  RETURN jsonb_build_object('success', true, 'status', 'failed');
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_business_verification_draft()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_profile RECORD;
  v_verification RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT onboarding_draft, onboarding_current_step, onboarding_status, business_verification_status
  INTO v_profile
  FROM public.profiles
  WHERE id = auth.uid();

  SELECT rejection_reason, metadata
  INTO v_verification
  FROM public.business_verifications
  WHERE user_id = auth.uid()
  ORDER BY created_at DESC
  LIMIT 1;

  RETURN jsonb_build_object(
    'draft', COALESCE(v_profile.onboarding_draft, '{}'::jsonb),
    'current_step', v_profile.onboarding_current_step,
    'status', v_profile.onboarding_status,
    'business_verification_status', v_profile.business_verification_status,
    'rejection_reason', v_verification.rejection_reason,
    'more_info_reason', v_verification.metadata->>'more_info_reason'
  );
END;
$function$;

COMMIT;

-- ==========================================================================
-- Source: 20260719000002_banking_onboarding_completed.sql
-- ==========================================================================

-- Adds a post-hierarchy "Complete Onboarding" step: the org's own operating bank account for
-- AP/vendor bill-pay (Dwolla-vaulted, via the existing onboarding_bank_accounts /
-- tenant_payment_authorizations infra from 20260706000001) -- separate from payment_verified,
-- which only means "the RestOps subscription has a payment method" and is required BEFORE
-- setup_onboarding_hierarchy runs. banking_onboarding_completed is required AFTER hierarchy
-- setup, unrelated to how the tenant pays RestOps.
--
-- Non-negotiable: this column defaults false, is never backfilled, and is never touched by
-- signup/business-verification/subscription-payment/hierarchy-setup flows. The ONLY writer is
-- capture_tenant_payment_signature(), and only after it verifies (a) the bank account belongs
-- to the caller and is in a signable state, (b) the signature/consent row was written and the
-- account marked authorized, (c) the billing address is valid -- including, when
-- billing_address_source = 'custom', that all custom address fields (line1/city/state/
-- postal_code/country; line2 optional) are present.

BEGIN;

ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS banking_onboarding_completed BOOLEAN NOT NULL DEFAULT false;

ALTER TABLE public.onboarding_bank_accounts
  ADD COLUMN IF NOT EXISTS billing_address_line1 TEXT,
  ADD COLUMN IF NOT EXISTS billing_address_line2 TEXT,
  ADD COLUMN IF NOT EXISTS billing_address_city TEXT,
  ADD COLUMN IF NOT EXISTS billing_address_state TEXT,
  ADD COLUMN IF NOT EXISTS billing_address_postal_code TEXT,
  ADD COLUMN IF NOT EXISTS billing_address_country TEXT;

ALTER TABLE public.onboarding_bank_accounts
  DROP CONSTRAINT IF EXISTS onboarding_bank_accounts_billing_address_source_check;
ALTER TABLE public.onboarding_bank_accounts
  ADD CONSTRAINT onboarding_bank_accounts_billing_address_source_check
  CHECK (billing_address_source = ANY (ARRAY['business'::text, 'mailing'::text, 'service'::text, 'custom'::text]));

CREATE OR REPLACE FUNCTION public.submit_onboarding_bank_account(p_payload jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_bank_id UUID;
  v_run_id UUID;
  v_account_number TEXT;
  v_routing_number TEXT;
  v_is_default BOOLEAN;
  v_billing_source TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  v_account_number := regexp_replace(COALESCE(p_payload->>'account_number', ''), '[^0-9]', '', 'g');
  v_routing_number := regexp_replace(COALESCE(p_payload->>'routing_number', ''), '[^0-9]', '', 'g');
  v_is_default := COALESCE((p_payload->>'is_default')::boolean, false)
    OR NOT EXISTS (
      SELECT 1 FROM public.onboarding_bank_accounts
      WHERE user_id = v_user_id AND status <> 'inactive'
    );
  v_billing_source := COALESCE(NULLIF(p_payload->>'billing_address_source', ''), 'business');

  IF NULLIF(btrim(COALESCE(p_payload->>'bank_name', '')), '') IS NULL THEN
    RAISE EXCEPTION 'Bank name is required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_payload->>'account_holder_name', '')), '') IS NULL THEN
    RAISE EXCEPTION 'Account holder name is required';
  END IF;

  IF COALESCE(p_payload->>'account_type', '') NOT IN ('checking', 'savings') THEN
    RAISE EXCEPTION 'Account type must be checking or savings';
  END IF;

  IF length(v_routing_number) <> 9 THEN
    RAISE EXCEPTION 'Routing number must be 9 digits';
  END IF;

  IF length(v_account_number) < 4 OR length(v_account_number) > 17 THEN
    RAISE EXCEPTION 'Account number must be between 4 and 17 digits';
  END IF;

  IF v_is_default THEN
    UPDATE public.onboarding_bank_accounts
    SET is_default = false
    WHERE user_id = v_user_id AND status <> 'inactive';
  END IF;

  INSERT INTO public.onboarding_bank_accounts (
    user_id,
    bank_name,
    account_holder_name,
    account_type,
    nickname,
    routing_number_last4,
    account_number_last4,
    billing_address_source,
    billing_address_line1,
    billing_address_line2,
    billing_address_city,
    billing_address_state,
    billing_address_postal_code,
    billing_address_country,
    is_default,
    status,
    metadata
  )
  VALUES (
    v_user_id,
    btrim(p_payload->>'bank_name'),
    btrim(p_payload->>'account_holder_name'),
    p_payload->>'account_type',
    NULLIF(btrim(COALESCE(p_payload->>'nickname', '')), ''),
    right(v_routing_number, 4),
    right(v_account_number, 4),
    v_billing_source,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_line1', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_line2', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_city', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_state', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_postal_code', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_country', '')), '') END,
    v_is_default,
    'pending_signature',
    COALESCE(p_payload->'metadata', '{}'::jsonb)
  )
  RETURNING id INTO v_bank_id;

  PERFORM public.store_onboarding_bank_secret(v_bank_id, v_account_number, v_routing_number);

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'bank_authorization',
    'bank_account_submitted',
    'pending_signature',
    jsonb_build_object('onboarding_bank_account_id', v_bank_id)
  );

  RETURN (
    SELECT jsonb_build_object(
      'success', true,
      'bank_account', jsonb_build_object(
        'id', id,
        'bank_name', bank_name,
        'account_holder_name', account_holder_name,
        'account_type', account_type,
        'nickname', nickname,
        'routing_number_last4', routing_number_last4,
        'account_number_last4', account_number_last4,
        'billing_address_source', billing_address_source,
        'is_default', is_default,
        'status', status
      )
    )
    FROM public.onboarding_bank_accounts
    WHERE id = v_bank_id
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.capture_tenant_payment_signature(
  p_bank_account_id uuid,
  p_signer_full_name text,
  p_signer_title text,
  p_consent_version text,
  p_consent_text text,
  p_signature_sha256 text,
  p_signature_payload jsonb DEFAULT '{}'::jsonb,
  p_signature_storage_path text DEFAULT NULL::text,
  p_user_agent text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_auth_id UUID;
  v_run_id UUID;
  v_account public.onboarding_bank_accounts%ROWTYPE;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT *
  INTO v_account
  FROM public.onboarding_bank_accounts
  WHERE id = p_bank_account_id AND user_id = v_user_id AND status <> 'inactive';

  IF v_account.id IS NULL THEN
    RAISE EXCEPTION 'Bank account not found';
  END IF;

  IF NULLIF(btrim(COALESCE(p_signer_full_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Signer full name is required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_signature_sha256, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Signature hash is required';
  END IF;

  IF v_account.billing_address_source = 'custom' THEN
    IF NULLIF(btrim(v_account.billing_address_line1), '') IS NULL
       OR NULLIF(btrim(v_account.billing_address_city), '') IS NULL
       OR NULLIF(btrim(v_account.billing_address_state), '') IS NULL
       OR NULLIF(btrim(v_account.billing_address_postal_code), '') IS NULL
       OR NULLIF(btrim(v_account.billing_address_country), '') IS NULL THEN
      RAISE EXCEPTION 'A complete custom billing address (line 1, city, state, postal code, country) is required';
    END IF;
  END IF;

  UPDATE public.tenant_payment_authorizations
  SET status = 'revoked',
      updated_at = now()
  WHERE onboarding_bank_account_id = p_bank_account_id
    AND user_id = v_user_id
    AND status = 'active';

  INSERT INTO public.tenant_payment_authorizations (
    user_id,
    onboarding_bank_account_id,
    signer_full_name,
    signer_title,
    consent_version,
    consent_text,
    consent_accepted,
    signature_storage_path,
    signature_sha256,
    signature_payload,
    user_agent,
    status
  )
  VALUES (
    v_user_id,
    p_bank_account_id,
    btrim(p_signer_full_name),
    NULLIF(btrim(COALESCE(p_signer_title, '')), ''),
    COALESCE(NULLIF(btrim(p_consent_version), ''), 'tenant-bank-authorization-v1'),
    p_consent_text,
    true,
    NULLIF(btrim(COALESCE(p_signature_storage_path, '')), ''),
    btrim(p_signature_sha256),
    COALESCE(p_signature_payload, '{}'::jsonb),
    NULLIF(btrim(COALESCE(p_user_agent, '')), ''),
    'active'
  )
  RETURNING id INTO v_auth_id;

  UPDATE public.onboarding_bank_accounts
  SET status = 'authorized'
  WHERE id = p_bank_account_id;

  UPDATE public.profiles
  SET banking_onboarding_completed = true,
      updated_at = now()
  WHERE id = v_user_id;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'bank_authorization',
    'signature_captured',
    'authorized',
    jsonb_build_object('onboarding_bank_account_id', p_bank_account_id, 'authorization_id', v_auth_id)
  );

  RETURN jsonb_build_object(
    'success', true,
    'authorization_id', v_auth_id,
    'bank_account_id', p_bank_account_id,
    'status', 'authorized'
  );
END;
$function$;

COMMIT;

-- ==========================================================================
-- Source: 20260719000003_drop_dead_preferred_vendor_id.sql
-- ==========================================================================

-- 20260719000003: Drop products.preferred_vendor_id
--
-- Dead column: defined in 001_initial_schema.sql, never read or written by any app code,
-- edge function, or RPC (confirmed by full-repo grep). The real product<->vendor bridge is
-- vendor_items + vendor_item_mappings (081_vendor_item_matching.sql), which supports a
-- product being sourced from multiple vendors -- a single preferred_vendor_id FK can't model
-- that and nothing in the app ever populated it.

BEGIN;

ALTER TABLE public.products DROP COLUMN IF EXISTS preferred_vendor_id;

COMMIT;

-- ==========================================================================
-- Source: 20260719000004_register_invoice_document.sql
-- ==========================================================================

-- 20260719000004: register_invoice_document / attach_invoice_document
--
-- Closes tracker items 2.1 (invoice_documents is defined but nothing ever writes to it) and
-- 2.4 (file-upload-to-storage logic is duplicated across 3 upload paths) with a single shared
-- entry point instead of fixing them separately and then consolidating.
--
-- The three upload paths differ in whether an invoice row exists yet at upload time:
--   - InvoiceUploader.jsx: usually has a draft invoice id already (onCreateUploadDraft runs
--     before the storage upload).
--   - MobileReceiptCapture.jsx: no invoice id yet at upload time (invoice is created after,
--     from the extracted data).
--   - process-email-invoices/index.ts: no invoice id yet either -- it exists once
--     ingest_email_invoice runs, immediately after upload, inside the same edge function call.
--
-- invoice_documents.invoice_id is nullable and its RLS insert policy (invoice_child_writable)
-- already falls back to an org-level check when invoice_id is NULL, so register_invoice_document
-- can record the file the moment it lands in storage, and attach_invoice_document links it to
-- the invoice once one exists -- no path has to wait on the other.

BEGIN;

CREATE OR REPLACE FUNCTION public.register_invoice_document(
  p_storage_path text,
  p_file_name text,
  p_file_type text DEFAULT NULL,
  p_file_size bigint DEFAULT NULL,
  p_file_hash text DEFAULT NULL,
  p_source text DEFAULT 'upload',
  p_invoice_id uuid DEFAULT NULL,
  p_organization_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_org_id uuid;
  v_document_id uuid;
BEGIN
  v_org_id := COALESCE(p_organization_id, public.get_my_org());

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  PERFORM public.assert_org_actor(v_org_id);

  IF p_storage_path IS NULL OR p_file_name IS NULL THEN
    RAISE EXCEPTION 'storage_path and file_name are required';
  END IF;

  INSERT INTO public.invoice_documents (
    organization_id, invoice_id, storage_path, file_name, file_type, file_size, file_hash, source, created_by
  ) VALUES (
    v_org_id, p_invoice_id, p_storage_path, p_file_name, p_file_type, p_file_size, p_file_hash, p_source, auth.uid()
  )
  RETURNING id INTO v_document_id;

  RETURN v_document_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.attach_invoice_document(
  p_document_id uuid,
  p_invoice_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_doc public.invoice_documents%ROWTYPE;
BEGIN
  SELECT * INTO v_doc FROM public.invoice_documents WHERE id = p_document_id;

  IF v_doc.id IS NULL THEN
    RAISE EXCEPTION 'Document not found';
  END IF;

  PERFORM public.assert_org_actor(v_doc.organization_id);

  UPDATE public.invoice_documents
  SET invoice_id = p_invoice_id, updated_at = now()
  WHERE id = p_document_id;
END;
$$;

REVOKE ALL ON FUNCTION public.register_invoice_document(text, text, text, bigint, text, text, uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.register_invoice_document(text, text, text, bigint, text, text, uuid, uuid) TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.attach_invoice_document(uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.attach_invoice_document(uuid, uuid) TO authenticated, service_role;

COMMIT;

-- ==========================================================================
-- Source: 20260719000005_find_duplicate_invoice_documents.sql
-- ==========================================================================

-- 20260719000005: find_duplicate_invoice_documents
--
-- Closes tracker item 5.2: file_hash on invoice_documents (080_invoice_document_intake.sql) has
-- existed since that migration but nothing ever computed or checked it -- duplicate detection
-- only happened at approval time (ValidationDialog.jsx's server-side query), never at upload
-- time. Since 20260719000004_register_invoice_document.sql now has every upload path computing
-- a real SHA-256 file_hash, this migration adds the lookup the frontend needs to warn the user
-- BEFORE the upload is saved, not after it's already gone through extraction and review.

BEGIN;

CREATE OR REPLACE FUNCTION public.find_duplicate_invoice_documents(
  p_organization_id uuid,
  p_file_hash text
)
RETURNS TABLE (
  document_id uuid,
  invoice_id uuid,
  vendor_name text,
  invoice_number text,
  invoice_date date,
  status text,
  uploaded_at timestamptz
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_org_id uuid;
BEGIN
  v_org_id := COALESCE(p_organization_id, public.get_my_org());

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  PERFORM public.assert_org_actor(v_org_id);

  IF p_file_hash IS NULL OR p_file_hash = '' THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    d.id,
    d.invoice_id,
    i.vendor_name,
    i.invoice_number,
    i.invoice_date,
    i.status,
    d.created_at
  FROM public.invoice_documents d
  LEFT JOIN public.invoices i ON i.id = d.invoice_id
  WHERE d.organization_id = v_org_id
    AND d.file_hash = p_file_hash
    AND (i.id IS NULL OR i.deleted_at IS NULL)
  ORDER BY d.created_at DESC;
END;
$$;

REVOKE ALL ON FUNCTION public.find_duplicate_invoice_documents(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.find_duplicate_invoice_documents(uuid, text) TO authenticated, service_role;

COMMIT;

-- ==========================================================================
-- Source: 20260719000006_unlimited_approval_flag.sql
-- ==========================================================================

-- 20260719000006: has_unlimited_approval flag
--
-- Closes tracker item 8.1: "Branch Manager and Location Manager need unlimited approval
-- option" / "Keep unlimited amount approval enabled for Branch Manager and Location Manager."
--
-- Today NULL invoice_approval_limit always blocks approval (approve_invoice_with_limit:
-- `v_user_limit IS NULL OR v_amount > v_user_limit`), for every role including the ones
-- granting the limits in the first place -- there's no way to mark someone as "unlimited" at
-- all, NULL just means "can't approve anything." This adds an explicit opt-in flag instead of
-- overloading NULL, so a numeric fallback ceiling can still be kept on file for if/when
-- unlimited is later revoked.
--
-- The flag is granted through the exact same update_user_approval_limit cascade rules already
-- enforced (org_manager -> branch_manager; branch_manager -> location_manager within their
-- brand; platform_admin/tenant_super_admin -> broader) -- no new authorization logic, just an
-- extra field on the same already-authorized write.

BEGIN;

ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS has_unlimited_approval boolean NOT NULL DEFAULT false;

-- Adding a 3rd parameter creates a new overload rather than replacing the function -- drop the
-- old 2-arg signature explicitly (this repo has been bitten by stale overloads before, see
-- 20260624000020_drop_stale_release_invoice_funds_overload.sql /
-- 20260625000016_drop_stale_tenant_backfill_overload.sql).
DROP FUNCTION IF EXISTS public.update_user_approval_limit(uuid, numeric);

CREATE OR REPLACE FUNCTION public.update_user_approval_limit(
  target_user_id uuid,
  new_limit numeric,
  p_unlimited boolean DEFAULT false
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_actor record;
  v_target record;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF target_user_id IS NULL THEN
    RAISE EXCEPTION 'Target user is required';
  END IF;

  IF new_limit IS NULL OR new_limit < 0 THEN
    RAISE EXCEPTION 'Approval limit must be non-negative';
  END IF;

  IF target_user_id = v_actor_id THEN
    RAISE EXCEPTION 'Users cannot set their own approval limit';
  END IF;

  SELECT id, role, organization_id, tenant_id, brand_id, location_id,
         COALESCE(invoice_approval_limit, 0) AS invoice_approval_limit
    INTO v_actor
  FROM public.profiles
  WHERE id = v_actor_id
    AND deleted_at IS NULL;

  SELECT id, role, organization_id, tenant_id, brand_id, location_id
    INTO v_target
  FROM public.profiles
  WHERE id = target_user_id
    AND deleted_at IS NULL;

  IF v_actor.id IS NULL THEN
    RAISE EXCEPTION 'Actor profile not found';
  END IF;

  IF v_target.id IS NULL THEN
    RAISE EXCEPTION 'Target profile not found';
  END IF;

  IF v_actor.role <> 'platform_admin'
    AND v_actor.role <> 'tenant_super_admin'
    AND v_actor.organization_id IS DISTINCT FROM v_target.organization_id THEN
    RAISE EXCEPTION 'Cannot set approval limit outside your organization';
  END IF;

  IF v_actor.role = 'tenant_super_admin'
    AND v_actor.tenant_id IS DISTINCT FROM v_target.tenant_id THEN
    RAISE EXCEPTION 'Cannot set approval limit outside your tenant';
  END IF;

  IF v_actor.role NOT IN ('platform_admin', 'tenant_super_admin')
    AND new_limit > v_actor.invoice_approval_limit THEN
    RAISE EXCEPTION 'Cannot grant approval limit % above your own limit %',
      new_limit, v_actor.invoice_approval_limit;
  END IF;

  IF v_actor.role = 'platform_admin' THEN
    IF v_target.role = 'platform_admin' THEN
      RAISE EXCEPTION 'Platform admins cannot set peer platform admin limits';
    END IF;
  ELSIF v_actor.role = 'tenant_super_admin' THEN
    IF v_target.role = 'tenant_super_admin' THEN
      RAISE EXCEPTION 'Tenant super admins cannot set peer limits';
    END IF;
  ELSIF v_actor.role = 'org_manager' THEN
    IF v_target.role <> 'branch_manager' THEN
      RAISE EXCEPTION 'Org managers may only set branch manager approval limits';
    END IF;
  ELSIF v_actor.role = 'branch_manager' THEN
    IF v_target.role <> 'location_manager' THEN
      RAISE EXCEPTION 'Branch managers may only set location manager approval limits';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.get_my_accessible_brand_ids() b(id)
      WHERE b.id = COALESCE(
        v_target.brand_id,
        (SELECT l.brand_id FROM public.locations l WHERE l.id = v_target.location_id)
      )
    ) THEN
      RAISE EXCEPTION 'Target user is outside your brand scope';
    END IF;
  ELSE
    RAISE EXCEPTION 'Insufficient role to set approval limits';
  END IF;

  UPDATE public.profiles
     SET invoice_approval_limit = new_limit,
         has_unlimited_approval = p_unlimited,
         updated_at = now()
   WHERE id = target_user_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.approve_invoice_with_limit(p_invoice_id uuid, p_user_id uuid, p_amount numeric)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_limit numeric;
  v_has_unlimited boolean;
  v_invoice public.invoices%ROWTYPE;
  v_amount numeric;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Approval user must match the authenticated user';
  END IF;

  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_can_approve_invoice_scope(
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id
  );

  SELECT invoice_approval_limit, COALESCE(has_unlimited_approval, false)
    INTO v_user_limit, v_has_unlimited
  FROM public.profiles
  WHERE id = p_user_id
    AND deleted_at IS NULL;

  v_amount := COALESCE(p_amount, v_invoice.total_amount, 0);

  IF NOT v_has_unlimited AND (v_user_limit IS NULL OR v_amount > v_user_limit) THEN
    RAISE EXCEPTION 'Approval limit exceeded. Your limit is $%, but the invoice is $%.',
      COALESCE(v_user_limit, 0), v_amount;
  END IF;

  UPDATE public.invoices
     SET status = 'approved',
         ap_status = 'approved',
         approved_by = auth.uid(),
         approved_date = now(),
         updated_at = now()
   WHERE id = p_invoice_id;

  -- Sync products right after approval
  PERFORM public.sync_invoice_products(p_invoice_id);

  RETURN jsonb_build_object('success', true, 'message', 'Invoice approved successfully');
END;
$$;

REVOKE ALL ON FUNCTION public.update_user_approval_limit(uuid, numeric, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.update_user_approval_limit(uuid, numeric, boolean) TO authenticated, service_role;

COMMIT;

-- ==========================================================================
-- Source: 20260719000007_invoice_audit_events_ip_user_agent.sql
-- ==========================================================================

-- 20260719000007: invoice_audit_events.ip_address / user_agent
--
-- Closes the schema-parity half of tracker item 9.7: audit_logs already has ip_address/
-- user_agent (006_saas_billing_and_audit.sql, extended 015_create_error_logs_and_audit_
-- hardening.sql) but invoice_audit_events never got them.
--
-- Note on what this can and can't capture: invoice_audit_events is currently written to by
-- exactly one path -- the trigger_invoice_status_audit trigger firing on invoices UPDATE
-- (086_invoice_audit_events.sql) -- which has no HTTP request context to draw a real IP or
-- user-agent from (it's a plain DB trigger, not a request handler). Adding the columns here
-- is for schema parity and to leave room for a future direct caller of
-- log_invoice_audit_event(); it does NOT fabricate values for the trigger path, which is the
-- honest answer for that path today.

BEGIN;

ALTER TABLE public.invoice_audit_events ADD COLUMN IF NOT EXISTS ip_address text;
ALTER TABLE public.invoice_audit_events ADD COLUMN IF NOT EXISTS user_agent text;

COMMIT;

-- ==========================================================================
-- Source: 20260719000008_restrict_autopay_invoice_approval.sql
-- ==========================================================================

-- 20260719000008: Restrict AutoPay invoice approval
--
-- Closes tracker item 12.8: "Auto Pay invoice approval should be restricted" / "Only Super
-- User can approve Auto Pay invoices." No "Super User" role exists in this app's vocabulary
-- (ground_staff/location_manager/branch_manager/brand_manager/org_manager/tenant_super_admin/
-- platform_admin); is_owner_or_admin() (org_manager, tenant_super_admin, platform_admin) is
-- the existing org-level-and-above tier and matches the tracker's intent of a higher bar than
-- ordinary invoice approval.
--
-- enforce_invoice_approval_authorization (20260628000005_secure_approval_primitives.sql) is
-- the single trigger every approval path already routes through (approve_invoice_with_limit,
-- bulk_process_invoices, or any future direct UPDATE) -- adding the AutoPay check here, next
-- to the existing scope check, means every path gets it for free instead of patching each
-- approval RPC separately.

BEGIN;

CREATE OR REPLACE FUNCTION public.enforce_invoice_approval_authorization()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_vendor_autopay boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'approved' OR NEW.ap_status = 'approved' THEN
      PERFORM public.assert_can_approve_invoice_scope(
        NEW.organization_id,
        NEW.brand_id,
        NEW.location_id
      );

      SELECT autopay_enabled INTO v_vendor_autopay FROM public.vendors WHERE id = NEW.vendor_id;
      IF v_vendor_autopay AND NOT public.is_owner_or_admin() THEN
        RAISE EXCEPTION 'AutoPay invoice approval requires an org manager, tenant super admin, or platform admin';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF (NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved')
    OR (NEW.ap_status = 'approved' AND OLD.ap_status IS DISTINCT FROM 'approved') THEN
    PERFORM public.assert_can_approve_invoice_scope(
      NEW.organization_id,
      NEW.brand_id,
      NEW.location_id
    );

    SELECT autopay_enabled INTO v_vendor_autopay FROM public.vendors WHERE id = NEW.vendor_id;
    IF v_vendor_autopay AND NOT public.is_owner_or_admin() THEN
      RAISE EXCEPTION 'AutoPay invoice approval requires an org manager, tenant super admin, or platform admin';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260719000009_org_remove_member_audit_log.sql
-- ==========================================================================

-- 20260719000009: org_remove_member writes an audit log entry
--
-- Closes tracker item 16.3: org_remove_member (20260709000002_fix_legacy_roles_in_access_
-- functions.sql) detaches org/brand/location membership and resets the target's role to
-- ground_staff, but writes no audit trail at all -- unlike admin_delete_user, which archives
-- the removed user's details to archived_users before deleting.
--
-- Decision made during planning: keep the detach-and-reset behavior as-is (a hard delete at
-- the org level isn't warranted here -- this repo's data-integrity rule is soft-delete-only,
-- and admin_delete_user's actual account deletion is deliberately reserved for platform_admin
-- only). The fix is just to make the action leave a record, reusing the existing common
-- audit_logs / log_audit_event path (the same one 9.9 will later route invoice_audit_events
-- through) instead of inventing a bespoke insert.

BEGIN;

-- Found while testing this change: trg_protect_profile_security_columns (a BEFORE UPDATE
-- trigger on profiles) unconditionally blocks any change to role/organization_id/brand_id/
-- location_id whenever current_setting('role') = 'authenticated' or 'anon'. That GUC reflects
-- the connection-level Postgres role PostgREST sets for the whole request -- it does NOT
-- change when execution enters a SECURITY DEFINER function, so this trigger cannot tell "a
-- client updating its own row" apart from "an already-authorized admin RPC updating someone
-- else's row". In practice this means org_remove_member's own detach-and-reset UPDATE has
-- never actually succeeded when called by a real authenticated user -- not just missing an
-- audit log, its core job has been broken. (Grepping prosrc turned up 7 other functions
-- touching these same columns -- setup_organization_full, admin_update_user_role,
-- complete_onboarding, accept_invitation, setup_onboarding_hierarchy, switch_user_context,
-- and this one -- flagged separately for the user to check; only org_remove_member is fixed
-- here, in scope for this change.)
--
-- Fix: a transaction-local trusted-context flag a SECURITY DEFINER function can set right
-- before its own already-authorized write, instead of loosening the trigger's blanket rule.
CREATE OR REPLACE FUNCTION public.protect_profile_security_columns()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO ''
AS $$
BEGIN
  IF NEW.role IS DISTINCT FROM OLD.role OR
     NEW.organization_id IS DISTINCT FROM OLD.organization_id OR
     NEW.brand_id IS DISTINCT FROM OLD.brand_id OR
     NEW.location_id IS DISTINCT FROM OLD.location_id THEN

    IF current_setting('role') IN ('authenticated', 'anon')
       AND current_setting('app.trusted_profile_write', true) IS DISTINCT FROM 'on' THEN
       RAISE EXCEPTION '42501: Privilege escalation attempt detected. You cannot modify your own role or organization bindings.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.org_remove_member(
  target_user_id uuid,
  target_org_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  caller_role TEXT;
  caller_org  UUID;
BEGIN
  caller_role := public.get_auth_role();
  caller_org  := COALESCE(target_org_id, public.get_auth_org());

  IF caller_role NOT IN ('org_manager', 'tenant_super_admin', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: only org_manager, tenant_super_admin, or platform_admin can remove users';
  END IF;

  IF target_user_id = auth.uid() THEN
    RAISE EXCEPTION 'You cannot remove yourself. Transfer ownership first.';
  END IF;

  -- Remove from organization_members
  DELETE FROM public.organization_members
  WHERE user_id = target_user_id AND organization_id = caller_org;

  -- Remove from brand_members for this org
  DELETE FROM public.brand_members
  WHERE user_id = target_user_id
    AND brand_id IN (SELECT id FROM public.brands WHERE organization_id = caller_org);

  -- Remove from location_members for this org
  DELETE FROM public.location_members
  WHERE user_id = target_user_id
    AND location_id IN (SELECT id FROM public.locations WHERE organization_id = caller_org);

  -- Update profiles if this was their active org
  PERFORM set_config('app.trusted_profile_write', 'on', true);
  UPDATE public.profiles
  SET organization_id = NULL, brand_id = NULL, location_id = NULL, role = 'ground_staff'
  WHERE id = target_user_id AND organization_id = caller_org;

  -- Update app_metadata if this is their active context
  IF (SELECT raw_app_meta_data->>'organization_id' FROM auth.users WHERE id = target_user_id) = caller_org::text THEN
      UPDATE auth.users
      SET raw_app_meta_data = raw_app_meta_data - 'organization_id' - 'role' - 'brand_id' - 'location_id'
      WHERE id = target_user_id;
  END IF;

  PERFORM public.log_audit_event(jsonb_build_object(
    'organization_id', caller_org,
    'user_id', auth.uid(),
    'action', 'org_member_removed',
    'table_name', 'organization_members',
    'entity_type', 'user',
    'entity_id', target_user_id::text,
    'record_id', target_user_id::text,
    'details', jsonb_build_object('removed_user_id', target_user_id, 'removed_from_org', caller_org)
  ));

  RETURN jsonb_build_object('success', true);
END;
$$;

-- Found while testing this change: org_remove_member had NO execute grant for any
-- non-superuser role at all (not authenticated, not service_role) -- Postgres silently drops
-- the implicit PUBLIC default the moment any explicit GRANT/REVOKE ever touches a function,
-- and nothing in this function's migration history (042_org_member_management_rpcs.sql,
-- 128_fix_lint_errors.sql, 20260709000002_fix_legacy_roles_in_access_functions.sql) ever
-- re-granted it. This was a pre-existing bug -- nobody could actually call this RPC before
-- now. Matches CLAUDE.md's own "Prod != local on grants" warning.
REVOKE ALL ON FUNCTION public.org_remove_member(uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.org_remove_member(uuid, uuid) TO authenticated;

COMMIT;

-- ==========================================================================
-- Source: 20260719000010_trusted_profile_write_remaining_functions.sql
-- ==========================================================================

-- 20260719000010: Extend the trusted-profile-write bypass to the remaining functions
-- affected by trg_protect_profile_security_columns
--
-- 20260719000009 found that trg_protect_profile_security_columns blocks any authenticated-
-- role write to profiles.role/organization_id/brand_id/location_id, even from an already-
-- authorized SECURITY DEFINER function, and fixed it for org_remove_member with a
-- transaction-local trusted-write flag. Grepping turned up 6 more functions with the same
-- shape (SECURITY DEFINER, invoked under 'authenticated', updating these same columns) --
-- all 6 confirmed by reading their live bodies before this migration:
--   - admin_update_user_role: the actual role/brand/location editing RPC UserManagement.jsx
--     calls directly. This one is the highest-impact fix in this migration -- an org_manager
--     currently cannot successfully change anyone's role, brand, or location through the UI
--     at all; the UPDATE has been silently rejected every time.
--   - complete_onboarding, accept_invitation, setup_onboarding_hierarchy,
--     setup_organization_full: all first-time-onboarding paths that stamp a brand-new user's
--     role/organization_id/brand_id/location_id onto their (auto-created, blank) profile row.
--   - switch_user_context: the org/brand/location context switcher for org_manager/
--     branch_manager (CLAUDE.md section 3).
-- All 6 already have correct EXECUTE grants for authenticated (verified live before this
-- migration) -- only org_remove_member had that separate, unrelated grant gap.

BEGIN;

CREATE OR REPLACE FUNCTION public.admin_update_user_role(
  target_user_id uuid,
  new_role text DEFAULT NULL::text,
  new_status text DEFAULT NULL::text,
  new_department text DEFAULT NULL::text,
  new_location text DEFAULT NULL::text,
  new_brand_id uuid DEFAULT NULL::uuid,
  new_location_id uuid DEFAULT NULL::uuid,
  new_access_level text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  caller_role text;
  caller_org uuid;
  caller_tenant uuid;
  target_org uuid;
  target_tenant uuid;
  normalized_role text;
BEGIN
  IF new_location IS NOT NULL THEN
    -- Backward-compatible no-op.
  END IF;

  caller_role := public.get_auth_role();
  caller_org := public.get_auth_org();
  caller_tenant := public.get_auth_tenant();
  normalized_role := CASE WHEN new_role IS NULL THEN NULL ELSE public.normalize_app_role(new_role) END;

  IF caller_role NOT IN ('org_manager', 'tenant_super_admin', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: org_manager, tenant_super_admin, or platform_admin required';
  END IF;

  SELECT p.organization_id, COALESCE(p.tenant_id, o.tenant_id)
  INTO target_org, target_tenant
  FROM public.profiles p
  LEFT JOIN public.organizations o ON o.id = p.organization_id
  WHERE p.id = target_user_id;

  IF caller_role = 'tenant_super_admin' AND target_tenant IS DISTINCT FROM caller_tenant THEN
    RAISE EXCEPTION 'Cannot modify users outside your tenant';
  END IF;

  IF caller_role = 'org_manager' AND target_org IS DISTINCT FROM caller_org THEN
    RAISE EXCEPTION 'Cannot modify users outside your organization';
  END IF;

  IF caller_role != 'platform_admin' AND normalized_role IS NOT NULL THEN
    IF NOT public.can_invite_role(normalized_role) THEN
      RAISE EXCEPTION 'Cannot assign a role equal to or above your own';
    END IF;
  END IF;

  IF target_user_id = auth.uid() AND normalized_role IS NOT NULL AND normalized_role <> caller_role THEN
    RAISE EXCEPTION 'Cannot change your own role';
  END IF;

  IF normalized_role = 'tenant_super_admin' AND target_tenant IS NOT NULL THEN
    INSERT INTO public.tenant_members (tenant_id, user_id, role)
    VALUES (target_tenant, target_user_id, 'tenant_super_admin')
    ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF normalized_role IS NOT NULL AND target_org IS NOT NULL THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (target_org, target_user_id, normalized_role)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  PERFORM set_config('app.trusted_profile_write', 'on', true);
  UPDATE public.profiles
  SET role = COALESCE(normalized_role, role),
      status = COALESCE(new_status, status),
      department = COALESCE(new_department, department),
      brand_id = COALESCE(new_brand_id, brand_id),
      location_id = COALESCE(new_location_id, location_id),
      access_level = COALESCE(new_access_level, access_level),
      tenant_id = COALESCE(tenant_id, target_tenant),
      updated_at = now()
  WHERE id = target_user_id;

  IF (SELECT raw_app_meta_data->>'organization_id' FROM auth.users WHERE id = target_user_id) = target_org::text THEN
    UPDATE auth.users
    SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
      'role', COALESCE(normalized_role, (SELECT role FROM public.profiles WHERE id = target_user_id)),
      'tenant_id', COALESCE(target_tenant::text, '')
    )
    WHERE id = target_user_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

CREATE OR REPLACE FUNCTION public.switch_user_context(p_organization_id uuid, p_brand_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid;
  v_role text;
  v_tenant_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT tenant_id INTO v_tenant_id FROM public.organizations WHERE id = p_organization_id;

  SELECT role INTO v_role
  FROM public.organization_members
  WHERE organization_id = p_organization_id
    AND user_id = v_user_id;

  IF v_role IS NULL AND public.get_auth_role() = 'tenant_super_admin' AND v_tenant_id = public.get_auth_tenant() THEN
    v_role := 'tenant_super_admin';
  END IF;

  IF v_role IS NULL AND NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'User is not a member of this organization';
  END IF;

  IF v_role IS NULL THEN
    v_role := 'platform_admin';
  END IF;

  v_role := public.normalize_app_role(v_role);

  IF p_brand_id IS NOT NULL
     AND NOT (p_brand_id = ANY (ARRAY(SELECT public.get_my_accessible_brand_ids()))) THEN
    RAISE EXCEPTION 'Brand % not in your accessible scope', p_brand_id;
  END IF;

  IF p_location_id IS NOT NULL
     AND NOT (p_location_id = ANY (ARRAY(SELECT public.get_my_accessible_location_ids()))) THEN
    RAISE EXCEPTION 'Location % not in your accessible scope', p_location_id;
  END IF;

  PERFORM set_config('app.trusted_profile_write', 'on', true);
  UPDATE public.profiles
  SET tenant_id = COALESCE(v_tenant_id, tenant_id),
      organization_id = p_organization_id,
      brand_id = p_brand_id,
      location_id = p_location_id,
      role = v_role,
      updated_at = now()
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'role', v_role,
    'tenant_id', v_tenant_id,
    'organization_id', p_organization_id,
    'brand_id', p_brand_id,
    'location_id', p_location_id
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.complete_onboarding(p_user_id uuid, p_org_id uuid, p_brand_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  caller_org_id uuid;
  org_owner uuid;
  v_current_role text;
BEGIN
  -- Verify caller is the user being updated
  IF auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Can only complete onboarding for yourself';
  END IF;

  -- Verify the user does NOT already have an org (prevents re-onboarding abuse)
  SELECT organization_id, role INTO caller_org_id, v_current_role FROM public.profiles WHERE id = p_user_id;
  IF caller_org_id IS NOT NULL THEN
    RAISE EXCEPTION 'User already belongs to an organization';
  END IF;

  -- Verify the org exists and the user is the owner
  SELECT owner_id INTO org_owner FROM public.organizations WHERE id = p_org_id;
  IF org_owner IS DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION 'Organization does not belong to this user';
  END IF;

  -- Update the profile with org hierarchy and preserve platform_admin
  PERFORM set_config('app.trusted_profile_write', 'on', true);
  UPDATE public.profiles SET
    organization_id = p_org_id,
    brand_id = p_brand_id,
    location_id = p_location_id,
    role = CASE WHEN v_current_role = 'platform_admin' THEN 'platform_admin' ELSE 'org_manager' END,
    access_level = CASE WHEN v_current_role = 'platform_admin' THEN 'platform' ELSE 'organization' END,
    updated_at = now()
  WHERE id = p_user_id;

  -- Sync JWT metadata
  UPDATE auth.users SET
    raw_user_meta_data = COALESCE(raw_user_meta_data, '{}'::jsonb) || jsonb_build_object(
      'role', CASE WHEN v_current_role = 'platform_admin' THEN 'platform_admin' ELSE 'org_manager' END,
      'access_level', CASE WHEN v_current_role = 'platform_admin' THEN 'platform' ELSE 'organization' END,
      'organization_id', p_org_id,
      'brand_id', p_brand_id,
      'location_id', p_location_id
    )
  WHERE id = p_user_id;

  -- Audit log
  INSERT INTO public.audit_logs (organization_id, user_id, action, table_name, record_id, new_data)
  VALUES (p_org_id, p_user_id, 'ONBOARDING_COMPLETE', 'profiles', p_user_id,
          jsonb_build_object('org_id', p_org_id, 'brand_id', p_brand_id, 'location_id', p_location_id));
END;
$$;

CREATE OR REPLACE FUNCTION public.setup_organization_full(p_user_id uuid, p_org_name text, p_org_slug text, p_brand_name text, p_location_name text, p_location_address text DEFAULT ''::text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_tenant_id uuid;
  v_org_id uuid;
  v_brand_id uuid;
  v_location_id uuid;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  INSERT INTO public.tenants (name, slug, owner_id, metadata)
  VALUES (
    p_org_name,
    left('tenant_' || regexp_replace(lower(p_org_slug), '[^a-z0-9]+', '_', 'g'), 63),
    p_user_id,
    jsonb_build_object('source', 'setup_organization_full')
  )
  ON CONFLICT (slug) DO UPDATE SET owner_id = EXCLUDED.owner_id
  RETURNING id INTO v_tenant_id;

  INSERT INTO public.organizations (tenant_id, name, slug, owner_id)
  VALUES (v_tenant_id, p_org_name, p_org_slug, p_user_id)
  RETURNING id INTO v_org_id;

  INSERT INTO public.brands (organization_id, name)
  VALUES (v_org_id, p_brand_name)
  RETURNING brand_id INTO v_brand_id;

  INSERT INTO public.locations (organization_id, brand_id, name, address)
  VALUES (v_org_id, v_brand_id, p_location_name, p_location_address)
  RETURNING id INTO v_location_id;

  INSERT INTO public.tenant_members (tenant_id, user_id, role)
  VALUES (v_tenant_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  INSERT INTO public.organization_members (organization_id, user_id, role)
  VALUES (v_org_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  INSERT INTO public.brand_members (brand_id, user_id, role)
  VALUES (v_brand_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  INSERT INTO public.location_members (location_id, user_id, role)
  VALUES (v_location_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  PERFORM set_config('app.trusted_profile_write', 'on', true);
  UPDATE public.profiles
  SET tenant_id = v_tenant_id,
      organization_id = v_org_id,
      brand_id = v_brand_id,
      location_id = v_location_id,
      role = 'tenant_super_admin',
      access_level = 'organization',
      updated_at = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'tenant_super_admin',
    'tenant_id', v_tenant_id::text,
    'organization_id', v_org_id::text,
    'brand_id', v_brand_id::text,
    'location_id', v_location_id::text
  )
  WHERE id = p_user_id;

  RETURN jsonb_build_object(
    'tenant_id', v_tenant_id,
    'org_id', v_org_id,
    'brand_id', v_brand_id,
    'location_id', v_location_id
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.accept_invitation(p_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_invite record;
  v_user_id uuid;
  v_user_email text;
  v_role text;
  v_tenant_id uuid;
  v_business_verification_required boolean := true;
  v_coupon_code text;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND closed_at IS NULL
    AND lower(email) = lower(v_user_email)
    AND (expires_at IS NULL OR expires_at > now());

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  v_role := public.normalize_app_role(v_invite.role);
  v_tenant_id := v_invite.tenant_id;
  v_business_verification_required := COALESCE((v_invite.metadata->>'business_verification_required')::boolean, true);
  v_coupon_code := COALESCE(v_invite.metadata->>'coupon_code', v_invite.metadata#>>'{coupon,code}');

  IF v_tenant_id IS NULL AND v_invite.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO v_tenant_id FROM public.organizations WHERE id = v_invite.organization_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NULL THEN
    INSERT INTO public.tenants (name, owner_id, metadata)
    VALUES (
      COALESCE(v_invite.metadata->>'tenant_name', split_part(v_user_email, '@', 1), 'Tenant'),
      v_user_id,
      jsonb_build_object(
        'source', 'accept_invitation',
        'invitation_id', v_invite.id,
        'invited_email', v_invite.email,
        'business_verification_required', v_business_verification_required,
        'coupon_code', v_coupon_code
      )
    )
    RETURNING id INTO v_tenant_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NOT NULL THEN
    INSERT INTO public.tenant_members (tenant_id, user_id, role)
    VALUES (v_tenant_id, v_user_id, 'tenant_super_admin')
    ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    UPDATE public.tenants
    SET owner_id = COALESCE(owner_id, v_user_id),
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
          'business_verification_required', v_business_verification_required,
          'coupon_code', v_coupon_code
        ),
        updated_at = now()
    WHERE id = v_tenant_id;
  END IF;

  IF v_invite.organization_id IS NOT NULL THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_invite.organization_id, v_user_id, v_role)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.brand_id IS NOT NULL THEN
    INSERT INTO public.brand_members (brand_id, user_id, role)
    VALUES (v_invite.brand_id, v_user_id, v_role)
    ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.location_id IS NOT NULL THEN
    INSERT INTO public.location_members (location_id, user_id, role)
    VALUES (v_invite.location_id, v_user_id, v_role)
    ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  PERFORM set_config('app.trusted_profile_write', 'on', true);
  UPDATE public.profiles
  SET tenant_id = COALESCE(v_tenant_id, tenant_id),
      role = v_role,
      organization_id = COALESCE(v_invite.organization_id, organization_id),
      brand_id = COALESCE(v_invite.brand_id, brand_id),
      location_id = COALESCE(v_invite.location_id, location_id),
      coupon_code = COALESCE(v_coupon_code, coupon_code),
      business_verification_status = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'verified'
        ELSE business_verification_status
      END,
      onboarding_current_step = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'hierarchy_setup'
        ELSE onboarding_current_step
      END,
      updated_at = now()
  WHERE id = v_user_id;

  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id,
      role = v_role,
      tenant_id = COALESCE(tenant_id, v_tenant_id),
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
        'business_verification_required', v_business_verification_required,
        'coupon_code', v_coupon_code
      )
  WHERE id = v_invite.id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', v_role,
    'tenant_id', COALESCE(v_tenant_id::text, ''),
    'organization_id', COALESCE(v_invite.organization_id::text, ''),
    'business_verification_required', v_business_verification_required,
    'coupon_code', COALESCE(v_coupon_code, '')
  )
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'role', v_role,
    'tenant_id', v_tenant_id,
    'organization_id', v_invite.organization_id,
    'business_verification_required', v_business_verification_required,
    'coupon_code', v_coupon_code
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.setup_onboarding_hierarchy(p_user_id uuid, p_hierarchy jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  org_item jsonb;
  brand_item jsonb;
  location_item jsonb;
  v_tenant_id uuid;
  v_org_id uuid;
  v_brand_id uuid;
  v_location_id uuid;
  v_primary_org_id uuid;
  v_primary_brand_id uuid;
  v_primary_location_id uuid;
  v_created_orgs jsonb := '[]'::jsonb;
  v_created_brands jsonb := '[]'::jsonb;
  v_created_locations jsonb := '[]'::jsonb;
  v_org_name text;
  v_org_slug text;
  v_brand_name text;
  v_location_name text;
  v_location_address text;
  v_org_count integer := 0;
  v_brand_count integer := 0;
  v_location_count integer := 0;
  v_business_status text;
  v_payment_verified boolean;
  v_pending_plan_id text;
  v_pending_stripe_customer_id text;
  v_pending_stripe_subscription_id text;
  v_pending_checkout_session_id text;
  v_pending_payment_metadata jsonb;
  v_run_id uuid;
  v_org_address jsonb;
  v_brand_address jsonb;
  v_business_address jsonb;
  v_mailing_address jsonb;
  v_tenant_identity jsonb;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  SELECT business_verification_status, payment_verified, pending_onboarding_plan_id, pending_stripe_customer_id, pending_stripe_subscription_id, pending_checkout_session_id, pending_payment_metadata
  INTO v_business_status, v_payment_verified, v_pending_plan_id, v_pending_stripe_customer_id, v_pending_stripe_subscription_id, v_pending_checkout_session_id, v_pending_payment_metadata
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE
     AND COALESCE(v_pending_payment_metadata->>'provider', '') NOT IN ('free_plan', 'stripe') THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' THEN
    RAISE EXCEPTION 'Onboarding hierarchy must be an array';
  END IF;

  IF jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  v_org_name := NULLIF(btrim((p_hierarchy->0)->>'name'), '');
  v_org_slug := NULLIF(btrim((p_hierarchy->0)->>'slug'), '');

  INSERT INTO public.tenants (name, slug, owner_id, metadata)
  VALUES (
    COALESCE(v_org_name, 'Tenant'),
    left('tenant_' || regexp_replace(lower(COALESCE(v_org_slug, gen_random_uuid()::text)), '[^a-z0-9]+', '_', 'g'), 63),
    p_user_id,
    jsonb_build_object(
      'source', 'setup_onboarding_hierarchy',
      'business_identity', (p_hierarchy->0)#>'{metadata,tenant_business_identity}'
    )
  )
  ON CONFLICT (slug) DO UPDATE
    SET owner_id = EXCLUDED.owner_id,
        metadata = COALESCE(public.tenants.metadata, '{}'::jsonb) || EXCLUDED.metadata
  RETURNING id INTO v_tenant_id;

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
  EXCEPTION WHEN undefined_function THEN
    v_run_id := NULL;
  END;

  FOR org_item IN SELECT value FROM jsonb_array_elements(p_hierarchy)
  LOOP
    v_org_name := NULLIF(btrim(org_item->>'name'), '');
    v_org_slug := NULLIF(btrim(org_item->>'slug'), '');
    v_org_address := NULLIF(COALESCE(org_item#>'{metadata,organization_business_address}', org_item#>'{metadata,organization_address}'), 'null'::jsonb);
    v_mailing_address := CASE
      WHEN COALESCE((org_item#>>'{metadata,organization_mailing_same_as_business}')::boolean, true) THEN v_org_address
      ELSE NULLIF(org_item#>'{metadata,organization_mailing_address}', 'null'::jsonb)
    END;

    IF v_org_name IS NULL OR v_org_slug IS NULL THEN
      RAISE EXCEPTION 'Each organization requires a name and slug';
    END IF;

    IF COALESCE(jsonb_typeof(org_item->'brands'), 'null') <> 'array'
       OR jsonb_array_length(org_item->'brands') = 0 THEN
      RAISE EXCEPTION 'Organization % requires at least one brand', v_org_name;
    END IF;

    INSERT INTO public.organizations (tenant_id, name, slug, owner_id)
    VALUES (v_tenant_id, v_org_name, v_org_slug, p_user_id)
    RETURNING id INTO v_org_id;

    IF v_org_address IS NOT NULL AND COALESCE(jsonb_typeof(v_org_address), 'null') <> 'object' THEN
      RAISE EXCEPTION 'Organization % business/service address must be an object when provided', v_org_name;
    END IF;

    IF v_org_address IS NOT NULL THEN
      IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
        RAISE EXCEPTION 'Organization % mailing address must be an object when organization address is provided', v_org_name;
      END IF;

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'service', v_org_name, v_org_address
      );

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'mailing', v_org_name, v_mailing_address
      );
    END IF;

    v_org_count := v_org_count + 1;
    v_created_orgs := v_created_orgs || jsonb_build_array(jsonb_build_object('id', v_org_id, 'name', v_org_name, 'slug', v_org_slug));

    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_org_id, p_user_id, 'tenant_super_admin')
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    IF v_primary_org_id IS NULL THEN
      v_primary_org_id := v_org_id;
    END IF;

    FOR brand_item IN SELECT value FROM jsonb_array_elements(org_item->'brands')
    LOOP
      v_brand_name := NULLIF(btrim(brand_item->>'name'), '');
      v_brand_address := NULLIF(brand_item#>'{metadata,brand_address}', 'null'::jsonb);

      IF v_brand_name IS NULL THEN
        RAISE EXCEPTION 'Every brand in organization % requires a name', v_org_name;
      END IF;

      IF COALESCE(jsonb_typeof(brand_item->'locations'), 'null') <> 'array'
         OR jsonb_array_length(brand_item->'locations') = 0 THEN
        RAISE EXCEPTION 'Brand % requires at least one location', v_brand_name;
      END IF;

      INSERT INTO public.brands (organization_id, name)
      VALUES (v_org_id, v_brand_name)
      RETURNING brand_id INTO v_brand_id;

      IF v_brand_address IS NOT NULL AND COALESCE(jsonb_typeof(v_brand_address), 'null') = 'object' THEN
        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, NULL, 'service', v_brand_name, v_brand_address
        );
      END IF;

      v_brand_count := v_brand_count + 1;
      v_created_brands := v_created_brands || jsonb_build_array(jsonb_build_object('id', v_brand_id, 'organization_id', v_org_id, 'name', v_brand_name));

      INSERT INTO public.brand_members (brand_id, user_id, role)
      VALUES (v_brand_id, p_user_id, 'tenant_super_admin')
      ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

      IF v_primary_brand_id IS NULL THEN
        v_primary_brand_id := v_brand_id;
      END IF;

      FOR location_item IN SELECT value FROM jsonb_array_elements(brand_item->'locations')
      LOOP
        v_location_name := NULLIF(btrim(location_item->>'name'), '');
        v_location_address := COALESCE(NULLIF(btrim(location_item->>'address'), ''), 'Address pending');
        v_business_address := location_item->'business_address';
        v_mailing_address := location_item->'mailing_address';

        IF v_location_name IS NULL THEN
          RAISE EXCEPTION 'Every location in brand % requires a name', v_brand_name;
        END IF;

        IF v_business_address IS NULL OR COALESCE(jsonb_typeof(v_business_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a business/service address', v_brand_name;
        END IF;

        INSERT INTO public.locations (organization_id, brand_id, name, address)
        VALUES (v_org_id, v_brand_id, v_location_name, v_location_address)
        RETURNING id INTO v_location_id;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'service', v_location_name, v_business_address
        );

        IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a mailing address', v_brand_name;
        END IF;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'mailing', v_location_name, v_mailing_address
        );

        v_location_count := v_location_count + 1;
        v_created_locations := v_created_locations || jsonb_build_array(jsonb_build_object(
          'id', v_location_id,
          'organization_id', v_org_id,
          'brand_id', v_brand_id,
          'name', v_location_name,
          'address', v_location_address
        ));

        INSERT INTO public.location_members (location_id, user_id, role)
        VALUES (v_location_id, p_user_id, 'tenant_super_admin')
        ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

        IF v_primary_location_id IS NULL THEN
          v_primary_location_id := v_location_id;
        END IF;
      END LOOP;
    END LOOP;

    INSERT INTO public.onboarding_progress (organization_id, current_step, completed_steps, is_completed)
    VALUES (v_org_id, 'hierarchy_created', ARRAY['organizations', 'brands', 'locations'], false)
    ON CONFLICT DO NOTHING;
  END LOOP;

  INSERT INTO public.tenant_members (tenant_id, user_id, role)
  VALUES (v_tenant_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  PERFORM set_config('app.trusted_profile_write', 'on', true);
  UPDATE public.profiles
  SET tenant_id = v_tenant_id,
      organization_id = v_primary_org_id,
      brand_id = v_primary_brand_id,
      location_id = v_primary_location_id,
      role = 'tenant_super_admin',
      access_level = 'organization',
      onboarding_status = 'completed',
      onboarding_current_step = 'completed',
      onboarding_completed_at = now(),
      updated_at = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'tenant_super_admin',
    'tenant_id', v_tenant_id::text,
    'organization_id', v_primary_org_id::text,
    'brand_id', v_primary_brand_id::text,
    'location_id', v_primary_location_id::text
  )
  WHERE id = p_user_id;

  IF v_primary_org_id IS NOT NULL THEN
    UPDATE public.organizations
    SET plan_id = COALESCE(v_pending_plan_id, plan_id),
        stripe_customer_id = COALESCE(v_pending_stripe_customer_id, stripe_customer_id),
        stripe_subscription_id = COALESCE(v_pending_stripe_subscription_id, stripe_subscription_id)
    WHERE id = v_primary_org_id;
  END IF;

  UPDATE public.business_verifications SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.organization_addresses SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_payment_methods SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_coupon_redemptions SET organization_id = v_primary_org_id
  WHERE user_id = p_user_id AND organization_id IS NULL;

  v_tenant_identity := (p_hierarchy->0)#>'{metadata,tenant_business_identity}';
  IF v_tenant_identity IS NOT NULL AND COALESCE(jsonb_typeof(v_tenant_identity), 'null') = 'object' THEN
    v_business_address := v_tenant_identity->'businessAddress';
    v_mailing_address := CASE
      WHEN COALESCE((v_tenant_identity->>'mailingSameAsBusiness')::boolean, true) THEN v_business_address
      ELSE v_tenant_identity->'mailingAddress'
    END;

    IF v_business_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'business'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'business', 'Tenant business identity', v_business_address
      );
    END IF;

    IF v_mailing_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'mailing'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'mailing', 'Tenant business identity', v_mailing_address
      );
    END IF;
  END IF;

  IF v_run_id IS NOT NULL THEN
    UPDATE public.onboarding_workflow_runs
    SET organization_id = v_primary_org_id,
        status = 'completed',
        current_step = 'completed',
        completed_at = now(),
        last_activity_at = now()
    WHERE id = v_run_id;

    PERFORM public.record_onboarding_event(
      v_run_id,
      p_user_id,
      'hierarchy_setup',
      'completed',
      'completed',
      jsonb_build_object('tenant_id', v_tenant_id, 'primary_org_id', v_primary_org_id, 'plan_id', v_pending_plan_id, 'checkout_session_id', v_pending_checkout_session_id)
    );
  END IF;

  RETURN jsonb_build_object(
    'tenant_id', v_tenant_id,
    'primary_org_id', v_primary_org_id,
    'primary_brand_id', v_primary_brand_id,
    'primary_location_id', v_primary_location_id,
    'organizations', v_created_orgs,
    'brands', v_created_brands,
    'locations', v_created_locations,
    'counts', jsonb_build_object('organizations', v_org_count, 'brands', v_brand_count, 'locations', v_location_count),
    'plan_id', v_pending_plan_id,
    'stripe_customer_id', v_pending_stripe_customer_id,
    'stripe_subscription_id', v_pending_stripe_subscription_id
  );
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260719000011_missing_product_crud_rpcs.sql
-- ==========================================================================

-- 20260719000011: create_product_details / update_product_details /
-- set_product_inventory_tracking / soft_delete_product_safe
--
-- Discovered while adding a vendor-quantity field to product creation (tracker item 17.1):
-- Products.jsx's Add/Edit/Delete/inventory-toggle actions all call these 4 RPCs
-- (code/src/lib/apiClient.js api.products.*) but NONE of them exist anywhere -- not in the
-- live DB, not in any migration file. The entire Products page write path has never worked.
--
-- products is a REFERENCE table (brand-shared + location-specific hybrid, CLAUDE.md section
-- 4) and already has the correct RLS policies for this using reference_scope_writable() --
-- operational_products_insert/update already exist and are correct. These RPCs reuse that
-- exact same helper explicitly (SECURITY DEFINER functions bypass RLS, so they need their own
-- check) rather than re-deriving the write rule, so RPC and any future direct-table-write path
-- stay consistent.

BEGIN;

CREATE OR REPLACE FUNCTION public.create_product_details(
  p_name text,
  p_restops_product_id text DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_accounting_category text DEFAULT NULL,
  p_is_inventoried boolean DEFAULT true,
  p_is_tax_exempt boolean DEFAULT false,
  p_report_by_unit text DEFAULT NULL,
  p_base_unit text DEFAULT NULL,
  p_latest_price numeric DEFAULT 0,
  p_location_specific boolean DEFAULT false,
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_my_org());
  v_brand_id uuid;
  v_location_id uuid;
  v_product public.products%ROWTYPE;
BEGIN
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'Product name is required';
  END IF;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF p_location_specific THEN
    v_location_id := COALESCE(p_location_id, (SELECT location_id FROM public.profiles WHERE id = auth.uid()));
    v_brand_id := COALESCE(p_brand_id, (SELECT brand_id FROM public.locations WHERE id = v_location_id));
  ELSE
    v_location_id := NULL;
    v_brand_id := p_brand_id;
  END IF;

  IF NOT public.reference_scope_writable(v_org_id, v_brand_id, v_location_id, NULL, 'location_manager') THEN
    RAISE EXCEPTION 'Insufficient permissions to create this product';
  END IF;

  INSERT INTO public.products (
    name, product_id, description, category, accounting_category,
    is_inventoried, is_tax_exempt, report_by_unit, base_unit, latest_price,
    location_specific, organization_id, brand_id, location_id, created_by
  ) VALUES (
    btrim(p_name), p_restops_product_id, p_description, p_category, p_accounting_category,
    p_is_inventoried, p_is_tax_exempt, p_report_by_unit, p_base_unit, p_latest_price,
    p_location_specific, v_org_id, v_brand_id, v_location_id, auth.uid()
  )
  RETURNING * INTO v_product;

  RETURN to_jsonb(v_product);
END;
$$;

CREATE OR REPLACE FUNCTION public.update_product_details(
  p_product_id uuid,
  p_name text,
  p_restops_product_id text DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_accounting_category text DEFAULT NULL,
  p_is_inventoried boolean DEFAULT true,
  p_is_tax_exempt boolean DEFAULT false,
  p_report_by_unit text DEFAULT NULL,
  p_base_unit text DEFAULT NULL,
  p_latest_price numeric DEFAULT 0,
  p_location_specific boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_existing public.products%ROWTYPE;
  v_product public.products%ROWTYPE;
BEGIN
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'Product name is required';
  END IF;

  SELECT * INTO v_existing FROM public.products WHERE id = p_product_id AND deleted_at IS NULL;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.reference_scope_writable(v_existing.organization_id, v_existing.brand_id, v_existing.location_id, v_existing.deleted_at, 'location_manager') THEN
    RAISE EXCEPTION 'Insufficient permissions to update this product';
  END IF;

  UPDATE public.products SET
    name = btrim(p_name),
    product_id = COALESCE(p_restops_product_id, product_id),
    description = p_description,
    category = p_category,
    accounting_category = COALESCE(p_accounting_category, accounting_category),
    is_inventoried = p_is_inventoried,
    is_tax_exempt = p_is_tax_exempt,
    report_by_unit = p_report_by_unit,
    base_unit = p_base_unit,
    latest_price = p_latest_price,
    location_specific = p_location_specific,
    updated_at = now()
  WHERE id = p_product_id
  RETURNING * INTO v_product;

  RETURN to_jsonb(v_product);
END;
$$;

CREATE OR REPLACE FUNCTION public.set_product_inventory_tracking(
  p_product_id uuid,
  p_is_inventoried boolean
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_existing public.products%ROWTYPE;
BEGIN
  SELECT * INTO v_existing FROM public.products WHERE id = p_product_id AND deleted_at IS NULL;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.reference_scope_writable(v_existing.organization_id, v_existing.brand_id, v_existing.location_id, v_existing.deleted_at, 'location_manager') THEN
    RAISE EXCEPTION 'Insufficient permissions to update this product';
  END IF;

  UPDATE public.products SET is_inventoried = p_is_inventoried, updated_at = now() WHERE id = p_product_id;

  RETURN jsonb_build_object('success', true, 'id', p_product_id, 'is_inventoried', p_is_inventoried);
END;
$$;

CREATE OR REPLACE FUNCTION public.soft_delete_product_safe(
  p_product_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_existing public.products%ROWTYPE;
BEGIN
  SELECT * INTO v_existing FROM public.products WHERE id = p_product_id AND deleted_at IS NULL;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.reference_scope_writable(v_existing.organization_id, v_existing.brand_id, v_existing.location_id, v_existing.deleted_at, 'location_manager') THEN
    RAISE EXCEPTION 'Insufficient permissions to delete this product';
  END IF;

  UPDATE public.products SET deleted_at = now(), deleted_by = auth.uid() WHERE id = p_product_id;

  RETURN jsonb_build_object('success', true);
END;
$$;

REVOKE ALL ON FUNCTION public.create_product_details(text, text, text, text, text, boolean, boolean, text, text, numeric, boolean, uuid, uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_product_details(text, text, text, text, text, boolean, boolean, text, text, numeric, boolean, uuid, uuid, uuid) TO authenticated;

REVOKE ALL ON FUNCTION public.update_product_details(uuid, text, text, text, text, text, boolean, boolean, text, text, numeric, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.update_product_details(uuid, text, text, text, text, text, boolean, boolean, text, text, numeric, boolean) TO authenticated;

REVOKE ALL ON FUNCTION public.set_product_inventory_tracking(uuid, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_product_inventory_tracking(uuid, boolean) TO authenticated;

REVOKE ALL ON FUNCTION public.soft_delete_product_safe(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.soft_delete_product_safe(uuid) TO authenticated;

