CREATE OR REPLACE FUNCTION public.soft_delete_product_safe(p_product_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Product not found');
  END IF;

  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to delete this product';
  END IF;

  UPDATE public.products
     SET deleted_at = now(),
         deleted_by = auth.uid(),
         updated_at = now()
   WHERE id = p_product_id;

  UPDATE public.inventory i
     SET deleted_at = COALESCE(i.deleted_at, now()),
         deleted_by = COALESCE(i.deleted_by, auth.uid()),
         updated_at = now()
   WHERE i.organization_id = v_product.organization_id
     AND i.deleted_at IS NULL
     AND (
       i.internal_product_id = v_product.id
       OR (NULLIF(i.product_id, '') IS NOT NULL AND i.product_id = v_product.product_id)
     )
     AND (v_product.location_id IS NULL OR i.location_id IS NULL OR i.location_id IS NOT DISTINCT FROM v_product.location_id);

  RETURN jsonb_build_object('success', true, 'product_id', p_product_id);
END;
$$;

GRANT EXECUTE ON FUNCTION public.soft_delete_product_safe(uuid) TO authenticated;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260720000011_backfill_approved_invoice_purchase_lines.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.sync_invoice_products(p_invoice_id UUID, p_user_id UUID DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_item RECORD;
  v_product_id UUID;
  v_vendor_item_id UUID;
  v_mapping_id UUID;
  v_previous_price NUMERIC;
  v_threshold NUMERIC := 10;
  v_price_variance_flag BOOLEAN;
  v_price_variance_percent NUMERIC;
  v_line_hash TEXT;
  v_existing_hash TEXT;
  v_updates_count INT := 0;
BEGIN
  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id;

  IF v_invoice IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Invoice not found');
  END IF;

  SELECT md5(COALESCE(jsonb_agg(jsonb_build_object(
      'id', ili.id,
      'item_name', ili.item_name,
      'quantity', ili.quantity,
      'unit_price', ili.unit_price,
      'total_price', ili.total_price,
      'vendor_item_code', ili.vendor_item_code,
      'vendor_unit', ili.vendor_unit
    ) ORDER BY ili.id)::TEXT, '[]'))
    INTO v_line_hash
  FROM public.invoice_line_items ili
  WHERE ili.invoice_id = p_invoice_id;

  SELECT hash INTO v_existing_hash
  FROM public.invoice_sync_log
  WHERE invoice_id = p_invoice_id
    AND operation = 'sync_invoice_products'
  ORDER BY processed_at DESC
  LIMIT 1;

  IF v_existing_hash IS NOT NULL AND v_existing_hash = v_line_hash THEN
    RETURN jsonb_build_object('status', 'success', 'updates_count', 0, 'idempotent', true);
  END IF;

  FOR v_item IN
    SELECT *
    FROM public.invoice_line_items
    WHERE invoice_id = p_invoice_id
      AND NULLIF(trim(COALESCE(item_name, '')), '') IS NOT NULL
  LOOP
    v_product_id := v_item.internal_product_id;
    v_vendor_item_id := NULL;
    v_mapping_id := NULL;
    v_price_variance_flag := false;
    v_price_variance_percent := 0;

    IF v_product_id IS NULL THEN
      SELECT id INTO v_product_id
      FROM public.products
      WHERE organization_id = v_invoice.organization_id
        AND lower(name) = lower(v_item.item_name)
        AND deleted_at IS NULL
        AND (
          brand_id IS NOT DISTINCT FROM v_invoice.brand_id
          OR brand_id IS NULL
        )
      ORDER BY CASE WHEN brand_id IS NOT DISTINCT FROM v_invoice.brand_id THEN 0 ELSE 1 END
      LIMIT 1;

      IF v_product_id IS NULL THEN
        INSERT INTO public.products (
          organization_id,
          brand_id,
          location_id,
          product_id,
          name,
          category,
          accounting_category,
          report_by_unit,
          base_unit,
          latest_price,
          is_inventoried
        ) VALUES (
          v_invoice.organization_id,
          v_invoice.brand_id,
          v_invoice.location_id,
          public.generate_restops_product_id(),
          v_item.item_name,
          public.derive_product_category(NULL, v_item.item_name),
          CASE
            WHEN public.derive_product_category_type(NULL, NULL, v_item.item_name) = 'Beverage' THEN '5200'
            ELSE '5100'
          END,
          COALESCE(NULLIF(v_item.vendor_unit, ''), 'ea'),
          COALESCE(NULLIF(v_item.vendor_unit, ''), 'ea'),
          COALESCE(v_item.unit_price, 0),
          false
        )
        ON CONFLICT ON CONSTRAINT products_org_name_key 
        DO UPDATE SET 
          deleted_at = NULL,
          latest_price = CASE
            WHEN COALESCE(EXCLUDED.latest_price, 0) > 0 THEN EXCLUDED.latest_price
            ELSE products.latest_price
          END,
          updated_at = now()
        RETURNING id INTO v_product_id;
      ELSE
        UPDATE public.products
           SET product_id = COALESCE(NULLIF(product_id, ''), public.generate_restops_product_id()),
               latest_price = CASE
                 WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price
                 ELSE latest_price
               END,
               category = CASE
                 WHEN NULLIF(trim(COALESCE(category, '')), '') IS NULL OR lower(category) = 'uncategorized'
                   THEN public.derive_product_category(category, v_item.item_name)
                 ELSE category
               END,
               brand_id = COALESCE(brand_id, v_invoice.brand_id),
               location_id = COALESCE(location_id, v_invoice.location_id),
               updated_at = now()
         WHERE id = v_product_id;
      END IF;
    END IF;

    IF v_invoice.vendor_id IS NOT NULL THEN
      SELECT id, last_price, price_variance_threshold_percent
        INTO v_vendor_item_id, v_previous_price, v_threshold
      FROM public.vendor_items
      WHERE organization_id = v_invoice.organization_id
        AND vendor_id = v_invoice.vendor_id
        AND lower(vendor_item_name) = lower(v_item.item_name)
        AND COALESCE(vendor_item_code, '') = COALESCE(v_item.vendor_item_code, '')
      LIMIT 1;

      v_threshold := COALESCE(v_threshold, 10);

      IF v_vendor_item_id IS NOT NULL THEN
        IF COALESCE(v_previous_price, 0) > 0 AND COALESCE(v_item.unit_price, 0) > 0 THEN
          v_price_variance_percent := ((v_item.unit_price - v_previous_price) / v_previous_price) * 100;
          v_price_variance_flag := abs(v_price_variance_percent) >= v_threshold;
        END IF;

        UPDATE public.vendor_items
           SET vendor_unit = COALESCE(NULLIF(v_item.vendor_unit, ''), vendor_unit),
               previous_price = last_price,
               last_price = COALESCE(v_item.unit_price, last_price),
               last_invoice_id = p_invoice_id,
               last_invoice_line_id = v_item.id,
               last_purchased_at = COALESCE(v_invoice.invoice_date, CURRENT_DATE),
               last_price_change_percent = v_price_variance_percent,
               price_variance_flag = v_price_variance_flag,
               updated_at = now()
         WHERE id = v_vendor_item_id;
      ELSE
        INSERT INTO public.vendor_items (
          organization_id,
          vendor_id,
          vendor_item_code,
          vendor_item_name,
          vendor_unit,
          default_price,
          last_price,
          last_invoice_id,
          last_invoice_line_id,
          last_purchased_at,
          updated_at
        ) VALUES (
          v_invoice.organization_id,
          v_invoice.vendor_id,
          NULLIF(v_item.vendor_item_code, ''),
          v_item.item_name,
          NULLIF(v_item.vendor_unit, ''),
          v_item.unit_price,
          v_item.unit_price,
          p_invoice_id,
          v_item.id,
          COALESCE(v_invoice.invoice_date, CURRENT_DATE),
          now()
        )
        RETURNING id INTO v_vendor_item_id;
      END IF;

      IF v_product_id IS NOT NULL AND v_vendor_item_id IS NOT NULL THEN
        INSERT INTO public.vendor_item_mappings (
          organization_id,
          vendor_item_id,
          internal_product_id,
          conversion_multiplier,
          is_verified,
          updated_at
        ) VALUES (
          v_invoice.organization_id,
          v_vendor_item_id,
          v_product_id,
          1,
          false,
          now()
        )
        ON CONFLICT (vendor_item_id, internal_product_id)
        DO UPDATE SET updated_at = now()
        RETURNING id INTO v_mapping_id;
      END IF;
    END IF;

    UPDATE public.invoice_line_items
       SET vendor_id = v_invoice.vendor_id,
           vendor_item_id = v_vendor_item_id,
           internal_product_id = v_product_id,
           price_variance_flag = v_price_variance_flag,
           price_variance_percent = v_price_variance_percent
     WHERE id = v_item.id;

    v_updates_count := v_updates_count + 1;
  END LOOP;

  INSERT INTO public.invoice_event_log (invoice_id, event_type, new_value, actor_id)
  VALUES (
    p_invoice_id,
    'product_catalog_synced',
    jsonb_build_object('updates_count', v_updates_count),
    COALESCE(p_user_id, auth.uid())
  );

  INSERT INTO public.invoice_sync_log (invoice_id, operation, hash)
  VALUES (p_invoice_id, 'sync_invoice_products', v_line_hash);

  RETURN jsonb_build_object('status', 'success', 'updates_count', v_updates_count);
END;
$$;


CREATE OR REPLACE FUNCTION public.ensure_invoice_line_items_from_json(p_invoice_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_invoice public.invoices%ROWTYPE;
  v_existing_count integer;
  v_inserted_count integer := 0;
BEGIN
  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL;

  IF v_invoice.id IS NULL THEN
    RETURN 0;
  END IF;

  SELECT count(*)
    INTO v_existing_count
  FROM public.invoice_line_items
  WHERE invoice_id = p_invoice_id;

  IF v_existing_count > 0 THEN
    RETURN 0;
  END IF;

  IF jsonb_typeof(COALESCE(v_invoice.line_items, '[]'::jsonb)) <> 'array'
     OR jsonb_array_length(COALESCE(v_invoice.line_items, '[]'::jsonb)) = 0 THEN
    RETURN 0;
  END IF;

  INSERT INTO public.invoice_line_items (
    invoice_id,
    organization_id,
    vendor_id,
    internal_product_id,
    item_name,
    quantity,
    unit_price,
    total_price,
    vendor_item_code,
    vendor_unit
  )
  SELECT
    v_invoice.id,
    v_invoice.organization_id,
    v_invoice.vendor_id,
    CASE
      WHEN COALESCE(item.value->>'internal_product_id', item.value->>'product_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN COALESCE(item.value->>'internal_product_id', item.value->>'product_id')::uuid
      ELSE NULL
    END,
    trim(COALESCE(
      NULLIF(item.value->>'description', ''),
      NULLIF(item.value->>'item_name', ''),
      NULLIF(item.value->>'name', ''),
      'Unknown Item'
    )),
    amounts.quantity,
    amounts.unit_price,
    COALESCE(amounts.extended_price, amounts.total_price, amounts.quantity * amounts.unit_price),
    NULLIF(item.value->>'vendor_item_code', ''),
    COALESCE(NULLIF(item.value->>'vendor_unit', ''), NULLIF(item.value->>'unit', ''))
  FROM jsonb_array_elements(v_invoice.line_items) WITH ORDINALITY AS item(value, ordinal)
  CROSS JOIN LATERAL (
    SELECT
      COALESCE(NULLIF(regexp_replace(COALESCE(item.value->>'quantity', ''), '[^0-9.\-]', '', 'g'), '')::numeric, 1) AS quantity,
      COALESCE(NULLIF(regexp_replace(COALESCE(item.value->>'unit_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric, 0) AS unit_price,
      NULLIF(regexp_replace(COALESCE(item.value->>'extended_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric AS extended_price,
      NULLIF(regexp_replace(COALESCE(item.value->>'total_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric AS total_price
  ) amounts
  WHERE NULLIF(trim(COALESCE(
    item.value->>'description',
    item.value->>'item_name',
    item.value->>'name',
    ''
  )), '') IS NOT NULL;

  GET DIAGNOSTICS v_inserted_count = ROW_COUNT;
  RETURN v_inserted_count;
END;
$$;

WITH approved_invoices AS (
  SELECT id
  FROM public.invoices
  WHERE deleted_at IS NULL
    AND (status = 'approved' OR ap_status = 'approved')
)
SELECT public.ensure_invoice_line_items_from_json(id)
FROM approved_invoices;

DELETE FROM public.invoice_sync_log isl
USING public.invoices i
WHERE isl.invoice_id = i.id
  AND isl.operation = 'sync_invoice_products'
  AND i.deleted_at IS NULL
  AND (i.status = 'approved' OR i.ap_status = 'approved');

DO $$
DECLARE
  v_invoice_id uuid;
BEGIN
  FOR v_invoice_id IN
    SELECT i.id
    FROM public.invoices i
    WHERE i.deleted_at IS NULL
      AND (i.status = 'approved' OR i.ap_status = 'approved')
      AND EXISTS (
        SELECT 1
        FROM public.invoice_line_items ili
        WHERE ili.invoice_id = i.id
      )
  LOOP
    PERFORM public.sync_invoice_products(v_invoice_id, NULL);
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION public.ensure_invoice_line_items_from_json(uuid) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260720000012_fix_purchase_report_scope_and_json_fallback.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.get_product_purchase_report(
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_start_date date DEFAULT NULL,
  p_end_date date DEFAULT NULL,
  p_category_type text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_search text DEFAULT NULL
)
RETURNS TABLE (
  restaurant text,
  product_id uuid,
  restops_product_id text,
  product_name text,
  category_type text,
  category text,
  report_by text,
  invoice_count bigint,
  line_count bigint,
  purchased_units numeric,
  purchased_amount numeric,
  latest_cost numeric,
  avg_cost numeric,
  last_purchased_at date
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  RETURN QUERY
  WITH approved_invoices AS (
    SELECT i.*
    FROM public.invoices i
    WHERE i.organization_id = v_org_id
      AND i.deleted_at IS NULL
      AND (i.status = 'approved' OR i.ap_status = 'approved')
      AND (p_brand_id IS NULL OR i.brand_id IS NOT DISTINCT FROM p_brand_id OR i.brand_id IS NULL)
      AND (p_location_id IS NULL OR i.location_id IS NOT DISTINCT FROM p_location_id OR i.location_id IS NULL)
      AND (p_start_date IS NULL OR i.invoice_date >= p_start_date)
      AND (p_end_date IS NULL OR i.invoice_date <= p_end_date)
      AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
  ),
  normalized_lines AS (
    SELECT
      i.id AS invoice_id,
      i.invoice_date,
      i.organization_id,
      i.brand_id,
      i.location_id,
      i.vendor_id,
      ili.id AS line_id,
      ili.item_name,
      ili.quantity,
      ili.unit_price,
      ili.total_price,
      ili.vendor_unit,
      ili.internal_product_id,
      ili.inventory_item_id::text AS inventory_item_id
    FROM approved_invoices i
    JOIN public.invoice_line_items ili ON ili.invoice_id = i.id
    WHERE public.tenant_scope_visible(ili.organization_id, i.brand_id, i.location_id, NULL)
  ),
  json_lines AS (
    SELECT
      i.id AS invoice_id,
      i.invoice_date,
      i.organization_id,
      i.brand_id,
      i.location_id,
      i.vendor_id,
      gen_random_uuid() AS line_id,
      trim(COALESCE(
        NULLIF(item.value->>'description', ''),
        NULLIF(item.value->>'item_name', ''),
        NULLIF(item.value->>'name', ''),
        'Unknown Item'
      )) AS item_name,
      amounts.quantity,
      amounts.unit_price,
      COALESCE(amounts.extended_price, amounts.total_price, amounts.quantity * amounts.unit_price) AS total_price,
      COALESCE(NULLIF(item.value->>'vendor_unit', ''), NULLIF(item.value->>'unit', '')) AS vendor_unit,
      CASE
        WHEN COALESCE(item.value->>'internal_product_id', item.value->>'product_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN COALESCE(item.value->>'internal_product_id', item.value->>'product_id')::uuid
        ELSE NULL
      END AS internal_product_id,
      NULLIF(item.value->>'inventory_item_id', '') AS inventory_item_id
    FROM approved_invoices i
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(i.line_items, '[]'::jsonb)) WITH ORDINALITY AS item(value, ordinal)
    CROSS JOIN LATERAL (
      SELECT
        COALESCE(NULLIF(regexp_replace(COALESCE(item.value->>'quantity', ''), '[^0-9.\-]', '', 'g'), '')::numeric, 1) AS quantity,
        COALESCE(NULLIF(regexp_replace(COALESCE(item.value->>'unit_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric, 0) AS unit_price,
        NULLIF(regexp_replace(COALESCE(item.value->>'extended_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric AS extended_price,
        NULLIF(regexp_replace(COALESCE(item.value->>'total_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric AS total_price
    ) amounts
    WHERE NOT EXISTS (
        SELECT 1
        FROM public.invoice_line_items ili
        WHERE ili.invoice_id = i.id
      )
      AND NULLIF(trim(COALESCE(
        item.value->>'description',
        item.value->>'item_name',
        item.value->>'name',
        ''
      )), '') IS NOT NULL
  ),
  approved_lines AS (
    SELECT * FROM normalized_lines
    UNION ALL
    SELECT * FROM json_lines
  ),
  enriched AS (
    SELECT
      COALESCE(l.name, 'Current Store') AS restaurant,
      p.id AS product_id,
      p.product_id AS restops_product_id,
      COALESCE(p.name, al.item_name) AS product_name,
      public.derive_product_category_type(p.accounting_category, p.category, COALESCE(p.name, al.item_name)) AS category_type,
      public.derive_product_category(p.category, COALESCE(p.name, al.item_name)) AS category,
      public.normalize_product_report_unit(COALESCE(p.report_by_unit, al.vendor_unit)) AS report_by,
      al.invoice_id,
      al.line_id,
      COALESCE(al.quantity, 0) AS quantity,
      COALESCE(al.total_price, COALESCE(al.quantity, 0) * COALESCE(al.unit_price, 0)) AS total_price,
      COALESCE(al.unit_price, 0) AS unit_price,
      al.invoice_date
    FROM approved_lines al
    LEFT JOIN public.products p
      ON p.id = al.internal_product_id
      OR (al.inventory_item_id IS NOT NULL AND p.product_id = al.inventory_item_id)
    LEFT JOIN public.locations l ON l.id = al.location_id
    WHERE (p_search IS NULL OR COALESCE(p.name, al.item_name, '') ILIKE '%' || p_search || '%')
  )
  SELECT
    e.restaurant,
    e.product_id,
    e.restops_product_id,
    e.product_name,
    e.category_type,
    e.category,
    e.report_by,
    count(DISTINCT e.invoice_id) AS invoice_count,
    count(e.line_id) AS line_count,
    round(sum(e.quantity), 4) AS purchased_units,
    round(sum(e.total_price), 2) AS purchased_amount,
    (array_agg(e.unit_price ORDER BY e.invoice_date DESC NULLS LAST, e.line_id DESC))[1] AS latest_cost,
    round(sum(e.total_price) / NULLIF(sum(e.quantity), 0), 4) AS avg_cost,
    max(e.invoice_date) AS last_purchased_at
  FROM enriched e
  WHERE (p_category_type IS NULL OR p_category_type = 'all' OR e.category_type = p_category_type)
    AND (p_category IS NULL OR p_category = 'all' OR e.category = p_category)
  GROUP BY
    e.restaurant,
    e.product_id,
    e.restops_product_id,
    e.product_name,
    e.category_type,
    e.category,
    e.report_by
  ORDER BY e.product_name;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_product_purchase_report(uuid, uuid, uuid, date, date, text, text, text) TO authenticated;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260720000013_fix_tenant_super_admin_visibility.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.tenant_scope_visible(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_deleted_at timestamp with time zone DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role text;
  v_org_id uuid;
BEGIN
  IF p_deleted_at IS NOT NULL THEN
    RETURN false;
  END IF;

  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT role, organization_id
    INTO v_role, v_org_id
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;

  IF p_organization_id IS NULL OR v_org_id IS DISTINCT FROM p_organization_id THEN
    RETURN false;
  END IF;

  IF v_role IN ('tenant_super_admin', 'org_manager', 'org_owner') THEN
    RETURN true;
  END IF;

  IF p_brand_id IS NULL AND p_location_id IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'branch_manager' THEN
    RETURN (
      p_brand_id IN (SELECT id FROM public.get_my_accessible_brand_ids() id)
      OR p_location_id IN (SELECT id FROM public.get_my_accessible_location_ids() id)
    );
  END IF;

  IF v_role = 'location_manager' THEN
    RETURN p_location_id IN (SELECT id FROM public.get_my_accessible_location_ids() id);
  END IF;

  IF v_role = 'ground_staff' THEN
    RETURN EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.id = auth.uid()
        AND p.organization_id = p_organization_id
        AND p.location_id = p_location_id
        AND (
          p_brand_id IS NULL
          OR p.brand_id IS NULL
          OR p.brand_id = p_brand_id
        )
        AND p.deleted_at IS NULL
    );
  END IF;

  RETURN false;
END;
$$;

GRANT EXECUTE ON FUNCTION public.tenant_scope_visible(uuid, uuid, uuid, timestamp with time zone) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260720000014_reject_business_verification_terminal_status.sql
-- ==========================================================================

-- Reject vs "ask to resubmit" are currently indistinguishable: both
-- reject_business_verification() and request_onboarding_more_info() set
-- verification_status / business_verification_status = 'failed', and
-- BusinessVerification.jsx routes both back to the same editable, resubmittable
-- form (see 20260719000001, which deliberately merged them). Product decision:
-- Reject must be a genuine terminal state the tenant cannot resubmit from,
-- while "ask to resubmit" (request_onboarding_more_info) keeps today's 'failed'
-- resubmit behavior unchanged.
--
-- Adds a new 'rejected' status distinct from 'failed':
--   - reject_business_verification() now sets 'rejected' (terminal)
--   - request_onboarding_more_info() is untouched, still sets 'failed' (resubmittable)
--   - notify_business_verification_review_state() fires for 'rejected' too, with
--     its own title/message copy and its own onboarding_step_events event_type
--   - platform_business_verification_reviews() queue includes 'rejected' rows so
--     admins can still see the outcome
--   - CHECK constraints on profiles.business_verification_status,
--     business_verifications.verification_status, and
--     onboarding_step_events.event_type extended to allow the new value(s)

BEGIN;

ALTER TABLE public.profiles
  DROP CONSTRAINT profiles_business_verification_status_check;
ALTER TABLE public.profiles
  ADD CONSTRAINT profiles_business_verification_status_check
  CHECK (business_verification_status = ANY (ARRAY['not_started'::text, 'pending_review'::text, 'verified'::text, 'failed'::text, 'rejected'::text]));

ALTER TABLE public.business_verifications
  DROP CONSTRAINT business_verifications_verification_status_check;
ALTER TABLE public.business_verifications
  ADD CONSTRAINT business_verifications_verification_status_check
  CHECK (verification_status = ANY (ARRAY['pending_review'::text, 'verified'::text, 'failed'::text, 'rejected'::text]));

ALTER TABLE public.onboarding_step_events
  DROP CONSTRAINT onboarding_step_events_event_type_check;
ALTER TABLE public.onboarding_step_events
  ADD CONSTRAINT onboarding_step_events_event_type_check
  CHECK (event_type = ANY (ARRAY['started'::text, 'submitted'::text, 'verified'::text, 'failed'::text, 'completed'::text, 'skipped'::text, 'draft_saved'::text, 'bank_account_submitted'::text, 'signature_captured'::text, 'admin_approved'::text, 'admin_rejected'::text, 'more_info_requested'::text, 'failed_notification_queued'::text, 'pending_review_notification_queued'::text, 'rejected_notification_queued'::text]));

CREATE OR REPLACE FUNCTION public.reject_business_verification(p_user_id uuid, p_reason text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_actor UUID := auth.uid();
  v_run_id UUID;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A rejection reason is required';
  END IF;

  UPDATE public.business_verifications
  SET verification_status = 'rejected',
      rejection_reason = p_reason,
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('admin_reason', p_reason),
      updated_at = now()
  WHERE id = (
    SELECT id FROM public.business_verifications
    WHERE user_id = p_user_id
    ORDER BY created_at DESC
    LIMIT 1
  );

  UPDATE public.profiles
  SET business_verification_status = 'rejected',
      onboarding_status = 'blocked',
      onboarding_current_step = 'business_verification',
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.onboarding_admin_actions(actor_user_id, target_user_id, action, reason)
  VALUES (v_actor, p_user_id, 'reject_business_verification', p_reason);

  -- Notification is handled by trg_notify_business_verification_review_state (fires on the
  -- verification_status UPDATE above) -- do not insert one here too, or the tenant gets two.

  v_run_id := public.get_or_create_onboarding_run(p_user_id);
  PERFORM public.record_onboarding_event(v_run_id, p_user_id, 'business_verification', 'admin_rejected', 'rejected', jsonb_build_object('actor_user_id', v_actor, 'reason', p_reason));

  RETURN jsonb_build_object('success', true, 'status', 'rejected');
END;
$function$;

CREATE OR REPLACE FUNCTION public.notify_business_verification_review_state()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_admin RECORD;
  v_title TEXT;
  v_message TEXT;
  v_run_id UUID;
BEGIN
  IF NEW.verification_status NOT IN ('pending_review', 'failed', 'rejected') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND COALESCE(OLD.verification_status, '') = NEW.verification_status THEN
    RETURN NEW;
  END IF;

  v_title := CASE
    WHEN NEW.verification_status = 'rejected' THEN 'Business verification rejected'
    WHEN NEW.verification_status = 'failed' THEN 'Business verification needs changes'
    ELSE 'Business verification pending review'
  END;
  v_message := CASE
    WHEN NEW.verification_status = 'rejected' THEN COALESCE(NULLIF(NEW.rejection_reason, ''), 'Your business verification was rejected.')
    WHEN NEW.verification_status = 'failed' THEN COALESCE(NULLIF(NEW.rejection_reason, ''), 'Your business verification could not be approved. Please review and resubmit.')
    ELSE 'Your business verification is pending platform admin review.'
  END;

  INSERT INTO public.notifications(user_id, organization_id, type, title, message, is_read)
  VALUES (NEW.user_id, NEW.organization_id, 'system', v_title, v_message, false);

  FOR v_admin IN SELECT id FROM public.profiles WHERE role = 'platform_admin'
  LOOP
    INSERT INTO public.notifications(user_id, organization_id, type, title, message, is_read)
    VALUES (
      v_admin.id,
      NEW.organization_id,
      'system',
      v_title,
      COALESCE(NEW.legal_business_name, 'Tenant') || ' requires onboarding follow-up: ' || NEW.verification_status,
      false
    );
  END LOOP;

  v_run_id := public.get_or_create_onboarding_run(NEW.user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    NEW.user_id,
    'business_verification',
    CASE
      WHEN NEW.verification_status = 'rejected' THEN 'rejected_notification_queued'
      WHEN NEW.verification_status = 'failed' THEN 'failed_notification_queued'
      ELSE 'pending_review_notification_queued'
    END,
    NEW.verification_status,
    jsonb_build_object('verification_id', NEW.id)
  );

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.platform_business_verification_reviews()
RETURNS SETOF public.business_verifications
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.role = 'platform_admin'
  ) THEN
    RAISE EXCEPTION 'platform_admin role required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT bv.*
  FROM public.business_verifications bv
  WHERE bv.verification_status IN ('pending_review', 'failed', 'verified', 'rejected')
  ORDER BY bv.created_at DESC
  LIMIT 200;
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260720000015_username_login.sql
-- ==========================================================================

-- Adds a real, unique, login-usable username to profiles (product decision: not just a
-- display handle -- a tenant can sign in with either their email or their username).
--
-- Supabase Auth's signInWithPassword only accepts email/phone, not an arbitrary username, and
-- there's no custom GoTrue hook in this project to change that. So username-login is done at
-- the application layer in two RPCs:
--   - is_username_available(p_username)   -- live availability check during signup
--   - resolve_username_email(p_username)  -- login-time: turn a typed username into the email
--     to pass into supabase.auth.signInWithPassword
--
-- Both RPCs are necessarily callable pre-authentication (anon), which means, like the
-- "email already registered" error Supabase Auth's own signup already exposes, a username can
-- be probed for existence by an anonymous caller. That's an inherent tradeoff of
-- username-login without a custom auth hook, not a bug in this migration -- both RPCs return
-- the minimum possible surface (a boolean, or an email string) and nothing else.
--
-- Username is nullable: existing profiles, SSO signups, and platform-created invites have no
-- username and keep signing in by email only.

BEGIN;

ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS username TEXT;

ALTER TABLE public.profiles
  ADD CONSTRAINT profiles_username_format_check
  CHECK (username IS NULL OR username ~ '^[a-z0-9_]{3,24}$');

CREATE UNIQUE INDEX IF NOT EXISTS profiles_username_unique
  ON public.profiles (username)
  WHERE username IS NOT NULL;

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.profiles (id, email, full_name, role, username)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', split_part(NEW.email, '@', 1)),
    COALESCE(NEW.raw_user_meta_data->>'role', 'ground_staff'),
    NULLIF(lower(btrim(NEW.raw_user_meta_data->>'username')), '')
  )
  ON CONFLICT (id) DO UPDATE SET
    email = EXCLUDED.email,
    updated_at = now();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.is_username_available(p_username text)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_normalized text := lower(btrim(p_username));
BEGIN
  IF v_normalized IS NULL OR v_normalized !~ '^[a-z0-9_]{3,24}$' THEN
    RETURN false;
  END IF;

  RETURN NOT EXISTS (
    SELECT 1 FROM public.profiles WHERE username = v_normalized
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.resolve_username_email(p_username text)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_normalized text := lower(btrim(p_username));
  v_email text;
BEGIN
  IF v_normalized IS NULL OR v_normalized = '' THEN
    RETURN NULL;
  END IF;

  SELECT email INTO v_email FROM public.profiles WHERE username = v_normalized LIMIT 1;
  RETURN v_email;
END;
$$;

GRANT EXECUTE ON FUNCTION public.is_username_available(text) TO anon, authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_username_email(text) TO anon, authenticated;

COMMIT;

-- ==========================================================================
-- Source: 20260720000016_check_payment_method.sql
-- ==========================================================================

-- Adds "Check" as a third tenant subscription payment method alongside Card (Stripe) and
-- ACH (Dwolla). Unlike those two, a mailed paper check can't be verified electronically at
-- checkout time -- create-checkout-session (edge function, updated alongside this migration)
-- records the tenant's intent to pay by check but leaves profiles.payment_verified = false,
-- so the tenant is held on the Payment step (a dedicated "awaiting check" screen, not the
-- normal wizard) until a platform admin confirms the check actually arrived.
--
-- confirm_check_payment_received() is that admin-side confirmation -- the same shape as
-- approve_business_verification(): platform_admin only, flips payment_verified true, notifies
-- the tenant, and logs an onboarding_step_events row so this shows up alongside the other
-- onboarding history.

BEGIN;

ALTER TABLE public.profiles
  DROP CONSTRAINT profiles_payment_method_type_check;
ALTER TABLE public.profiles
  ADD CONSTRAINT profiles_payment_method_type_check
  CHECK (payment_method_type IS NULL OR payment_method_type = ANY (ARRAY['card'::text, 'ach'::text, 'check'::text, 'free_plan'::text, 'mock_subscription'::text, 'stripe_subscription'::text, 'trial_coupon'::text]));

CREATE OR REPLACE FUNCTION public.confirm_check_payment_received(p_user_id uuid, p_note text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_actor UUID := auth.uid();
  v_run_id UUID;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  UPDATE public.profiles
  SET payment_verified = true,
      payment_method_verified_at = now(),
      pending_payment_metadata = COALESCE(pending_payment_metadata, '{}'::jsonb) || jsonb_build_object(
        'status', 'received',
        'confirmed_by', v_actor,
        'confirmed_at', now(),
        'note', p_note
      ),
      updated_at = now()
  WHERE id = p_user_id
    AND payment_method_type = 'check';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No pending check payment found for this tenant';
  END IF;

  INSERT INTO public.notifications(user_id, organization_id, type, title, message, is_read)
  SELECT p_user_id, organization_id, 'system', 'Check payment received',
         'Your check payment has been received and confirmed. You can continue setting up your workspace.', false
  FROM public.profiles WHERE id = p_user_id;

  v_run_id := public.get_or_create_onboarding_run(p_user_id);
  PERFORM public.record_onboarding_event(v_run_id, p_user_id, 'payment_method', 'completed', 'check_received', jsonb_build_object('actor_user_id', v_actor, 'note', p_note));

  RETURN jsonb_build_object('success', true, 'status', 'payment_verified');
END;
$function$;

GRANT EXECUTE ON FUNCTION public.confirm_check_payment_received(uuid, text) TO authenticated;

COMMIT;

-- ==========================================================================
-- Source: 20260720000017_tax_identifier_vault_reveal.sql
-- ==========================================================================

-- Real EIN/SSN storage + a tenant-facing reveal toggle.
--
-- Today submit_business_verification() only ever stores identifier_last4 (via
-- mask_tax_identifier) -- the full EIN/SSN is discarded, so no "show full value" toggle can
-- exist because there is nothing to reveal. Product decision: keep the verification provider
-- call simulated for now (no live KYB/KYC API key yet), but persist the full identifier
-- encrypted in Supabase Vault -- the same pattern already used for bank account secrets
-- (store_onboarding_bank_secret) -- so a tenant-facing reveal toggle has something real to
-- show, while the admin queue keeps showing last-4-only, exactly as before.
--
-- reveal_my_tax_identifier() is deliberately self-only: it takes no user id parameter and
-- always operates on auth.uid()'s own most recent business_verifications row. There is no
-- equivalent admin-facing reveal RPC -- that is the enforcement that platform admins can
-- never see the full value, only ever identifier_last4 (already the case in
-- PlatformOrganizations.jsx and platform_business_verification_reviews()).

BEGIN;

ALTER TABLE public.business_verifications ADD COLUMN IF NOT EXISTS tax_identifier_secret_id UUID;

CREATE OR REPLACE FUNCTION public.store_tax_identifier_secret(p_business_verification_id uuid, p_identifier_type text, p_full_identifier text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_user_id UUID;
  v_secret_id UUID;
  v_secret_name TEXT;
  v_payload TEXT;
BEGIN
  SELECT user_id INTO v_user_id
  FROM public.business_verifications
  WHERE id = p_business_verification_id;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Business verification not found';
  END IF;

  v_secret_name := 'onboarding-tax-id-' || p_business_verification_id::text || '-' || extract(epoch from clock_timestamp())::text;
  v_payload := jsonb_build_object(
    'business_verification_id', p_business_verification_id,
    'user_id', v_user_id,
    'identifier_type', p_identifier_type,
    'full_identifier', p_full_identifier,
    'stored_at', now()
  )::text;

  SELECT vault.create_secret(v_payload, v_secret_name, 'tenant onboarding tax identifier')
    INTO v_secret_id;

  UPDATE public.business_verifications
  SET tax_identifier_secret_id = v_secret_id
  WHERE id = p_business_verification_id;

  RETURN v_secret_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.reveal_my_tax_identifier()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_secret_id UUID;
  v_identifier_type TEXT;
  v_decrypted TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT tax_identifier_secret_id, identifier_type
  INTO v_secret_id, v_identifier_type
  FROM public.business_verifications
  WHERE user_id = v_user_id
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_secret_id IS NULL THEN
    RAISE EXCEPTION 'No stored tax identifier to reveal';
  END IF;

  SELECT decrypted_secret INTO v_decrypted
  FROM vault.decrypted_secrets
  WHERE id = v_secret_id;

  IF v_decrypted IS NULL THEN
    RAISE EXCEPTION 'Stored tax identifier could not be decrypted';
  END IF;

  RETURN jsonb_build_object(
    'identifier_type', v_identifier_type,
    'full_identifier', (v_decrypted::jsonb)->>'full_identifier'
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.submit_business_verification(p_payload jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_run_id UUID;
  v_legal_name TEXT;
  v_business_type TEXT;
  v_identifier_type TEXT;
  v_identifier_required BOOLEAN;
  v_full_identifier TEXT;
  v_identifier_last4 TEXT;
  v_email TEXT;
  v_phone TEXT;
  v_website TEXT;
  v_provider TEXT;
  v_score INTEGER := 0;
  v_status TEXT;
  v_verification_id UUID;
  v_settings RECORD;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT ein_verification_enabled, ssn_verification_enabled
  INTO v_settings
  FROM public.platform_onboarding_settings
  WHERE id = true;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  v_legal_name := NULLIF(btrim(p_payload->>'legalName'), '');
  v_business_type := COALESCE(NULLIF(btrim(p_payload->>'businessType'), ''), 'llc');
  v_identifier_type := COALESCE(NULLIF(btrim(p_payload->>'identifierType'), ''), public.required_tax_identifier_type_for_business_type(v_business_type));
  v_identifier_required := CASE
    WHEN v_identifier_type = 'ein' THEN COALESCE(v_settings.ein_verification_enabled, true)
    WHEN v_identifier_type = 'ssn' THEN COALESCE(v_settings.ssn_verification_enabled, true)
    ELSE true
  END;
  v_full_identifier := CASE WHEN v_identifier_required THEN regexp_replace(COALESCE(p_payload->>'taxIdentifier', ''), '\D', '', 'g') ELSE NULL END;
  v_identifier_last4 := CASE WHEN v_identifier_required THEN public.mask_tax_identifier(p_payload->>'taxIdentifier') ELSE NULL END;
  v_email := NULLIF(btrim(p_payload->>'email'), '');
  v_phone := NULLIF(btrim(p_payload->>'phone'), '');
  v_website := NULLIF(btrim(p_payload->>'website'), '');

  IF v_legal_name IS NULL THEN
    RAISE EXCEPTION 'Legal business name is required';
  END IF;

  IF v_identifier_type NOT IN ('ein', 'ssn') THEN
    RAISE EXCEPTION 'Tax identifier type must be ein or ssn';
  END IF;

  IF v_identifier_type IS DISTINCT FROM public.required_tax_identifier_type_for_business_type(v_business_type) THEN
    RAISE EXCEPTION 'Tax identifier type % is not allowed for business type %', v_identifier_type, v_business_type;
  END IF;

  IF v_identifier_required AND length(COALESCE(v_identifier_last4, '')) <> 4 THEN
    RAISE EXCEPTION 'Valid tax identifier is required';
  END IF;

  IF v_email IS NULL OR position('@' in v_email) = 0 THEN
    RAISE EXCEPTION 'A valid business email is required';
  END IF;

  IF length(regexp_replace(COALESCE(v_phone, ''), '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid business phone number is required';
  END IF;

  v_score := CASE
    WHEN NOT v_identifier_required THEN 60
    WHEN v_identifier_type = 'ein' THEN 50
    ELSE 45
  END;
  IF v_email LIKE '%@%' THEN v_score := v_score + 10; END IF;
  IF length(regexp_replace(v_phone, '\D', '', 'g')) >= 10 THEN v_score := v_score + 10; END IF;
  IF v_website IS NOT NULL THEN v_score := v_score + 10; END IF;
  v_score := LEAST(v_score, 100);
  v_status := CASE WHEN v_score >= 80 THEN 'verified' WHEN v_score >= 50 THEN 'pending_review' ELSE 'failed' END;
  v_provider := CASE
    WHEN NOT v_identifier_required THEN v_identifier_type || '_verification_disabled_by_platform'
    WHEN v_identifier_type = 'ein' THEN 'global_database_kyb'
    ELSE 'searchbug_ssn'
  END;

  INSERT INTO public.business_verifications (
    user_id,
    legal_business_name,
    business_type,
    identifier_type,
    identifier_last4,
    provider_name,
    provider_reference_id,
    verification_status,
    trust_score,
    metadata,
    reviewed_by,
    reviewed_at,
    rejection_reason,
    updated_at
  )
  VALUES (
    v_user_id,
    v_legal_name,
    v_business_type,
    v_identifier_type,
    v_identifier_last4,
    v_provider,
    CASE WHEN v_identifier_required THEN 'provider-ready-' || replace(gen_random_uuid()::text, '-', '') ELSE 'verification-disabled' END,
    v_status,
    v_score,
    jsonb_build_object(
      'email', v_email,
      'phone', v_phone,
      'website', v_website,
      'tax_identifier_required', v_identifier_required,
      'ein_verification_enabled', COALESCE(v_settings.ein_verification_enabled, true),
      'ssn_verification_enabled', COALESCE(v_settings.ssn_verification_enabled, true),
      'provider_mode', CASE WHEN v_identifier_required THEN 'simulation_until_provider_keys_configured' ELSE 'disabled_by_platform_admin' END
    ),
    NULL,
    NULL,
    NULL,
    now()
  )
  ON CONFLICT (user_id) WHERE user_id IS NOT NULL DO UPDATE
  SET legal_business_name = EXCLUDED.legal_business_name,
      business_type = EXCLUDED.business_type,
      identifier_type = EXCLUDED.identifier_type,
      identifier_last4 = EXCLUDED.identifier_last4,
      provider_name = EXCLUDED.provider_name,
      provider_reference_id = EXCLUDED.provider_reference_id,
      verification_status = EXCLUDED.verification_status,
      trust_score = EXCLUDED.trust_score,
      metadata = EXCLUDED.metadata,
      reviewed_by = NULL,
      reviewed_at = NULL,
      rejection_reason = NULL,
      updated_at = now()
  RETURNING id INTO v_verification_id;

  IF v_identifier_required AND length(COALESCE(v_full_identifier, '')) > 0 THEN
    PERFORM public.store_tax_identifier_secret(v_verification_id, v_identifier_type, v_full_identifier);
  END IF;

  UPDATE public.profiles
  SET business_verification_status = v_status,
      business_verification_score = v_score,
      business_verification_provider = v_provider,
      business_verified_at = CASE WHEN v_status = 'verified' THEN now() ELSE NULL END,
      business_type = v_business_type,
      tax_identifier_type = v_identifier_type,
      tax_identifier_last4 = v_identifier_last4,
      onboarding_draft = '{}'::jsonb,
      onboarding_status = CASE WHEN v_status = 'pending_review' THEN 'pending_review' ELSE 'in_progress' END,
      onboarding_current_step = CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'business_verification' END,
      updated_at = now()
  WHERE id = v_user_id;

  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'business_verification',
    CASE WHEN v_status = 'verified' THEN 'verified' WHEN v_status = 'failed' THEN 'failed' ELSE 'submitted' END,
    v_status,
    jsonb_build_object('verification_id', v_verification_id, 'trust_score', v_score, 'tax_identifier_required', v_identifier_required)
  );

  RETURN jsonb_build_object(
    'success', true,
    'verification_id', v_verification_id,
    'status', v_status,
    'trust_score', v_score,
    'tax_identifier_required', v_identifier_required,
    'next_step', CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'manual_review' END
  );
END;
$function$;

GRANT EXECUTE ON FUNCTION public.reveal_my_tax_identifier() TO authenticated;

COMMIT;

-- ==========================================================================
-- Source: 20260720000018_business_name_availability_check.sql
-- ==========================================================================

-- Advisory business-name check, matching the username pattern (20260720000015) in spirit --
-- but NOT its enforcement. Product decision: unlike a username (a login identifier that must
-- be unique), a legal business name legitimately collides in the real world -- two unrelated
-- tenants can both be "Downtown Grill LLC" -- so this is warn-only. There is no unique
-- constraint on business_verifications.legal_business_name, and submit_business_verification()
-- is untouched by this migration: a duplicate name still submits successfully.
--
-- is_business_name_available() is the same live pre-check shape as
-- is_username_available()/resolve_username_email() (case-insensitive, self-excluding so a
-- tenant resubmitting their own name isn't flagged against themselves) -- the frontend uses it
-- to show a soft "a business with this name already exists -- is this you?" nudge on the
-- Business Information step, without blocking Next/Submit.

BEGIN;

-- A separate session applied the original hard-block draft of this migration before it could
-- be rewritten (the unique index + the RAISE EXCEPTION in submit_business_verification()).
-- Undo both explicitly rather than assuming a clean base -- this migration is now the
-- corrective version, not a fresh one.
DROP INDEX IF EXISTS public.business_verifications_legal_name_unique;

CREATE INDEX IF NOT EXISTS idx_business_verifications_legal_name_lower
  ON public.business_verifications (lower(btrim(legal_business_name)));

CREATE OR REPLACE FUNCTION public.is_business_name_available(p_legal_name text)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_normalized text := lower(btrim(p_legal_name));
  v_caller uuid := auth.uid();
BEGIN
  IF v_normalized IS NULL OR v_normalized = '' THEN
    RETURN true;
  END IF;

  RETURN NOT EXISTS (
    SELECT 1 FROM public.business_verifications
    WHERE lower(btrim(legal_business_name)) = v_normalized
      AND (v_caller IS NULL OR user_id IS DISTINCT FROM v_caller)
  );
END;
$function$;

GRANT EXECUTE ON FUNCTION public.is_business_name_available(text) TO authenticated;

-- Restore submit_business_verification() to the 20260720000017 body (no name-based block) --
-- the separate session's applied draft added a RAISE EXCEPTION here that must come back out.
CREATE OR REPLACE FUNCTION public.submit_business_verification(p_payload jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_run_id UUID;
  v_legal_name TEXT;
  v_business_type TEXT;
  v_identifier_type TEXT;
  v_identifier_required BOOLEAN;
  v_full_identifier TEXT;
  v_identifier_last4 TEXT;
  v_email TEXT;
  v_phone TEXT;
  v_website TEXT;
  v_provider TEXT;
  v_score INTEGER := 0;
  v_status TEXT;
  v_verification_id UUID;
  v_settings RECORD;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT ein_verification_enabled, ssn_verification_enabled
  INTO v_settings
  FROM public.platform_onboarding_settings
  WHERE id = true;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  v_legal_name := NULLIF(btrim(p_payload->>'legalName'), '');
  v_business_type := COALESCE(NULLIF(btrim(p_payload->>'businessType'), ''), 'llc');
  v_identifier_type := COALESCE(NULLIF(btrim(p_payload->>'identifierType'), ''), public.required_tax_identifier_type_for_business_type(v_business_type));
  v_identifier_required := CASE
    WHEN v_identifier_type = 'ein' THEN COALESCE(v_settings.ein_verification_enabled, true)
    WHEN v_identifier_type = 'ssn' THEN COALESCE(v_settings.ssn_verification_enabled, true)
    ELSE true
  END;
  v_full_identifier := CASE WHEN v_identifier_required THEN regexp_replace(COALESCE(p_payload->>'taxIdentifier', ''), '\D', '', 'g') ELSE NULL END;
  v_identifier_last4 := CASE WHEN v_identifier_required THEN public.mask_tax_identifier(p_payload->>'taxIdentifier') ELSE NULL END;
  v_email := NULLIF(btrim(p_payload->>'email'), '');
  v_phone := NULLIF(btrim(p_payload->>'phone'), '');
  v_website := NULLIF(btrim(p_payload->>'website'), '');

  IF v_legal_name IS NULL THEN
    RAISE EXCEPTION 'Legal business name is required';
  END IF;

  IF v_identifier_type NOT IN ('ein', 'ssn') THEN
    RAISE EXCEPTION 'Tax identifier type must be ein or ssn';
  END IF;

  IF v_identifier_type IS DISTINCT FROM public.required_tax_identifier_type_for_business_type(v_business_type) THEN
    RAISE EXCEPTION 'Tax identifier type % is not allowed for business type %', v_identifier_type, v_business_type;
  END IF;

  IF v_identifier_required AND length(COALESCE(v_identifier_last4, '')) <> 4 THEN
    RAISE EXCEPTION 'Valid tax identifier is required';
  END IF;

  IF v_email IS NULL OR position('@' in v_email) = 0 THEN
    RAISE EXCEPTION 'A valid business email is required';
  END IF;

  IF length(regexp_replace(COALESCE(v_phone, ''), '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid business phone number is required';
  END IF;

  v_score := CASE
    WHEN NOT v_identifier_required THEN 60
    WHEN v_identifier_type = 'ein' THEN 50
    ELSE 45
  END;
  IF v_email LIKE '%@%' THEN v_score := v_score + 10; END IF;
  IF length(regexp_replace(v_phone, '\D', '', 'g')) >= 10 THEN v_score := v_score + 10; END IF;
  IF v_website IS NOT NULL THEN v_score := v_score + 10; END IF;
  v_score := LEAST(v_score, 100);
  v_status := CASE WHEN v_score >= 80 THEN 'verified' WHEN v_score >= 50 THEN 'pending_review' ELSE 'failed' END;
  v_provider := CASE
    WHEN NOT v_identifier_required THEN v_identifier_type || '_verification_disabled_by_platform'
    WHEN v_identifier_type = 'ein' THEN 'global_database_kyb'
    ELSE 'searchbug_ssn'
  END;

  INSERT INTO public.business_verifications (
    user_id,
    legal_business_name,
    business_type,
    identifier_type,
    identifier_last4,
    provider_name,
    provider_reference_id,
    verification_status,
    trust_score,
    metadata,
    reviewed_by,
    reviewed_at,
    rejection_reason,
    updated_at
  )
  VALUES (
    v_user_id,
    v_legal_name,
    v_business_type,
    v_identifier_type,
    v_identifier_last4,
    v_provider,
    CASE WHEN v_identifier_required THEN 'provider-ready-' || replace(gen_random_uuid()::text, '-', '') ELSE 'verification-disabled' END,
    v_status,
    v_score,
    jsonb_build_object(
      'email', v_email,
      'phone', v_phone,
      'website', v_website,
      'tax_identifier_required', v_identifier_required,
      'ein_verification_enabled', COALESCE(v_settings.ein_verification_enabled, true),
      'ssn_verification_enabled', COALESCE(v_settings.ssn_verification_enabled, true),
      'provider_mode', CASE WHEN v_identifier_required THEN 'simulation_until_provider_keys_configured' ELSE 'disabled_by_platform_admin' END
    ),
    NULL,
    NULL,
    NULL,
    now()
  )
  ON CONFLICT (user_id) WHERE user_id IS NOT NULL DO UPDATE
  SET legal_business_name = EXCLUDED.legal_business_name,
      business_type = EXCLUDED.business_type,
      identifier_type = EXCLUDED.identifier_type,
      identifier_last4 = EXCLUDED.identifier_last4,
      provider_name = EXCLUDED.provider_name,
      provider_reference_id = EXCLUDED.provider_reference_id,
      verification_status = EXCLUDED.verification_status,
      trust_score = EXCLUDED.trust_score,
      metadata = EXCLUDED.metadata,
      reviewed_by = NULL,
      reviewed_at = NULL,
      rejection_reason = NULL,
      updated_at = now()
  RETURNING id INTO v_verification_id;

  IF v_identifier_required AND length(COALESCE(v_full_identifier, '')) > 0 THEN
    PERFORM public.store_tax_identifier_secret(v_verification_id, v_identifier_type, v_full_identifier);
  END IF;

  UPDATE public.profiles
  SET business_verification_status = v_status,
      business_verification_score = v_score,
      business_verification_provider = v_provider,
      business_verified_at = CASE WHEN v_status = 'verified' THEN now() ELSE NULL END,
      business_type = v_business_type,
      tax_identifier_type = v_identifier_type,
      tax_identifier_last4 = v_identifier_last4,
      onboarding_draft = '{}'::jsonb,
      onboarding_status = CASE WHEN v_status = 'pending_review' THEN 'pending_review' ELSE 'in_progress' END,
      onboarding_current_step = CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'business_verification' END,
      updated_at = now()
  WHERE id = v_user_id;

  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'business_verification',
    CASE WHEN v_status = 'verified' THEN 'verified' WHEN v_status = 'failed' THEN 'failed' ELSE 'submitted' END,
    v_status,
    jsonb_build_object('verification_id', v_verification_id, 'trust_score', v_score, 'tax_identifier_required', v_identifier_required)
  );

  RETURN jsonb_build_object(
    'success', true,
    'verification_id', v_verification_id,
    'status', v_status,
    'trust_score', v_score,
    'tax_identifier_required', v_identifier_required,
    'next_step', CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'manual_review' END
  );
END;
$function$;

COMMIT;

-- ==========================================================================
-- Source: 20260720000019_remove_check_payment_method.sql
-- ==========================================================================

-- Removes the Check payment method (added in 20260720000016_check_payment_method.sql).
-- Product decision: Card + ACH cover it; the manual admin-confirmation workflow Check
-- required wasn't worth keeping. No profiles.payment_method_type = 'check' rows exist yet
-- (verified before writing this migration), so this is a clean revert, not a data migration.
--
-- Drops confirm_check_payment_received() -- its only caller (the admin "Confirm Check
-- Received" button in PlatformOrganizations.jsx) has been removed, and create-checkout-session
-- no longer has a 'check' branch to set profiles.payment_method_type = 'check' in the first
-- place. Reverts the payment_method_type CHECK constraint to its pre-20260720000016 shape.

BEGIN;

DROP FUNCTION IF EXISTS public.confirm_check_payment_received(uuid, text);

ALTER TABLE public.profiles
  DROP CONSTRAINT profiles_payment_method_type_check;
ALTER TABLE public.profiles
  ADD CONSTRAINT profiles_payment_method_type_check
  CHECK (payment_method_type IS NULL OR payment_method_type = ANY (ARRAY['card'::text, 'ach'::text, 'free_plan'::text, 'mock_subscription'::text, 'stripe_subscription'::text, 'trial_coupon'::text]));

COMMIT;

-- ==========================================================================
-- Source: 20260720000020_hierarchy_review_gate.sql
-- ==========================================================================

-- Adds a platform-admin review gate between payment and organization creation. Today,
-- performOnboarding() calls setup_onboarding_hierarchy() directly the moment payment
-- succeeds, creating organizations/brands/locations immediately with no review. New flow:
-- the tenant's hierarchy gets SUBMITTED for review (stored, not yet applied); a platform
-- admin Approves (runs the real setup_onboarding_hierarchy), Rejects (terminal, same
-- vocabulary as reject_business_verification), or Requests Resubmit (sends the tenant back
-- to the Hierarchy step -- no re-payment needed, payment_verified is untouched).
--
-- setup_onboarding_hierarchy() already has an admin-bypass auth check
-- (`auth.uid() != p_user_id AND get_auth_role() != 'platform_admin'`), so
-- approve_onboarding_hierarchy() can call it directly on the tenant's behalf without any
-- change to that function -- it was already built to allow this.
--
-- Deliberate scope decision: submit_onboarding_hierarchy_for_review() only re-checks the
-- same top-level preconditions setup_onboarding_hierarchy() checks (business verified,
-- payment verified) plus a non-empty-array sanity check. It does NOT duplicate that
-- function's full per-field validation (org/brand/location names, required addresses, etc.)
-- -- the frontend's own validateHierarchy() already blocks submission of incomplete data in
-- the normal path, and if malformed data somehow reaches approval anyway,
-- approve_onboarding_hierarchy() surfaces setup_onboarding_hierarchy()'s exception to the
-- admin, who can Reject or Request Resubmit with a note. Duplicating ~150 lines of nested
-- validation here was judged not worth the maintenance burden of keeping two copies in sync.

BEGIN;

CREATE TABLE public.onboarding_hierarchy_submissions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES public.profiles(id),
  hierarchy_payload JSONB NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending_review'
    CHECK (status IN ('pending_review', 'approved', 'rejected', 'failed')),
  rejection_reason TEXT,
  reviewed_by UUID,
  reviewed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (user_id)
);

CREATE INDEX idx_onboarding_hierarchy_submissions_status ON public.onboarding_hierarchy_submissions(status);

-- Internal-only table, same grant shape as onboarding_admin_actions: no direct
-- SELECT/INSERT/UPDATE/DELETE for anon/authenticated -- access only through the
-- SECURITY DEFINER RPCs below.

ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS hierarchy_review_status TEXT;
ALTER TABLE public.profiles
  ADD CONSTRAINT profiles_hierarchy_review_status_check
  CHECK (hierarchy_review_status IS NULL OR hierarchy_review_status IN ('pending_review', 'approved', 'rejected', 'failed'));

CREATE OR REPLACE FUNCTION public.submit_onboarding_hierarchy_for_review(p_user_id uuid, p_hierarchy jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_business_status TEXT;
  v_payment_verified BOOLEAN;
  v_pending_payment_metadata JSONB;
  v_submission_id UUID;
  v_run_id UUID;
BEGIN
  IF auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Not authorized to submit hierarchy for another user';
  END IF;

  SELECT business_verification_status, payment_verified, pending_payment_metadata
  INTO v_business_status, v_payment_verified, v_pending_payment_metadata
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE
     AND COALESCE(v_pending_payment_metadata->>'provider', '') NOT IN ('free_plan', 'stripe') THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' OR jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  INSERT INTO public.onboarding_hierarchy_submissions (user_id, hierarchy_payload, status, rejection_reason, reviewed_by, reviewed_at)
  VALUES (p_user_id, p_hierarchy, 'pending_review', NULL, NULL, NULL)
  ON CONFLICT (user_id) DO UPDATE
  SET hierarchy_payload = EXCLUDED.hierarchy_payload,
      status = 'pending_review',
      rejection_reason = NULL,
      reviewed_by = NULL,
      reviewed_at = NULL,
      updated_at = now()
  RETURNING id INTO v_submission_id;

  UPDATE public.profiles
  SET hierarchy_review_status = 'pending_review',
      onboarding_status = 'pending_review',
      onboarding_current_step = 'hierarchy_review',
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.notifications(user_id, type, title, message, is_read)
  SELECT p.id, 'system', 'Tenant workspace pending review',
         COALESCE(p.full_name, p.email, 'A tenant') || ' submitted an organization hierarchy for review.', false
  FROM public.profiles p WHERE p.role = 'platform_admin';

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
    PERFORM public.record_onboarding_event(v_run_id, p_user_id, 'hierarchy_setup', 'submitted', 'pending_review', jsonb_build_object('submission_id', v_submission_id));
  EXCEPTION WHEN undefined_function THEN
    NULL;
  END;

  RETURN jsonb_build_object('success', true, 'status', 'pending_review', 'submission_id', v_submission_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.approve_onboarding_hierarchy(p_user_id uuid, p_note text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_hierarchy JSONB;
  v_result JSONB;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  SELECT hierarchy_payload INTO v_hierarchy
  FROM public.onboarding_hierarchy_submissions
  WHERE user_id = p_user_id AND status = 'pending_review';

  IF v_hierarchy IS NULL THEN
    RAISE EXCEPTION 'No pending hierarchy submission for this tenant';
  END IF;

  v_result := public.setup_onboarding_hierarchy(p_user_id, v_hierarchy);

  UPDATE public.onboarding_hierarchy_submissions
  SET status = 'approved', reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
  WHERE user_id = p_user_id AND status = 'pending_review';

  UPDATE public.profiles SET hierarchy_review_status = 'approved' WHERE id = p_user_id;

  INSERT INTO public.notifications(user_id, organization_id, type, title, message, is_read)
  SELECT p_user_id, (v_result->>'primary_org_id')::uuid, 'system', 'Workspace approved',
         'Your organization workspace has been approved and created.', false;

  RETURN v_result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.reject_onboarding_hierarchy(p_user_id uuid, p_reason text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_run_id UUID;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A rejection reason is required';
  END IF;

  UPDATE public.onboarding_hierarchy_submissions
  SET status = 'rejected', rejection_reason = p_reason, reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
  WHERE user_id = p_user_id AND status = 'pending_review';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No pending hierarchy submission for this tenant';
  END IF;

  UPDATE public.profiles
  SET hierarchy_review_status = 'rejected',
      onboarding_status = 'blocked',
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.notifications(user_id, type, title, message, is_read)
  VALUES (p_user_id, 'system', 'Workspace setup rejected', p_reason, false);

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
    PERFORM public.record_onboarding_event(v_run_id, p_user_id, 'hierarchy_setup', 'admin_rejected', 'rejected', jsonb_build_object('actor_user_id', auth.uid(), 'reason', p_reason));
  EXCEPTION WHEN undefined_function THEN
    NULL;
  END;

  RETURN jsonb_build_object('success', true, 'status', 'rejected');
END;
$function$;

CREATE OR REPLACE FUNCTION public.request_onboarding_hierarchy_resubmit(p_user_id uuid, p_reason text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_run_id UUID;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Tell the tenant what needs to change';
  END IF;

  UPDATE public.onboarding_hierarchy_submissions
  SET status = 'failed', rejection_reason = p_reason, reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
  WHERE user_id = p_user_id AND status = 'pending_review';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No pending hierarchy submission for this tenant';
  END IF;

  UPDATE public.profiles
  SET hierarchy_review_status = 'failed',
      onboarding_status = 'blocked',
      onboarding_current_step = 'hierarchy_setup',
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.notifications(user_id, type, title, message, is_read)
  VALUES (p_user_id, 'system', 'Workspace setup needs changes', p_reason, false);

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
    PERFORM public.record_onboarding_event(v_run_id, p_user_id, 'hierarchy_setup', 'more_info_requested', 'failed', jsonb_build_object('actor_user_id', auth.uid(), 'reason', p_reason));
  EXCEPTION WHEN undefined_function THEN
    NULL;
  END;

  RETURN jsonb_build_object('success', true, 'status', 'failed');
END;
$function$;

CREATE OR REPLACE FUNCTION public.platform_hierarchy_review_queue()
RETURNS SETOF public.onboarding_hierarchy_submissions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles p WHERE p.id = auth.uid() AND p.role = 'platform_admin'
  ) THEN
    RAISE EXCEPTION 'platform_admin role required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT * FROM public.onboarding_hierarchy_submissions
  WHERE status IN ('pending_review', 'rejected', 'failed')
  ORDER BY created_at DESC
  LIMIT 200;
END;
$$;

GRANT EXECUTE ON FUNCTION public.submit_onboarding_hierarchy_for_review(uuid, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.approve_onboarding_hierarchy(uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.reject_onboarding_hierarchy(uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.request_onboarding_hierarchy_resubmit(uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.platform_hierarchy_review_queue() TO authenticated;

COMMIT;

-- ==========================================================================
-- Source: 20260720000021_onboarding_state_includes_hierarchy_submission.sql
-- ==========================================================================

-- Small follow-up to 20260720000020_hierarchy_review_gate.sql: the frontend needs the
-- rejection/resubmit reason text to show the tenant why their hierarchy submission was sent
-- back. profiles.hierarchy_review_status (the status itself) is already visible via the
-- normal profile load, but the reason text lives on onboarding_hierarchy_submissions.
-- Extends get_my_onboarding_state() with a 'hierarchy_submission' key, same pattern already
-- used there for business_verification/payment_method/coupon_redemption.

BEGIN;

CREATE OR REPLACE FUNCTION public.get_my_onboarding_state()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_profile JSONB;
  v_verification JSONB;
  v_payment JSONB;
  v_coupon JSONB;
  v_run JSONB;
  v_hierarchy JSONB;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT to_jsonb(p) INTO v_profile
  FROM public.profiles p
  WHERE p.id = v_user_id;

  SELECT to_jsonb(bv) INTO v_verification
  FROM public.business_verifications bv
  WHERE bv.user_id = v_user_id
  ORDER BY bv.created_at DESC
  LIMIT 1;

  SELECT to_jsonb(pm) INTO v_payment
  FROM public.onboarding_payment_methods pm
  WHERE pm.user_id = v_user_id
  ORDER BY pm.created_at DESC
  LIMIT 1;

  SELECT to_jsonb(r) INTO v_coupon
  FROM public.onboarding_coupon_redemptions r
  WHERE r.user_id = v_user_id
    AND r.status = 'applied'
  ORDER BY r.redeemed_at DESC
  LIMIT 1;

  SELECT to_jsonb(w) INTO v_run
  FROM public.onboarding_workflow_runs w
  WHERE w.user_id = v_user_id
  ORDER BY w.started_at DESC
  LIMIT 1;

  SELECT jsonb_build_object('status', h.status, 'rejection_reason', h.rejection_reason) INTO v_hierarchy
  FROM public.onboarding_hierarchy_submissions h
  WHERE h.user_id = v_user_id
  ORDER BY h.created_at DESC
  LIMIT 1;

  RETURN jsonb_build_object(
    'profile', v_profile,
    'workflow_run', v_run,
    'business_verification', v_verification,
    'payment_method', v_payment,
    'coupon_redemption', v_coupon,
    'hierarchy_submission', v_hierarchy
  );
END;
$function$;

COMMIT;

-- ==========================================================================
-- Source: 20260720000022_bank_account_hierarchy_assignment.sql
-- ==========================================================================

-- Task 4 (banking page redesign, part 1): each onboarding bank account must be assigned to
-- exactly one node of the tenant's own hierarchy (organization, brand, or location), selected
-- from a dropdown the frontend sources from fetch_user_access_tree() -- the same RPC the
-- ContextSwitcher already uses. organization_id already exists on onboarding_bank_accounts but
-- was never populated; this adds brand_id/location_id and rewrites submit_onboarding_bank_account
-- to validate the chosen node against the caller's own membership rows (never trust the client
-- for scope) and stamp all three columns using the standard NULL-tier pattern already used
-- throughout the schema: org-level = brand_id/location_id NULL, brand-level = location_id NULL,
-- location-level = all three set.

BEGIN;

ALTER TABLE public.onboarding_bank_accounts
  ADD COLUMN brand_id UUID REFERENCES public.brands(brand_id) ON DELETE SET NULL,
  ADD COLUMN location_id UUID REFERENCES public.locations(id) ON DELETE SET NULL;

ALTER TABLE public.onboarding_bank_accounts
  ADD CONSTRAINT onboarding_bank_accounts_scope_tier_check
  CHECK (
    (location_id IS NULL OR (brand_id IS NOT NULL AND organization_id IS NOT NULL))
    AND (brand_id IS NULL OR organization_id IS NOT NULL)
  );

CREATE INDEX idx_onboarding_bank_accounts_brand ON public.onboarding_bank_accounts(brand_id) WHERE brand_id IS NOT NULL;
CREATE INDEX idx_onboarding_bank_accounts_location ON public.onboarding_bank_accounts(location_id) WHERE location_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public.submit_onboarding_bank_account(p_payload jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_bank_id UUID;
  v_run_id UUID;
  v_account_number TEXT;
  v_routing_number TEXT;
  v_is_default BOOLEAN;
  v_billing_source TEXT;
  v_scope TEXT;
  v_scope_id UUID;
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  v_account_number := regexp_replace(COALESCE(p_payload->>'account_number', ''), '[^0-9]', '', 'g');
  v_routing_number := regexp_replace(COALESCE(p_payload->>'routing_number', ''), '[^0-9]', '', 'g');
  v_is_default := COALESCE((p_payload->>'is_default')::boolean, false)
    OR NOT EXISTS (
      SELECT 1 FROM public.onboarding_bank_accounts
      WHERE user_id = v_user_id AND status <> 'inactive'
    );
  v_billing_source := COALESCE(NULLIF(p_payload->>'billing_address_source', ''), 'business');
  v_scope := NULLIF(p_payload->>'assignment_scope', '');
  v_scope_id := NULLIF(p_payload->>'assignment_id', '')::uuid;

  IF NULLIF(btrim(COALESCE(p_payload->>'bank_name', '')), '') IS NULL THEN
    RAISE EXCEPTION 'Bank name is required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_payload->>'account_holder_name', '')), '') IS NULL THEN
    RAISE EXCEPTION 'Account holder name is required';
  END IF;

  IF COALESCE(p_payload->>'account_type', '') NOT IN ('checking', 'savings') THEN
    RAISE EXCEPTION 'Account type must be checking or savings';
  END IF;

  IF length(v_routing_number) <> 9 THEN
    RAISE EXCEPTION 'Routing number must be 9 digits';
  END IF;

  IF length(v_account_number) < 4 OR length(v_account_number) > 17 THEN
    RAISE EXCEPTION 'Account number must be between 4 and 17 digits';
  END IF;

  IF v_scope IS NULL OR v_scope_id IS NULL THEN
    RAISE EXCEPTION 'Select which organization, brand, or location this bank account belongs to';
  END IF;

  IF v_scope = 'organization' THEN
    SELECT om.organization_id INTO v_org_id
    FROM public.organization_members om
    WHERE om.user_id = v_user_id AND om.organization_id = v_scope_id;

    IF v_org_id IS NULL THEN
      RAISE EXCEPTION 'You do not have access to that organization';
    END IF;
  ELSIF v_scope = 'brand' THEN
    SELECT b.organization_id, b.brand_id INTO v_org_id, v_brand_id
    FROM public.brand_members bm
    JOIN public.brands b ON b.brand_id = bm.brand_id
    WHERE bm.user_id = v_user_id AND bm.brand_id = v_scope_id;

    IF v_brand_id IS NULL THEN
      RAISE EXCEPTION 'You do not have access to that brand';
    END IF;
  ELSIF v_scope = 'location' THEN
    SELECT l.organization_id, l.brand_id, l.id INTO v_org_id, v_brand_id, v_location_id
    FROM public.location_members lm
    JOIN public.locations l ON l.id = lm.location_id
    WHERE lm.user_id = v_user_id AND lm.location_id = v_scope_id;

    IF v_location_id IS NULL THEN
      RAISE EXCEPTION 'You do not have access to that location';
    END IF;
  ELSE
    RAISE EXCEPTION 'Assignment scope must be organization, brand, or location';
  END IF;

  IF v_is_default THEN
    UPDATE public.onboarding_bank_accounts
    SET is_default = false
    WHERE user_id = v_user_id AND status <> 'inactive';
  END IF;

  INSERT INTO public.onboarding_bank_accounts (
    user_id,
    organization_id,
    brand_id,
    location_id,
    bank_name,
    account_holder_name,
    account_type,
    nickname,
    routing_number_last4,
    account_number_last4,
    billing_address_source,
    billing_address_line1,
    billing_address_line2,
    billing_address_city,
    billing_address_state,
    billing_address_postal_code,
    billing_address_country,
    is_default,
    status,
    metadata
  )
  VALUES (
    v_user_id,
    v_org_id,
    v_brand_id,
    v_location_id,
    btrim(p_payload->>'bank_name'),
    btrim(p_payload->>'account_holder_name'),
    p_payload->>'account_type',
    NULLIF(btrim(COALESCE(p_payload->>'nickname', '')), ''),
    right(v_routing_number, 4),
    right(v_account_number, 4),
    v_billing_source,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_line1', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_line2', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_city', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_state', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_postal_code', '')), '') END,
    CASE WHEN v_billing_source = 'custom' THEN NULLIF(btrim(COALESCE(p_payload->>'billing_address_country', '')), '') END,
    v_is_default,
    'pending_signature',
    COALESCE(p_payload->'metadata', '{}'::jsonb)
  )
  RETURNING id INTO v_bank_id;

  PERFORM public.store_onboarding_bank_secret(v_bank_id, v_account_number, v_routing_number);

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'bank_authorization',
    'bank_account_submitted',
    'pending_signature',
    jsonb_build_object('onboarding_bank_account_id', v_bank_id)
  );

  RETURN (
    SELECT jsonb_build_object(
      'success', true,
      'bank_account', jsonb_build_object(
        'id', id,
        'organization_id', organization_id,
        'brand_id', brand_id,
        'location_id', location_id,
        'bank_name', bank_name,
        'account_holder_name', account_holder_name,
        'account_type', account_type,
        'nickname', nickname,
        'routing_number_last4', routing_number_last4,
        'account_number_last4', account_number_last4,
        'billing_address_source', billing_address_source,
        'is_default', is_default,
        'status', status
      )
    )
    FROM public.onboarding_bank_accounts
    WHERE id = v_bank_id
  );
END;
$function$;

COMMIT;

-- ==========================================================================
-- Source: 20260720000023_fix_wastage_soft_delete_and_product_vendor_name.sql
-- ==========================================================================

BEGIN;

-- The inventory page reads wastage_logs through the soft-delete entity client.
ALTER TABLE public.wastage_logs
  ADD COLUMN IF NOT EXISTS deleted_at timestamptz,
  ADD COLUMN IF NOT EXISTS deleted_by uuid REFERENCES auth.users(id);

CREATE INDEX IF NOT EXISTS idx_wastage_logs_deleted_at
  ON public.wastage_logs(deleted_at)
  WHERE deleted_at IS NOT NULL;

-- Recreate the product catalog RPC without the removed products.preferred_vendor_id
-- column and include vendor names for the Products table display.
DROP FUNCTION IF EXISTS public.get_product_catalog(uuid, uuid, uuid, text, text, integer, integer);

CREATE OR REPLACE FUNCTION public.get_product_catalog(
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_search text DEFAULT NULL,
  p_sort_by text DEFAULT 'name',
  p_page integer DEFAULT 0,
  p_page_size integer DEFAULT 50
)
RETURNS TABLE (
  id uuid,
  product_id text,
  name text,
  description text,
  category text,
  accounting_category text,
  category_confidence numeric,
  category_source text,
  category_review_status text,
  suggested_category text,
  suggested_category_type text,
  suggested_accounting_category text,
  category_reason text,
  is_inventoried boolean,
  is_tax_exempt boolean,
  report_by_unit text,
  base_unit text,
  latest_price numeric,
  location_specific boolean,
  organization_id uuid,
  brand_id uuid,
  location_id uuid,
  created_at timestamptz,
  item_count bigint,
  vendor_item_count bigint,
  inventory_item_id uuid,
  vendor_name text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_page integer := GREATEST(COALESCE(p_page, 0), 0);
  v_page_size integer := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 100);
  v_sort_by text := COALESCE(NULLIF(p_sort_by, ''), 'name');
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  RETURN QUERY
  WITH product_scope AS (
    SELECT p.*
    FROM public.products p
    WHERE p.organization_id = v_org_id
      AND p.deleted_at IS NULL
      AND (p_brand_id IS NULL OR p.brand_id IS NOT DISTINCT FROM p_brand_id)
      AND (p_location_id IS NULL OR p.location_id IS NOT DISTINCT FROM p_location_id)
      AND public.reference_scope_visible(p.organization_id, p.brand_id, p.location_id, p.deleted_at)
      AND (
        p_search IS NULL
        OR p.name ILIKE '%' || p_search || '%'
        OR COALESCE(p.description, '') ILIKE '%' || p_search || '%'
        OR COALESCE(p.product_id, '') ILIKE '%' || p_search || '%'
      )
  )
  SELECT
    p.id,
    p.product_id,
    p.name,
    p.description,
    p.category,
    p.accounting_category,
    p.category_confidence,
    p.category_source,
    p.category_review_status,
    p.suggested_category,
    p.suggested_category_type,
    p.suggested_accounting_category,
    p.category_reason,
    p.is_inventoried,
    p.is_tax_exempt,
    p.report_by_unit,
    p.base_unit,
    p.latest_price,
    p.location_specific,
    p.organization_id,
    p.brand_id,
    p.location_id,
    p.created_at,
    COALESCE(vendor_info.vendor_item_count, 0) AS item_count,
    COALESCE(vendor_info.vendor_item_count, 0) AS vendor_item_count,
    inv.id AS inventory_item_id,
    vendor_info.vendor_name
  FROM product_scope p
  LEFT JOIN LATERAL (
    SELECT
      count(DISTINCT vim.vendor_item_id)::bigint AS vendor_item_count,
      string_agg(DISTINCT v.name, ', ' ORDER BY v.name) AS vendor_name
    FROM public.vendor_item_mappings vim
    JOIN public.vendor_items vi ON vi.id = vim.vendor_item_id
    LEFT JOIN public.vendors v ON v.id = vi.vendor_id
    WHERE vim.internal_product_id = p.id
      AND vim.organization_id = p.organization_id
      AND vi.organization_id = p.organization_id
  ) vendor_info ON true
  LEFT JOIN LATERAL (
    SELECT i.id
    FROM public.inventory i
    WHERE i.organization_id = p.organization_id
      AND i.deleted_at IS NULL
      AND (
        i.internal_product_id = p.id
        OR (NULLIF(i.product_id, '') IS NOT NULL AND i.product_id = p.product_id)
      )
      AND (p.location_id IS NULL OR i.location_id IS NULL OR i.location_id IS NOT DISTINCT FROM p.location_id)
    ORDER BY
      CASE WHEN i.internal_product_id = p.id THEN 0 ELSE 1 END,
      i.updated_at DESC NULLS LAST,
      i.created_at DESC NULLS LAST
    LIMIT 1
  ) inv ON true
  ORDER BY
    CASE WHEN v_sort_by = 'name' THEN p.name END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-name' THEN p.name END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'category' THEN p.category END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-category' THEN p.category END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'accounting_category' THEN p.accounting_category END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-accounting_category' THEN p.accounting_category END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'is_inventoried' THEN p.is_inventoried END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-is_inventoried' THEN p.is_inventoried END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'latest_price' THEN p.latest_price END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-latest_price' THEN p.latest_price END DESC NULLS LAST,
    p.name ASC NULLS LAST,
    p.created_at DESC NULLS LAST
  LIMIT v_page_size
  OFFSET v_page * v_page_size;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_product_catalog(uuid, uuid, uuid, text, text, integer, integer) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260720000024_repeatable_bank_signature_capture.sql
-- ==========================================================================

-- Task 5: capture_tenant_payment_signature previously set profiles.banking_onboarding_completed
-- = true after the FIRST signature captured for ANY bank account, which would kick the tenant
-- out of the banking page before they'd signed every account they'd added (Task 4 made adding
-- multiple accounts real). Onboarding should only finish once every non-inactive bank account
-- the tenant added has been signed. Rewritten to check that condition instead, and to return
-- 'all_accounts_signed' so the frontend knows whether to finalize or prompt for the next account.

BEGIN;

CREATE OR REPLACE FUNCTION public.capture_tenant_payment_signature(
  p_bank_account_id uuid,
  p_signer_full_name text,
  p_signer_title text,
  p_consent_version text,
  p_consent_text text,
  p_signature_sha256 text,
  p_signature_payload jsonb DEFAULT '{}'::jsonb,
  p_signature_storage_path text DEFAULT NULL::text,
  p_user_agent text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_auth_id UUID;
  v_run_id UUID;
  v_account public.onboarding_bank_accounts%ROWTYPE;
  v_all_signed BOOLEAN;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT *
  INTO v_account
  FROM public.onboarding_bank_accounts
  WHERE id = p_bank_account_id AND user_id = v_user_id AND status <> 'inactive';

  IF v_account.id IS NULL THEN
    RAISE EXCEPTION 'Bank account not found';
  END IF;

  IF NULLIF(btrim(COALESCE(p_signer_full_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Signer full name is required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_signature_sha256, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Signature hash is required';
  END IF;

  IF v_account.billing_address_source = 'custom' THEN
    IF NULLIF(btrim(v_account.billing_address_line1), '') IS NULL
       OR NULLIF(btrim(v_account.billing_address_city), '') IS NULL
       OR NULLIF(btrim(v_account.billing_address_state), '') IS NULL
       OR NULLIF(btrim(v_account.billing_address_postal_code), '') IS NULL
       OR NULLIF(btrim(v_account.billing_address_country), '') IS NULL THEN
      RAISE EXCEPTION 'A complete custom billing address (line 1, city, state, postal code, country) is required';
    END IF;
  END IF;

  UPDATE public.tenant_payment_authorizations
  SET status = 'revoked',
      updated_at = now()
  WHERE onboarding_bank_account_id = p_bank_account_id
    AND user_id = v_user_id
    AND status = 'active';

  INSERT INTO public.tenant_payment_authorizations (
    user_id,
    onboarding_bank_account_id,
    signer_full_name,
    signer_title,
    consent_version,
    consent_text,
    consent_accepted,
    signature_storage_path,
    signature_sha256,
    signature_payload,
    user_agent,
    status
  )
  VALUES (
    v_user_id,
    p_bank_account_id,
    btrim(p_signer_full_name),
    NULLIF(btrim(COALESCE(p_signer_title, '')), ''),
    COALESCE(NULLIF(btrim(p_consent_version), ''), 'tenant-bank-authorization-v1'),
    p_consent_text,
    true,
    NULLIF(btrim(COALESCE(p_signature_storage_path, '')), ''),
    btrim(p_signature_sha256),
    COALESCE(p_signature_payload, '{}'::jsonb),
    NULLIF(btrim(COALESCE(p_user_agent, '')), ''),
    'active'
  )
  RETURNING id INTO v_auth_id;

  UPDATE public.onboarding_bank_accounts
  SET status = 'authorized'
  WHERE id = p_bank_account_id;

  -- Onboarding is only "done" once every non-inactive account the tenant added has moved past
  -- pending_signature -- not after the first one, since Task 4 made multi-account real.
  SELECT NOT EXISTS (
    SELECT 1 FROM public.onboarding_bank_accounts
    WHERE user_id = v_user_id AND status = 'pending_signature'
  ) INTO v_all_signed;

  IF v_all_signed THEN
    UPDATE public.profiles
    SET banking_onboarding_completed = true,
        updated_at = now()
    WHERE id = v_user_id;
  END IF;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'bank_authorization',
    'signature_captured',
    'authorized',
    jsonb_build_object('onboarding_bank_account_id', p_bank_account_id, 'authorization_id', v_auth_id, 'all_accounts_signed', v_all_signed)
  );

  RETURN jsonb_build_object(
    'success', true,
    'authorization_id', v_auth_id,
    'bank_account_id', p_bank_account_id,
    'status', 'authorized',
    'all_accounts_signed', v_all_signed
  );
END;
$function$;

COMMIT;

-- ==========================================================================
-- Source: 20260720000025_usps_onboarding_address_validation_toggle.sql
-- ==========================================================================

-- Add a platform-level USPS address validation toggle and enforce it before
-- tenants submit address-bearing onboarding hierarchy payloads for review.

ALTER TABLE public.platform_onboarding_settings
  ADD COLUMN IF NOT EXISTS usps_address_validation_enabled boolean NOT NULL DEFAULT false;

UPDATE public.platform_onboarding_settings
SET usps_address_validation_enabled = COALESCE(usps_address_validation_enabled, false)
WHERE id = true;

CREATE OR REPLACE FUNCTION public.get_onboarding_verification_settings()
RETURNS jsonb
LANGUAGE sql
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT jsonb_build_object(
    'ein_verification_enabled', ein_verification_enabled,
    'ssn_verification_enabled', ssn_verification_enabled,
    'usps_address_validation_enabled', usps_address_validation_enabled,
    'updated_at', updated_at
  )
  FROM public.platform_onboarding_settings
  WHERE id = true;
$$;

DROP FUNCTION IF EXISTS public.update_onboarding_verification_settings(boolean, boolean);

CREATE OR REPLACE FUNCTION public.update_onboarding_verification_settings(
  p_ein_enabled boolean,
  p_ssn_enabled boolean,
  p_usps_address_validation_enabled boolean DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_settings public.platform_onboarding_settings%ROWTYPE;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  UPDATE public.platform_onboarding_settings
  SET ein_verification_enabled = COALESCE(p_ein_enabled, ein_verification_enabled),
      ssn_verification_enabled = COALESCE(p_ssn_enabled, ssn_verification_enabled),
      usps_address_validation_enabled = COALESCE(p_usps_address_validation_enabled, usps_address_validation_enabled)
  WHERE id = true
  RETURNING * INTO v_settings;

  RETURN jsonb_build_object(
    'success', true,
    'ein_verification_enabled', v_settings.ein_verification_enabled,
    'ssn_verification_enabled', v_settings.ssn_verification_enabled,
    'usps_address_validation_enabled', v_settings.usps_address_validation_enabled,
    'updated_at', v_settings.updated_at
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.submit_onboarding_hierarchy_for_review(p_user_id uuid, p_hierarchy jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_business_status text;
  v_payment_verified boolean;
  v_pending_payment_metadata jsonb;
  v_usps_address_validation_enabled boolean;
  v_submission_id uuid;
  v_run_id uuid;
BEGIN
  IF auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Not authorized to submit hierarchy for another user';
  END IF;

  SELECT business_verification_status, payment_verified, pending_payment_metadata
  INTO v_business_status, v_payment_verified, v_pending_payment_metadata
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE
     AND COALESCE(v_pending_payment_metadata->>'provider', '') NOT IN ('free_plan', 'stripe') THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' OR jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  SELECT usps_address_validation_enabled
  INTO v_usps_address_validation_enabled
  FROM public.platform_onboarding_settings
  WHERE id = true;

  IF COALESCE(v_usps_address_validation_enabled, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'USPS address validation must be enabled before address onboarding can be submitted';
  END IF;

  INSERT INTO public.onboarding_hierarchy_submissions (user_id, hierarchy_payload, status, rejection_reason, reviewed_by, reviewed_at)
  VALUES (p_user_id, p_hierarchy, 'pending_review', NULL, NULL, NULL)
  ON CONFLICT (user_id) DO UPDATE
  SET hierarchy_payload = EXCLUDED.hierarchy_payload,
      status = 'pending_review',
      rejection_reason = NULL,
      reviewed_by = NULL,
      reviewed_at = NULL,
      updated_at = now()
  RETURNING id INTO v_submission_id;

  UPDATE public.profiles
  SET hierarchy_review_status = 'pending_review',
      onboarding_status = 'pending_review',
      onboarding_current_step = 'hierarchy_review',
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.notifications(user_id, type, title, message, is_read)
  SELECT p.id, 'system', 'Tenant workspace pending review',
         COALESCE(p.full_name, p.email, 'A tenant') || ' submitted an organization hierarchy for review.', false
  FROM public.profiles p WHERE p.role = 'platform_admin';

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
    PERFORM public.record_onboarding_event(v_run_id, p_user_id, 'hierarchy_setup', 'submitted', 'pending_review', jsonb_build_object('submission_id', v_submission_id));
  EXCEPTION WHEN undefined_function THEN
    NULL;
  END;

  RETURN jsonb_build_object('success', true, 'status', 'pending_review', 'submission_id', v_submission_id);
END;
$function$;

GRANT EXECUTE ON FUNCTION public.update_onboarding_verification_settings(boolean, boolean, boolean) TO authenticated, service_role;

-- ==========================================================================
-- Source: 20260721000001_recipe_categories_phase1.sql
-- ==========================================================================

-- Phase 1: organization-scoped recipe_categories + list/create/count RPCs.
-- Also widens recipes.category CHECK so custom slugs can be stored later without breaking existing values.

BEGIN;

-- ---------------------------------------------------------------------------
-- 1) Drop restrictive recipes.category CHECK (keep column TEXT; preserve values)
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  v_conname text;
BEGIN
  SELECT c.conname
  INTO v_conname
  FROM pg_constraint c
  JOIN pg_class t ON t.oid = c.conrelid
  JOIN pg_namespace n ON n.oid = t.relnamespace
  WHERE n.nspname = 'public'
    AND t.relname = 'recipes'
    AND c.contype = 'c'
    AND pg_get_constraintdef(c.oid) ILIKE '%category%'
    AND pg_get_constraintdef(c.oid) ILIKE '%appetizer%'
  LIMIT 1;

  IF v_conname IS NOT NULL THEN
    EXECUTE format('ALTER TABLE public.recipes DROP CONSTRAINT %I', v_conname);
  END IF;
END;
$$;

-- Soft validation only: disallow blank category when provided.
ALTER TABLE public.recipes
  DROP CONSTRAINT IF EXISTS recipes_category_nonempty_check;

ALTER TABLE public.recipes
  ADD CONSTRAINT recipes_category_nonempty_check
  CHECK (category IS NULL OR length(trim(category)) > 0);

-- ---------------------------------------------------------------------------
-- 2) recipe_categories table
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.recipe_categories (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  slug TEXT NOT NULL,
  description TEXT,
  display_order INTEGER NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT true,
  is_system BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at TIMESTAMPTZ
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_recipe_categories_org_slug_active
  ON public.recipe_categories (organization_id, lower(slug))
  WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_recipe_categories_organization
  ON public.recipe_categories (organization_id)
  WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_recipe_categories_org_order
  ON public.recipe_categories (organization_id, display_order, name)
  WHERE deleted_at IS NULL;

ALTER TABLE public.recipe_categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.recipe_categories FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS recipe_categories_select ON public.recipe_categories;
CREATE POLICY recipe_categories_select ON public.recipe_categories
  FOR SELECT
  USING (organization_id = public.get_my_org() AND deleted_at IS NULL);

DROP POLICY IF EXISTS recipe_categories_manage ON public.recipe_categories;
CREATE POLICY recipe_categories_manage ON public.recipe_categories
  FOR ALL
  USING (organization_id = public.get_my_org() AND public.is_manager_or_above())
  WITH CHECK (organization_id = public.get_my_org() AND public.is_manager_or_above());

GRANT SELECT, INSERT, UPDATE ON public.recipe_categories TO authenticated;
GRANT ALL ON public.recipe_categories TO service_role;

-- ---------------------------------------------------------------------------
-- 3) Helpers
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.normalize_recipe_category_slug(p_value text)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT NULLIF(
    trim(both '_' FROM lower(regexp_replace(trim(COALESCE(p_value, '')), '[^a-zA-Z0-9]+', '_', 'g'))),
    ''
  );
$$;

CREATE OR REPLACE FUNCTION public.ensure_default_recipe_categories(p_organization_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF p_organization_id IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO public.recipe_categories (
    organization_id, name, slug, display_order, is_active, is_system
  )
  SELECT
    p_organization_id,
    d.name,
    d.slug,
    d.display_order,
    true,
    true
  FROM (
    VALUES
      ('Appetizer', 'appetizer', 10),
      ('Main Course', 'main_course', 20),
      ('Dessert', 'dessert', 30),
      ('Beverage', 'beverage', 40),
      ('Side', 'side', 50),
      ('Sauce', 'sauce', 60)
  ) AS d(name, slug, display_order)
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.recipe_categories rc
    WHERE rc.organization_id = p_organization_id
      AND lower(rc.slug) = d.slug
  );
END;
$$;

-- Seed defaults for all existing organizations (idempotent).
DO $$
DECLARE
  v_org uuid;
BEGIN
  FOR v_org IN SELECT id FROM public.organizations LOOP
    PERFORM public.ensure_default_recipe_categories(v_org);
  END LOOP;
END;
$$;

-- ---------------------------------------------------------------------------
-- 4) RPCs
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.list_recipe_categories(
  p_organization_id uuid DEFAULT NULL,
  p_include_inactive boolean DEFAULT false
)
RETURNS SETOF public.recipe_categories
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_org uuid := COALESCE(p_organization_id, public.get_my_org());
BEGIN
  IF auth.uid() IS NULL OR v_org IS NULL OR v_org <> public.get_my_org() THEN
    RAISE EXCEPTION 'Not authorized to list recipe categories';
  END IF;

  PERFORM public.ensure_default_recipe_categories(v_org);

  RETURN QUERY
  SELECT rc.*
  FROM public.recipe_categories rc
  WHERE rc.organization_id = v_org
    AND rc.deleted_at IS NULL
    AND (p_include_inactive OR rc.is_active)
  ORDER BY rc.display_order ASC, rc.name ASC;
END;
$$;

CREATE OR REPLACE FUNCTION public.create_recipe_category(
  p_name text,
  p_description text DEFAULT NULL,
  p_organization_id uuid DEFAULT NULL
)
RETURNS public.recipe_categories
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_org uuid := COALESCE(p_organization_id, public.get_my_org());
  v_name text := trim(COALESCE(p_name, ''));
  v_slug text;
  v_order integer;
  v_row public.recipe_categories;
BEGIN
  IF auth.uid() IS NULL OR v_org IS NULL OR v_org <> public.get_my_org() OR NOT public.is_manager_or_above() THEN
    RAISE EXCEPTION 'Not authorized to create recipe categories';
  END IF;

  IF v_name = '' THEN
    RAISE EXCEPTION 'Category name is required';
  END IF;

  v_slug := public.normalize_recipe_category_slug(v_name);
  IF v_slug IS NULL THEN
    RAISE EXCEPTION 'Category name is invalid';
  END IF;

  PERFORM public.ensure_default_recipe_categories(v_org);

  IF EXISTS (
    SELECT 1
    FROM public.recipe_categories rc
    WHERE rc.organization_id = v_org
      AND rc.deleted_at IS NULL
      AND (lower(rc.slug) = v_slug OR lower(rc.name) = lower(v_name))
  ) THEN
    RAISE EXCEPTION 'A category with this name already exists';
  END IF;

  SELECT COALESCE(MAX(rc.display_order), 0) + 10
  INTO v_order
  FROM public.recipe_categories rc
  WHERE rc.organization_id = v_org
    AND rc.deleted_at IS NULL;

  INSERT INTO public.recipe_categories (
    organization_id, name, slug, description, display_order, is_active, is_system
  )
  VALUES (
    v_org, v_name, v_slug, NULLIF(trim(COALESCE(p_description, '')), ''), v_order, true, false
  )
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_recipe_category_counts(
  p_organization_id uuid DEFAULT NULL
)
RETURNS TABLE (
  category_id uuid,
  slug text,
  name text,
  display_order integer,
  recipe_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_org uuid := COALESCE(p_organization_id, public.get_my_org());
BEGIN
  IF auth.uid() IS NULL OR v_org IS NULL OR v_org <> public.get_my_org() THEN
    RAISE EXCEPTION 'Not authorized to read recipe category counts';
  END IF;

  PERFORM public.ensure_default_recipe_categories(v_org);

  -- Count menu-style recipes only. Avoid recipe_types / recipe_type_id so this
  -- works on QA clones that have not yet received later recipe-type migrations.
  RETURN QUERY
  SELECT
    rc.id AS category_id,
    rc.slug,
    rc.name,
    rc.display_order,
    COALESCE(cnt.recipe_count, 0)::bigint AS recipe_count
  FROM public.recipe_categories rc
  LEFT JOIN LATERAL (
    SELECT COUNT(*)::bigint AS recipe_count
    FROM public.recipes r
    WHERE r.organization_id = v_org
      AND r.deleted_at IS NULL
      AND COALESCE(r.is_batch, false) = false
      AND COALESCE(r.category, '') IS DISTINCT FROM 'prepared_item'
      AND COALESCE(r.category, '') IS DISTINCT FROM 'beverage'
      AND lower(COALESCE(r.category, '')) = lower(rc.slug)
  ) cnt ON true
  WHERE rc.organization_id = v_org
    AND rc.deleted_at IS NULL
    AND rc.is_active
  ORDER BY rc.display_order ASC, rc.name ASC;
END;
$$;

