-- ==========================================================================
-- Source: 20260721000005_fix_product_category_type_and_accounting_sync.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.derive_product_category_type(
  p_accounting_category text,
  p_category text DEFAULT NULL,
  p_name text DEFAULT NULL
)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  WITH normalized AS (
    SELECT
      lower(COALESCE(p_accounting_category, '')) AS accounting,
      lower(COALESCE(p_category, '')) AS category,
      lower(COALESCE(p_name, '')) AS name
  ),
  combined AS (
    SELECT
      accounting,
      category,
      name,
      category || ' ' || name AS category_name,
      accounting || ' ' || category || ' ' || name AS text
    FROM normalized
  )
  SELECT CASE
    WHEN category_name ~ '(paper|packaging|container|cup|lid|straw|napkin|towel|bag|box|plate|foil|wrap|cleaning|cleaner|soap|detergent|sanitizer|bleach|sponge|scrubber|glove|apron|scraper|blade|pan|utensil|equipment|smallware|thermometer|restaurant supplies)'
      THEN 'Other'
    WHEN category_name ~ '(beer|ale|lager|ipa|stout|porter|pilsner|cider|seltzer|blue moon|modelo|corona|budweiser|bud light|coors|miller|heineken)'
      OR accounting = '5230'
      THEN 'Beer'
    WHEN category_name ~ '(wine|pinot|chardonnay|cabernet|merlot|sauvignon|riesling|prosecco|champagne|moscato|malbec|zinfandel|rose\b)'
      OR accounting = '5240'
      THEN 'Wine'
    WHEN category_name ~ '(liquor|spirit|vodka|gin|rum|tequila|whiskey|whisky|bourbon|scotch|brandy|cognac|mezcal|liqueur|triple sec)'
      OR accounting = '5220'
      THEN 'Liquor'
    WHEN category_name ~ '(n/a bev|na beverage|non[- ]?alcohol|beverage|soda|juice|tea|coffee|lemonade|energy drink|water|syrup, fontn|fountain|bib)'
      OR accounting = '5210'
      OR accounting = '1220'
      THEN 'N/A Bev'
    WHEN category_name ~ '(retail|merchandise|gift card|giftcard|apparel|shirt|hat|merch)'
      OR accounting = '5300'
      THEN 'Retail'
    WHEN accounting LIKE '51%'
      OR accounting LIKE '%food%'
      OR accounting IN ('food', 'food_cogs', '5100')
      OR category ~ '(dairy|produce|poultry|grocery|meat|seafood|bakery|bread|frozen|dry goods)'
      THEN 'Food'
    ELSE 'Other'
  END
  FROM combined;
$$;

CREATE OR REPLACE FUNCTION public.product_accounting_category_for_type(
  p_category_type text,
  p_category text DEFAULT NULL
)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE
    WHEN lower(COALESCE(p_category, '')) LIKE '%paper%'
      OR lower(COALESCE(p_category, '')) LIKE '%packaging%'
      OR lower(COALESCE(p_category, '')) LIKE '%cleaning%'
      OR lower(COALESCE(p_category, '')) LIKE '%restaurant supplies%'
      THEN '5110'
    WHEN p_category_type = 'Beer' THEN '5230'
    WHEN p_category_type = 'Wine' THEN '5240'
    WHEN p_category_type = 'Liquor' THEN '5220'
    WHEN p_category_type = 'N/A Bev' THEN '5210'
    WHEN p_category_type = 'Retail' THEN '5300'
    WHEN lower(COALESCE(p_category, '')) LIKE '%produce%' THEN '5150'
    WHEN lower(COALESCE(p_category, '')) LIKE '%dairy%' THEN '5140'
    WHEN lower(COALESCE(p_category, '')) LIKE '%poultry%' THEN '5120'
    WHEN lower(COALESCE(p_category, '')) LIKE '%seafood%' THEN '5130'
    WHEN lower(COALESCE(p_category, '')) LIKE '%frozen%' THEN '5160'
    WHEN lower(COALESCE(p_category, '')) LIKE '%grocery%' THEN '5170'
    WHEN lower(COALESCE(p_category, '')) LIKE '%dry goods%' THEN '5170'
    ELSE '5110'
  END;
$$;

CREATE OR REPLACE FUNCTION public.apply_product_category_suggestion(p_product_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_category_type text;
  v_accounting_category text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Product not found');
  END IF;

  IF NOT public.reference_scope_writable(
    v_product.organization_id,
    v_product.brand_id,
    v_product.location_id,
    v_product.deleted_at,
    'location_manager'
  ) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;

  IF NULLIF(trim(COALESCE(v_product.suggested_category, '')), '') IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'No category suggestion is available');
  END IF;

  v_category_type := public.derive_product_category_type(NULL, v_product.suggested_category, v_product.name);
  v_accounting_category := public.product_accounting_category_for_type(v_category_type, v_product.suggested_category);

  UPDATE public.products
     SET category = v_product.suggested_category,
         accounting_category = v_accounting_category,
         category_confidence = v_product.category_confidence,
         category_source = 'approved',
         category_review_status = 'approved',
         category_reviewed_at = now(),
         category_reviewed_by = auth.uid(),
         updated_at = now()
   WHERE id = p_product_id;

  UPDATE public.inventory i
     SET category = v_product.suggested_category,
         accounting_category = v_accounting_category,
         updated_at = now()
   WHERE i.internal_product_id = p_product_id
     AND i.deleted_at IS NULL;

  RETURN jsonb_build_object(
    'success', true,
    'product_id', p_product_id,
    'category', v_product.suggested_category,
    'accounting_category', v_accounting_category
  );
END;
$$;

UPDATE public.products p
   SET accounting_category = public.product_accounting_category_for_type(
         public.derive_product_category_type(NULL, p.category, p.name),
         p.category
       ),
       updated_at = now()
 WHERE p.deleted_at IS NULL
   AND NULLIF(trim(COALESCE(p.category, '')), '') IS NOT NULL
   AND p.accounting_category IS DISTINCT FROM public.product_accounting_category_for_type(
         public.derive_product_category_type(NULL, p.category, p.name),
         p.category
       )
   AND lower(p.category) ~ '(paper|packaging|cleaning supplies|restaurant supplies|produce|dairy|poultry|seafood|frozen|grocery|dry goods|beer|wine|liquor|n/a beverage|n/a bev|retail)';

UPDATE public.inventory i
   SET category = p.category,
       accounting_category = p.accounting_category,
       updated_at = now()
  FROM public.products p
 WHERE i.internal_product_id = p.id
   AND i.deleted_at IS NULL
   AND p.deleted_at IS NULL
   AND (
     i.category IS DISTINCT FROM p.category
     OR i.accounting_category IS DISTINCT FROM p.accounting_category
   );

GRANT EXECUTE ON FUNCTION public.apply_product_category_suggestion(uuid) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.derive_product_category_type(text, text, text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.product_accounting_category_for_type(text, text) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260721000006_manual_category_edit_approves_ai_review.sql
-- ==========================================================================

BEGIN;

DROP FUNCTION IF EXISTS public.update_product_details;

CREATE OR REPLACE FUNCTION public.update_product_details(
  p_product_id uuid,
  p_name text,
  p_restops_product_id text DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_accounting_category text DEFAULT NULL,
  p_is_inventoried boolean DEFAULT NULL,
  p_is_tax_exempt boolean DEFAULT NULL,
  p_report_by_unit text DEFAULT NULL,
  p_base_unit text DEFAULT NULL,
  p_latest_price numeric DEFAULT NULL,
  p_location_specific boolean DEFAULT NULL
)
RETURNS public.products
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_updated public.products%ROWTYPE;
  v_category text;
  v_accounting_category text;
  v_category_changed boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;

  IF NULLIF(trim(p_name), '') IS NULL THEN
    RAISE EXCEPTION 'Product name is required';
  END IF;

  v_category := NULLIF(trim(COALESCE(p_category, '')), '');
  v_accounting_category := NULLIF(trim(COALESCE(p_accounting_category, '')), '');
  v_category_changed :=
    COALESCE(v_product.category, '') IS DISTINCT FROM COALESCE(v_category, '')
    OR COALESCE(v_product.accounting_category, '') IS DISTINCT FROM COALESCE(v_accounting_category, '');

  UPDATE public.products
     SET name = upper(trim(p_name)),
         product_id = NULLIF(trim(COALESCE(p_restops_product_id, '')), ''),
         description = NULLIF(trim(COALESCE(p_description, '')), ''),
         category = v_category,
         accounting_category = v_accounting_category,
         is_tax_exempt = COALESCE(p_is_tax_exempt, false),
         report_by_unit = NULLIF(trim(COALESCE(p_report_by_unit, '')), ''),
         base_unit = NULLIF(trim(COALESCE(p_base_unit, '')), ''),
         latest_price = COALESCE(p_latest_price, 0),
         location_specific = COALESCE(p_location_specific, false),
         category_source = CASE WHEN v_category_changed THEN 'manual' ELSE category_source END,
         category_review_status = CASE WHEN v_category_changed THEN 'approved' ELSE category_review_status END,
         category_reviewed_at = CASE WHEN v_category_changed THEN now() ELSE category_reviewed_at END,
         category_reviewed_by = CASE WHEN v_category_changed THEN auth.uid() ELSE category_reviewed_by END,
         suggested_category = CASE WHEN v_category_changed THEN NULL ELSE suggested_category END,
         suggested_category_type = CASE WHEN v_category_changed THEN NULL ELSE suggested_category_type END,
         suggested_accounting_category = CASE WHEN v_category_changed THEN NULL ELSE suggested_accounting_category END,
         category_reason = CASE WHEN v_category_changed THEN NULL ELSE category_reason END,
         updated_at = now()
   WHERE id = p_product_id
   RETURNING * INTO v_updated;

  IF p_is_inventoried IS NOT NULL AND p_is_inventoried IS DISTINCT FROM v_product.is_inventoried THEN
    PERFORM public.set_product_inventory_tracking(p_product_id, p_is_inventoried);

    SELECT *
      INTO v_updated
    FROM public.products
    WHERE id = p_product_id;
  ELSIF p_is_inventoried IS NOT NULL THEN
    UPDATE public.products
       SET is_inventoried = p_is_inventoried,
           updated_at = now()
     WHERE id = p_product_id
     RETURNING * INTO v_updated;
  END IF;

  RETURN v_updated;
END;
$$;

GRANT EXECUTE ON FUNCTION public.update_product_details(uuid, text, text, text, text, text, boolean, boolean, text, text, numeric, boolean) TO authenticated;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260721000007_fix_product_report_units_from_extracted_pack_size.sql
-- ==========================================================================

BEGIN;

ALTER TABLE public.invoice_line_items
  ADD COLUMN IF NOT EXISTS pack_size text;

ALTER TABLE public.vendor_items
  ADD COLUMN IF NOT EXISTS pack_size text;

ALTER TABLE public.inventory
  ADD COLUMN IF NOT EXISTS report_by text;

CREATE OR REPLACE FUNCTION public.product_unit_is_generic(p_unit text)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT NULLIF(trim(COALESCE(p_unit, '')), '') IS NULL
    OR lower(trim(p_unit)) IN ('ea', 'each', 'other', 'unit', 'units');
$$;

CREATE OR REPLACE FUNCTION public.format_product_unit_quantity(p_quantity numeric)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT regexp_replace(regexp_replace(COALESCE(p_quantity, 0)::text, '0+$', ''), '\.$', '');
$$;

CREATE OR REPLACE FUNCTION public.normalize_product_unit_label(
  p_unit text,
  p_quantity numeric DEFAULT NULL
)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_unit text := upper(regexp_replace(trim(COALESCE(p_unit, '')), '[^A-Z]', '', 'g'));
  v_plural boolean := COALESCE(p_quantity, 2) <> 1;
BEGIN
  IF v_unit = '' THEN
    RETURN NULL;
  END IF;

  RETURN CASE
    WHEN v_unit IN ('EA', 'EACH', 'EACHES', 'CT', 'COUNT', 'CN') THEN 'Each'
    WHEN v_unit IN ('CS', 'CASE', 'CASES') THEN 'Case'
    WHEN v_unit IN ('LB', 'LBS', 'POUND', 'POUNDS') THEN CASE WHEN v_plural THEN 'Pounds' ELSE 'Pound' END
    WHEN v_unit IN ('OZ', 'OZS', 'OUNCE', 'OUNCES') THEN CASE WHEN v_plural THEN 'Ounces' ELSE 'Ounce' END
    WHEN v_unit IN ('GA', 'GAL', 'GALS', 'GALLON', 'GALLONS') THEN CASE WHEN v_plural THEN 'Gallons' ELSE 'Gallon' END
    WHEN v_unit IN ('L', 'LT', 'LTR', 'LTRS', 'LITER', 'LITERS', 'LITRE', 'LITRES') THEN CASE WHEN v_plural THEN 'Liters' ELSE 'Liter' END
    WHEN v_unit IN ('ML', 'MLS', 'MILLILITER', 'MILLILITERS') THEN CASE WHEN v_plural THEN 'Milliliters' ELSE 'Milliliter' END
    WHEN v_unit IN ('G', 'GM', 'GRAM', 'GRAMS') THEN CASE WHEN v_plural THEN 'Grams' ELSE 'Gram' END
    WHEN v_unit IN ('KG', 'KGS', 'KILOGRAM', 'KILOGRAMS') THEN CASE WHEN v_plural THEN 'Kilograms' ELSE 'Kilogram' END
    WHEN v_unit IN ('BTL', 'BTLS', 'BOTTLE', 'BOTTLES') THEN CASE WHEN v_plural THEN 'Bottles' ELSE 'Bottle' END
    WHEN v_unit IN ('CAN', 'CANS') THEN CASE WHEN v_plural THEN 'Cans' ELSE 'Can' END
    WHEN v_unit IN ('BAG', 'BAGS') THEN CASE WHEN v_plural THEN 'Bags' ELSE 'Bag' END
    WHEN v_unit IN ('BOX', 'BOXES', 'BX') THEN CASE WHEN v_plural THEN 'Boxes' ELSE 'Box' END
    WHEN v_unit IN ('PK', 'PKG', 'PACK', 'PACKAGE') THEN CASE WHEN v_plural THEN 'Packs' ELSE 'Pack' END
    WHEN v_unit IN ('DOZ', 'DOZEN') THEN 'Dozen'
    WHEN v_unit IN ('FLAT', 'FLATS') THEN CASE WHEN v_plural THEN 'Flats' ELSE 'Flat' END
    WHEN v_unit IN ('CUP', 'CUPS') THEN CASE WHEN v_plural THEN 'Cups' ELSE 'Cup' END
    WHEN v_unit IN ('QT', 'QTS', 'QUART', 'QUARTS') THEN CASE WHEN v_plural THEN 'Quarts' ELSE 'Quart' END
    ELSE initcap(lower(v_unit))
  END;
END;
$$;

CREATE OR REPLACE FUNCTION public.derive_product_report_unit(
  p_vendor_unit text DEFAULT NULL,
  p_pack_size text DEFAULT NULL
)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_pack text := upper(regexp_replace(trim(COALESCE(p_pack_size, '')), '[^A-Z0-9./ ]', ' ', 'g'));
  v_vendor text := trim(COALESCE(p_vendor_unit, ''));
  v_vendor_label text := public.normalize_product_unit_label(v_vendor);
  v_match text[];
  v_outer numeric;
  v_inner numeric;
  v_qty numeric;
  v_unit text;
  v_unit_label text;
  v_qty_label text;
  v_container_label text;
BEGIN
  IF v_pack = '' AND v_vendor ~ '[0-9]' THEN
    v_pack := upper(regexp_replace(v_vendor, '[^A-Z0-9./ ]', ' ', 'g'));
  END IF;

  v_match := regexp_match(v_pack, '^\s*([0-9]+(?:\.[0-9]+)?)\s*/\s*([0-9]+(?:\.[0-9]+)?)\s*([A-Z]+)');
  IF v_match IS NOT NULL THEN
    v_outer := v_match[1]::numeric;
    v_inner := v_match[2]::numeric;
    v_unit := v_match[3];
    v_unit_label := public.normalize_product_unit_label(v_unit, v_inner);
    v_container_label := CASE
      WHEN v_vendor_label IS NOT NULL AND lower(v_vendor_label) NOT IN ('each', 'unit', 'other') THEN v_vendor_label
      ELSE NULL
    END;

    IF v_container_label IS NOT NULL THEN
      RETURN v_container_label || ' (' || public.format_product_unit_quantity(v_outer) || ' x '
        || public.format_product_unit_quantity(v_inner) || ' ' || v_unit_label || ')';
    END IF;

    RETURN public.format_product_unit_quantity(v_outer) || ' x '
      || public.format_product_unit_quantity(v_inner) || ' ' || v_unit_label;
  END IF;

  v_match := regexp_match(v_pack, '([0-9]+(?:\.[0-9]+)?)\s*([A-Z]+)\b');
  IF v_match IS NOT NULL THEN
    v_qty := v_match[1]::numeric;
    v_unit := v_match[2];
    v_unit_label := public.normalize_product_unit_label(v_unit, v_qty);
    v_qty_label := public.format_product_unit_quantity(v_qty);

    IF v_vendor_label IS NOT NULL
      AND lower(v_vendor_label) NOT IN ('each', 'unit', 'other')
      AND lower(v_vendor_label) <> lower(v_unit_label)
      AND v_unit_label IS NOT NULL THEN
      RETURN v_vendor_label || ' (' || v_qty_label || ' ' || v_unit_label || ')';
    END IF;

    RETURN v_qty_label || ' ' || COALESCE(v_unit_label, initcap(lower(v_unit)));
  END IF;

  IF v_pack <> '' THEN
    v_unit_label := public.normalize_product_unit_label(v_pack);
    IF v_unit_label IS NOT NULL THEN
      RETURN v_unit_label;
    END IF;
  END IF;

  RETURN COALESCE(v_vendor_label, NULLIF(v_vendor, ''), 'Each');
END;
$$;

CREATE OR REPLACE FUNCTION public.best_product_report_unit(
  p_product_unit text DEFAULT NULL,
  p_vendor_unit text DEFAULT NULL,
  p_pack_size text DEFAULT NULL
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT CASE
    WHEN public.product_unit_is_generic(p_product_unit)
      THEN public.derive_product_report_unit(p_vendor_unit, p_pack_size)
    ELSE p_product_unit
  END;
$$;

CREATE OR REPLACE FUNCTION public.upsert_invoice_line_items(p_invoice_id UUID, p_items JSONB)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_item RECORD;
  v_incoming_ids UUID[] := ARRAY[]::UUID[];
  v_org_id UUID;
BEGIN
  SELECT organization_id INTO v_org_id
  FROM public.invoices
  WHERE id = p_invoice_id;

  FOR v_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(
    id UUID,
    inventory_item_id TEXT,
    internal_product_id UUID,
    item_name TEXT,
    quantity NUMERIC,
    unit_price NUMERIC,
    total_price NUMERIC,
    vendor_item_code TEXT,
    vendor_unit TEXT,
    pack_size TEXT
  ) LOOP
    IF v_item.id IS NULL THEN
      v_item.id := gen_random_uuid();

      INSERT INTO public.invoice_line_items (
        id, invoice_id, organization_id, inventory_item_id, internal_product_id,
        item_name, quantity, unit_price, total_price, vendor_item_code, vendor_unit, pack_size
      ) VALUES (
        v_item.id, p_invoice_id, v_org_id, v_item.inventory_item_id, v_item.internal_product_id,
        v_item.item_name, v_item.quantity, v_item.unit_price, v_item.total_price,
        v_item.vendor_item_code, v_item.vendor_unit, NULLIF(v_item.pack_size, '')
      );
    ELSE
      UPDATE public.invoice_line_items
         SET inventory_item_id = v_item.inventory_item_id,
             internal_product_id = v_item.internal_product_id,
             item_name = v_item.item_name,
             quantity = v_item.quantity,
             unit_price = v_item.unit_price,
             total_price = v_item.total_price,
             vendor_item_code = v_item.vendor_item_code,
             vendor_unit = v_item.vendor_unit,
             pack_size = NULLIF(v_item.pack_size, '')
       WHERE id = v_item.id
         AND invoice_id = p_invoice_id;
    END IF;

    v_incoming_ids := array_append(v_incoming_ids, v_item.id);
  END LOOP;

  DELETE FROM public.invoice_line_items
   WHERE invoice_id = p_invoice_id
     AND id <> ALL(v_incoming_ids);
END;
$$;

CREATE OR REPLACE FUNCTION public.sync_invoice_products(p_invoice_id UUID, p_user_id UUID DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_item RECORD;
  v_product_id UUID;
  v_vendor_item_id UUID;
  v_mapping_id UUID;
  v_previous_price NUMERIC;
  v_threshold NUMERIC := 10;
  v_price_variance_flag BOOLEAN;
  v_price_variance_percent NUMERIC;
  v_line_hash TEXT;
  v_existing_hash TEXT;
  v_updates_count INT := 0;
  v_report_unit TEXT;
BEGIN
  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id;

  IF v_invoice IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Invoice not found');
  END IF;

  SELECT md5(COALESCE(jsonb_agg(jsonb_build_object(
      'id', ili.id,
      'item_name', ili.item_name,
      'quantity', ili.quantity,
      'unit_price', ili.unit_price,
      'total_price', ili.total_price,
      'vendor_item_code', ili.vendor_item_code,
      'vendor_unit', ili.vendor_unit,
      'pack_size', ili.pack_size
    ) ORDER BY ili.id)::TEXT, '[]'))
    INTO v_line_hash
  FROM public.invoice_line_items ili
  WHERE ili.invoice_id = p_invoice_id;

  SELECT hash INTO v_existing_hash
  FROM public.invoice_sync_log
  WHERE invoice_id = p_invoice_id
    AND operation = 'sync_invoice_products'
  ORDER BY processed_at DESC
  LIMIT 1;

  IF v_existing_hash IS NOT NULL AND v_existing_hash = v_line_hash THEN
    RETURN jsonb_build_object('status', 'success', 'updates_count', 0, 'idempotent', true);
  END IF;

  FOR v_item IN
    SELECT *
    FROM public.invoice_line_items
    WHERE invoice_id = p_invoice_id
      AND NULLIF(trim(COALESCE(item_name, '')), '') IS NOT NULL
  LOOP
    v_product_id := v_item.internal_product_id;
    v_vendor_item_id := NULL;
    v_mapping_id := NULL;
    v_price_variance_flag := false;
    v_price_variance_percent := 0;
    v_report_unit := public.derive_product_report_unit(v_item.vendor_unit, v_item.pack_size);

    IF v_product_id IS NULL THEN
      SELECT id INTO v_product_id
      FROM public.products
      WHERE organization_id = v_invoice.organization_id
        AND lower(name) = lower(v_item.item_name)
        AND deleted_at IS NULL
        AND (
          brand_id IS NOT DISTINCT FROM v_invoice.brand_id
          OR brand_id IS NULL
        )
      ORDER BY CASE WHEN brand_id IS NOT DISTINCT FROM v_invoice.brand_id THEN 0 ELSE 1 END
      LIMIT 1;

      IF v_product_id IS NULL THEN
        INSERT INTO public.products (
          organization_id,
          brand_id,
          location_id,
          product_id,
          name,
          category,
          accounting_category,
          report_by_unit,
          base_unit,
          latest_price,
          is_inventoried
        ) VALUES (
          v_invoice.organization_id,
          v_invoice.brand_id,
          v_invoice.location_id,
          public.generate_restops_product_id(),
          v_item.item_name,
          public.derive_product_category(NULL, v_item.item_name),
          CASE
            WHEN public.derive_product_category_type(NULL, NULL, v_item.item_name) = 'Beverage' THEN '5200'
            ELSE '5100'
          END,
          COALESCE(v_report_unit, 'Each'),
          COALESCE(v_report_unit, 'Each'),
          COALESCE(v_item.unit_price, 0),
          false
        )
        ON CONFLICT ON CONSTRAINT products_org_name_key
        DO UPDATE SET
          deleted_at = NULL,
          report_by_unit = CASE
            WHEN public.product_unit_is_generic(products.report_by_unit) THEN COALESCE(EXCLUDED.report_by_unit, products.report_by_unit)
            ELSE products.report_by_unit
          END,
          base_unit = CASE
            WHEN public.product_unit_is_generic(products.base_unit) THEN COALESCE(EXCLUDED.base_unit, products.base_unit)
            ELSE products.base_unit
          END,
          latest_price = CASE
            WHEN COALESCE(EXCLUDED.latest_price, 0) > 0 THEN EXCLUDED.latest_price
            ELSE products.latest_price
          END,
          updated_at = now()
        RETURNING id INTO v_product_id;
      ELSE
        UPDATE public.products
           SET product_id = COALESCE(NULLIF(product_id, ''), public.generate_restops_product_id()),
               report_by_unit = CASE
                 WHEN public.product_unit_is_generic(report_by_unit) THEN COALESCE(v_report_unit, report_by_unit)
                 ELSE report_by_unit
               END,
               base_unit = CASE
                 WHEN public.product_unit_is_generic(base_unit) THEN COALESCE(v_report_unit, base_unit)
                 ELSE base_unit
               END,
               latest_price = CASE
                 WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price
                 ELSE latest_price
               END,
               category = CASE
                 WHEN NULLIF(trim(COALESCE(category, '')), '') IS NULL OR lower(category) = 'uncategorized'
                   THEN public.derive_product_category(category, v_item.item_name)
                 ELSE category
               END,
               brand_id = COALESCE(brand_id, v_invoice.brand_id),
               location_id = COALESCE(location_id, v_invoice.location_id),
               updated_at = now()
         WHERE id = v_product_id;
      END IF;
    ELSE
      UPDATE public.products
         SET report_by_unit = CASE
               WHEN public.product_unit_is_generic(report_by_unit) THEN COALESCE(v_report_unit, report_by_unit)
               ELSE report_by_unit
             END,
             base_unit = CASE
               WHEN public.product_unit_is_generic(base_unit) THEN COALESCE(v_report_unit, base_unit)
               ELSE base_unit
             END,
             latest_price = CASE
               WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price
               ELSE latest_price
             END,
             updated_at = now()
       WHERE id = v_product_id
         AND deleted_at IS NULL;
    END IF;

    IF v_invoice.vendor_id IS NOT NULL THEN
      SELECT id, last_price, price_variance_threshold_percent
        INTO v_vendor_item_id, v_previous_price, v_threshold
      FROM public.vendor_items
      WHERE organization_id = v_invoice.organization_id
        AND vendor_id = v_invoice.vendor_id
        AND lower(vendor_item_name) = lower(v_item.item_name)
        AND COALESCE(vendor_item_code, '') = COALESCE(v_item.vendor_item_code, '')
      LIMIT 1;

      v_threshold := COALESCE(v_threshold, 10);

      IF v_vendor_item_id IS NOT NULL THEN
        IF COALESCE(v_previous_price, 0) > 0 AND COALESCE(v_item.unit_price, 0) > 0 THEN
          v_price_variance_percent := ((v_item.unit_price - v_previous_price) / v_previous_price) * 100;
          v_price_variance_flag := abs(v_price_variance_percent) >= v_threshold;
        END IF;

        UPDATE public.vendor_items
           SET vendor_unit = COALESCE(NULLIF(v_item.vendor_unit, ''), vendor_unit),
               pack_size = COALESCE(NULLIF(v_item.pack_size, ''), pack_size),
               previous_price = last_price,
               last_price = COALESCE(v_item.unit_price, last_price),
               last_invoice_id = p_invoice_id,
               last_invoice_line_id = v_item.id,
               last_purchased_at = COALESCE(v_invoice.invoice_date, CURRENT_DATE),
               last_price_change_percent = v_price_variance_percent,
               price_variance_flag = v_price_variance_flag,
               updated_at = now()
         WHERE id = v_vendor_item_id;
      ELSE
        INSERT INTO public.vendor_items (
          organization_id,
          vendor_id,
          vendor_item_code,
          vendor_item_name,
          vendor_unit,
          pack_size,
          default_price,
          last_price,
          last_invoice_id,
          last_invoice_line_id,
          last_purchased_at,
          updated_at
        ) VALUES (
          v_invoice.organization_id,
          v_invoice.vendor_id,
          NULLIF(v_item.vendor_item_code, ''),
          v_item.item_name,
          NULLIF(v_item.vendor_unit, ''),
          NULLIF(v_item.pack_size, ''),
          v_item.unit_price,
          v_item.unit_price,
          p_invoice_id,
          v_item.id,
          COALESCE(v_invoice.invoice_date, CURRENT_DATE),
          now()
        )
        RETURNING id INTO v_vendor_item_id;
      END IF;

      IF v_product_id IS NOT NULL AND v_vendor_item_id IS NOT NULL THEN
        INSERT INTO public.vendor_item_mappings (
          organization_id,
          vendor_item_id,
          internal_product_id,
          conversion_multiplier,
          is_verified,
          updated_at
        ) VALUES (
          v_invoice.organization_id,
          v_vendor_item_id,
          v_product_id,
          1,
          false,
          now()
        )
        ON CONFLICT (vendor_item_id, internal_product_id)
        DO UPDATE SET updated_at = now()
        RETURNING id INTO v_mapping_id;
      END IF;
    END IF;

    UPDATE public.invoice_line_items
       SET vendor_id = v_invoice.vendor_id,
           vendor_item_id = v_vendor_item_id,
           internal_product_id = v_product_id,
           price_variance_flag = v_price_variance_flag,
           price_variance_percent = v_price_variance_percent
     WHERE id = v_item.id;

    UPDATE public.inventory inv
       SET current_unit = CASE
             WHEN public.product_unit_is_generic(inv.current_unit) THEN COALESCE(v_report_unit, inv.current_unit)
             ELSE inv.current_unit
           END,
           report_by = CASE
             WHEN public.product_unit_is_generic(inv.report_by) THEN COALESCE(v_report_unit, inv.report_by)
             ELSE inv.report_by
           END,
           updated_at = now()
     WHERE v_product_id IS NOT NULL
       AND inv.organization_id = v_invoice.organization_id
       AND inv.deleted_at IS NULL
       AND (
         inv.internal_product_id = v_product_id
         OR inv.product_id = (SELECT product_id FROM public.products WHERE id = v_product_id)
       );

    v_updates_count := v_updates_count + 1;
  END LOOP;

  INSERT INTO public.invoice_event_log (invoice_id, event_type, new_value, actor_id)
  VALUES (
    p_invoice_id,
    'product_catalog_synced',
    jsonb_build_object('updates_count', v_updates_count),
    COALESCE(p_user_id, auth.uid())
  );

  INSERT INTO public.invoice_sync_log (invoice_id, operation, hash)
  VALUES (p_invoice_id, 'sync_invoice_products', v_line_hash);

  RETURN jsonb_build_object('status', 'success', 'updates_count', v_updates_count);
END;
$$;

UPDATE public.invoice_line_items ili
   SET pack_size = (
     SELECT NULLIF(trim(COALESCE(
       item.value->>'pack_size',
       item.value->>'PackSize',
       item.value->>'pack',
       item.value->>'Pack',
       item.value->>'size',
       item.value->>'Size'
     )), '')
     FROM public.invoices i
     CROSS JOIN LATERAL jsonb_array_elements(COALESCE(i.line_items, '[]'::jsonb)) AS item(value)
     WHERE i.id = ili.invoice_id
       AND lower(trim(COALESCE(
           item.value->>'description',
           item.value->>'item_name',
           item.value->>'name',
           ''
         ))) = lower(trim(ili.item_name))
       AND (
         NULLIF(trim(COALESCE(ili.vendor_item_code, '')), '') IS NULL
         OR NULLIF(trim(COALESCE(
           item.value->>'vendor_item_code',
           item.value->>'product_number',
           item.value->>'item_code',
           ''
         )), '') = NULLIF(trim(COALESCE(ili.vendor_item_code, '')), '')
       )
     LIMIT 1
   )
 WHERE NULLIF(trim(COALESCE(ili.pack_size, '')), '') IS NULL
   AND EXISTS (
     SELECT 1
     FROM public.invoices i
     CROSS JOIN LATERAL jsonb_array_elements(COALESCE(i.line_items, '[]'::jsonb)) AS item(value)
     WHERE i.id = ili.invoice_id
       AND NULLIF(trim(COALESCE(
         item.value->>'pack_size',
         item.value->>'PackSize',
         item.value->>'pack',
         item.value->>'Pack',
         item.value->>'size',
         item.value->>'Size'
       )), '') IS NOT NULL
       AND lower(trim(COALESCE(
           item.value->>'description',
           item.value->>'item_name',
           item.value->>'name',
           ''
         ))) = lower(trim(ili.item_name))
   );

UPDATE public.vendor_items vi
   SET pack_size = COALESCE(NULLIF(ili.pack_size, ''), vi.pack_size),
       updated_at = now()
  FROM public.invoice_line_items ili
 WHERE vi.last_invoice_line_id = ili.id
   AND NULLIF(trim(COALESCE(vi.pack_size, '')), '') IS NULL
   AND NULLIF(trim(COALESCE(ili.pack_size, '')), '') IS NOT NULL;

WITH latest_units AS (
  SELECT DISTINCT ON (p.id)
    p.id AS product_id,
    public.derive_product_report_unit(
      COALESCE(ili.vendor_unit, vi.vendor_unit),
      COALESCE(ili.pack_size, vi.pack_size)
    ) AS report_unit
  FROM public.products p
  LEFT JOIN public.invoice_line_items ili ON ili.internal_product_id = p.id
  LEFT JOIN public.invoices invc ON invc.id = ili.invoice_id
  LEFT JOIN public.vendor_item_mappings vim ON vim.internal_product_id = p.id
  LEFT JOIN public.vendor_items vi ON vi.id = vim.vendor_item_id
  WHERE p.deleted_at IS NULL
    AND (
      NULLIF(trim(COALESCE(ili.pack_size, '')), '') IS NOT NULL
      OR NULLIF(trim(COALESCE(vi.pack_size, '')), '') IS NOT NULL
      OR NULLIF(trim(COALESCE(ili.vendor_unit, vi.vendor_unit, '')), '') IS NOT NULL
    )
  ORDER BY p.id, invc.invoice_date DESC NULLS LAST, ili.created_at DESC NULLS LAST, vi.last_purchased_at DESC NULLS LAST
)
UPDATE public.products p
   SET report_by_unit = CASE
         WHEN public.product_unit_is_generic(p.report_by_unit) THEN latest_units.report_unit
         ELSE p.report_by_unit
       END,
       base_unit = CASE
         WHEN public.product_unit_is_generic(p.base_unit) THEN latest_units.report_unit
         ELSE p.base_unit
       END,
       updated_at = now()
  FROM latest_units
 WHERE p.id = latest_units.product_id
   AND latest_units.report_unit IS NOT NULL
   AND (
     public.product_unit_is_generic(p.report_by_unit)
     OR public.product_unit_is_generic(p.base_unit)
   );

UPDATE public.inventory inv
   SET current_unit = CASE
         WHEN public.product_unit_is_generic(inv.current_unit) THEN p.report_by_unit
         ELSE inv.current_unit
       END,
       report_by = CASE
         WHEN public.product_unit_is_generic(inv.report_by) THEN p.report_by_unit
         ELSE inv.report_by
       END,
       updated_at = now()
  FROM public.products p
 WHERE inv.deleted_at IS NULL
   AND p.deleted_at IS NULL
   AND NULLIF(trim(COALESCE(p.report_by_unit, '')), '') IS NOT NULL
   AND (
     inv.internal_product_id = p.id
     OR inv.product_id = p.product_id
   )
   AND (
     public.product_unit_is_generic(inv.current_unit)
     OR public.product_unit_is_generic(inv.report_by)
   );

DROP FUNCTION IF EXISTS public.get_product_purchase_report(uuid, uuid, uuid, date, date, text, text, text);

CREATE OR REPLACE FUNCTION public.get_product_purchase_report(
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_start_date date DEFAULT NULL,
  p_end_date date DEFAULT NULL,
  p_category_type text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_search text DEFAULT NULL
)
RETURNS TABLE (
  restaurant text,
  product_id uuid,
  restops_product_id text,
  product_name text,
  category_type text,
  category text,
  report_by text,
  invoice_count bigint,
  line_count bigint,
  purchased_units numeric,
  purchased_amount numeric,
  latest_cost numeric,
  avg_cost numeric,
  last_purchased_at date
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  RETURN QUERY
  WITH approved_invoices AS (
    SELECT i.*
    FROM public.invoices i
    WHERE i.organization_id = v_org_id
      AND i.deleted_at IS NULL
      AND (i.status = 'approved' OR i.ap_status = 'approved')
      AND (p_brand_id IS NULL OR i.brand_id IS NOT DISTINCT FROM p_brand_id OR i.brand_id IS NULL)
      AND (p_location_id IS NULL OR i.location_id IS NOT DISTINCT FROM p_location_id OR i.location_id IS NULL)
      AND (p_start_date IS NULL OR i.invoice_date >= p_start_date)
      AND (p_end_date IS NULL OR i.invoice_date <= p_end_date)
      AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
  ),
  normalized_lines AS (
    SELECT
      i.id AS invoice_id,
      i.invoice_date,
      i.organization_id,
      i.brand_id,
      i.location_id,
      i.vendor_id,
      ili.id AS line_id,
      ili.item_name,
      ili.quantity,
      ili.unit_price,
      ili.total_price,
      ili.vendor_unit,
      ili.pack_size,
      ili.internal_product_id,
      ili.inventory_item_id::text AS inventory_item_id
    FROM approved_invoices i
    JOIN public.invoice_line_items ili ON ili.invoice_id = i.id
    WHERE public.tenant_scope_visible(ili.organization_id, i.brand_id, i.location_id, NULL)
  ),
  json_lines AS (
    SELECT
      i.id AS invoice_id,
      i.invoice_date,
      i.organization_id,
      i.brand_id,
      i.location_id,
      i.vendor_id,
      gen_random_uuid() AS line_id,
      trim(COALESCE(
        NULLIF(item.value->>'description', ''),
        NULLIF(item.value->>'item_name', ''),
        NULLIF(item.value->>'name', ''),
        'Unknown Item'
      )) AS item_name,
      amounts.quantity,
      amounts.unit_price,
      COALESCE(amounts.extended_price, amounts.total_price, amounts.quantity * amounts.unit_price) AS total_price,
      COALESCE(NULLIF(item.value->>'vendor_unit', ''), NULLIF(item.value->>'unit', '')) AS vendor_unit,
      COALESCE(
        NULLIF(item.value->>'pack_size', ''),
        NULLIF(item.value->>'PackSize', ''),
        NULLIF(item.value->>'pack', ''),
        NULLIF(item.value->>'size', '')
      ) AS pack_size,
      CASE
        WHEN COALESCE(item.value->>'internal_product_id', item.value->>'product_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN COALESCE(item.value->>'internal_product_id', item.value->>'product_id')::uuid
        ELSE NULL
      END AS internal_product_id,
      NULLIF(item.value->>'inventory_item_id', '') AS inventory_item_id
    FROM approved_invoices i
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(i.line_items, '[]'::jsonb)) WITH ORDINALITY AS item(value, ordinal)
    CROSS JOIN LATERAL (
      SELECT
        COALESCE(NULLIF(regexp_replace(COALESCE(item.value->>'quantity', ''), '[^0-9.\-]', '', 'g'), '')::numeric, 1) AS quantity,
        COALESCE(NULLIF(regexp_replace(COALESCE(item.value->>'unit_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric, 0) AS unit_price,
        NULLIF(regexp_replace(COALESCE(item.value->>'extended_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric AS extended_price,
        NULLIF(regexp_replace(COALESCE(item.value->>'total_price', ''), '[^0-9.\-]', '', 'g'), '')::numeric AS total_price
    ) amounts
    WHERE NOT EXISTS (
        SELECT 1
        FROM public.invoice_line_items ili
        WHERE ili.invoice_id = i.id
      )
      AND NULLIF(trim(COALESCE(
        item.value->>'description',
        item.value->>'item_name',
        item.value->>'name',
        ''
      )), '') IS NOT NULL
  ),
  approved_lines AS (
    SELECT * FROM normalized_lines
    UNION ALL
    SELECT * FROM json_lines
  ),
  enriched AS (
    SELECT
      COALESCE(l.name, 'Current Store') AS restaurant,
      p.id AS product_id,
      p.product_id AS restops_product_id,
      COALESCE(p.name, al.item_name) AS product_name,
      public.derive_product_category_type(p.accounting_category, p.category, COALESCE(p.name, al.item_name)) AS category_type,
      public.derive_product_category(p.category, COALESCE(p.name, al.item_name)) AS category,
      public.best_product_report_unit(p.report_by_unit, al.vendor_unit, al.pack_size) AS report_by,
      al.invoice_id,
      al.line_id,
      COALESCE(al.quantity, 0) AS quantity,
      COALESCE(al.total_price, COALESCE(al.quantity, 0) * COALESCE(al.unit_price, 0)) AS total_price,
      COALESCE(al.unit_price, 0) AS unit_price,
      al.invoice_date
    FROM approved_lines al
    LEFT JOIN public.products p
      ON p.id = al.internal_product_id
      OR (al.inventory_item_id IS NOT NULL AND p.product_id = al.inventory_item_id)
    LEFT JOIN public.locations l ON l.id = al.location_id
    WHERE (p_search IS NULL OR COALESCE(p.name, al.item_name, '') ILIKE '%' || p_search || '%')
  )
  SELECT
    e.restaurant,
    e.product_id,
    e.restops_product_id,
    e.product_name,
    e.category_type,
    e.category,
    e.report_by,
    count(DISTINCT e.invoice_id) AS invoice_count,
    count(e.line_id) AS line_count,
    round(sum(e.quantity), 4) AS purchased_units,
    round(sum(e.total_price), 2) AS purchased_amount,
    (array_agg(e.unit_price ORDER BY e.invoice_date DESC NULLS LAST, e.line_id DESC))[1] AS latest_cost,
    round(sum(e.total_price) / NULLIF(sum(e.quantity), 0), 4) AS avg_cost,
    max(e.invoice_date) AS last_purchased_at
  FROM enriched e
  WHERE (p_category_type IS NULL OR p_category_type = 'all' OR e.category_type = p_category_type)
    AND (p_category IS NULL OR p_category = 'all' OR e.category = p_category)
  GROUP BY
    e.restaurant,
    e.product_id,
    e.restops_product_id,
    e.product_name,
    e.category_type,
    e.category,
    e.report_by
  ORDER BY e.product_name;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_product_purchase_report(uuid, uuid, uuid, date, date, text, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.sync_invoice_products(uuid, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.upsert_invoice_line_items(uuid, jsonb) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260721000008_fix_product_unit_quantity_formatter.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.format_product_unit_quantity(p_quantity numeric)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT regexp_replace(trim(to_char(COALESCE(p_quantity, 0), 'FM999999999999990.9999')), '\.$', '');
$$;

WITH latest_units AS (
  SELECT DISTINCT ON (p.id)
    p.id AS product_id,
    public.derive_product_report_unit(
      COALESCE(ili.vendor_unit, vi.vendor_unit),
      COALESCE(ili.pack_size, vi.pack_size)
    ) AS report_unit
  FROM public.products p
  LEFT JOIN public.invoice_line_items ili ON ili.internal_product_id = p.id
  LEFT JOIN public.invoices invc ON invc.id = ili.invoice_id
  LEFT JOIN public.vendor_item_mappings vim ON vim.internal_product_id = p.id
  LEFT JOIN public.vendor_items vi ON vi.id = vim.vendor_item_id
  WHERE p.deleted_at IS NULL
    AND (
      NULLIF(trim(COALESCE(ili.pack_size, '')), '') IS NOT NULL
      OR NULLIF(trim(COALESCE(vi.pack_size, '')), '') IS NOT NULL
      OR NULLIF(trim(COALESCE(ili.vendor_unit, vi.vendor_unit, '')), '') IS NOT NULL
    )
  ORDER BY p.id, invc.invoice_date DESC NULLS LAST, ili.created_at DESC NULLS LAST, vi.last_purchased_at DESC NULLS LAST
)
UPDATE public.products p
   SET report_by_unit = latest_units.report_unit,
       base_unit = CASE
         WHEN public.product_unit_is_generic(p.base_unit) OR p.base_unit = p.report_by_unit THEN latest_units.report_unit
         ELSE p.base_unit
       END,
       updated_at = now()
  FROM latest_units
 WHERE p.id = latest_units.product_id
   AND latest_units.report_unit IS NOT NULL
   AND (
     public.product_unit_is_generic(p.report_by_unit)
     OR p.report_by_unit ~ '^[0-9]+(\.[0-9]+)?\s'
   );

UPDATE public.inventory inv
   SET current_unit = CASE
         WHEN public.product_unit_is_generic(inv.current_unit) OR inv.current_unit ~ '^[0-9]+(\.[0-9]+)?\s' THEN p.report_by_unit
         ELSE inv.current_unit
       END,
       report_by = CASE
         WHEN public.product_unit_is_generic(inv.report_by) OR inv.report_by ~ '^[0-9]+(\.[0-9]+)?\s' THEN p.report_by_unit
         ELSE inv.report_by
       END,
       updated_at = now()
  FROM public.products p
 WHERE inv.deleted_at IS NULL
   AND p.deleted_at IS NULL
   AND NULLIF(trim(COALESCE(p.report_by_unit, '')), '') IS NOT NULL
   AND (
     inv.internal_product_id = p.id
     OR inv.product_id = p.product_id
   )
   AND (
     public.product_unit_is_generic(inv.current_unit)
     OR public.product_unit_is_generic(inv.report_by)
     OR inv.current_unit ~ '^[0-9]+(\.[0-9]+)?\s'
     OR inv.report_by ~ '^[0-9]+(\.[0-9]+)?\s'
   );

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260721000009_product_unit_conversion_pricing.sql
-- ==========================================================================

BEGIN;

ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS report_unit_quantity numeric DEFAULT 1,
  ADD COLUMN IF NOT EXISTS report_unit_source_price numeric;

UPDATE public.products
   SET report_unit_quantity = COALESCE(NULLIF(report_unit_quantity, 0), 1),
       report_unit_source_price = COALESCE(report_unit_source_price, latest_price, 0)
 WHERE report_unit_quantity IS NULL
    OR report_unit_quantity = 0
    OR report_unit_source_price IS NULL;

CREATE OR REPLACE FUNCTION public.update_product_details(
  p_product_id uuid,
  p_name text,
  p_restops_product_id text DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_accounting_category text DEFAULT NULL,
  p_is_inventoried boolean DEFAULT NULL,
  p_is_tax_exempt boolean DEFAULT NULL,
  p_report_by_unit text DEFAULT NULL,
  p_base_unit text DEFAULT NULL,
  p_latest_price numeric DEFAULT NULL,
  p_location_specific boolean DEFAULT NULL,
  p_report_unit_quantity numeric DEFAULT NULL,
  p_report_unit_source_price numeric DEFAULT NULL
)
RETURNS public.products
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_updated public.products%ROWTYPE;
  v_category text;
  v_accounting_category text;
  v_category_changed boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;

  IF NULLIF(trim(p_name), '') IS NULL THEN
    RAISE EXCEPTION 'Product name is required';
  END IF;

  v_category := NULLIF(trim(COALESCE(p_category, '')), '');
  v_accounting_category := NULLIF(trim(COALESCE(p_accounting_category, '')), '');
  v_category_changed :=
    COALESCE(v_product.category, '') IS DISTINCT FROM COALESCE(v_category, '')
    OR COALESCE(v_product.accounting_category, '') IS DISTINCT FROM COALESCE(v_accounting_category, '');

  UPDATE public.products
     SET name = upper(trim(p_name)),
         product_id = NULLIF(trim(COALESCE(p_restops_product_id, '')), ''),
         description = NULLIF(trim(COALESCE(p_description, '')), ''),
         category = v_category,
         accounting_category = v_accounting_category,
         is_tax_exempt = COALESCE(p_is_tax_exempt, false),
         report_by_unit = NULLIF(trim(COALESCE(p_report_by_unit, '')), ''),
         base_unit = NULLIF(trim(COALESCE(p_base_unit, '')), ''),
         latest_price = COALESCE(p_latest_price, 0),
         location_specific = COALESCE(p_location_specific, false),
         report_unit_quantity = GREATEST(COALESCE(p_report_unit_quantity, report_unit_quantity, 1), 0.0001),
         report_unit_source_price = COALESCE(p_report_unit_source_price, report_unit_source_price, p_latest_price, latest_price, 0),
         category_source = CASE WHEN v_category_changed THEN 'manual' ELSE category_source END,
         category_review_status = CASE WHEN v_category_changed THEN 'approved' ELSE category_review_status END,
         category_reviewed_at = CASE WHEN v_category_changed THEN now() ELSE category_reviewed_at END,
         category_reviewed_by = CASE WHEN v_category_changed THEN auth.uid() ELSE category_reviewed_by END,
         suggested_category = CASE WHEN v_category_changed THEN NULL ELSE suggested_category END,
         suggested_category_type = CASE WHEN v_category_changed THEN NULL ELSE suggested_category_type END,
         suggested_accounting_category = CASE WHEN v_category_changed THEN NULL ELSE suggested_accounting_category END,
         category_reason = CASE WHEN v_category_changed THEN NULL ELSE category_reason END,
         updated_at = now()
   WHERE id = p_product_id
   RETURNING * INTO v_updated;

  IF p_is_inventoried IS NOT NULL AND p_is_inventoried IS DISTINCT FROM v_product.is_inventoried THEN
    PERFORM public.set_product_inventory_tracking(p_product_id, p_is_inventoried);

    SELECT *
      INTO v_updated
    FROM public.products
    WHERE id = p_product_id;
  ELSIF p_is_inventoried IS NOT NULL THEN
    UPDATE public.products
       SET is_inventoried = p_is_inventoried,
           updated_at = now()
     WHERE id = p_product_id
     RETURNING * INTO v_updated;
  END IF;

  RETURN v_updated;
END;
$$;

GRANT EXECUTE ON FUNCTION public.update_product_details(uuid, text, text, text, text, text, boolean, boolean, text, text, numeric, boolean, numeric, numeric) TO authenticated;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260721000010_category_performance_report.sql
-- ==========================================================================

-- Category Performance Report: consolidated purchasing analytics (no POS).
-- Spend fact: invoice_allocations joined to invoices.invoice_date.
-- Eligible invoices:
--   deleted_at IS NULL
--   status NOT IN ('rejected', 'duplicate')
--   ap_status IS DISTINCT FROM 'rejected'
--   AND purchasing-recognized status:
--     status IN ('approved','scheduled','partially_paid','paid')
--     OR ap_status IN ('approved','scheduled','paid','closed')
-- Rationale: invoices use dual tracks (status + ap_status). Purchase-report
-- historically used (status='approved' OR ap_status='approved'), which drops
-- fully paid invoices whose status/ap_status moved to paid/closed. Category
-- Report includes those paid/settled states while still excluding rejected,
-- duplicate, draft/extract, and soft-deleted rows. There is no 'void' status;
-- voiding is represented by deleted_at.
-- Label: Purchasing Spend (not COGS).

BEGIN;

-- Shared eligibility predicate for purchasing spend (allocations join invoices).
-- Keep in sync with get_category_performance_drilldown.
CREATE OR REPLACE FUNCTION public.is_purchasing_spend_invoice(
  p_status text,
  p_ap_status text,
  p_deleted_at timestamptz
)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT
    p_deleted_at IS NULL
    AND COALESCE(p_status, '') NOT IN ('rejected', 'duplicate')
    AND COALESCE(p_ap_status, '') IS DISTINCT FROM 'rejected'
    AND (
      COALESCE(p_status, '') IN ('approved', 'scheduled', 'partially_paid', 'paid')
      OR COALESCE(p_ap_status, '') IN ('approved', 'scheduled', 'paid', 'closed')
    );
$$;

COMMENT ON FUNCTION public.is_purchasing_spend_invoice(text, text, timestamptz) IS
  'True when an invoice should count toward purchasing-spend analytics.';

CREATE OR REPLACE FUNCTION public.get_category_performance_report(
  p_organization_id uuid DEFAULT NULL,
  p_location_ids uuid[] DEFAULT NULL,
  p_date_from date DEFAULT NULL,
  p_date_to date DEFAULT NULL,
  p_comparison_date_from date DEFAULT NULL,
  p_comparison_date_to date DEFAULT NULL,
  p_category_names text[] DEFAULT NULL,
  p_vendor_ids uuid[] DEFAULT NULL,
  p_timezone text DEFAULT 'UTC',
  p_selected_category text DEFAULT NULL,
  p_trend_categories text[] DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_tz text := COALESCE(NULLIF(trim(p_timezone), ''), 'UTC');
  v_days int;
  v_granularity text;
  v_min_spend numeric;
  v_result jsonb;
  v_has_budget boolean := false;
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  IF p_date_from IS NULL OR p_date_to IS NULL THEN
    RAISE EXCEPTION 'date_from and date_to are required';
  END IF;

  v_days := GREATEST(1, (p_date_to - p_date_from) + 1);
  IF v_days <= 31 THEN
    v_granularity := 'day';
  ELSIF v_days <= 120 THEN
    v_granularity := 'week';
  ELSE
    v_granularity := 'month';
  END IF;

  -- Product-category budgets are uncommon; detect any overlapping budget_targets
  -- whose category string matches an allocation category_name in scope.
  SELECT EXISTS (
    SELECT 1
    FROM public.budget_targets bt
    WHERE bt.organization_id = v_org_id
      AND bt.period_start <= p_date_to
      AND bt.period_end >= p_date_from
      AND EXISTS (
        SELECT 1
        FROM public.invoice_allocations ia
        JOIN public.invoices i ON i.id = ia.invoice_id
        WHERE ia.organization_id = v_org_id
          AND public.is_purchasing_spend_invoice(i.status, i.ap_status, i.deleted_at)
          AND COALESCE(NULLIF(trim(ia.category_name), ''), 'Uncategorized') = bt.category
      )
  ) INTO v_has_budget;

  WITH eligible AS (
    SELECT
      ia.id AS allocation_id,
      ia.invoice_id,
      ia.amount,
      ia.allocation_type,
      COALESCE(NULLIF(trim(ia.category_name), ''), 'Uncategorized') AS category_name,
      COALESCE(ia.location_id, i.location_id) AS effective_location_id,
      i.invoice_date,
      i.vendor_id,
      COALESCE(NULLIF(trim(i.vendor_name), ''), 'Unknown vendor') AS vendor_name,
      i.invoice_number,
      i.status,
      i.ap_status,
      i.brand_id,
      i.organization_id
    FROM public.invoice_allocations ia
    JOIN public.invoices i ON i.id = ia.invoice_id
    WHERE ia.organization_id = v_org_id
      AND i.organization_id = v_org_id
      AND public.is_purchasing_spend_invoice(i.status, i.ap_status, i.deleted_at)
      AND ia.allocation_type = 'line_items'
      AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
      AND (
        p_location_ids IS NULL
        OR cardinality(p_location_ids) = 0
        OR COALESCE(ia.location_id, i.location_id) = ANY (p_location_ids)
      )
      AND (
        p_vendor_ids IS NULL
        OR cardinality(p_vendor_ids) = 0
        OR i.vendor_id = ANY (p_vendor_ids)
      )
      AND (
        p_category_names IS NULL
        OR cardinality(p_category_names) = 0
        OR COALESCE(NULLIF(trim(ia.category_name), ''), 'Uncategorized') = ANY (p_category_names)
      )
  ),
  current_rows AS (
    SELECT * FROM eligible e
    WHERE e.invoice_date >= p_date_from
      AND e.invoice_date <= p_date_to
  ),
  previous_rows AS (
    SELECT * FROM eligible e
    WHERE p_comparison_date_from IS NOT NULL
      AND p_comparison_date_to IS NOT NULL
      AND e.invoice_date >= p_comparison_date_from
      AND e.invoice_date <= p_comparison_date_to
  ),
  current_by_cat AS (
    SELECT
      category_name,
      round(sum(amount)::numeric, 2) AS spend,
      count(DISTINCT invoice_id)::bigint AS invoice_count,
      count(DISTINCT vendor_id) FILTER (WHERE vendor_id IS NOT NULL)::bigint AS vendor_count
    FROM current_rows
    GROUP BY category_name
  ),
  previous_by_cat AS (
    SELECT
      category_name,
      round(sum(amount)::numeric, 2) AS spend,
      count(DISTINCT invoice_id)::bigint AS invoice_count
    FROM previous_rows
    GROUP BY category_name
  ),
  all_categories AS (
    SELECT category_name FROM current_by_cat
    UNION
    SELECT category_name FROM previous_by_cat
  ),
  category_join AS (
    SELECT
      c.category_name,
      COALESCE(cur.spend, 0)::numeric AS current_spend,
      COALESCE(prev.spend, 0)::numeric AS previous_spend,
      COALESCE(cur.invoice_count, 0)::bigint AS invoice_count,
      COALESCE(cur.vendor_count, 0)::bigint AS vendor_count,
      (COALESCE(cur.spend, 0) - COALESCE(prev.spend, 0))::numeric AS absolute_variance,
      CASE
        WHEN COALESCE(prev.spend, 0) = 0 AND COALESCE(cur.spend, 0) = 0 THEN 0::numeric
        WHEN COALESCE(prev.spend, 0) = 0 THEN NULL
        ELSE round(((COALESCE(cur.spend, 0) - prev.spend) / abs(prev.spend)) * 100, 2)
      END AS percentage_variance
    FROM all_categories c
    LEFT JOIN current_by_cat cur ON cur.category_name = c.category_name
    LEFT JOIN previous_by_cat prev ON prev.category_name = c.category_name
  ),
  totals AS (
    SELECT
      COALESCE((SELECT sum(current_spend) FROM category_join), 0)::numeric AS total_spend,
      COALESCE((SELECT sum(previous_spend) FROM category_join), 0)::numeric AS previous_spend,
      COALESCE((SELECT count(DISTINCT invoice_id) FROM current_rows), 0)::bigint AS invoice_count
  ),
  largest_vendor_by_cat AS (
    SELECT DISTINCT ON (category_name)
      category_name,
      vendor_name,
      round(sum(amount)::numeric, 2) AS vendor_spend
    FROM current_rows
    GROUP BY category_name, vendor_name
    ORDER BY category_name, sum(amount) DESC
  ),
  budget_by_cat AS (
    SELECT
      bt.category AS category_name,
      round(sum(bt.target_amount)::numeric, 2) AS budget_amount
    FROM public.budget_targets bt
    WHERE bt.organization_id = v_org_id
      AND bt.period_start <= p_date_to
      AND bt.period_end >= p_date_from
    GROUP BY bt.category
  ),
  table_enriched AS (
    SELECT
      cj.*,
      CASE
        WHEN t.total_spend = 0 THEN 0
        ELSE round((cj.current_spend / t.total_spend) * 100, 2)
      END AS percentage_of_total,
      CASE
        WHEN cj.invoice_count = 0 THEN 0
        ELSE round(cj.current_spend / cj.invoice_count, 2)
      END AS average_invoice_value,
      lv.vendor_name AS largest_vendor,
      bb.budget_amount,
      CASE
        WHEN bb.budget_amount IS NULL THEN NULL
        ELSE round(cj.current_spend - bb.budget_amount, 2)
      END AS budget_variance,
      CASE
        WHEN cj.percentage_variance IS NULL THEN 'new'
        WHEN cj.percentage_variance > 5 THEN 'up'
        WHEN cj.percentage_variance < -5 THEN 'down'
        ELSE 'flat'
      END AS trend_status
    FROM category_join cj
    CROSS JOIN totals t
    LEFT JOIN largest_vendor_by_cat lv ON lv.category_name = cj.category_name
    LEFT JOIN budget_by_cat bb ON bb.category_name = cj.category_name
  ),
  ranked AS (
    SELECT *
    FROM table_enriched
    ORDER BY current_spend DESC
  ),
  summary_calc AS (
    SELECT
      t.total_spend,
      t.previous_spend,
      (t.total_spend - t.previous_spend) AS absolute_change,
      CASE
        WHEN t.previous_spend = 0 AND t.total_spend = 0 THEN 0::numeric
        WHEN t.previous_spend = 0 THEN NULL
        ELSE round(((t.total_spend - t.previous_spend) / abs(t.previous_spend)) * 100, 2)
      END AS percentage_change,
      t.invoice_count,
      CASE
        WHEN t.invoice_count = 0 THEN 0
        ELSE round(t.total_spend / t.invoice_count, 2)
      END AS average_invoice_value,
      (SELECT count(*) FROM ranked WHERE current_spend > 0)::int AS active_category_count,
      COALESCE((
        SELECT round((sum(s.current_spend) / NULLIF(t.total_spend, 0)) * 100, 2)
        FROM (SELECT current_spend FROM ranked ORDER BY current_spend DESC LIMIT 3) s
      ), 0) AS top_three_concentration_percentage
    FROM totals t
  ),
  largest AS (
    SELECT jsonb_build_object(
      'category', r.category_name,
      'spend', r.current_spend,
      'percentageOfTotal', r.percentage_of_total
    ) AS obj
    FROM ranked r
    WHERE r.current_spend > 0
    ORDER BY r.current_spend DESC
    LIMIT 1
  ),
  fastest AS (
    SELECT jsonb_build_object(
      'category', r.category_name,
      'currentSpend', r.current_spend,
      'previousSpend', r.previous_spend,
      'percentageChange', r.percentage_variance,
      'absoluteChange', r.absolute_variance
    ) AS obj
    FROM ranked r
    CROSS JOIN summary_calc sc
    WHERE r.current_spend >= GREATEST(100::numeric, sc.total_spend * 0.01)
      AND r.percentage_variance IS NOT NULL
    ORDER BY r.percentage_variance DESC
    LIMIT 1
  ),
  over_budget AS (
    SELECT count(*)::int AS cnt
    FROM ranked r
    WHERE r.budget_amount IS NOT NULL
      AND r.current_spend > r.budget_amount
  ),
  -- Distribution: top 8 + Other
  dist_ranked AS (
    SELECT
      category_name,
      current_spend,
      row_number() OVER (ORDER BY current_spend DESC) AS rn
    FROM ranked
    WHERE current_spend > 0
  ),
  distribution AS (
    SELECT category_name AS category, current_spend AS spend, false AS is_other
    FROM dist_ranked
    WHERE rn <= 8
    UNION ALL
    SELECT 'Other', COALESCE(sum(current_spend), 0), true
    FROM dist_ranked
    WHERE rn > 8
    HAVING sum(current_spend) > 0
  ),
  pareto AS (
    SELECT
      category_name AS category,
      current_spend AS spend,
      row_number() OVER (ORDER BY current_spend DESC) AS rank,
      round((current_spend / NULLIF(sum(current_spend) OVER (), 0)) * 100, 2) AS share_percentage,
      round((sum(current_spend) OVER (ORDER BY current_spend DESC rows unbounded preceding) / NULLIF(sum(current_spend) OVER (), 0)) * 100, 2) AS cumulative_percentage
    FROM ranked
    WHERE current_spend > 0
  ),
  -- Trend buckets for top categories
  top_trend_cats AS (
    SELECT category_name
    FROM ranked
    WHERE current_spend > 0
      AND (
        p_trend_categories IS NULL
        OR cardinality(p_trend_categories) = 0
        OR category_name = ANY (p_trend_categories)
      )
    ORDER BY current_spend DESC
    LIMIT CASE
      WHEN p_trend_categories IS NOT NULL AND cardinality(p_trend_categories) > 0 THEN 20
      ELSE 5
    END
  ),
  bucketed AS (
    SELECT
      CASE v_granularity
        WHEN 'day' THEN cr.invoice_date::text
        WHEN 'week' THEN to_char(date_trunc('week', cr.invoice_date::timestamp), 'IYYY-"W"IW')
        ELSE to_char(date_trunc('month', cr.invoice_date::timestamp), 'YYYY-MM')
      END AS bucket,
      CASE v_granularity
        WHEN 'day' THEN cr.invoice_date
        WHEN 'week' THEN date_trunc('week', cr.invoice_date::timestamp)::date
        ELSE date_trunc('month', cr.invoice_date::timestamp)::date
      END AS bucket_start,
      cr.category_name,
      sum(cr.amount) AS spend
    FROM current_rows cr
    WHERE cr.category_name IN (SELECT category_name FROM top_trend_cats)
    GROUP BY 1, 2, 3
  ),
  trend_json AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'bucket', b.bucket,
        'bucketStart', b.bucket_start,
        'category', b.category_name,
        'spend', round(b.spend::numeric, 2)
      )
      ORDER BY b.bucket_start, b.category_name
    ), '[]'::jsonb) AS arr
    FROM bucketed b
  ),
  vendor_for_selected AS (
    SELECT
      COALESCE(p_selected_category, (SELECT category_name FROM ranked WHERE current_spend > 0 ORDER BY current_spend DESC LIMIT 1)) AS selected_category
  ),
  vendor_current AS (
    SELECT
      vfs.selected_category AS category,
      cr.vendor_id,
      cr.vendor_name AS vendor,
      round(sum(cr.amount)::numeric, 2) AS spend,
      count(DISTINCT cr.invoice_id)::bigint AS invoice_count
    FROM current_rows cr
    CROSS JOIN vendor_for_selected vfs
    WHERE cr.category_name = vfs.selected_category
    GROUP BY vfs.selected_category, cr.vendor_id, cr.vendor_name
  ),
  vendor_previous AS (
    SELECT
      pr.vendor_id,
      round(sum(pr.amount)::numeric, 2) AS spend
    FROM previous_rows pr
    CROSS JOIN vendor_for_selected vfs
    WHERE pr.category_name = vfs.selected_category
    GROUP BY pr.vendor_id
  ),
  vendor_contrib AS (
    SELECT
      vc.category,
      vc.vendor,
      vc.vendor_id,
      vc.spend,
      vc.invoice_count,
      CASE
        WHEN sum(vc.spend) OVER () = 0 THEN 0
        ELSE round((vc.spend / sum(vc.spend) OVER ()) * 100, 2)
      END AS share_percentage,
      COALESCE(vp.spend, 0) AS previous_spend,
      (vc.spend - COALESCE(vp.spend, 0)) AS absolute_change,
      CASE
        WHEN COALESCE(vp.spend, 0) = 0 AND vc.spend = 0 THEN 0::numeric
        WHEN COALESCE(vp.spend, 0) = 0 THEN NULL
        ELSE round(((vc.spend - vp.spend) / abs(vp.spend)) * 100, 2)
      END AS percentage_change
    FROM vendor_current vc
    LEFT JOIN vendor_previous vp ON vp.vendor_id IS NOT DISTINCT FROM vc.vendor_id
  ),
  filter_categories AS (
    SELECT COALESCE(jsonb_agg(DISTINCT category_name ORDER BY category_name), '[]'::jsonb) AS arr
    FROM (
      SELECT category_name FROM eligible
      UNION
      SELECT category_name FROM ranked
    ) x
  ),
  filter_vendors AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object('id', vendor_id, 'name', vendor_name)
      ORDER BY vendor_name
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT DISTINCT vendor_id, vendor_name
      FROM eligible
      WHERE vendor_id IS NOT NULL
    ) v
  ),
  uncategorized_amt AS (
    SELECT COALESCE(sum(current_spend), 0)::numeric AS amount
    FROM ranked
    WHERE category_name = 'Uncategorized'
  )
  SELECT jsonb_build_object(
    'summary', jsonb_build_object(
      'totalSpend', sc.total_spend,
      'previousSpend', sc.previous_spend,
      'absoluteChange', sc.absolute_change,
      'percentageChange', sc.percentage_change,
      'largestCategory', (SELECT obj FROM largest),
      'fastestGrowingCategory', (SELECT obj FROM fastest),
      'activeCategoryCount', sc.active_category_count,
      'topThreeConcentrationPercentage', sc.top_three_concentration_percentage,
      'averageInvoiceValue', sc.average_invoice_value,
      'categoriesOverBudget', CASE WHEN v_has_budget THEN (SELECT cnt FROM over_budget) ELSE NULL END,
      'invoiceCount', sc.invoice_count,
      'uncategorizedSpend', (SELECT amount FROM uncategorized_amt)
    ),
    'categoryBreakdown', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'category', r.category_name,
          'currentSpend', r.current_spend,
          'previousSpend', r.previous_spend,
          'absoluteVariance', r.absolute_variance,
          'percentageVariance', r.percentage_variance,
          'percentageOfTotal', r.percentage_of_total
        )
        ORDER BY r.current_spend DESC
      )
      FROM ranked r
    ), '[]'::jsonb),
    'trend', (SELECT arr FROM trend_json),
    'distribution', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'category', d.category,
          'spend', d.spend,
          'isOther', d.is_other,
          'percentageOfTotal', CASE WHEN sc.total_spend = 0 THEN 0 ELSE round((d.spend / sc.total_spend) * 100, 2) END
        )
        ORDER BY d.spend DESC
      )
      FROM distribution d
      CROSS JOIN summary_calc sc
    ), '[]'::jsonb),
    'pareto', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'category', p.category,
          'spend', p.spend,
          'rank', p.rank,
          'sharePercentage', p.share_percentage,
          'cumulativePercentage', p.cumulative_percentage
        )
        ORDER BY p.rank
      )
      FROM pareto p
    ), '[]'::jsonb),
    'vendorContribution', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'category', v.category,
          'vendor', v.vendor,
          'vendorId', v.vendor_id,
          'spend', v.spend,
          'sharePercentage', v.share_percentage,
          'invoiceCount', v.invoice_count,
          'previousSpend', v.previous_spend,
          'absoluteChange', v.absolute_change,
          'percentageChange', v.percentage_change
        )
        ORDER BY v.spend DESC
      )
      FROM vendor_contrib v
    ), '[]'::jsonb),
    'tableRows', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'category', r.category_name,
          'currentSpend', r.current_spend,
          'previousSpend', r.previous_spend,
          'absoluteVariance', r.absolute_variance,
          'percentageVariance', r.percentage_variance,
          'percentageOfTotal', r.percentage_of_total,
          'invoiceCount', r.invoice_count,
          'vendorCount', r.vendor_count,
          'averageInvoiceValue', r.average_invoice_value,
          'largestVendor', r.largest_vendor,
          'budget', r.budget_amount,
          'budgetVariance', r.budget_variance,
          'trendStatus', r.trend_status
        )
        ORDER BY r.current_spend DESC
      )
      FROM ranked r
    ), '[]'::jsonb),
    'insights', '[]'::jsonb,
    'metadata', jsonb_build_object(
      'currency', 'USD',
      'timezone', v_tz,
      'dataFreshness', to_char(now() AT TIME ZONE v_tz, 'YYYY-MM-DD HH24:MI'),
      'hasBudgetData', v_has_budget,
      'granularity', v_granularity,
          'spendDefinition', 'Net purchasing spend from invoice line-item allocations on purchasing-eligible invoices (approved/scheduled/partially_paid/paid or matching ap_status), dated by invoice_date. Credits reduce allocation amounts when present. Excludes deleted, rejected, and duplicate invoices.',
      'filterOptions', jsonb_build_object(
        'categories', (SELECT arr FROM filter_categories),
        'vendors', (SELECT arr FROM filter_vendors)
      ),
      'selectedCategory', (SELECT selected_category FROM vendor_for_selected)
    )
  )
  INTO v_result
  FROM summary_calc sc;

  RETURN v_result;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_category_performance_report(
  uuid, uuid[], date, date, date, date, text[], uuid[], text, text, text[]
) TO authenticated, service_role;

-- Drill-down: vendors, products, invoices for one category
CREATE OR REPLACE FUNCTION public.get_category_performance_drilldown(
  p_organization_id uuid DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_location_ids uuid[] DEFAULT NULL,
  p_date_from date DEFAULT NULL,
  p_date_to date DEFAULT NULL,
  p_comparison_date_from date DEFAULT NULL,
  p_comparison_date_to date DEFAULT NULL,
  p_vendor_ids uuid[] DEFAULT NULL,
  p_timezone text DEFAULT 'UTC'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_category text := COALESCE(NULLIF(trim(p_category), ''), 'Uncategorized');
  v_result jsonb;
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;
  IF p_date_from IS NULL OR p_date_to IS NULL THEN
    RAISE EXCEPTION 'date_from and date_to are required';
  END IF;

  WITH eligible AS (
    SELECT
      ia.invoice_id,
      ia.amount,
      COALESCE(NULLIF(trim(ia.category_name), ''), 'Uncategorized') AS category_name,
      COALESCE(ia.location_id, i.location_id) AS effective_location_id,
      i.invoice_date,
      i.vendor_id,
      COALESCE(NULLIF(trim(i.vendor_name), ''), 'Unknown vendor') AS vendor_name,
      i.invoice_number,
      i.status,
      i.location_id,
      l.name AS location_name
    FROM public.invoice_allocations ia
    JOIN public.invoices i ON i.id = ia.invoice_id
    LEFT JOIN public.locations l ON l.id = COALESCE(ia.location_id, i.location_id)
    WHERE ia.organization_id = v_org_id
      AND public.is_purchasing_spend_invoice(i.status, i.ap_status, i.deleted_at)
      AND ia.allocation_type = 'line_items'
      AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
      AND COALESCE(NULLIF(trim(ia.category_name), ''), 'Uncategorized') = v_category
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR COALESCE(ia.location_id, i.location_id) = ANY (p_location_ids)
      )
      AND (
        p_vendor_ids IS NULL OR cardinality(p_vendor_ids) = 0
        OR i.vendor_id = ANY (p_vendor_ids)
      )
  ),
  current_rows AS (
    SELECT * FROM eligible
    WHERE invoice_date >= p_date_from AND invoice_date <= p_date_to
  ),
  previous_rows AS (
    SELECT * FROM eligible
    WHERE p_comparison_date_from IS NOT NULL
      AND p_comparison_date_to IS NOT NULL
      AND invoice_date >= p_comparison_date_from
      AND invoice_date <= p_comparison_date_to
  ),
  summary AS (
    SELECT
      round(COALESCE(sum(amount), 0)::numeric, 2) AS total_spend,
      count(DISTINCT invoice_id)::bigint AS invoice_count,
      count(DISTINCT vendor_id) FILTER (WHERE vendor_id IS NOT NULL)::bigint AS vendor_count
    FROM current_rows
  ),
  prev_total AS (
    SELECT round(COALESCE(sum(amount), 0)::numeric, 2) AS previous_spend
    FROM previous_rows
  ),
  vendors AS (
    SELECT
      cr.vendor_id,
      cr.vendor_name AS vendor,
      round(sum(cr.amount)::numeric, 2) AS spend,
      count(DISTINCT cr.invoice_id)::bigint AS invoice_count,
      COALESCE((
        SELECT round(sum(pr.amount)::numeric, 2)
        FROM previous_rows pr
        WHERE pr.vendor_id IS NOT DISTINCT FROM cr.vendor_id
      ), 0) AS previous_spend
    FROM current_rows cr
    GROUP BY cr.vendor_id, cr.vendor_name
  ),
  products AS (
    SELECT *
    FROM (
      SELECT
        COALESCE(p.id, ili.internal_product_id) AS product_id,
        COALESCE(p.name, ili.item_name, 'Unknown product') AS product,
        round(sum(COALESCE(ili.quantity, 0))::numeric, 4) AS quantity_purchased,
        (array_agg(ili.unit_price ORDER BY i.invoice_date DESC NULLS LAST))[1] AS current_unit_price,
        CASE WHEN sum(COALESCE(ili.quantity, 0)) = 0 THEN 0
             ELSE round(sum(COALESCE(ili.total_price, 0)) / NULLIF(sum(COALESCE(ili.quantity, 0)), 0), 4)
        END AS average_unit_price,
        round(sum(COALESCE(ili.total_price, 0))::numeric, 2) AS total_spend,
        (array_agg(COALESCE(i.vendor_name, 'Unknown vendor') ORDER BY i.invoice_date DESC NULLS LAST))[1] AS vendor
      FROM public.invoices i
      JOIN public.invoice_line_items ili ON ili.invoice_id = i.id
      LEFT JOIN public.products p ON p.id = ili.internal_product_id
      WHERE i.organization_id = v_org_id
        AND public.is_purchasing_spend_invoice(i.status, i.ap_status, i.deleted_at)
        AND i.invoice_date >= p_date_from
        AND i.invoice_date <= p_date_to
        AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
        AND COALESCE(NULLIF(trim(COALESCE(p.category, '')), ''), 'Uncategorized') = v_category
        AND (
          p_location_ids IS NULL OR cardinality(p_location_ids) = 0
          OR i.location_id = ANY (p_location_ids)
        )
        AND (
          p_vendor_ids IS NULL OR cardinality(p_vendor_ids) = 0
          OR i.vendor_id = ANY (p_vendor_ids)
        )
      GROUP BY COALESCE(p.id, ili.internal_product_id), COALESCE(p.name, ili.item_name, 'Unknown product')
      ORDER BY sum(COALESCE(ili.total_price, 0)) DESC
      LIMIT 200
    ) ranked_products
  ),
  invoices AS (
    SELECT
      cr.invoice_id,
      cr.invoice_number,
      cr.invoice_date,
      cr.vendor_name AS vendor,
      round(sum(cr.amount)::numeric, 2) AS amount,
      cr.status,
      cr.location_name AS location
    FROM current_rows cr
    GROUP BY cr.invoice_id, cr.invoice_number, cr.invoice_date, cr.vendor_name, cr.status, cr.location_name
    ORDER BY cr.invoice_date DESC
    LIMIT 500
  )
  SELECT jsonb_build_object(
    'category', v_category,
    'summary', jsonb_build_object(
      'totalSpend', s.total_spend,
      'previousSpend', pt.previous_spend,
      'absoluteChange', s.total_spend - pt.previous_spend,
      'percentageChange', CASE
        WHEN pt.previous_spend = 0 AND s.total_spend = 0 THEN 0
        WHEN pt.previous_spend = 0 THEN NULL
        ELSE round(((s.total_spend - pt.previous_spend) / abs(pt.previous_spend)) * 100, 2)
      END,
      'invoiceCount', s.invoice_count,
      'vendorCount', s.vendor_count,
      'averageInvoiceValue', CASE WHEN s.invoice_count = 0 THEN 0 ELSE round(s.total_spend / s.invoice_count, 2) END
    ),
    'vendors', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'vendor', v.vendor,
          'vendorId', v.vendor_id,
          'spend', v.spend,
          'sharePercentage', CASE WHEN s.total_spend = 0 THEN 0 ELSE round((v.spend / s.total_spend) * 100, 2) END,
          'invoiceCount', v.invoice_count,
          'averageInvoice', CASE WHEN v.invoice_count = 0 THEN 0 ELSE round(v.spend / v.invoice_count, 2) END,
          'absoluteChange', v.spend - v.previous_spend,
          'percentageChange', CASE
            WHEN v.previous_spend = 0 AND v.spend = 0 THEN 0
            WHEN v.previous_spend = 0 THEN NULL
            ELSE round(((v.spend - v.previous_spend) / abs(v.previous_spend)) * 100, 2)
          END
        )
        ORDER BY v.spend DESC
      )
      FROM vendors v
      CROSS JOIN summary s
    ), '[]'::jsonb),
    'products', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'product', p.product,
          'productId', p.product_id,
          'quantityPurchased', p.quantity_purchased,
          'currentUnitPrice', p.current_unit_price,
          'averageUnitPrice', p.average_unit_price,
          'totalSpend', p.total_spend,
          'vendor', p.vendor,
          'priceChange', CASE
            WHEN p.average_unit_price IS NULL OR p.current_unit_price IS NULL THEN NULL
            ELSE round(p.current_unit_price - p.average_unit_price, 4)
          END
        )
      )
      FROM products p
    ), '[]'::jsonb),
    'invoices', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'invoiceId', i.invoice_id,
          'invoiceNumber', i.invoice_number,
          'date', i.invoice_date,
          'vendor', i.vendor,
          'amount', i.amount,
          'status', i.status,
          'location', i.location
        )
        ORDER BY i.invoice_date DESC
      )
      FROM invoices i
    ), '[]'::jsonb)
  )
  INTO v_result
  FROM summary s
  CROSS JOIN prev_total pt;

  RETURN v_result;
END;
$$;

GRANT EXECUTE ON FUNCTION public.is_purchasing_spend_invoice(text, text, timestamptz)
  TO authenticated, service_role;

GRANT EXECUTE ON FUNCTION public.get_category_performance_drilldown(
  uuid, text, uuid[], date, date, date, date, uuid[], text
) TO authenticated, service_role;

-- Partial index for active (non-deleted) invoices by org + invoice_date.
-- Name reflects the predicate; deleted_at is not an indexed column.
CREATE INDEX IF NOT EXISTS idx_invoices_org_invoice_date_not_deleted
  ON public.invoices (organization_id, invoice_date)
  WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_invoice_allocations_invoice_type
