-- Source: 20260721000015_repair_vendor_operational_columns.sql
-- ==========================================================================

-- Repair vendor operational columns required by vendor list, onboarding,
-- AP routing, and accounting controls. This is intentionally idempotent so
-- drifted live databases can be brought back to the app contract safely.

BEGIN;

ALTER TABLE public.vendors
  ADD COLUMN IF NOT EXISTS contact_name text,
  ADD COLUMN IF NOT EXISTS phone text,
  ADD COLUMN IF NOT EXISTS address text,
  ADD COLUMN IF NOT EXISTS city text,
  ADD COLUMN IF NOT EXISTS state text,
  ADD COLUMN IF NOT EXISTS zip_code text,
  ADD COLUMN IF NOT EXISTS country text DEFAULT 'USA',
  ADD COLUMN IF NOT EXISTS payment_terms text DEFAULT 'net_30',
  ADD COLUMN IF NOT EXISTS notes text,
  ADD COLUMN IF NOT EXISTS whatsapp_number text,
  ADD COLUMN IF NOT EXISTS total_orders integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS onboarding_status text DEFAULT 'completed',
  ADD COLUMN IF NOT EXISTS ap_routing_preference text NOT NULL DEFAULT 'payments',
  ADD COLUMN IF NOT EXISTS ap_routing_updated_at timestamptz,
  ADD COLUMN IF NOT EXISTS ap_routing_updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS is_commissary_vendor boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS is_internal_transfer_vendor boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS allowed_expense_categories text[],
  ADD COLUMN IF NOT EXISTS use_org_accounting_defaults boolean NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS exclude_from_accounting boolean NOT NULL DEFAULT false;

ALTER TABLE public.vendors DROP CONSTRAINT IF EXISTS vendors_ap_routing_preference_check;
ALTER TABLE public.vendors
  ADD CONSTRAINT vendors_ap_routing_preference_check
  CHECK (ap_routing_preference IN ('payments', 'storage', 'accounting', 'manual_paid_only')) NOT VALID;

ALTER TABLE public.vendors DROP CONSTRAINT IF EXISTS vendors_file_routing_preference_check;
ALTER TABLE public.vendors
  ADD CONSTRAINT vendors_file_routing_preference_check
  CHECK (file_routing_preference IS NULL OR file_routing_preference IN ('storage', 'payments', 'accounting')) NOT VALID;

ALTER TABLE public.vendors DROP CONSTRAINT IF EXISTS vendors_payment_terms_check;
ALTER TABLE public.vendors
  ADD CONSTRAINT vendors_payment_terms_check
  CHECK (payment_terms IS NULL OR payment_terms IN ('net_15', 'net_30', 'net_45', 'net_60', 'due_on_receipt')) NOT VALID;

CREATE INDEX IF NOT EXISTS idx_vendors_org_ap_routing
  ON public.vendors (organization_id, ap_routing_preference);

DO $$
BEGIN
  IF to_regclass('tenant_template.vendors') IS NOT NULL THEN
    ALTER TABLE tenant_template.vendors
      ADD COLUMN IF NOT EXISTS contact_name text,
      ADD COLUMN IF NOT EXISTS phone text,
      ADD COLUMN IF NOT EXISTS address text,
      ADD COLUMN IF NOT EXISTS city text,
      ADD COLUMN IF NOT EXISTS state text,
      ADD COLUMN IF NOT EXISTS zip_code text,
      ADD COLUMN IF NOT EXISTS country text DEFAULT 'USA',
      ADD COLUMN IF NOT EXISTS payment_terms text DEFAULT 'net_30',
      ADD COLUMN IF NOT EXISTS notes text,
      ADD COLUMN IF NOT EXISTS whatsapp_number text,
      ADD COLUMN IF NOT EXISTS total_orders integer NOT NULL DEFAULT 0,
      ADD COLUMN IF NOT EXISTS onboarding_status text DEFAULT 'completed',
      ADD COLUMN IF NOT EXISTS ap_routing_preference text NOT NULL DEFAULT 'payments',
      ADD COLUMN IF NOT EXISTS ap_routing_updated_at timestamptz,
      ADD COLUMN IF NOT EXISTS ap_routing_updated_by uuid,
      ADD COLUMN IF NOT EXISTS is_commissary_vendor boolean NOT NULL DEFAULT false,
      ADD COLUMN IF NOT EXISTS is_internal_transfer_vendor boolean NOT NULL DEFAULT false,
      ADD COLUMN IF NOT EXISTS allowed_expense_categories text[],
      ADD COLUMN IF NOT EXISTS use_org_accounting_defaults boolean NOT NULL DEFAULT true,
      ADD COLUMN IF NOT EXISTS exclude_from_accounting boolean NOT NULL DEFAULT false;

    ALTER TABLE tenant_template.vendors DROP CONSTRAINT IF EXISTS vendors_ap_routing_preference_check;
    ALTER TABLE tenant_template.vendors
      ADD CONSTRAINT vendors_ap_routing_preference_check
      CHECK (ap_routing_preference IN ('payments', 'storage', 'accounting', 'manual_paid_only')) NOT VALID;

    ALTER TABLE tenant_template.vendors DROP CONSTRAINT IF EXISTS vendors_file_routing_preference_check;
    ALTER TABLE tenant_template.vendors
      ADD CONSTRAINT vendors_file_routing_preference_check
      CHECK (file_routing_preference IS NULL OR file_routing_preference IN ('storage', 'payments', 'accounting')) NOT VALID;

    ALTER TABLE tenant_template.vendors DROP CONSTRAINT IF EXISTS vendors_payment_terms_check;
    ALTER TABLE tenant_template.vendors
      ADD CONSTRAINT vendors_payment_terms_check
      CHECK (payment_terms IS NULL OR payment_terms IN ('net_15', 'net_30', 'net_45', 'net_60', 'due_on_receipt')) NOT VALID;

    CREATE INDEX IF NOT EXISTS idx_tenant_template_vendors_org_ap_routing
      ON tenant_template.vendors (organization_id, ap_routing_preference);
  END IF;
END $$;

DO $$
DECLARE
  schema_record record;
BEGIN
  IF to_regclass('public.tenant_registry') IS NULL THEN
    RETURN;
  END IF;

  FOR schema_record IN
    SELECT schema_name
    FROM public.tenant_registry
    WHERE schema_name IS NOT NULL
      AND schema_name ~ '^tenant_[a-z0-9_]+$'
      AND to_regnamespace(schema_name) IS NOT NULL
      AND to_regclass(format('%I.vendors', schema_name)) IS NOT NULL
  LOOP
    EXECUTE format($sql$
      ALTER TABLE %I.vendors
        ADD COLUMN IF NOT EXISTS contact_name text,
        ADD COLUMN IF NOT EXISTS phone text,
        ADD COLUMN IF NOT EXISTS address text,
        ADD COLUMN IF NOT EXISTS city text,
        ADD COLUMN IF NOT EXISTS state text,
        ADD COLUMN IF NOT EXISTS zip_code text,
        ADD COLUMN IF NOT EXISTS country text DEFAULT 'USA',
        ADD COLUMN IF NOT EXISTS payment_terms text DEFAULT 'net_30',
        ADD COLUMN IF NOT EXISTS notes text,
        ADD COLUMN IF NOT EXISTS whatsapp_number text,
        ADD COLUMN IF NOT EXISTS total_orders integer NOT NULL DEFAULT 0,
        ADD COLUMN IF NOT EXISTS onboarding_status text DEFAULT 'completed',
        ADD COLUMN IF NOT EXISTS ap_routing_preference text NOT NULL DEFAULT 'payments',
        ADD COLUMN IF NOT EXISTS ap_routing_updated_at timestamptz,
        ADD COLUMN IF NOT EXISTS ap_routing_updated_by uuid,
        ADD COLUMN IF NOT EXISTS is_commissary_vendor boolean NOT NULL DEFAULT false,
        ADD COLUMN IF NOT EXISTS is_internal_transfer_vendor boolean NOT NULL DEFAULT false,
        ADD COLUMN IF NOT EXISTS allowed_expense_categories text[],
        ADD COLUMN IF NOT EXISTS use_org_accounting_defaults boolean NOT NULL DEFAULT true,
        ADD COLUMN IF NOT EXISTS exclude_from_accounting boolean NOT NULL DEFAULT false;
    $sql$, schema_record.schema_name);

    EXECUTE format('ALTER TABLE %I.vendors DROP CONSTRAINT IF EXISTS vendors_ap_routing_preference_check;', schema_record.schema_name);
    EXECUTE format('ALTER TABLE %I.vendors ADD CONSTRAINT vendors_ap_routing_preference_check CHECK (ap_routing_preference IN (''payments'', ''storage'', ''accounting'', ''manual_paid_only'')) NOT VALID;', schema_record.schema_name);
    EXECUTE format('ALTER TABLE %I.vendors DROP CONSTRAINT IF EXISTS vendors_file_routing_preference_check;', schema_record.schema_name);
    EXECUTE format('ALTER TABLE %I.vendors ADD CONSTRAINT vendors_file_routing_preference_check CHECK (file_routing_preference IS NULL OR file_routing_preference IN (''storage'', ''payments'', ''accounting'')) NOT VALID;', schema_record.schema_name);
    EXECUTE format('ALTER TABLE %I.vendors DROP CONSTRAINT IF EXISTS vendors_payment_terms_check;', schema_record.schema_name);
    EXECUTE format('ALTER TABLE %I.vendors ADD CONSTRAINT vendors_payment_terms_check CHECK (payment_terms IS NULL OR payment_terms IN (''net_15'', ''net_30'', ''net_45'', ''net_60'', ''due_on_receipt'')) NOT VALID;', schema_record.schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I.vendors (organization_id, ap_routing_preference);', 'idx_' || left(schema_record.schema_name, 30) || '_vendors_ap_routing', schema_record.schema_name);
  END LOOP;
END $$;

COMMIT;

-- ==========================================================================
-- Source: 20260721000016_guard_invoice_workflow_scope.sql
-- ==========================================================================

BEGIN;

ALTER TABLE public.invoices
  ADD COLUMN IF NOT EXISTS raw_text text,
  ADD COLUMN IF NOT EXISTS extraction_method text,
  ADD COLUMN IF NOT EXISTS purchase_order_number text;

CREATE OR REPLACE FUNCTION public.save_invoice_workflow(
  p_invoice_id UUID DEFAULT NULL,
  p_invoice JSONB DEFAULT '{}'::jsonb,
  p_line_items JSONB DEFAULT '[]'::jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_existing public.invoices%ROWTYPE;
  v_invoice public.invoices%ROWTYPE;
  v_payload JSONB;
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
  v_actor_role TEXT;
BEGIN
  v_payload := COALESCE(p_invoice, '{}'::jsonb)
    - 'id'
    - 'created_at'
    - 'updated_at'
    - 'deleted_at'
    - 'deleted_by'
    - 'vendor_address';

  IF p_invoice_id IS NULL THEN
    v_org_id := NULLIF(v_payload->>'organization_id', '')::UUID;

    IF v_org_id IS NULL THEN
      v_org_id := public.get_my_org();
      v_payload := jsonb_set(v_payload, '{organization_id}', to_jsonb(v_org_id), true);
    END IF;

    PERFORM public.assert_org_actor(v_org_id);

    v_actor_role := public.get_auth_role();
    v_brand_id := NULLIF(v_payload->>'brand_id', '')::UUID;
    v_location_id := NULLIF(v_payload->>'location_id', '')::UUID;

    IF (v_brand_id IS NULL OR v_location_id IS NULL)
      AND v_actor_role IN ('location_manager', 'ground_staff') THEN
      SELECT COALESCE(v_brand_id, p.brand_id), COALESCE(v_location_id, p.location_id)
        INTO v_brand_id, v_location_id
      FROM public.profiles p
      WHERE p.id = auth.uid();

      IF v_brand_id IS NULL AND v_location_id IS NOT NULL THEN
        SELECT l.brand_id
          INTO v_brand_id
        FROM public.locations l
        WHERE l.id = v_location_id;
      END IF;

      IF v_brand_id IS NOT NULL THEN
        v_payload := jsonb_set(v_payload, '{brand_id}', to_jsonb(v_brand_id), true);
      END IF;
      IF v_location_id IS NOT NULL THEN
        v_payload := jsonb_set(v_payload, '{location_id}', to_jsonb(v_location_id), true);
      END IF;
    END IF;

    IF v_brand_id IS NULL OR v_location_id IS NULL THEN
      RAISE EXCEPTION 'Invoice requires brand and location context';
    END IF;

    v_invoice := jsonb_populate_record(NULL::public.invoices, v_payload);

    INSERT INTO public.invoices (
      vendor_name,
      invoice_number,
      total_amount,
      status,
      account_number,
      subtotal,
      organization_id,
      location_id,
      payment_status,
      vendor_id,
      due_date,
      delivery_fee,
      fuel_surcharge,
      other_charges,
      tax_amount,
      currency,
      source,
      file_url,
      line_items,
      validation_results,
      validation_notes,
      approved_by,
      approved_date,
      location,
      created_by,
      extraction_method,
      raw_text,
      purchase_order_number,
      invoice_date,
      payment_terms,
      file_destination,
      purchase_order_id,
      matched_order_id,
      match_status,
      brand_id,
      ap_status,
      action_required_reason,
      action_required_details,
      assigned_reviewer_id,
      payment_account_id,
      scheduled_payment_date,
      closed_at,
      closed_by,
      ap_metadata,
      paid_amount,
      payment_reference,
      credit_applied,
      credit_reason,
      version_number,
      ap_routing_destination,
      ap_routing_resolved_at
    ) VALUES (
      v_invoice.vendor_name,
      v_invoice.invoice_number,
      v_invoice.total_amount,
      COALESCE(v_invoice.status, 'pending_review'),
      v_invoice.account_number,
      v_invoice.subtotal,
      v_org_id,
      v_invoice.location_id,
      COALESCE(v_invoice.payment_status, 'unpaid'),
      v_invoice.vendor_id,
      v_invoice.due_date,
      v_invoice.delivery_fee,
      v_invoice.fuel_surcharge,
      v_invoice.other_charges,
      v_invoice.tax_amount,
      COALESCE(v_invoice.currency, 'USD'),
      v_invoice.source,
      v_invoice.file_url,
      COALESCE(v_invoice.line_items, '[]'::jsonb),
      COALESCE(v_invoice.validation_results, '{}'::jsonb),
      v_invoice.validation_notes,
      v_invoice.approved_by,
      v_invoice.approved_date,
      v_invoice.location,
      COALESCE(v_invoice.created_by, auth.uid()),
      v_invoice.extraction_method,
      v_invoice.raw_text,
      v_invoice.purchase_order_number,
      v_invoice.invoice_date,
      v_invoice.payment_terms,
      v_invoice.file_destination,
      v_invoice.purchase_order_id,
      v_invoice.matched_order_id,
      v_invoice.match_status,
      v_invoice.brand_id,
      COALESCE(v_invoice.ap_status, 'processing'),
      v_invoice.action_required_reason,
      v_invoice.action_required_details,
      v_invoice.assigned_reviewer_id,
      v_invoice.payment_account_id,
      v_invoice.scheduled_payment_date,
      v_invoice.closed_at,
      v_invoice.closed_by,
      COALESCE(v_invoice.ap_metadata, '{}'::jsonb),
      COALESCE(v_invoice.paid_amount, 0),
      v_invoice.payment_reference,
      COALESCE(v_invoice.credit_applied, 0),
      v_invoice.credit_reason,
      COALESCE(v_invoice.version_number, 1),
      v_invoice.ap_routing_destination,
      v_invoice.ap_routing_resolved_at
    )
    RETURNING * INTO v_invoice;
  ELSE
    SELECT *
      INTO v_existing
    FROM public.invoices
    WHERE id = p_invoice_id
      AND deleted_at IS NULL
    FOR UPDATE;

    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION 'Invoice not found';
    END IF;

    PERFORM public.assert_org_actor(v_existing.organization_id);

    IF v_payload ? 'organization_id'
      AND NULLIF(v_payload->>'organization_id', '')::UUID IS DISTINCT FROM v_existing.organization_id THEN
      RAISE EXCEPTION 'Invoice organization cannot be changed';
    END IF;

    v_invoice := jsonb_populate_record(v_existing, v_payload);

    IF v_invoice.brand_id IS NULL OR v_invoice.location_id IS NULL THEN
      RAISE EXCEPTION 'Invoice requires brand and location context';
    END IF;

    UPDATE public.invoices
       SET vendor_name = v_invoice.vendor_name,
           invoice_number = v_invoice.invoice_number,
           total_amount = v_invoice.total_amount,
           status = v_invoice.status,
           account_number = v_invoice.account_number,
           subtotal = v_invoice.subtotal,
           location_id = v_invoice.location_id,
           payment_status = v_invoice.payment_status,
           vendor_id = v_invoice.vendor_id,
           due_date = v_invoice.due_date,
           delivery_fee = v_invoice.delivery_fee,
           fuel_surcharge = v_invoice.fuel_surcharge,
           other_charges = v_invoice.other_charges,
           tax_amount = v_invoice.tax_amount,
           currency = v_invoice.currency,
           source = v_invoice.source,
           file_url = v_invoice.file_url,
           line_items = v_invoice.line_items,
           validation_results = v_invoice.validation_results,
           validation_notes = v_invoice.validation_notes,
           approved_by = v_invoice.approved_by,
           approved_date = v_invoice.approved_date,
           location = v_invoice.location,
           extraction_method = v_invoice.extraction_method,
           raw_text = v_invoice.raw_text,
           purchase_order_number = v_invoice.purchase_order_number,
           invoice_date = v_invoice.invoice_date,
           payment_terms = v_invoice.payment_terms,
           file_destination = v_invoice.file_destination,
           purchase_order_id = v_invoice.purchase_order_id,
           matched_order_id = v_invoice.matched_order_id,
           match_status = v_invoice.match_status,
           brand_id = v_invoice.brand_id,
           ap_status = v_invoice.ap_status,
           action_required_reason = v_invoice.action_required_reason,
           action_required_details = v_invoice.action_required_details,
           assigned_reviewer_id = v_invoice.assigned_reviewer_id,
           payment_account_id = v_invoice.payment_account_id,
           scheduled_payment_date = v_invoice.scheduled_payment_date,
           closed_at = v_invoice.closed_at,
           closed_by = v_invoice.closed_by,
           ap_metadata = v_invoice.ap_metadata,
           paid_amount = v_invoice.paid_amount,
           payment_reference = v_invoice.payment_reference,
           credit_applied = v_invoice.credit_applied,
           credit_reason = v_invoice.credit_reason,
           version_number = COALESCE(v_existing.version_number, 1) + 1,
           ap_routing_destination = v_invoice.ap_routing_destination,
           ap_routing_resolved_at = v_invoice.ap_routing_resolved_at,
           updated_at = now()
     WHERE id = p_invoice_id
     RETURNING * INTO v_invoice;
  END IF;

  IF jsonb_typeof(COALESCE(p_line_items, '[]'::jsonb)) = 'array' AND jsonb_array_length(COALESCE(p_line_items, '[]'::jsonb)) > 0 THEN
    PERFORM public.upsert_invoice_line_items(v_invoice.id, p_line_items);
  END IF;

  RETURN to_jsonb(v_invoice);
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260721000017_mandatory_invoice_payment_scope_ids.sql
-- ==========================================================================

BEGIN;

-- Locally, invoices/payments both have 0 rows right now (read live state first):
--   SELECT count(*) FILTER (WHERE brand_id IS NULL), count(*) FILTER (WHERE location_id IS NULL)
--   FROM invoices / payments  ->  0, 0 for both tables.
-- So the NOT NULL constraints below apply cleanly with no backfill/triage needed locally.
-- PROD CHECKLIST: re-run that same count against prod before applying there -- prod has real
-- data and is exactly where the black-hole bug (Phases 1-3, already applied) has been letting
-- null-scoped rows accumulate. If prod has any, they need manual scope assignment first or this
-- migration will fail to apply.

-- ── 1. ingest_email_invoice: stop inserting the black-hole row ────────────────────────────────
-- The no-match branch used to insert an invoice with brand_id/location_id NULL (flagged via
-- action_required_reason, but that's about to become impossible under the NOT NULL constraints
-- added below). Now that process-email-invoices (already shipped) emails the sender when a
-- match fails, there's nothing useful left to create here -- no location to scope the row to,
-- and no human in the loop to assign one later. Don't insert; report the miss and let the
-- caller's existing bounce-email logic (gated on matched === false, already shipped) handle it.
CREATE OR REPLACE FUNCTION public.ingest_email_invoice(
  p_recipient_email text,
  p_fallback_organization_id uuid DEFAULT NULL,
  p_invoice jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_recipient_email text;
  v_location_email public.location_email_addresses%ROWTYPE;
  v_vendor_name text;
  v_invoice_number text;
  v_total_amount numeric := 0;
  v_invoice_id uuid;
  v_system_user_id uuid := '99999999-9999-9999-9999-999999999999';
  v_metadata jsonb;
BEGIN
  v_recipient_email := lower(btrim(COALESCE(p_recipient_email, '')));

  IF v_recipient_email = '' THEN
    v_recipient_email := NULL;
  END IF;

  v_vendor_name := COALESCE(NULLIF(btrim(p_invoice->>'vendor_name'), ''), 'Unknown Vendor (Auto-Ingested)');
  v_invoice_number := COALESCE(
    NULLIF(btrim(p_invoice->>'invoice_number'), ''),
    'EMAIL-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS') || '-' || substr(gen_random_uuid()::text, 1, 8)
  );

  BEGIN
    v_total_amount := COALESCE(NULLIF(btrim(p_invoice->>'total_amount'), '')::numeric, 0);
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    v_total_amount := 0;
  END;

  SELECT lea.*
    INTO v_location_email
  FROM public.location_email_addresses lea
  WHERE lower(lea.email) = v_recipient_email
    AND lea.is_active = true
    AND lea.deleted_at IS NULL
  LIMIT 1;

  IF FOUND THEN
    v_metadata := COALESCE(p_invoice->'ap_metadata', '{}'::jsonb)
      || jsonb_build_object(
        'ingest_recipient', v_recipient_email,
        'received_at', now(),
        'matched_location_email_id', v_location_email.id,
        'source', 'email_import'
      );

    INSERT INTO public.invoices (
      vendor_name,
      invoice_number,
      total_amount,
      status,
      ap_status,
      source,
      file_url,
      organization_id,
      brand_id,
      location_id,
      created_by,
      ap_metadata
    ) VALUES (
      v_vendor_name,
      v_invoice_number,
      v_total_amount,
      'extracting',
      'processing',
      'email_import',
      NULLIF(p_invoice->>'file_url', ''),
      v_location_email.organization_id,
      v_location_email.brand_id,
      v_location_email.location_id,
      v_system_user_id,
      v_metadata
    )
    RETURNING id INTO v_invoice_id;

    RETURN jsonb_build_object(
      'invoice_id', v_invoice_id,
      'matched', true,
      'organization_id', v_location_email.organization_id,
      'brand_id', v_location_email.brand_id,
      'location_id', v_location_email.location_id,
      'recipient_email', v_recipient_email
    );
  END IF;

  -- No location matched: nothing to scope the row to under the NOT NULL constraints below.
  -- Report the miss; the caller emails the sender instead of us creating an orphaned row.
  RETURN jsonb_build_object(
    'invoice_id', NULL,
    'matched', false,
    'recipient_email', v_recipient_email,
    'warning', 'no_location_email_match'
  );
END;
$$;

REVOKE ALL ON FUNCTION public.ingest_email_invoice(text, uuid, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.ingest_email_invoice(text, uuid, jsonb) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.ingest_email_invoice(text, uuid, jsonb) TO service_role;

-- ── 2. tenant_id column + auto-derive trigger (invoices, payments) ────────────────────────────
ALTER TABLE public.invoices ADD COLUMN IF NOT EXISTS tenant_id uuid REFERENCES public.tenants(id);
ALTER TABLE public.payments ADD COLUMN IF NOT EXISTS tenant_id uuid REFERENCES public.tenants(id);

CREATE OR REPLACE FUNCTION public.sync_tenant_id_from_organization()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    SELECT o.tenant_id INTO NEW.tenant_id
    FROM public.organizations o
    WHERE o.id = NEW.organization_id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_invoices_sync_tenant_id ON public.invoices;
CREATE TRIGGER trg_invoices_sync_tenant_id
  BEFORE INSERT OR UPDATE OF organization_id ON public.invoices
  FOR EACH ROW EXECUTE FUNCTION public.sync_tenant_id_from_organization();

DROP TRIGGER IF EXISTS trg_payments_sync_tenant_id ON public.payments;
CREATE TRIGGER trg_payments_sync_tenant_id
  BEFORE INSERT OR UPDATE OF organization_id ON public.payments
  FOR EACH ROW EXECUTE FUNCTION public.sync_tenant_id_from_organization();

-- Backfill (no-op locally -- both tables are empty -- required for prod/staging).
UPDATE public.invoices i SET tenant_id = o.tenant_id
FROM public.organizations o
WHERE i.organization_id = o.id AND i.tenant_id IS NULL;

UPDATE public.payments p SET tenant_id = o.tenant_id
FROM public.organizations o
WHERE p.organization_id = o.id AND p.tenant_id IS NULL;

-- ── 3. Mandatory scope: all 4 IDs required on invoices and payments ───────────────────────────
ALTER TABLE public.invoices
  ALTER COLUMN organization_id SET NOT NULL,
  ALTER COLUMN tenant_id SET NOT NULL,
  ALTER COLUMN brand_id SET NOT NULL,
  ALTER COLUMN location_id SET NOT NULL;

ALTER TABLE public.payments
  ALTER COLUMN organization_id SET NOT NULL,
  ALTER COLUMN tenant_id SET NOT NULL,
  ALTER COLUMN brand_id SET NOT NULL,
  ALTER COLUMN location_id SET NOT NULL;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260721000018_production_onboarding_security_hardening.sql
-- ==========================================================================

-- Production hardening for onboarding security gaps:
-- 1. Lock direct access to hierarchy review submissions behind SECURITY DEFINER RPCs.
-- 2. Remove the temporary contact OTP bypass and fail closed for old clients.
-- 3. Canonicalize the old brand_manager role to branch_manager.
-- 4. Serialize invitation acceptance so a token can only be accepted once.

BEGIN;

ALTER TABLE public.onboarding_hierarchy_submissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.onboarding_hierarchy_submissions FORCE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE public.onboarding_hierarchy_submissions FROM public, anon, authenticated;
GRANT ALL ON TABLE public.onboarding_hierarchy_submissions TO service_role;

DROP POLICY IF EXISTS onboarding_hierarchy_submissions_no_direct_select ON public.onboarding_hierarchy_submissions;
DROP POLICY IF EXISTS onboarding_hierarchy_submissions_no_direct_insert ON public.onboarding_hierarchy_submissions;
DROP POLICY IF EXISTS onboarding_hierarchy_submissions_no_direct_update ON public.onboarding_hierarchy_submissions;
DROP POLICY IF EXISTS onboarding_hierarchy_submissions_no_direct_delete ON public.onboarding_hierarchy_submissions;

CREATE POLICY onboarding_hierarchy_submissions_no_direct_select
  ON public.onboarding_hierarchy_submissions
  FOR SELECT
  TO authenticated
  USING (false);

CREATE POLICY onboarding_hierarchy_submissions_no_direct_insert
  ON public.onboarding_hierarchy_submissions
  FOR INSERT
  TO authenticated
  WITH CHECK (false);

CREATE POLICY onboarding_hierarchy_submissions_no_direct_update
  ON public.onboarding_hierarchy_submissions
  FOR UPDATE
  TO authenticated
  USING (false)
  WITH CHECK (false);

CREATE POLICY onboarding_hierarchy_submissions_no_direct_delete
  ON public.onboarding_hierarchy_submissions
  FOR DELETE
  TO authenticated
  USING (false);

CREATE OR REPLACE FUNCTION public.request_onboarding_contact_dev_otp(
  p_channel text,
  p_target text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  RAISE EXCEPTION 'Temporary development contact OTP bypass is disabled in production';
END;
$$;

CREATE OR REPLACE FUNCTION public.verify_onboarding_contact_dev_otp(
  p_channel text,
  p_target text,
  p_code text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  RAISE EXCEPTION 'Temporary development contact OTP bypass is disabled in production';
END;
$$;

REVOKE EXECUTE ON FUNCTION public.request_onboarding_contact_dev_otp(text, text) FROM public, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.verify_onboarding_contact_dev_otp(text, text, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.request_onboarding_contact_dev_otp(text, text) TO service_role;
GRANT EXECUTE ON FUNCTION public.verify_onboarding_contact_dev_otp(text, text, text) TO service_role;

UPDATE public.profiles SET role = 'branch_manager' WHERE role = 'brand_manager';
UPDATE public.invitations SET role = 'branch_manager' WHERE role = 'brand_manager';
UPDATE public.organization_members SET role = 'branch_manager' WHERE role = 'brand_manager';
UPDATE public.brand_members SET role = 'branch_manager' WHERE role = 'brand_manager';
UPDATE public.location_members SET role = 'branch_manager' WHERE role = 'brand_manager';
DELETE FROM public.roles
WHERE name = 'brand_manager'
  AND EXISTS (SELECT 1 FROM public.roles WHERE name = 'branch_manager');

UPDATE public.roles SET name = 'branch_manager' WHERE name = 'brand_manager';

CREATE OR REPLACE FUNCTION public.normalize_app_role(p_role text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE lower(NULLIF(trim(p_role), ''))
    WHEN 'owner' THEN 'org_manager'
    WHEN 'org_owner' THEN 'org_manager'
    WHEN 'organization_owner' THEN 'org_manager'
    WHEN 'manager' THEN 'branch_manager'
    WHEN 'brand_manager' THEN 'branch_manager'
    WHEN 'admin' THEN 'platform_admin'
    ELSE lower(NULLIF(trim(p_role), ''))
  END;
$$;

CREATE OR REPLACE FUNCTION public.is_manager_or_above()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT public.get_auth_role() IN (
    'location_manager',
    'branch_manager',
    'org_manager',
    'tenant_super_admin',
    'platform_admin'
  );
$$;

CREATE OR REPLACE FUNCTION public.access_role_rank(p_role text)
RETURNS integer
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE public.normalize_app_role(p_role)
    WHEN 'ground_staff' THEN 10
    WHEN 'location_manager' THEN 20
    WHEN 'branch_manager' THEN 30
    WHEN 'org_manager' THEN 40
    WHEN 'tenant_super_admin' THEN 50
    WHEN 'platform_admin' THEN 60
    ELSE 0
  END;
$$;

CREATE OR REPLACE FUNCTION public.can_invite_role(target_role text)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  caller_role text := public.get_auth_role();
  normalized_target text := public.normalize_app_role(target_role);
BEGIN
  IF caller_role = 'platform_admin' THEN
    RETURN normalized_target IN ('ground_staff', 'location_manager', 'branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin');
  END IF;

  IF caller_role = 'tenant_super_admin' THEN
    RETURN normalized_target IN ('ground_staff', 'location_manager', 'branch_manager', 'org_manager', 'tenant_super_admin');
  END IF;

  IF caller_role = 'org_manager' THEN
    RETURN normalized_target IN ('ground_staff', 'location_manager', 'branch_manager');
  END IF;

  IF caller_role = 'branch_manager' THEN
    RETURN normalized_target IN ('ground_staff', 'location_manager');
  END IF;

  RETURN false;
END;
$$;

CREATE OR REPLACE FUNCTION public.normalize_invitation_role_before_check()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role text;
BEGIN
  v_role := lower(trim(COALESCE(NEW.role, '')));
  v_role := replace(replace(v_role, '-', '_'), ' ', '_');

  NEW.role := CASE
    WHEN v_role IN ('tenant', 'tenant_admin', 'tenant_superadmin', 'tenant_super_admin') THEN 'tenant_super_admin'
    WHEN v_role IN ('owner', 'org_owner', 'organization_owner') AND NEW.organization_id IS NULL THEN 'tenant_super_admin'
    WHEN v_role IN ('owner', 'org_owner', 'organization_owner', 'org_manager', 'organization_manager') THEN 'org_manager'
    WHEN v_role IN ('brand_manager', 'branch_manager') THEN 'branch_manager'
    WHEN v_role IN ('manager', 'location_manager') THEN 'location_manager'
    WHEN v_role IN ('ground_staff', 'staff') THEN 'ground_staff'
    WHEN v_role IN ('admin', 'platform_admin') THEN 'platform_admin'
    ELSE v_role
  END;

  RETURN NEW;
END;
$$;

ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_role_check;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_role_check CHECK (
  role IN ('ground_staff', 'location_manager', 'branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin')
);

ALTER TABLE public.invitations DROP CONSTRAINT IF EXISTS invitations_role_check;
ALTER TABLE public.invitations ADD CONSTRAINT invitations_role_check CHECK (
  role IN ('ground_staff', 'location_manager', 'branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin')
);

CREATE OR REPLACE FUNCTION public.accept_invitation(p_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_invite record;
  v_user_id uuid;
  v_user_email text;
  v_role text;
  v_tenant_id uuid;
  v_business_verification_required boolean := true;
  v_coupon_code text;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND closed_at IS NULL
    AND lower(email) = lower(v_user_email)
    AND (expires_at IS NULL OR expires_at > now())
  FOR UPDATE;

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  v_role := public.normalize_app_role(v_invite.role);
  v_tenant_id := v_invite.tenant_id;
  v_business_verification_required := COALESCE((v_invite.metadata->>'business_verification_required')::boolean, true);
  v_coupon_code := COALESCE(v_invite.metadata->>'coupon_code', v_invite.metadata#>>'{coupon,code}');

  IF v_tenant_id IS NULL AND v_invite.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO v_tenant_id FROM public.organizations WHERE id = v_invite.organization_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NULL THEN
    INSERT INTO public.tenants (name, owner_id, metadata)
    VALUES (
      COALESCE(v_invite.metadata->>'tenant_name', split_part(v_user_email, '@', 1), 'Tenant'),
      v_user_id,
      jsonb_build_object(
        'source', 'accept_invitation',
        'invitation_id', v_invite.id,
        'invited_email', v_invite.email,
        'business_verification_required', v_business_verification_required,
        'coupon_code', v_coupon_code
      )
    )
    RETURNING id INTO v_tenant_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NOT NULL THEN
    INSERT INTO public.tenant_members (tenant_id, user_id, role)
    VALUES (v_tenant_id, v_user_id, 'tenant_super_admin')
    ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    UPDATE public.tenants
    SET owner_id = COALESCE(owner_id, v_user_id),
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
          'business_verification_required', v_business_verification_required,
          'coupon_code', v_coupon_code
        ),
        updated_at = now()
    WHERE id = v_tenant_id;
  END IF;

  IF v_invite.organization_id IS NOT NULL THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_invite.organization_id, v_user_id, v_role)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.brand_id IS NOT NULL THEN
    INSERT INTO public.brand_members (brand_id, user_id, role)
    VALUES (v_invite.brand_id, v_user_id, v_role)
    ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.location_id IS NOT NULL THEN
    INSERT INTO public.location_members (location_id, user_id, role)
    VALUES (v_invite.location_id, v_user_id, v_role)
    ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  PERFORM set_config('app.trusted_profile_write', 'on', true);
  UPDATE public.profiles
  SET tenant_id = COALESCE(v_tenant_id, tenant_id),
      role = v_role,
      organization_id = COALESCE(v_invite.organization_id, organization_id),
      brand_id = COALESCE(v_invite.brand_id, brand_id),
      location_id = COALESCE(v_invite.location_id, location_id),
      coupon_code = COALESCE(v_coupon_code, coupon_code),
      business_verification_status = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'verified'
        ELSE business_verification_status
      END,
      onboarding_current_step = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'hierarchy_setup'
        ELSE onboarding_current_step
      END,
      updated_at = now()
  WHERE id = v_user_id;

  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id,
      role = v_role,
      tenant_id = COALESCE(tenant_id, v_tenant_id),
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
        'business_verification_required', v_business_verification_required,
        'coupon_code', v_coupon_code
      )
  WHERE id = v_invite.id
    AND accepted_at IS NULL
    AND closed_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', v_role,
    'tenant_id', COALESCE(v_tenant_id::text, ''),
    'organization_id', COALESCE(v_invite.organization_id::text, ''),
    'business_verification_required', v_business_verification_required,
    'coupon_code', COALESCE(v_coupon_code, '')
  )
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'role', v_role,
    'tenant_id', v_tenant_id,
    'organization_id', v_invite.organization_id,
    'business_verification_required', v_business_verification_required,
    'coupon_code', v_coupon_code
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.accept_invitation(text) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260721000019_production_reporting_and_backup_hardening.sql
-- ==========================================================================

BEGIN;

INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('db-backups', 'db-backups', false, 104857600, ARRAY['application/json'])
ON CONFLICT (id) DO UPDATE
SET public = false,
    file_size_limit = EXCLUDED.file_size_limit,
    allowed_mime_types = EXCLUDED.allowed_mime_types;

DROP POLICY IF EXISTS "Service role can manage db backups" ON storage.objects;
CREATE POLICY "Service role can manage db backups" ON storage.objects
  FOR ALL TO service_role
  USING (bucket_id = 'db-backups')
  WITH CHECK (bucket_id = 'db-backups');

DROP POLICY IF EXISTS "Authenticated users cannot read db backups" ON storage.objects;
CREATE POLICY "Authenticated users cannot read db backups" ON storage.objects
  FOR SELECT TO authenticated
  USING (false);

CREATE OR REPLACE FUNCTION public.run_custom_report(p_metrics TEXT[], p_dimension TEXT, p_start_date DATE DEFAULT NULL, p_end_date DATE DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org UUID := public.get_auth_org();
  v_start DATE := COALESCE(p_start_date, CURRENT_DATE - INTERVAL '30 days');
  v_end DATE := COALESCE(p_end_date, CURRENT_DATE);
  v_result JSONB;
BEGIN
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'organization context is required';
  END IF;

  IF p_dimension NOT IN ('date', 'week', 'month', 'location') THEN
    RAISE EXCEPTION 'unsupported report dimension: %', p_dimension;
  END IF;

  WITH pos_rollup AS (
    SELECT
      CASE p_dimension
        WHEN 'date' THEN to_char(date_trunc('day', po.order_date), 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', po.order_date), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', po.order_date), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Unassigned')
      END AS dimension,
      SUM(po.total_amount)::NUMERIC AS sales_revenue,
      COUNT(*)::NUMERIC AS pos_transaction_count
    FROM public.pos_orders po
    LEFT JOIN public.locations l ON l.id = po.location_id
    WHERE po.organization_id = v_org
      AND po.order_date::DATE BETWEEN v_start AND v_end
    GROUP BY 1
  ), inventory_rollup AS (
    SELECT
      CASE p_dimension
        WHEN 'date' THEN to_char(date_trunc('day', im.created_at), 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', im.created_at), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', im.created_at), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Unassigned')
      END AS dimension,
      SUM(CASE WHEN im.movement_type IN ('wastage', 'spoilage') THEN ABS(im.quantity) * COALESCE(i.unit_cost, 0) ELSE 0 END)::NUMERIC AS inventory_waste,
      SUM(CASE WHEN im.quantity < 0 THEN ABS(im.quantity) * COALESCE(i.unit_cost, 0) ELSE 0 END)::NUMERIC AS cogs
    FROM public.inventory_movements im
    LEFT JOIN public.inventory i ON i.id = im.inventory_id
    LEFT JOIN public.locations l ON l.id = im.location_id
    WHERE im.organization_id = v_org
      AND im.created_at::DATE BETWEEN v_start AND v_end
    GROUP BY 1
  ), labor_rollup AS (
    SELECT
      CASE p_dimension
        WHEN 'date' THEN to_char(date_trunc('day', es.shift_start), 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', es.shift_start), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', es.shift_start), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Unassigned')
      END AS dimension,
      SUM(COALESCE(es.labor_cost, 0))::NUMERIC AS labor_cost
    FROM public.employee_shifts es
    LEFT JOIN public.locations l ON l.id = es.location_id
    WHERE es.organization_id = v_org
      AND es.shift_start::DATE BETWEEN v_start AND v_end
    GROUP BY 1
  ), merged AS (
    SELECT dimension FROM pos_rollup
    UNION SELECT dimension FROM inventory_rollup
    UNION SELECT dimension FROM labor_rollup
  )
  SELECT COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'dimension', m.dimension,
    'sales_revenue', CASE WHEN 'sales_revenue' = ANY(p_metrics) THEN COALESCE(p.sales_revenue, 0) END,
    'pos_transaction_count', CASE WHEN 'pos_transaction_count' = ANY(p_metrics) THEN COALESCE(p.pos_transaction_count, 0) END,
    'cogs', CASE WHEN 'cogs' = ANY(p_metrics) THEN COALESCE(i.cogs, 0) END,
    'inventory_waste', CASE WHEN 'inventory_waste' = ANY(p_metrics) THEN COALESCE(i.inventory_waste, 0) END,
    'labor_cost', CASE WHEN 'labor_cost' = ANY(p_metrics) THEN COALESCE(l.labor_cost, 0) END
  )) ORDER BY m.dimension), '[]'::JSONB)
  INTO v_result
  FROM merged m
  LEFT JOIN pos_rollup p USING (dimension)
  LEFT JOIN inventory_rollup i USING (dimension)
  LEFT JOIN labor_rollup l USING (dimension);

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.run_custom_report(TEXT[], TEXT, DATE, DATE) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.run_custom_report(TEXT[], TEXT, DATE, DATE) TO authenticated;

COMMIT;

-- ==========================================================================
-- Source: 20260721000020_invoice_module_production_hardening.sql
-- ==========================================================================

-- 20260721000020: Invoice module production hardening
--
-- Closes the high-risk invoice checklist gaps that can be enforced locally:
-- public invoice storage reads, approval/AP-state drift, post-approval financial edits,
-- self-approval, duplicate manual payment recording, and the discoverable reconciliation RPC.

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. Storage: make the final migration state explicit for invoice documents.
-- ---------------------------------------------------------------------------

UPDATE storage.buckets
   SET public = false,
       file_size_limit = COALESCE(file_size_limit, 52428800),
       allowed_mime_types = COALESCE(
         allowed_mime_types,
         ARRAY['application/pdf', 'image/jpeg', 'image/png', 'image/webp']::text[]
       )
 WHERE id = 'invoices';

DROP POLICY IF EXISTS "Public Access to View Invoices" ON storage.objects;
DROP POLICY IF EXISTS "Tenant Isolation Invoices View" ON storage.objects;
DROP POLICY IF EXISTS "Tenant Isolation Invoices Insert" ON storage.objects;
DROP POLICY IF EXISTS "Tenant Isolation Invoices Delete" ON storage.objects;
DROP POLICY IF EXISTS "Authenticated users can view invoices" ON storage.objects;
DROP POLICY IF EXISTS "Authenticated users can upload invoices" ON storage.objects;
DROP POLICY IF EXISTS "Authenticated users can delete invoices" ON storage.objects;
DROP POLICY IF EXISTS "invoices_bucket_authenticated_access" ON storage.objects;
DROP POLICY IF EXISTS "invoices_bucket_org_read" ON storage.objects;
DROP POLICY IF EXISTS "invoices_bucket_org_insert" ON storage.objects;
DROP POLICY IF EXISTS "invoices_bucket_org_delete" ON storage.objects;
DROP POLICY IF EXISTS "invoices_bucket_service_role" ON storage.objects;

CREATE POLICY "invoices_bucket_org_read"
ON storage.objects
FOR SELECT
TO authenticated
USING (
  bucket_id = 'invoices'
  AND auth.uid() IS NOT NULL
  AND (storage.foldername(name))[1] = public.get_auth_org()::text
);

CREATE POLICY "invoices_bucket_org_insert"
ON storage.objects
FOR INSERT
TO authenticated
WITH CHECK (
  bucket_id = 'invoices'
  AND auth.uid() IS NOT NULL
  AND (storage.foldername(name))[1] = public.get_auth_org()::text
);

CREATE POLICY "invoices_bucket_org_delete"
ON storage.objects
FOR DELETE
TO authenticated
USING (
  bucket_id = 'invoices'
  AND auth.uid() IS NOT NULL
  AND (storage.foldername(name))[1] = public.get_auth_org()::text
);

CREATE POLICY "invoices_bucket_service_role"
ON storage.objects
FOR ALL
TO service_role
USING (bucket_id = 'invoices')
WITH CHECK (bucket_id = 'invoices');

CREATE OR REPLACE FUNCTION public.assert_financial_actor(
  p_organization_id UUID,
  p_allowed_roles TEXT[] DEFAULT ARRAY[
    'location_manager',
    'branch_manager',
    'brand_manager',
    'org_manager',
    'tenant_super_admin',
    'platform_admin',
    'org_owner',
    'owner',
    'admin'
  ]
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  v_role TEXT;
  v_profile_org UUID;
  v_profile_tenant UUID;
  v_org_tenant UUID;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT role, organization_id, tenant_id
    INTO v_role, v_profile_org, v_profile_tenant
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    SELECT tenant_id INTO v_org_tenant
    FROM public.organizations
    WHERE id = p_organization_id;

    IF v_profile_tenant IS DISTINCT FROM v_org_tenant THEN
      RAISE EXCEPTION 'Cross-tenant financial access denied';
    END IF;
  ELSIF v_role <> 'platform_admin' AND v_profile_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization financial access denied';
  END IF;

  IF NOT v_role = ANY(p_allowed_roles) THEN
    RAISE EXCEPTION 'Insufficient financial permissions';
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.assert_financial_actor(UUID, TEXT[]) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.assert_financial_actor(UUID, TEXT[]) TO service_role;

-- ---------------------------------------------------------------------------
-- 2. Status consistency and historical anomaly visibility.
-- ---------------------------------------------------------------------------

DROP VIEW IF EXISTS public.invoice_production_anomalies;
CREATE VIEW public.invoice_production_anomalies AS
SELECT
  id,
  organization_id,
  brand_id,
  location_id,
  tenant_id,
  invoice_number,
  vendor_name,
  status,
  ap_status,
  payment_status,
  paid_amount,
  total_amount,
  CASE
    WHEN status = 'rejected'
      AND COALESCE(payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay', 'processing')
      THEN 'rejected_invoice_has_payment_state'
    WHEN status = 'rejected'
      AND COALESCE(paid_amount, 0) > 0
      THEN 'rejected_invoice_has_paid_amount'
    WHEN status = 'approved' AND ap_status IS DISTINCT FROM 'approved'
      THEN 'approved_status_ap_status_desync'
    WHEN status = 'scheduled' AND ap_status IS DISTINCT FROM 'scheduled'
      THEN 'scheduled_status_ap_status_desync'
    WHEN status = 'paid' AND (ap_status IS DISTINCT FROM 'paid' OR payment_status IS DISTINCT FROM 'paid')
      THEN 'paid_status_desync'
    WHEN status = 'rejected' AND ap_status IS DISTINCT FROM 'rejected'
      THEN 'rejected_status_ap_status_desync'
  END AS anomaly_type,
  updated_at
FROM public.invoices
WHERE deleted_at IS NULL
  AND (
    (status = 'rejected' AND COALESCE(payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay', 'processing'))
    OR (status = 'rejected' AND COALESCE(paid_amount, 0) > 0)
    OR (status = 'approved' AND ap_status IS DISTINCT FROM 'approved')
    OR (status = 'scheduled' AND ap_status IS DISTINCT FROM 'scheduled')
    OR (status = 'paid' AND (ap_status IS DISTINCT FROM 'paid' OR payment_status IS DISTINCT FROM 'paid'))
    OR (status = 'rejected' AND ap_status IS DISTINCT FROM 'rejected')
  );

REVOKE ALL ON public.invoice_production_anomalies FROM PUBLIC, anon;
GRANT SELECT ON public.invoice_production_anomalies TO authenticated, service_role;

ALTER TABLE public.invoices DROP CONSTRAINT IF EXISTS invoices_no_rejected_paid_state;
ALTER TABLE public.invoices
  ADD CONSTRAINT invoices_no_rejected_paid_state CHECK (
    status <> 'rejected'
    OR (
      COALESCE(payment_status, 'unpaid') NOT IN ('partial', 'paid', 'auto_pay', 'processing')
      AND COALESCE(paid_amount, 0) = 0
    )
  ) NOT VALID;

CREATE OR REPLACE FUNCTION public.normalize_invoice_ap_state()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.status = 'approved' THEN
    NEW.ap_status := 'approved';
  ELSIF NEW.status = 'scheduled' THEN
    NEW.ap_status := 'scheduled';
  ELSIF NEW.status = 'paid' THEN
    NEW.ap_status := 'paid';
    NEW.payment_status := 'paid';
  ELSIF NEW.status = 'rejected' THEN
    IF COALESCE(NEW.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay', 'processing')
      OR COALESCE(NEW.paid_amount, 0) > 0 THEN
      RAISE EXCEPTION 'Rejected invoices cannot carry paid or in-flight payment state';
    END IF;
    NEW.ap_status := 'rejected';
  END IF;

  IF NEW.payment_status = 'paid' THEN
    NEW.status := 'paid';
    NEW.ap_status := 'paid';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS normalize_invoice_ap_state ON public.invoices;
CREATE TRIGGER normalize_invoice_ap_state
  BEFORE INSERT OR UPDATE OF status, ap_status, payment_status, paid_amount
  ON public.invoices
  FOR EACH ROW
  EXECUTE FUNCTION public.normalize_invoice_ap_state();

-- ---------------------------------------------------------------------------
-- 3. Approval controls: no self-approval, autopay bar retained.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.enforce_invoice_approval_authorization()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_vendor_autopay boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'approved' OR NEW.ap_status = 'approved' THEN
      IF NEW.created_by IS NOT NULL AND NEW.created_by = auth.uid() THEN
        RAISE EXCEPTION 'Invoice submitters cannot approve their own invoices';
      END IF;

      PERFORM public.assert_can_approve_invoice_scope(
        NEW.organization_id,
        NEW.brand_id,
        NEW.location_id
      );

      SELECT autopay_enabled INTO v_vendor_autopay FROM public.vendors WHERE id = NEW.vendor_id;
      IF v_vendor_autopay AND NOT public.is_owner_or_admin() THEN
        RAISE EXCEPTION 'AutoPay invoice approval requires an org manager, tenant super admin, or platform admin';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF (NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved')
    OR (NEW.ap_status = 'approved' AND OLD.ap_status IS DISTINCT FROM 'approved') THEN
    IF COALESCE(OLD.created_by, NEW.created_by) IS NOT NULL
      AND COALESCE(OLD.created_by, NEW.created_by) = auth.uid() THEN
      RAISE EXCEPTION 'Invoice submitters cannot approve their own invoices';
    END IF;

    PERFORM public.assert_can_approve_invoice_scope(
      NEW.organization_id,
      NEW.brand_id,
      NEW.location_id
    );

    SELECT autopay_enabled INTO v_vendor_autopay FROM public.vendors WHERE id = NEW.vendor_id;
    IF v_vendor_autopay AND NOT public.is_owner_or_admin() THEN
      RAISE EXCEPTION 'AutoPay invoice approval requires an org manager, tenant super admin, or platform admin';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS enforce_invoice_approval_authorization ON public.invoices;
CREATE TRIGGER enforce_invoice_approval_authorization
BEFORE INSERT OR UPDATE OF status, ap_status
ON public.invoices
FOR EACH ROW
EXECUTE FUNCTION public.enforce_invoice_approval_authorization();

-- ---------------------------------------------------------------------------
-- 4. Financial immutability after approval/payment.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.guard_locked_invoice_financial_fields()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF OLD.status IN ('approved', 'scheduled', 'partially_paid', 'paid')
    OR OLD.ap_status IN ('approved', 'scheduled', 'paid', 'closed')
    OR COALESCE(OLD.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay')
    OR COALESCE(OLD.paid_amount, 0) > 0 THEN
    IF NEW.organization_id IS DISTINCT FROM OLD.organization_id
      OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
      OR NEW.brand_id IS DISTINCT FROM OLD.brand_id
      OR NEW.location_id IS DISTINCT FROM OLD.location_id
      OR NEW.vendor_id IS DISTINCT FROM OLD.vendor_id
      OR NEW.vendor_name IS DISTINCT FROM OLD.vendor_name
      OR NEW.invoice_number IS DISTINCT FROM OLD.invoice_number
      OR NEW.invoice_date IS DISTINCT FROM OLD.invoice_date
      OR NEW.due_date IS DISTINCT FROM OLD.due_date
      OR NEW.total_amount IS DISTINCT FROM OLD.total_amount
      OR NEW.subtotal IS DISTINCT FROM OLD.subtotal
      OR NEW.tax_amount IS DISTINCT FROM OLD.tax_amount
      OR NEW.delivery_fee IS DISTINCT FROM OLD.delivery_fee
      OR NEW.fuel_surcharge IS DISTINCT FROM OLD.fuel_surcharge
      OR NEW.other_charges IS DISTINCT FROM OLD.other_charges
      OR NEW.currency IS DISTINCT FROM OLD.currency
      OR NEW.account_number IS DISTINCT FROM OLD.account_number
      OR NEW.purchase_order_id IS DISTINCT FROM OLD.purchase_order_id
      OR NEW.line_items IS DISTINCT FROM OLD.line_items THEN
      RAISE EXCEPTION 'Approved, scheduled, partially paid, or paid invoice financial fields are immutable';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS guard_locked_invoice_financial_fields ON public.invoices;
CREATE TRIGGER guard_locked_invoice_financial_fields
  BEFORE UPDATE ON public.invoices
  FOR EACH ROW
  EXECUTE FUNCTION public.guard_locked_invoice_financial_fields();

CREATE OR REPLACE FUNCTION public.guard_locked_invoice_line_items()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_invoice record;
  v_invoice_id uuid;
BEGIN
  v_invoice_id := COALESCE(NEW.invoice_id, OLD.invoice_id);

  SELECT status, ap_status, payment_status, paid_amount
    INTO v_invoice
  FROM public.invoices
  WHERE id = v_invoice_id;

  IF v_invoice.status IN ('approved', 'scheduled', 'partially_paid', 'paid')
    OR v_invoice.ap_status IN ('approved', 'scheduled', 'paid', 'closed')
    OR COALESCE(v_invoice.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay')
    OR COALESCE(v_invoice.paid_amount, 0) > 0 THEN
    RAISE EXCEPTION 'Invoice line items are immutable after approval or payment activity';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;

DROP TRIGGER IF EXISTS guard_locked_invoice_line_items ON public.invoice_line_items;
CREATE TRIGGER guard_locked_invoice_line_items
  BEFORE INSERT OR UPDATE OR DELETE ON public.invoice_line_items
  FOR EACH ROW
  EXECUTE FUNCTION public.guard_locked_invoice_line_items();

-- ---------------------------------------------------------------------------
-- 5. Payment idempotency and status guards.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.guard_payment_reference_uniqueness()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.invoice_id IS NOT NULL
    AND NULLIF(trim(COALESCE(NEW.transaction_id, '')), '') IS NOT NULL
    AND COALESCE(NEW.status, 'pending') NOT IN ('failed', 'cancelled', 'refunded')
    AND EXISTS (
      SELECT 1
      FROM public.payments p
      WHERE p.invoice_id = NEW.invoice_id
        AND p.id IS DISTINCT FROM NEW.id
        AND p.transaction_id = NEW.transaction_id
        AND COALESCE(p.status, 'pending') NOT IN ('failed', 'cancelled', 'refunded')
    ) THEN
    RAISE EXCEPTION 'A non-reversed payment with reference % already exists for this invoice', NEW.transaction_id;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS guard_payment_reference_uniqueness ON public.payments;
CREATE TRIGGER guard_payment_reference_uniqueness
  BEFORE INSERT OR UPDATE OF invoice_id, transaction_id, status
  ON public.payments
  FOR EACH ROW
  EXECUTE FUNCTION public.guard_payment_reference_uniqueness();

CREATE OR REPLACE FUNCTION public.record_invoice_payment(
  p_invoice_id UUID,
  p_amount NUMERIC,
  p_reference TEXT,
  p_payment_method TEXT DEFAULT 'manual'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_existing_payment_id UUID;
  v_remaining NUMERIC;
  v_new_paid_amount NUMERIC;
  v_new_status TEXT;
  v_payment_id UUID;
BEGIN
  IF COALESCE(p_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'Payment amount must be greater than zero';
  END IF;

  IF NULLIF(trim(COALESCE(p_reference, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Payment reference is required';
  END IF;

  SELECT * INTO v_invoice
    FROM public.invoices
   WHERE id = p_invoice_id
   FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_financial_actor(v_invoice.organization_id);

  IF COALESCE(v_invoice.ap_routing_destination, 'payments') <> 'payments' THEN
    RAISE EXCEPTION 'Invoice is routed to %, not Payments', v_invoice.ap_routing_destination;
  END IF;

  IF v_invoice.status = 'rejected' OR v_invoice.ap_status = 'rejected' THEN
    RAISE EXCEPTION 'Rejected invoices cannot receive payments';
  END IF;

  SELECT id
    INTO v_existing_payment_id
  FROM public.payments
  WHERE invoice_id = p_invoice_id
    AND transaction_id = p_reference
    AND COALESCE(status, 'pending') NOT IN ('failed', 'cancelled', 'refunded')
  LIMIT 1;

  IF v_existing_payment_id IS NOT NULL THEN
    RAISE EXCEPTION 'Payment reference % has already been recorded for this invoice', p_reference;
  END IF;

  IF COALESCE(v_invoice.payment_status, 'unpaid') IN ('paid', 'auto_pay') OR v_invoice.status = 'paid' THEN
    RAISE EXCEPTION 'Paid invoices cannot receive another payment';
  END IF;

  IF v_invoice.status NOT IN ('approved', 'scheduled', 'partially_paid') THEN
    RAISE EXCEPTION 'Invoice must be approved before recording payment';
  END IF;

  v_remaining := GREATEST(0, COALESCE(v_invoice.total_amount, 0) - COALESCE(v_invoice.paid_amount, 0));
  IF p_amount > v_remaining THEN
    RAISE EXCEPTION 'Payment amount % exceeds remaining balance %', p_amount, v_remaining;
  END IF;

  v_new_paid_amount := COALESCE(v_invoice.paid_amount, 0) + p_amount;
  v_new_status := CASE
    WHEN v_new_paid_amount >= COALESCE(v_invoice.total_amount, 0) THEN 'paid'
    ELSE 'partially_paid'
  END;

  UPDATE public.invoices
     SET paid_amount = v_new_paid_amount,
         payment_status = CASE WHEN v_new_status = 'paid' THEN 'paid' ELSE 'partial' END,
         status = v_new_status,
         ap_status = CASE WHEN v_new_status = 'paid' THEN 'paid' ELSE ap_status END,
         payment_reference = p_reference,
         updated_at = now()
   WHERE id = p_invoice_id;

  INSERT INTO public.payments (
    invoice_id,
    vendor_id,
    vendor_name,
    invoice_number,
    amount,
    payment_method,
    status,
    transaction_id,
    payment_date,
    payment_account_id,
    organization_id,
    brand_id,
    location_id,
    created_by
  ) VALUES (
    v_invoice.id,
    v_invoice.vendor_id,
    v_invoice.vendor_name,
    v_invoice.invoice_number,
    p_amount,
    p_payment_method,
    'completed',
    p_reference,
    CURRENT_DATE,
    v_invoice.payment_account_id,
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id,
    auth.uid()
  )
  RETURNING id INTO v_payment_id;

  PERFORM public.log_invoice_audit_event(
    v_invoice.id,
    'payment_recorded',
    'Payment recorded through tenant-safe financial RPC',
    to_jsonb(v_invoice),
    jsonb_build_object(
      'payment_id', v_payment_id,
      'amount', p_amount,
      'payment_method', p_payment_method,
      'reference', p_reference,
      'status', v_new_status
    )
  );

  RETURN jsonb_build_object(
    'status', v_new_status,
    'paid_amount', v_new_paid_amount,
    'payment_id', v_payment_id
  );
END;
$$;

REVOKE ALL ON FUNCTION public.record_invoice_payment(uuid, numeric, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.record_invoice_payment(uuid, numeric, text, text) TO authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 6. Make the public reconciliation RPC surface the real PO-level match result.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.reconcile_invoice_lines(p_invoice_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
  v_po_id UUID;
  v_line RECORD;
  v_match JSONB;
  v_status TEXT;
  v_reconciled_count INTEGER := 0;
  v_variance_count INTEGER := 0;
BEGIN
  SELECT organization_id, purchase_order_id
    INTO v_org_id, v_po_id
  FROM public.invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  DELETE FROM public.invoice_line_matches
  WHERE invoice_line_id IN (
    SELECT id FROM public.invoice_line_items WHERE invoice_id = p_invoice_id
  );

  DELETE FROM public.reconciliation_variances
  WHERE invoice_id = p_invoice_id;

  IF v_po_id IS NOT NULL THEN
    v_match := public.get_three_way_match_status(v_po_id);
    v_status := COALESCE(v_match->>'match_status', 'unmatched');
  ELSE
    v_match := jsonb_build_object('match_status', 'missing_po');
    v_status := 'missing_po';
  END IF;

  FOR v_line IN SELECT * FROM public.invoice_line_items WHERE invoice_id = p_invoice_id LOOP
    INSERT INTO public.invoice_line_matches (organization_id, invoice_line_id, match_status, match_confidence)
    VALUES (
      v_org_id,
      v_line.id,
      CASE WHEN v_status = 'matched' THEN 'exact' ELSE 'variance' END,
      CASE WHEN v_status = 'matched' THEN 1.0 ELSE 0.5 END
    );

    v_reconciled_count := v_reconciled_count + 1;

    IF v_status = 'missing_po' THEN
      INSERT INTO public.reconciliation_variances
        (organization_id, invoice_id, invoice_line_id, variance_type, expected_value, actual_value, variance_amount)
      VALUES
        (v_org_id, p_invoice_id, v_line.id, 'missing_po', 0, COALESCE(v_line.total_price, 0), COALESCE(v_line.total_price, 0));
      v_variance_count := v_variance_count + 1;
    END IF;

    IF v_status IN ('price_variance', 'critical_variance') THEN
      INSERT INTO public.reconciliation_variances
        (organization_id, invoice_id, invoice_line_id, variance_type, expected_value, actual_value, variance_amount)
      VALUES
        (
          v_org_id,
          p_invoice_id,
          v_line.id,
          'price',
          NULL,
          COALESCE(v_line.total_price, 0),
          COALESCE((v_match->>'variance_amount')::numeric, 0)
        );
      v_variance_count := v_variance_count + 1;
    END IF;

    IF v_status IN ('quantity_variance', 'critical_variance') THEN
      INSERT INTO public.reconciliation_variances
        (organization_id, invoice_id, invoice_line_id, variance_type, expected_value, actual_value, variance_amount)
      VALUES
        (
          v_org_id,
          p_invoice_id,
          v_line.id,
          'quantity',
          COALESCE((v_match->>'po_quantity')::numeric, 0),
          COALESCE((v_match->>'received_quantity')::numeric, 0),
          ABS(COALESCE((v_match->>'po_quantity')::numeric, 0) - COALESCE((v_match->>'received_quantity')::numeric, 0))
        );
      v_variance_count := v_variance_count + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'reconciled_lines', v_reconciled_count,
    'variance_count', v_variance_count,
    'match_status', v_status,
    'match', v_match
  );
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260721000021_invoice_anomaly_review_workflow.sql
-- ==========================================================================

-- 20260721000021: Invoice anomaly review workflow
--
-- Adds an auditable user reaction path for historical invoice anomalies surfaced by
-- invoice_production_anomalies. Decisions are recorded instead of silently rewriting money data.

BEGIN;

CREATE TABLE IF NOT EXISTS public.invoice_anomaly_reviews (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id uuid NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  brand_id uuid REFERENCES public.brands(brand_id) ON DELETE SET NULL,
  location_id uuid REFERENCES public.locations(id) ON DELETE SET NULL,
  anomaly_type text NOT NULL,
  decision text NOT NULL CHECK (decision IN ('opened_for_review', 'accepted_historical', 'finance_cleanup_requested')),
  notes text,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.invoice_anomaly_reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoice_anomaly_reviews FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS invoice_anomaly_reviews_select ON public.invoice_anomaly_reviews;
CREATE POLICY invoice_anomaly_reviews_select
ON public.invoice_anomaly_reviews
FOR SELECT
USING (
  public.financial_scope_visible(organization_id, brand_id, location_id, NULL)
);

DROP POLICY IF EXISTS invoice_anomaly_reviews_insert ON public.invoice_anomaly_reviews;
CREATE POLICY invoice_anomaly_reviews_insert
ON public.invoice_anomaly_reviews
FOR INSERT
WITH CHECK (
  public.financial_scope_writable(organization_id, brand_id, location_id, NULL, false)
);

CREATE INDEX IF NOT EXISTS idx_invoice_anomaly_reviews_invoice_created
  ON public.invoice_anomaly_reviews(invoice_id, created_at DESC);

CREATE OR REPLACE FUNCTION public.record_invoice_anomaly_review(
  p_invoice_id uuid,
  p_anomaly_type text,
  p_decision text,
  p_notes text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_invoice public.invoices%ROWTYPE;
  v_review_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_decision NOT IN ('opened_for_review', 'accepted_historical', 'finance_cleanup_requested') THEN
    RAISE EXCEPTION 'Unsupported invoice anomaly decision %', p_decision;
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_financial_actor(v_invoice.organization_id);

  INSERT INTO public.invoice_anomaly_reviews (
    invoice_id,
    organization_id,
    brand_id,
    location_id,
    anomaly_type,
    decision,
    notes,
    created_by
  ) VALUES (
    v_invoice.id,
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id,
    COALESCE(NULLIF(p_anomaly_type, ''), 'unknown'),
    p_decision,
    p_notes,
    auth.uid()
  )
  RETURNING id INTO v_review_id;

  UPDATE public.invoices
     SET validation_results = COALESCE(validation_results, '{}'::jsonb)
       || jsonb_build_object(
            'invoice_anomaly_review',
            jsonb_build_object(
              'decision', p_decision,
              'anomaly_type', COALESCE(NULLIF(p_anomaly_type, ''), 'unknown'),
              'reviewed_by', auth.uid(),
              'reviewed_at', now(),
              'notes', p_notes
            )
          ),
         updated_at = now()
   WHERE id = v_invoice.id;

  RETURN jsonb_build_object(
    'success', true,
    'review_id', v_review_id,
    'decision', p_decision
  );
END;
$$;

REVOKE ALL ON FUNCTION public.record_invoice_anomaly_review(uuid, text, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.record_invoice_anomaly_review(uuid, text, text, text) TO authenticated, service_role;

DROP VIEW IF EXISTS public.invoice_production_anomalies;
CREATE VIEW public.invoice_production_anomalies AS
SELECT
  i.id,
  i.organization_id,
  i.brand_id,
  i.location_id,
  i.tenant_id,
  i.invoice_number,
  i.vendor_name,
  i.status,
  i.ap_status,
  i.payment_status,
  i.paid_amount,
  i.total_amount,
  CASE
    WHEN i.status = 'rejected'
      AND COALESCE(i.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay', 'processing')
      THEN 'rejected_invoice_has_payment_state'
    WHEN i.status = 'rejected'
      AND COALESCE(i.paid_amount, 0) > 0
      THEN 'rejected_invoice_has_paid_amount'
    WHEN i.status = 'approved' AND i.ap_status IS DISTINCT FROM 'approved'
      THEN 'approved_status_ap_status_desync'
    WHEN i.status = 'scheduled' AND i.ap_status IS DISTINCT FROM 'scheduled'
      THEN 'scheduled_status_ap_status_desync'
    WHEN i.status = 'paid' AND (i.ap_status IS DISTINCT FROM 'paid' OR i.payment_status IS DISTINCT FROM 'paid')
      THEN 'paid_status_desync'
    WHEN i.status = 'rejected' AND i.ap_status IS DISTINCT FROM 'rejected'
      THEN 'rejected_status_ap_status_desync'
  END AS anomaly_type,
  latest_review.decision AS latest_review_decision,
  latest_review.created_at AS latest_reviewed_at,
  i.updated_at
FROM public.invoices i
LEFT JOIN LATERAL (
  SELECT r.decision, r.created_at
  FROM public.invoice_anomaly_reviews r
  WHERE r.invoice_id = i.id
    AND r.anomaly_type = CASE
      WHEN i.status = 'rejected'
        AND COALESCE(i.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay', 'processing')
        THEN 'rejected_invoice_has_payment_state'
      WHEN i.status = 'rejected'
        AND COALESCE(i.paid_amount, 0) > 0
        THEN 'rejected_invoice_has_paid_amount'
      WHEN i.status = 'approved' AND i.ap_status IS DISTINCT FROM 'approved'
        THEN 'approved_status_ap_status_desync'
      WHEN i.status = 'scheduled' AND i.ap_status IS DISTINCT FROM 'scheduled'
        THEN 'scheduled_status_ap_status_desync'
      WHEN i.status = 'paid' AND (i.ap_status IS DISTINCT FROM 'paid' OR i.payment_status IS DISTINCT FROM 'paid')
        THEN 'paid_status_desync'
      WHEN i.status = 'rejected' AND i.ap_status IS DISTINCT FROM 'rejected'
        THEN 'rejected_status_ap_status_desync'
    END
  ORDER BY r.created_at DESC
  LIMIT 1
) latest_review ON true
WHERE i.deleted_at IS NULL
  AND (
    (i.status = 'rejected' AND COALESCE(i.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay', 'processing'))
    OR (i.status = 'rejected' AND COALESCE(i.paid_amount, 0) > 0)
    OR (i.status = 'approved' AND i.ap_status IS DISTINCT FROM 'approved')
    OR (i.status = 'scheduled' AND i.ap_status IS DISTINCT FROM 'scheduled')
    OR (i.status = 'paid' AND (i.ap_status IS DISTINCT FROM 'paid' OR i.payment_status IS DISTINCT FROM 'paid'))
    OR (i.status = 'rejected' AND i.ap_status IS DISTINCT FROM 'rejected')
  )
  AND COALESCE(latest_review.decision, '') NOT IN ('accepted_historical', 'finance_cleanup_requested');

REVOKE ALL ON public.invoice_production_anomalies FROM PUBLIC, anon;
GRANT SELECT ON public.invoice_production_anomalies TO authenticated, service_role;

COMMIT;

-- ==========================================================================
-- Source: 20260721000022_remote_lint_cleanup.sql
-- ==========================================================================

-- Clean up remaining DB lint blockers that are not part of runtime invoice behavior.

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;

-- pgTAP helper functions are test-only and should not live in the public runtime schema.
-- Keeping them there causes schema lint failures on modern Postgres catalogs.
DROP EXTENSION IF EXISTS pgtap CASCADE;

CREATE OR REPLACE FUNCTION public.log_frontend_event(
    p_event_name TEXT,
    p_entity_type TEXT,
    p_entity_id UUID,
    p_payload JSONB
) RETURNS UUID AS $$
DECLARE
    v_org_id UUID;
    v_role TEXT;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    v_org_id := public.get_my_org();
    v_role := public.get_auth_role();

    IF v_org_id IS NULL AND v_role <> 'platform_admin' THEN
        RAISE EXCEPTION 'Cannot emit event without organization context';
    END IF;

    RETURN public.emit_domain_event(p_event_name, p_entity_type, p_entity_id, v_org_id, p_payload);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

CREATE OR REPLACE FUNCTION public.reissue_owner_invitation(p_invitation_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_old public.invitations%ROWTYPE;
  v_new public.invitations%ROWTYPE;
  v_token TEXT := encode(gen_random_bytes(32), 'hex');
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  SELECT * INTO v_old FROM public.invitations WHERE id = p_invitation_id;
  IF v_old.id IS NULL THEN
    RAISE EXCEPTION 'Invitation not found';
  END IF;

  UPDATE public.invitations SET closed_at = now() WHERE id = p_invitation_id;

  INSERT INTO public.invitations (
    tenant_id, organization_id, email, role, token, invited_by, expires_at, metadata, status
  )
  VALUES (
    v_old.tenant_id,
    v_old.organization_id,
    v_old.email,
    v_old.role,
    v_token,
    auth.uid(),
    now() + interval '7 days',
    COALESCE(v_old.metadata, '{}'::jsonb) || jsonb_build_object('reissued_from', v_old.id),
    COALESCE(v_old.status, 'pending')
  )
  RETURNING * INTO v_new;

  RETURN jsonb_build_object('success', true, 'invitation_id', v_new.id, 'token', v_new.token, 'expires_at', v_new.expires_at);
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260721000023_db_lint_warning_cleanup.sql
-- ==========================================================================

-- Resolve remaining plpgsql_check warnings after the runtime lint cleanup.

BEGIN;

ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS report_unit_quantity numeric DEFAULT 1,
  ADD COLUMN IF NOT EXISTS report_unit_source_price numeric;

UPDATE public.products
   SET report_unit_quantity = COALESCE(NULLIF(report_unit_quantity, 0), 1),
       report_unit_source_price = COALESCE(report_unit_source_price, latest_price, 0)
 WHERE report_unit_quantity IS NULL
    OR report_unit_quantity = 0
    OR report_unit_source_price IS NULL;
CREATE OR REPLACE FUNCTION public.derive_product_category_type(
  p_accounting_category text,
  p_category text DEFAULT NULL,
  p_name text DEFAULT NULL
)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE
    WHEN lower(COALESCE(p_accounting_category, '')) LIKE '52%'
      OR lower(COALESCE(p_accounting_category, '')) LIKE '%beverage%'
      OR lower(COALESCE(p_category, '')) IN ('beer', 'wine', 'liquor', 'beverage', 'beverages')
      OR lower(COALESCE(p_name, '')) ~ '(beer|wine|liquor|vodka|gin|rum|tequila|whiskey|syrup, fontn|soda)'
      THEN 'Beverage'
    WHEN lower(COALESCE(p_accounting_category, '')) LIKE '51%'
      OR lower(COALESCE(p_accounting_category, '')) LIKE '%food%'
      OR lower(COALESCE(p_accounting_category, '')) IN ('food', 'food_cogs', '5100')
      THEN 'Food'
    ELSE 'Other'
  END;
$$;

CREATE OR REPLACE FUNCTION public.derive_product_category(p_category text, p_name text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE
    WHEN NULLIF(trim(COALESCE(p_category, '')), '') IS NOT NULL
      AND lower(trim(p_category)) <> 'uncategorized'
      THEN trim(p_category)
    WHEN lower(COALESCE(p_name, '')) ~ '(lettuce|tomato|potato|onion|pepper|celery|carrot|cucumber|lemon|okra|coleslaw|produce)'
      THEN 'Produce'
    WHEN lower(COALESCE(p_name, '')) ~ '(cheese|milk|cream|butter|buttermilk|dairy)'
      THEN 'Dairy'
    WHEN lower(COALESCE(p_name, '')) ~ '(chicken|wing|breast|tender|poultry)'
      THEN 'Poultry'
    WHEN lower(COALESCE(p_name, '')) ~ '(beef|bacon|pork|meat|patty)'
      THEN 'Meat'
    WHEN lower(COALESCE(p_name, '')) ~ '(beer|ale|lager)'
      THEN 'Beer'
    WHEN lower(COALESCE(p_name, '')) ~ '(wine|pinot|cabernet|chardonnay)'
      THEN 'Wine'
    WHEN lower(COALESCE(p_name, '')) ~ '(vodka|gin|rum|tequila|whiskey|liquor)'
      THEN 'Liquor'
    WHEN lower(COALESCE(p_name, '')) ~ '(container|towel|scrubber|glove|kit, ctly|napkin|paper|bleach)'
      THEN 'Restaurant Supplies'
    WHEN lower(COALESCE(p_name, '')) ~ '(flour|bread|roll|macaroni|ketchup|mayonnaise|sauce|shortening|tortilla|breade?r|syrup)'
      THEN 'Grocery and Dry Goods'
    ELSE 'Uncategorized'
  END;
$$;

CREATE OR REPLACE FUNCTION public.generate_restops_product_id()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_next bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('public.products.product_id'));

  SELECT COALESCE(MAX(((regexp_match(product_id, '^PRD-([0-9]+)$'))[1])::bigint), 0) + 1
    INTO v_next
  FROM public.products
  WHERE product_id ~ '^PRD-[0-9]+$';

  RETURN 'PRD-' || lpad(v_next::text, 6, '0');
END;
$$;
CREATE OR REPLACE FUNCTION public.product_unit_is_generic(p_unit text)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT NULLIF(trim(COALESCE(p_unit, '')), '') IS NULL
    OR lower(trim(p_unit)) IN ('ea', 'each', 'other', 'unit', 'units');
$$;

CREATE OR REPLACE FUNCTION public.format_product_unit_quantity(p_quantity numeric)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT regexp_replace(regexp_replace(COALESCE(p_quantity, 0)::text, '0+$', ''), '\.$', '');
$$;

CREATE OR REPLACE FUNCTION public.normalize_product_unit_label(p_unit text, p_quantity numeric DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_unit text := upper(regexp_replace(trim(COALESCE(p_unit, '')), '[^A-Z]', '', 'g'));
  v_plural boolean := COALESCE(p_quantity, 2) <> 1;
BEGIN
  IF v_unit = '' THEN
    RETURN NULL;
  END IF;

  RETURN CASE
    WHEN v_unit IN ('EA', 'EACH', 'EACHES', 'CT', 'COUNT', 'CN') THEN 'Each'
    WHEN v_unit IN ('CS', 'CASE', 'CASES') THEN 'Case'
    WHEN v_unit IN ('LB', 'LBS', 'POUND', 'POUNDS') THEN CASE WHEN v_plural THEN 'Pounds' ELSE 'Pound' END
    WHEN v_unit IN ('OZ', 'OZS', 'OUNCE', 'OUNCES') THEN CASE WHEN v_plural THEN 'Ounces' ELSE 'Ounce' END
    WHEN v_unit IN ('GA', 'GAL', 'GALS', 'GALLON', 'GALLONS') THEN CASE WHEN v_plural THEN 'Gallons' ELSE 'Gallon' END
    WHEN v_unit IN ('L', 'LT', 'LTR', 'LTRS', 'LITER', 'LITERS', 'LITRE', 'LITRES') THEN CASE WHEN v_plural THEN 'Liters' ELSE 'Liter' END
    WHEN v_unit IN ('ML', 'MLS', 'MILLILITER', 'MILLILITERS') THEN CASE WHEN v_plural THEN 'Milliliters' ELSE 'Milliliter' END
    WHEN v_unit IN ('G', 'GM', 'GRAM', 'GRAMS') THEN CASE WHEN v_plural THEN 'Grams' ELSE 'Gram' END
    WHEN v_unit IN ('KG', 'KGS', 'KILOGRAM', 'KILOGRAMS') THEN CASE WHEN v_plural THEN 'Kilograms' ELSE 'Kilogram' END
    WHEN v_unit IN ('BTL', 'BTLS', 'BOTTLE', 'BOTTLES') THEN CASE WHEN v_plural THEN 'Bottles' ELSE 'Bottle' END
    WHEN v_unit IN ('CAN', 'CANS') THEN CASE WHEN v_plural THEN 'Cans' ELSE 'Can' END
    WHEN v_unit IN ('BAG', 'BAGS') THEN CASE WHEN v_plural THEN 'Bags' ELSE 'Bag' END
    WHEN v_unit IN ('BOX', 'BOXES', 'BX') THEN CASE WHEN v_plural THEN 'Boxes' ELSE 'Box' END
    WHEN v_unit IN ('PK', 'PKG', 'PACK', 'PACKAGE') THEN CASE WHEN v_plural THEN 'Packs' ELSE 'Pack' END
    WHEN v_unit IN ('DOZ', 'DOZEN') THEN 'Dozen'
    WHEN v_unit IN ('FLAT', 'FLATS') THEN CASE WHEN v_plural THEN 'Flats' ELSE 'Flat' END
    WHEN v_unit IN ('CUP', 'CUPS') THEN CASE WHEN v_plural THEN 'Cups' ELSE 'Cup' END
    WHEN v_unit IN ('QT', 'QTS', 'QUART', 'QUARTS') THEN CASE WHEN v_plural THEN 'Quarts' ELSE 'Quart' END
    ELSE initcap(lower(v_unit))
  END;
END;
$$;

CREATE OR REPLACE FUNCTION public.derive_product_report_unit(p_vendor_unit text DEFAULT NULL, p_pack_size text DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_pack text := upper(regexp_replace(trim(COALESCE(p_pack_size, '')), '[^A-Z0-9./ ]', ' ', 'g'));
  v_vendor text := trim(COALESCE(p_vendor_unit, ''));
  v_vendor_label text := public.normalize_product_unit_label(v_vendor);
BEGIN
  IF v_pack = '' AND v_vendor ~ '[0-9]' THEN
    v_pack := upper(regexp_replace(v_vendor, '[^A-Z0-9./ ]', ' ', 'g'));
  END IF;

  IF v_pack <> '' THEN
    RETURN COALESCE(public.normalize_product_unit_label(v_pack), v_pack);
  END IF;

  RETURN COALESCE(v_vendor_label, NULLIF(v_vendor, ''), 'Each');
END;
$$;
CREATE OR REPLACE FUNCTION public.assert_can_approve_vendor_scope(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_role text;
  v_auth_org uuid;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_role := public.get_auth_role();
  v_auth_org := public.get_auth_org();

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    IF public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'Cross-tenant vendor approval denied';
  END IF;

  IF p_organization_id IS NULL OR v_auth_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization vendor approval denied';
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN;
  END IF;

  IF v_role = 'branch_manager'
     AND p_brand_id IS NOT NULL
     AND public.reference_scope_writable(
       p_organization_id,
       p_brand_id,
       p_location_id,
       NULL,
       'branch_manager'
     ) THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'Vendor approval denied for role % outside accessible brand scope', v_role;
END;
$$;

CREATE OR REPLACE FUNCTION public.approve_onboarding_hierarchy(p_user_id uuid, p_note text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_hierarchy JSONB;
  v_result JSONB;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  SELECT hierarchy_payload INTO v_hierarchy
  FROM public.onboarding_hierarchy_submissions
  WHERE user_id = p_user_id AND status = 'pending_review';

  IF v_hierarchy IS NULL THEN
    RAISE EXCEPTION 'No pending hierarchy submission for this tenant';
  END IF;

  v_result := public.setup_onboarding_hierarchy(p_user_id, v_hierarchy);

  UPDATE public.onboarding_hierarchy_submissions
  SET status = 'approved',
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      rejection_reason = NULLIF(btrim(COALESCE(p_note, '')), ''),
      updated_at = now()
  WHERE user_id = p_user_id AND status = 'pending_review';

  UPDATE public.profiles SET hierarchy_review_status = 'approved' WHERE id = p_user_id;

  INSERT INTO public.notifications(user_id, organization_id, type, title, message, is_read)
  SELECT p_user_id, (v_result->>'primary_org_id')::uuid, 'system', 'Workspace approved',
         'Your organization workspace has been approved and created.', false;

  RETURN v_result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.ingest_email_invoice(
  p_recipient_email text,
  p_fallback_organization_id uuid DEFAULT NULL,
  p_invoice jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_recipient_email text;
  v_location_email public.location_email_addresses%ROWTYPE;
  v_vendor_name text;
  v_invoice_number text;
  v_total_amount numeric := 0;
  v_invoice_id uuid;
  v_system_user_id uuid := '99999999-9999-9999-9999-999999999999'::uuid;
  v_metadata jsonb;
BEGIN
  v_recipient_email := lower(btrim(COALESCE(p_recipient_email, '')));

  IF v_recipient_email = '' THEN
    v_recipient_email := NULL;
  END IF;

  v_vendor_name := COALESCE(NULLIF(btrim(p_invoice->>'vendor_name'), ''), 'Unknown Vendor (Auto-Ingested)');
  v_invoice_number := COALESCE(
    NULLIF(btrim(p_invoice->>'invoice_number'), ''),
    'EMAIL-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS') || '-' || substr(gen_random_uuid()::text, 1, 8)
  );

  BEGIN
    v_total_amount := COALESCE(NULLIF(btrim(p_invoice->>'total_amount'), '')::numeric, 0);
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    v_total_amount := 0;
  END;

  SELECT lea.*
    INTO v_location_email
  FROM public.location_email_addresses lea
  WHERE lower(lea.email) = v_recipient_email
    AND lea.is_active = true
    AND lea.deleted_at IS NULL
  LIMIT 1;

  IF FOUND THEN
    v_metadata := COALESCE(p_invoice->'ap_metadata', '{}'::jsonb)
      || jsonb_build_object(
        'ingest_recipient', v_recipient_email,
        'received_at', now(),
        'matched_location_email_id', v_location_email.id,
        'source', 'email_import'
      );

    INSERT INTO public.invoices (
      vendor_name,
      invoice_number,
      total_amount,
      status,
      ap_status,
      source,
      file_url,
      organization_id,
      brand_id,
      location_id,
      created_by,
      ap_metadata
    ) VALUES (
      v_vendor_name,
      v_invoice_number,
      v_total_amount,
      'extracting',
      'processing',
      'email_import',
      NULLIF(p_invoice->>'file_url', ''),
      v_location_email.organization_id,
      v_location_email.brand_id,
      v_location_email.location_id,
      v_system_user_id,
      v_metadata
    )
    RETURNING id INTO v_invoice_id;

    RETURN jsonb_build_object(
      'invoice_id', v_invoice_id,
      'matched', true,
      'organization_id', v_location_email.organization_id,
      'brand_id', v_location_email.brand_id,
      'location_id', v_location_email.location_id,
      'recipient_email', v_recipient_email
    );
  END IF;

  RETURN jsonb_build_object(
    'invoice_id', NULL,
    'matched', false,
    'organization_id', p_fallback_organization_id,
    'recipient_email', v_recipient_email,
    'warning', 'no_location_email_match'
  );
END;
$$;

REVOKE ALL ON FUNCTION public.ingest_email_invoice(text, uuid, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.ingest_email_invoice(text, uuid, jsonb) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.ingest_email_invoice(text, uuid, jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.sync_invoice_products(p_invoice_id UUID, p_user_id UUID DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_item RECORD;
  v_product_id UUID;
  v_vendor_item_id UUID;
  v_previous_price NUMERIC;
  v_threshold NUMERIC := 10;
  v_price_variance_flag BOOLEAN;
  v_price_variance_percent NUMERIC;
  v_line_hash TEXT;
  v_existing_hash TEXT;
  v_updates_count INT := 0;
  v_report_unit TEXT;
BEGIN
  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id;

  IF v_invoice IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Invoice not found');
  END IF;

  SELECT md5(COALESCE(jsonb_agg(jsonb_build_object(
      'id', ili.id,
      'item_name', ili.item_name,
      'quantity', ili.quantity,
      'unit_price', ili.unit_price,
      'total_price', ili.total_price,
      'vendor_item_code', ili.vendor_item_code,
      'vendor_unit', ili.vendor_unit
    ) ORDER BY ili.id)::TEXT, '[]'))
    INTO v_line_hash
  FROM public.invoice_line_items ili
  WHERE ili.invoice_id = p_invoice_id;

  SELECT hash INTO v_existing_hash
  FROM public.invoice_sync_log
  WHERE invoice_id = p_invoice_id
    AND operation = 'sync_invoice_products'
  ORDER BY processed_at DESC
  LIMIT 1;

  IF v_existing_hash IS NOT NULL AND v_existing_hash = v_line_hash THEN
    RETURN jsonb_build_object('status', 'success', 'updates_count', 0, 'idempotent', true);
  END IF;

  FOR v_item IN
    SELECT *
    FROM public.invoice_line_items
    WHERE invoice_id = p_invoice_id
      AND NULLIF(trim(COALESCE(item_name, '')), '') IS NOT NULL
  LOOP
    v_product_id := v_item.internal_product_id;
    v_vendor_item_id := NULL;
    v_price_variance_flag := false;
    v_price_variance_percent := 0;
    v_report_unit := public.derive_product_report_unit(v_item.vendor_unit, NULL);

    IF v_product_id IS NULL THEN
      SELECT id INTO v_product_id
      FROM public.products
      WHERE organization_id = v_invoice.organization_id
        AND lower(name) = lower(v_item.item_name)
        AND deleted_at IS NULL
        AND (
          brand_id IS NOT DISTINCT FROM v_invoice.brand_id
          OR brand_id IS NULL
        )
      ORDER BY CASE WHEN brand_id IS NOT DISTINCT FROM v_invoice.brand_id THEN 0 ELSE 1 END
      LIMIT 1;

      IF v_product_id IS NULL THEN
        INSERT INTO public.products (
          organization_id,
          brand_id,
          location_id,
          product_id,
          name,
          category,
          accounting_category,
          report_by_unit,
          base_unit,
          latest_price,
          report_unit_quantity,
          report_unit_source_price,
          is_inventoried
        ) VALUES (
          v_invoice.organization_id,
          v_invoice.brand_id,
          v_invoice.location_id,
          public.generate_restops_product_id(),
          v_item.item_name,
          public.derive_product_category(NULL, v_item.item_name),
          CASE
            WHEN public.derive_product_category_type(NULL, NULL, v_item.item_name) = 'Beverage' THEN '5200'
            ELSE '5100'
          END,
          COALESCE(v_report_unit, 'Each'),
          COALESCE(v_report_unit, 'Each'),
          COALESCE(v_item.unit_price, 0),
          1,
          COALESCE(v_item.unit_price, 0),
          false
        )
        ON CONFLICT ON CONSTRAINT products_org_name_key
        DO UPDATE SET
          deleted_at = NULL,
          report_by_unit = CASE
            WHEN public.product_unit_is_generic(products.report_by_unit) THEN COALESCE(EXCLUDED.report_by_unit, products.report_by_unit)
            ELSE products.report_by_unit
          END,
          base_unit = CASE
            WHEN public.product_unit_is_generic(products.base_unit) THEN COALESCE(EXCLUDED.base_unit, products.base_unit)
            ELSE products.base_unit
          END,
          report_unit_source_price = CASE
            WHEN COALESCE(EXCLUDED.report_unit_source_price, 0) > 0 THEN EXCLUDED.report_unit_source_price
            ELSE products.report_unit_source_price
          END,
          latest_price = CASE
            WHEN COALESCE(EXCLUDED.latest_price, 0) > 0 THEN EXCLUDED.latest_price
            ELSE products.latest_price
          END,
          updated_at = now()
        RETURNING id INTO v_product_id;
      ELSE
        UPDATE public.products
           SET product_id = COALESCE(NULLIF(product_id, ''), public.generate_restops_product_id()),
               report_by_unit = CASE
                 WHEN public.product_unit_is_generic(report_by_unit) THEN COALESCE(v_report_unit, report_by_unit)
                 ELSE report_by_unit
               END,
               base_unit = CASE
                 WHEN public.product_unit_is_generic(base_unit) THEN COALESCE(v_report_unit, base_unit)
                 ELSE base_unit
               END,
               report_unit_source_price = CASE
                 WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price
                 ELSE report_unit_source_price
               END,
               latest_price = CASE
                 WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price / GREATEST(COALESCE(report_unit_quantity, 1), 0.0001)
                 ELSE latest_price
               END,
               category = CASE
                 WHEN NULLIF(trim(COALESCE(category, '')), '') IS NULL OR lower(category) = 'uncategorized'
                   THEN public.derive_product_category(category, v_item.item_name)
                 ELSE category
               END,
               brand_id = COALESCE(brand_id, v_invoice.brand_id),
               location_id = COALESCE(location_id, v_invoice.location_id),
               updated_at = now()
         WHERE id = v_product_id;
      END IF;
    ELSE
      UPDATE public.products
         SET report_by_unit = CASE
               WHEN public.product_unit_is_generic(report_by_unit) THEN COALESCE(v_report_unit, report_by_unit)
               ELSE report_by_unit
             END,
             base_unit = CASE
               WHEN public.product_unit_is_generic(base_unit) THEN COALESCE(v_report_unit, base_unit)
               ELSE base_unit
             END,
             report_unit_source_price = CASE
               WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price
               ELSE report_unit_source_price
             END,
             latest_price = CASE
               WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price / GREATEST(COALESCE(report_unit_quantity, 1), 0.0001)
               ELSE latest_price
             END,
             updated_at = now()
       WHERE id = v_product_id
         AND deleted_at IS NULL;
    END IF;

    IF v_invoice.vendor_id IS NOT NULL THEN
      SELECT id, last_price, price_variance_threshold_percent
        INTO v_vendor_item_id, v_previous_price, v_threshold
      FROM public.vendor_items
      WHERE organization_id = v_invoice.organization_id
        AND vendor_id = v_invoice.vendor_id
        AND lower(vendor_item_name) = lower(v_item.item_name)
        AND COALESCE(vendor_item_code, '') = COALESCE(v_item.vendor_item_code, '')
      LIMIT 1;

      v_threshold := COALESCE(v_threshold, 10);

      IF v_vendor_item_id IS NOT NULL THEN
        IF COALESCE(v_previous_price, 0) > 0 AND COALESCE(v_item.unit_price, 0) > 0 THEN
          v_price_variance_percent := ((v_item.unit_price - v_previous_price) / v_previous_price) * 100;
          v_price_variance_flag := abs(v_price_variance_percent) >= v_threshold;
        END IF;

        UPDATE public.vendor_items
           SET vendor_unit = COALESCE(NULLIF(v_item.vendor_unit, ''), vendor_unit),
               previous_price = last_price,
               last_price = COALESCE(v_item.unit_price, last_price),
               last_invoice_id = p_invoice_id,
               last_invoice_line_id = v_item.id,
               last_purchased_at = COALESCE(v_invoice.invoice_date, CURRENT_DATE),
               last_price_change_percent = v_price_variance_percent,
               price_variance_flag = v_price_variance_flag,
               updated_at = now()
         WHERE id = v_vendor_item_id;
      ELSE
        INSERT INTO public.vendor_items (
          organization_id,
          vendor_id,
          vendor_item_code,
          vendor_item_name,
          vendor_unit,
          default_price,
          last_price,
          last_invoice_id,
          last_invoice_line_id,
          last_purchased_at,
          updated_at
        ) VALUES (
          v_invoice.organization_id,
          v_invoice.vendor_id,
          NULLIF(v_item.vendor_item_code, ''),
          v_item.item_name,
          NULLIF(v_item.vendor_unit, ''),
          v_item.unit_price,
          v_item.unit_price,
          p_invoice_id,
          v_item.id,
          COALESCE(v_invoice.invoice_date, CURRENT_DATE),
          now()
        )
        RETURNING id INTO v_vendor_item_id;
      END IF;

      IF v_product_id IS NOT NULL AND v_vendor_item_id IS NOT NULL THEN
        INSERT INTO public.vendor_item_mappings (
          organization_id,
          vendor_item_id,
          internal_product_id,
          conversion_multiplier,
          is_verified,
          updated_at
        ) VALUES (
          v_invoice.organization_id,
          v_vendor_item_id,
          v_product_id,
          1,
          false,
          now()
        )
        ON CONFLICT (vendor_item_id, internal_product_id)
        DO UPDATE SET updated_at = now();
      END IF;
    END IF;

    UPDATE public.invoice_line_items
       SET vendor_id = v_invoice.vendor_id,
           vendor_item_id = v_vendor_item_id,
           internal_product_id = v_product_id,
           price_variance_flag = v_price_variance_flag,
           price_variance_percent = v_price_variance_percent
     WHERE id = v_item.id;

    UPDATE public.inventory inv
       SET unit_cost = CASE
             WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price / GREATEST((SELECT COALESCE(report_unit_quantity, 1) FROM public.products WHERE id = v_product_id), 0.0001)
             ELSE inv.unit_cost
           END,
           current_unit = CASE
             WHEN public.product_unit_is_generic(inv.current_unit) THEN COALESCE(v_report_unit, inv.current_unit)
             ELSE inv.current_unit
           END,
           report_by = CASE
             WHEN public.product_unit_is_generic(inv.report_by) THEN COALESCE(v_report_unit, inv.report_by)
             ELSE inv.report_by
           END,
           updated_at = now()
     WHERE v_product_id IS NOT NULL
       AND inv.organization_id = v_invoice.organization_id
       AND inv.deleted_at IS NULL
       AND (
         inv.internal_product_id = v_product_id
         OR inv.product_id = (SELECT product_id FROM public.products WHERE id = v_product_id)
       );

    v_updates_count := v_updates_count + 1;
  END LOOP;

  INSERT INTO public.invoice_event_log (invoice_id, event_type, new_value, actor_id)
  VALUES (
    p_invoice_id,
    'product_catalog_synced',
    jsonb_build_object('updates_count', v_updates_count),
    COALESCE(p_user_id, auth.uid())
  );

  INSERT INTO public.invoice_sync_log (invoice_id, operation, hash)
  VALUES (p_invoice_id, 'sync_invoice_products', v_line_hash);

  RETURN jsonb_build_object('status', 'success', 'updates_count', v_updates_count);
END;
$$;

GRANT EXECUTE ON FUNCTION public.sync_invoice_products(uuid, uuid) TO authenticated;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260721000040_price_movers_report.sql
-- ==========================================================================

-- Price Movers Report: purchasing unit-price analytics (no POS).
-- Safe comparison: same internal_product_id + same normalized UOM.
-- Normalized unit cost = total_price / NULLIF(quantity * COALESCE(conversion_multiplier, 1), 0).
-- Eligibility: is_purchasing_spend_invoice (same as Category Report).

BEGIN;

-- Ensure UOM normalization helper exists (may be missing if product-module
-- migration was not applied to this environment).
CREATE OR REPLACE FUNCTION public.normalize_product_report_unit(p_unit text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE
    WHEN NULLIF(trim(COALESCE(p_unit, '')), '') IS NULL THEN 'Each'
    WHEN lower(trim(p_unit)) IN ('ea', 'each', 'unit', 'units') THEN 'Each'
    WHEN lower(trim(p_unit)) IN ('cs', 'case', 'cases') THEN 'Case'
    WHEN lower(trim(p_unit)) IN ('lb', 'lbs', 'pound', 'pounds') THEN 'Pound'
    WHEN lower(trim(p_unit)) IN ('oz', 'ounce', 'ounces') THEN 'Ounce'
    WHEN lower(trim(p_unit)) IN ('gal', 'gallon', 'gallons') THEN 'Gallon'
    WHEN lower(trim(p_unit)) IN ('qt', 'quart', 'quarts') THEN 'Quart'
    WHEN lower(trim(p_unit)) IN ('pt', 'pint', 'pints') THEN 'Pint'
    WHEN lower(trim(p_unit)) IN ('floz', 'fl oz', 'fluid ounce', 'fluid ounces') THEN 'Fluid Ounce'
    WHEN lower(trim(p_unit)) IN ('kg', 'kilogram', 'kilograms') THEN 'Kilogram'
    WHEN lower(trim(p_unit)) IN ('g', 'gram', 'grams') THEN 'Gram'
    WHEN lower(trim(p_unit)) IN ('box', 'boxes') THEN 'Box'
    WHEN lower(trim(p_unit)) IN ('bag', 'bags') THEN 'Bag'
    WHEN lower(trim(p_unit)) IN ('btl', 'bottle', 'bottles') THEN 'Bottle'
    WHEN lower(trim(p_unit)) IN ('can', 'cans') THEN 'Can'
    ELSE initcap(trim(p_unit))
  END;
$$;

CREATE OR REPLACE FUNCTION public.get_price_movers_report(
  p_organization_id uuid DEFAULT NULL,
  p_location_ids uuid[] DEFAULT NULL,
  p_date_from date DEFAULT NULL,
  p_date_to date DEFAULT NULL,
  p_comparison_date_from date DEFAULT NULL,
  p_comparison_date_to date DEFAULT NULL,
  p_category_names text[] DEFAULT NULL,
  p_vendor_ids uuid[] DEFAULT NULL,
  p_timezone text DEFAULT 'UTC',
  p_product_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_tz text := COALESCE(NULLIF(trim(p_timezone), ''), 'UTC');
  v_result jsonb;
  v_outlier_threshold numeric := 50; -- abs % change above this flagged as outlier
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;
  IF p_date_from IS NULL OR p_date_to IS NULL THEN
    RAISE EXCEPTION 'date_from and date_to are required';
  END IF;

  WITH eligible_invoices AS (
    SELECT i.*
    FROM public.invoices i
    WHERE i.organization_id = v_org_id
      AND public.is_purchasing_spend_invoice(i.status, i.ap_status, i.deleted_at)
      AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR i.location_id = ANY (p_location_ids)
      )
      AND (
        p_vendor_ids IS NULL OR cardinality(p_vendor_ids) = 0
        OR i.vendor_id = ANY (p_vendor_ids)
      )
  ),
  mapped_lines AS (
    SELECT
      ili.id AS line_id,
      ili.invoice_id,
      i.invoice_date,
      i.vendor_id,
      COALESCE(NULLIF(trim(i.vendor_name), ''), 'Unknown vendor') AS vendor_name,
      i.location_id,
      ili.internal_product_id,
      COALESCE(p.name, ili.item_name, 'Unknown product') AS product_name,
      COALESCE(NULLIF(trim(p.category), ''), 'Uncategorized') AS category_name,
      public.normalize_product_report_unit(
        COALESCE(NULLIF(trim(p.report_by_unit), ''), NULLIF(trim(ili.vendor_unit), ''), 'Each')
      ) AS report_unit,
      COALESCE(ili.quantity, 0)::numeric AS quantity,
      COALESCE(ili.unit_price, 0)::numeric AS unit_price,
      COALESCE(ili.total_price, COALESCE(ili.quantity, 0) * COALESCE(ili.unit_price, 0))::numeric AS total_price,
      COALESCE(vim.conversion_multiplier, 1)::numeric AS conversion_multiplier,
      CASE
        WHEN ili.internal_product_id IS NULL THEN 'unmapped'
        WHEN vim.is_verified IS TRUE THEN 'verified'
        WHEN vim.internal_product_id IS NOT NULL THEN 'mapped'
        ELSE 'mapped'
      END AS mapping_status,
      NULLIF(trim(ili.vendor_unit), '') AS vendor_unit,
      NULLIF(trim(vi.pack_size), '') AS pack_size
    FROM eligible_invoices i
    JOIN public.invoice_line_items ili ON ili.invoice_id = i.id
    LEFT JOIN public.products p ON p.id = ili.internal_product_id AND p.deleted_at IS NULL
    LEFT JOIN LATERAL (
      SELECT m.conversion_multiplier, m.is_verified, m.internal_product_id
      FROM public.vendor_item_mappings m
      WHERE m.internal_product_id = ili.internal_product_id
        AND (ili.vendor_item_id IS NULL OR m.vendor_item_id = ili.vendor_item_id)
      ORDER BY m.is_verified DESC NULLS LAST
      LIMIT 1
    ) vim ON TRUE
    LEFT JOIN public.vendor_items vi ON vi.id = ili.vendor_item_id
    WHERE (
        p_category_names IS NULL OR cardinality(p_category_names) = 0
        OR COALESCE(NULLIF(trim(p.category), ''), 'Uncategorized') = ANY (p_category_names)
      )
      AND (p_product_id IS NULL OR ili.internal_product_id = p_product_id)
  ),
  priced AS (
    SELECT
      ml.*,
      (ml.quantity * ml.conversion_multiplier) AS normalized_qty,
      CASE
        WHEN (ml.quantity * ml.conversion_multiplier) = 0 THEN NULL
        ELSE round(ml.total_price / (ml.quantity * ml.conversion_multiplier), 6)
      END AS normalized_unit_cost
    FROM mapped_lines ml
  ),
  current_rows AS (
    SELECT * FROM priced
    WHERE invoice_date >= p_date_from AND invoice_date <= p_date_to
  ),
  previous_rows AS (
    SELECT * FROM priced
    WHERE p_comparison_date_from IS NOT NULL
      AND p_comparison_date_to IS NOT NULL
      AND invoice_date >= p_comparison_date_from
      AND invoice_date <= p_comparison_date_to
  ),
  current_agg AS (
    SELECT
      internal_product_id,
      product_name,
      category_name,
      report_unit,
      (array_agg(vendor_name ORDER BY total_price DESC))[1] AS primary_vendor,
      (array_agg(vendor_id ORDER BY total_price DESC))[1] AS primary_vendor_id,
      (array_agg(mapping_status ORDER BY CASE mapping_status WHEN 'verified' THEN 0 WHEN 'mapped' THEN 1 ELSE 2 END))[1] AS mapping_status,
      (array_agg(pack_size) FILTER (WHERE pack_size IS NOT NULL))[1] AS pack_size,
      round(sum(total_price)::numeric, 2) AS current_spend,
      round(sum(normalized_qty)::numeric, 4) AS current_qty,
      CASE WHEN sum(normalized_qty) = 0 THEN NULL
           ELSE round(sum(total_price) / sum(normalized_qty), 6)
      END AS current_price,
      count(DISTINCT invoice_id)::bigint AS invoice_count,
      max(invoice_date) AS last_purchase
    FROM current_rows
    GROUP BY internal_product_id, product_name, category_name, report_unit
  ),
  previous_agg AS (
    SELECT
      internal_product_id,
      report_unit,
      round(sum(total_price)::numeric, 2) AS previous_spend,
      round(sum(normalized_qty)::numeric, 4) AS previous_qty,
      CASE WHEN sum(normalized_qty) = 0 THEN NULL
           ELSE round(sum(total_price) / sum(normalized_qty), 6)
      END AS previous_price
    FROM previous_rows
    GROUP BY internal_product_id, report_unit
  ),
  joined AS (
    SELECT
      c.internal_product_id AS product_id,
      c.product_name AS product,
      c.primary_vendor AS vendor,
      c.primary_vendor_id AS vendor_id,
      c.category_name AS category,
      c.report_unit AS unit,
      c.pack_size,
      c.current_price,
      p.previous_price,
      c.current_spend,
      COALESCE(p.previous_spend, 0) AS previous_spend,
      c.current_qty,
      c.invoice_count,
      c.last_purchase,
      c.mapping_status,
      CASE
        WHEN c.internal_product_id IS NULL THEN 'not_comparable'
        WHEN c.current_price IS NULL THEN 'not_comparable'
        WHEN p.previous_price IS NULL THEN 'not_comparable'
        WHEN c.report_unit IS DISTINCT FROM p.report_unit THEN 'not_comparable'
        ELSE 'comparable'
      END AS comparability_status,
      CASE
        WHEN c.internal_product_id IS NULL OR c.current_price IS NULL OR p.previous_price IS NULL
          OR c.report_unit IS DISTINCT FROM p.report_unit
        THEN NULL
        ELSE round(c.current_price - p.previous_price, 6)
      END AS price_change,
      CASE
        WHEN c.internal_product_id IS NULL OR c.current_price IS NULL OR p.previous_price IS NULL
          OR c.report_unit IS DISTINCT FROM p.report_unit
        THEN NULL
        WHEN p.previous_price = 0 AND c.current_price = 0 THEN 0
        WHEN p.previous_price = 0 THEN NULL
        ELSE round(((c.current_price - p.previous_price) / abs(p.previous_price)) * 100, 2)
      END AS percentage_change,
      CASE
        WHEN c.internal_product_id IS NULL OR c.current_price IS NULL OR p.previous_price IS NULL
          OR c.report_unit IS DISTINCT FROM p.report_unit
        THEN NULL
        ELSE round((c.current_price - p.previous_price) * c.current_qty, 2)
      END AS estimated_impact
    FROM current_agg c
    LEFT JOIN previous_agg p
      ON p.internal_product_id IS NOT DISTINCT FROM c.internal_product_id
     AND p.report_unit = c.report_unit
  ),
  enriched AS (
    SELECT
      j.*,
      CASE
        WHEN j.comparability_status <> 'comparable' OR j.percentage_change IS NULL THEN 'n/a'
        WHEN abs(j.percentage_change) >= v_outlier_threshold THEN 'outlier'
        ELSE 'normal'
      END AS outlier_status
    FROM joined j
  ),
  comparable AS (
    SELECT * FROM enriched WHERE comparability_status = 'comparable'
  ),
  summary AS (
    SELECT
      (SELECT count(*) FROM comparable WHERE price_change > 0)::int AS products_with_increases,
      (SELECT count(*) FROM comparable WHERE price_change < 0)::int AS products_with_decreases,
      (SELECT round(avg(percentage_change)::numeric, 2) FROM comparable WHERE percentage_change IS NOT NULL) AS average_price_change,
      (SELECT round(coalesce(sum(estimated_impact), 0)::numeric, 2) FROM comparable WHERE estimated_impact > 0) AS estimated_unfavorable_impact,
      (SELECT round(coalesce(sum(estimated_impact), 0)::numeric, 2) FROM comparable WHERE estimated_impact < 0) AS estimated_favorable_impact,
      (SELECT count(*) FROM enriched WHERE comparability_status = 'not_comparable')::int AS non_comparable_count,
      (SELECT count(*) FROM enriched)::int AS total_products,
      (SELECT count(DISTINCT vendor_id) FROM comparable WHERE price_change > 0 AND vendor_id IS NOT NULL)::int AS vendors_driving_increases
  ),
  largest_increase AS (
    SELECT jsonb_build_object(
      'product', product,
      'vendor', vendor,
      'category', category,
      'priceChange', price_change,
      'percentageChange', percentage_change,
      'estimatedImpact', estimated_impact
    ) AS obj
    FROM comparable
    WHERE price_change IS NOT NULL
    ORDER BY price_change DESC NULLS LAST
    LIMIT 1
  ),
  largest_decrease AS (
    SELECT jsonb_build_object(
      'product', product,
      'vendor', vendor,
      'category', category,
      'priceChange', price_change,
      'percentageChange', percentage_change,
      'estimatedImpact', estimated_impact
    ) AS obj
    FROM comparable
    WHERE price_change IS NOT NULL
    ORDER BY price_change ASC NULLS LAST
    LIMIT 1
  ),
  most_volatile AS (
    SELECT jsonb_build_object(
      'product', product,
      'vendor', vendor,
      'category', category,
      'percentageChange', percentage_change,
      'estimatedImpact', estimated_impact
    ) AS obj
    FROM comparable
    WHERE percentage_change IS NOT NULL
    ORDER BY abs(percentage_change) DESC NULLS LAST
    LIMIT 1
  ),
  ranking AS (
    SELECT jsonb_agg(
      jsonb_build_object(
        'product', product,
        'productId', product_id,
        'vendor', vendor,
        'category', category,
        'percentageChange', percentage_change,
        'priceChange', price_change,
        'estimatedImpact', estimated_impact,
        'currentPrice', current_price
      )
      ORDER BY estimated_impact DESC NULLS LAST
    ) AS arr
    FROM (
      SELECT * FROM comparable
      WHERE estimated_impact IS NOT NULL
      ORDER BY estimated_impact DESC NULLS LAST
      LIMIT 20
    ) top_impact
  ),
  -- Histogram buckets of percentage change
  hist AS (
    SELECT
      width_bucket(percentage_change, -50, 50, 10) AS bucket,
      count(*)::int AS count
    FROM comparable
    WHERE percentage_change IS NOT NULL
      AND percentage_change BETWEEN -50 AND 50
    GROUP BY 1
  ),
  distribution AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'bucket', bucket,
        'label', CASE bucket
          WHEN 1 THEN '-50 to -40'
          WHEN 2 THEN '-40 to -30'
          WHEN 3 THEN '-30 to -20'
          WHEN 4 THEN '-20 to -10'
          WHEN 5 THEN '-10 to 0'
          WHEN 6 THEN '0 to 10'
          WHEN 7 THEN '10 to 20'
          WHEN 8 THEN '20 to 30'
          WHEN 9 THEN '30 to 40'
          WHEN 10 THEN '40 to 50'
          ELSE 'other'
        END,
        'count', count
      )
      ORDER BY bucket
    ), '[]'::jsonb) AS arr
    FROM hist
  ),
  scatter AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'productId', product_id,
        'product', product,
        'percentageChange', percentage_change,
        'estimatedImpact', estimated_impact,
        'currentSpend', current_spend,
        'category', category
      )
    ), '[]'::jsonb) AS arr
    FROM comparable
    WHERE percentage_change IS NOT NULL AND estimated_impact IS NOT NULL
  ),
  category_inflation AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'category', category,
        'averagePercentageChange', average_percentage_change,
        'unfavorableImpact', unfavorable_impact,
        'productCount', product_count
      )
      ORDER BY average_percentage_change DESC NULLS LAST
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT
        category,
        round(avg(percentage_change)::numeric, 2) AS average_percentage_change,
        round(sum(estimated_impact) FILTER (WHERE estimated_impact > 0)::numeric, 2) AS unfavorable_impact,
        count(*)::int AS product_count
      FROM comparable
      WHERE percentage_change IS NOT NULL
      GROUP BY category
    ) cat
  ),
  vendor_impact AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'vendor', vendor,
        'vendorId', vendor_id,
        'unfavorableImpact', unfavorable_impact,
        'favorableImpact', favorable_impact,
        'netImpact', net_impact,
        'productsIncreased', products_increased,
        'productCount', product_count
      )
      ORDER BY unfavorable_impact DESC NULLS LAST
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT
        vendor,
        vendor_id,
        round(sum(estimated_impact) FILTER (WHERE estimated_impact > 0)::numeric, 2) AS unfavorable_impact,
        round(sum(estimated_impact) FILTER (WHERE estimated_impact < 0)::numeric, 2) AS favorable_impact,
        round(sum(estimated_impact)::numeric, 2) AS net_impact,
        count(*) FILTER (WHERE price_change > 0)::int AS products_increased,
        count(*)::int AS product_count
      FROM comparable
      WHERE vendor IS NOT NULL AND estimated_impact IS NOT NULL
      GROUP BY vendor, vendor_id
    ) ven
  ),
  -- Trend for top volatile / impact products (daily or weekly points in current period)
  top_trend_products AS (
    SELECT product_id
    FROM comparable
    WHERE product_id IS NOT NULL AND percentage_change IS NOT NULL
    ORDER BY abs(COALESCE(estimated_impact, 0)) DESC
    LIMIT 5
  ),
  trend AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'bucket', t.bucket,
        'bucketStart', t.bucket_start,
        'product', t.product_name,
        'productId', t.internal_product_id,
        'unitCost', t.unit_cost
      )
      ORDER BY t.bucket_start, t.product_name
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT
        cr.invoice_date::text AS bucket,
        cr.invoice_date AS bucket_start,
        cr.internal_product_id,
        cr.product_name,
        round(avg(cr.normalized_unit_cost)::numeric, 6) AS unit_cost
      FROM current_rows cr
      WHERE cr.internal_product_id IN (SELECT product_id FROM top_trend_products)
        AND cr.normalized_unit_cost IS NOT NULL
      GROUP BY cr.invoice_date, cr.internal_product_id, cr.product_name
    ) t
  ),
  filter_options AS (
    SELECT
      COALESCE((
        SELECT jsonb_agg(DISTINCT category_name ORDER BY category_name)
        FROM priced WHERE category_name IS NOT NULL
      ), '[]'::jsonb) AS categories,
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object('id', vendor_id, 'name', vendor_name) ORDER BY vendor_name)
        FROM (
          SELECT DISTINCT vendor_id, vendor_name FROM priced WHERE vendor_id IS NOT NULL
        ) v
      ), '[]'::jsonb) AS vendors
  )
  SELECT jsonb_build_object(
    'summary', jsonb_build_object(
      'productsWithIncreases', s.products_with_increases,
      'productsWithDecreases', s.products_with_decreases,
      'averagePriceChange', s.average_price_change,
      'estimatedUnfavorableImpact', s.estimated_unfavorable_impact,
      'estimatedFavorableImpact', s.estimated_favorable_impact,
      'largestPriceIncrease', (SELECT obj FROM largest_increase),
      'largestPriceDecrease', (SELECT obj FROM largest_decrease),
      'mostVolatileProduct', (SELECT obj FROM most_volatile),
      'vendorsDrivingIncreases', s.vendors_driving_increases,
      'nonComparableProducts', s.non_comparable_count,
      'totalProducts', s.total_products
    ),
    'ranking', COALESCE((SELECT arr FROM ranking), '[]'::jsonb),
    'trend', COALESCE((SELECT arr FROM trend), '[]'::jsonb),
    'distribution', COALESCE((SELECT arr FROM distribution), '[]'::jsonb),
    'scatter', COALESCE((SELECT arr FROM scatter), '[]'::jsonb),
    'categoryInflation', COALESCE((SELECT arr FROM category_inflation), '[]'::jsonb),
    'vendorImpact', COALESCE((SELECT arr FROM vendor_impact), '[]'::jsonb),
    'tableRows', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'productId', e.product_id,
          'product', e.product,
          'vendor', e.vendor,
          'vendorId', e.vendor_id,
          'category', e.category,
          'unit', e.unit,
          'packSize', e.pack_size,
          'currentPrice', e.current_price,
          'previousPrice', e.previous_price,
          'priceChange', e.price_change,
          'percentageChange', e.percentage_change,
          'currentSpend', e.current_spend,
          'estimatedImpact', e.estimated_impact,
          'invoiceCount', e.invoice_count,
          'lastPurchase', e.last_purchase,
          'mappingStatus', e.mapping_status,
          'comparabilityStatus', e.comparability_status,
          'outlierStatus', e.outlier_status
        )
        ORDER BY COALESCE(e.estimated_impact, 0) DESC
      )
      FROM enriched e
    ), '[]'::jsonb),
    'insights', COALESCE((
      SELECT jsonb_agg(ins ORDER BY (ins->>'impact')::numeric DESC)
      FROM (
        SELECT jsonb_build_object(
          'id', 'unfavorable-impact',
          'impact', abs(s.estimated_unfavorable_impact),
          'text', format(
            'Estimated unfavorable purchasing impact from price increases is $%s.',
            to_char(s.estimated_unfavorable_impact, 'FM999,999,990')
          )
        ) AS ins
        WHERE s.estimated_unfavorable_impact > 0
        UNION ALL
        SELECT jsonb_build_object(
          'id', 'avg-change',
          'impact', abs(COALESCE(s.average_price_change, 0)) * 100,
          'text', format(
            'Average comparable price change is %s%% across %s products.',
            to_char(COALESCE(s.average_price_change, 0), 'FM990.0'),
            s.products_with_increases + s.products_with_decreases
          )
        )
        WHERE s.average_price_change IS NOT NULL
        UNION ALL
        SELECT jsonb_build_object(
          'id', 'non-comparable',
          'impact', s.non_comparable_count,
          'text', format(
            '%s products are not comparable due to missing product mapping or incompatible units.',
            s.non_comparable_count
          )
        )
        WHERE s.non_comparable_count > 0
        UNION ALL
        SELECT jsonb_build_object(
          'id', 'largest-inc',
          'impact', abs(COALESCE((SELECT (obj->>'estimatedImpact')::numeric FROM largest_increase), 0)),
          'text', format(
            '%s had the largest price increase (%s%%).',
            (SELECT obj->>'product' FROM largest_increase),
            (SELECT obj->>'percentageChange' FROM largest_increase)
          )
        )
        WHERE EXISTS (SELECT 1 FROM largest_increase WHERE obj IS NOT NULL)
      ) insight_rows
    ), '[]'::jsonb),
    'metadata', jsonb_build_object(
      'currency', 'USD',
      'timezone', v_tz,
      'dataFreshness', to_char(now() AT TIME ZONE v_tz, 'YYYY-MM-DD HH24:MI'),
      'priceDefinition', 'Normalized weighted-average unit cost = line total_price / (quantity * COALESCE(conversion_multiplier, 1)). Comparisons require the same internal product and normalized UOM. Incompatible units return not_comparable with null percentage change.',
      'outlierThresholdPercent', v_outlier_threshold,
      'filterOptions', jsonb_build_object(
        'categories', (SELECT categories FROM filter_options),
        'vendors', (SELECT vendors FROM filter_options)
      )
    )
  )
  INTO v_result
  FROM summary s;

  RETURN v_result;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_price_movers_report(
  uuid, uuid[], date, date, date, date, text[], uuid[], text, uuid
) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.get_price_movers_drilldown(
  p_organization_id uuid DEFAULT NULL,
  p_product_id uuid DEFAULT NULL,
  p_product_name text DEFAULT NULL,
  p_location_ids uuid[] DEFAULT NULL,
  p_date_from date DEFAULT NULL,
  p_date_to date DEFAULT NULL,
  p_comparison_date_from date DEFAULT NULL,
  p_comparison_date_to date DEFAULT NULL,
  p_vendor_ids uuid[] DEFAULT NULL,
  p_timezone text DEFAULT 'UTC'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_result jsonb;
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;
  IF p_date_from IS NULL OR p_date_to IS NULL THEN
    RAISE EXCEPTION 'date_from and date_to are required';
  END IF;
  IF p_product_id IS NULL AND NULLIF(trim(COALESCE(p_product_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'product_id or product_name is required';
  END IF;

  WITH eligible_invoices AS (
    SELECT i.*
    FROM public.invoices i
    WHERE i.organization_id = v_org_id
      AND public.is_purchasing_spend_invoice(i.status, i.ap_status, i.deleted_at)
      AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR i.location_id = ANY (p_location_ids)
      )
      AND (
        p_vendor_ids IS NULL OR cardinality(p_vendor_ids) = 0
        OR i.vendor_id = ANY (p_vendor_ids)
      )
  ),
  lines AS (
    SELECT
      ili.id AS line_id,
      ili.invoice_id,
      i.invoice_number,
      i.invoice_date,
      i.vendor_id,
      COALESCE(NULLIF(trim(i.vendor_name), ''), 'Unknown vendor') AS vendor_name,
      l.name AS location_name,
      ili.internal_product_id,
      COALESCE(p.name, ili.item_name) AS product_name,
      COALESCE(NULLIF(trim(p.category), ''), 'Uncategorized') AS category_name,
      public.normalize_product_report_unit(
        COALESCE(NULLIF(trim(p.report_by_unit), ''), NULLIF(trim(ili.vendor_unit), ''), 'Each')
      ) AS report_unit,
      COALESCE(ili.quantity, 0)::numeric AS quantity,
      COALESCE(ili.unit_price, 0)::numeric AS unit_price,
      COALESCE(ili.total_price, 0)::numeric AS total_price,
      COALESCE(vim.conversion_multiplier, 1)::numeric AS conversion_multiplier,
      NULLIF(trim(ili.vendor_unit), '') AS vendor_unit,
      NULLIF(trim(vi.pack_size), '') AS pack_size,
      i.status
    FROM eligible_invoices i
    JOIN public.invoice_line_items ili ON ili.invoice_id = i.id
    LEFT JOIN public.products p ON p.id = ili.internal_product_id
    LEFT JOIN public.locations l ON l.id = i.location_id
    LEFT JOIN LATERAL (
      SELECT m.conversion_multiplier
      FROM public.vendor_item_mappings m
      WHERE m.internal_product_id = ili.internal_product_id
      ORDER BY m.is_verified DESC NULLS LAST
      LIMIT 1
    ) vim ON TRUE
    LEFT JOIN public.vendor_items vi ON vi.id = ili.vendor_item_id
    WHERE (
      (p_product_id IS NOT NULL AND ili.internal_product_id = p_product_id)
      OR (
        p_product_id IS NULL
        AND lower(COALESCE(p.name, ili.item_name, '')) = lower(trim(p_product_name))
      )
    )
  ),
  priced AS (
    SELECT
      *,
      quantity * conversion_multiplier AS normalized_qty,
      CASE WHEN quantity * conversion_multiplier = 0 THEN NULL
           ELSE round(total_price / (quantity * conversion_multiplier), 6)
      END AS normalized_unit_cost
    FROM lines
  ),
  current_rows AS (
    SELECT * FROM priced
    WHERE invoice_date >= p_date_from AND invoice_date <= p_date_to
  ),
  previous_rows AS (
    SELECT * FROM priced
    WHERE p_comparison_date_from IS NOT NULL
      AND p_comparison_date_to IS NOT NULL
      AND invoice_date >= p_comparison_date_from
      AND invoice_date <= p_comparison_date_to
  ),
  summary AS (
    SELECT
      (SELECT product_name FROM current_rows LIMIT 1) AS product,
      (SELECT category_name FROM current_rows LIMIT 1) AS category,
      (SELECT report_unit FROM current_rows LIMIT 1) AS unit,
      (SELECT pack_size FROM current_rows WHERE pack_size IS NOT NULL LIMIT 1) AS pack_size,
      CASE WHEN sum(normalized_qty) = 0 THEN NULL
           ELSE round(sum(total_price) / sum(normalized_qty), 6) END AS current_price,
      (SELECT CASE WHEN sum(pr.normalized_qty) = 0 THEN NULL
                   ELSE round(sum(pr.total_price) / sum(pr.normalized_qty), 6) END
       FROM previous_rows pr) AS previous_price,
      round(sum(total_price)::numeric, 2) AS current_spend,
      count(DISTINCT invoice_id)::bigint AS invoice_count,
      count(DISTINCT vendor_id)::bigint AS vendor_count
    FROM current_rows
  ),
  price_history AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'date', invoice_date,
        'unitCost', round(avg(normalized_unit_cost)::numeric, 6),
        'spend', round(sum(total_price)::numeric, 2),
        'quantity', round(sum(normalized_qty)::numeric, 4)
      )
      ORDER BY invoice_date
    ), '[]'::jsonb) AS arr
    FROM current_rows
    WHERE normalized_unit_cost IS NOT NULL
    GROUP BY invoice_date
  ),
  vendor_comparison AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'vendor', vendor_name,
        'vendorId', vendor_id,
        'currentPrice', CASE WHEN sum(normalized_qty) = 0 THEN NULL
                             ELSE round(sum(total_price) / sum(normalized_qty), 6) END,
        'spend', round(sum(total_price)::numeric, 2),
        'invoiceCount', count(DISTINCT invoice_id),
        'unit', (array_agg(report_unit))[1]
      )
      ORDER BY sum(total_price) DESC
    ), '[]'::jsonb) AS arr
    FROM current_rows
    GROUP BY vendor_id, vendor_name
  ),
  purchases AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'invoiceId', invoice_id,
        'invoiceNumber', invoice_number,
        'date', invoice_date,
        'vendor', vendor_name,
        'quantity', quantity,
        'unitPrice', unit_price,
        'normalizedUnitCost', normalized_unit_cost,
        'amount', total_price,
        'unit', report_unit,
        'status', status,
        'location', location_name
      )
      ORDER BY invoice_date DESC
    ), '[]'::jsonb) AS arr
    FROM current_rows
  ),
  normalization AS (
    SELECT jsonb_build_object(
      'reportUnit', (SELECT unit FROM summary),
      'packSize', (SELECT pack_size FROM summary),
      'conversionMultiplier', (SELECT conversion_multiplier FROM current_rows LIMIT 1),
      'formula', 'normalized_unit_cost = total_price / (quantity * COALESCE(conversion_multiplier, 1))',
      'comparabilityRule', 'Same internal_product_id and normalized UOM required across periods'
    ) AS obj
  )
  SELECT jsonb_build_object(
    'productId', p_product_id,
    'summary', jsonb_build_object(
      'product', s.product,
      'category', s.category,
      'unit', s.unit,
      'packSize', s.pack_size,
      'currentPrice', s.current_price,
      'previousPrice', s.previous_price,
      'priceChange', CASE WHEN s.current_price IS NULL OR s.previous_price IS NULL THEN NULL
                          ELSE round(s.current_price - s.previous_price, 6) END,
      'percentageChange', CASE
        WHEN s.current_price IS NULL OR s.previous_price IS NULL THEN NULL
        WHEN s.previous_price = 0 AND s.current_price = 0 THEN 0
        WHEN s.previous_price = 0 THEN NULL
        ELSE round(((s.current_price - s.previous_price) / abs(s.previous_price)) * 100, 2)
      END,
      'currentSpend', s.current_spend,
      'invoiceCount', s.invoice_count,
      'vendorCount', s.vendor_count
    ),
    'priceHistory', (SELECT arr FROM price_history),
    'vendorComparison', (SELECT arr FROM vendor_comparison),
    'purchaseHistory', (SELECT arr FROM purchases),
    'normalization', (SELECT obj FROM normalization)
  )
  INTO v_result
  FROM summary s;

  RETURN v_result;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_price_movers_drilldown(
  uuid, uuid, text, uuid[], date, date, date, date, uuid[], text
) TO authenticated, service_role;

CREATE INDEX IF NOT EXISTS idx_invoice_line_items_org_product
  ON public.invoice_line_items (organization_id, internal_product_id);

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260721000050_inventory_usage_report.sql
-- ==========================================================================

-- Inventory Usage Report: actual inventory movement/count analytics (no POS).
-- Locked rules:
--   Actual Usage = Opening + Receipts + Transfers In - Transfers Out + Adjustments(signed) - Closing
--   Waste reported separately (not added into Actual Usage)
--   Official Actual Usage only when opening AND closing counts exist; else Not Calculable
--   Exclude POS/theoretical movement types
--   Widen movement_type CHECK for writer RPC types

BEGIN;

-- 1) Widen CHECK so transfer_in/out and count_variance (and related) are valid.
ALTER TABLE public.inventory_movements
  DROP CONSTRAINT IF EXISTS inventory_movements_movement_type_check;

ALTER TABLE public.inventory_movements
  ADD CONSTRAINT inventory_movements_movement_type_check
  CHECK (movement_type = ANY (ARRAY[
    'invoice_received'::text,
    'recipe_consumption'::text,
    'manual_adjustment'::text,
    'transfer'::text,
    'transfer_in'::text,
    'transfer_out'::text,
    'wastage'::text,
    'spoilage'::text,
    'purchase_order'::text,
    'stock_count'::text,
    'count_variance'::text,
    'sales_depletion'::text,
    'pos_adjustment'::text
  ]));

CREATE OR REPLACE FUNCTION public.get_inventory_usage_report(
  p_organization_id uuid DEFAULT NULL,
  p_location_ids uuid[] DEFAULT NULL,
  p_date_from date DEFAULT NULL,
  p_date_to date DEFAULT NULL,
  p_category_names text[] DEFAULT NULL,
  p_timezone text DEFAULT 'UTC'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_tz text := COALESCE(NULLIF(trim(p_timezone), ''), 'UTC');
  v_result jsonb;
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;
  IF p_date_from IS NULL OR p_date_to IS NULL THEN
    RAISE EXCEPTION 'date_from and date_to are required';
  END IF;

  WITH scoped_inventory AS (
    SELECT
      inv.id AS inventory_id,
      inv.organization_id,
      inv.location_id,
      COALESCE(loc.name, inv.location, 'Unknown location') AS location_name,
      inv.internal_product_id AS product_id,
      COALESCE(p.name, inv.product_name, 'Unknown product') AS product,
      COALESCE(NULLIF(trim(COALESCE(p.category, inv.category)), ''), 'Uncategorized') AS category,
      public.normalize_product_report_unit(
        COALESCE(NULLIF(trim(inv.current_unit), ''), NULLIF(trim(p.report_by_unit), ''), NULLIF(trim(p.base_unit), ''), 'Each')
      ) AS unit,
      COALESCE(inv.unit_cost, p.latest_price, 0)::numeric AS unit_cost,
      COALESCE(inv.current_quantity, 0)::numeric AS current_quantity,
      inv.last_counted_date
    FROM public.inventory inv
    LEFT JOIN public.products p
      ON p.id = inv.internal_product_id AND p.deleted_at IS NULL
    LEFT JOIN public.locations loc
      ON loc.id = inv.location_id
    WHERE inv.organization_id = v_org_id
      AND inv.deleted_at IS NULL
      AND public.tenant_scope_visible(inv.organization_id, inv.brand_id, inv.location_id, inv.deleted_at)
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR inv.location_id = ANY (p_location_ids)
      )
      AND (
        p_category_names IS NULL OR cardinality(p_category_names) = 0
        OR COALESCE(NULLIF(trim(COALESCE(p.category, inv.category)), ''), 'Uncategorized') = ANY (p_category_names)
      )
  ),
  -- Completed count lines: counted_data object keyed by inventory_id
  count_object_lines AS (
    SELECT
      cs.id AS session_id,
      cs.completed_at,
      (cs.completed_at AT TIME ZONE v_tz)::date AS count_date,
      sh.location_id,
      (e.key)::uuid AS inventory_id,
      COALESCE(
        NULLIF(e.value->>'counted_quantity', '')::numeric,
        NULLIF(e.value->>'count', '')::numeric,
        NULLIF(e.value->>'quantity', '')::numeric
      ) AS counted_qty,
      public.normalize_product_report_unit(COALESCE(NULLIF(trim(e.value->>'unit'), ''), 'Each')) AS unit
    FROM public.count_sessions cs
    JOIN public.count_sheets sh ON sh.id = cs.count_sheet_id
    CROSS JOIN LATERAL jsonb_each(
      CASE WHEN jsonb_typeof(cs.counted_data) = 'object' THEN cs.counted_data ELSE '{}'::jsonb END
    ) e
    WHERE cs.organization_id = v_org_id
      AND lower(cs.status) = 'completed'
      AND cs.completed_at IS NOT NULL
      AND e.key ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR sh.location_id = ANY (p_location_ids)
      )
  ),
  count_array_lines AS (
    SELECT
      cs.id AS session_id,
      cs.completed_at,
      (cs.completed_at AT TIME ZONE v_tz)::date AS count_date,
      sh.location_id,
      NULLIF(elem->>'inventory_id', '')::uuid AS inventory_id,
      COALESCE(
        NULLIF(elem->>'counted_quantity', '')::numeric,
        NULLIF(elem->>'count', '')::numeric,
        NULLIF(elem->>'quantity', '')::numeric
      ) AS counted_qty,
      public.normalize_product_report_unit(COALESCE(NULLIF(trim(elem->>'unit'), ''), 'Each')) AS unit
    FROM public.count_sessions cs
    JOIN public.count_sheets sh ON sh.id = cs.count_sheet_id
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE WHEN jsonb_typeof(cs.counted_data) = 'array' THEN cs.counted_data ELSE '[]'::jsonb END
    ) elem
    WHERE cs.organization_id = v_org_id
      AND lower(cs.status) = 'completed'
      AND cs.completed_at IS NOT NULL
      AND NULLIF(elem->>'inventory_id', '') IS NOT NULL
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR sh.location_id = ANY (p_location_ids)
      )
  ),
  count_lines AS (
    SELECT * FROM count_object_lines WHERE counted_qty IS NOT NULL
    UNION ALL
    SELECT * FROM count_array_lines WHERE counted_qty IS NOT NULL AND inventory_id IS NOT NULL
  ),
  opening_counts AS (
    SELECT DISTINCT ON (inventory_id)
      inventory_id,
      counted_qty AS opening_qty,
      count_date AS opening_count_date,
      session_id AS opening_session_id,
      unit AS opening_unit
    FROM count_lines
    WHERE count_date <= p_date_from
    ORDER BY inventory_id, count_date DESC, completed_at DESC
  ),
  closing_counts AS (
    SELECT DISTINCT ON (inventory_id)
      inventory_id,
      counted_qty AS closing_qty,
      count_date AS closing_count_date,
      session_id AS closing_session_id,
      unit AS closing_unit
    FROM count_lines
    WHERE count_date <= p_date_to
    ORDER BY inventory_id, count_date DESC, completed_at DESC
  ),
  period_movements AS (
    SELECT
      im.id,
      im.inventory_id,
      im.location_id,
      im.movement_type,
      im.quantity::numeric AS quantity,
      im.source_type,
      im.source_id,
      im.created_at,
      (im.created_at AT TIME ZONE v_tz)::date AS movement_date,
      CASE
        WHEN im.movement_type IN ('purchase_order', 'invoice_received') AND im.quantity > 0 THEN 'receipt'
        WHEN im.movement_type = 'transfer_in' OR (im.movement_type = 'transfer' AND im.quantity >= 0) THEN 'transfer_in'
        WHEN im.movement_type = 'transfer_out' OR (im.movement_type = 'transfer' AND im.quantity < 0) THEN 'transfer_out'
        WHEN im.movement_type IN ('wastage', 'spoilage') THEN 'waste'
        WHEN im.movement_type = 'manual_adjustment' THEN 'adjustment'
        WHEN im.movement_type IN ('count_variance', 'stock_count') THEN 'count_variance'
        WHEN im.movement_type IN ('recipe_consumption', 'sales_depletion', 'pos_adjustment') THEN 'pos_excluded'
        ELSE 'other'
      END AS class
    FROM public.inventory_movements im
    WHERE im.organization_id = v_org_id
      AND (im.created_at AT TIME ZONE v_tz)::date >= p_date_from
      AND (im.created_at AT TIME ZONE v_tz)::date <= p_date_to
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR im.location_id = ANY (p_location_ids)
      )
  ),
  movement_agg AS (
    SELECT
      inventory_id,
      round(sum(quantity) FILTER (WHERE class = 'receipt'), 4) AS received_qty,
      round(sum(quantity) FILTER (WHERE class = 'transfer_in'), 4) AS transfers_in_qty,
      round(sum(abs(quantity)) FILTER (WHERE class = 'transfer_out'), 4) AS transfers_out_qty,
      -- When opening/closing come from counts, exclude count_variance from adjustments (absorbed).
      round(sum(quantity) FILTER (WHERE class = 'adjustment'), 4) AS adjustment_qty,
      round(sum(abs(quantity)) FILTER (WHERE class = 'waste'), 4) AS waste_qty_from_movements,
      max(movement_date) AS last_movement_date
    FROM period_movements
    WHERE class <> 'pos_excluded'
    GROUP BY inventory_id
  ),
  waste_from_logs AS (
    SELECT
      inv.id AS inventory_id,
      round(sum(w.quantity)::numeric, 4) AS waste_qty,
      round(sum(COALESCE(w.value, w.quantity * COALESCE(inv.unit_cost, 0)))::numeric, 2) AS waste_value
    FROM public.wastage_logs w
    JOIN public.inventory inv
      ON inv.organization_id = w.organization_id
     AND inv.deleted_at IS NULL
     AND (
       (w.product_id IS NOT NULL AND inv.product_id = w.product_id)
       OR lower(inv.product_name) = lower(w.product_name)
     )
     AND (w.location_id IS NULL OR inv.location_id IS NOT DISTINCT FROM w.location_id)
    WHERE w.organization_id = v_org_id
      AND (w.created_at AT TIME ZONE v_tz)::date >= p_date_from
      AND (w.created_at AT TIME ZONE v_tz)::date <= p_date_to
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR w.location_id = ANY (p_location_ids)
        OR (w.location_id IS NULL AND inv.location_id = ANY (p_location_ids))
      )
    GROUP BY inv.id
  ),
  base AS (
    SELECT
      si.*,
      oc.opening_qty,
      oc.opening_count_date,
      oc.opening_unit,
      cc.closing_qty,
      cc.closing_count_date,
      cc.closing_unit,
      COALESCE(ma.received_qty, 0) AS received_qty,
      COALESCE(ma.transfers_in_qty, 0) AS transfers_in_qty,
      COALESCE(ma.transfers_out_qty, 0) AS transfers_out_qty,
      COALESCE(ma.adjustment_qty, 0) AS adjustment_qty,
      COALESCE(wl.waste_qty, ma.waste_qty_from_movements, 0) AS waste_qty,
      COALESCE(wl.waste_value, COALESCE(ma.waste_qty_from_movements, 0) * si.unit_cost) AS waste_value,
      ma.last_movement_date,
      CASE
        WHEN oc.opening_qty IS NULL OR cc.closing_qty IS NULL THEN 'not_calculable'
        WHEN oc.opening_unit IS DISTINCT FROM cc.closing_unit
          AND oc.opening_unit IS NOT NULL AND cc.closing_unit IS NOT NULL
          THEN 'not_calculable'
        ELSE 'calculable'
      END AS data_quality_status,
      CASE
        WHEN oc.opening_qty IS NULL OR cc.closing_qty IS NULL THEN NULL
        WHEN oc.opening_unit IS DISTINCT FROM cc.closing_unit
          AND oc.opening_unit IS NOT NULL AND cc.closing_unit IS NOT NULL
          THEN NULL
        ELSE round(
          oc.opening_qty
          + COALESCE(ma.received_qty, 0)
          + COALESCE(ma.transfers_in_qty, 0)
          - COALESCE(ma.transfers_out_qty, 0)
          + COALESCE(ma.adjustment_qty, 0)
          - cc.closing_qty
        , 4)
      END AS actual_usage
    FROM scoped_inventory si
    LEFT JOIN opening_counts oc ON oc.inventory_id = si.inventory_id
    LEFT JOIN closing_counts cc ON cc.inventory_id = si.inventory_id
    LEFT JOIN movement_agg ma ON ma.inventory_id = si.inventory_id
    LEFT JOIN waste_from_logs wl ON wl.inventory_id = si.inventory_id
  ),
  enriched AS (
    SELECT
      b.*,
      CASE WHEN b.actual_usage IS NULL THEN NULL
           ELSE round(b.actual_usage * b.unit_cost, 2)
      END AS usage_value,
      CASE WHEN b.opening_qty IS NULL THEN NULL
           ELSE round(b.opening_qty * b.unit_cost, 2)
      END AS opening_value,
      CASE WHEN b.closing_qty IS NULL THEN NULL
           ELSE round(b.closing_qty * b.unit_cost, 2)
      END AS closing_value,
      CASE WHEN b.opening_qty IS NULL OR b.closing_qty IS NULL THEN NULL
           ELSE round((b.closing_qty - b.opening_qty) * b.unit_cost, 2)
      END AS inventory_value_change,
      round(b.received_qty * b.unit_cost, 2) AS received_value,
      round(b.transfers_in_qty * b.unit_cost, 2) AS transfers_in_value,
      round(b.transfers_out_qty * b.unit_cost, 2) AS transfers_out_value,
      round(b.adjustment_qty * b.unit_cost, 2) AS adjustment_value
    FROM base b
  ),
  calculable AS (
    SELECT * FROM enriched WHERE data_quality_status = 'calculable' AND actual_usage IS NOT NULL
  ),
  abc_ranked AS (
    SELECT
      e.*,
      sum(COALESCE(e.usage_value, 0)) OVER (ORDER BY COALESCE(e.usage_value, 0) DESC, e.product) AS cum_usage_value,
      sum(COALESCE(e.usage_value, 0)) OVER () AS total_usage_value
    FROM calculable e
  ),
  with_abc AS (
    SELECT
      e.*,
      CASE
        WHEN e.data_quality_status <> 'calculable' OR e.usage_value IS NULL THEN 'n/a'
        WHEN ar.total_usage_value <= 0 THEN 'C'
        WHEN ar.cum_usage_value <= ar.total_usage_value * 0.80 THEN 'A'
        WHEN ar.cum_usage_value <= ar.total_usage_value * 0.95 THEN 'B'
        ELSE 'C'
      END AS abc_class
    FROM enriched e
    LEFT JOIN abc_ranked ar ON ar.inventory_id = e.inventory_id
  ),
  summary AS (
    SELECT
      round(sum(opening_value)::numeric, 2) AS opening_inventory_value,
      round(sum(closing_value)::numeric, 2) AS closing_inventory_value,
      round(sum(received_value)::numeric, 2) AS inventory_received,
      round(sum(usage_value)::numeric, 2) AS actual_inventory_usage,
      round(sum(waste_value)::numeric, 2) AS waste_value,
      round(sum(transfers_in_value)::numeric, 2) AS transfers_in,
      round(sum(transfers_out_value)::numeric, 2) AS transfers_out,
      round(sum(adjustment_value)::numeric, 2) AS inventory_adjustments,
      round(sum(inventory_value_change)::numeric, 2) AS inventory_value_change,
      count(*) FILTER (WHERE opening_qty IS NULL OR closing_qty IS NULL OR last_counted_date IS NULL)::int AS uncounted_or_missing,
      count(*)::int AS total_products,
      count(*) FILTER (WHERE data_quality_status = 'calculable')::int AS calculable_products
    FROM with_abc
  ),
  highest_usage_category AS (
    SELECT jsonb_build_object(
      'category', category,
      'usageValue', round(sum(usage_value)::numeric, 2),
      'usageQty', round(sum(actual_usage)::numeric, 4)
    ) AS obj
    FROM calculable
    GROUP BY category
    ORDER BY sum(usage_value) DESC NULLS LAST
    LIMIT 1
  ),
  highest_waste_product AS (
    SELECT jsonb_build_object(
      'product', product,
      'category', category,
      'wasteValue', waste_value,
      'wasteQty', waste_qty
    ) AS obj
    FROM with_abc
    WHERE waste_qty > 0
    ORDER BY waste_value DESC NULLS LAST
    LIMIT 1
  ),
  waterfall AS (
    SELECT jsonb_build_array(
      jsonb_build_object('step', 'Opening', 'value', (SELECT opening_inventory_value FROM summary)),
      jsonb_build_object('step', 'Receipts', 'value', (SELECT inventory_received FROM summary)),
      jsonb_build_object('step', 'Transfers In', 'value', (SELECT transfers_in FROM summary)),
      jsonb_build_object('step', 'Transfers Out', 'value', -abs(COALESCE((SELECT transfers_out FROM summary), 0))),
      jsonb_build_object('step', 'Adjustments', 'value', (SELECT inventory_adjustments FROM summary)),
      jsonb_build_object('step', 'Closing', 'value', -abs(COALESCE((SELECT closing_inventory_value FROM summary), 0))),
      jsonb_build_object('step', 'Actual Usage', 'value', (SELECT actual_inventory_usage FROM summary))
    ) AS arr
  ),
  usage_by_category AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'category', category,
        'usageValue', usage_value,
        'usageQty', usage_qty,
        'wasteValue', waste_value,
        'productCount', product_count
      )
      ORDER BY usage_value DESC NULLS LAST
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT
        category,
        round(sum(usage_value)::numeric, 2) AS usage_value,
        round(sum(actual_usage)::numeric, 4) AS usage_qty,
        round(sum(waste_value)::numeric, 2) AS waste_value,
        count(*)::int AS product_count
      FROM calculable
      GROUP BY category
    ) c
  ),
  value_trend AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'bucket', bucket,
        'receivedValue', received_value,
        'usageProxyValue', usage_proxy_value,
        'wasteValue', waste_value
      )
      ORDER BY bucket
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT
        to_char(date_trunc('week', m.created_at AT TIME ZONE v_tz), 'YYYY-MM-DD') AS bucket,
        round(sum(CASE WHEN m.class = 'receipt' THEN m.quantity * COALESCE(si.unit_cost, 0) ELSE 0 END)::numeric, 2) AS received_value,
        round(sum(CASE WHEN m.class = 'transfer_out' THEN abs(m.quantity) * COALESCE(si.unit_cost, 0) ELSE 0 END)::numeric, 2) AS usage_proxy_value,
        round(sum(CASE WHEN m.class = 'waste' THEN abs(m.quantity) * COALESCE(si.unit_cost, 0) ELSE 0 END)::numeric, 2) AS waste_value
      FROM period_movements m
      LEFT JOIN scoped_inventory si ON si.inventory_id = m.inventory_id
      WHERE m.class <> 'pos_excluded'
      GROUP BY 1
    ) t
  ),
  waste_trend AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'bucket', bucket,
        'wasteValue', waste_value,
        'wasteQty', waste_qty
      )
      ORDER BY bucket
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT
        ((created_at AT TIME ZONE v_tz)::date)::text AS bucket,
        round(COALESCE(sum(value), 0)::numeric, 2) AS waste_value,
        round(COALESCE(sum(quantity), 0)::numeric, 4) AS waste_qty
      FROM public.wastage_logs
      WHERE organization_id = v_org_id
        AND public.tenant_scope_visible(organization_id, brand_id, location_id)
        AND (created_at AT TIME ZONE v_tz)::date >= p_date_from
        AND (created_at AT TIME ZONE v_tz)::date <= p_date_to
        AND (
          p_location_ids IS NULL OR cardinality(p_location_ids) = 0
          OR location_id = ANY (p_location_ids)
        )
      GROUP BY 1
    ) w
  ),
  product_ranking AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'product', product,
        'productId', product_id,
        'inventoryId', inventory_id,
        'category', category,
        'location', location_name,
        'actualUsage', actual_usage,
        'usageValue', usage_value,
        'wasteValue', waste_value
      )
      ORDER BY usage_value DESC NULLS LAST
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT * FROM calculable
      ORDER BY usage_value DESC NULLS LAST
      LIMIT 20
    ) top_u
  ),
  location_comparison AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'location', location_name,
        'locationId', location_id,
        'openingValue', opening_value,
        'closingValue', closing_value,
        'usageValue', usage_value,
        'wasteValue', waste_value,
        'receivedValue', received_value
      )
      ORDER BY usage_value DESC NULLS LAST
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT
        location_id,
        location_name,
        round(sum(opening_value)::numeric, 2) AS opening_value,
        round(sum(closing_value)::numeric, 2) AS closing_value,
        round(sum(usage_value)::numeric, 2) AS usage_value,
        round(sum(waste_value)::numeric, 2) AS waste_value,
        round(sum(received_value)::numeric, 2) AS received_value
      FROM with_abc
      GROUP BY location_id, location_name
    ) loc
  ),
  heatmap AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'category', category,
        'location', location_name,
        'usageValue', usage_value,
        'wasteValue', waste_value
      )
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT category, location_name,
             round(sum(usage_value)::numeric, 2) AS usage_value,
             round(sum(waste_value)::numeric, 2) AS waste_value
      FROM with_abc
      GROUP BY category, location_name
    ) h
  ),
  abc AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'class', abc_class,
        'productCount', product_count,
        'usageValue', usage_value
      )
      ORDER BY abc_class
    ), '[]'::jsonb) AS arr
    FROM (
      SELECT abc_class,
             count(*)::int AS product_count,
             round(sum(COALESCE(usage_value, 0))::numeric, 2) AS usage_value
      FROM with_abc
      WHERE abc_class <> 'n/a'
      GROUP BY abc_class
    ) a
  ),
  insights AS (
    SELECT COALESCE(jsonb_agg(ins ORDER BY (ins->>'impact')::numeric DESC), '[]'::jsonb) AS arr
    FROM (
      SELECT jsonb_build_object(
        'id', 'usage-total',
        'impact', abs(COALESCE(s.actual_inventory_usage, 0)),
        'text', format('Calculable actual inventory usage value is $%s across %s products.',
          to_char(COALESCE(s.actual_inventory_usage, 0), 'FM999,999,990'),
          s.calculable_products)
      ) AS ins
      FROM summary s
      UNION ALL
      SELECT jsonb_build_object(
        'id', 'waste',
        'impact', abs(COALESCE(s.waste_value, 0)),
        'text', format('Waste value in period is $%s (reported separately; not added into Actual Usage).',
          to_char(COALESCE(s.waste_value, 0), 'FM999,999,990'))
      )
      FROM summary s
      WHERE COALESCE(s.waste_value, 0) > 0
      UNION ALL
      SELECT jsonb_build_object(
        'id', 'uncounted',
        'impact', s.uncounted_or_missing,
        'text', format('%s inventory items are missing opening/closing counts (Actual Usage = Not Calculable).',
          s.uncounted_or_missing)
      )
      FROM summary s
      WHERE s.uncounted_or_missing > 0
      UNION ALL
      SELECT jsonb_build_object(
        'id', 'top-cat',
        'impact', COALESCE((SELECT (obj->>'usageValue')::numeric FROM highest_usage_category), 0),
        'text', format('%s is the highest-usage category.',
          (SELECT obj->>'category' FROM highest_usage_category))
      )
      WHERE EXISTS (SELECT 1 FROM highest_usage_category WHERE obj IS NOT NULL)
    ) x
  ),
  filter_options AS (
    SELECT
      COALESCE((
        SELECT jsonb_agg(DISTINCT category ORDER BY category)
        FROM with_abc WHERE category IS NOT NULL
      ), '[]'::jsonb) AS categories,
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object('id', location_id, 'name', location_name) ORDER BY location_name)
        FROM (
          SELECT DISTINCT location_id, location_name FROM with_abc WHERE location_id IS NOT NULL
        ) l
      ), '[]'::jsonb) AS locations
  )
  SELECT jsonb_build_object(
    'summary', jsonb_build_object(
      'openingInventoryValue', s.opening_inventory_value,
      'closingInventoryValue', s.closing_inventory_value,
      'inventoryReceived', s.inventory_received,
      'actualInventoryUsage', s.actual_inventory_usage,
      'wasteValue', s.waste_value,
      'transfersIn', s.transfers_in,
      'transfersOut', s.transfers_out,
      'inventoryAdjustments', s.inventory_adjustments,
      'highestUsageCategory', (SELECT obj FROM highest_usage_category),
      'highestWasteProduct', (SELECT obj FROM highest_waste_product),
      'inventoryValueChange', s.inventory_value_change,
      'uncountedOrMissing', s.uncounted_or_missing,
      'totalProducts', s.total_products,
      'calculableProducts', s.calculable_products
    ),
    'waterfall', (SELECT arr FROM waterfall),
    'usageByCategory', (SELECT arr FROM usage_by_category),
    'valueTrend', (SELECT arr FROM value_trend),
    'wasteTrend', (SELECT arr FROM waste_trend),
    'productRanking', (SELECT arr FROM product_ranking),
    'locationComparison', (SELECT arr FROM location_comparison),
    'heatmap', (SELECT arr FROM heatmap),
    'abc', (SELECT arr FROM abc),
    'tableRows', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'inventoryId', w.inventory_id,
          'productId', w.product_id,
          'product', w.product,
          'category', w.category,
          'location', w.location_name,
          'locationId', w.location_id,
          'openingQuantity', w.opening_qty,
          'receivedQuantity', w.received_qty,
          'transfersIn', w.transfers_in_qty,
          'transfersOut', w.transfers_out_qty,
          'wasteQuantity', w.waste_qty,
          'adjustmentQuantity', w.adjustment_qty,
          'closingQuantity', w.closing_qty,
          'actualUsage', w.actual_usage,
          'unit', w.unit,
          'unitCost', w.unit_cost,
          'usageValue', w.usage_value,
          'wasteValue', w.waste_value,
          'countDate', w.closing_count_date,
          'lastMovementDate', w.last_movement_date,
          'dataQualityStatus', w.data_quality_status,
          'abcClass', w.abc_class
        )
        ORDER BY COALESCE(w.usage_value, 0) DESC, w.product
      )
      FROM with_abc w
    ), '[]'::jsonb),
    'insights', (SELECT arr FROM insights),
    'metadata', jsonb_build_object(
      'currency', 'USD',
      'timezone', v_tz,
      'dataFreshness', to_char(now() AT TIME ZONE v_tz, 'YYYY-MM-DD HH24:MI'),
      'usageDefinition', 'Actual Usage = Opening + Receipts + Transfers In - Transfers Out + Adjustments(signed) - Closing. Waste is reported separately and not added into Actual Usage. POS/theoretical movements are excluded. Official usage requires opening and closing completed counts.',
      'filterOptions', jsonb_build_object(
        'categories', (SELECT categories FROM filter_options),
        'locations', (SELECT locations FROM filter_options)
      )
    )
  )
  INTO v_result
  FROM summary s;

  RETURN v_result;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_inventory_usage_report(
  uuid, uuid[], date, date, text[], text
) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.get_inventory_usage_drilldown(
  p_organization_id uuid DEFAULT NULL,
  p_inventory_id uuid DEFAULT NULL,
  p_product_id uuid DEFAULT NULL,
  p_location_ids uuid[] DEFAULT NULL,
  p_date_from date DEFAULT NULL,
  p_date_to date DEFAULT NULL,
  p_timezone text DEFAULT 'UTC'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_tz text := COALESCE(NULLIF(trim(p_timezone), ''), 'UTC');
  v_inv_id uuid := p_inventory_id;
  v_result jsonb;
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;
  IF p_date_from IS NULL OR p_date_to IS NULL THEN
    RAISE EXCEPTION 'date_from and date_to are required';
  END IF;
  IF v_inv_id IS NULL AND p_product_id IS NULL THEN
    RAISE EXCEPTION 'inventory_id or product_id is required';
  END IF;

  IF v_inv_id IS NULL THEN
    SELECT id INTO v_inv_id
    FROM public.inventory
    WHERE organization_id = v_org_id
      AND deleted_at IS NULL
      AND internal_product_id = p_product_id
      AND (
        p_location_ids IS NULL OR cardinality(p_location_ids) = 0
        OR location_id = ANY (p_location_ids)
      )
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  WITH inv AS (
    SELECT
      i.*,
      COALESCE(p.name, i.product_name) AS product,
      COALESCE(NULLIF(trim(COALESCE(p.category, i.category)), ''), 'Uncategorized') AS category,
      COALESCE(loc.name, i.location, 'Unknown') AS location_name,
      public.normalize_product_report_unit(
        COALESCE(NULLIF(trim(i.current_unit), ''), NULLIF(trim(p.report_by_unit), ''), 'Each')
      ) AS unit,
      COALESCE(i.unit_cost, p.latest_price, 0)::numeric AS unit_cost
    FROM public.inventory i
    LEFT JOIN public.products p ON p.id = i.internal_product_id
    LEFT JOIN public.locations loc ON loc.id = i.location_id
    WHERE i.id = v_inv_id
      AND i.organization_id = v_org_id
      AND i.deleted_at IS NULL
  ),
  counts AS (
    SELECT
      cs.id AS session_id,
      (cs.completed_at AT TIME ZONE v_tz)::date AS count_date,
      cs.completed_at,
      COALESCE(
        NULLIF(cs.counted_data->(v_inv_id::text)->>'counted_quantity', '')::numeric,
        NULLIF(cs.counted_data->(v_inv_id::text)->>'count', '')::numeric
      ) AS counted_qty,
      cs.status
    FROM public.count_sessions cs
    JOIN public.count_sheets sh ON sh.id = cs.count_sheet_id
    WHERE cs.organization_id = v_org_id
      AND lower(cs.status) = 'completed'
      AND cs.counted_data ? (v_inv_id::text)
      AND (cs.completed_at AT TIME ZONE v_tz)::date >= p_date_from - 90
      AND (cs.completed_at AT TIME ZONE v_tz)::date <= p_date_to
    ORDER BY cs.completed_at DESC
    LIMIT 50
  ),
  movements AS (
    SELECT
      im.id,
      im.movement_type,
      im.quantity,
      im.source_type,
      im.source_id,
      im.created_at,
      (im.created_at AT TIME ZONE v_tz)::date AS movement_date,
      CASE
        WHEN im.movement_type IN ('purchase_order', 'invoice_received') THEN 'receipt'
        WHEN im.movement_type IN ('transfer_in') OR (im.movement_type = 'transfer' AND im.quantity >= 0) THEN 'transfer_in'
        WHEN im.movement_type IN ('transfer_out') OR (im.movement_type = 'transfer' AND im.quantity < 0) THEN 'transfer_out'
        WHEN im.movement_type IN ('wastage', 'spoilage') THEN 'waste'
        WHEN im.movement_type = 'manual_adjustment' THEN 'adjustment'
        WHEN im.movement_type IN ('count_variance', 'stock_count') THEN 'count_variance'
        WHEN im.movement_type IN ('recipe_consumption', 'sales_depletion', 'pos_adjustment') THEN 'pos_excluded'
        ELSE 'other'
      END AS class
    FROM public.inventory_movements im
    WHERE im.organization_id = v_org_id
      AND im.inventory_id = v_inv_id
      AND (im.created_at AT TIME ZONE v_tz)::date >= p_date_from
      AND (im.created_at AT TIME ZONE v_tz)::date <= p_date_to
  ),
  waste AS (
    SELECT
      w.id,
      w.quantity,
      w.unit,
      w.value,
      w.reason,
      w.created_at,
      (w.created_at AT TIME ZONE v_tz)::date AS waste_date
    FROM public.wastage_logs w
    JOIN inv ON true
    WHERE w.organization_id = v_org_id
      AND (
        (w.product_id IS NOT NULL AND w.product_id = inv.product_id)
        OR lower(w.product_name) = lower(inv.product_name)
      )
      AND (w.created_at AT TIME ZONE v_tz)::date >= p_date_from
      AND (w.created_at AT TIME ZONE v_tz)::date <= p_date_to
    ORDER BY w.created_at DESC
    LIMIT 50
  ),
  usage_trend AS (
    SELECT
      movement_date AS bucket,
      round(sum(CASE WHEN class = 'receipt' THEN quantity ELSE 0 END)::numeric, 4) AS received,
      round(sum(CASE WHEN class = 'transfer_in' THEN quantity ELSE 0 END)::numeric, 4) AS transfers_in,
      round(sum(CASE WHEN class = 'transfer_out' THEN abs(quantity) ELSE 0 END)::numeric, 4) AS transfers_out,
      round(sum(CASE WHEN class = 'waste' THEN abs(quantity) ELSE 0 END)::numeric, 4) AS waste_qty,
      round(sum(CASE WHEN class = 'adjustment' THEN quantity ELSE 0 END)::numeric, 4) AS adjustments
    FROM movements
    WHERE class <> 'pos_excluded'
    GROUP BY movement_date
    ORDER BY movement_date
  ),
  location_comp AS (
    SELECT
      COALESCE(loc.name, i.location, 'Unknown') AS location,
      i.location_id,
      i.current_quantity,
      COALESCE(i.unit_cost, 0) AS unit_cost,
      round(i.current_quantity * COALESCE(i.unit_cost, 0), 2) AS value
    FROM public.inventory i
    LEFT JOIN public.locations loc ON loc.id = i.location_id
    WHERE i.organization_id = v_org_id
      AND i.deleted_at IS NULL
      AND (
        (SELECT product_id FROM inv) IS NOT NULL AND i.internal_product_id = (SELECT product_id FROM inv)
        OR lower(i.product_name) = lower((SELECT product FROM inv))
      )
  )
  SELECT jsonb_build_object(
    'inventoryId', v_inv_id,
    'summary', jsonb_build_object(
      'product', (SELECT product FROM inv),
      'category', (SELECT category FROM inv),
      'location', (SELECT location_name FROM inv),
      'unit', (SELECT unit FROM inv),
      'unitCost', (SELECT unit_cost FROM inv),
      'currentQuantity', (SELECT current_quantity FROM inv),
      'lastCountedDate', (SELECT last_counted_date FROM inv)
    ),
    'countHistory', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'sessionId', session_id,
        'date', count_date,
        'countedQuantity', counted_qty,
        'status', status
      ) ORDER BY completed_at DESC)
      FROM counts
    ), '[]'::jsonb),
    'receiptHistory', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'movementId', id,
        'date', movement_date,
        'quantity', quantity,
        'sourceType', source_type,
        'sourceId', source_id,
        'movementType', movement_type
      ) ORDER BY created_at DESC)
      FROM movements WHERE class = 'receipt'
    ), '[]'::jsonb),
    'wasteHistory', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', id,
        'date', waste_date,
        'quantity', quantity,
        'unit', unit,
        'value', value,
        'reason', reason
      ) ORDER BY created_at DESC)
      FROM waste
    ), '[]'::jsonb),
    'transferHistory', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'movementId', id,
        'date', movement_date,
        'quantity', quantity,
        'class', class,
        'sourceId', source_id,
        'movementType', movement_type
      ) ORDER BY created_at DESC)
      FROM movements WHERE class IN ('transfer_in', 'transfer_out')
    ), '[]'::jsonb),
    'adjustmentHistory', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'movementId', id,
        'date', movement_date,
        'quantity', quantity,
        'sourceType', source_type,
        'movementType', movement_type
      ) ORDER BY created_at DESC)
      FROM movements WHERE class IN ('adjustment', 'count_variance')
    ), '[]'::jsonb),
    'usageTrend', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'bucket', bucket,
        'received', received,
        'transfersIn', transfers_in,
        'transfersOut', transfers_out,
        'wasteQty', waste_qty,
        'adjustments', adjustments
      ) ORDER BY bucket)
      FROM usage_trend
    ), '[]'::jsonb),
    'locationComparison', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'location', location,
        'locationId', location_id,
        'currentQuantity', current_quantity,
        'unitCost', unit_cost,
        'value', value
      ))
      FROM location_comp
    ), '[]'::jsonb),
    'normalization', jsonb_build_object(
      'reportUnit', (SELECT unit FROM inv),
      'formula', 'Actual Usage = Opening + Receipts + Transfers In - Transfers Out + Adjustments(signed) - Closing',
      'wasteRule', 'Waste is reported separately and is not added into Actual Usage',
      'posExcluded', true
    )
  )
  INTO v_result;

  RETURN v_result;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_inventory_usage_drilldown(
  uuid, uuid, uuid, uuid[], date, date, text
) TO authenticated, service_role;

CREATE INDEX IF NOT EXISTS idx_inventory_movements_org_created
  ON public.inventory_movements (organization_id, created_at);

CREATE INDEX IF NOT EXISTS idx_inventory_movements_inventory_created
  ON public.inventory_movements (inventory_id, created_at);

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260721120657_repair_count_sessions_stock_count_columns.sql
-- ==========================================================================

BEGIN;

-- Repair production schemas where the stock count persistence migration was
-- marked applied before these columns existed.
ALTER TABLE public.count_sessions
  ADD COLUMN IF NOT EXISTS location_id uuid,
  ADD COLUMN IF NOT EXISTS brand_id uuid,
  ADD COLUMN IF NOT EXISTS scope_key text DEFAULT 'all',
  ADD COLUMN IF NOT EXISTS type text DEFAULT 'Inventory',
  ADD COLUMN IF NOT EXISTS count_date date DEFAULT CURRENT_DATE,
  ADD COLUMN IF NOT EXISTS items jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS total_value numeric NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS item_count integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS saved_at timestamptz DEFAULT now(),
  ADD COLUMN IF NOT EXISTS closed_at timestamptz,
  ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT now(),
  ADD COLUMN IF NOT EXISTS deleted_at timestamptz,
  ADD COLUMN IF NOT EXISTS created_by uuid,
  ADD COLUMN IF NOT EXISTS notes text;

CREATE INDEX IF NOT EXISTS idx_count_sessions_org_location_date
  ON public.count_sessions (organization_id, location_id, count_date DESC);

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260721124500_repair_count_sessions_rls_for_stock_counts.sql
-- ==========================================================================

BEGIN;

-- Stock Counts can be saved without a count sheet ("All Inventory" or category
-- scopes). The older parent-inherited count_sessions policy only checked
-- count_sheet_id, so those rows failed RLS when count_sheet_id was NULL.

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'count_sessions'
      AND policyname = 'count_sessions_stock_count_scope_select'
  ) THEN
    CREATE POLICY count_sessions_stock_count_scope_select
      ON public.count_sessions
      FOR SELECT
      USING (
        count_sheet_id IS NULL
        AND public.tenant_scope_visible(organization_id, brand_id, location_id, deleted_at)
      );
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'count_sessions'
      AND policyname = 'count_sessions_stock_count_scope_insert'
  ) THEN
    CREATE POLICY count_sessions_stock_count_scope_insert
      ON public.count_sessions
      FOR INSERT
      WITH CHECK (
        count_sheet_id IS NULL
        AND public.tenant_scope_writable(organization_id, brand_id, location_id, NULL, true)
      );
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'count_sessions'
      AND policyname = 'count_sessions_stock_count_scope_update'
  ) THEN
    CREATE POLICY count_sessions_stock_count_scope_update
      ON public.count_sessions
      FOR UPDATE
      USING (
        count_sheet_id IS NULL
        AND public.tenant_scope_writable(organization_id, brand_id, location_id, deleted_at, true)
      )
      WITH CHECK (
        count_sheet_id IS NULL
        AND public.tenant_scope_writable(organization_id, brand_id, location_id, deleted_at, true)
      );
  END IF;
END $$;

COMMIT;

