-- ==========================================================================
-- Source: 20260722000001_accept_invitation_upserts_profile.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.accept_invitation(p_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_invite record;
  v_user_id uuid;
  v_user_email text;
  v_user_name text;
  v_role text;
  v_tenant_id uuid;
  v_business_verification_required boolean := true;
  v_coupon_code text;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT
    email,
    COALESCE(raw_user_meta_data->>'full_name', raw_user_meta_data->>'name', split_part(email, '@', 1))
  INTO v_user_email, v_user_name
  FROM auth.users
  WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND closed_at IS NULL
    AND lower(email) = lower(v_user_email)
    AND (expires_at IS NULL OR expires_at > now())
  FOR UPDATE;

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  v_role := public.normalize_app_role(v_invite.role);
  v_tenant_id := v_invite.tenant_id;
  v_business_verification_required := COALESCE((v_invite.metadata->>'business_verification_required')::boolean, true);
  v_coupon_code := COALESCE(v_invite.metadata->>'coupon_code', v_invite.metadata#>>'{coupon,code}');

  IF v_tenant_id IS NULL AND v_invite.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO v_tenant_id FROM public.organizations WHERE id = v_invite.organization_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NULL THEN
    INSERT INTO public.tenants (name, owner_id, metadata)
    VALUES (
      COALESCE(v_invite.metadata->>'tenant_name', split_part(v_user_email, '@', 1), 'Tenant'),
      v_user_id,
      jsonb_build_object(
        'source', 'accept_invitation',
        'invitation_id', v_invite.id,
        'invited_email', v_invite.email,
        'business_verification_required', v_business_verification_required,
        'coupon_code', v_coupon_code
      )
    )
    RETURNING id INTO v_tenant_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NOT NULL THEN
    INSERT INTO public.tenant_members (tenant_id, user_id, role)
    VALUES (v_tenant_id, v_user_id, 'tenant_super_admin')
    ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    UPDATE public.tenants
    SET owner_id = COALESCE(owner_id, v_user_id),
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
          'business_verification_required', v_business_verification_required,
          'coupon_code', v_coupon_code
        ),
        updated_at = now()
    WHERE id = v_tenant_id;
  END IF;

  IF v_invite.organization_id IS NOT NULL THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_invite.organization_id, v_user_id, v_role)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.brand_id IS NOT NULL THEN
    INSERT INTO public.brand_members (brand_id, user_id, role)
    VALUES (v_invite.brand_id, v_user_id, v_role)
    ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.location_id IS NOT NULL THEN
    INSERT INTO public.location_members (location_id, user_id, role)
    VALUES (v_invite.location_id, v_user_id, v_role)
    ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  PERFORM set_config('app.trusted_profile_write', 'on', true);

  INSERT INTO public.profiles (
    id,
    email,
    full_name,
    tenant_id,
    role,
    organization_id,
    brand_id,
    location_id,
    coupon_code,
    payment_verified,
    business_verification_status,
    onboarding_status,
    onboarding_current_step,
    is_active
  )
  VALUES (
    v_user_id,
    v_user_email,
    COALESCE(v_user_name, split_part(v_user_email, '@', 1), 'User'),
    v_tenant_id,
    v_role,
    v_invite.organization_id,
    v_invite.brand_id,
    v_invite.location_id,
    v_coupon_code,
    false,
    CASE
      WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'verified'
      ELSE 'not_started'
    END,
    'not_started',
    CASE
      WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'hierarchy_setup'
      ELSE 'business_verification'
    END,
    true
  )
  ON CONFLICT (id) DO UPDATE
  SET email = EXCLUDED.email,
      full_name = COALESCE(NULLIF(public.profiles.full_name, ''), EXCLUDED.full_name),
      tenant_id = COALESCE(EXCLUDED.tenant_id, public.profiles.tenant_id),
      role = EXCLUDED.role,
      organization_id = COALESCE(EXCLUDED.organization_id, public.profiles.organization_id),
      brand_id = COALESCE(EXCLUDED.brand_id, public.profiles.brand_id),
      location_id = COALESCE(EXCLUDED.location_id, public.profiles.location_id),
      coupon_code = COALESCE(EXCLUDED.coupon_code, public.profiles.coupon_code),
      business_verification_status = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'verified'
        ELSE public.profiles.business_verification_status
      END,
      onboarding_current_step = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'hierarchy_setup'
        ELSE public.profiles.onboarding_current_step
      END,
      is_active = true,
      updated_at = now();

  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id,
      role = v_role,
      tenant_id = COALESCE(tenant_id, v_tenant_id),
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
        'business_verification_required', v_business_verification_required,
        'coupon_code', v_coupon_code
      )
  WHERE id = v_invite.id
    AND accepted_at IS NULL
    AND closed_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', v_role,
    'tenant_id', COALESCE(v_tenant_id::text, ''),
    'organization_id', COALESCE(v_invite.organization_id::text, ''),
    'business_verification_required', v_business_verification_required,
    'coupon_code', COALESCE(v_coupon_code, '')
  )
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'role', v_role,
    'tenant_id', v_tenant_id,
    'organization_id', v_invite.organization_id,
    'business_verification_required', v_business_verification_required,
    'coupon_code', v_coupon_code
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.accept_invitation(text) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260722000002_notification_delivery_preferences.sql
-- ==========================================================================

-- Store per-user delivery preferences for the Notifications module.
-- Preferences are scoped by module key so the UI can show only modules the user can access.

CREATE TABLE IF NOT EXISTS public.notification_delivery_preferences (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  organization_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE,
  module_key text NOT NULL,
  in_app_enabled boolean NOT NULL DEFAULT true,
  email_enabled boolean NOT NULL DEFAULT false,
  phone_enabled boolean NOT NULL DEFAULT false,
  critical_only boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT notification_delivery_preferences_module_key_check CHECK (module_key ~ '^[a-z0-9_]+$'),
  CONSTRAINT notification_delivery_preferences_user_module_unique UNIQUE (user_id, module_key)
);

CREATE INDEX IF NOT EXISTS idx_notification_delivery_preferences_user_id
  ON public.notification_delivery_preferences (user_id);

CREATE INDEX IF NOT EXISTS idx_notification_delivery_preferences_organization_id
  ON public.notification_delivery_preferences (organization_id);

DROP TRIGGER IF EXISTS set_notification_delivery_preferences_updated_at ON public.notification_delivery_preferences;
CREATE TRIGGER set_notification_delivery_preferences_updated_at
BEFORE UPDATE ON public.notification_delivery_preferences
FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.notification_delivery_preferences ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notification_delivery_preferences FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS notification_delivery_preferences_select_own ON public.notification_delivery_preferences;
CREATE POLICY notification_delivery_preferences_select_own
ON public.notification_delivery_preferences
FOR SELECT
TO authenticated
USING (auth.uid() = user_id);

DROP POLICY IF EXISTS notification_delivery_preferences_insert_own ON public.notification_delivery_preferences;
CREATE POLICY notification_delivery_preferences_insert_own
ON public.notification_delivery_preferences
FOR INSERT
TO authenticated
WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS notification_delivery_preferences_update_own ON public.notification_delivery_preferences;
CREATE POLICY notification_delivery_preferences_update_own
ON public.notification_delivery_preferences
FOR UPDATE
TO authenticated
USING (auth.uid() = user_id)
WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS notification_delivery_preferences_delete_own ON public.notification_delivery_preferences;
CREATE POLICY notification_delivery_preferences_delete_own
ON public.notification_delivery_preferences
FOR DELETE
TO authenticated
USING (auth.uid() = user_id);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.notification_delivery_preferences TO authenticated;
GRANT ALL ON public.notification_delivery_preferences TO service_role;

-- ==========================================================================
-- Source: 20260722000003_fix_organization_plan_default_after_plan_catalog_cleanup.sql
-- ==========================================================================

-- Keep organization creation aligned with the current three-plan catalog.
-- The old schema defaulted organizations.plan_id to 'free', but the current catalog
-- only contains starter, starter-ai, and advanced. During hierarchy approval the
-- organization row is inserted before pending_onboarding_plan_id is applied, so the
-- stale default can violate organizations_plan_id_fkey.

INSERT INTO public.plans (id, name, description, price_monthly, features, is_active)
VALUES
  (
    'starter',
    'Starter',
    'Core location operations for one restaurant, store, or service location.',
    149.00,
    '["invoices", "products", "vendors", "payments", "inventory", "recipes", "analytics"]'::jsonb,
    true
  ),
  (
    'starter-ai',
    'Starter + AI',
    'Starter modules plus AI-assisted operating intelligence.',
    249.00,
    '["starter_modules", "ai"]'::jsonb,
    false
  ),
  (
    'advanced',
    'Advanced modules',
    'Expanded controls for larger teams and advanced operating workflows.',
    349.00,
    '["starter_ai", "advanced_modules"]'::jsonb,
    false
  )
ON CONFLICT (id) DO UPDATE
SET name = EXCLUDED.name,
    description = EXCLUDED.description,
    price_monthly = EXCLUDED.price_monthly,
    features = EXCLUDED.features,
    is_active = EXCLUDED.is_active;

UPDATE public.organizations o
SET plan_id = 'starter'
WHERE o.plan_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM public.plans p WHERE p.id = o.plan_id
  );

UPDATE public.profiles p
SET pending_onboarding_plan_id = 'starter',
    updated_at = now()
WHERE p.pending_onboarding_plan_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM public.plans plan WHERE plan.id = p.pending_onboarding_plan_id
  );

ALTER TABLE public.organizations
  ALTER COLUMN plan_id SET DEFAULT 'starter';

-- ==========================================================================
-- Source: 20260722000004_restore_dim_date_for_invoice_fact_sync.sql
-- ==========================================================================

-- Restore the shared calendar dimension after data cleanup and make invoice fact
-- syncing resilient to missing date rows.

CREATE OR REPLACE FUNCTION public.ensure_dim_date(p_date date)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_date_key integer;
BEGIN
  IF p_date IS NULL THEN
    RETURN NULL;
  END IF;

  v_date_key := to_char(p_date, 'YYYYMMDD')::integer;

  INSERT INTO public.dim_date (
    date_key,
    full_date,
    day_of_week,
    day_name,
    day_of_month,
    day_of_year,
    week_of_year,
    month_number,
    month_name,
    quarter,
    year,
    is_weekend,
    is_month_end,
    fiscal_quarter
  ) VALUES (
    v_date_key,
    p_date,
    extract(dow from p_date)::smallint,
    trim(to_char(p_date, 'Day')),
    extract(day from p_date)::smallint,
    extract(doy from p_date)::smallint,
    extract(week from p_date)::smallint,
    extract(month from p_date)::smallint,
    trim(to_char(p_date, 'Month')),
    extract(quarter from p_date)::smallint,
    extract(year from p_date)::smallint,
    extract(dow from p_date) in (0, 6),
    p_date = (date_trunc('month', p_date)::date + interval '1 month - 1 day')::date,
    'FY' || extract(year from p_date)::text || '-Q' || extract(quarter from p_date)::text
  )
  ON CONFLICT (date_key) DO NOTHING;

  RETURN v_date_key;
END;
$$;

INSERT INTO public.dim_date (
  date_key,
  full_date,
  day_of_week,
  day_name,
  day_of_month,
  day_of_year,
  week_of_year,
  month_number,
  month_name,
  quarter,
  year,
  is_weekend,
  is_month_end,
  fiscal_quarter
)
SELECT
  to_char(d::date, 'YYYYMMDD')::integer,
  d::date,
  extract(dow from d)::smallint,
  trim(to_char(d, 'Day')),
  extract(day from d)::smallint,
  extract(doy from d)::smallint,
  extract(week from d)::smallint,
  extract(month from d)::smallint,
  trim(to_char(d, 'Month')),
  extract(quarter from d)::smallint,
  extract(year from d)::smallint,
  extract(dow from d) in (0, 6),
  d::date = (date_trunc('month', d)::date + interval '1 month - 1 day')::date,
  'FY' || extract(year from d)::text || '-Q' || extract(quarter from d)::text
FROM generate_series('2020-01-01'::date, '2035-12-31'::date, '1 day'::interval) AS d
ON CONFLICT (date_key) DO NOTHING;

CREATE OR REPLACE FUNCTION public.sync_fact_invoices()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_vendor_key uuid;
  v_user_key uuid;
  v_invoice_date_key integer;
  v_due_date_key integer;
BEGIN
  SELECT id INTO v_vendor_key FROM public.dim_vendor WHERE source_vendor_id = NEW.vendor_id LIMIT 1;
  SELECT id INTO v_user_key FROM public.dim_user WHERE source_user_id = NEW.created_by LIMIT 1;

  v_invoice_date_key := public.ensure_dim_date(COALESCE(NEW.invoice_date, NEW.created_at::date, now()::date));
  v_due_date_key := public.ensure_dim_date(NEW.due_date);

  INSERT INTO public.fact_invoices (
    source_invoice_id, invoice_date_key, due_date_key,
    vendor_key, created_by_key,
    organization_id, location_id, invoice_number,
    status, payment_status, source,
    total_amount, subtotal, tax_amount,
    fuel_surcharge, delivery_fee, other_charges,
    line_item_count
  ) VALUES (
    NEW.id,
    v_invoice_date_key,
    v_due_date_key,
    v_vendor_key,
    v_user_key,
    NEW.organization_id,
    NEW.location_id,
    NEW.invoice_number,
    NEW.status,
    NEW.payment_status,
    NEW.source,
    NEW.total_amount,
    NEW.subtotal,
    NEW.tax_amount,
    NEW.fuel_surcharge,
    NEW.delivery_fee,
    NEW.other_charges,
    COALESCE(jsonb_array_length(NEW.line_items), 0)
  )
  ON CONFLICT (source_invoice_id) DO UPDATE SET
    invoice_date_key = EXCLUDED.invoice_date_key,
    due_date_key     = EXCLUDED.due_date_key,
    vendor_key       = EXCLUDED.vendor_key,
    status           = EXCLUDED.status,
    payment_status   = EXCLUDED.payment_status,
    total_amount     = EXCLUDED.total_amount,
    subtotal         = EXCLUDED.subtotal,
    tax_amount       = EXCLUDED.tax_amount,
    fuel_surcharge   = EXCLUDED.fuel_surcharge,
    delivery_fee     = EXCLUDED.delivery_fee,
    other_charges    = EXCLUDED.other_charges,
    line_item_count  = EXCLUDED.line_item_count;

  RETURN NEW;
END;
$$;

GRANT EXECUTE ON FUNCTION public.ensure_dim_date(date) TO authenticated, service_role;

