-- ==========================================================================
-- Source: 20260722000007_preserve_invoice_extraction_state_for_paid_uploads.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.normalize_invoice_ap_state()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.status = 'approved' THEN
    NEW.ap_status := 'approved';
  ELSIF NEW.status = 'scheduled' THEN
    NEW.ap_status := 'scheduled';
  ELSIF NEW.status = 'paid' THEN
    NEW.ap_status := 'paid';
    NEW.payment_status := 'paid';
  ELSIF NEW.status = 'rejected' THEN
    IF COALESCE(NEW.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay', 'processing')
      OR COALESCE(NEW.paid_amount, 0) > 0 THEN
      RAISE EXCEPTION 'Rejected invoices cannot carry paid or in-flight payment state';
    END IF;
    NEW.ap_status := 'rejected';
  END IF;

  IF NEW.payment_status = 'paid'
     AND COALESCE(NEW.status, '') NOT IN ('extracting', 'extract_failed') THEN
    NEW.status := 'paid';
    NEW.ap_status := 'paid';
  END IF;

  RETURN NEW;
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260722000008_requeue_stuck_paid_invoice_uploads.sql
-- ==========================================================================

BEGIN;

UPDATE public.invoices
SET
  status = 'extracting',
  ap_status = 'processing',
  extraction_started_at = NULL,
  validation_results = jsonb_set(
    COALESCE(validation_results, '{}'::jsonb),
    '{upload_state}',
    '"stored"'::jsonb,
    true
  ),
  updated_at = now()
WHERE source IN ('manual_upload', 'camera')
  AND invoice_number LIKE 'PENDING-%'
  AND file_url IS NOT NULL
  AND raw_text IS NULL
  AND extraction_started_at IS NULL
  AND status = 'paid';

COMMIT;

