-- Source: 20260722000009_allow_extraction_updates_for_paid_uploads.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.guard_locked_invoice_financial_fields()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF COALESCE(OLD.status, '') NOT IN ('extracting', 'extract_failed')
    AND (
      OLD.status IN ('approved', 'scheduled', 'partially_paid', 'paid')
      OR OLD.ap_status IN ('approved', 'scheduled', 'paid', 'closed')
      OR COALESCE(OLD.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay')
      OR COALESCE(OLD.paid_amount, 0) > 0
    ) THEN
    IF NEW.organization_id IS DISTINCT FROM OLD.organization_id
      OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
      OR NEW.brand_id IS DISTINCT FROM OLD.brand_id
      OR NEW.location_id IS DISTINCT FROM OLD.location_id
      OR NEW.vendor_id IS DISTINCT FROM OLD.vendor_id
      OR NEW.vendor_name IS DISTINCT FROM OLD.vendor_name
      OR NEW.invoice_number IS DISTINCT FROM OLD.invoice_number
      OR NEW.invoice_date IS DISTINCT FROM OLD.invoice_date
      OR NEW.due_date IS DISTINCT FROM OLD.due_date
      OR NEW.total_amount IS DISTINCT FROM OLD.total_amount
      OR NEW.subtotal IS DISTINCT FROM OLD.subtotal
      OR NEW.tax_amount IS DISTINCT FROM OLD.tax_amount
      OR NEW.delivery_fee IS DISTINCT FROM OLD.delivery_fee
      OR NEW.fuel_surcharge IS DISTINCT FROM OLD.fuel_surcharge
      OR NEW.other_charges IS DISTINCT FROM OLD.other_charges
      OR NEW.currency IS DISTINCT FROM OLD.currency
      OR NEW.account_number IS DISTINCT FROM OLD.account_number
      OR NEW.purchase_order_id IS DISTINCT FROM OLD.purchase_order_id
      OR NEW.line_items IS DISTINCT FROM OLD.line_items THEN
      RAISE EXCEPTION 'Approved, scheduled, partially paid, or paid invoice financial fields are immutable';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260722000010_configurable_payment_approval_controls.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.get_payment_approval_settings(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE((
    SELECT os.settings
    FROM public.operational_settings os
    WHERE os.organization_id = p_organization_id
      AND os.category = 'payments'
      AND (
        (p_location_id IS NOT NULL AND os.location_id = p_location_id)
        OR (p_brand_id IS NOT NULL AND os.brand_id = p_brand_id AND os.location_id IS NULL)
        OR (os.brand_id IS NULL AND os.location_id IS NULL)
      )
    ORDER BY
      CASE
        WHEN p_location_id IS NOT NULL AND os.location_id = p_location_id THEN 1
        WHEN p_brand_id IS NOT NULL AND os.brand_id = p_brand_id AND os.location_id IS NULL THEN 2
        ELSE 3
      END,
      os.updated_at DESC NULLS LAST
    LIMIT 1
  ), '{}'::jsonb);
$$;

CREATE OR REPLACE FUNCTION public.enforce_invoice_approval_authorization()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vendor_autopay boolean;
  v_settings jsonb;
  v_require_separate_approver boolean;
  v_enforce_approval_limits boolean;
  v_user_limit numeric;
  v_has_unlimited boolean;
  v_amount numeric;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'approved' OR NEW.ap_status = 'approved' THEN
      v_settings := public.get_payment_approval_settings(NEW.organization_id, NEW.brand_id, NEW.location_id);
      v_require_separate_approver := COALESCE((v_settings->>'requireSeparateApprover')::boolean, false);
      v_enforce_approval_limits := COALESCE((v_settings->>'enforceApprovalLimits')::boolean, false);

      IF v_require_separate_approver
        AND NEW.created_by IS NOT NULL
        AND NEW.created_by = auth.uid() THEN
        RAISE EXCEPTION 'Invoice submitters cannot approve their own invoices';
      END IF;

      PERFORM public.assert_can_approve_invoice_scope(
        NEW.organization_id,
        NEW.brand_id,
        NEW.location_id
      );

      IF v_enforce_approval_limits THEN
        SELECT invoice_approval_limit, COALESCE(has_unlimited_approval, false)
          INTO v_user_limit, v_has_unlimited
        FROM public.profiles
        WHERE id = auth.uid()
          AND deleted_at IS NULL;

        v_amount := COALESCE(NEW.total_amount, 0);
        IF NOT COALESCE(v_has_unlimited, false)
          AND (v_user_limit IS NULL OR v_amount > v_user_limit) THEN
          RAISE EXCEPTION 'Approval limit exceeded. Your limit is $%, but the invoice is $%.',
            COALESCE(v_user_limit, 0), v_amount;
        END IF;
      END IF;

      SELECT autopay_enabled INTO v_vendor_autopay FROM public.vendors WHERE id = NEW.vendor_id;
      IF v_vendor_autopay AND NOT public.is_owner_or_admin() THEN
        RAISE EXCEPTION 'AutoPay invoice approval requires an org manager, tenant super admin, or platform admin';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF (NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved')
    OR (NEW.ap_status = 'approved' AND OLD.ap_status IS DISTINCT FROM 'approved') THEN
    v_settings := public.get_payment_approval_settings(NEW.organization_id, NEW.brand_id, NEW.location_id);
    v_require_separate_approver := COALESCE((v_settings->>'requireSeparateApprover')::boolean, false);
    v_enforce_approval_limits := COALESCE((v_settings->>'enforceApprovalLimits')::boolean, false);

    IF v_require_separate_approver
      AND COALESCE(OLD.created_by, NEW.created_by) IS NOT NULL
      AND COALESCE(OLD.created_by, NEW.created_by) = auth.uid() THEN
      RAISE EXCEPTION 'Invoice submitters cannot approve their own invoices';
    END IF;

    PERFORM public.assert_can_approve_invoice_scope(
      NEW.organization_id,
      NEW.brand_id,
      NEW.location_id
    );

    IF v_enforce_approval_limits THEN
      SELECT invoice_approval_limit, COALESCE(has_unlimited_approval, false)
        INTO v_user_limit, v_has_unlimited
      FROM public.profiles
      WHERE id = auth.uid()
        AND deleted_at IS NULL;

      v_amount := COALESCE(NEW.total_amount, OLD.total_amount, 0);
      IF NOT COALESCE(v_has_unlimited, false)
        AND (v_user_limit IS NULL OR v_amount > v_user_limit) THEN
        RAISE EXCEPTION 'Approval limit exceeded. Your limit is $%, but the invoice is $%.',
          COALESCE(v_user_limit, 0), v_amount;
      END IF;
    END IF;

    SELECT autopay_enabled INTO v_vendor_autopay FROM public.vendors WHERE id = NEW.vendor_id;
    IF v_vendor_autopay AND NOT public.is_owner_or_admin() THEN
      RAISE EXCEPTION 'AutoPay invoice approval requires an org manager, tenant super admin, or platform admin';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_payment_approval_settings(uuid, uuid, uuid) TO authenticated, service_role;

COMMIT;

-- ==========================================================================
-- Source: 20260722000011_allow_internal_product_sync_after_invoice_approval.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.guard_locked_invoice_line_items()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_invoice record;
  v_invoice_id uuid;
BEGIN
  IF current_setting('app.invoice_product_sync', true) = 'on' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  v_invoice_id := COALESCE(NEW.invoice_id, OLD.invoice_id);

  SELECT status, ap_status, payment_status, paid_amount
    INTO v_invoice
  FROM public.invoices
  WHERE id = v_invoice_id;

  IF v_invoice.status IN ('approved', 'scheduled', 'partially_paid', 'paid')
    OR v_invoice.ap_status IN ('approved', 'scheduled', 'paid', 'closed')
    OR COALESCE(v_invoice.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay')
    OR COALESCE(v_invoice.paid_amount, 0) > 0 THEN
    RAISE EXCEPTION 'Invoice line items are immutable after approval or payment activity';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE OR REPLACE FUNCTION public.trigger_sync_invoice_products()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF (TG_OP = 'UPDATE' AND NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved') THEN
    PERFORM set_config('app.invoice_product_sync', 'on', true);
    PERFORM public.sync_invoice_products(NEW.id);
    PERFORM set_config('app.invoice_product_sync', '', true);
  END IF;

  IF (TG_OP = 'INSERT' AND NEW.status = 'approved') THEN
    PERFORM set_config('app.invoice_product_sync', 'on', true);
    PERFORM public.sync_invoice_products(NEW.id);
    PERFORM set_config('app.invoice_product_sync', '', true);
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.invoice_product_sync', '', true);
  RAISE;
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260722000012_sync_approved_invoice_products_to_inventory.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.ensure_inventory_for_invoiced_products(p_invoice_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_created_count integer := 0;
  v_marked_count integer := 0;
BEGIN
  WITH invoice_products AS (
    SELECT DISTINCT
      i.organization_id,
      i.brand_id,
      i.location_id,
      l.name AS location_name,
      p.id AS internal_product_id,
      p.product_id,
      p.name AS product_name,
      p.category,
      p.accounting_category,
      COALESCE(p.report_by_unit, p.base_unit, 'Each') AS unit,
      COALESCE(p.latest_price, 0) AS unit_cost
    FROM public.invoices i
    JOIN public.invoice_line_items ili ON ili.invoice_id = i.id
    JOIN public.products p ON p.id = ili.internal_product_id
    LEFT JOIN public.locations l ON l.id = i.location_id
    WHERE i.id = p_invoice_id
      AND i.deleted_at IS NULL
      AND p.deleted_at IS NULL
      AND ili.internal_product_id IS NOT NULL
  ), marked AS (
    UPDATE public.products p
       SET is_inventoried = true,
           updated_at = now()
      FROM invoice_products ip
     WHERE p.id = ip.internal_product_id
       AND COALESCE(p.is_inventoried, false) IS DISTINCT FROM true
    RETURNING p.id
  ), inserted AS (
    INSERT INTO public.inventory (
      organization_id,
      brand_id,
      location_id,
      internal_product_id,
      product_id,
      product_name,
      category,
      accounting_category,
      location,
      current_quantity,
      current_unit,
      current_value,
      previous_quantity,
      previous_value,
      unit_cost,
      report_by,
      conversion_rates,
      created_at,
      updated_at
    )
    SELECT
      ip.organization_id,
      ip.brand_id,
      ip.location_id,
      ip.internal_product_id,
      ip.product_id,
      ip.product_name,
      ip.category,
      ip.accounting_category,
      ip.location_name,
      0,
      ip.unit,
      0,
      0,
      0,
      ip.unit_cost,
      ip.unit,
      '{}'::jsonb,
      now(),
      now()
    FROM invoice_products ip
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.inventory inv
      WHERE inv.organization_id = ip.organization_id
        AND inv.location_id IS NOT DISTINCT FROM ip.location_id
        AND inv.internal_product_id = ip.internal_product_id
        AND inv.deleted_at IS NULL
    )
    RETURNING id
  )
  SELECT
    (SELECT count(*) FROM marked),
    (SELECT count(*) FROM inserted)
  INTO v_marked_count, v_created_count;

  RETURN jsonb_build_object(
    'status', 'success',
    'marked_products_count', v_marked_count,
    'created_inventory_count', v_created_count
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.trigger_sync_invoice_products()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF (TG_OP = 'UPDATE' AND NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved') THEN
    PERFORM set_config('app.invoice_product_sync', 'on', true);
    PERFORM public.sync_invoice_products(NEW.id);
    PERFORM public.ensure_inventory_for_invoiced_products(NEW.id);
    PERFORM set_config('app.invoice_product_sync', '', true);
  END IF;

  IF (TG_OP = 'INSERT' AND NEW.status = 'approved') THEN
    PERFORM set_config('app.invoice_product_sync', 'on', true);
    PERFORM public.sync_invoice_products(NEW.id);
    PERFORM public.ensure_inventory_for_invoiced_products(NEW.id);
    PERFORM set_config('app.invoice_product_sync', '', true);
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.invoice_product_sync', '', true);
  RAISE;
END;
$$;

WITH approved_invoice_products AS (
  SELECT DISTINCT
    i.id AS invoice_id,
    i.organization_id,
    i.brand_id,
    i.location_id,
    l.name AS location_name,
    p.id AS internal_product_id,
    p.product_id,
    p.name AS product_name,
    p.category,
    p.accounting_category,
    COALESCE(p.report_by_unit, p.base_unit, 'Each') AS unit,
    COALESCE(p.latest_price, 0) AS unit_cost
  FROM public.invoices i
  JOIN public.invoice_line_items ili ON ili.invoice_id = i.id
  JOIN public.products p ON p.id = ili.internal_product_id
  LEFT JOIN public.locations l ON l.id = i.location_id
  WHERE i.status = 'approved'
    AND i.deleted_at IS NULL
    AND p.deleted_at IS NULL
    AND ili.internal_product_id IS NOT NULL
), marked AS (
  UPDATE public.products p
     SET is_inventoried = true,
         updated_at = now()
    FROM approved_invoice_products aip
   WHERE p.id = aip.internal_product_id
     AND COALESCE(p.is_inventoried, false) IS DISTINCT FROM true
  RETURNING p.id
)
INSERT INTO public.inventory (
  organization_id,
  brand_id,
  location_id,
  internal_product_id,
  product_id,
  product_name,
  category,
  accounting_category,
  location,
  current_quantity,
  current_unit,
  current_value,
  previous_quantity,
  previous_value,
  unit_cost,
  report_by,
  conversion_rates,
  created_at,
  updated_at
)
SELECT
  aip.organization_id,
  aip.brand_id,
  aip.location_id,
  aip.internal_product_id,
  aip.product_id,
  aip.product_name,
  aip.category,
  aip.accounting_category,
  aip.location_name,
  0,
  aip.unit,
  0,
  0,
  0,
  aip.unit_cost,
  aip.unit,
  '{}'::jsonb,
  now(),
  now()
FROM approved_invoice_products aip
WHERE NOT EXISTS (
  SELECT 1
  FROM public.inventory inv
  WHERE inv.organization_id = aip.organization_id
    AND inv.location_id IS NOT DISTINCT FROM aip.location_id
    AND inv.internal_product_id = aip.internal_product_id
    AND inv.deleted_at IS NULL
);

GRANT EXECUTE ON FUNCTION public.ensure_inventory_for_invoiced_products(uuid) TO authenticated, service_role;

COMMIT;

-- ==========================================================================
-- Source: 20260722000013_allow_tenant_super_admin_invoice_org_guard.sql
-- ==========================================================================

BEGIN;

-- Invoice intake/document RPCs still depend on assert_org_actor(), which only
-- allowed profile.organization_id unless the caller was platform_admin. Tenant
-- super admins can switch into sibling organizations in the same tenant, so the
-- org guard must honor tenant ownership instead of treating that as cross-org.
CREATE OR REPLACE FUNCTION public.assert_org_actor(p_organization_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  v_role TEXT;
  v_profile_org UUID;
  v_profile_tenant UUID;
  v_org_tenant UUID;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  SELECT public.normalize_app_role(p.role), p.organization_id, p.tenant_id
    INTO v_role, v_profile_org, v_profile_tenant
  FROM public.profiles p
  WHERE p.id = auth.uid()
    AND p.deleted_at IS NULL;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    SELECT o.tenant_id
      INTO v_org_tenant
    FROM public.organizations o
    WHERE o.id = p_organization_id;

    IF COALESCE(v_profile_tenant, public.get_auth_tenant()) IS NOT DISTINCT FROM v_org_tenant THEN
      RETURN;
    END IF;

    RAISE EXCEPTION 'Cross-tenant access denied';
  END IF;

  IF v_profile_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization access denied';
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.assert_org_actor(UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.assert_org_actor(UUID) TO service_role;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260722000014_org_level_reference_scope_visible.sql
-- ==========================================================================

BEGIN;

-- Organization-level reference rows (brand_id IS NULL AND location_id IS NULL) are the
-- default product shape for many tenants. 20260721191500 made every reference row require
-- an active location and then returned false for this org-level tier, so Products /
-- get_product_catalog could hide an entire org catalog even though rows exist.
--
-- After this change:
--   * Same organization only (tenant/org isolation unchanged via organization_id match)
--   * Org-level rows are visible to callers in that organization (no location required)
--   * Brand-shared / location-specific rows still require an active location and match
--     the previous exact brand / location rules
--
-- Also widen get_product_catalog's optional brand/location filters so passing the active
-- brand/location (Products page + Recipe Unit Conversion) still includes ancestor scopes:
-- org-level and brand-shared rows remain in the catalog alongside exact location matches.

CREATE OR REPLACE FUNCTION public.reference_scope_visible(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_deleted_at timestamp with time zone DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role text;
  v_org_id uuid;
  v_location_id uuid;
  v_active_location_brand_id uuid;
BEGIN
  IF p_deleted_at IS NOT NULL THEN
    RETURN false;
  END IF;

  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT role, organization_id, location_id
    INTO v_role, v_org_id, v_location_id
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;

  -- Tenant / organization isolation: never leak across organizations.
  IF p_organization_id IS NULL OR p_organization_id IS DISTINCT FROM v_org_id THEN
    RETURN false;
  END IF;

  -- Organization-level reference row (shared across the org catalog).
  IF p_brand_id IS NULL AND p_location_id IS NULL THEN
    RETURN true;
  END IF;

  -- Brand-shared and location-specific rows still require an active location.
  IF v_location_id IS NULL THEN
    RETURN false;
  END IF;

  -- Location-specific reference row: exact match.
  IF p_location_id IS NOT NULL THEN
    RETURN p_location_id = v_location_id;
  END IF;

  -- Brand-shared reference row (location intentionally NULL): visible when it matches the
  -- brand of the caller's currently active location.
  IF p_brand_id IS NOT NULL THEN
    SELECT l.brand_id INTO v_active_location_brand_id
    FROM public.locations l
    WHERE l.id = v_location_id;

    RETURN p_brand_id IS NOT NULL AND p_brand_id = v_active_location_brand_id;
  END IF;

  RETURN false;
END;
$$;

GRANT EXECUTE ON FUNCTION public.reference_scope_visible(uuid, uuid, uuid, timestamp with time zone)
  TO authenticated, service_role;

-- Keep Products and Recipe Unit Conversion on the same inclusive catalog when the UI
-- passes the active brand/location context.
DROP FUNCTION IF EXISTS public.get_product_catalog(uuid, uuid, uuid, text, text, integer, integer);

CREATE OR REPLACE FUNCTION public.get_product_catalog(
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_search text DEFAULT NULL,
  p_sort_by text DEFAULT 'name',
  p_page integer DEFAULT 0,
  p_page_size integer DEFAULT 50
)
RETURNS TABLE (
  id uuid,
  product_id text,
  name text,
  description text,
  category text,
  accounting_category text,
  category_confidence numeric,
  category_source text,
  category_review_status text,
  suggested_category text,
  suggested_category_type text,
  suggested_accounting_category text,
  category_reason text,
  is_inventoried boolean,
  is_tax_exempt boolean,
  report_by_unit text,
  base_unit text,
  latest_price numeric,
  location_specific boolean,
  organization_id uuid,
  brand_id uuid,
  location_id uuid,
  created_at timestamptz,
  item_count bigint,
  vendor_item_count bigint,
  inventory_item_id uuid,
  vendor_name text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_page integer := GREATEST(COALESCE(p_page, 0), 0);
  v_page_size integer := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 100);
  v_sort_by text := COALESCE(NULLIF(p_sort_by, ''), 'name');
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  RETURN QUERY
  WITH product_scope AS (
    SELECT p.*
    FROM public.products p
    WHERE p.organization_id = v_org_id
      AND p.deleted_at IS NULL
      -- Inclusive hierarchy filter: org-level + matching brand-shared + exact location.
      AND (
        p_brand_id IS NULL
        OR p.brand_id IS NULL
        OR p.brand_id IS NOT DISTINCT FROM p_brand_id
      )
      AND (
        p_location_id IS NULL
        OR p.location_id IS NULL
        OR p.location_id IS NOT DISTINCT FROM p_location_id
      )
      AND public.reference_scope_visible(p.organization_id, p.brand_id, p.location_id, p.deleted_at)
      AND (
        p_search IS NULL
        OR p.name ILIKE '%' || p_search || '%'
        OR COALESCE(p.description, '') ILIKE '%' || p_search || '%'
        OR COALESCE(p.product_id, '') ILIKE '%' || p_search || '%'
      )
  )
  SELECT
    p.id,
    p.product_id,
    p.name,
    p.description,
    p.category,
    p.accounting_category,
    p.category_confidence,
    p.category_source,
    p.category_review_status,
    p.suggested_category,
    p.suggested_category_type,
    p.suggested_accounting_category,
    p.category_reason,
    p.is_inventoried,
    p.is_tax_exempt,
    p.report_by_unit,
    p.base_unit,
    p.latest_price,
    p.location_specific,
    p.organization_id,
    p.brand_id,
    p.location_id,
    p.created_at,
    COALESCE(vendor_info.vendor_item_count, 0) AS item_count,
    COALESCE(vendor_info.vendor_item_count, 0) AS vendor_item_count,
    inv.id AS inventory_item_id,
    vendor_info.vendor_name
  FROM product_scope p
  LEFT JOIN LATERAL (
    SELECT
      count(DISTINCT vim.vendor_item_id)::bigint AS vendor_item_count,
      string_agg(DISTINCT v.name, ', ' ORDER BY v.name) AS vendor_name
    FROM public.vendor_item_mappings vim
    JOIN public.vendor_items vi ON vi.id = vim.vendor_item_id
    LEFT JOIN public.vendors v ON v.id = vi.vendor_id
    WHERE vim.internal_product_id = p.id
      AND vim.organization_id = p.organization_id
      AND vi.organization_id = p.organization_id
  ) vendor_info ON true
  LEFT JOIN LATERAL (
    SELECT i.id
    FROM public.inventory i
    WHERE i.organization_id = p.organization_id
      AND i.deleted_at IS NULL
      AND (
        i.internal_product_id = p.id
        OR (NULLIF(i.product_id, '') IS NOT NULL AND i.product_id = p.product_id)
      )
      AND (p.location_id IS NULL OR i.location_id IS NULL OR i.location_id IS NOT DISTINCT FROM p.location_id)
    ORDER BY
      CASE WHEN i.internal_product_id = p.id THEN 0 ELSE 1 END,
      i.updated_at DESC NULLS LAST,
      i.created_at DESC NULLS LAST
    LIMIT 1
  ) inv ON true
  ORDER BY
    CASE WHEN v_sort_by = 'name' THEN p.name END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-name' THEN p.name END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'category' THEN p.category END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-category' THEN p.category END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'accounting_category' THEN p.accounting_category END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-accounting_category' THEN p.accounting_category END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'is_inventoried' THEN p.is_inventoried END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-is_inventoried' THEN p.is_inventoried END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'latest_price' THEN p.latest_price END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-latest_price' THEN p.latest_price END DESC NULLS LAST,
    p.name ASC NULLS LAST,
    p.created_at DESC NULLS LAST
  LIMIT v_page_size
  OFFSET v_page * v_page_size;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_product_catalog(uuid, uuid, uuid, text, text, integer, integer)
  TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260722000015_audit_logs_hierarchy_visibility.sql
-- ==========================================================================

BEGIN;

-- Audit log hierarchy visibility + filter columns + related bug fixes.
--
-- Root bug: audit_logs_admin_select (is_admin() AND organization_id = get_auth_org()) has no
-- platform_admin bypass -- platform_admin has no organization_id by design, so the Platform
-- Audit Logs page always showed zero rows (confirmed via live role impersonation). That policy
-- was copy-pasted from general_ledger_entries in 20260628000013_append_only_ledger_audit.sql
-- and never tailored for audit_logs' cross-org purpose.
--
-- Also extends the hierarchy model per product decision: org_manager sees their whole org,
-- branch_manager their whole brand, tenant_super_admin every org in their tenant,
-- platform_admin everything, location_manager/ground_staff limited to their own location.
-- Deliberately NOT the newer "exact active location only" rule that governs
-- invoices/payments/inventory -- that's a separate, later product decision for those
-- transactional tables (see 20260721190000_require_exact_location_match_for_org_wide_roles.sql).

-- 1. Schema: nullable brand_id/location_id (declarative partitioning auto-cascades
--    ADD COLUMN/CREATE INDEX/ADD CONSTRAINT to audit_logs_default/y2025/y2026).
ALTER TABLE public.audit_logs
  ADD COLUMN brand_id uuid,
  ADD COLUMN location_id uuid;

-- ON DELETE SET NULL (not RESTRICT like invoices/payments/inventory/auto_orders) --
-- deliberate: this is a historical record, a later brand/location deletion should null
-- the reference, never be blocked by the mere existence of old audit rows.
ALTER TABLE public.audit_logs
  ADD CONSTRAINT audit_logs_brand_id_fkey FOREIGN KEY (brand_id) REFERENCES public.brands(brand_id) ON DELETE SET NULL,
  ADD CONSTRAINT audit_logs_location_id_fkey FOREIGN KEY (location_id) REFERENCES public.locations(id) ON DELETE SET NULL;

CREATE INDEX idx_audit_logs_brand_id ON public.audit_logs (brand_id);
CREATE INDEX idx_audit_logs_location_id ON public.audit_logs (location_id);

-- 2. New hierarchy predicate. Structured like tenant_scope_visible()/reference_scope_visible()
--    (one profile lookup up front) but each role gets its own real rule rather than collapsing
--    to one -- so the NULL-tier (org-level, brand+location both NULL) behavior falls out for
--    free: org_manager/tenant_super_admin never look at brand/location at all (see it),
--    branch_manager/location_manager/ground_staff all hard-require their column non-null
--    (don't see it) -- no special-cased carve-out needed, unlike tenant_scope_visible().
--
--    ground_staff note: get_my_accessible_location_ids() has no ground_staff branch (it's
--    manager-tier only, matching is_manager_or_above() excluding ground_staff elsewhere on
--    purpose) -- composing it alone would silently give ground_staff zero visibility. Fixed
--    with a local OR-fallback against the caller's own profiles.location_id (already fetched
--    above for the org-match guard, so this is free) instead of touching the shared helper,
--    which has unrelated callers across many other migrations.
CREATE OR REPLACE FUNCTION public.audit_log_scope_visible(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL::uuid,
  p_location_id uuid DEFAULT NULL::uuid
)
RETURNS boolean
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_role text;
  v_org_id uuid;
  v_location_id uuid;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT role, organization_id, location_id
    INTO v_role, v_org_id, v_location_id
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    RETURN p_organization_id IS NOT NULL
       AND p_organization_id IN (
         SELECT o.id FROM public.organizations o WHERE o.tenant_id = public.get_auth_tenant()
       );
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN p_organization_id IS NOT NULL AND p_organization_id = v_org_id;
  END IF;

  IF v_role IN ('branch_manager', 'brand_manager') THEN
    RETURN p_organization_id IS NOT NULL AND p_organization_id = v_org_id
       AND p_brand_id IS NOT NULL
       AND p_brand_id IN (SELECT id FROM public.get_my_accessible_brand_ids() id);
  END IF;

  IF v_role IN ('location_manager', 'ground_staff') THEN
    RETURN p_organization_id IS NOT NULL AND p_organization_id = v_org_id
       AND p_location_id IS NOT NULL
       AND (
         p_location_id IN (SELECT id FROM public.get_my_accessible_location_ids() id)
         OR p_location_id = v_location_id
       );
  END IF;

  RETURN false;
END;
$function$;

GRANT EXECUTE ON FUNCTION public.audit_log_scope_visible(uuid, uuid, uuid) TO authenticated;

-- 3. Drop all 4 existing policies (parent + 3 partitions -- this table does NOT rely on
--    policy inheritance, all 4 currently carry an identical explicit predicate), replace
--    with the hierarchy version.
DROP POLICY IF EXISTS audit_logs_admin_select ON public.audit_logs;
DROP POLICY IF EXISTS audit_logs_default_admin_select ON public.audit_logs_default;
DROP POLICY IF EXISTS audit_logs_y2025_admin_select ON public.audit_logs_y2025;
DROP POLICY IF EXISTS audit_logs_y2026_admin_select ON public.audit_logs_y2026;

CREATE POLICY audit_logs_hierarchy_select ON public.audit_logs
  FOR SELECT USING (public.audit_log_scope_visible(organization_id, brand_id, location_id));
CREATE POLICY audit_logs_default_hierarchy_select ON public.audit_logs_default
  FOR SELECT USING (public.audit_log_scope_visible(organization_id, brand_id, location_id));
CREATE POLICY audit_logs_y2025_hierarchy_select ON public.audit_logs_y2025
  FOR SELECT USING (public.audit_log_scope_visible(organization_id, brand_id, location_id));
CREATE POLICY audit_logs_y2026_hierarchy_select ON public.audit_logs_y2026
  FOR SELECT USING (public.audit_log_scope_visible(organization_id, brand_id, location_id));

-- 4. Trigger fix: remove JWT user_metadata fallback (the exact JWT-vs-profiles anti-pattern
--    this repo's hardening eliminated elsewhere -- profiles/the row itself wins), capture
--    brand_id/location_id. Attached only to invoices/payments/inventory/auto_orders -- all 4
--    confirmed to have their own brand_id/location_id columns. process_onboarding_audit_log()
--    needs NO changes -- it's attached only to pre-org/org-level tables with no brand/location
--    of their own, so those rows correctly land in the NULL tier already.
CREATE OR REPLACE FUNCTION public.process_audit_log()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID;
BEGIN
    v_user_id := auth.uid();
    IF (TG_OP = 'DELETE') THEN
        INSERT INTO public.audit_logs (organization_id, brand_id, location_id, user_id, action, table_name, record_id, old_data)
        VALUES (OLD.organization_id, OLD.brand_id, OLD.location_id, v_user_id, 'DELETE', TG_TABLE_NAME, OLD.id, row_to_json(OLD)::jsonb);
        RETURN OLD;
    ELSIF (TG_OP = 'UPDATE') THEN
        INSERT INTO public.audit_logs (organization_id, brand_id, location_id, user_id, action, table_name, record_id, old_data, new_data)
        VALUES (NEW.organization_id, NEW.brand_id, NEW.location_id, v_user_id, 'UPDATE', TG_TABLE_NAME, NEW.id, row_to_json(OLD)::jsonb, row_to_json(NEW)::jsonb);
        RETURN NEW;
    ELSIF (TG_OP = 'INSERT') THEN
        INSERT INTO public.audit_logs (organization_id, brand_id, location_id, user_id, action, table_name, record_id, new_data)
        VALUES (NEW.organization_id, NEW.brand_id, NEW.location_id, v_user_id, 'INSERT', TG_TABLE_NAME, NEW.id, row_to_json(NEW)::jsonb);
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$function$;

-- 5. RPC fix: log_audit_event() accepts brand_id/location_id, same COALESCE pattern as every
--    other field. Everything else in the body is unchanged. log_audit_events() needs no edit
--    -- it just loops calling this per array element.
CREATE OR REPLACE FUNCTION public.log_audit_event(p_entry JSONB)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
  v_record_id UUID;
  v_row public.audit_logs%ROWTYPE;
  v_details TEXT;
BEGIN
  IF p_entry IS NULL OR jsonb_typeof(p_entry) <> 'object' THEN
    RAISE EXCEPTION 'Audit entry must be a JSON object';
  END IF;

  v_org_id := NULLIF(COALESCE(p_entry->>'organization_id', p_entry->>'org_id', p_entry->>'orgId'), '')::UUID;
  v_brand_id := NULLIF(COALESCE(p_entry->>'brand_id', p_entry->>'brandId'), '')::UUID;
  v_location_id := NULLIF(COALESCE(p_entry->>'location_id', p_entry->>'locationId'), '')::UUID;

  IF v_org_id IS NOT NULL THEN
    PERFORM public.assert_org_actor(v_org_id);
  ELSIF auth.role() <> 'service_role' AND NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'organization_id is required for non-platform audit events';
  END IF;

  v_record_id := CASE
    WHEN COALESCE(p_entry->>'record_id', p_entry->>'recordId') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN COALESCE(p_entry->>'record_id', p_entry->>'recordId')::UUID
    ELSE NULL
  END;

  v_details := CASE
    WHEN p_entry ? 'details' AND jsonb_typeof(p_entry->'details') IN ('object', 'array') THEN (p_entry->'details')::TEXT
    WHEN p_entry ? 'details' THEN p_entry->>'details'
    ELSE NULL
  END;

  INSERT INTO public.audit_logs (
    organization_id,
    brand_id,
    location_id,
    user_id,
    action,
    table_name,
    record_id,
    old_data,
    new_data,
    ip_address,
    user_agent,
    entity_type,
    entity_id,
    module,
    field_changed,
    old_value,
    new_value,
    user_email,
    details
  ) VALUES (
    v_org_id,
    v_brand_id,
    v_location_id,
    COALESCE(NULLIF(p_entry->>'user_id', '')::UUID, auth.uid()),
    COALESCE(NULLIF(p_entry->>'action', ''), 'audit'),
    COALESCE(NULLIF(p_entry->>'table_name', ''), NULLIF(p_entry->>'tableName', ''), NULLIF(p_entry->>'entity_type', ''), NULLIF(p_entry->>'entityType', ''), NULLIF(p_entry->>'module', ''), 'system'),
    v_record_id,
    CASE WHEN p_entry ? 'old_data' THEN p_entry->'old_data' WHEN p_entry ? 'oldData' THEN p_entry->'oldData' ELSE NULL END,
    CASE WHEN p_entry ? 'new_data' THEN p_entry->'new_data' WHEN p_entry ? 'newData' THEN p_entry->'newData' ELSE NULL END,
    NULLIF(p_entry->>'ip_address', ''),
    NULLIF(p_entry->>'user_agent', ''),
    COALESCE(NULLIF(p_entry->>'entity_type', ''), NULLIF(p_entry->>'entityType', ''), NULLIF(p_entry->>'action', ''), 'unknown'),
    COALESCE(NULLIF(p_entry->>'entity_id', ''), NULLIF(p_entry->>'entityId', ''), NULLIF(p_entry->>'target_user_id', ''), NULLIF(p_entry->>'record_id', ''), NULLIF(p_entry->>'recordId', '')),
    NULLIF(p_entry->>'module', ''),
    COALESCE(NULLIF(p_entry->>'field_changed', ''), NULLIF(p_entry->>'fieldChanged', '')),
    COALESCE(NULLIF(p_entry->>'old_value', ''), NULLIF(p_entry->>'oldValue', '')),
    COALESCE(NULLIF(p_entry->>'new_value', ''), NULLIF(p_entry->>'newValue', '')),
    COALESCE(NULLIF(p_entry->>'user_email', ''), NULLIF(p_entry->>'userEmail', '')),
    v_details
  )
  RETURNING * INTO v_row;

  RETURN to_jsonb(v_row);
END;
$$;

-- 6. assert_org_actor() recognizes tenant_super_admin's tenant-wide scope, not just an exact
--    own-org match -- needed now that log_audit_event() can be called for any org within a
--    tenant_super_admin's tenant. Everything else unchanged.
CREATE OR REPLACE FUNCTION public.assert_org_actor(p_organization_id UUID)
RETURNS void
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_role TEXT;
  v_profile_org UUID;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT role, organization_id
    INTO v_role, v_profile_org
  FROM public.profiles
  WHERE id = auth.uid();

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    IF p_organization_id IN (SELECT o.id FROM public.organizations o WHERE o.tenant_id = public.get_auth_tenant()) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'Cross-organization access denied';
  END IF;

  IF v_profile_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization access denied';
  END IF;
END;
$function$;

-- 7. Realtime was silently dead on both audit-log pages: audit_logs was never added to the
--    supabase_realtime publication (confirmed: 0 rows in pg_publication_tables for it), so
--    their postgres_changes subscriptions never fired. Register it (auto-cascades to
--    partitions).
ALTER PUBLICATION supabase_realtime ADD TABLE public.audit_logs;

COMMIT;

-- ==========================================================================
-- Source: 20260722000016_product_count_units.sql
-- ==========================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS public.product_count_units (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  brand_id uuid REFERENCES public.brands(brand_id) ON DELETE SET NULL,
  location_id uuid REFERENCES public.locations(id) ON DELETE SET NULL,
  product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  name text NOT NULL,
  normalized_name text NOT NULL,
  quantity numeric NOT NULL DEFAULT 1 CHECK (quantity > 0),
  unit text NOT NULL,
  unit_price numeric NOT NULL DEFAULT 0,
  source_quantity numeric NOT NULL DEFAULT 1 CHECK (source_quantity > 0),
  source_unit text NOT NULL,
  source_price numeric NOT NULL DEFAULT 0,
  is_active boolean NOT NULL DEFAULT true,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_product_count_units_active_name
  ON public.product_count_units (organization_id, product_id, normalized_name)
  WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_product_count_units_product
  ON public.product_count_units (organization_id, product_id)
  WHERE deleted_at IS NULL;

ALTER TABLE public.product_count_units ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS product_count_units_select ON public.product_count_units;
CREATE POLICY product_count_units_select ON public.product_count_units
  FOR SELECT
  USING (
    deleted_at IS NULL
    AND public.reference_scope_visible(organization_id, brand_id, location_id, deleted_at)
  );

DROP POLICY IF EXISTS product_count_units_insert ON public.product_count_units;
CREATE POLICY product_count_units_insert ON public.product_count_units
  FOR INSERT
  WITH CHECK (
    public.product_write_allowed(organization_id, brand_id, location_id)
    AND EXISTS (
      SELECT 1
      FROM public.products p
      WHERE p.id = product_count_units.product_id
        AND p.organization_id = product_count_units.organization_id
        AND p.deleted_at IS NULL
    )
  );

DROP POLICY IF EXISTS product_count_units_update ON public.product_count_units;
CREATE POLICY product_count_units_update ON public.product_count_units
  FOR UPDATE
  USING (
    deleted_at IS NULL
    AND public.product_write_allowed(organization_id, brand_id, location_id)
  )
  WITH CHECK (
    public.product_write_allowed(organization_id, brand_id, location_id)
    AND EXISTS (
      SELECT 1
      FROM public.products p
      WHERE p.id = product_count_units.product_id
        AND p.organization_id = product_count_units.organization_id
        AND p.deleted_at IS NULL
    )
  );

DROP POLICY IF EXISTS product_count_units_delete ON public.product_count_units;
CREATE POLICY product_count_units_delete ON public.product_count_units
  FOR DELETE
  USING (
    public.product_write_allowed(organization_id, brand_id, location_id)
  );

GRANT SELECT, INSERT, UPDATE, DELETE ON public.product_count_units TO authenticated;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260722000017_product_count_unit_rpcs.sql
-- ==========================================================================

BEGIN;

CREATE OR REPLACE FUNCTION public.upsert_product_count_unit(
  p_product_id uuid,
  p_name text,
  p_quantity numeric,
  p_unit text,
  p_unit_price numeric,
  p_source_quantity numeric,
  p_source_unit text,
  p_source_price numeric
)
RETURNS public.product_count_units
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_normalized_name text;
  v_existing_id uuid;
  v_count_unit public.product_count_units%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;

  v_normalized_name := lower(trim(COALESCE(p_name, '')));

  IF v_normalized_name = '' THEN
    RAISE EXCEPTION 'Count unit name is required';
  END IF;

  IF COALESCE(p_quantity, 0) <= 0 THEN
    RAISE EXCEPTION 'Count unit quantity must be greater than zero';
  END IF;

  IF COALESCE(p_source_quantity, 0) <= 0 THEN
    RAISE EXCEPTION 'Source package quantity must be greater than zero';
  END IF;

  SELECT id
    INTO v_existing_id
  FROM public.product_count_units
  WHERE organization_id = v_product.organization_id
    AND product_id = v_product.id
    AND normalized_name = v_normalized_name
    AND deleted_at IS NULL
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    UPDATE public.product_count_units
       SET brand_id = v_product.brand_id,
           location_id = v_product.location_id,
           name = trim(p_name),
           quantity = p_quantity,
           unit = trim(p_unit),
           unit_price = COALESCE(p_unit_price, 0),
           source_quantity = p_source_quantity,
           source_unit = trim(p_source_unit),
           source_price = COALESCE(p_source_price, 0),
           is_active = true,
           updated_at = now()
     WHERE id = v_existing_id
     RETURNING * INTO v_count_unit;
  ELSE
    INSERT INTO public.product_count_units (
      organization_id,
      brand_id,
      location_id,
      product_id,
      name,
      normalized_name,
      quantity,
      unit,
      unit_price,
      source_quantity,
      source_unit,
      source_price,
      is_active,
      created_by
    )
    VALUES (
      v_product.organization_id,
      v_product.brand_id,
      v_product.location_id,
      v_product.id,
      trim(p_name),
      v_normalized_name,
      p_quantity,
      trim(p_unit),
      COALESCE(p_unit_price, 0),
      p_source_quantity,
      trim(p_source_unit),
      COALESCE(p_source_price, 0),
      true,
      auth.uid()
    )
    RETURNING * INTO v_count_unit;
  END IF;

  RETURN v_count_unit;
END;
$$;

CREATE OR REPLACE FUNCTION public.remove_product_count_unit(
  p_count_unit_id uuid
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_count_unit public.product_count_units%ROWTYPE;
  v_product public.products%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_count_unit
  FROM public.product_count_units
  WHERE id = p_count_unit_id
    AND deleted_at IS NULL;

  IF v_count_unit.id IS NULL THEN
    RETURN true;
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = v_count_unit.product_id
    AND deleted_at IS NULL;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;

  UPDATE public.product_count_units
     SET deleted_at = now(),
         is_active = false,
         updated_at = now()
   WHERE id = p_count_unit_id;

  RETURN true;
END;
$$;

GRANT EXECUTE ON FUNCTION public.upsert_product_count_unit(uuid, text, numeric, text, numeric, numeric, text, numeric) TO authenticated;
GRANT EXECUTE ON FUNCTION public.remove_product_count_unit(uuid) TO authenticated;

NOTIFY pgrst, 'reload schema';

COMMIT;

