  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.purchase_orders po
      WHERE po.id = purchase_order_items.purchase_order_id
        AND public.tenant_scope_writable(po.organization_id, NULL, po.location_id, NULL, false)
