-- Source: 20260725000002_client_feedback_issue_suggestions.sql
-- ==========================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS public.platform_feedback_settings (
  id BOOLEAN PRIMARY KEY DEFAULT true,
  issue_to TEXT[] NOT NULL DEFAULT ARRAY['pradeepk@mindfultechsol.com']::TEXT[],
  issue_cc TEXT[] NOT NULL DEFAULT ARRAY['karthiku@mindfultechsol.com', 'Narendrapydi@mindfultechsol.com']::TEXT[],
  suggestion_to TEXT[] NOT NULL DEFAULT ARRAY['Karthiku@MIndfultechsol.com']::TEXT[],
  suggestion_cc TEXT[] NOT NULL DEFAULT ARRAY['Narendrapydi@mindfultechsol.com']::TEXT[],
  updated_by UUID REFERENCES auth.users(id),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT platform_feedback_settings_singleton CHECK (id = true)
);

INSERT INTO public.platform_feedback_settings (id)
VALUES (true)
ON CONFLICT (id) DO NOTHING;

ALTER TABLE public.platform_feedback_settings ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS platform_feedback_settings_read ON public.platform_feedback_settings;
CREATE POLICY platform_feedback_settings_read
  ON public.platform_feedback_settings FOR SELECT
  USING (auth.role() = 'authenticated');

DROP POLICY IF EXISTS platform_feedback_settings_admin_update ON public.platform_feedback_settings;
CREATE POLICY platform_feedback_settings_admin_update
  ON public.platform_feedback_settings FOR UPDATE
  USING (public.get_auth_role() = 'platform_admin')
  WITH CHECK (public.get_auth_role() = 'platform_admin');

CREATE OR REPLACE FUNCTION public.touch_platform_feedback_settings_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_touch_platform_feedback_settings ON public.platform_feedback_settings;
CREATE TRIGGER trg_touch_platform_feedback_settings
  BEFORE UPDATE ON public.platform_feedback_settings
  FOR EACH ROW EXECUTE FUNCTION public.touch_platform_feedback_settings_updated_at();

CREATE TABLE IF NOT EXISTS public.client_feedback_submissions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  type TEXT NOT NULL CHECK (type IN ('issue', 'suggestion')),
  subject TEXT NOT NULL,
  message TEXT NOT NULL,
  priority TEXT,
  user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  user_email TEXT,
  user_name TEXT,
  organization_id UUID REFERENCES public.organizations(id) ON DELETE SET NULL,
  organization_name TEXT,
  status TEXT NOT NULL DEFAULT 'submitted' CHECK (status IN ('submitted', 'emailed', 'email_failed', 'reviewed', 'closed')),
  email_to TEXT[] NOT NULL DEFAULT '{}'::TEXT[],
  email_cc TEXT[] NOT NULL DEFAULT '{}'::TEXT[],
  email_sent BOOLEAN NOT NULL DEFAULT false,
  email_error TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.client_feedback_submissions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS client_feedback_insert_own ON public.client_feedback_submissions;
CREATE POLICY client_feedback_insert_own
  ON public.client_feedback_submissions FOR INSERT
  WITH CHECK (auth.uid() IS NOT NULL AND (user_id IS NULL OR user_id = auth.uid()));

DROP POLICY IF EXISTS client_feedback_read_own_or_platform ON public.client_feedback_submissions;
CREATE POLICY client_feedback_read_own_or_platform
  ON public.client_feedback_submissions FOR SELECT
  USING (public.get_auth_role() = 'platform_admin' OR user_id = auth.uid());

DROP POLICY IF EXISTS client_feedback_platform_update ON public.client_feedback_submissions;
CREATE POLICY client_feedback_platform_update
  ON public.client_feedback_submissions FOR UPDATE
  USING (public.get_auth_role() = 'platform_admin')
  WITH CHECK (public.get_auth_role() = 'platform_admin');

CREATE INDEX IF NOT EXISTS idx_client_feedback_submissions_type_created
  ON public.client_feedback_submissions(type, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_client_feedback_submissions_user
  ON public.client_feedback_submissions(user_id, created_at DESC);

CREATE OR REPLACE FUNCTION public.touch_client_feedback_submissions_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_touch_client_feedback_submissions ON public.client_feedback_submissions;
CREATE TRIGGER trg_touch_client_feedback_submissions
  BEFORE UPDATE ON public.client_feedback_submissions
  FOR EACH ROW EXECUTE FUNCTION public.touch_client_feedback_submissions_updated_at();

CREATE OR REPLACE FUNCTION public.get_platform_feedback_settings()
RETURNS JSONB
LANGUAGE sql
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT jsonb_build_object(
    'issue_to', issue_to,
    'issue_cc', issue_cc,
    'suggestion_to', suggestion_to,
    'suggestion_cc', suggestion_cc,
    'updated_at', updated_at
  )
  FROM public.platform_feedback_settings
  WHERE id = true;
$$;

CREATE OR REPLACE FUNCTION public.update_platform_feedback_settings(
  p_issue_to TEXT[],
  p_issue_cc TEXT[],
  p_suggestion_to TEXT[],
  p_suggestion_cc TEXT[]
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_settings public.platform_feedback_settings%ROWTYPE;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  UPDATE public.platform_feedback_settings
  SET issue_to = COALESCE(p_issue_to, issue_to),
      issue_cc = COALESCE(p_issue_cc, issue_cc),
      suggestion_to = COALESCE(p_suggestion_to, suggestion_to),
      suggestion_cc = COALESCE(p_suggestion_cc, suggestion_cc)
  WHERE id = true
  RETURNING * INTO v_settings;

  RETURN jsonb_build_object(
    'success', true,
    'issue_to', v_settings.issue_to,
    'issue_cc', v_settings.issue_cc,
    'suggestion_to', v_settings.suggestion_to,
    'suggestion_cc', v_settings.suggestion_cc,
    'updated_at', v_settings.updated_at
  );
END;
$$;

GRANT SELECT ON public.platform_feedback_settings TO authenticated;
GRANT SELECT, INSERT ON public.client_feedback_submissions TO authenticated;
GRANT UPDATE ON public.client_feedback_submissions TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_platform_feedback_settings() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.update_platform_feedback_settings(TEXT[], TEXT[], TEXT[], TEXT[]) TO authenticated, service_role;

COMMIT;

-- ==========================================================================
-- Source: 20260726000001_team_invite_access_permissions.sql
-- ==========================================================================

BEGIN;

ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS access_permissions jsonb NOT NULL DEFAULT '{}'::jsonb;

ALTER TABLE public.roles
  ADD COLUMN IF NOT EXISTS default_page_permissions jsonb NOT NULL DEFAULT '{}'::jsonb;

CREATE OR REPLACE FUNCTION public.accept_invitation(p_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_invite record;
  v_user_id uuid;
  v_user_email text;
  v_user_name text;
  v_role text;
  v_tenant_id uuid;
  v_business_verification_required boolean := true;
  v_coupon_code text;
  v_access_permissions jsonb := '{}'::jsonb;
  v_role_id uuid;
  v_profile_context record;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT
    email,
    COALESCE(raw_user_meta_data->>'full_name', raw_user_meta_data->>'name', split_part(email, '@', 1))
  INTO v_user_email, v_user_name
  FROM auth.users
  WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND closed_at IS NULL
    AND lower(email) = lower(v_user_email)
    AND (expires_at IS NULL OR expires_at > now())
  FOR UPDATE;

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  v_role := public.normalize_app_role(v_invite.role);
  v_tenant_id := v_invite.tenant_id;
  v_business_verification_required := COALESCE((v_invite.metadata->>'business_verification_required')::boolean, true);
  v_coupon_code := COALESCE(v_invite.metadata->>'coupon_code', v_invite.metadata#>>'{coupon,code}');
  v_access_permissions := CASE
    WHEN jsonb_typeof(v_invite.metadata->'permissions') = 'object' THEN v_invite.metadata->'permissions'
    WHEN jsonb_typeof(v_invite.metadata->'access') = 'object' THEN v_invite.metadata->'access'
    ELSE '{}'::jsonb
  END;

  IF v_tenant_id IS NULL AND v_invite.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO v_tenant_id FROM public.organizations WHERE id = v_invite.organization_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NULL THEN
    INSERT INTO public.tenants (name, owner_id, metadata)
    VALUES (
      COALESCE(v_invite.metadata->>'tenant_name', split_part(v_user_email, '@', 1), 'Tenant'),
      v_user_id,
      jsonb_build_object(
        'source', 'accept_invitation',
        'invitation_id', v_invite.id,
        'invited_email', v_invite.email,
        'business_verification_required', v_business_verification_required,
        'coupon_code', v_coupon_code
      )
    )
    RETURNING id INTO v_tenant_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NOT NULL THEN
    INSERT INTO public.tenant_members (tenant_id, user_id, role)
    VALUES (v_tenant_id, v_user_id, 'tenant_super_admin')
    ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    UPDATE public.tenants
    SET owner_id = COALESCE(owner_id, v_user_id),
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
          'business_verification_required', v_business_verification_required,
          'coupon_code', v_coupon_code
        ),
        updated_at = now()
    WHERE id = v_tenant_id;
  END IF;

  IF v_invite.organization_id IS NOT NULL THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_invite.organization_id, v_user_id, v_role)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.brand_id IS NOT NULL THEN
    INSERT INTO public.brand_members (brand_id, user_id, role)
    VALUES (v_invite.brand_id, v_user_id, v_role)
    ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.location_id IS NOT NULL THEN
    INSERT INTO public.location_members (location_id, user_id, role)
    VALUES (v_invite.location_id, v_user_id, v_role)
    ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  SELECT id INTO v_role_id
  FROM public.roles
  WHERE name = v_role
    AND (is_system = true OR organization_id = v_invite.organization_id)
  ORDER BY is_system ASC
  LIMIT 1;

  IF v_role_id IS NOT NULL AND v_invite.organization_id IS NOT NULL THEN
    INSERT INTO public.user_roles (user_id, role_id, location_id, organization_id)
    VALUES (v_user_id, v_role_id, v_invite.location_id, v_invite.organization_id)
    ON CONFLICT (user_id, role_id) DO UPDATE
      SET location_id = EXCLUDED.location_id,
          organization_id = EXCLUDED.organization_id;
  END IF;

  PERFORM set_config('app.trusted_profile_write', 'on', true);

  INSERT INTO public.profiles (
    id,
    email,
    full_name,
    tenant_id,
    role,
    organization_id,
    brand_id,
    location_id,
    coupon_code,
    payment_verified,
    business_verification_status,
    onboarding_status,
    onboarding_current_step,
    access_permissions,
    is_active
  )
  VALUES (
    v_user_id,
    v_user_email,
    COALESCE(v_user_name, split_part(v_user_email, '@', 1), 'User'),
    v_tenant_id,
    v_role,
    v_invite.organization_id,
    v_invite.brand_id,
    v_invite.location_id,
    v_coupon_code,
    false,
    CASE
      WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'verified'
      ELSE 'not_started'
    END,
    'not_started',
    CASE
      WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'hierarchy_setup'
      ELSE 'business_verification'
    END,
    v_access_permissions,
    true
  )
  ON CONFLICT (id) DO UPDATE
  SET email = EXCLUDED.email,
      full_name = COALESCE(NULLIF(public.profiles.full_name, ''), EXCLUDED.full_name),
      tenant_id = COALESCE(EXCLUDED.tenant_id, public.profiles.tenant_id),
      role = EXCLUDED.role,
      organization_id = COALESCE(EXCLUDED.organization_id, public.profiles.organization_id),
      brand_id = COALESCE(EXCLUDED.brand_id, public.profiles.brand_id),
      location_id = COALESCE(EXCLUDED.location_id, public.profiles.location_id),
      coupon_code = COALESCE(EXCLUDED.coupon_code, public.profiles.coupon_code),
      access_permissions = CASE WHEN v_access_permissions = '{}'::jsonb THEN public.profiles.access_permissions ELSE v_access_permissions END,
      business_verification_status = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'verified'
        ELSE public.profiles.business_verification_status
      END,
      onboarding_current_step = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'hierarchy_setup'
        ELSE public.profiles.onboarding_current_step
      END,
      is_active = true,
      updated_at = now();

  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id,
      role = v_role,
      tenant_id = COALESCE(tenant_id, v_tenant_id),
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
        'business_verification_required', v_business_verification_required,
        'coupon_code', v_coupon_code,
        'permissions', v_access_permissions
      )
  WHERE id = v_invite.id
    AND accepted_at IS NULL
    AND closed_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  SELECT
    role,
    tenant_id,
    organization_id,
    brand_id,
    location_id,
    access_permissions
  INTO v_profile_context
  FROM public.profiles
  WHERE id = v_user_id;

  PERFORM public.sync_auth_metadata_from_profile(v_user_id);

  RETURN jsonb_build_object(
    'success', true,
    'role', v_profile_context.role,
    'tenant_id', v_profile_context.tenant_id,
    'organization_id', v_profile_context.organization_id,
    'brand_id', v_profile_context.brand_id,
    'location_id', v_profile_context.location_id,
    'access_permissions', v_profile_context.access_permissions,
    'business_verification_required', v_business_verification_required,
    'coupon_code', v_coupon_code
  );
END;
$$;

DROP FUNCTION IF EXISTS public.admin_update_user_role(uuid, text, text, text, text, uuid, uuid, text);
DROP FUNCTION IF EXISTS public.admin_update_user_role(uuid, text, text, text, text, uuid, uuid, text, jsonb);

CREATE OR REPLACE FUNCTION public.admin_update_user_role(
  target_user_id uuid,
  new_role text DEFAULT NULL::text,
  new_status text DEFAULT NULL::text,
  new_department text DEFAULT NULL::text,
  new_location text DEFAULT NULL::text,
  new_brand_id uuid DEFAULT NULL::uuid,
  new_location_id uuid DEFAULT NULL::uuid,
  new_access_level text DEFAULT NULL::text,
  new_access_permissions jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  caller_role text;
  caller_org uuid;
  caller_tenant uuid;
  target_org uuid;
  target_tenant uuid;
  normalized_role text;
BEGIN
  IF new_location IS NOT NULL THEN
    -- Backward-compatible no-op.
  END IF;

  caller_role := public.get_auth_role();
  caller_org := public.get_auth_org();
  caller_tenant := public.get_auth_tenant();
  normalized_role := CASE WHEN new_role IS NULL THEN NULL ELSE public.normalize_app_role(new_role) END;

  IF caller_role NOT IN ('org_manager', 'tenant_super_admin', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: org_manager, tenant_super_admin, or platform_admin required';
  END IF;

  SELECT p.organization_id, COALESCE(p.tenant_id, o.tenant_id)
  INTO target_org, target_tenant
  FROM public.profiles p
  LEFT JOIN public.organizations o ON o.id = p.organization_id
  WHERE p.id = target_user_id;

  IF caller_role = 'tenant_super_admin' AND target_tenant IS DISTINCT FROM caller_tenant THEN
    RAISE EXCEPTION 'Cannot modify users outside your tenant';
  END IF;

  IF caller_role = 'org_manager' AND target_org IS DISTINCT FROM caller_org THEN
    RAISE EXCEPTION 'Cannot modify users outside your organization';
  END IF;

  IF caller_role != 'platform_admin' AND normalized_role IS NOT NULL THEN
    IF NOT public.can_invite_role(normalized_role) THEN
      RAISE EXCEPTION 'Cannot assign a role equal to or above your own';
    END IF;
  END IF;

  IF target_user_id = auth.uid() AND normalized_role IS NOT NULL AND normalized_role <> caller_role THEN
    RAISE EXCEPTION 'Cannot change your own role';
  END IF;

  IF normalized_role = 'tenant_super_admin' AND target_tenant IS NOT NULL THEN
    INSERT INTO public.tenant_members (tenant_id, user_id, role)
    VALUES (target_tenant, target_user_id, 'tenant_super_admin')
    ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF normalized_role IS NOT NULL AND target_org IS NOT NULL THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (target_org, target_user_id, normalized_role)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  PERFORM set_config('app.trusted_profile_write', 'on', true);
  UPDATE public.profiles
  SET role = COALESCE(normalized_role, role),
      status = COALESCE(new_status, status),
      department = COALESCE(new_department, department),
      brand_id = COALESCE(new_brand_id, brand_id),
      location_id = COALESCE(new_location_id, location_id),
      access_level = COALESCE(new_access_level, access_level),
      access_permissions = COALESCE(new_access_permissions, access_permissions),
      tenant_id = COALESCE(tenant_id, target_tenant),
      updated_at = now()
  WHERE id = target_user_id;

  PERFORM public.sync_auth_metadata_from_profile(target_user_id);

  RETURN jsonb_build_object('success', true);
END;
$$;

GRANT EXECUTE ON FUNCTION public.accept_invitation(text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_update_user_role(uuid, text, text, text, text, uuid, uuid, text, jsonb) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';

COMMIT;

-- ==========================================================================
-- Source: 20260726000002_notification_delivery_preference_enforcement.sql
-- ==========================================================================

-- Today only notificationService.js's createNotification/notifyManagers (client-side) check
-- notification_delivery_preferences before inserting into public.notifications. At least five
-- other insert paths -- workflowService.js, _shared/notifyPaymentFailure.ts,
-- dashboard-report-scheduler, billing-worker, iot-webhook, plus the send_due_date_reminders/
-- notify_expired_owner_invitations DB functions -- insert directly and bypass it entirely, so a
-- user who disables in-app notifications for a module (or asks for critical-only) still gets
-- notified anyway depending on which code path happened to create the row. Patching each caller
-- individually is six+ diffs that can drift apart again; enforcing it once at the DB layer is
-- the root-cause fix and covers every future caller too.
--
-- This also activates the email_enabled/phone_enabled toggles the Settings UI already exposes
-- (code/src/modules/dashboard/pages/Notifications.jsx) but that nothing has ever acted on: an
-- AFTER-the-fact dispatch to a new notify-channel-dispatch Edge Function, gated per-channel by
-- the same preference row. Critical-type notifications (see CRITICAL_TYPES in
-- notificationService.js) always email regardless of the email_enabled toggle, matching the
-- existing (now-simplified) behavior of _shared/notifyPaymentFailure.ts, which unconditionally
-- emailed on payment failure before this migration -- nothing forces SMS the same way, since no
-- such precedent existed anywhere in this codebase before now.

BEGIN;

CREATE OR REPLACE FUNCTION public.enforce_notification_delivery_preference()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_module_key text;
  v_is_critical boolean;
  v_in_app_enabled boolean;
  v_critical_only boolean;
  v_email_enabled boolean;
  v_phone_enabled boolean;
  v_send_email boolean;
  v_send_sms boolean;
  v_functions_url text;
  v_service_role_key text;
  v_url text;
BEGIN
  -- Resolve module key the same way notificationService.js's moduleForNotification() does:
  -- explicit metadata.module_key wins, else map from type, else fall back to 'dashboard'.
  v_module_key := COALESCE(
    NEW.metadata->>'module_key',
    CASE NEW.type
      WHEN 'approval' THEN 'invoices'
      WHEN 'invoice' THEN 'invoices'
      WHEN 'invoice_approved' THEN 'invoices'
      WHEN 'payment' THEN 'payments'
      WHEN 'payment_failed' THEN 'payments'
      WHEN 'billing' THEN 'payments'
      WHEN 'inventory' THEN 'inventory'
      WHEN 'low_inventory' THEN 'inventory'
      WHEN 'order' THEN 'inventory'
      WHEN 'vendor_update' THEN 'vendors'
      WHEN 'labor_alert' THEN 'labor'
      ELSE 'dashboard'
    END
  );

  -- Mirrors notificationService.js's CRITICAL_TYPES / isCriticalNotification().
  v_is_critical := COALESCE((NEW.metadata->>'critical')::boolean, false)
    OR NEW.metadata->>'priority' = 'critical'
    OR NEW.type IN ('error', 'warning', 'payment_failed', 'low_inventory', 'AI_alert');

  SELECT in_app_enabled, critical_only, email_enabled, phone_enabled
    INTO v_in_app_enabled, v_critical_only, v_email_enabled, v_phone_enabled
  FROM public.notification_delivery_preferences
  WHERE user_id = NEW.user_id AND module_key = v_module_key;

  IF NOT FOUND THEN
    -- No stored row => same defaults the table's own column defaults encode.
    v_in_app_enabled := true;
    v_critical_only := false;
    v_email_enabled := false;
    v_phone_enabled := false;
  END IF;

  IF NOT v_in_app_enabled THEN
    RETURN NULL; -- silently cancel the insert, same "skip" behavior createNotification() already does client-side
  END IF;

  IF v_critical_only AND NOT v_is_critical THEN
    RETURN NULL;
  END IF;

  -- A caller that already sends its own specialized email (e.g. send_due_date_reminders(), which
  -- triggers send-due-date-reminder-emails separately) sets this to skip a duplicate generic one.
  IF NEW.metadata->>'skip_channel_dispatch' = 'true' THEN
    RETURN NEW;
  END IF;

  v_send_email := v_email_enabled OR v_is_critical;
  v_send_sms := v_phone_enabled;

  IF v_send_email OR v_send_sms THEN
    BEGIN
      SELECT setting_value INTO v_functions_url FROM private.workflow_runtime_settings WHERE setting_name = 'functions_url';
      SELECT setting_value INTO v_service_role_key FROM private.workflow_runtime_settings WHERE setting_name = 'service_role_key';

      IF v_service_role_key IS NOT NULL AND length(trim(v_service_role_key)) > 0 THEN
        v_url := COALESCE(NULLIF(trim(v_functions_url), ''), 'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1') || '/notify-channel-dispatch';

        PERFORM net.http_post(
          url := v_url,
          body := jsonb_build_object(
            'user_id', NEW.user_id,
            'title', NEW.title,
            'message', COALESCE(NEW.message, NEW.body),
            'send_email', v_send_email,
            'send_sms', v_send_sms
          ),
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || v_service_role_key
          )
        );
      END IF;
    EXCEPTION WHEN OTHERS THEN
      -- The in-app row is already landing via this same trigger's RETURN NEW below; a dispatch
      -- failure (or pg_net/net schema missing locally) must never block that.
      NULL;
    END;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_enforce_notification_delivery_preference ON public.notifications;
CREATE TRIGGER trg_enforce_notification_delivery_preference
  BEFORE INSERT ON public.notifications
  FOR EACH ROW EXECUTE FUNCTION public.enforce_notification_delivery_preference();

-- send_due_date_reminders() (most recently redefined in 20260718000004_fix_reminders_role_list.sql)
-- already triggers its own dedicated send-due-date-reminder-emails call with properly formatted
-- invoice/vendor/amount content; mark its notification inserts so the new trigger above doesn't
-- also fire a second, generic email for the same event. CREATE OR REPLACE with only the
-- metadata's added skip_channel_dispatch key changed; rest of the function body is unchanged
-- from 20260718000004_fix_reminders_role_list.sql:9-108.
CREATE OR REPLACE FUNCTION public.send_due_date_reminders()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_setting RECORD;
  v_profile RECORD;
  v_invoice RECORD;
BEGIN
  FOR v_setting IN
    SELECT user_id, organization_id, reminder_days
    FROM public.invoice_reminder_settings
    WHERE enabled = true
  LOOP
    SELECT role, organization_id, brand_id, location_id
      INTO v_profile
    FROM public.profiles
    WHERE id = v_setting.user_id
      AND deleted_at IS NULL;

    IF v_profile.role IS NULL THEN
      CONTINUE;
    END IF;

    FOR v_invoice IN
      SELECT i.id, i.due_date, (i.due_date - CURRENT_DATE) AS days_out
      FROM public.invoices i
      WHERE i.deleted_at IS NULL
        AND i.organization_id = v_setting.organization_id
        AND COALESCE(i.payment_status, 'unpaid') NOT IN ('paid', 'auto_pay')
        AND i.due_date IS NOT NULL
        AND (i.due_date - CURRENT_DATE) = ANY(v_setting.reminder_days)
        AND (
          v_profile.role IN ('org_manager', 'tenant_super_admin', 'platform_admin')
          OR (
            v_profile.role = 'branch_manager'
            AND (
              i.brand_id = v_profile.brand_id
              OR i.location_id IN (SELECT l.id FROM public.locations l WHERE l.brand_id = v_profile.brand_id)
            )
          )
          OR (
            v_profile.role IN ('location_manager', 'ground_staff')
            AND i.location_id = v_profile.location_id
          )
        )
    LOOP
      INSERT INTO public.invoice_reminder_log (invoice_id, user_id, reminder_day)
      VALUES (v_invoice.id, v_setting.user_id, v_invoice.days_out)
      ON CONFLICT (invoice_id, user_id, reminder_day) DO NOTHING;

      IF FOUND THEN
        INSERT INTO public.notifications (user_id, organization_id, type, title, message, is_read, metadata)
        VALUES (
          v_setting.user_id,
          v_setting.organization_id,
          'invoice',
          CASE WHEN v_invoice.days_out <= 0 THEN 'Invoice overdue' ELSE 'Invoice due soon' END,
          CASE WHEN v_invoice.days_out <= 0
            THEN format('An invoice was due on %s and is still unpaid.', to_char(v_invoice.due_date, 'Mon DD, YYYY'))
            ELSE format('An invoice is due in %s day%s (%s).', v_invoice.days_out, CASE WHEN v_invoice.days_out = 1 THEN '' ELSE 's' END, to_char(v_invoice.due_date, 'Mon DD, YYYY'))
          END,
          false,
          jsonb_build_object('invoice_id', v_invoice.id, 'due_in_days', v_invoice.days_out, 'skip_channel_dispatch', true)
        );
      END IF;
    END LOOP;
  END LOOP;

  -- Trigger the email side (plain SQL can't call Resend). Same secure-dispatch pattern as
  -- dispatch_webhook_queue(): read the functions URL/service key from
  -- private.workflow_runtime_settings rather than hardcoding credentials in this function.
  DECLARE
    v_functions_url text;
    v_service_role_key text;
    v_url text;
  BEGIN
    SELECT setting_value INTO v_functions_url FROM private.workflow_runtime_settings WHERE setting_name = 'functions_url';
    SELECT setting_value INTO v_service_role_key FROM private.workflow_runtime_settings WHERE setting_name = 'service_role_key';

    IF v_service_role_key IS NOT NULL AND length(trim(v_service_role_key)) > 0 THEN
      v_url := COALESCE(NULLIF(trim(v_functions_url), ''), 'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1') || '/send-due-date-reminder-emails';

      PERFORM net.http_post(
        url := v_url,
        body := '{}'::jsonb,
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || v_service_role_key
        )
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
END;
$$;

COMMIT;

-- ==========================================================================
-- Source: 20260726000003_add_billing_notification_type_and_subscription_trigger.sql
-- ==========================================================================

-- billing-worker's notifyOrgManagers() (subscription past-due / status-changed alerts) has been
-- structurally unreachable since before the subscriptions table existed: trg_subscriptions_webhook
-- was only ever defined in 120_native_workflow_triggers.sql, guarded on
-- `IF EXISTS (... table_name = 'subscriptions')`, but that migration runs (numeric prefix "120_")
-- before 20260622210009_saas_subscriptions.sql creates the table (timestamp-prefixed migrations
-- sort after plain numeric ones), so the guard always skipped it and nothing recreated it since.
-- (The payment-failure trigger into billing-worker is a separate, already-working trigger and is
-- unaffected by any of this.)
--
-- Independently, even if that trigger fires, billing-worker's notifyOrgManagers() inserts
-- type: 'billing', which was never added to notifications_type_check (defined once, in
-- 068_workflow_wiring_hardening.sql) -- so the insert would fail the CHECK constraint. Both need
-- fixing together for subscription alerts to actually work.

BEGIN;

ALTER TABLE public.notifications
  DROP CONSTRAINT IF EXISTS notifications_type_check;

ALTER TABLE public.notifications
  ADD CONSTRAINT notifications_type_check CHECK (
    type IS NULL OR type IN (
      'invoice',
      'approval',
      'invoice_approved',
      'payment',
      'payment_failed',
      'order',
      'inventory',
      'low_inventory',
      'AI_alert',
      'vendor_update',
      'labor_alert',
      'system',
      'alert',
      'warning',
      'error',
      'billing'
    )
  );

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'subscriptions') THEN
    DROP TRIGGER IF EXISTS trg_subscriptions_webhook ON public.subscriptions;
    CREATE TRIGGER trg_subscriptions_webhook
      AFTER INSERT OR UPDATE ON public.subscriptions
      FOR EACH ROW EXECUTE FUNCTION public.invoke_edge_function('billing-worker');
  END IF;
END $$;

COMMIT;

-- ==========================================================================
-- Source: 20260726000004_schedule_missing_notification_cron_jobs.sql
-- ==========================================================================

-- schedule-reports (proxies to dashboard-report-scheduler) and onboarding-expiry-monitor both
-- contain complete, working logic but were never actually scheduled anywhere in this repo: no
-- cron.schedule call, no supabase/config.toml cron entry, no external trigger. Wires both up
-- with the same guarded cron.schedule + private.workflow_runtime_settings pattern already used
-- for send_due_date_reminders (20260717000003_payment_reminders_and_failure_notify.sql).
--
-- schedule-reports runs at 6am daily to match dashboard-report-scheduler's own internal
-- shouldSendCustomReport()/shouldSendPreference() checks, which compare against the cron strings
-- '0 6 * * *' / '0 6 * * 1' / '0 6 1 * *' (daily/weekly-Monday/monthly-1st) -- it only actually
-- sends when today matches, so a single daily invocation at that hour covers all three cadences.
-- onboarding-expiry-monitor runs at 9am daily, offset an hour from the existing 8am
-- send_due_date_reminders job so they don't contend for the same minute.

BEGIN;

DO $$
DECLARE
  v_functions_url text;
  v_service_role_key text;
  v_reports_url text;
  v_expiry_url text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    RETURN;
  END IF;

  SELECT setting_value INTO v_functions_url FROM private.workflow_runtime_settings WHERE setting_name = 'functions_url';
  SELECT setting_value INTO v_service_role_key FROM private.workflow_runtime_settings WHERE setting_name = 'service_role_key';

  IF v_service_role_key IS NULL OR length(trim(v_service_role_key)) = 0 THEN
    RAISE NOTICE 'Skipping schedule-reports/onboarding-expiry-monitor cron schedule: private.workflow_runtime_settings.service_role_key is not configured';
    RETURN;
  END IF;

  v_reports_url := COALESCE(NULLIF(trim(v_functions_url), ''), 'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1') || '/schedule-reports';
  v_expiry_url := COALESCE(NULLIF(trim(v_functions_url), ''), 'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1') || '/onboarding-expiry-monitor';

  BEGIN
    PERFORM cron.unschedule('schedule-reports')
    WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'schedule-reports');

    PERFORM cron.schedule(
      'schedule-reports',
      '0 6 * * *',
      format(
        'SELECT net.http_post(%L, ''{}''::jsonb, jsonb_build_object(%L, %L, %L, %L));',
        v_reports_url,
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_service_role_key
      )
    );
  EXCEPTION WHEN OTHERS THEN
    NULL; -- local/CI without cron privileges: skip, not fatal
  END;

  BEGIN
    PERFORM cron.unschedule('onboarding-expiry-monitor')
    WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'onboarding-expiry-monitor');

    PERFORM cron.schedule(
      'onboarding-expiry-monitor',
      '0 9 * * *',
      format(
        'SELECT net.http_post(%L, ''{}''::jsonb, jsonb_build_object(%L, %L, %L, %L));',
        v_expiry_url,
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_service_role_key
      )
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
END $$;

COMMIT;

